INSERT INTO `lang_definitions` VALUES (16226, 5, 5, 'Eine klinische Entscheidungsregel besteht aus patientenspezifischen Informationen, die gefiltert und zu geeigneten Zeiten angezeigt werden, um die Gesundheit und die Gesundheitsfürsorge zu verbessern');
