INSERT INTO `lang_definitions` VALUES (16230, 9, 5, 'Eine datierte Erinnerungsnachricht kann entweder durch Klicken auf die Schaltfläche Weiterleiten weitergeleitet oder durch Klicken auf die Schaltfläche Als erledigt festlegen aus der Liste der datierten Erinnerungen entfernt werden');
INSERT INTO `lang_definitions` VALUES (16231, 10, 5, 'Es muss ein dedizierter Sicherheitsschlüssel erworben werden');
INSERT INTO `lang_definitions` VALUES (16232, 11, 5, 'Ein Standardcode ist optional, da der erforderliche Code zum Zeitpunkt der Bestellung eingegeben werden kann');
INSERT INTO `lang_definitions` VALUES (16233, 12, 5, 'Eine ausführliche Anleitung zum Aktivieren und Einrichten einer klinischen Entscheidungsregel finden Sie hier');
INSERT INTO `lang_definitions` VALUES (16234, 13, 5, 'Ein Verteiler ist notwendig');
INSERT INTO `lang_definitions` VALUES (16235, 14, 5, 'Es kann ein Fälligkeitsdatum angegeben oder ein bestimmter Zeitraum ausgewählt werden, in dem die datierte Erinnerung angezeigt werden soll');
INSERT INTO `lang_definitions` VALUES (16236, 15, 5, 'Ein paar Worte, um den Grund für den Besuch anzugeben');
INSERT INTO `lang_definitions` VALUES (16237, 16, 5, 'Ein Folgetermin kann auch direkt über das Gebührenblatt vereinbart werden.');
INSERT INTO `lang_definitions` VALUES (16238, 17, 5, 'Ein GCAC Konsultationsformular sollte angefügt werden');
INSERT INTO `lang_definitions` VALUES (16239, 18, 5, 'Eine HL7 v2.x-Nachricht besteht einfach aus mehreren Textzeilen. Jede Zeile wird als Segment bezeichnet und mit dem Pipe-Zeichen (|) in Felder unterteilt');
INSERT INTO `lang_definitions` VALUES (16240, 19, 5, 'Eine grosse Anwendung wie openEMR wird von einer Vielzahl von Benutzern mit unterschiedlichen Rollen und Verantwortungsgraden verwendet. Der Zugriff auf verschiedene Programmteile muss den Benutzern unbedingt auf der Grundlage von Kenntnissen gewährt werden. Zu diesem Zweck werden Zugriffssteuerungslisten (Access Control Lists, ACL) verwendet.');
