INSERT INTO `lang_definitions` VALUES (16745, 623, 5, 'Alternativ kann ein CPT-Code verwendet werden. Es ist 84550 für Serumharnsäure');
INSERT INTO `lang_definitions` VALUES (16746, 624, 5, 'Alternativ können Sie eine Beispieltabelle herunterladen, indem Sie auf die Schaltfläche Herunterladen klicken');
INSERT INTO `lang_definitions` VALUES (16747, 625, 5, 'Alternativ können Sie darauf zugreifen, indem Sie in der oberen Navigationsleiste auf den Menüpunkt Nachrichten klicken');
INSERT INTO `lang_definitions` VALUES (16748, 626, 5, 'Alternativ können Sie alle Auswahlen aufheben und nur die Elemente auswählen, die Teil des Berichts sein sollen');
INSERT INTO `lang_definitions` VALUES (16749, 627, 5, 'Alternativ können Sie auch eine elektronische Überweisungsdatei (X12 835) hochladen, die Sie von Ihrem Zahler oder Ihrer Clearingstelle erhalten haben. Sie können dies tun, indem Sie zuerst die Option \"ERA-Upload\" im ersten Abschnitt \"Methode auswählen\" auswählen. Daraufhin wird der Abschnitt \"ERA-Upload\" angezeigt.');
INSERT INTO `lang_definitions` VALUES (16750, 628, 5, 'Alternativ können Sie auch die Suchseite verwenden um eine elektronische Überweisungsdatei (X12 835), die Sie von ihrem Kostenträger oder ihrer Bank bekommen haben, hochzuladen. Durch klicken von \"Auswählen\" kann eine Datei selektiert werden und durch Drücken von \"Suchen\" hochgeladen und eine Ansicht der entsprechenden Rechnungen erhalten werden. In diesen Fall sind die oben stehenden Parameter nicht von Bedeutung und werden ignoriert. Beim Hochladen wird die Datei gespeichert aber nicht weiter verarbeitet -- dieses wird separat durchgeführt wie weiter unten beschrieben.');
INSERT INTO `lang_definitions` VALUES (16751, 629, 5, 'Obwohl der HCFA-1500 ursprünglich für die Einreichung von Medicare-Anträgen entwickelt wurde, wurde er schließlich von allen gewerblichen / privaten Versicherungsträgern akzeptiert, um die Standardisierung des Antragsprozesses zu erleichtern');
