INSERT INTO `lang_definitions` VALUES (23168, 1782, 6, 'Klik op \"Exporteren\" om uw categorie, subcategorie, punt, Inhoud gegevens naar een tekstbestand te exporteren. Elke gelijkenis van dit bestand naar een XML-bestand is louter toevallig. Het openen en sluiten van tags moeten op dezelfde lijn, zij worden kleine letters zonder spaties. Om te importeren, blader naar een bestand en klik op \'import\' Als de gegevens volledig anders zijn, worden ze samengevoegd met uw bestaande gegevens. Als er soortgelijk artikel namen zijn, worden de oude behouden en de nieuwe opgeslagen met een nummer toegevoegd aan het einde.');
INSERT INTO `lang_definitions` VALUES (23169, 1785, 6, 'Klik op regio van de tekening om pijn aan te geven. Klik op zelfde plek om te verwijderen, of op nieuwe regio om nieuwe plek aan te geven.');
