INSERT INTO `lang_definitions` VALUES (25402, 5180, 6, 'Indien u al de calendar_external tabel heeft ingevuld, klik dan op \"Synchroniseren\" om de vakantiedagen op te nemen in het kalenderoverzicht. Opm. klikken op de knop zal alle bestaande items in het kalenderoverzicht gerelateerd aan vakanties verwijderen');
INSERT INTO `lang_definitions` VALUES (25403, 5182, 6, 'Als u heeft gekozen voor het uploaden van elektronisch afdrachten, dan zal het zoekvenster opnieuw zelf met de bijbehorende facturen van de X12-bestand invullen. U klikt op een van deze factuurnummers (zoals hieronder beschreven), indien u eventuele correcties wil maken voordat de afdracht informatie wordt toegepast Voor de toepassing van de wijzigingen, klikt u op het proces ERA File knop aan de onderkant van de pagina. Dit zal een nieuw venster met een gedetailleerd rapport tonen.');
INSERT INTO `lang_definitions` VALUES (25404, 5185, 6, 'Als u een Pay Datum in de zoekresultaten pagina invoert, zal dit voorrang krijgen op de terbeschikkingstelling datum van de betalingen en de aanpassingen die anders uit de X12-bestand worden opgehaald. Dit kan handig zijn voor rapportage doeleinden, als u wilt dat uw inkomsten rapportage gebruik je je posting datum eerder dan de verzekeringsmaatschappij de verwerking datum. Merk op dat dit ook invloed heeft op de data van voorafgaande betalingen en aanpassingen die in het secundaire claims zijn gedaan.');
INSERT INTO `lang_definitions` VALUES (25405, 5195, 6, 'Indien u wijzigingen heeft aangebracht en opnieuw wilt versturen, verwijder het originele exemplaar (in Communications) en probeer opnieuw.');
