INSERT INTO `lang_definitions` VALUES (33346, 5123, 7, 'במקרה של שימוש ב-SMTP, מספר יציאת TCP של שרת (בדרך כלל 25).');
INSERT INTO `lang_definitions` VALUES (33347, 5150, 7, 'אם לא מועסק, הזן \'סטודנט\'');
INSERT INTO `lang_definitions` VALUES (33348, 5152, 7, 'אם נבחר YMD עבור תצוגת גיל, עבור ל\'שנים\' בלבד כאשר גיל המטופלים עולה על ערך זה בשנים');
INSERT INTO `lang_definitions` VALUES (33349, 5161, 7, 'אם אתה משתמש במספר מעבדות הכנס את הפרטים של כל אחת מהן');
INSERT INTO `lang_definitions` VALUES (33350, 5162, 7, 'אם תשנה תפקיד e-RX עבור ePrescription, הדבר עשוי להשפיע על זרימת העבודה של ה-ePrescription. אם תיתקל בבעיה כלשהי, צור קשר עם ספק ה-ePrescription שלך.');
INSERT INTO `lang_definitions` VALUES (33351, 5172, 7, 'אם לא תבחר התאמה, המטופל ייווצר.');
INSERT INTO `lang_definitions` VALUES (33352, 5182, 7, 'אם בחרת להעלות העברת כספים אלקטרונית, חלון החיפוש יופיע שוב עם החשבוניות התואמות מקובץ ה-X12.  תוכל ללחוץ על מספר כלשהו ממספרי החשבוניות (כמתואר למטה) אם ברצונך לבצע תיקונים כלשהם לפני החלת פרטי העברת הכספים. כדי להחיל את השינויים, לחץ על הלחצן \'עבד קובץ ERA\' בתחתית הדף.  פעולה זו תיצור חלון חדש עם דוח מפורט.');
INSERT INTO `lang_definitions` VALUES (33353, 5185, 7, 'אם הזנת \'תאריך תשלום\' בדף החיפוש, ערך זה יעקוף את תאריך הרישום של התשלומים ואת ההתאמות, אשר אחרת היו מתקבלים מקובץ ה-X12.  אפשרות זו עשויה להועיל לצורכי דיווח, אם אתה מעוניין שדיווח הקבלות ישתמש בתאריך הרישום שלך במקום תאריך העיבוד של חברת הביטוח.  שים לב: הדבר ישפיע גם על תאריכים של התאמות ותשלומים קודמים שנכללו בתביעות משניות.');
INSERT INTO `lang_definitions` VALUES (33354, 5199, 7, 'אם ברצונך לשנות את סוגי הנתונים או להוסיף שורות/עמודות');
INSERT INTO `lang_definitions` VALUES (33355, 5200, 7, 'אם ברצונך לשדרג את מסד הנתונים, הצב את קובץ ה-zip של מסד הנתונים בספרייה הבאה');
