INSERT INTO `lang_definitions` VALUES (37681, 12211, 7, 'לאחר לחיצה על מספר חשבונית, יופיע \"חלון ההצבה הידנית\". כאן תוכל לשנות את תאריך הפירעון והערות עבור החשבונית, לבחור את הצד שעבורו אתה מצב ולבחור את הביטוחים שעבורם התקבלו כל התשלומים הצפויים.  והכי חשוב - לכל קוד חיוב שעבורו היה סכום חיוב, תוכל להזין פרטי תשלום והתאמה.');
INSERT INTO `lang_definitions` VALUES (37682, 12216, 7, 'לאחר החיפוש, תקבל רשימת חשבוניות.  תוכל ללחוץ על אחד ממספרי החשבוניות כי לפתוח חלון שני, שהוא דף הזנת הנתונים להצבה ידנית.  תוכל גם ללחוץ על שם מטופל אם ברצונך להזין הערה אשר צוות המשרד הקדמי יראה בעת צ\'ק אין של המטופל, ותוכל לבחור חשבוניות שיופיעו בדוחות מטופל וכן להדפיס דוחות אלה.');
