INSERT INTO `lang_definitions` VALUES (39304, 1782, 8, 'Cliquez sur «exporter» pour exporter votre Catégorie, Sous-catégorie, objets, et les données de contenu dans un fichier texte. Toute ressemblance de ce fichier à un fichier XML est purement fortuite. Les balises d’ouverture et de fermeture doivent être sur la même ligne, ils doivent être en minuscules et sans espace. Pour importer, rechercher un fichier et cliquez sur «importer». Si les données sont complètement différentes, elles vont être fusionnées avec les données existantes. Si il y’a des noms similaires, l’ancien sera conservé et le nouveau enregistré avec un numéro ajouté à la fin.');
