INSERT INTO `lang_definitions` VALUES (52709, 1782, 11, '點擊“出口”以出口你的分類，子類別，項目，內容數據到一個文本文件。這個文件與XML文件任何的相似之處，純屬巧合。開始和結束標記必須在同一行上，他們必須是不帶空格的小寫。導入，瀏覽一個文件，並單擊“導入”。如果數據是完全不同的，它會與您現有的數據合併。如果有類似的項目名稱，舊的將被保存和新的一個會以一個添加到末尾的數字儲存。');
