INSERT INTO `lang_definitions` VALUES (56879, 12211, 11, '當點擊發票號碼“手冊的發布窗口”出現。在這裡，你可以改變發票的截止日期和票據，選擇你張貼的黨，並選擇保險，所有預期的付款已經收到。最重要的是，收費金額為每個計費代碼，您可以輸入支付和調整資訊。');
INSERT INTO `lang_definitions` VALUES (56880, 12216, 11, '根據搜索，你與發票清單一起出現。你可以點擊一個發票號碼打開第二個窗口，這是手冊發布的數據條目頁面上的發票號碼之一。您也可以點擊上病人的名字，如果你想輸入一個音符，前台人員會看到病人檢查時，您可以選擇的發票出現在病人的報表和打印這些報表。');
