INSERT INTO `lang_definitions` VALUES (57847, 1250, 12, 'Синии строки в этом отчете являются информационными.  Черные строки показывают ранее существовавшую  информацию. Зеленые строки показывают изменения,  которые были успешно применены. Красные строки  обозначают ошибки или изменения, которые не были  применены; они должны быть обработаны вручную.  В настоящее время отклоненные требования и откат  оплаты автоматически не обрабатываются, и поэтому  будут отображаться красным.');
