INSERT INTO `lang_definitions` VALUES (58088, 1782, 12, 'Нажмите \"Экспорт\", чтобы экспортировать категорию, подкатегорию, пункт, данные содержания в текстовый файл. Любое сходство этого файла с файлом XML является чисто случайным. Открывающий и закрывающий теги должны быть в одной строке, в нижнем регистре без пробелов. Для импорта найдите файл и нажмите \"Импорт\". Если данные совершенно другие, он объединится с существующими данными. Если есть похожие наименования пунктов, старый будет оставлен, а новый сохранен с добавлением в конце номера.');
