INSERT INTO `lang_definitions` VALUES (63005, 4, 13, 'Որպես ԱԴՄԻՆ օգտվող  հաճախորդի հավաստագիր');
INSERT INTO `lang_definitions` VALUES (63006, 5, 13, 'Կլինիկական որոշման կանոնը պացիենտի համար հատուկ տեղեկատվություն է, որը զտվում և ներկայացվում է համապատասխան ժամանակներում՝ առողջությունն ու խնամքը բարելավելու համար');
INSERT INTO `lang_definitions` VALUES (63007, 6, 13, 'Կցված է բժշկական/կլինիկական փաստաթուղթ');
