INSERT INTO `lang_definitions` VALUES (63009, 8, 13, 'Նմանատիպ կոդ արդեն ընտրված է․ նախ մաքրեք դաշտը, եթե ցանկանում եք տեղափոխել այն');
INSERT INTO `lang_definitions` VALUES (63010, 9, 13, 'Հիշեցման հաղորդագրությունը կարող է փոխանցվել` սեղմելով Փոխանցել կոճակը կամ հանվել թվագրված հիշեցումների ցուցակից` սեղմելով Սահմանել որպես ավարտված կոճակին:');
INSERT INTO `lang_definitions` VALUES (63011, 10, 13, 'Անհրաժեշտ է գնել անվտանգության հատուկ բանալի');
INSERT INTO `lang_definitions` VALUES (63012, 11, 13, 'Լռելյայն ծածկագիրը պարտադիր չէ, քանի որ անհրաժեշտ կոդը կարող է մուտքագրվել իրական պատվերը դնելու պահին');
