INSERT INTO `lang_definitions` VALUES (63650, 1250, 13, 'Այս հաշվետվության մեջ կապույտով նշված են  տեղեկատվական տողերը, սև տողերը ցույց են տալիս  նախկինում եղած ինֆորմցիան։ Կանաչով երևում են  հաջողությամբ ավելացված փոփոխությունները։ Կարմիրով  ցուցադրված են սխալները կամ չընդունված  փոփոխությունները․ դրանք պետք է գործարկել ձեռքով։  Ընթացիք մերժված պահանջներն ու վճարման հետկանչը  ավտոմատ չեն գործարկվում, ուստի կցուցադրվեն կարմիրով։');
