INSERT INTO `lang_definitions` VALUES (66838, 7256, 13, 'Ուշադրություն։ Այս կոդը մուտքագրվել է ոչ լիազորված օգտվողի կողմից։ Բաց Բժշկական Հաշվեգրման Ցանցի գործարկման համար անհրաժեշտ է բեռնել լիազորված/վավեր կոդեր։ Եթե ցանկանում եք բեռնել/մուտքագրել այս կոդերը, ապա այստեղից  ընտրեք լիազորված օգտվողի։');
INSERT INTO `lang_definitions` VALUES (66839, 7257, 13, 'Ուշադրություն։ Այս հավելավչարը մուտքագրվել է չհաստատված/անվավեր հաշվի վրա։ Վերստուգեք վերջինիս կարգավիճակը։');
INSERT INTO `lang_definitions` VALUES (66840, 7259, 13, 'ՈՒՇԱԴՐՈՒԹՅՈՒՆ։ Կրկնվող անուններով ֆայլերի բեռնման ժամանակ անունները ավտոմատ կվերանվանվեն (օր․՝ file.jpg կդառնա file.1.jpg) Ֆայլերի անունները պետք է լինեն չկրկնվող ոչ թե յուրաքանչյուր կատեգորիայի, այլ յուրաքանչյուր պացիենտի համար։');
