INSERT INTO `lang_definitions` VALUES (68958, 11248, 13, 'Աղբյուրի և ամսաթվի սյուները կրկնօրինակվում են առաջին էջից, ուստի կարիք չկա դրանց ձեռք տալ։ Վճարման գումարը տեղադրում եք վճարում սյան մեջ, ճշգրտման ենթական ումարը՝ Ճշգրտում սյան մեջ, կամ երկուսում էլ։ Կարող եք աջ կողմում սեղմել  \"W\" to automatically compute an adjustment value that writes off the remainder of the charge for that line item.');
