INSERT INTO `lang_definitions` VALUES (69042, 11525, 13, 'Այս էջը հնարավորություն է ընձեռում վերանայել աջակցվող   յուրաքանչյուր արտաքին տվյալի բեռնումը, որը հնարավոր է տեղադրել կամ թարմացնել։ Each section below can be expanded by clicking on the section header to review the status of the particular database of interest.');
INSERT INTO `lang_definitions` VALUES (69043, 11526, 13, 'Անվտանգության նկատառումներից ելնելով էջն ապաակտիվացվել է');
INSERT INTO `lang_definitions` VALUES (69044, 11528, 13, 'Այս էջը կներառի նաև մինջակյալ մուտքի էջ, որպեսզի ամեն անգամ չսեղմեք \"կրկին մուտք գործել\"');
INSERT INTO `lang_definitions` VALUES (69045, 11532, 13, 'Այս պացիենտի էջում գործողություններ չկան');
INSERT INTO `lang_definitions` VALUES (69046, 11533, 13, 'Պացիենտի ID-ն արդեն գործածվում է/գործածության մեջ է');
INSERT INTO `lang_definitions` VALUES (69047, 11535, 13, 'Այս ապրանքը յուրաքանչյուր պահեստում թույլատրում է միայն մեկ խմբաքանակ');
INSERT INTO `lang_definitions` VALUES (69048, 11536, 13, 'Այս արձանագրությունը չի իրականացվել/կյանքի չի կոչվել');
INSERT INTO `lang_definitions` VALUES (69049, 11539, 13, 'Այս զեկույցը/հաշվետվությունն աշխատում է միայն ICD9  կոդերի համար');
INSERT INTO `lang_definitions` VALUES (69050, 11550, 13, 'Սրանով սահմանվում/ճշտում է, թե արդյոք պետք է ամսաթիվ ներառվի 31 վանդակում');
INSERT INTO `lang_definitions` VALUES (69051, 11553, 13, 'Այս քայլով կստեղծվի նոր ֆայլ, որն անհրաժեշտ է պահպանել հետագա կիրառման համար։ Այն հետագայում չի վերստեղծվելու։ Գործարկե՞լ այն։');
INSERT INTO `lang_definitions` VALUES (69052, 11556, 13, 'Այս օգտատերը չի հանդիսանում ոչ մի խմբի անդամ');
INSERT INTO `lang_definitions` VALUES (69053, 11557, 13, 'Այս օգտատերը անձնական նամակների վերաբերյալ ծանուցումներ կստանա');
INSERT INTO `lang_definitions` VALUES (69054, 11558, 13, 'Սա փորձնական սպասարկող ծրագիր է․ Կրկնօրինակեք ձեր տվյալներն ու փաստաթղթերը նախքան վերջինիս կիրառումը։');
INSERT INTO `lang_definitions` VALUES (69055, 11560, 13, 'Այս այցով սկսվում է նոր հակաբեղմնավորիչների կիրառմամբ');
INSERT INTO `lang_definitions` VALUES (69056, 11561, 13, 'Այս այցի համար անհրաժեշտ է GCAC ձև, ուղեգիր կամ միջամտություն');
INSERT INTO `lang_definitions` VALUES (69057, 11562, 13, 'Դա ընդամենը հին մետրիկ կենսաչափական որոշիչների ձև էր, որն այժմ համարվում է անընդունելի');
INSERT INTO `lang_definitions` VALUES (69058, 11563, 13, 'Այս շաբաթ մինչ օրս');
INSERT INTO `lang_definitions` VALUES (69059, 11566, 13, 'Այն կակտիվացնի ԽՇԳ (Խնամքի Շարունակական Գրառման) և ՇԽՓ (Շարունակական  Խնամքի Փաստաթղթերի) զեկուցումը');
INSERT INTO `lang_definitions` VALUES (69060, 11570, 13, 'Թույլ կտա կատարել կարգաբերող ( \'կեղծ \') լեզվի  ընտրություն');
INSERT INTO `lang_definitions` VALUES (69061, 11579, 13, 'Սա կստեղծի tar ֆորմատի կրկնօրինակ և կուղարկի ձեր բրոուզեր, որպեսզի կարողանա պահպանել այն։');
INSERT INTO `lang_definitions` VALUES (69062, 11580, 13, 'Փաստաթղթի կոդավորման և ապակոդավորման հնարավորությունները կարգելափակվեն և կթաքցվեն օգտվողի ինտերֆեյսում');
INSERT INTO `lang_definitions` VALUES (69063, 11581, 13, 'Սա կանջատի բոլոր այն ձևերի \"Խմբագրել\" կոճակը, որոնցում առաջին/գլխավոր այցելության վրա առկա է էլ․ ստորագրություն');
INSERT INTO `lang_definitions` VALUES (69064, 11582, 13, 'Սա կանջատի  էլ․ ստորագրությամբ ստորագրված ցանկացած  ձևի \"Խմբագրել\" կոճակը');
INSERT INTO `lang_definitions` VALUES (69065, 11586, 13, 'Ի տարբերություն անհատական/առանձին ձևերի՝ սա թույլ կտա ստորագրել ողջ այցելությունը');
