INSERT INTO `lang_definitions` VALUES (72265, 5162, 14, 'Jika anda mengubah tugas e-RX untuk ePrescription(Resep Elektronik), mungkin akan mempengaruhi alur kerja ePrescription. Jika anda menghadapi kesulitan, hubungi vendor ePrescription anda.');
INSERT INTO `lang_definitions` VALUES (72266, 5182, 14, 'Jika Anda telah memilih untuk mengupload pengiriman uang elektronik, maka jendela pencarian menampilkan kembali dengan sendirinya dengan faktu/tagihan yang sesuai dari X12 file. Anda bisa mengklik pada salah satu nomor faktur (seperti yang dijelaskan di bawah) jika anda ingin melakukan koreksi sebelum informasi pengiriman uang diterapkan. Untuk menerapkan perubahan, klik tombol Proses ERA File di bagian bawah halaman. Ini akan menghasilkan sebuah jendela baru dengan laporan rinci.');
INSERT INTO `lang_definitions` VALUES (72267, 5185, 14, 'Jika Anda telah memasuki Tanggal Bayar di halaman pencarian, ini akan menimpa postingan tanggal pembayaran dan penyesuaian yang sebaliknya diambil dari file X12. Ini mungkin berguna untuk keperluan laporan, jika Anda ingin laporan penerimaan anda menggunakan tanggal posting Anda daripada tanggal pengolahan asuransi perusahaan. Catatan bahwa ini juga akan mempengaruhi tanggal pembayaran sebelumnya dan penyesuaian yang dimasukkan ke dalam klaim sekunder.');
