INSERT INTO `lang_definitions` VALUES (75323, 12211, 14, 'Setelah mengklik nomor faktur \"jendela postingan manual\" muncul. Di sini Anda dapat mengubah tanggal jatuh tempo dan catatan untuk faktur, pilih pihak untuk siapa yang Anda posting, dan pilih asuransi yang semua pembayaran yang diharapkan telah diterima. Yang paling penting, untuk setiap kode tagihan yang besarnya telah dibebankan, Anda dapat memasukkan informasi pembayaran dan penyesuaian.');
INSERT INTO `lang_definitions` VALUES (75324, 12216, 14, 'Setelah pencarian Anda disajikan dengan daftar faktur/tagihan. Anda bisa mengklik pada salah satu nomor faktur untuk membuka jendela kedua, yang merupakan halaman entri data untuk posting manual. Anda juga dapat mengklik nama pasien jika ingin memasukkan catatan bahwa staf front office akan melihat ketika pasien melakukan check in, dan Anda dapat memilih faktur untuk tampil di laporan pasien dan mencetak laporan itu.');
