INSERT INTO `lang_definitions` VALUES (76958, 1782, 15, 'Πατήστε “Εξαγωγή” για να εξάγετε τα δεδομένα Κατηγορίας, Υποκατηγορίας και Αντικειμένου, σε ένα αρχείο. Οποιαδήποτε ομοιότητα αυτού του αρχείου με αρχείο XML είναι καθαρά συμπτωματική. Το άνοιγμα και το κλείσιμο ετικετών πρέπει να είναι στην ίδια γραμμή με πεζά γράμματα, χωρίς κενά. Για εισαγωγή, αναζητήστε ένα αρχείο και κάντε κλικ στο κουμπί “Εισαγωγή”. Εάν τα δεδομένα είναι εντελώς διαφορετικά, θα συγχωνευτούν με τα υπάρχοντα. Αν υπάρχουν ίδια ονόματα αντικειμένων, το παλιό όνομα θα διατηρηθεί και το νέο θα αποθηκευθεί με την προσθήκη ενός αριθμού στο τέλος του.');
INSERT INTO `lang_definitions` VALUES (76959, 1783, 15, 'Κάντε κλικ στην «Αποθήκευση»');
INSERT INTO `lang_definitions` VALUES (76960, 1785, 15, 'Κάντε κλικ σε ένα σημείο στην εικόνα για να προσθέσετε νέα επισήμανση. Κάντε κλικ ξανά στο ίδιο σημείο για να την αφαιρέσετε.');
