INSERT INTO `lang_definitions` VALUES (79071, 5101, 15, 'Αν όλα τα δεδομένα για όλες τις στήλες είναι πλήρη για αυτό το έντυπο');
INSERT INTO `lang_definitions` VALUES (79072, 5103, 15, 'Αν χρησιμοποιήσετε αιτιολόγηση χρέωσης, βάλτε το όνομα του κωδικού διάγνωσης');
INSERT INTO `lang_definitions` VALUES (79073, 5109, 15, 'αν εισάγετε, επιλέξτε μόνο αυτούς που είχαν αυτήν την υπηρεσία');
