INSERT INTO `lang_definitions` VALUES (79076, 5118, 15, 'Εάν ο ασθενής έχει πεθάνει, τότε εισάγετε την ημερ. θανάτου.');
INSERT INTO `lang_definitions` VALUES (79077, 5122, 15, 'Εάν χρησιμοποιείται SMTP, εισάγετε το όνομα του host ή τη διεύθυνση IP.');
INSERT INTO `lang_definitions` VALUES (79078, 5123, 15, 'Εάν χρησιμοποιείται SMTP, ο αριθμός θύρας TCP του server (συνήθως 25).');
INSERT INTO `lang_definitions` VALUES (79079, 5150, 15, 'αν άνεργος εισάγετε Φοιτητής');
INSERT INTO `lang_definitions` VALUES (79080, 5152, 15, 'Αν έχει επιλεγεί η μορφή Έτη-Μήνες-Ημέρες για την εμφάνιση ηλικίας, αλλαγή σε -Έτη- όταν η ηλικία των ασθενών (σε έτη) είναι μεγαλύτερη από την τιμή αυτή');
INSERT INTO `lang_definitions` VALUES (79081, 5162, 15, 'Εάν αλλάξετε τον ρόλο του e-RX για την ηλεκτρονική συνταγογράφηση, μπορεί να επηρεάσει τη ροή εργασίας της ηλεκτρονικής συνταγογράφησης. Αν αντιμετωπίζετε οποιαδήποτε δυσκολία, επικοινωνήστε με τον προμηθευτή της ηλεκτρονικής συνταγογράφησης.');
INSERT INTO `lang_definitions` VALUES (79082, 5172, 15, 'Αν δεν επιλέξετε μία εγγραφή που να ταιριάζει, ο ασθενής θα δημιουργηθεί.');
INSERT INTO `lang_definitions` VALUES (79083, 5182, 15, 'Εάν επιλέξατε να ανεβάσετε ηλεκτρον. εμβάσματα, τότε το παράθυρο αναζήτησης θα επανεμφανισθεί, με τα τιμολόγια που ταιριάζουν από το αρχείο X12. Μπορείτε να κάνετε κλικ σε οποιονδήποτε αριθμό παραστατικού (όπως περιγράφεται παρακάτω), εάν θέλετε να κάνετε διορθώσεις πριν να οριστικοποιηθούν οι πληροφορίες εμβάσματος. Για να εφαρμόσετε τις αλλαγές, κάντε κλικ στο κουμπί \"Επεξεργασία ERA\" στο κάτω μέρος της σελίδας. Θα εμφανισθεί ένα νέο παράθυρο με μια λεπτομερή αναφορά.');
INSERT INTO `lang_definitions` VALUES (79084, 5185, 15, 'Εάν έχετε εισάγει μια Ημ/νία Πληρωμής στη σελίδα αναζήτησης, αυτή θα υπερισχύσει της ημ/νίας αποστολής των πληρωμών και των προσαρμογών, που λαμβάνονται ούτως ή άλλως από το αρχείο X12. Αυτό μπορεί να είναι χρήσιμο για λόγους αναφοράς, αν θέλετε οι αναφορές των αποδείξεών σας να κάνουν χρήση της ημ/νίας αποστολής σας αντί της ημ/νίας επεξεργασίας από την ασφαλιστική εταιρείας. Σημειώστε ότι αυτό θα επηρεάσει επίσης τις ημερομηνίες των προηγούμενων πληρωμών και τις προσαρμογές που έχουν τεθεί σε δευτερεύουσες απαιτήσεις.');
INSERT INTO `lang_definitions` VALUES (79085, 5195, 15, 'Αν πραγματοποιήσατε αλλαγές και επιθυμείτε να το ξαναστείλετε, διαγράψτε το αρχικό (στις Επικοινωνίες) και προσπαθήστε ξανά.');
INSERT INTO `lang_definitions` VALUES (79086, 5199, 15, 'Αν θέλετε να αλλάξετε τους τύπους δεδομένων, ή να προσθέσετε γραμμές ή στήλες');
INSERT INTO `lang_definitions` VALUES (79087, 5200, 15, 'Αν θέλετε να αναβαθμίσετε τη βάση δεδομένων, τοποθετήστε το αρχείο zip της βάσης δεδομένων στον ακόλουθο κατάλογο.');
