INSERT INTO `lang_definitions` VALUES (80409, 7256, 15, 'Προσοχή: Αυτές οι γραμμές κώδικα δεν έχουν γραφεί από έναν εξουσιοδοτημένο χρήστη. Μόνο εξουσιοδοτημένοι κώδικες μπορούν να φορτωθούν στο Open Medical Billing Network. Αν θέλετε να ανεβάσετε αυτές τις αλλαγές, παρακαλώ επιλέξτε έναν εξουσιοδοτημένο χρήστη εδώ.');
