INSERT INTO `lang_definitions` VALUES (80412, 7260, 15, 'Προσοχή: Όταν γίνεται προσθήκη αρχείων με όνομα που ήδη υπάρχει, το πρόγραμμα θα μετονομάζει αυτόματα το αρχείο. Π.χ. το αρχείο file.jpg θα μετονομαστεί σε file.jpg.1. Μοναδικά θεωρούνται τα αρχεία για κάθε ασθενή, όχι για κάθε κατηγορία.');
