INSERT INTO `lang_definitions` VALUES (82936, 11053, 15, 'Ο επιλέξιμος Πάροχος, το επιλέξιμο νοσοκομείο ή το νοσοκομείο επείγουσας πρόσβασης που λαμβάνει έναν ασθενή από κάποια άλλη μονάδα περίθαλψης ή πάροχο περίθαλψης ή πιστεύει ότι μια επίσκεψη είναι σχετική θα πρέπει να συμβιβαστεί με τη φαρμακευτική αγωγή.');
INSERT INTO `lang_definitions` VALUES (82937, 11056, 15, 'Ο επιλέξιμος Πάροχος, το επιλέξιμο νοσοκομείο ή το νοσοκομείο επείγουσας πρόσβασης που μεταβιβάζει έναν ασθενή του σε κάποια άλλη μονάδα περίθαλψης ή πάροχο περίθαλψης ή παραπέμπει έναν ασθενή του σε άλλο πάροχο περίθαλψης θα πρέπει να παρέχει περίληψη των αναφορών περίθαλψης για κάθε μετάβαση ή παραπομπή.');
INSERT INTO `lang_definitions` VALUES (82938, 11057, 15, 'Τα συμβάντα έχουν εγκριθεί.');
INSERT INTO `lang_definitions` VALUES (82939, 11058, 15, 'Τα συμβάντα έχουν κρυφτεί.');
INSERT INTO `lang_definitions` VALUES (82940, 11059, 15, 'Τα δεδομένα που εξάγονται εμφανίζονται στην περιοχή κείμενου που ακολουθεί. Μπορείτε να αντιγράψετε και να επικολλήσετε αυτά σε ένα email ή σε οποιοδήποτε άλλο επιθυμητό προορισμό.');
INSERT INTO `lang_definitions` VALUES (82941, 11060, 15, 'Τα δεδομένα που εξάγονται εμφανίζονται στην περιοχή κείμενου που ακολουθεί. Μπορείτε να αντιγράψετε και να επικολλήσετε αυτά σε ένα email ή σε οποιονδήποτε άλλο επιθυμητό προορισμό (ή) να τα κατεβάσετε από τον παρακάτω σύνδεσμο.');
INSERT INTO `lang_definitions` VALUES (82942, 11061, 15, 'Τα δεδομένα που εξάγονται εμφανίζονται στην περιοχή κείμενου που ακολουθεί. Μπορείτε να αντιγράψετε και να επικολλήσετε αυτά σε ένα email ή σε οποιονδήποτε άλλο επιθυμητό προορισμό.');
INSERT INTO `lang_definitions` VALUES (82943, 11062, 15, 'Τα εξαγόμενα δεδομένα εμφανίζονται στην περιοχή του κειμένου που ακολουθεί. Μπορείτε να αντιγράψετε και να επικολλήσετε αυτά σε ένα μήνυμα ηλεκτρονικού ταχυδρομείου ή σε οποιαδήποτε άλλο επιθυμητό προορισμό.');
INSERT INTO `lang_definitions` VALUES (82944, 11065, 15, 'Το αρχείο δεν μπορούσε να αποθηκευθεί στο CouchDB.');
INSERT INTO `lang_definitions` VALUES (82945, 11066, 15, 'Το αρχείο δεν μπόρεσε να μετονομαστεί με επιτυχία, αυτό το σφάλμα σχετίζεται συνήθως προβλήματα δικαιωμάτων στο σύστημα αποθήκευσης.');
INSERT INTO `lang_definitions` VALUES (82946, 11067, 15, 'Το αρχείο δεν αποθηκεύθηκε επιτυχώς. Αυτό το σφάλμα σχετίζεται συνήθως με προβλήματα δικαιωμάτων στο σύστημα αποθήκευσης.');
INSERT INTO `lang_definitions` VALUES (82947, 11071, 15, 'Ο πρώτος (\"στόχος\") φάκελος είναι αυτός που θεωρείται πιο ολοκληρωμένος και ακριβής. Τα Δημογραφικά, το Ιστορικό και η Ασφάλιση που περιέχει θα διατηρηθούν.');
