INSERT INTO `lang_definitions` VALUES (82961, 11101, 15, 'Τα ακόλουθα πεδία πρέπει να συμπληρωθούν για να αποσταλεί το αίτημα.');
INSERT INTO `lang_definitions` VALUES (82962, 11104, 15, 'Συνέβη το ακόλουθο');
INSERT INTO `lang_definitions` VALUES (82963, 11105, 15, 'Τα ακόλουθα προβλήματα έχουν τον ίδιο κωδικό διάγνωσης. Δεν θα πραγματοποιηθεί ενημέρωση των Θεμάτων στην Επίσκεψη. Παρακαλώ χρησιμοποιήστε το περιβάλλον της Επίσκεψης αντί αυτού.');
INSERT INTO `lang_definitions` VALUES (82964, 11126, 15, 'Το αρχικό παράθυρο είναι η σελίδα αναζήτησης του παραστατικού. Στην κορυφή μπορείτε να δώσετε μια πηγή (π.χ. αριθμός ελέγχου), ημ/νία πληρωμής και ποσό ελέγχου. Ο λόγος για την ημ/νία πηγής και πληρωμής είναι αυτός, ώστε δεν χρειάζεται να τα εισάγετε ξανά και ξανά για κάθε αξίωση. Το ποσό που εισάγετε θα μειωθεί για κάθε τιμολόγιο που δίνεται μέρος της πληρωμής και ελπίζουμε ότι θα τελειώσει στο μηδέν όταν τελειώσετε.');
INSERT INTO `lang_definitions` VALUES (82965, 11128, 15, 'Πρέπει να δημιουργηθεί ο κατάλογος εγκατάστασης.');
INSERT INTO `lang_definitions` VALUES (82966, 11135, 15, 'Τα Θέματα μπορούν να εισαχθούν με έναν από τους δύο τρόπους');
INSERT INTO `lang_definitions` VALUES (82967, 11140, 15, 'Η ετικέτα που φαίνεται στο χρήστη πάνω στο έντυπο');
INSERT INTO `lang_definitions` VALUES (82968, 11147, 15, 'Το μήκος δεν θα πρέπει να υπερβαίνει τον ακόλουθο αριθμό χαρακτήρων');
INSERT INTO `lang_definitions` VALUES (82969, 11152, 15, 'Η συγχώνευση δεν θα εκτελεστεί αν το ΑΜΚΑ και η Ημ/νία Γέν. των δύο φακέλων δεν συμφωνούν. Οι Ημ/νία Γέν. δεν μπορούν να είναι κενές.');
INSERT INTO `lang_definitions` VALUES (82970, 11153, 15, 'Αδύνατη η αποστολή του μηνύματος.');
INSERT INTO `lang_definitions` VALUES (82971, 11168, 15, 'Ο νέος κατάλογος θα είναι μια υπο-κατηγορία του/της');
INSERT INTO `lang_definitions` VALUES (82972, 11170, 15, 'Ο νέος κωδικός πρόσβασης δεν μπορεί να είναι ο ίδιος με τον τρέχοντα κωδικό πρόσβασης.');
INSERT INTO `lang_definitions` VALUES (82973, 11171, 15, 'Τα πεδία του νέου κωδικού πρόσβασης δεν είναι ίδια.');
INSERT INTO `lang_definitions` VALUES (82974, 11189, 15, 'Η σελίδα θα ανακατευθυνθεί στα Δημογραφικά. Μπορείτε να επεξεργαστείτε το πεδίο \"Χώρα\" και να προχωρήσετε στο NewCrop ξανά.');
