INSERT INTO `lang_definitions` VALUES (82977, 11194, 15, 'Το παρελθόν Οφθαλμικό Ιστορικό (POH) και το παρελθόν Ιατρικό Ιστορικό (PMH) είναι αρνητικά');
INSERT INTO `lang_definitions` VALUES (82978, 11195, 15, 'Ο ασθενής είναι ήδη εγγεγραμμένος στην ομάδα');
INSERT INTO `lang_definitions` VALUES (82979, 11196, 15, 'Το αίτημα φακέλου ασθενούς έχει καταγραφεί.');
INSERT INTO `lang_definitions` VALUES (82980, 11197, 15, 'Οι υπενθυμίσεις προς ασθενή(-είς) έχουν σταλεί');
INSERT INTO `lang_definitions` VALUES (82981, 11198, 15, 'Οι υπενθυμίσεις προς ασθενή(-είς) έχουν ενημερωθεί');
