INSERT INTO `lang_definitions` VALUES (82985, 11203, 15, 'Οι πληρωμές που απεστάλησαν δεν μπορούν να είναι κάτω από αυτήν την ημ/νία. Αυτό εξασφαλίζει ότι μετά τη λήψη της τελικής αναφοράς, κανείς δεν αποστέλει για προηγούμενες ημερομηνίες.');
INSERT INTO `lang_definitions` VALUES (82986, 11205, 15, 'Το Portal έχει δεδομένα για αυτόν τον ασθενή και το έντυπο. Να φορτωθούν τώρα;');
INSERT INTO `lang_definitions` VALUES (82987, 11219, 15, 'Οι υπόλοιπες πληροφορίες παρακάτω ισχύουν μόνο αν αποστέλλετε χειρωνακτικά, ή αν κάνετε διορθώσεις με το χέρι.');
INSERT INTO `lang_definitions` VALUES (82988, 11222, 15, 'Το ζητούμενο έγγραφο δεν είναι παρόν στην αναμενόμενη θέση στο σύστημα αρχείων ή δεν υπάρχουν επαρκή δικαιώματα για πρόσβαση σε αυτό.');
INSERT INTO `lang_definitions` VALUES (82989, 11223, 15, 'Το ζητούμενο έγγραφο δεν είναι παρόν στην αναμενόμενη θέση στο σύστημα αρχείων ή δεν υπάρχουν επαρκή δικαιώματα για πρόσβαση σε αυτό.');
INSERT INTO `lang_definitions` VALUES (82990, 11232, 15, 'Ο χρόνος ανανέωσης οθόνης σε Δευτερόλεπτα για την Οθόνη Πίνακα Ροής Ασθενών.');
INSERT INTO `lang_definitions` VALUES (82991, 11235, 15, 'Τα Δημογραφικά, το Ιστορικό και η Ασφάλιση του δεύτερου φακέλου (\"προέλευση\") θα απορριφθούν. Τα υπόλοιπα δεδομένα του θα συγχωνευθούν κανονικά στον φάκελο προορισμού.');
INSERT INTO `lang_definitions` VALUES (82992, 11248, 15, 'Οι στήλες Πηγής και Ημ/νίας αντιγράφονται από την πρώτη σελίδα, έτσι κανονικά δεν θα χρειαστεί να τις αγγίξετε. Μπορείτε να τοποθετήσετε ένα ποσό πληρωμής στη στήλη Πληρωμή, ένα ποσό προσαρμογής στην στήλη Ρύθμιση, ή και τα δύο. Μπορείτε επίσης να κάνετε κλικ στο \"W\" στα δεξιά για να υπολογιστεί αυτόματα μια τιμή προσαρμογής που γράφει το υπόλοιπο του τέλους για το στοιχείο γραμμής.');
INSERT INTO `lang_definitions` VALUES (82993, 11256, 15, 'η κατάσταση τριών χρόνιων/ανενεργών νοσημάτων');
