INSERT INTO `lang_definitions` VALUES (83107, 11557, 15, 'Αυτός ο χρήστης θα λάβει ειδοποίηση νέων εισερχόμενων Άμεσων μηνυμάτων.');
INSERT INTO `lang_definitions` VALUES (83108, 11558, 15, 'Αυτή η λειτουργία είναι πειραματική. Κάντε backup της βάσης δεδομένων και των εγγράφων πριν την χρησιμοποιήσετε!');
