INSERT INTO `lang_definitions` VALUES (83110, 11561, 15, 'Αυτή η επίσκεψη θα χρειαστεί ένα έντυπο GCAC, μια παραπομπή ή μια υπηρεσιακή διαδικασία.');
INSERT INTO `lang_definitions` VALUES (83111, 11562, 15, 'Αυτό ήταν το παλαιό μονάχα μετρικό έντυπο Ζωτικών, που έχει τώρα αποσυρθεί.');
