INSERT INTO `lang_definitions` VALUES (83113, 11565, 15, 'Με αυτήν την ενέργεια θα χαθούν οι μη αποθηκευμένες αλλαγές. Είστε σίγουρος/η;');
INSERT INTO `lang_definitions` VALUES (83114, 11566, 15, 'Αυτή η ενέργεια θα ενεργοποιήσει την εγγραφή του CCR (Αναφορά Συνέχισης της Φροντίδας) και του CCD (Εγγραφο Συνέχισης της Φροντίδας).');
INSERT INTO `lang_definitions` VALUES (83115, 11570, 15, 'Αυτή η ενέργεια θα επιτρέψει την επιλογή της αποσφαλμάτωσης ( \'εικονική \') γλώσσα.');
INSERT INTO `lang_definitions` VALUES (83116, 11572, 15, 'Αυτή η ενέργεια θα επιτρέψει την χρήση τροποποιημένης αναφοράς Τέλους Ημέρας και την υπόδειξη σχετικά με το ποια αναφορά θα χρησιμοποιηθεί.');
