INSERT INTO `lang_definitions` VALUES (83120, 11580, 15, 'Αυτή η ενέργεια θα απενεργοποιήσει την κρυπτογράφηση του εγγράφου και τις δυνατότητες αποκρυπτογράφησης και θα τις κρύψει στο UI.');
