INSERT INTO `lang_definitions` VALUES (84819, 674, 17, 'Um e-mail com as suas novas credenciais de conta será enviado para o endereço de e-mail fornecido anteriormente. Você ainda pode rever ou editar qualquer parte de suas informações usando os botões de passo superior para ir aos painéis apropriados. Note estar seguro que você deu o seu endereço de e-mail correto. Se após receber as credenciais tiver problemas com o acesso ao portal, entre em contato com a administração');
INSERT INTO `lang_definitions` VALUES (84820, 675, 17, 'Uma ordem eletrônica e o resultado retornado estão na forma de uma mensagem chamada a mensagem HL7. HL7 significa Nível de Saúde (Application Layer) 7. O principal objetivo da HL7 é simplificar a implementação de interfaces entre aplicativos de software de saúde e vários fornecedores, de modo a reduzir a dor e o custo envolvido na programação de interface personalizada');
