INSERT INTO `lang_definitions` VALUES (88722, 5096, 17, 'Se um campo de dados Col = 0, o campo de dados seguirá imediatamente seu campo de rótulo na mesma linha');
INSERT INTO `lang_definitions` VALUES (88723, 5097, 17, 'Se o Label Col de um campo = 0, o rótulo seguirá imediatamente o campo de dados anterior na sequência do pedido, na mesma linha do campo de dados');
INSERT INTO `lang_definitions` VALUES (88724, 5098, 17, 'Se Label Col de um campo = 1, o campo de rótulo irá para uma nova linha, a menos que os valores totais da coluna do campo anterior (Label + Dados) sejam menores que o número de colunas de Layout de Propriedades de Grupo ou Propriedades de Layout.');
INSERT INTO `lang_definitions` VALUES (88725, 5099, 17, 'Se um produto for vendido, então altere o padrão para refletir o número necessário. Deixe em um para procedimentos');
INSERT INTO `lang_definitions` VALUES (88726, 5100, 17, 'Se um código errado foi selecionado, clique na caixa de texto Codificação para abrir a página pop-up Selecionar códigos');
INSERT INTO `lang_definitions` VALUES (88727, 5101, 17, 'Se todos os dados para todas as colunas estão completas para esta forma');
INSERT INTO `lang_definitions` VALUES (88728, 5102, 17, 'Se todos os detalhes foram inseridos corretamente, você verá a glicose no sangue na coluna Nome com uma barra vertical antes dela indicando que ela não tem descendentes ou filhos, Resultado na coluna Categoria, WWT01R na coluna Código, o valor da coluna Tier deve ser 3 e a coluna Descrição deve dizer Resultado de glicose em jejum');
INSERT INTO `lang_definitions` VALUES (88729, 5103, 17, 'Se a justificativa de faturamento for usada, insira o nome do tipo de código de diagnóstico');
INSERT INTO `lang_definitions` VALUES (88730, 5104, 17, 'Se configurado corretamente, a coluna Nome deve dizer Glicose no sangue com uma barra vertical antes de indicar nenhum descendente ou filho, a coluna Categoria deve dizer Ordem personalizada e ambas as colunas Nome e Categoria serão destacadas em rosa indicando uma ordem agrupada personalizada');
INSERT INTO `lang_definitions` VALUES (88731, 5105, 17, 'Se desejar, a mensagem atual pode ser impressa');
INSERT INTO `lang_definitions` VALUES (88732, 5108, 17, 'Se habilitado, usa o diretório ativo especificado para login e autenticação');
INSERT INTO `lang_definitions` VALUES (88733, 5109, 17, 'se inserido, selecione apenas aqueles que tiveram este serviço');
INSERT INTO `lang_definitions` VALUES (88734, 5110, 17, 'Se ainda estiver ativo, ou seja, a data de término não foi inserida, ele será exibido em vermelho; se o problema tiver uma data de término, ele será exibido em preto');
INSERT INTO `lang_definitions` VALUES (88735, 5111, 17, 'Se nome, qualquer parte do último nome ou');
INSERT INTO `lang_definitions` VALUES (88736, 5112, 17, 'Se NewCrop eRx - o módulo de prescrição eletrônica, estiver habilitado, os botões NewCrop MedEntry e NewCrop Account Status aparecerão aqui');
INSERT INTO `lang_definitions` VALUES (88737, 5113, 17, 'Se não estiver listado, você pode adicionar o medicamento à caixa de texto Título');
INSERT INTO `lang_definitions` VALUES (88738, 5115, 17, 'Se apenas capturar o código QR, mas não registrar a chave TOTP com OpenEMR, este recurso não será habilitado no login');
INSERT INTO `lang_definitions` VALUES (88739, 5116, 17, 'Se o paciente tiver um compromisso, clique em OK para criar um encontro, caso contrário, cancele esto e logo crie um encontro para a visita de hoje.');
INSERT INTO `lang_definitions` VALUES (88740, 5117, 17, 'Se pagar por');
INSERT INTO `lang_definitions` VALUES (88741, 5118, 17, 'Se a pessoa faleceu, insira a data da morte');
INSERT INTO `lang_definitions` VALUES (88742, 5119, 17, 'Se o telefone for perdido, não será possível fazer o login');
INSERT INTO `lang_definitions` VALUES (88743, 5120, 17, 'Administração> Usuários ou mais convenientemente nesta página, ou seja, Administração> ACL, onde todos os usuários são listados em uma página e mais opções estão disponíveis');
INSERT INTO `lang_definitions` VALUES (88744, 5121, 17, 'Se definido como alto, restringirá a visibilidade do encontro para usuários pertencentes a certos grupos (AROs). Por padrão – Físicos e Administradores');
INSERT INTO `lang_definitions` VALUES (88745, 5122, 17, 'Se SMTP for usado, o nome de anfitrião do servidor ou endereço IP');
INSERT INTO `lang_definitions` VALUES (88746, 5123, 17, 'Se for usado SMTP, o número da porta TCP do servidor (geralmente 25)');
INSERT INTO `lang_definitions` VALUES (88747, 5124, 17, 'Se desejar, o quadro padrão pode ser desabilitado indo para Administração> Calendário> Re call Quadro: Desabilite, marque a caixa de seleção e clique em Salvar');
INSERT INTO `lang_definitions` VALUES (88748, 5125, 17, 'Nesse caso, você terá que criar pedidos de procedimento individuais (os pedidos) para esses testes, juntamente com os resultados discretos (o local para inserir e exibir o resultado retornado)');
INSERT INTO `lang_definitions` VALUES (88749, 5126, 17, 'Se for bem sucedido, ele autentica o usuário');
INSERT INTO `lang_definitions` VALUES (88750, 5127, 17, 'Se a caixa de seleção estiver marcada e a mensagem for enviada a vários usuários, então cada usuário deve assinar a mensagem clicando no botão Definir como concluído para essa mensagem');
INSERT INTO `lang_definitions` VALUES (88751, 5128, 17, 'Se a caixa de seleção estiver marcada, então cada indivíduo de um grupo que receber esta mensagem terá que assinar, clicando no botão Definir como concluído');
INSERT INTO `lang_definitions` VALUES (88752, 5129, 17, 'Se o arquivo csv foi carregado, então clique no botão \"Importar eventos de feriado\". NOTE que clicar no botão irá remover todas as linhas existentes na tabela calendar_external');
INSERT INTO `lang_definitions` VALUES (88753, 5130, 17, 'Se o título desejado não estiver incluído, ele pode ser digitado na caixa de texto abaixo da lista');
INSERT INTO `lang_definitions` VALUES (88754, 5131, 17, 'Se a tabela exibida disser Nenhum registro correspondente encontrado, significa que o conjunto de códigos ICD10 não está instalado');
INSERT INTO `lang_definitions` VALUES (88755, 5132, 17, 'Se o arquivo de ajuda não existir, crie um e coloque-o em');
INSERT INTO `lang_definitions` VALUES (88756, 5133, 17, 'Se o problema não estiver relacionado a um encontro, ele exibirá 0');
INSERT INTO `lang_definitions` VALUES (88757, 5134, 17, 'Se o problema médico não estiver listado na caixa suspensa, clique na caixa de texto de Codificação para abrir a página pop-up Selecionar códigos');
INSERT INTO `lang_definitions` VALUES (88758, 5135, 17, 'Se a mensagem for encaminhada, ela aparecerá na lista de mensagens ativas do usuário para quem a mensagem foi encaminhada e desaparecerá da lista de mensagens ativas do usuário atual');
INSERT INTO `lang_definitions` VALUES (88759, 5136, 17, 'Se o portal do paciente externo estiver ativado, haverá um botão que diz Criar credenciais do portal externo, desde que o paciente tenha dado permissão para acessar o portal do paciente online ou uma mensagem que diz que o paciente não autorizou o portal do paciente');
INSERT INTO `lang_definitions` VALUES (88760, 5137, 17, 'Se o portal do paciente externo estiver ativado, haverá um botão que diz Criar credenciais do portal externo, desde que o paciente tenha dado permissão para acessar o portal do paciente online ou uma mensagem que diz que o paciente não autorizou o portal do paciente');
INSERT INTO `lang_definitions` VALUES (88761, 5138, 17, 'Se as credenciais do portal online / offsite já tiverem sido definidas, o botão mudará para');
INSERT INTO `lang_definitions` VALUES (88762, 5139, 17, 'Se o paciente tiver quaisquer dados demográficos inseridos no openEMR, ele preencherá automaticamente os campos relevantes nas seções corretas');
INSERT INTO `lang_definitions` VALUES (88763, 5140, 17, 'Se o paciente não autorizou o portal do paciente, então um paciente não autorizou a mensagem do portal do paciente será exibida aqui');
INSERT INTO `lang_definitions` VALUES (88764, 5141, 17, 'Se o paciente estiver sendo adicionado à lista de recall no dia da visita, ele refletirá a data atual');
INSERT INTO `lang_definitions` VALUES (88765, 5142, 17, 'Se o paciente está ligando de volta para ser adicionado à lista, a última consulta pode ter sido no passado remoto. Esteja ciente de que os mais de 1,2,3 anos são calculados e exibidos na caixa Data na parte inferior desta seção');
INSERT INTO `lang_definitions` VALUES (88766, 5143, 17, 'Se o paciente já faleceu, então a notificação de falecimento aparecerá em vermelho nesta seção');
INSERT INTO `lang_definitions` VALUES (88767, 5144, 17, 'Se o relatório for enviado eletronicamente, todas as etapas necessárias para a transmissão segura e protegida de informações de saúde protegidas (PHI) devem ser seguidas');
INSERT INTO `lang_definitions` VALUES (88768, 5145, 17, 'Se não houver nenhum fornecedor, insira qualquer número único arbitrário, de preferência um número zerado de 5 dígitos, por exemplo, 00211');
INSERT INTO `lang_definitions` VALUES (88769, 5146, 17, 'Se esses testes estiverem sendo enviados para o mesmo laboratório externo, eles terão códigos de identificação idênticos e específicos do fornecedor, fazendo com que linhas duplicadas apareçam quando os resultados forem exibidos');
INSERT INTO `lang_definitions` VALUES (88770, 5147, 17, 'Se eles foram configurados corretamente, cada resultado deve ter um valor de Nível 4, indicando que eles são o sucessor ou filho da primeira linha acima com um valor de Nível 3, ou seja, Painel de Eletrólito');
INSERT INTO `lang_definitions` VALUES (88771, 5148, 17, 'Se esta página não atualizar, recarregue a página Mensagens manualmente');
INSERT INTO `lang_definitions` VALUES (88772, 5149, 17, 'Se não atribuído, o padrão será a configuração do php.ini para date.timezone');
INSERT INTO `lang_definitions` VALUES (88773, 5150, 17, 'Se desempregado clique estudane');
INSERT INTO `lang_definitions` VALUES (88774, 5151, 17, 'Se o valor for deixado como zero, será classificado em ordem alfabética');
INSERT INTO `lang_definitions` VALUES (88775, 5152, 17, 'Se YMD for selecionado para exibição de idade, mude para apenas anos quando os pacientes forem mais velhos do que este valor em anos');
INSERT INTO `lang_definitions` VALUES (88776, 5153, 17, 'Se você está tendo problemas para fazer login em sua conta');
INSERT INTO `lang_definitions` VALUES (88777, 5154, 17, 'Se você estiver interessado no que acontece nos bastidores');
INSERT INTO `lang_definitions` VALUES (88778, 5155, 17, 'Se você estiver usando apenas um pequeno subconjunto de códigos CPT, você pode inseri-lo manualmente em Administração> Códigos');
INSERT INTO `lang_definitions` VALUES (88779, 5156, 17, 'Se você está planejando inserir preços diferentes para modalidades de pagamento diferentes, vá para Administração> Listas');
INSERT INTO `lang_definitions` VALUES (88780, 5160, 17, 'Se você estiver usando a entrada de laboratório eletrônico, então preencha os detalhes necessários e clique em Salvar');
INSERT INTO `lang_definitions` VALUES (88781, 5161, 17, 'Se você estiver usando vários laboratórios, insira os detalhes para cada um deles');
INSERT INTO `lang_definitions` VALUES (88782, 5162, 17, 'Se você alterar a função do e-RX para ePrescription, isso poderá afetar o fluxo de trabalho do ePrescription. Se você enfrentar qualquer dificuldade, entre em contato com seu fornecedor de ePrescription');
INSERT INTO `lang_definitions` VALUES (88783, 5163, 17, 'Se você alterar seu Smartphone, você pode recapturar o código QR da chave TOTP em um novo dispositivo, primeiro fazendo login usando o aplicativo autenticador em seu telefone antigo e, em seguida, indo para Diversos> Autenticação MFA e clicando no botão Exibir na seção Método de autenticação atual');
INSERT INTO `lang_definitions` VALUES (88784, 5164, 17, 'Se você marcar a caixa de seleção em qualquer uma dessas células irá gerar uma entrada na última célula chamada Progresso');
INSERT INTO `lang_definitions` VALUES (88785, 5165, 17, 'Se você optar por fazer uma entrada manual, clique no botão de opção \'Pesquisa de fatura\'. Ele exibe duas seções \'Publicar item\' e \'Pesquisa de fatura\'');
INSERT INTO `lang_definitions` VALUES (88786, 5166, 17, 'Se você optar por integrar os resultados do laboratório com o registro do paciente, então alguma configuração preliminar deve ser realizada');
INSERT INTO `lang_definitions` VALUES (88787, 5167, 17, 'Se você clicar em qualquer usuário na seção \'Associações de usuários\', verá agora esses grupos recém-criados (ARO) na coluna \'Inativos\'. Eles agora podem ser atribuídos da maneira usual, conforme necessário');
INSERT INTO `lang_definitions` VALUES (88788, 5168, 17, 'Se você clicar no ícone de edição próximo a este grupo recém-criado (ARO), você notará que a coluna \'Ativo\' contém apenas uma única entrada - Espaço reservado (mantém ACLs vazios). No momento, este novo grupo (ARO) NÃO tem acesso a qualquer parte do programa, pois não há ACOs atribuídos na coluna \'Ativo\'');
INSERT INTO `lang_definitions` VALUES (88789, 5169, 17, 'Se você clicar no sinal + azul em Química do soro, verá uma nova linha chamada Painel de órgãos / doenças com uma categoria de subgrupo');
INSERT INTO `lang_definitions` VALUES (88790, 5170, 17, 'Se você continuar tendo esse erro, por favor entre em contato com o suporte');
INSERT INTO `lang_definitions` VALUES (88791, 5171, 17, 'Se você não encontrar um valor necessário na caixa suspensa, você precisará adicioná-lo via Administração> Listas> Unidades de procedimento. Consulte o arquivo de ajuda em Procedimentos> Provedores');
INSERT INTO `lang_definitions` VALUES (88792, 5172, 17, 'Se você não selecionar uma correspondência, o paciente será criado');
INSERT INTO `lang_definitions` VALUES (88793, 5173, 17, 'Se você não selecionar pelo menos um deles, o OpenEMR operará em um modo somente de recepção');
INSERT INTO `lang_definitions` VALUES (88794, 5174, 17, 'Se você não enviar pedidos eletronicamente ou receber resultados eletronicamente, deixe como o valor padrão, Download');
INSERT INTO `lang_definitions` VALUES (88795, 5176, 17, 'Se você não quiser fazer isso, o método a seguir envolve adicionar dados manualmente usando a interface openEMR');
INSERT INTO `lang_definitions` VALUES (88796, 5177, 17, 'Se você detalhar a linha do painel de eletrólito e clicar no sinal + na coluna Nome, você deverá ver o sódio listado abaixo dela com um valor de categoria de resultado com um valor de nível 4');
INSERT INTO `lang_definitions` VALUES (88797, 5178, 17, 'Se você detalhar a linha do painel de eletrólito, deverá ver que ele tem uma categoria de pedido e destacado em amarelo, indicando que é um pedido pesquisável e válido e tem um valor de nível 3');
INSERT INTO `lang_definitions` VALUES (88798, 5179, 17, 'Se você selecionou vários códigos, eles serão separados por ponto e vírgula');
INSERT INTO `lang_definitions` VALUES (88799, 5180, 17, 'Se você já preencheu a tabela calendar_external, então clique no botão \"Sincronizar\" para ter os feriados na visualização do calendário. NOTE que clicar no botão irá remover todos os itens existentes na visualização do calendário relacionados aos feriados');
INSERT INTO `lang_definitions` VALUES (88800, 5181, 17, 'Se você tiver um superbill antigo você pode usar seu agrupamento de códigos como um modelo para iniciar a personalização');
INSERT INTO `lang_definitions` VALUES (88801, 5182, 17, 'Se você tiver escolhido para carregar as remessas eletrônicas, em seguida, a janela de pesquisa redisplays com as faturas correspondentes a partir do arquivo X12. Você pode clicar em qualquer um destes números de fatura (como descrito abaixo) se você deseja fazer as correções antes do envio de informações é aplicada. Para aplicar as alterações, clique no botão Arquivo Processo ERA, na parte inferior da página. Isto produzirá uma nova janela com um relatório detalhado.');
INSERT INTO `lang_definitions` VALUES (88802, 5183, 17, 'Se você optou por fazer upload de remessas eletrônicas, então a janela de pesquisa é exibida novamente com as faturas correspondentes do arquivo X12. Você pode clicar em qualquer um desses números de fatura (conforme descrito acima) se desejar fazer quaisquer correções antes que as informações de remessa sejam aplicadas. Para aplicar as alterações, clique no botão \'Processar Arquivo ERA\' na parte inferior da página. Isso produzirá uma nova janela com um relatório detalhado');
INSERT INTO `lang_definitions` VALUES (88803, 5184, 17, 'Se você tiver habilitado o método TOTP na próxima vez que fizer login, será solicitado que você digite a senha TOTP');
INSERT INTO `lang_definitions` VALUES (88804, 5185, 17, 'Se você digitou uma data de pagamento na página de pesquisa, esta irá substituir a data de lançamento de pagamentos e ajustes que são de outra tiradas do arquivo X12. Isso pode ser útil para fins de notificação, se você quiser que o seu relatório de receitas para usar a sua data de lançamento, em vez de a companhia de seguros da data de processamento. Note que isso vai afetar também as datas de pagamentos, antes e ajustes que são postos em créditos secundário.');
INSERT INTO `lang_definitions` VALUES (88805, 5186, 17, 'Se você inseriu uma data de pagamento na página de pesquisa, isso substituirá a data de lançamento de pagamentos e ajustes que são retirados do arquivo X12. Isso pode ser útil para fins de relatório, se você quiser que o relatório de recibos use a data de lançamento em vez da data de processamento da emprsa da seguradora. Observe que isso também afetará as datas de pagamentos anteriores e ajustes que são colocados em reivindicações secundárias');
INSERT INTO `lang_definitions` VALUES (88806, 5187, 17, 'Se você seguiu todas as etapas acima corretamente, deverá ver Ácido Úrico no Soro sob Nome, ele será precedido por uma barra vertical indicando a ausência de descendentes ou filhos nesta entrada');
INSERT INTO `lang_definitions` VALUES (88807, 5188, 17, 'Se você seguiu as etapas acima corretamente, o teste de ácido úrico no soro agora deve ter um sinal de + antes do nome, indicando a presença de sucessores ou filhos');
INSERT INTO `lang_definitions` VALUES (88808, 5189, 17, 'Se você perdeu seu Smartphone, aqueles com privilégios de administrador podem excluir as chaves indo para Administração> Usuários e marcando a caixa de seleção Limpar 2FA e clicando em Salvar');
INSERT INTO `lang_definitions` VALUES (88809, 5190, 17, 'Se você tiver o módulo NewCrop eRx habilitado, então as alergias devem ser inseridas na página NewCrop MedEntry');
INSERT INTO `lang_definitions` VALUES (88810, 5191, 17, 'Se você ainda não fez alguma pré-configuração, incluindo a adição de provedores, faça-o acessando Procedimentos> Provedores');
INSERT INTO `lang_definitions` VALUES (88811, 5192, 17, 'Se você tiver a necessidade de solicitar componentes individuais do painel, você terá que criar um pedido de procedimento separado para cada componente individual do painel e armazenar o resultado retornado em um Resultado discreto criado de uma forma semelhante ao usado anteriormente para criar um pedido para ácido úrico sérico');
INSERT INTO `lang_definitions` VALUES (88812, 5193, 17, 'Se você clicar no botão Atualizar sem configurar nenhum filtro,então todos os lembretes datados para o usuário aparecerão abaixo');
INSERT INTO `lang_definitions` VALUES (88813, 5194, 17, 'Se você deixar no padrão de 0 então as entradas de nível superior que você fizer serão classificadas em ordem alfabética');
INSERT INTO `lang_definitions` VALUES (88814, 5195, 17, 'Se você fez alterações e deseja reenviá-lo, exclua o original (em Comunicações) e tente novamente');
INSERT INTO `lang_definitions` VALUES (88815, 5196, 17, 'Se você fez alterações e deseja reenviá-lo, exclua o original (em Comunicações) ou aguarde 60 segundos e tente novamente');
INSERT INTO `lang_definitions` VALUES (88816, 5197, 17, 'Se você precisar inserir manualmente o resultado retornado, cada teste (item favorito personalizado) deve ter um resultado discreto como um descendente direto');
INSERT INTO `lang_definitions` VALUES (88817, 5198, 17, 'Se você não vir nenhuma entrada na caixa suspensa Pedir de, significa que você não configurou um laboratório em Procedimentos> Provedores');
INSERT INTO `lang_definitions` VALUES (88818, 5199, 17, 'Se quiser mudar tipos de dados, acrescentar linhas ou colunas');
INSERT INTO `lang_definitions` VALUES (88819, 5200, 17, 'Se você deseja atualizar o banco de dados, então coloque o arquivo zip do banco de dados no seguinte diretório');
INSERT INTO `lang_definitions` VALUES (88820, 5201, 17, 'Se a sua pesquisa foi bem sucedida, os resultados da pesquisa serão exibidos na caixa de resultados da pesquisa abaixo');
