INSERT INTO `lang_definitions` VALUES (88877, 5262, 17, 'IMPORTANTE: O número NPI também existe na entrada do Catálogo de endereços para o provedor, tome cuidado para inserir o número NPI correto');
INSERT INTO `lang_definitions` VALUES (88878, 5263, 17, 'IMPORTANTE: Esta ferramenta de upload serve apenas para fazer upload de documentos de pacientes que ainda não foram inseridos no sistema. Para fazer upload de arquivos para pacientes que já foram inseridos no sistema, por favor use a ferramenta de upload vinculada à tela de resumo do paciente.');
