INSERT INTO `lang_definitions` VALUES (88903, 5291, 17, 'No openEMR, os relatórios de Registro de Continuidade de Cuidados (CCR) a serem gerados podem ser limitados a um intervalo de datas específico marcando a caixa de seleção Usar intervalo de datas e inserindo o intervalo de datas desejado');
INSERT INTO `lang_definitions` VALUES (88904, 5292, 17, 'A fim de cumprir os requisitos de uso significativo para entrada de pedido de provedor computadorizado (CPOE) para testes de laboratório e radiologia, este módulo precisa ser usado');
INSERT INTO `lang_definitions` VALUES (88905, 5293, 17, 'Para armazenar e recuperar adequadamente os resultados do teste e fazer novos pedidos, os testes / pedidos devem ser configurados de maneira hierárquica');
INSERT INTO `lang_definitions` VALUES (88906, 5294, 17, 'Para registrar os valores dos resultados retornados, você deve criar um Resultado Discreto separado (Nível 4) para cada um dos constituintes do painel, a fruta, como descendentes diretos deste ramo (Painel de Saúde Geral) (Nível 3). Exemplos dos resultados são CBC - Hemoglobina, CBC - Hematócrito, CMP - Sódio, CMP - Potássio, TSH etc.');
INSERT INTO `lang_definitions` VALUES (88907, 5295, 17, 'Para registrar seu dispositivo, por favor forneça sua senha de login do OpenEMR');
INSERT INTO `lang_definitions` VALUES (88908, 5296, 17, 'Para enviar Registro de Continuidade de Cuidados (CCR) e / ou Documento de Continuidade de Cuidados (CCD), opcionalmente, marque phiMail Permitir CCD Send e / ou phiMail Permitir CCR Send para habilitar o recurso de transmissão para esses tipos de dados');
INSERT INTO `lang_definitions` VALUES (88909, 5297, 17, 'No nosso caso, escolheremos o laboratório local que foi configurado anteriormente');
INSERT INTO `lang_definitions` VALUES (88910, 5298, 17, 'No nosso caso, vamos deixá-lo como Não atribuído');
INSERT INTO `lang_definitions` VALUES (88911, 5300, 17, 'No modo Retrato, determina a altura do envelope ao longo do eixo y em mm');
INSERT INTO `lang_definitions` VALUES (88912, 5301, 17, 'No modo Retrato, determina a largura do envelope ao longo do eixo x em mm');
INSERT INTO `lang_definitions` VALUES (88913, 5302, 17, 'no olho direto');
INSERT INTO `lang_definitions` VALUES (88914, 5303, 17, 'Em suma, os pedidos eletrônicos podem ser feitos, envolve uma quantidade significativa de testes e customização para ser certificado pelo laboratório, geralmente por meio de um terceiro e só pode acontecer se o laboratório concordar em dar luz verde ao projeto');
INSERT INTO `lang_definitions` VALUES (88915, 5304, 17, 'Na seção \'Postar item\' exibida na parte superior, você pode inserir uma fonte (por exemplo, número do cheque), data de pagamento e valor do cheque. A razão para a fonte e a data de pagamento é para que você não precise inseri-las repetidamente para cada reivindicação. O valor que você inserir será reduzido para cada fatura que receber parte do pagamento e, com sorte, terminará em zero quando você terminar');
INSERT INTO `lang_definitions` VALUES (88916, 5305, 17, 'No exemplo acima, um pedido para um único teste foi criado, ou seja, ácido úrico sérico');
INSERT INTO `lang_definitions` VALUES (88917, 5306, 17, 'Na instalação padrão, clique em Adicionar para abrir a página pop-up Adicionar / Editar Problema');
INSERT INTO `lang_definitions` VALUES (88918, 5307, 17, 'Nas palavras do paciente');
INSERT INTO `lang_definitions` VALUES (88919, 5308, 17, 'Na segunda fase do uso significativo, o CCD, mas não o CCR, foi incluído como parte do padrão para troca de documentos clínicos');
INSERT INTO `lang_definitions` VALUES (88920, 5309, 17, 'Neste caso, o grupo de favoritos personalizados será chamado de Laboratórios de pré-operatório e os dois painéis reconhecidos serão descendentes diretos, cada um em um nível de item favorito personalizado denominado CBC e Painel renal, respectivamente');
INSERT INTO `lang_definitions` VALUES (88921, 5310, 17, 'Neste caso, você criará um Pedido de Procedimento, o ramo frutífero denominado Painel Geral de Saúde (Nível 3)');
INSERT INTO `lang_definitions` VALUES (88922, 5311, 17, 'No total, há dezessete seções que podem ser incluídas em um Registro de Continuidade de Cuidados (CCR)');
