INSERT INTO `lang_definitions` VALUES (89264, 5691, 17, 'Ele permite que o navegador se comunique diretamente com o dispositivo USB evitando a necessidade do usuário fazer qualquer coisa além de inserir o dispositivo em uma porta USB e tocar nele para ativá-lo');
INSERT INTO `lang_definitions` VALUES (89265, 5692, 17, 'Também permite criar novos grupos (AROs), bem como remover os existentes');
INSERT INTO `lang_definitions` VALUES (89266, 5693, 17, 'Ele também pode receber resultados eletronicamente');
INSERT INTO `lang_definitions` VALUES (89267, 5694, 17, 'Pode ser vinculado a um paciente ou apenas uma mensagem endereçada a outro (s) usuário (s)');
INSERT INTO `lang_definitions` VALUES (89268, 5695, 17, 'Ele combina o que o usuário sabe, ou seja, a senha do usuário com o que o usuário possui, ou seja, um dispositivo que é único ou um mecanismo para gerar / receber um código único para ser usado em cada login');
INSERT INTO `lang_definitions` VALUES (89269, 5696, 17, 'Consiste em três seções');
INSERT INTO `lang_definitions` VALUES (89270, 5697, 17, 'Consiste em duas partes - definir um provedor e configurar os pedidos e os resultados');
INSERT INTO `lang_definitions` VALUES (89271, 5698, 17, 'Consiste em duas partes - o aplicativo de recebimento e o recurso de recebimento');
INSERT INTO `lang_definitions` VALUES (89272, 5699, 17, 'Consiste em duas partes - o aplicativo de envio e o recurso de envio');
INSERT INTO `lang_definitions` VALUES (89273, 5700, 17, 'Ele contém uma seção esquerda e direita');
INSERT INTO `lang_definitions` VALUES (89274, 5701, 17, 'Ele contém um código QR que precisa ser capturado pelo aplicativo autenticador');
INSERT INTO `lang_definitions` VALUES (89275, 5702, 17, 'Ele contém dados estruturados que estão incluídos no Registro de Continuidade de Cuidados (CCR) definido para o padrão de Arquitetura de Documento Clínico');
INSERT INTO `lang_definitions` VALUES (89276, 5703, 17, 'Não se refere à referência real que foi criada');
INSERT INTO `lang_definitions` VALUES (89277, 5704, 17, 'Ele faz isso usando um algoritmo para combinar o horário UNIX atual com a chave secreta para gerar uma chave única em constante mudança');
INSERT INTO `lang_definitions` VALUES (89278, 5705, 17, 'Tem quatro guias');
INSERT INTO `lang_definitions` VALUES (89279, 5706, 17, 'Tem três níveis');
INSERT INTO `lang_definitions` VALUES (89280, 5707, 17, 'É um módulo de mensagem comercial disponível para práticas openEMR utilizando a versão 5.0.1 e superior');
INSERT INTO `lang_definitions` VALUES (89281, 5708, 17, 'É um campo no cabeçalho da mensagem HL7 conhecido como ID de processamento');
INSERT INTO `lang_definitions` VALUES (89282, 5709, 17, 'Faz parte do prontuário médico');
INSERT INTO `lang_definitions` VALUES (89283, 5710, 17, 'É também um serviço baseado em assinatura');
INSERT INTO `lang_definitions` VALUES (89284, 5711, 17, 'Também é necessário listar um código CID10 para que o problema seja listado no Relatório de Continuidade de Cuidados (CCR) e no Documento de Continuidade de Cuidados (CCD)');
INSERT INTO `lang_definitions` VALUES (89285, 5712, 17, 'Está dividido em duas seções');
INSERT INTO `lang_definitions` VALUES (89286, 5713, 17, 'É essencial que você leia as primeiras quatro seções para compreender os princípios subjacentes');
INSERT INTO `lang_definitions` VALUES (89287, 5714, 17, 'É muito mais fácil e intuitivo fazer grandes alterações e reorganizar os dados na planilha antes de começar a inserir os dados no openEMR');
INSERT INTO `lang_definitions` VALUES (89288, 5715, 17, 'É importante perceber que isso gerencia o MFA para o usuário conectado');
INSERT INTO `lang_definitions` VALUES (89289, 5716, 17, 'É importante compreender a função destes dois ícones dado que todos os passos subsequentes necessários para configurar correctamente a hierarquia irão depender da utilização correcta destes dois ícones');
INSERT INTO `lang_definitions` VALUES (89290, 5717, 17, 'Destina-se a incluir apenas as informações que são críticas para efetivamente continuar o cuidado');
INSERT INTO `lang_definitions` VALUES (89291, 5718, 17, 'É emitido para prestadores de cuidados de saúde nos Estados Unidos pelos Centros de Serviços Medicare e Medicaid (CMS)');
INSERT INTO `lang_definitions` VALUES (89292, 5719, 17, 'Não é necessário para o laboratório local, em vez disso, você pode usar qualquer número único arbitrário');
INSERT INTO `lang_definitions` VALUES (89293, 5720, 17, 'Não é necessário preencher os códigos de diagnóstico padrão, pois os códigos ICD10 podem ser inseridos no momento do pedido real do teste');
INSERT INTO `lang_definitions` VALUES (89294, 5721, 17, 'Não é enviado com a reclamação');
INSERT INTO `lang_definitions` VALUES (89295, 5722, 17, 'Não é incomum solicitar vários exames de sangue juntos, agrupá-los como um painel de exames facilita esse processo');
INSERT INTO `lang_definitions` VALUES (89296, 5724, 17, 'É o formulário de reclamação em papel básico prescrito por muitos pagadores para reclamações submetidas por médicos e práticas individuais, enfermeiras e profissionais, incluindo terapeutas, quiropráticos e clínicas ambulatoriais e, em alguns casos, para serviços de ambulância');
INSERT INTO `lang_definitions` VALUES (89297, 5725, 17, 'É usado para vincular problemas a encontros e também é usado para ver quais encontros estão associados a um determinado problema');
INSERT INTO `lang_definitions` VALUES (89298, 5726, 17, 'É útil praticar em um local de teste para se familiarizar com o processo antes de fazer isso no aplicativo openEMR de produção');
INSERT INTO `lang_definitions` VALUES (89299, 5727, 17, 'Permite pesquisar por códigos de diagnóstico ICD 9 e ICD 10 e CPT4 e HCPCS');
INSERT INTO `lang_definitions` VALUES (89300, 5728, 17, 'Ele permite que você envie mensagens e lembretes datados aos membros da equipe, adicione o paciente à lista de re call e envie mensagens de texto SMS para os pacientes');
INSERT INTO `lang_definitions` VALUES (89301, 5729, 17, 'Ele serve como uma ponte necessária para um ambiente diferente, muitas vezes com novos médicos que não sabem nada sobre o paciente, permitindo que o próximo provedor facilmente');
INSERT INTO `lang_definitions` VALUES (89302, 5731, 17, 'Portanto, é lógico que você não pode criar uma contra-referência por si só');
INSERT INTO `lang_definitions` VALUES (89303, 5732, 17, 'Ele usa um padrão aberto e, portanto, disponível em vários fabricantes');
INSERT INTO `lang_definitions` VALUES (89304, 5733, 17, 'Ele usa a função hash HMAC-SHA256 para gerar uma chave privada exclusiva para a conta');
INSERT INTO `lang_definitions` VALUES (89305, 5734, 17, 'Ele usa essa chave privada para assinar o desafio e envia a resposta de volta ao aplicativo');
INSERT INTO `lang_definitions` VALUES (89306, 5735, 17, 'Será exibido no resumo da visita');
INSERT INTO `lang_definitions` VALUES (89307, 5736, 17, 'Isso abrirá o formulário pop-up Inserir detalhes');
INSERT INTO `lang_definitions` VALUES (89308, 5737, 17, 'Isso abrirá o pop-up do localizador de vários pacientes');
INSERT INTO `lang_definitions` VALUES (89309, 5738, 17, 'Ele exibirá o pop-up de exibição justificado. Tem uma caixa de pesquisa que permite pesquisar um código ICD. Ele também exibirá os 10 códigos ICD mais comumente usados. Você pode selecionar qualquer um ou todos os códigos marcando a caixa de seleção J (justificar) e pressionando atualizar');
INSERT INTO `lang_definitions` VALUES (89310, 5739, 17, 'Terá um valor de 2 na coluna nível indicando que é um sucessor ou filho na primeira linha acima tendo um valor nível 1 que neste caso é Química do Soro');
INSERT INTO `lang_definitions` VALUES (89311, 5740, 17, 'Terá duas seções - a Seção de Problemas e a Seção de Encontros');
INSERT INTO `lang_definitions` VALUES (89312, 5741, 17, 'Isso ajudará mais tarde na solução de problemas que podem surgir com a configuração do módulo de Pedidos de Procedimento');
INSERT INTO `lang_definitions` VALUES (89313, 5742, 17, 'Irá abrir a seção Criar Nova Mensagem');
INSERT INTO `lang_definitions` VALUES (89314, 5743, 17, 'Isso o levará para a página de inscrição do MedEx');
INSERT INTO `lang_definitions` VALUES (89315, 5744, 17, 'Ele então aparecerá no widget Alergias no Painel do Paciente, bem como em alergias na página Problemas');
INSERT INTO `lang_definitions` VALUES (89316, 5745, 17, 'Ele então aparecerá no widget Medicamentos no Painel do Paciente, bem como em Medicamentos na página de Problemas');
