INSERT INTO `lang_definitions` VALUES (90895, 7530, 17, 'A Open Med Practice e seus fornecedores usam seus esforços comercialmente razoáveis para fornecer os dados mais atuais e completos disponíveis para eles sobre históricos de prescrição, interações de medicamentos e formulários, alergias de pacientes e outros fatores, mas ao usar este serviço você reconhece que (1) a integridade e precisão de tais dados depende da integridade e precisão com que são inseridos em bancos de dados eletrônicos conectados por médicos, consultórios médicos, gerentes de benefícios farmacêuticos, empresas de registros médicos eletrônicos e outros participantes da rede, (2) tais dados estão sujeitos a erro ou omissão na entrada, armazenamento ou recuperação, transmissão e exibição, interrupção técnica, falta de energia ou serviço, ou outras interrupções na comunicação eletrônica, qualquer uma ou todas as quais podem estar além do controle da Open Med Practice e seus fornecedores, e (3 ) algumas informações podem estar indisponíveis devido a restrições regulatórias, contratuais, de privacidade ou outras legais. Você é responsável por usar seu julgamento clínico em todos os momentos na prestação de serviços e conselhos médicos');
