INSERT INTO `lang_definitions` VALUES (93967, 10963, 17, 'Os valores reais que serão exibidos devem existir no banco de dados');
INSERT INTO `lang_definitions` VALUES (93968, 10964, 17, 'Os testes ou procedimentos reais que podem ser pesquisados e solicitados são destacados em amarelo');
INSERT INTO `lang_definitions` VALUES (93969, 10965, 17, 'O ícone Adicionar é usado para configurar um nível que será um descendente direto deste nível');
INSERT INTO `lang_definitions` VALUES (93970, 10966, 17, 'A vantagem de integrar os resultados ao prontuário do paciente como dados estruturados é a capacidade de manipulá-los para ver as tendências em um local conveniente, para traçar gráficos com os dados e usá-los na análise de dados');
INSERT INTO `lang_definitions` VALUES (93971, 10967, 17, 'A vantagem de digitalizar os resultados no gráfico é a simplicidade - nenhuma configuração é necessária, a não ser definir um diretório / pasta no prontuário do paciente em Documentos onde o resultado será armazenado. Sendo dados não estruturados, eles não têm as vantagens acima e não atenderão aos critérios de uso significativo para entrada de pedido do provedor computadorizado (CPOE)');
INSERT INTO `lang_definitions` VALUES (93972, 10968, 17, 'A solução Allscripts integra o site Allscripts ePrescribe com openEMR');
INSERT INTO `lang_definitions` VALUES (93973, 10969, 17, 'A American Medical Association definiu 9 painéis que podem ser solicitados. Cada painel contém vários testes agrupados');
INSERT INTO `lang_definitions` VALUES (93974, 10970, 17, 'O valor será exibido na coluna Pagamento ou Ajuste, conforme o caso');
INSERT INTO `lang_definitions` VALUES (93975, 10971, 17, 'O certificado do servidor Apache SSL e a chave pública');
INSERT INTO `lang_definitions` VALUES (93976, 10972, 17, 'O aplicativo gera um desafio - um número aleatório e o passa para a chave USB junto com o nonce e a soma de verificação armazenados no aplicativo');
INSERT INTO `lang_definitions` VALUES (93977, 10973, 17, 'O aplicativo então usa a chave pública que o dispositivo USB enviou no registro para verificar a resposta');
INSERT INTO `lang_definitions` VALUES (93978, 10974, 17, 'As mudanças no status da consulta e as criações de encontros são gerenciadas através do Patient Tracker');
INSERT INTO `lang_definitions` VALUES (93979, 10975, 17, 'O nome Autentificação ou chave API para a conta selecionada. Nome de autenticação para Authorize.Net e segredo API para Stripe');
INSERT INTO `lang_definitions` VALUES (93980, 10976, 17, 'A coluna Saldo ficaria vazia');
INSERT INTO `lang_definitions` VALUES (93981, 10977, 17, 'O objetivo básico do aplicativo autenticador é gerar um código de 20 bytes (160 bits) codificado em base32 usando uma função hash segura, SHA-1, e é chamado de HMAC-SHA1 (código de autenticação de mensagem baseado em hash)');
INSERT INTO `lang_definitions` VALUES (93982, 10978, 17, 'A base para o CCR é um Formulário de Referência de Cuidados ao Paciente desenvolvido pelo Departamento de Saúde Pública de Massachusetts');
INSERT INTO `lang_definitions` VALUES (93983, 10979, 17, 'A coluna Data de cobrança / pagador mostrará a data em que o pagamento do item de linha foi recebido e o nome do pagador - seguro ou paciente');
INSERT INTO `lang_definitions` VALUES (93984, 10980, 17, 'A coluna Data de cobrança / pagador mostrará a data em que o item de linha foi cobrado e o pagador - seguro ou paciente');
