INSERT INTO `lang_definitions` VALUES (93996, 10992, 17, 'O formulário CMS 1500 possui 33 caixas e é dividido em duas seções');
INSERT INTO `lang_definitions` VALUES (93997, 10993, 17, 'A coluna Código deve ter 905, o código de identificação específico do fornecedor que foi inserido anteriormente');
INSERT INTO `lang_definitions` VALUES (93998, 10994, 17, 'A coluna Código ficará vazia porque os itens listados como um Grupo não são usados no relatório real de resultados e, portanto, não têm um número de código distinto');
INSERT INTO `lang_definitions` VALUES (93999, 10995, 17, 'O Código será R905, o valor do Código de Identificação que foi inserido para o Resultado Discreto');
INSERT INTO `lang_definitions` VALUES (94000, 10996, 17, 'O código que você digitou não era válido');
INSERT INTO `lang_definitions` VALUES (94001, 10997, 17, 'O pacote SNOMED da extensão US testada compatível já foi instalado');
INSERT INTO `lang_definitions` VALUES (94002, 10998, 17, 'A célula de Contatos tem vários bits de informações de contato, como números de telefone, e-mail, etc.');
INSERT INTO `lang_definitions` VALUES (94003, 10999, 17, 'O Documento de Continuidade de Cuidados (CCD) e o Registro de Continuidade de Cuidados (CCR) foram ambos selecionados como formatos aceitáveis para extrair informações para resumos de cuidados clínicos como parte do Estágio 1 de Uso Significativo');
INSERT INTO `lang_definitions` VALUES (94004, 11000, 17, 'O Continuity of Care Record (CCR) foi desenvolvido em conjunto pela ASTM International - uma organização que está envolvida no desenvolvimento e entrega de consenso voluntário, a Massachusetts Medical Society (MMS), a Health Information Management and Systems Society (HIMSS), a American Academy of Family Physicians (AAFP) e American Academy of Pediatrics');
INSERT INTO `lang_definitions` VALUES (94005, 11001, 17, 'O Registro de Continuidade de Cuidados (CCR) é o registro clínico do estado de saúde atual e histórico do paciente');
INSERT INTO `lang_definitions` VALUES (94006, 11002, 17, 'O conjunto de dados principal consiste em');
INSERT INTO `lang_definitions` VALUES (94007, 11003, 17, 'A chave privada correspondente');
INSERT INTO `lang_definitions` VALUES (94008, 11004, 17, 'O relatório criado pode conter muitas ou poucas informações com base na necessidade');
INSERT INTO `lang_definitions` VALUES (94009, 11005, 17, 'O método de autenticação atual para a seção de usuário conectado agora apresentará os métodos ativados');
INSERT INTO `lang_definitions` VALUES (94010, 11006, 17, 'O método de autenticação atual lista todos os métodos que estão ativos');
INSERT INTO `lang_definitions` VALUES (94011, 11007, 17, 'A folha de honorários personalizada pode ser usada. Se e quando você encontrar um código que não existe na seção \"Selecionar códigos\" personalizada, você pode usar sempre a seção \"Pesquisar códigos adicionais\"');
INSERT INTO `lang_definitions` VALUES (94012, 11008, 17, 'O nível de item favorito personalizado deve ser descendente direto ou filho do grupo favorito personalizado relevante');
INSERT INTO `lang_definitions` VALUES (94013, 11009, 17, 'O agrupamento personalizado também te permiterá agrupar dois painéis de testes reconhecidos em um grupo personalizado e, assim, organizá-los juntos, por exemplo, um grupo personalizado de Laboratórios Preop pode conter dois painéis, CBC e Painel Renal');
INSERT INTO `lang_definitions` VALUES (94014, 11010, 17, 'O painel é o local central para acesso conveniente ao prontuário médico do paciente');
INSERT INTO `lang_definitions` VALUES (94015, 11011, 17, 'A página do painel é dividida em três seções');
INSERT INTO `lang_definitions` VALUES (94016, 11012, 17, 'O teste de integridade de dados falhou para este formulário');
INSERT INTO `lang_definitions` VALUES (94017, 11013, 17, 'A seção de dados da página do painel lista todos os itens pertinentes relacionados a um paciente');
INSERT INTO `lang_definitions` VALUES (94018, 11014, 17, 'O lembrete com data começará a aparecer 5 dias antes da data do lembrete em Lembretes com data');
INSERT INTO `lang_definitions` VALUES (94019, 11015, 17, 'O tipo de código padrão a ser pesquisado na Folha de Taxas');
INSERT INTO `lang_definitions` VALUES (94020, 11016, 17, 'A folha de taxas padrão pode ser modificada e personalizada para torná-la mais útil');
INSERT INTO `lang_definitions` VALUES (94021, 11017, 17, 'A folha de taxas padrão é dividida em várias seções e é projetada para ser preenchida de cima para baixo com o botão Salvar no final');
INSERT INTO `lang_definitions` VALUES (94022, 11018, 17, 'O formulário padrão pode ser personalizado editando-o em Administração> Layouts');
INSERT INTO `lang_definitions` VALUES (94023, 11019, 17, 'O padrão tem dois botões que são definidos para \'Novo paciente\' e \'Estabelecido\' paciente');
INSERT INTO `lang_definitions` VALUES (94024, 11020, 17, 'A instalação padrão tem seis grupos - Contabilidade, Administradores, Clínicos, Login de emergência, Front Office e Médicos');
INSERT INTO `lang_definitions` VALUES (94025, 11021, 17, 'A instalação padrão possui os seguintes itens');
INSERT INTO `lang_definitions` VALUES (94026, 11022, 17, 'A instalação padrão lista 5 tipos de problemas que podem ser documentados');
INSERT INTO `lang_definitions` VALUES (94027, 11023, 17, 'A instalação padrão não fará a ligação automaticamente');
INSERT INTO `lang_definitions` VALUES (94028, 11024, 17, 'O padrão é \'Padrão\' geralmente usado para refletir as taxas cobradas para cobrança de seguro. Você pode ter um valor diferente cobrado para pagamento com cartão de crédito e pagamento em dinheiro');
INSERT INTO `lang_definitions` VALUES (94029, 11025, 17, 'O padrão é Normal, ou seja, é visível para todos. Selecionar Alta irá restringi-lo a usuários pertencentes aos grupos de Médicos e Administradores por padrão');
INSERT INTO `lang_definitions` VALUES (94030, 11026, 17, 'O tipo de problema padrão é definido como Problema');
INSERT INTO `lang_definitions` VALUES (94031, 11027, 17, 'O centro de mensagens padrão é dividido em três seções - Mensagens, Lembretes e Recalls');
INSERT INTO `lang_definitions` VALUES (94032, 11028, 17, 'Os valores padrão para os provedores de renderização podem ser definidos');
INSERT INTO `lang_definitions` VALUES (94033, 11029, 17, 'o Código de Negação é');
INSERT INTO `lang_definitions` VALUES (94034, 11030, 17, 'o código do grupo de negação é');
INSERT INTO `lang_definitions` VALUES (94035, 11031, 17, 'A coluna Descrição exibe a breve descrição que foi inserida, testes de química de soro');
INSERT INTO `lang_definitions` VALUES (94036, 11032, 17, 'A coluna Descrição refletirá o valor da descrição que foi inserido anteriormente');
INSERT INTO `lang_definitions` VALUES (94037, 11033, 17, 'A descrição deve dizer resultado de ácido úrico no soro');
INSERT INTO `lang_definitions` VALUES (94038, 11034, 17, 'A descrição irá detalhar o tipo de pagamento ou ajuste - dinheiro, cheque, eletrônico, etc.');
INSERT INTO `lang_definitions` VALUES (94039, 11035, 17, 'O formulário de destino foi fechado');
INSERT INTO `lang_definitions` VALUES (94040, 11037, 17, 'A forma de destino estava fechada; Eu não posso agir em sua seleção.');
INSERT INTO `lang_definitions` VALUES (94041, 11038, 17, 'A diferença entre os dois é que para um painel de testes que são ordenados juntos, os testes individuais são representados apenas por Resultado Discreto e esses testes não podem ser pedidos separadamente, a menos que também tenham sido configurados como testes individuais');
INSERT INTO `lang_definitions` VALUES (94042, 11039, 17, 'O nível de resultados discretos deve ser descendente direto ou filho de um nível de ordem de procedimento para a exibição adequada dos resultados');
INSERT INTO `lang_definitions` VALUES (94043, 11040, 17, 'Os resultados discretos para cada painel conterão os nomes dos testes individuais para conter os valores dos resultados retornados - WBC, hemoglobina, plaquetas, sódio, potássio, etc.');
INSERT INTO `lang_definitions` VALUES (94044, 11041, 17, 'A janela de exibição pode ser redimensionada clicando e arrastando o canto inferior direito da janela');
INSERT INTO `lang_definitions` VALUES (94045, 11042, 17, 'A opção Cada Compromisso permitirá um novo encontro independentemente da visita no mesmo dia');
INSERT INTO `lang_definitions` VALUES (94046, 11043, 17, 'O botão Encounter Preview é útil para mostrar formulários de layout de tipo de encontro como vistos ao usar o formulário em um encontro. Observe que este recurso só é útil para mostrar formulários de encontro e não exibirá formulários de sistema como dados demográficos');
INSERT INTO `lang_definitions` VALUES (94047, 11044, 17, 'A seção de encontros exibirá a data do encontro, bem como a apresentação da reclamação');
INSERT INTO `lang_definitions` VALUES (94048, 11045, 17, 'O resultado final foi uma coleção confusa de documentos contendo informações ambíguas e / ou conflitantes');
INSERT INTO `lang_definitions` VALUES (94049, 11046, 17, 'A caixa pop-up Inserir detalhes abrirá no modo Adicionar');
INSERT INTO `lang_definitions` VALUES (94050, 11047, 17, 'O pop-up Inserir detalhes do provedor ficará visível');
INSERT INTO `lang_definitions` VALUES (94051, 11048, 17, 'A coleção inteira de ACOs forma a Lista de Controle de Acesso (ACL)');
INSERT INTO `lang_definitions` VALUES (94052, 11049, 17, 'A entidade para um item favorito personalizado é a entidade escolhida para o grupo de favoritos personalizados e não pode ser alterada');
INSERT INTO `lang_definitions` VALUES (94053, 11050, 17, 'A entidade que realiza este procedimento');
INSERT INTO `lang_definitions` VALUES (94054, 11051, 17, 'As entradas contêm dados usados para processamento posterior do computador');
INSERT INTO `lang_definitions` VALUES (94055, 11052, 17, 'As entradas destacadas em amarelo podem ser solicitadas como um teste ou procedimento, aquelas destacadas em rosa podem ser solicitadas como um grupo personalizado');
INSERT INTO `lang_definitions` VALUES (94056, 11053, 17, 'O EP, hospital elegível ou CAH que recebe um paciente de outro ambiente de cuidados ou prestador de cuidados ou acredita que um encontro é relevante deve realizar reconciliação de medicamentos');
INSERT INTO `lang_definitions` VALUES (94057, 11054, 17, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento (Medida A)');
INSERT INTO `lang_definitions` VALUES (94058, 11055, 17, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento (Medida B)');
INSERT INTO `lang_definitions` VALUES (94059, 11056, 17, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento');
INSERT INTO `lang_definitions` VALUES (94060, 11057, 17, 'O evento(s) foi aprovado.');
INSERT INTO `lang_definitions` VALUES (94061, 11058, 17, 'O evento(s) foi escondido.');
INSERT INTO `lang_definitions` VALUES (94062, 11059, 17, 'O dados exportado se aparece na área de texto abaixo. Você pode copiar e pode colar isto em um e-mail ou para qualquer outro destino desejado.');
INSERT INTO `lang_definitions` VALUES (94063, 11060, 17, 'Os dados exportados aparecem na área de texto abaixo. Você pode copiar e colar isso em um e-mail ou em qualquer outro destino desejado (ou) baixar o link abaixo');
INSERT INTO `lang_definitions` VALUES (94064, 11061, 17, 'O dados exportado se aparece na área de texto abaixo. Você pode copiar e pode colar isto em um e-mail ou para qualquer outro destino desejado.');
INSERT INTO `lang_definitions` VALUES (94065, 11062, 17, 'Os dados exportados aparecem na área de texto abaixo. Você pode copiar e colar isto em um e-mail ou em qualquer outro destino desejado. {{MARQUE PARA DELEÇÃO DURANTE A PRÓXIMA CONSTRUÇÃO DA TRADUÇÃO}}');
INSERT INTO `lang_definitions` VALUES (94066, 11063, 17, 'Os recursos de uma instalação habilitada para MedEx são explicados neste vídeo');
