INSERT INTO `lang_definitions` VALUES (94068, 11066, 17, 'O arquivo não pode ser renomear com sucesso, esse erro geralmente está relacionado a problemas de permissões no sistema de armazenamento');
INSERT INTO `lang_definitions` VALUES (94069, 11067, 17, 'O arquivo não pôde ser armazenado com sucesso, este erro geralmente está relacionado a problemas de permissões no sistema de armazenamento');
INSERT INTO `lang_definitions` VALUES (94070, 11068, 17, 'A seção de filtro pode ser escondida ou revelada clicando na ponta da seta no canto inferior direito');
INSERT INTO `lang_definitions` VALUES (94071, 11069, 17, 'Os resultados filtrados aparecerão na seção abaixo deles');
INSERT INTO `lang_definitions` VALUES (94072, 11071, 17, 'O primeiro gráfico (\"alvo\") é aquele considerado o mais completo e preciso. As seções demográficas, históricas e de seguro para este serão mantidas.');
INSERT INTO `lang_definitions` VALUES (94073, 11072, 17, 'A primeira coluna contém o nome do Grupo / Categoria que será exibido no botão');
INSERT INTO `lang_definitions` VALUES (94074, 11073, 17, 'A primeira coluna é o nome que você deu a esta entrada, ou seja, Química do Soro. Uma barra vertical precederá o nome real. Isso indica que não há descendentes ou filhos para esta entrada');
INSERT INTO `lang_definitions` VALUES (94075, 11074, 17, 'As primeiras quatro seções lidam com a criação de ordens de procedimento de uma maneira estruturada para facilitar a ordem de testes e inserir os resultados retornados manualmente');
INSERT INTO `lang_definitions` VALUES (94076, 11075, 17, 'A primeira linha mostrará a data do encontro e o motivo, bem como o provedor para esse encontro');
INSERT INTO `lang_definitions` VALUES (94077, 11076, 17, 'A primeira seção permite que você vincule esta mensagem a um paciente, se desejar');
INSERT INTO `lang_definitions` VALUES (94078, 11077, 17, 'O primeiro segmento em cada mensagem HL7 é sempre o cabeçalho da mensagem, um segmento que transmite os metadados da mensagem como quem a enviou e quando. O cabeçalho da mensagem é indicado nas três primeiras letras do segmento como MSH');
INSERT INTO `lang_definitions` VALUES (94079, 11078, 17, 'O primeiro passo é se inscrever para uma conta de produção de mensagens diretas com EMR Direct, registrando-se em seu site');
INSERT INTO `lang_definitions` VALUES (94080, 11079, 17, 'A primeira etapa é fazer o download da versão SNOMED CT. O acesso ao SNOMED CT é fornecido pela IHTSDO e seus países membros. Para mais informações, veja');
INSERT INTO `lang_definitions` VALUES (94081, 11080, 17, 'O primeiro passo é fazer o download da versão VALUESET. O acesso ao VALUESET é fornecido pela NLM. Apenas o conjunto de valores para Profissionais Elegíveis precisa ser baixado e deve ser baixado no formato XML da coluna Sorted By CMS ID. Para obter mais detalhes, veja o link abaixo');
INSERT INTO `lang_definitions` VALUES (94082, 11081, 17, 'A primeira etapa é abrir uma conta no site do Unified Medical Language System');
INSERT INTO `lang_definitions` VALUES (94083, 11082, 17, 'A primeira etapa é planejar o que a seção \'Selecionar Códigos\' da sua Folha de Taxas deve exibir');
INSERT INTO `lang_definitions` VALUES (94084, 11083, 17, 'A primeira etapa é selecionar um tipo de transação');
INSERT INTO `lang_definitions` VALUES (94085, 11084, 17, 'A primeira etapa seria criar uma entrada de nível superior. Faça isso clicando no botão nível superior Adicionar');
INSERT INTO `lang_definitions` VALUES (94086, 11085, 17, 'A primeira guia é a guia de referência que constitui a referência que está sendo feita');
INSERT INTO `lang_definitions` VALUES (94087, 11086, 17, 'Os primeiros dois números na primeira e segunda colunas serão usados para determinar a ordem de classificação dos botões e das listas que estão presentes no pop-up');
INSERT INTO `lang_definitions` VALUES (94088, 11087, 17, 'O evento de calendário seguinte foi somado:');
