INSERT INTO `lang_definitions` VALUES (94114, 11114, 17, 'O nome do host da máquina do repositório de auditoria ATNA');
INSERT INTO `lang_definitions` VALUES (94115, 11116, 17, 'O código de identificação deve ser único para que os resultados sejam exibidos corretamente, você pode apenas usar R905 como exemplo');
INSERT INTO `lang_definitions` VALUES (94116, 11117, 17, 'O código de identificação deve ser único, se for enviar para um laboratório externo, o código de identificação fornecido pelo fornecedor deve ser inserido. Vamos inserir um valor único arbitrário - WWT01');
INSERT INTO `lang_definitions` VALUES (94117, 11118, 17, 'O código de identificação é um código específico do fornecedor que identifica este procedimento ou resultado. Você pode ver exemplos disso nos papéis do laboratório que os laboratórios usam');
INSERT INTO `lang_definitions` VALUES (94118, 11119, 17, 'O código de identificação é essencial para a exibição adequada e tabulação dos resultados');
INSERT INTO `lang_definitions` VALUES (94119, 11120, 17, 'O código de identificação de R34392-1, um número arbitrário, neste caso o código de identificação precedido por R para indicar o resultado e seguido por 1 para indicar o primeiro na sequência, pode ser qualquer coisa única que você escolher');
INSERT INTO `lang_definitions` VALUES (94120, 11121, 17, 'As informações inseridas aqui são usadas para exibir um resumo do encontro. Também é usado para fins de cobrança');
INSERT INTO `lang_definitions` VALUES (94121, 11122, 17, 'As informações inseridas neste formulário serão usadas para preencher uma reclamação em papel');
INSERT INTO `lang_definitions` VALUES (94122, 11123, 17, 'As informações fornecidas no Formulário de Novo Encontro e Folha de Taxas no openEMR são usadas para gerar a reclamação em papel, bem como as reclamações eletrônicas');
INSERT INTO `lang_definitions` VALUES (94123, 11124, 17, 'Os esforços iniciais levaram à criação de Guias de Implementação (IGs) duplicados e conflitantes publicados por diferentes organizações de padrões');
INSERT INTO `lang_definitions` VALUES (94124, 11125, 17, 'A tela inicial permite que você selecione um método, oferecendo-lhe essas duas opções');
INSERT INTO `lang_definitions` VALUES (94125, 11126, 17, 'A janela inicial é a página de procura de fatura. Ao topo você pode entrar em uma fonte (por exemplo confira número), pague data e confira quantia. A razão para a fonte e data de pagamento está de forma que você dom \'t têm que entrar neles inúmeras vezes para cada reivindicação. A quantia na que você entra será diminuída para cada fatura que é determinada parte do pagamento, e esperançosamente terminará a zero quando você for terminado.');
INSERT INTO `lang_definitions` VALUES (94126, 11127, 17, 'A entrada deve ser um arquivo CSV com 3 colunas: ID do layout, tipo de código e código');
INSERT INTO `lang_definitions` VALUES (94127, 11128, 17, 'O diretório de instalação precisa ser criado');
INSERT INTO `lang_definitions` VALUES (94128, 11129, 17, 'A versão SNOMED internacional instalada não é compatível com o pacote SNOMED da extensão dos EUA testado');
INSERT INTO `lang_definitions` VALUES (94129, 11130, 17, 'A versão SNOMED internacional instalada está desatualizada e não é compatível com o arquivo SNOMED de extensão dos EUA testado');
INSERT INTO `lang_definitions` VALUES (94130, 11131, 17, 'A versão instalada e os arquivos testados são os mesmos');
INSERT INTO `lang_definitions` VALUES (94131, 11132, 17, 'A versão instalada é uma versão mais recente do que os arquivos testados');
INSERT INTO `lang_definitions` VALUES (94132, 11133, 17, 'O manual de instruções sobre como preencher o formulário CMS 1500 pode ser encontrado aqui');
INSERT INTO `lang_definitions` VALUES (94133, 11134, 17, 'O endereço IP do (s) seu (s) controlador (es) de domínio');
INSERT INTO `lang_definitions` VALUES (94134, 11135, 17, 'Os problemas podem ser inseridos de duas maneiras');
INSERT INTO `lang_definitions` VALUES (94135, 11136, 17, 'A seção de problemas exibirá todos os problemas inseridos para o paciente e exibirá o tipo de problema, seu título e uma descrição');
INSERT INTO `lang_definitions` VALUES (94136, 11137, 17, 'Os itens listados na coluna \'Ativo\' delineiam os privilégios deste grupo (ARO) e constituem esta Lista de Controle de Acesso (ACL) deste grupo');
INSERT INTO `lang_definitions` VALUES (94137, 11138, 17, 'Os itens que têm asteriscos após eles são obrigatórios');
INSERT INTO `lang_definitions` VALUES (94138, 11140, 17, 'O rótulo que aparece para o usuário sobre a forma');
INSERT INTO `lang_definitions` VALUES (94139, 11141, 17, 'A última célula da linha no Encontro');
INSERT INTO `lang_definitions` VALUES (94140, 11142, 17, 'A última linha deste bloco de encontro dará ao encontro os totais de Encargos, Pagamentos, Ajustes e o Saldo');
INSERT INTO `lang_definitions` VALUES (94141, 11143, 17, 'A última seção trata de pedidos eletrônicos');
INSERT INTO `lang_definitions` VALUES (94142, 11144, 17, 'A data da última visita será preenchida automaticamente');
INSERT INTO `lang_definitions` VALUES (94143, 11145, 17, 'A versão mais recente é FHIR - Fast Healthcare Interoperability Resources - é uma estrutura de padrões de próxima geração criada pelo HL7. Isso está ganhando popularidade, mas ainda não foi amplamente implementado');
INSERT INTO `lang_definitions` VALUES (94144, 11147, 17, 'O comprimento não deve exceder o seguinte número de caracteres');
INSERT INTO `lang_definitions` VALUES (94145, 11150, 17, 'A tabela de registro mostrará uma lista de ambos mensagens e lembretes datados, se houver');
INSERT INTO `lang_definitions` VALUES (94146, 11151, 17, 'O código LOINC para ácido úrico sérico é 3084-1, LOINC refere-se a ele como urato no soro ou plasma');
INSERT INTO `lang_definitions` VALUES (94147, 11152, 17, 'A mesclagem não será executada a menos que SSN e DOB para que os dois gráficos sejam idênticos');
INSERT INTO `lang_definitions` VALUES (94148, 11153, 17, 'A mensagem não pôde ser enviada neste momento');
INSERT INTO `lang_definitions` VALUES (94149, 11154, 17, 'O status da mensagem será Novo, pois é uma nova mensagem que está sendo criada');
INSERT INTO `lang_definitions` VALUES (94150, 11155, 17, 'As mensagens que foram enviadas pelo usuário naquele dia serão exibidas na tabela abaixo');
INSERT INTO `lang_definitions` VALUES (94151, 11156, 17, 'O centro de mensagens consolida convenientemente as opções de comunicação em um só lugar');
INSERT INTO `lang_definitions` VALUES (94152, 11157, 17, 'O centro de mensagens será aberto com a guia Mensagens ativada e exibirá as mensagens do usuário conectado, conforme indicado pela legenda Minhas mensagens');
INSERT INTO `lang_definitions` VALUES (94153, 11158, 17, 'A informação mínima necessária para criar um novo encontro é selecionar uma categoria de visita');
INSERT INTO `lang_definitions` VALUES (94154, 11159, 17, 'As opções de faturamento diversas para o formulário HCFA-1500 são usadas para fornecer informações adicionais para uma reclamação individual');
INSERT INTO `lang_definitions` VALUES (94155, 11160, 17, 'O método mais comum é chamado de autorização de 2 fatores ou 2FA');
INSERT INTO `lang_definitions` VALUES (94156, 11161, 17, 'A questão mais importante que precisa ser tratada é com quem você está tentando se conectar e o que precisa acontecer no final. A maioria dos grandes laboratórios não lidará com práticas individuais; em tais casos, um fornecedor terceirizado atuará como um intermediário que será responsável por estabelecer uma conexão entre a clínica e o laboratório por meio de sua interface (do intermediário)');
INSERT INTO `lang_definitions` VALUES (94157, 11162, 17, 'O fabricante mais popular de chaves de segurança é a Yubico, que oferece versões USB regulares, bem como aquelas feitas para dispositivos que requerem conexões USB-C, como os sistemas Mac OS mais recentes da Apple');
INSERT INTO `lang_definitions` VALUES (94158, 11163, 17, 'O Sistema Open-source Médico e Hospitalar de Saúde mais popular que existe.');
INSERT INTO `lang_definitions` VALUES (94159, 11164, 17, 'A célula do nome contém o nome, data de nascimento, ID do paciente e data da última visita');
INSERT INTO `lang_definitions` VALUES (94160, 11165, 17, 'O bloco narrativo contém informações que são processadas como texto legível');
INSERT INTO `lang_definitions` VALUES (94161, 11166, 17, 'O National Uniform Claim Committee (NUCC) é responsável pela manutenção do Formulário de Reivindicação 1500');
INSERT INTO `lang_definitions` VALUES (94162, 11167, 17, 'A barra de navegação permite navegar rapidamente para várias partes do registro médico do paciente');
INSERT INTO `lang_definitions` VALUES (94163, 11168, 17, 'A nova categoria será uma subcategoria de');
