INSERT INTO `lang_definitions` VALUES (94165, 11171, 17, 'Os novos campos de senha não são os mesmos');
INSERT INTO `lang_definitions` VALUES (94166, 11173, 17, 'O nome do parceiro NewCrop eRx, o nome NewCrop eRx e a senha NewCrop eRx serão fornecidos pelo fornecedor');
INSERT INTO `lang_definitions` VALUES (94167, 11174, 17, 'A próxima caixa é Body Site, não relevante para um exame de sangue, mas pode ser mais útil, digamos, para rastrear injeções ou solicitar raios-X');
INSERT INTO `lang_definitions` VALUES (94168, 11175, 17, 'As próximas poucas linhas listarão todos os códigos E / M e CPT que foram cobrados, uma linha por código');
INSERT INTO `lang_definitions` VALUES (94169, 11176, 17, 'O próximo grupo consiste dos códigos ICD');
INSERT INTO `lang_definitions` VALUES (94170, 11177, 17, 'As próximas três células são as células de ação que permitem que você execute alguma atividade de recordação');
INSERT INTO `lang_definitions` VALUES (94171, 11178, 17, 'As próximas duas caixas que indicam o código de identificação e o código padrão são muito importantes');
INSERT INTO `lang_definitions` VALUES (94172, 11179, 17, 'A célula de Notas permite- lhe adicionar uma nota a uma ação que você realiza nas 3 células de ação ou apenas uma nota sem qualquer associação com a ação');
INSERT INTO `lang_definitions` VALUES (94173, 11180, 17, 'O número de compromissos futuros para exibir na declaração');
INSERT INTO `lang_definitions` VALUES (94174, 11181, 17, 'O número de arquivos testados está incorreto. Coloque apenas o arquivo que deseja instalar / atualizar para');
INSERT INTO `lang_definitions` VALUES (94175, 11182, 17, 'O número de arquivos testados está incorreto. Coloque apenas o arquivo que deseja instalar / atualizar para');
INSERT INTO `lang_definitions` VALUES (94176, 11183, 17, 'O escritório: o celular permite que você indique que uma chamada foi feita');
INSERT INTO `lang_definitions` VALUES (94177, 11184, 17, 'A opção Expandir toda a linha é útil ao usar Texto estático para permitir que o texto seja quebrado e estendido por toda a linha, independentemente das configurações da coluna. Outro uso pode ser criar uma linha vazia como espaçador ou adicionar a opção Adicionar Borda Inferior para criar uma quebra de linha. Somente a Linha da Borda Inferior é útil aqui');
INSERT INTO `lang_definitions` VALUES (94178, 11185, 17, 'As opções de Contorno e Borda irão envolver uma linha em uma borda fina ou adicionar uma borda na parte inferior de um item');
INSERT INTO `lang_definitions` VALUES (94179, 11186, 17, 'A ordem em que a categoria, procedimento ou resultado aparece');
INSERT INTO `lang_definitions` VALUES (94180, 11187, 17, 'Os outros 4 tipos de transação são tipos de transação simples - Solicitação do paciente, Solicitação do médico, Legal e Cobrança');
INSERT INTO `lang_definitions` VALUES (94181, 11188, 17, 'Os outros segmentos contêm informações adicionais de forma estritamente estruturada');
INSERT INTO `lang_definitions` VALUES (94182, 11189, 17, 'A página será redirecionada para Demografia. Você pode editar o campo do país e clicar para NewCrop novamente');
INSERT INTO `lang_definitions` VALUES (94183, 11190, 17, 'A página que você requisitou não foi encontrada. Por favor, erifique se você digitou o URL corretamente');
INSERT INTO `lang_definitions` VALUES (94184, 11191, 17, 'As partes do programa às quais o acesso pode ser controlado são chamadas de Objetos de Controle de Acesso (ACOs)');
