INSERT INTO `lang_definitions` VALUES (94190, 11197, 17, 'Os lembretes do paciente foram enviados');
INSERT INTO `lang_definitions` VALUES (94191, 11198, 17, 'Os lembretes do paciente foram atualizados');
INSERT INTO `lang_definitions` VALUES (94192, 11199, 17, 'O paciente não estava logado ao enviar este formulário');
INSERT INTO `lang_definitions` VALUES (94193, 11200, 17, 'O paciente terá que alterar suas credenciais no primeiro login');
INSERT INTO `lang_definitions` VALUES (94194, 11201, 17, 'Os direitos dos pacientes');
INSERT INTO `lang_definitions` VALUES (94195, 11202, 17, 'O Pagamento, Ajuste e Saldo ficarão em branco, pois essas linhas refletem apenas as cobranças sendo feitas');
INSERT INTO `lang_definitions` VALUES (94196, 11203, 17, 'Os pagamentos lançados não podem ser inferiores a esta data. Isso garante que, depois de fazer o relatório final, ninguém poste para datas anteriores');
INSERT INTO `lang_definitions` VALUES (94197, 11204, 17, 'O cabeçalho do formulário pop-up agora exibirá Inserir detalhes para item favorito individual personalizado');
INSERT INTO `lang_definitions` VALUES (94198, 11205, 17, 'O portal possui dados para este paciente e formulário. Carregar agora?');
INSERT INTO `lang_definitions` VALUES (94199, 11206, 17, 'A mensagem anterior pode, no entanto, ser visualizada clicando no botão Exibir Log');
INSERT INTO `lang_definitions` VALUES (94200, 11207, 17, 'A página de Ordem de Procedimento lista os seguintes tipos de procedimento');
INSERT INTO `lang_definitions` VALUES (94201, 11208, 17, 'A solicitação de procedimento precisa ser estruturada de maneira hierárquica e um código de identificação exclusivo atribuído a ela que será então usado para rastrear e tabular o resultado');
INSERT INTO `lang_definitions` VALUES (94202, 11209, 17, 'O módulo de procedimentos é usado para fazer e revisar pedidos');
INSERT INTO `lang_definitions` VALUES (94203, 11210, 17, 'O processo de encaminhamento da mensagem é bastante semelhante ao de criação de uma nova mensagem');
INSERT INTO `lang_definitions` VALUES (94204, 11211, 17, 'A célula de progresso lista todas as ações junto com quaisquer notas associadas, se houver');
INSERT INTO `lang_definitions` VALUES (94205, 11213, 17, 'A chave de acesso pública para tokenização segura de autorização de cartão de crédito ou débito. Conformidade PCI');
INSERT INTO `lang_definitions` VALUES (94206, 11214, 17, 'O código QR também contém o nome do usuário e precisa ser capturado pelo usuário em seu dispositivo móvel usando um aplicativo autenticador');
INSERT INTO `lang_definitions` VALUES (94207, 11215, 17, 'A liberação do feed de dados brutos pode ser obtida em');
INSERT INTO `lang_definitions` VALUES (94208, 11216, 17, 'A célula de recall tem a data e o motivo do recall');
INSERT INTO `lang_definitions` VALUES (94209, 11217, 17, 'A guia Recalls tem dois botões New Recall e Recall Board');
INSERT INTO `lang_definitions` VALUES (94210, 11218, 17, 'O nível de recomendação é opcional');
INSERT INTO `lang_definitions` VALUES (94211, 11219, 17, 'A informação restante debaixo de só aplica se você está postando manualmente, ou se você está fazendo correções manuais.');
INSERT INTO `lang_definitions` VALUES (94212, 11220, 17, 'O lembrete para o dia atual terá um ícone de exclamação laranja');
INSERT INTO `lang_definitions` VALUES (94213, 11221, 17, 'Os lembretes estão vencidos terão um ícone de triângulo de exclamação vermelho');
INSERT INTO `lang_definitions` VALUES (94214, 11222, 17, 'O documento solicitado não está presente no local esperado no sistema de arquivos ou não há permissões suficientes para acessá-lo');
INSERT INTO `lang_definitions` VALUES (94215, 11223, 17, 'O documento pedido não está presente no local esperado no filesystem ou não há permissões suficientes para acessar isto.');
INSERT INTO `lang_definitions` VALUES (94216, 11224, 17, 'O resto pode ser deixado em branco se preferir');
INSERT INTO `lang_definitions` VALUES (94217, 11225, 17, 'O resto das caixas relacionadas ao serviço NewCrop eRx podem ser deixadas com os valores padrão');
INSERT INTO `lang_definitions` VALUES (94218, 11226, 17, 'A linha de resultados começará com um nome de ácido úrico sérico que será precedido por uma barra vertical indicando nenhum sucessor ou filho');
INSERT INTO `lang_definitions` VALUES (94219, 11227, 17, 'Os resultados não puderam ser carregados');
INSERT INTO `lang_definitions` VALUES (94220, 11228, 17, 'Os resultados, Resultado Discreto, serão o fruto deste ramo e criaremos um tal Resultado Discreto para cada um dos testes de componentes, Sódio, Potássio, Cloreto e Dióxido de Carbono');
INSERT INTO `lang_definitions` VALUES (94221, 11229, 17, 'As linhas contendo os códigos CPT4 têm várias caixas que precisam ser preenchidas para garantir o faturamento adequado de reclamações');
INSERT INTO `lang_definitions` VALUES (94222, 11230, 17, 'O problema médico salvo agora será listado como uma única linha na página de problemas principal em Problemas médicos');
INSERT INTO `lang_definitions` VALUES (94223, 11232, 17, 'O tempo de atualização da tela em segundos para a tela do quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (94224, 11234, 17, 'Os resultados da pesquisa são exibidos na seção \'Resultados da pesquisa\'');
INSERT INTO `lang_definitions` VALUES (94225, 11235, 17, 'O segundo gráfico (\"fonte\") terá suas seções demográficas, histórico e de seguros descartadas. Seus outros dados serão mesclados no gráfico de destino');
INSERT INTO `lang_definitions` VALUES (94226, 11236, 17, 'A segunda coluna contém as opções que serão exibidas quando o botão for clicado');
INSERT INTO `lang_definitions` VALUES (94227, 11237, 17, 'A segunda coluna é Categoria e deve dizer Grupo Superior para indicar sua posição como o item superior nesta árvore hierárquica particular que iremos construir');
INSERT INTO `lang_definitions` VALUES (94228, 11238, 17, 'A segunda seção permite que você escolha para quem deseja enviar a mensagem');
INSERT INTO `lang_definitions` VALUES (94229, 11239, 17, 'A segunda guia é um pouco ambiguamente chamada de Contra-referência, é o local para documentar a resposta recebida à referência que está sendo feita');
INSERT INTO `lang_definitions` VALUES (94230, 11240, 17, 'A seção chamada \'Pesquisa de fatura\' é onde você coloca seus parâmetros de pesquisa. Você pode pesquisar pelo nome do paciente, número do prontuário, número do encontro ou data do serviço, ou qualquer combinação destes. Você também pode selecionar se deseja ver todas as faturas, faturas em aberto ou apenas as faturas vencidas (pelo paciente). Clique no botão \'Pesquisar\' para realizar a pesquisa');
INSERT INTO `lang_definitions` VALUES (94231, 11241, 17, 'O código selecionado será adicionado à caixa de texto de codificação e a Descrição do código será adicionada à caixa de texto Título');
INSERT INTO `lang_definitions` VALUES (94232, 11242, 17, 'Os códigos selecionados irão aparecer na seção \'Códigos da Folha de Taxas Selecionados e Encargos para Encontro Atual\'');
INSERT INTO `lang_definitions` VALUES (94233, 11243, 17, 'As seleções nesta seção serão usadas para cobrar por este encontro');
INSERT INTO `lang_definitions` VALUES (94234, 11244, 17, 'A sequência é a ordem em que este item de ordem superior será exibido na página, 1 para denotar o primeiro grupo de nível superior');
INSERT INTO `lang_definitions` VALUES (94235, 11245, 17, 'O endereço do servidor será da forma');
INSERT INTO `lang_definitions` VALUES (94236, 11246, 17, 'A configuração para os testes de laboratório será descrita em detalhes, pequenas modificações nessas etapas serão necessárias para configurar os procedimentos no escritório e outros tipos de procedimento');
INSERT INTO `lang_definitions` VALUES (94237, 11247, 17, 'A Contra-referência, um tanto ambiguamente, é o espaço onde a resposta à referência feita pode ser documentada');
INSERT INTO `lang_definitions` VALUES (94238, 11248, 17, 'São copiadas a Fonte e colunas de Data da primeira página, tão normalmente você não precisará tocar esses. Você pode pôr uma quantia de pagamento na coluna de Pagamento, uma quantia de ajuste no Ajuste coluna, ou ambos. Você também pode clicar à direita o \"W\" para computar um valor de ajuste que escreve fora o resto do custo para aquele artigo de linha automaticamente.');
INSERT INTO `lang_definitions` VALUES (94239, 11249, 17, 'As colunas fonte e Data são copiadas da primeira página, portanto, normalmente você não precisará tocá-las. Você pode colocar um valor de pagamento na coluna Pagamento, um valor de ajuste na coluna Ajuste ou ambos. Você também pode clicar no \'W\' à direita para calcular automaticamente um valor de ajuste que baixa o restante da cobrança desse item de linha');
INSERT INTO `lang_definitions` VALUES (94240, 11250, 17, 'O tipo de amostra será Sangue, esta lista suspensa também pode ser editada conforme necessário');
INSERT INTO `lang_definitions` VALUES (94241, 11251, 17, 'As datas de lançamento dos arquivos testados não são todas do mesmo lançamento');
INSERT INTO `lang_definitions` VALUES (94242, 11252, 17, 'As revisões dos arquivos testados não são todas da mesma versão');
INSERT INTO `lang_definitions` VALUES (94243, 11253, 17, 'O pacote SNOMED da extensão dos EUA testado não pode ser instalado até que o pacote SNOMED internacional tenha sido instalado');
INSERT INTO `lang_definitions` VALUES (94244, 11254, 17, 'O código padrão é opcional se estiver usando um laboratório local, ou seja, com base na prática, mas recomendado ao usar um laboratório externo');
INSERT INTO `lang_definitions` VALUES (94245, 11255, 17, 'O código padrão será o código LOINC se for enviado para um laboratório externo ou pode ser qualquer número exclusivo. Vamos inserir o código LOINC para a glicose de jejum 1558-6');
INSERT INTO `lang_definitions` VALUES (94246, 11256, 17, 'o estado de três problemas crônicos / inativos');
INSERT INTO `lang_definitions` VALUES (94247, 11257, 17, 'As linhas subsequentes indicarão os detalhes dos pagamentos recebidos, ajustes realizados e o saldo devedor');
INSERT INTO `lang_definitions` VALUES (94248, 11258, 17, 'O sufixo da conta');
INSERT INTO `lang_definitions` VALUES (94249, 11259, 17, 'O sistema não permite o upload de arquivos de tamanho 0');
INSERT INTO `lang_definitions` VALUES (94250, 11260, 17, 'O sistema não permite o upload de arquivos com tipo de conteúdo MIME');
INSERT INTO `lang_definitions` VALUES (94251, 11261, 17, 'O sistema também é projetado para analisar mensagens HL7 recebidas e colocar os resultados no prontuário do paciente apropriado, caso contrário, você terá a oportunidade de vinculá-lo manualmente a um prontuário do paciente');
INSERT INTO `lang_definitions` VALUES (94252, 11262, 17, 'O sistema é projetado para ambos fazer pedidos eletronicamente e receber os resultados eletronicamente');
INSERT INTO `lang_definitions` VALUES (94253, 11263, 17, 'A terceira coluna conterá o código CPT');
INSERT INTO `lang_definitions` VALUES (94254, 11264, 17, 'O valor da coluna nível será 1, indicando que é um item de nível superior');
INSERT INTO `lang_definitions` VALUES (94255, 11265, 17, 'O valor da coluna nível será 3, indicando que este é um sucessor ou filho da primeira linha acima com o valor 2');
INSERT INTO `lang_definitions` VALUES (94256, 11266, 17, 'A coluna nível será 2, indicando que este é um sucessor ou filho da primeira linha acima com o valor 1');
INSERT INTO `lang_definitions` VALUES (94257, 11267, 17, 'A Coluna do nível seria 1, indicando que é o Grupo Principal');
INSERT INTO `lang_definitions` VALUES (94258, 11268, 17, 'A granularidade de tempo do calendário e o menor intervalo em minutos para um bloco de compromisso');
INSERT INTO `lang_definitions` VALUES (94259, 11269, 17, 'O Título será o nome do novo grupo (ARO) que você vai criar');
INSERT INTO `lang_definitions` VALUES (94260, 11270, 17, 'O grupo superior consiste em cargas para o encontro - uma linha por carga');
INSERT INTO `lang_definitions` VALUES (94261, 11271, 17, 'A parte superior do Recall Board permite a configuração de filtros para exibir dados especificados');
