INSERT INTO `lang_definitions` VALUES (94643, 11696, 17, 'Para excluir qualquer um ou todos os códigos ICD10 selecionados, clique novamente na caixa Códigos de Diagnóstico para abrir a janela pop-up Selecionar Códigos de Diagnóstico');
INSERT INTO `lang_definitions` VALUES (94644, 11697, 17, 'Para desvincular, basta clicar no item para desvincular e ele será desvinculado e não será mais destacado');
INSERT INTO `lang_definitions` VALUES (94645, 11698, 17, 'Para Dems');
INSERT INTO `lang_definitions` VALUES (94646, 11699, 17, 'Para desativar a verificação automática de mensagens, vá para Administração> Globais> Conectores e defina o intervalo de verificação de mensagens phiMail como 0 (zero)');
INSERT INTO `lang_definitions` VALUES (94647, 11700, 17, 'Para desativar os certificados SSL do lado do cliente, comente acima das linhas no arquivo de configuração do Apache e defina');
INSERT INTO `lang_definitions` VALUES (94648, 11702, 17, 'Para desabilitar HTTPS, comente as linhas acima no arquivo de configuração do Apache e reinicie o servidor Apache');
INSERT INTO `lang_definitions` VALUES (94649, 11703, 17, 'Para exibir o valor do copagamento, ele deve ter sido inserido no seguro do paciente em Editar> Dados demográficos');
INSERT INTO `lang_definitions` VALUES (94650, 11704, 17, 'Para fazer isso, clique no sinal + preto no final da linha de pedido de ácido úrico no soro para abrir o pop-up Inserir detalhes');
INSERT INTO `lang_definitions` VALUES (94651, 11705, 17, 'Para editar um grupo existente (ARO) clique no ícone ao lado do grupo desejado. Isso abrirá a janela de edição');
INSERT INTO `lang_definitions` VALUES (94652, 11706, 17, 'Para ativar qualquer outra forma de conectividade, será necessário escrever um novo código');
