INSERT INTO `lang_definitions` VALUES (94655, 11709, 17, 'Para ativar a ajuda - Vá para Administração> Globais> Recursos> Ativar Modal de Ajuda');
INSERT INTO `lang_definitions` VALUES (94656, 11710, 17, 'Para ativar a ajuda - Vá para o Nome de usuário no canto superior esquerdo> Configurações> Recursos> Ativar Modal de Ajuda');
INSERT INTO `lang_definitions` VALUES (94657, 11711, 17, 'Para habilitar a ajuda - Vá para o Nome de Usuário no canto superior direito> Configurações> Recursos> Habilitar Modal de Ajuda');
INSERT INTO `lang_definitions` VALUES (94658, 11712, 17, 'Para ativar apenas HTTPS, execute as alterações acima e reinicie o servidor Apache. Se você quiser configurar certificados do lado do cliente também, por favor configure-os na próxima seção');
INSERT INTO `lang_definitions` VALUES (94659, 11713, 17, 'Para habilitar o Portal do Paciente, vá para Administração> Portal> Habilitar Portal do Paciente no local na Versão 2, Habilitar Portal do Paciente Externo ou Habilitar Portal CMS');
