INSERT INTO `lang_definitions` VALUES (94662, 11717, 17, 'Para cumprir os requisitos de uso significativo e ajudar a rastrear seu uso, você pode marcar a caixa de seleção Resumo de cuidados enviados e a caixa de seleção Resumo de cuidados enviados eletronicamente, se apropriado');
INSERT INTO `lang_definitions` VALUES (94663, 11718, 17, 'Para excluir totalmente, clique em \'Salvar\'');
INSERT INTO `lang_definitions` VALUES (94664, 11719, 17, 'Para começar, você escolhe um dos dois botões de opção. \'Pesquisa de fatura\' ou \'Upload ERA\'');
INSERT INTO `lang_definitions` VALUES (94665, 11720, 17, 'Para ajudar a explorar os vários componentes da página Relatório, especialmente se você quiser usá-la como um manual de instruções, é sugerido que você reduza o tamanho do navegador para cobrir metade da janela de visualização, redimensione o pop-up de ajuda clicando e arrastando a parte inferior canto direito da janela pop-up. Abra outra instância do navegador e redimensione-a para cobrir a outra metade da janela de visualização, faça login no openEMR');
INSERT INTO `lang_definitions` VALUES (94666, 11721, 17, 'Para ajudar a se familiarizar com os vários componentes da página Dashboard, é sugerido que você reduza o tamanho do navegador para cobrir metade da janela de visualização, redimensione o pop-up de ajuda clicando e arrastando a parte inferior canto direito da janela pop-up. Abra outra instância do navegador e redimensione-a para cobrir a outra metade da janela de visualização, faça login no openEMR');
INSERT INTO `lang_definitions` VALUES (94667, 11722, 17, 'Para ajudar a simplificar as implementações, os modelos comumente usados foram harmonizados a partir de guias de implementação de CDA existentes e consolidados em um único guia de implementação - o Guia de Implementação C-CDA (IG) (07/2012)');
