INSERT INTO `lang_definitions` VALUES (94671, 11726, 17, 'Para vincular os problemas a um encontro, primeiro selecione o problema, ele será destacado em amarelo, logo clique em um ou mais encontros para vinculá-los, os encontros selecionados serão destacados em roxo');
