INSERT INTO `lang_definitions` VALUES (94679, 11734, 17, 'Para receber notificações de erro do serviço de mensagens diretas, um endereço de e-mail de notificação válido precisa ser inserido para o usuário nomeado em Administração> Globais> Conectores> usuário de notificação phiMail');
