INSERT INTO `lang_definitions` VALUES (95085, 12210, 17, 'Após uma pesquisa bem-sucedida, você verá uma lista de faturas. Você pode clicar em um dos números da fatura para abrir uma segunda janela, que é a página de entrada de dados para postagem manual. Você também pode clicar no nome de um paciente se quiser inserir uma nota que a equipe da recepção verá quando o paciente fizer check-in, e você pode selecionar faturas para aparecer nos extratos dos pacientes e imprimir esses extratos');
INSERT INTO `lang_definitions` VALUES (95086, 12211, 17, 'Ao clicar um número de fatura a janela postando\" manual\" se aparece. Aqui você pode mudar a data de vencimento e notas para a fatura, selecione a festa para quem você está postando, e seleciona foram recebidos os seguros para os quais tudo esperaram paymants. Importantemente, para cada código de faturamento pelo qual uma quantia foi cobrada, você pode entrar em pagamento e informação de ajuste.');
INSERT INTO `lang_definitions` VALUES (95087, 12212, 17, 'Ao clicar em um número de fatura, a \'janela de lançamento manual\' aparece. Aqui você pode alterar a data de vencimento e as notas da fatura, selecionar a parte para a qual está lançando e selecionar os seguros para os quais todos os pagamentos esperados foram recebidos. Mais importante ainda, para cada código de faturamento pelo qual um valor foi cobrado, você pode inserir informações de pagamento e ajuste');
INSERT INTO `lang_definitions` VALUES (95088, 12213, 17, 'Ao entrar na página, existem dois botões visíveis abaixo da barra de navegação');
INSERT INTO `lang_definitions` VALUES (95089, 12214, 17, 'Ao fazer login no openEMR, um pequeno ícone de envelope fica visível no canto superior direito. Mostra o número de mensagens pendentes e lembretes datados');
INSERT INTO `lang_definitions` VALUES (95090, 12215, 17, 'Ao atingir um ponto predeterminado, seja uma data ou valor, a regra irá disparar um ou mais eventos');
INSERT INTO `lang_definitions` VALUES (95091, 12216, 17, 'Ao o procurar é apresentado com uma lista de faturas. Você pode clicar aceso dos números de fatura abrir uma segunda janela que é a página de entrada de dados por manual postar. Você também pode fazer tique-taque em um nome paciente se você quiser entrar em uma nota que o pessoal de escritório dianteiro verá quando os cheques pacientes em, e você pode selecionar faturas para se aparecer em declarações pacientes e imprimir essas declarações.');
INSERT INTO `lang_definitions` VALUES (95092, 12217, 17, 'Ao selecionar uma lista para editar a página de edição com os valores da lista serão exibidos');
INSERT INTO `lang_definitions` VALUES (95093, 12218, 17, 'Após o registro bem-sucedido, você será levado a página de destino Gerenciar autenticação multifator');
