INSERT INTO `lang_definitions` VALUES (95453, 12632, 17, 'Vamos criar o teste que pode ser pedido denominado Ácido Úrico no Soro');
INSERT INTO `lang_definitions` VALUES (95454, 12634, 17, 'observámos o paciente acima identificado, na nossa clínica psiquiátrica ambulatoria. Gratos pela preferência.');
INSERT INTO `lang_definitions` VALUES (95455, 12635, 17, 'Tivemos alguns problemas ao conectar seu EHR aos servidores MedEx');
INSERT INTO `lang_definitions` VALUES (95456, 12640, 17, 'Estaremos baseando o painel de eletrólito no tronco principal ou Grupo (Química do Soro)');
INSERT INTO `lang_definitions` VALUES (95457, 12641, 17, 'Estaremos criando um pedido para três testes de glicose no sangue, TSH e vitamina D e agrupá-lo em um grupo personalizado chamado Testes de Mulher Bem e criar um local para inserir manualmente os resultados retornados');
INSERT INTO `lang_definitions` VALUES (95458, 12642, 17, 'Passaremos pelo processo de configuração do pedido de um único exame de sangue - Ácido Úrico no Soro');
INSERT INTO `lang_definitions` VALUES (95459, 12643, 17, 'Vamos agora criar o pedido, ou Ordem de Procedimento, chamado Painel de Eletrólito que pode ser visualizado como o galho frutífero em nossa árvore frutífera hipotética');
INSERT INTO `lang_definitions` VALUES (95460, 12644, 17, 'Iremos configurar o pedido para o painel de eletrólito que consiste em sódio sérico, potássio, cloreto e dióxido de carbono');
INSERT INTO `lang_definitions` VALUES (95461, 12645, 17, 'Começaremos com a unidade mais básica do módulo de Pedidos de Procedimento, para configurar um único pedido de teste de laboratório e a capacidade de registrar manualmente o resultado retornado');
INSERT INTO `lang_definitions` VALUES (95462, 12646, 17, 'Usaremos um resultado discreto para cada teste para manter os valores de resultado retornados');
INSERT INTO `lang_definitions` VALUES (95463, 12647, 17, 'Usaremos esta ramificação para conter todos os 9 painéis, aqui estaremos apenas criando o pedido que representa um painel, o Painel de Eletrólito');
