INSERT INTO `lang_definitions` VALUES (95509, 12699, 17, 'Quando um novo usuário é criado, o controle de acesso é concedido pelo administrador ou por um usuário com privilégios semelhantes, selecionando a quais grupos (AROs) um usuário pode pertencer');
INSERT INTO `lang_definitions` VALUES (95510, 12700, 17, 'Quando e com que frequência?');
INSERT INTO `lang_definitions` VALUES (95511, 12701, 17, 'Quando verificado, os dados demográficos abrirão em uma nova janela do quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (95512, 12702, 17, 'Quando verificado, a última equipe a atualizar o quadro será exibida no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (95513, 12703, 17, 'Quando marcada, as mensagens são processadas para pacientes com Escolha Demográfica do Paciente: \"Notificação Hipaa Recebida\" definida como \"Não Atribuída\" ou \"Sim\". Quando desmarcada, esta opção deve ser = \"SIM\" para processar o lembrete do paciente. Para pacientes com Escolha = \"Não\", os lembretes precisarão ser processados manualmente');
INSERT INTO `lang_definitions` VALUES (95514, 12704, 17, 'Quando verificado, o número de encontro do paciente será exibido no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (95515, 12705, 17, 'Quando verificado, a ID do paciente será exibida no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (95516, 12706, 17, 'Quando verificado, o motivo da visita será exibido no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (95517, 12707, 17, 'Ao lidar com informações de saúde protegidas (PHI) e informações de identificação pessoal (PII), é importante permitir que apenas usuários autorizados acessem os dados');
INSERT INTO `lang_definitions` VALUES (95518, 12708, 17, 'Quando terminar, clique em Enviar (abaixo) para aplicar suas escolhas');
