INSERT INTO `lang_definitions` VALUES (96526, 627, 18, 'Alternativamente, você pode optar por carregar um arquivo de remessa eletrônica (X12 835) que você tenha obtido de seu pagador ou clearinghouse. Você pode fazer isso selecionando primeiro a opção \'ERA upload\' na seção inicial \'Select Method\'. Isso traz a seção \'ERA Upload\'');
INSERT INTO `lang_definitions` VALUES (96527, 628, 18, 'Alternativamente, você pode utilizar a página de pesquisa para enviar uma remessa eletrônica (X12 835 arquivos) que você tenha obtido a partir do seu autor ou câmara de compensação. Você pode fazer isso clicando no botão Procurar e selecionar o arquivo para upload, e depois clique em Procurar para realizar o upload e mostrar as faturas correspondentes. Neste caso, os outros parâmetros mencionados acima não se aplicam e serão ignorados. Uploading salva o arquivo, mas não ainda processo seu conteúdo - que é feito separadamente, como descrito abaixo.');
INSERT INTO `lang_definitions` VALUES (96528, 629, 18, 'Embora o HCFA-1500 tenha sido originalmente desenvolvido para a apresentação de reivindicações do Medicare, acabou sendo aceito por todas as seguradoras comerciais / privadas para facilitar a padronização do processo de reivindicações');
