INSERT INTO `lang_definitions` VALUES (96578, 683, 18, 'Um conceito importante a ser compreendido é que, uma vez que a chave secreta entregue por meio do código QR é capturada pelo aplicativo autenticador, não há mais comunicação entre o aplicativo e o OpenEMR, cada um usará a hora atual do UNIX e sua cópia da chave secreta compartilhada específica do usuário para gerar o mesmo número único de 6 dígitos');
