INSERT INTO `lang_definitions` VALUES (97370, 1562, 18, 'Altere qualquer item disponível e, quando estiver pronto, clique em Enviar para revisão. As mudanças serão sinalizadas e a equipe notificada para revisar as mudanças antes de enviá-las ao gráfico. Durante o período de tempo antes que as alterações sejam revisadas, o botão Revisado mostrará Pendente e os dados do perfil ainda estão disponíveis para alterações. Ao acessar ao perfil no estado pendente, todas as edições anteriores aparecerão em azul e os valores do gráfico atual em vermelho. Você pode reverter qualquer edição para o valor do gráfico clicando naquele item vermelho (ou vice-versa), mas lembre-se de que quando você clica em Enviar para Revisão, os itens que preenchem os itens de campo são os que são enviados. O botão Reverter edições altera tudo de volta para os valores do gráfico e você pode fazer alterações a partir daí. Recapitulando: os itens em AZUL são edições do paciente com itens em VERMELHO sendo os valores originais antes de quaisquer edições');
