INSERT INTO `lang_definitions` VALUES (100468, 5086, 18, 'Cartão de identificação / fotos - exibirá qualquer cartão de identificação ou foto do paciente que tenha sido carregado nos Documentos> Informações do paciente> Cartão de identificação do paciente e pastas Fotografia do paciente');
