INSERT INTO `lang_definitions` VALUES (100646, 5276, 18, 'Da mesma forma, crie um item favorito personalizado para TSH (sequência 2, código de identificação WWT02, código padrão 30166-3) e vitamina D (sequência 3, código de identificação WWT03, código padrão 35365-6)');
INSERT INTO `lang_definitions` VALUES (100647, 5277, 18, 'Da mesma forma, crie um Resultado Discreto para TSH (Sequência - 2, Código de Identificação - WWT02R, Unidades Padrão - mU / L, intervalo Padrão - 0,4-4, deixe os Serviços de Acompanhamento em branco) e Vitamina D (Sequência - 3, Código de Identificação - WWT03R, unidades padrão - ng / mL, intervalo padrão - 0-20, deixe os serviços de acompanhamento em branco)');
INSERT INTO `lang_definitions` VALUES (100648, 5278, 18, 'Além disso, existem 2 caixas de seleção');
INSERT INTO `lang_definitions` VALUES (100649, 5279, 18, 'Além de criar uma Referência, o sistema também permite que você imprima um formulário de referência em branco que pode ser preenchido manualmente para gerar uma Referência');
INSERT INTO `lang_definitions` VALUES (100650, 5280, 18, 'Em qualquer caso, o estabelecimento de uma conexão, garantindo conformidade HIPAA, a segurança dos dados etc. exigirá codificação, cujo custo geralmente é suportado pelo laboratório. No entanto, eles só aprovarão se o volume de negócios justificar seu investimento');
