INSERT INTO `lang_definitions` VALUES (100658, 5291, 18, 'No openEMR, os relatórios de Registro de Continuidade de Cuidados (CCR) a serem gerados podem ser limitados a um intervalo de datas específico marcando a caixa de seleção Usar intervalo de datas e inserindo o intervalo de datas desejado');
INSERT INTO `lang_definitions` VALUES (100659, 5292, 18, 'A fim de cumprir os requisitos de uso significativo para entrada de pedido de provedor computadorizado (CPOE) para testes de laboratório e radiologia, este módulo precisa ser usado');
INSERT INTO `lang_definitions` VALUES (100660, 5293, 18, 'Para armazenar e recuperar adequadamente os resultados do teste e fazer novos pedidos, os testes / pedidos devem ser configurados de maneira hierárquica');
INSERT INTO `lang_definitions` VALUES (100661, 5294, 18, 'Para registrar os valores dos resultados retornados, você deve criar um Resultado Discreto separado (Nível 4) para cada um dos constituintes do painel, a fruta, como descendentes diretos deste ramo (Painel de Saúde Geral) (Nível 3). Exemplos dos resultados são CBC - Hemoglobina, CBC - Hematócrito, CMP - Sódio, CMP - Potássio, TSH etc.');
INSERT INTO `lang_definitions` VALUES (100662, 5295, 18, 'Para registrar seu dispositivo, por favor forneça sua senha de login do OpenEMR');
INSERT INTO `lang_definitions` VALUES (100663, 5296, 18, 'Para enviar Registro de Continuidade de Cuidados (CCR) e / ou Documento de Continuidade de Cuidados (CCD), opcionalmente, marque phiMail Permitir CCD Send e / ou phiMail Permitir CCR Send para habilitar o recurso de transmissão para esses tipos de dados');
INSERT INTO `lang_definitions` VALUES (100664, 5297, 18, 'No nosso caso, escolheremos o laboratório local que foi configurado anteriormente');
INSERT INTO `lang_definitions` VALUES (100665, 5298, 18, 'No nosso caso, vamos deixá-lo como Não atribuído');
INSERT INTO `lang_definitions` VALUES (100666, 5300, 18, 'No modo Retrato, determina a altura do envelope ao longo do eixo y em mm');
INSERT INTO `lang_definitions` VALUES (100667, 5301, 18, 'No modo Retrato, determina a largura do envelope ao longo do eixo x em mm');
INSERT INTO `lang_definitions` VALUES (100668, 5302, 18, 'no olho direito');
INSERT INTO `lang_definitions` VALUES (100669, 5303, 18, 'Em suma, os pedidos eletrônicos podem ser feitos, envolve uma quantidade significativa de testes e customização para ser certificado pelo laboratório, geralmente por meio de um terceiro e só pode acontecer se o laboratório concordar em dar luz verde ao projeto');
INSERT INTO `lang_definitions` VALUES (100670, 5304, 18, 'Na seção \'Postar item\' exibida na parte superior, você pode inserir uma fonte (por exemplo, número do cheque), data de pagamento e valor do cheque. A razão para a fonte e a data de pagamento é para que você não precise inseri-las repetidamente para cada reivindicação. O valor que você inserir será reduzido para cada fatura que receber parte do pagamento e, com sorte, terminará em zero quando você terminar');
INSERT INTO `lang_definitions` VALUES (100671, 5305, 18, 'No exemplo acima, um pedido para um único teste foi criado, ou seja, ácido úrico sérico');
INSERT INTO `lang_definitions` VALUES (100672, 5306, 18, 'Na instalação padrão, clique em Adicionar para abrir a página pop-up Adicionar / Editar Problema');
INSERT INTO `lang_definitions` VALUES (100673, 5307, 18, 'Nas palavras do paciente');
INSERT INTO `lang_definitions` VALUES (100674, 5308, 18, 'Na segunda fase do uso significativo, o CCD, mas não o CCR, foi incluído como parte do padrão para troca de documentos clínicos');
INSERT INTO `lang_definitions` VALUES (100675, 5309, 18, 'Neste caso, o grupo de favoritos personalizados será chamado de Laboratórios de pré-operatório e os dois painéis reconhecidos serão descendentes diretos, cada um em um nível de item favorito personalizado denominado CBC e Painel renal, respectivamente');
INSERT INTO `lang_definitions` VALUES (100676, 5310, 18, 'Neste caso, você criará um Pedido de Procedimento, o ramo frutífero denominado Painel Geral de Saúde (Nível 3)');
