INSERT INTO `lang_definitions` VALUES (101039, 5711, 18, 'Também é necessário listar um código CID10 para que o problema seja listado no Relatório de Continuidade de Cuidados (CCR) e no Documento de Continuidade de Cuidados (CCD)');
INSERT INTO `lang_definitions` VALUES (101040, 5712, 18, 'Está dividido em duas seções');
INSERT INTO `lang_definitions` VALUES (101041, 5713, 18, 'É essencial que você leia as primeiras quatro seções para compreender os princípios subjacentes');
INSERT INTO `lang_definitions` VALUES (101042, 5714, 18, 'É muito mais fácil e intuitivo fazer grandes alterações e reorganizar os dados na planilha antes de começar a inserir os dados no openEMR');
INSERT INTO `lang_definitions` VALUES (101043, 5715, 18, 'É importante perceber que isso gerencia o MFA para o usuário conectado');
INSERT INTO `lang_definitions` VALUES (101044, 5716, 18, 'É importante compreender a função destes dois ícones dado que todos os passos subsequentes necessários para configurar correctamente a hierarquia irão depender da utilização correcta destes dois ícones');
INSERT INTO `lang_definitions` VALUES (101045, 5717, 18, 'Destina-se a incluir apenas as informações que são críticas para efetivamente continuar o cuidado');
INSERT INTO `lang_definitions` VALUES (101046, 5718, 18, 'É emitido para prestadores de cuidados de saúde nos Estados Unidos pelos Centros de Serviços Medicare e Medicaid (CMS)');
INSERT INTO `lang_definitions` VALUES (101047, 5719, 18, 'Não é necessário para o laboratório local, em vez disso, você pode usar qualquer número único arbitrário');
INSERT INTO `lang_definitions` VALUES (101048, 5720, 18, 'Não é necessário preencher os códigos de diagnóstico padrão, pois os códigos ICD10 podem ser inseridos no momento do pedido real do teste');
INSERT INTO `lang_definitions` VALUES (101049, 5721, 18, 'Não é enviado com a reclamação');
INSERT INTO `lang_definitions` VALUES (101050, 5722, 18, 'Não é incomum solicitar vários exames de sangue juntos, agrupá-los como um painel de exames facilita esse processo');
INSERT INTO `lang_definitions` VALUES (101051, 5724, 18, 'É o formulário de reclamação em papel básico prescrito por muitos pagadores para reclamações submetidas por médicos e práticas individuais, enfermeiras e profissionais, incluindo terapeutas, quiropráticos e clínicas ambulatoriais e, em alguns casos, para serviços de ambulância');
INSERT INTO `lang_definitions` VALUES (101052, 5725, 18, 'É usado para vincular problemas a encontros e também é usado para ver quais encontros estão associados a um determinado problema');
INSERT INTO `lang_definitions` VALUES (101053, 5726, 18, 'É útil praticar em um local de teste para se familiarizar com o processo antes de fazer isso no aplicativo openEMR de produção');
INSERT INTO `lang_definitions` VALUES (101054, 5727, 18, 'Permite pesquisar por códigos de diagnóstico ICD 9 e ICD 10 e CPT4 e HCPCS');
INSERT INTO `lang_definitions` VALUES (101055, 5728, 18, 'Ele permite que você envie mensagens e lembretes datados aos membros da equipe, adicione o paciente à lista de re call e envie mensagens de texto SMS para os pacientes');
INSERT INTO `lang_definitions` VALUES (101056, 5729, 18, 'Ele serve como uma ponte necessária para um ambiente diferente, muitas vezes com novos médicos que não sabem nada sobre o paciente, permitindo que o próximo provedor facilmente');
INSERT INTO `lang_definitions` VALUES (101057, 5731, 18, 'Portanto, é lógico que você não pode criar uma contra-referência por si só');
INSERT INTO `lang_definitions` VALUES (101058, 5732, 18, 'Ele usa um padrão aberto e, portanto, disponível em vários fabricantes');
INSERT INTO `lang_definitions` VALUES (101059, 5733, 18, 'Ele usa a função hash HMAC-SHA256 para gerar uma chave privada exclusiva para a conta');
INSERT INTO `lang_definitions` VALUES (101060, 5734, 18, 'Ele usa essa chave privada para assinar o desafio e envia a resposta de volta ao aplicativo');
INSERT INTO `lang_definitions` VALUES (101061, 5735, 18, 'Será exibido no resumo da visita');
INSERT INTO `lang_definitions` VALUES (101062, 5736, 18, 'Isso abrirá o formulário pop-up Inserir detalhes');
INSERT INTO `lang_definitions` VALUES (101063, 5737, 18, 'Isso abrirá o pop-up do localizador de vários pacientes');
INSERT INTO `lang_definitions` VALUES (101064, 5738, 18, 'Ele exibirá o pop-up de exibição justificado. Tem uma caixa de pesquisa que permite pesquisar um código ICD. Ele também exibirá os 10 códigos ICD mais comumente usados. Você pode selecionar qualquer um ou todos os códigos marcando a caixa de seleção J (justificar) e pressionando atualizar');
INSERT INTO `lang_definitions` VALUES (101065, 5739, 18, 'Terá um valor de 2 na coluna nível indicando que é um sucessor ou filho na primeira linha acima tendo um valor nível 1 que neste caso é Química do Soro');
INSERT INTO `lang_definitions` VALUES (101066, 5740, 18, 'Terá duas seções - a Seção de Problemas e a Seção de Encontros');
INSERT INTO `lang_definitions` VALUES (101067, 5741, 18, 'Isso ajudará mais tarde na solução de problemas que podem surgir com a configuração do módulo de Pedidos de Procedimento');
INSERT INTO `lang_definitions` VALUES (101068, 5742, 18, 'Irá abrir a seção Criar Nova Mensagem');
INSERT INTO `lang_definitions` VALUES (101069, 5743, 18, 'Isso o levará para a página de inscrição do MedEx');
INSERT INTO `lang_definitions` VALUES (101070, 5744, 18, 'Ele então aparecerá no widget Alergias no Painel do Paciente, bem como em alergias na página Problemas');
INSERT INTO `lang_definitions` VALUES (101071, 5745, 18, 'Ele então aparecerá no widget Medicamentos no Painel do Paciente, bem como em Medicamentos na página de Problemas');
