INSERT INTO `lang_definitions` VALUES (103136, 8068, 18, 'Preste atenção ao \"\"Feito com \"\" caixas. Depois que os seguros são marcadas completa, então vamos começar a pedir o doente para o pagamento do saldo remanescente, se você deixar de marcar todos os seguros, em seguida, completar o valor restante não será coletado! Além disso, se há um equilíbrio que o paciente deve pagar, em seguida, defina a data de vencimento de forma adequada, como isso vai afetar o idioma que aparece sobre as declarações do paciente.');
INSERT INTO `lang_definitions` VALUES (103137, 8069, 18, 'Preste atenção às caixas de seleção \"Concluído com\". Depois que os seguros forem marcados como concluídos, então começaremos a solicitar ao paciente o pagamento do saldo remanescente; se você deixar de marcar todos os seguros como concluídos, então o valor restante não será cobrado! Além disso, se houver um saldo que o paciente deve pagar, então defina a data de vencimento de forma adequada, pois isso afetará a linguagem que aparece nas declarações do paciente');
