INSERT INTO `lang_definitions` VALUES (105712, 10955, 18, 'A janela \'Editar\' é dividida em duas colunas, \'Ativo\' e \'Inativo\'. Os grupos (AROs) listados na coluna ativa são essos grupos aos quais o usuário pertence a');
INSERT INTO `lang_definitions` VALUES (105713, 10956, 18, 'A seção \'Selecionar Códigos\' agora terá todos os códigos CPT e ICD que você inseriu agrupados nas categorias que você decidiu');
INSERT INTO `lang_definitions` VALUES (105714, 10957, 18, 'A tecla * Tab * cria cada entrada');
INSERT INTO `lang_definitions` VALUES (105715, 10958, 18, 'O Formulário de Reivindicação 1500 também pode ser usado para relatar dados de encontros com pacientes para agências federais, estaduais e / ou outras agências de saúde pública');
INSERT INTO `lang_definitions` VALUES (105716, 10959, 18, 'O 837P (Profissional) é o formato padrão usado por profissionais de saúde e fornecedores para transmitir eletronicamente alegações de saúde');
INSERT INTO `lang_definitions` VALUES (105717, 10960, 18, 'A capacidade de vincular problemas individuais a encontros com pacientes permitirá que o usuário determine rapidamente o resultado do problema ao longo do tempo');
INSERT INTO `lang_definitions` VALUES (105718, 10961, 18, 'A declaração acima falhou');
INSERT INTO `lang_definitions` VALUES (105719, 10962, 18, 'A página ACL de duas seções');
INSERT INTO `lang_definitions` VALUES (105720, 10963, 18, 'Os valores reais que serão exibidos devem existir no banco de dados');
INSERT INTO `lang_definitions` VALUES (105721, 10964, 18, 'Os testes ou procedimentos reais que podem ser pesquisados e solicitados são destacados em amarelo');
INSERT INTO `lang_definitions` VALUES (105722, 10965, 18, 'O ícone Adicionar é usado para configurar um nível que será um descendente direto deste nível');
INSERT INTO `lang_definitions` VALUES (105723, 10966, 18, 'A vantagem de integrar os resultados ao prontuário do paciente como dados estruturados é a capacidade de manipulá-los para ver as tendências em um local conveniente, para traçar gráficos com os dados e usá-los na análise de dados');
INSERT INTO `lang_definitions` VALUES (105724, 10967, 18, 'A vantagem de digitalizar os resultados no gráfico é a simplicidade - nenhuma configuração é necessária, a não ser definir um diretório / pasta no prontuário do paciente em Documentos onde o resultado será armazenado. Sendo dados não estruturados, eles não têm as vantagens acima e não atenderão aos critérios de uso significativo para entrada de pedido do provedor computadorizado (CPOE)');
INSERT INTO `lang_definitions` VALUES (105725, 10968, 18, 'A solução Allscripts integra o site Allscripts ePrescribe com openEMR');
INSERT INTO `lang_definitions` VALUES (105726, 10969, 18, 'A American Medical Association definiu 9 painéis que podem ser solicitados. Cada painel contém vários testes agrupados');
INSERT INTO `lang_definitions` VALUES (105727, 10970, 18, 'O valor será exibido na coluna Pagamento ou Ajuste, conforme o caso');
INSERT INTO `lang_definitions` VALUES (105728, 10971, 18, 'O certificado do servidor Apache SSL e a chave pública');
INSERT INTO `lang_definitions` VALUES (105729, 10972, 18, 'O aplicativo gera um desafio - um número aleatório e o passa para a chave USB junto com o nonce e a soma de verificação armazenados no aplicativo');
INSERT INTO `lang_definitions` VALUES (105730, 10973, 18, 'O aplicativo então usa a chave pública que o dispositivo USB enviou no registro para verificar a resposta');
INSERT INTO `lang_definitions` VALUES (105731, 10974, 18, 'As mudanças no status da consulta e as criações de encontros são gerenciadas através do Patient Tracker');
INSERT INTO `lang_definitions` VALUES (105732, 10975, 18, 'O nome Autentificação ou chave API para a conta selecionada. Nome de autenticação para Authorize.Net e segredo API para Stripe');
INSERT INTO `lang_definitions` VALUES (105733, 10976, 18, 'A coluna Saldo ficaria vazia');
INSERT INTO `lang_definitions` VALUES (105734, 10977, 18, 'O objetivo básico do aplicativo autenticador é gerar um código de 20 bytes (160 bits) codificado em base32 usando uma função hash segura, SHA-1, e é chamado de HMAC-SHA1 (código de autenticação de mensagem baseado em hash)');
INSERT INTO `lang_definitions` VALUES (105735, 10978, 18, 'A base para o CCR é um Formulário de Referência de Cuidados ao Paciente desenvolvido pelo Departamento de Saúde Pública de Massachusetts');
INSERT INTO `lang_definitions` VALUES (105736, 10979, 18, 'A coluna Data de cobrança / pagador mostrará a data em que o pagamento do item de linha foi recebido e o nome do pagador - seguro ou paciente');
INSERT INTO `lang_definitions` VALUES (105737, 10980, 18, 'A coluna Data de cobrança / pagador mostrará a data em que o item de linha foi cobrado e o pagador - seguro ou paciente');
INSERT INTO `lang_definitions` VALUES (105738, 10981, 18, 'O corpo contém os dados clínicos que podem ser estruturados e organizados como uma ou mais seções ou podem ser um blob não estruturado de dados');
INSERT INTO `lang_definitions` VALUES (105739, 10982, 18, 'As caixas Body Site, Administer Via e Laterality podem ser deixadas como Unassigned');
INSERT INTO `lang_definitions` VALUES (105740, 10983, 18, 'O grupo inferior consiste nos Copays');
INSERT INTO `lang_definitions` VALUES (105741, 10984, 18, 'A coluna Categoria será Custom Top Group e será destacada em rosa');
INSERT INTO `lang_definitions` VALUES (105742, 10985, 18, 'A coluna Categoria mostrará Pedido, indicando que é um pedido');
INSERT INTO `lang_definitions` VALUES (105743, 10986, 18, 'A categoria será o resultado');
INSERT INTO `lang_definitions` VALUES (105744, 10987, 18, 'O CDA é um documento de texto simples que é codificado usando a Extensible Markup Language (XML) e contém um cabeçalho e corpo');
INSERT INTO `lang_definitions` VALUES (105745, 10988, 18, 'O certificado da Autoridade de Certificação');
INSERT INTO `lang_definitions` VALUES (105746, 10989, 18, 'A coluna Cobrança ficaria em branco');
INSERT INTO `lang_definitions` VALUES (105747, 10990, 18, 'A cobrança será o valor real sendo cobrado para cada item de linha');
INSERT INTO `lang_definitions` VALUES (105748, 10991, 18, 'A alegação de arquivo:');
INSERT INTO `lang_definitions` VALUES (105749, 10992, 18, 'O formulário CMS 1500 possui 33 caixas e é dividido em duas seções');
INSERT INTO `lang_definitions` VALUES (105750, 10993, 18, 'A coluna Código deve ter 905, o código de identificação específico do fornecedor que foi inserido anteriormente');
INSERT INTO `lang_definitions` VALUES (105751, 10994, 18, 'A coluna Código ficará vazia porque os itens listados como um Grupo não são usados no relatório real de resultados e, portanto, não têm um número de código distinto');
INSERT INTO `lang_definitions` VALUES (105752, 10995, 18, 'O Código será R905, o valor do Código de Identificação que foi inserido para o Resultado Discreto');
INSERT INTO `lang_definitions` VALUES (105753, 10996, 18, 'O código que você digitou não era válido');
INSERT INTO `lang_definitions` VALUES (105754, 10997, 18, 'O pacote SNOMED da extensão US testada compatível já foi instalado');
INSERT INTO `lang_definitions` VALUES (105755, 10998, 18, 'A célula de Contatos tem vários bits de informações de contato, como números de telefone, e-mail, etc.');
INSERT INTO `lang_definitions` VALUES (105756, 10999, 18, 'O Documento de Continuidade de Cuidados (CCD) e o Registro de Continuidade de Cuidados (CCR) foram ambos selecionados como formatos aceitáveis para extrair informações para resumos de cuidados clínicos como parte do Estágio 1 de Uso Significativo');
INSERT INTO `lang_definitions` VALUES (105757, 11000, 18, 'O Continuity of Care Record (CCR) foi desenvolvido em conjunto pela ASTM International - uma organização que está envolvida no desenvolvimento e entrega de consenso voluntário, a Massachusetts Medical Society (MMS), a Health Information Management and Systems Society (HIMSS), a American Academy of Family Physicians (AAFP) e American Academy of Pediatrics');
INSERT INTO `lang_definitions` VALUES (105758, 11001, 18, 'O Registro de Continuidade de Cuidados (CCR) é o registro clínico do estado de saúde atual e histórico do paciente');
INSERT INTO `lang_definitions` VALUES (105759, 11002, 18, 'O conjunto de dados principal consiste em');
INSERT INTO `lang_definitions` VALUES (105760, 11003, 18, 'A chave privada correspondente');
INSERT INTO `lang_definitions` VALUES (105761, 11004, 18, 'O relatório criado pode conter muitas ou poucas informações com base na necessidade');
INSERT INTO `lang_definitions` VALUES (105762, 11005, 18, 'O método de autenticação atual para a seção de usuário conectado agora apresentará os métodos ativados');
INSERT INTO `lang_definitions` VALUES (105763, 11006, 18, 'O método de autenticação atual lista todos os métodos que estão ativos');
INSERT INTO `lang_definitions` VALUES (105764, 11007, 18, 'A folha de honorários personalizada pode ser usada. Se e quando você encontrar um código que não existe na seção \"Selecionar códigos\" personalizada, você pode usar sempre a seção \"Pesquisar códigos adicionais\"');
INSERT INTO `lang_definitions` VALUES (105765, 11008, 18, 'O nível de item favorito personalizado deve ser descendente direto ou filho do grupo favorito personalizado relevante');
INSERT INTO `lang_definitions` VALUES (105766, 11009, 18, 'O agrupamento personalizado também te permiterá agrupar dois painéis de testes reconhecidos em um grupo personalizado e, assim, organizá-los juntos, por exemplo, um grupo personalizado de Laboratórios Preop pode conter dois painéis, CBC e Painel Renal');
INSERT INTO `lang_definitions` VALUES (105767, 11010, 18, 'O painel é o local central para acesso conveniente ao prontuário médico do paciente');
INSERT INTO `lang_definitions` VALUES (105768, 11011, 18, 'A página do painel é dividida em três seções');
INSERT INTO `lang_definitions` VALUES (105769, 11012, 18, 'O teste de integridade de dados falhou para este formulário');
INSERT INTO `lang_definitions` VALUES (105770, 11013, 18, 'A seção de dados da página do painel lista todos os itens pertinentes relacionados a um paciente');
INSERT INTO `lang_definitions` VALUES (105771, 11014, 18, 'O lembrete com data começará a aparecer 5 dias antes da data do lembrete em Lembretes com data');
INSERT INTO `lang_definitions` VALUES (105772, 11015, 18, 'O tipo de código padrão a ser pesquisado na Folha de Taxas');
INSERT INTO `lang_definitions` VALUES (105773, 11016, 18, 'A folha de taxas padrão pode ser modificada e personalizada para torná-la mais útil');
INSERT INTO `lang_definitions` VALUES (105774, 11017, 18, 'A folha de taxas padrão é dividida em várias seções e é projetada para ser preenchida de cima para baixo com o botão Salvar no final');
INSERT INTO `lang_definitions` VALUES (105775, 11018, 18, 'O formulário padrão pode ser personalizado editando-o em Administração> Layouts');
INSERT INTO `lang_definitions` VALUES (105776, 11019, 18, 'O padrão tem dois botões que são definidos para \'Novo paciente\' e \'Estabelecido\' paciente');
INSERT INTO `lang_definitions` VALUES (105777, 11020, 18, 'A instalação padrão tem seis grupos - Contabilidade, Administradores, Clínicos, Login de emergência, Front Office e Médicos');
INSERT INTO `lang_definitions` VALUES (105778, 11021, 18, 'A instalação padrão possui os seguintes itens');
INSERT INTO `lang_definitions` VALUES (105779, 11022, 18, 'A instalação padrão lista 5 tipos de problemas que podem ser documentados');
INSERT INTO `lang_definitions` VALUES (105780, 11023, 18, 'A instalação padrão não fará a ligação automaticamente');
INSERT INTO `lang_definitions` VALUES (105781, 11024, 18, 'O padrão é \'Padrão\' geralmente usado para refletir as taxas cobradas para cobrança de seguro. Você pode ter um valor diferente cobrado para pagamento com cartão de crédito e pagamento em dinheiro');
INSERT INTO `lang_definitions` VALUES (105782, 11025, 18, 'O padrão é Normal, ou seja, é visível para todos. Selecionar Alta irá restringi-lo a usuários pertencentes aos grupos de Médicos e Administradores por padrão');
INSERT INTO `lang_definitions` VALUES (105783, 11026, 18, 'O tipo de problema padrão é definido como Problema');
INSERT INTO `lang_definitions` VALUES (105784, 11027, 18, 'O centro de mensagens padrão é dividido em três seções - Mensagens, Lembretes e Recalls');
INSERT INTO `lang_definitions` VALUES (105785, 11028, 18, 'Os valores padrão para os provedores de renderização podem ser definidos');
INSERT INTO `lang_definitions` VALUES (105786, 11029, 18, 'o código de negação é');
INSERT INTO `lang_definitions` VALUES (105787, 11030, 18, 'o código do grupo de negação é');
INSERT INTO `lang_definitions` VALUES (105788, 11031, 18, 'A coluna Descrição exibe a breve descrição que foi inserida, testes de química de soro');
INSERT INTO `lang_definitions` VALUES (105789, 11032, 18, 'A coluna Descrição refletirá o valor da descrição que foi inserido anteriormente');
INSERT INTO `lang_definitions` VALUES (105790, 11033, 18, 'A descrição deve dizer resultado de ácido úrico no soro');
INSERT INTO `lang_definitions` VALUES (105791, 11034, 18, 'A descrição irá detalhar o tipo de pagamento ou ajuste - dinheiro, cheque, eletrônico, etc.');
INSERT INTO `lang_definitions` VALUES (105792, 11035, 18, 'O formulário de destino foi fechado');
INSERT INTO `lang_definitions` VALUES (105793, 11037, 18, 'O formulário de destino foi fechado, não posso agir em sua seleção.');
INSERT INTO `lang_definitions` VALUES (105794, 11038, 18, 'A diferença entre os dois é que para um painel de testes que são ordenados juntos, os testes individuais são representados apenas por Resultado Discreto e esses testes não podem ser pedidos separadamente, a menos que também tenham sido configurados como testes individuais');
INSERT INTO `lang_definitions` VALUES (105795, 11039, 18, 'O nível de resultados discretos deve ser descendente direto ou filho de um nível de ordem de procedimento para a exibição adequada dos resultados');
INSERT INTO `lang_definitions` VALUES (105796, 11040, 18, 'Os resultados discretos para cada painel conterão os nomes dos testes individuais para conter os valores dos resultados retornados - WBC, hemoglobina, plaquetas, sódio, potássio, etc.');
INSERT INTO `lang_definitions` VALUES (105797, 11041, 18, 'A janela de exibição pode ser redimensionada clicando e arrastando o canto inferior direito da janela');
INSERT INTO `lang_definitions` VALUES (105798, 11042, 18, 'A opção Cada Compromisso permitirá um novo encontro independentemente da visita no mesmo dia');
INSERT INTO `lang_definitions` VALUES (105799, 11043, 18, 'O botão Encounter Preview é útil para mostrar formulários de layout de tipo de encontro como vistos ao usar o formulário em um encontro. Observe que este recurso só é útil para mostrar formulários de encontro e não exibirá formulários de sistema como dados demográficos');
INSERT INTO `lang_definitions` VALUES (105800, 11044, 18, 'A seção de encontros exibirá a data do encontro, bem como a apresentação da reclamação');
INSERT INTO `lang_definitions` VALUES (105801, 11045, 18, 'O resultado final foi uma coleção confusa de documentos contendo informações ambíguas e / ou conflitantes');
INSERT INTO `lang_definitions` VALUES (105802, 11046, 18, 'A caixa pop-up Inserir detalhes abrirá no modo Adicionar');
INSERT INTO `lang_definitions` VALUES (105803, 11047, 18, 'O pop-up Inserir detalhes do provedor ficará visível');
INSERT INTO `lang_definitions` VALUES (105804, 11048, 18, 'A coleção inteira de ACOs forma a Lista de Controle de Acesso (ACL)');
INSERT INTO `lang_definitions` VALUES (105805, 11049, 18, 'A entidade para um item favorito personalizado é a entidade escolhida para o grupo de favoritos personalizados e não pode ser alterada');
INSERT INTO `lang_definitions` VALUES (105806, 11050, 18, 'A entidade que realiza este procedimento');
INSERT INTO `lang_definitions` VALUES (105807, 11051, 18, 'As entradas contêm dados usados para processamento posterior do computador');
INSERT INTO `lang_definitions` VALUES (105808, 11052, 18, 'As entradas destacadas em amarelo podem ser solicitadas como um teste ou procedimento, aquelas destacadas em rosa podem ser solicitadas como um grupo personalizado');
INSERT INTO `lang_definitions` VALUES (105809, 11053, 18, 'O EP, hospital elegível ou CAH que recebe um paciente de outro ambiente de cuidados ou prestador de cuidados ou acredita que um encontro é relevante deve realizar reconciliação de medicamentos');
INSERT INTO `lang_definitions` VALUES (105810, 11054, 18, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento (Medida A)');
INSERT INTO `lang_definitions` VALUES (105811, 11055, 18, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento (Medida B)');
INSERT INTO `lang_definitions` VALUES (105812, 11056, 18, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento');
INSERT INTO `lang_definitions` VALUES (105813, 11057, 18, 'O evento (s) foram aprovados.');
INSERT INTO `lang_definitions` VALUES (105814, 11058, 18, 'O evento (s) foram escondidos.');
INSERT INTO `lang_definitions` VALUES (105815, 11059, 18, 'Os dados exportados aparece na área de texto abaixo. Você pode copiar e colar as informações em um e-mail ou para qualquer outro destino desejado.');
INSERT INTO `lang_definitions` VALUES (105816, 11060, 18, 'Os dados exportados aparecem na área de texto abaixo. Você pode copiar e colar isso em um e-mail ou em qualquer outro destino desejado (ou) baixar o link abaixo');
INSERT INTO `lang_definitions` VALUES (105817, 11061, 18, 'Os dados exportados aparece na área de texto abaixo. Você pode copiar e colar as informações em um e-mail ou para qualquer outro destino desejado.');
INSERT INTO `lang_definitions` VALUES (105818, 11062, 18, 'Os dados exportados aparecem na área de texto abaixo. Você pode copiar e colar isto em um e-mail ou em qualquer outro destino desejado. {{MARQUE PARA DELEÇÃO DURANTE A PRÓXIMA CONSTRUÇÃO DA TRADUÇÃO}}');
INSERT INTO `lang_definitions` VALUES (105819, 11063, 18, 'Os recursos de uma instalação habilitada para MedEx são explicados neste vídeo');
INSERT INTO `lang_definitions` VALUES (105820, 11065, 18, 'O arquivo não pôde ser salvo no CouchDB');
INSERT INTO `lang_definitions` VALUES (105821, 11066, 18, 'O arquivo não pode ser renomear com sucesso, esse erro geralmente está relacionado a problemas de permissões no sistema de armazenamento');
INSERT INTO `lang_definitions` VALUES (105822, 11067, 18, 'O arquivo não pôde ser armazenado com sucesso, este erro geralmente está relacionado a problemas de permissões no sistema de armazenamento');
INSERT INTO `lang_definitions` VALUES (105823, 11068, 18, 'A seção de filtro pode ser escondida ou revelada clicando na ponta da seta no canto inferior direito');
INSERT INTO `lang_definitions` VALUES (105824, 11069, 18, 'Os resultados filtrados aparecerão na seção abaixo deles');
INSERT INTO `lang_definitions` VALUES (105825, 11071, 18, 'O primeiro gráfico (\"alvo\") é aquele considerado o mais completo e preciso. As seções demográficas, históricas e de seguro para este serão mantidas.');
INSERT INTO `lang_definitions` VALUES (105826, 11072, 18, 'A primeira coluna contém o nome do Grupo / Categoria que será exibido no botão');
INSERT INTO `lang_definitions` VALUES (105827, 11073, 18, 'A primeira coluna é o nome que você deu a esta entrada, ou seja, Química do Soro. Uma barra vertical precederá o nome real. Isso indica que não há descendentes ou filhos para esta entrada');
INSERT INTO `lang_definitions` VALUES (105828, 11074, 18, 'As primeiras quatro seções lidam com a criação de ordens de procedimento de uma maneira estruturada para facilitar a ordem de testes e inserir os resultados retornados manualmente');
INSERT INTO `lang_definitions` VALUES (105829, 11075, 18, 'A primeira linha mostrará a data do encontro e o motivo, bem como o provedor para esse encontro');
INSERT INTO `lang_definitions` VALUES (105830, 11076, 18, 'A primeira seção permite que você vincule esta mensagem a um paciente, se desejar');
INSERT INTO `lang_definitions` VALUES (105831, 11077, 18, 'O primeiro segmento em cada mensagem HL7 é sempre o cabeçalho da mensagem, um segmento que transmite os metadados da mensagem como quem a enviou e quando. O cabeçalho da mensagem é indicado nas três primeiras letras do segmento como MSH');
INSERT INTO `lang_definitions` VALUES (105832, 11078, 18, 'O primeiro passo é se inscrever para uma conta de produção de mensagens diretas com EMR Direct, registrando-se em seu site');
INSERT INTO `lang_definitions` VALUES (105833, 11079, 18, 'A primeira etapa é fazer o download da versão SNOMED CT. O acesso ao SNOMED CT é fornecido pela IHTSDO e seus países membros. Para mais informações, veja');
INSERT INTO `lang_definitions` VALUES (105834, 11080, 18, 'O primeiro passo é fazer o download da versão VALUESET. O acesso ao VALUESET é fornecido pela NLM. Apenas o conjunto de valores para Profissionais Elegíveis precisa ser baixado e deve ser baixado no formato XML da coluna Sorted By CMS ID. Para obter mais detalhes, veja o link abaixo');
INSERT INTO `lang_definitions` VALUES (105835, 11081, 18, 'A primeira etapa é abrir uma conta no site do Unified Medical Language System');
INSERT INTO `lang_definitions` VALUES (105836, 11082, 18, 'A primeira etapa é planejar o que a seção \'Selecionar Códigos\' da sua Folha de Taxas deve exibir');
INSERT INTO `lang_definitions` VALUES (105837, 11083, 18, 'A primeira etapa é selecionar um tipo de transação');
INSERT INTO `lang_definitions` VALUES (105838, 11084, 18, 'A primeira etapa seria criar uma entrada de nível superior. Faça isso clicando no botão nível superior Adicionar');
INSERT INTO `lang_definitions` VALUES (105839, 11085, 18, 'A primeira guia é a guia de referência que constitui a referência que está sendo feita');
INSERT INTO `lang_definitions` VALUES (105840, 11086, 18, 'Os primeiros dois números na primeira e segunda colunas serão usados para determinar a ordem de classificação dos botões e das listas que estão presentes no pop-up');
INSERT INTO `lang_definitions` VALUES (105841, 11087, 18, 'O calendário de eventos a seguir foi adicionado:');
INSERT INTO `lang_definitions` VALUES (105842, 11088, 18, 'O calendário de eventos que se segue foi modifed:');
INSERT INTO `lang_definitions` VALUES (105843, 11089, 18, 'As seguintes categorias serão removidas da sua lista de categorias');
INSERT INTO `lang_definitions` VALUES (105844, 11090, 18, 'O seguinte lançamento do banco de dados está instalada atualmente');
INSERT INTO `lang_definitions` VALUES (105845, 11091, 18, 'Os seguintes documentos foram anexados a esta mensagem direta:');
INSERT INTO `lang_definitions` VALUES (105846, 11092, 18, 'O seguinte arquivo EDI falhou ao salvar para o arquivo');
INSERT INTO `lang_definitions` VALUES (105847, 11093, 18, 'O seguinte arquivo EDI foi carregado');
INSERT INTO `lang_definitions` VALUES (105848, 11094, 18, 'O seguinte upload de arquivo EDI falhou ao abrir');
INSERT INTO `lang_definitions` VALUES (105849, 11095, 18, 'O seguinte usuário de login de emergência esta ativado:');
INSERT INTO `lang_definitions` VALUES (105850, 11096, 18, 'Os seguintes erros ocorreram');
INSERT INTO `lang_definitions` VALUES (105851, 11097, 18, 'O campo a seguir possui um valor inválido');
INSERT INTO `lang_definitions` VALUES (105852, 11098, 18, 'Os seguintes campos estão vazios');
INSERT INTO `lang_definitions` VALUES (105853, 11099, 18, 'Os seguintes campos são obrigatórios');
INSERT INTO `lang_definitions` VALUES (105854, 11100, 18, 'Os seguintes campos devem ser preenchidos para enviar um pedido');
INSERT INTO `lang_definitions` VALUES (105855, 11101, 18, 'Os seguintes campos devem ser preenchidos para enviar o pedido');
INSERT INTO `lang_definitions` VALUES (105856, 11102, 18, 'Os seguintes idiomas de lançamento internacional do Snomed são suportados');
INSERT INTO `lang_definitions` VALUES (105857, 11104, 18, 'O seguinte ocorreu');
INSERT INTO `lang_definitions` VALUES (105858, 11105, 18, 'Os problemas a seguir têm os mesmos códigos de diagnóstico. Problemas de encontro não serão atualizados. Por favor, em vez disso, use a interface de encontro');
INSERT INTO `lang_definitions` VALUES (105859, 11106, 18, 'As etapas a seguir ajudarão a personalizar a Folha de Taxas para imitar o antigo superbill de papel com uma lista de códigos CPT4 e ICD organizados em categorias');
INSERT INTO `lang_definitions` VALUES (105860, 11107, 18, 'O grupo (ARO) que você criou agora aparecerá em ordem alfabética na seção \'Grupos e controles de acesso\'');
INSERT INTO `lang_definitions` VALUES (105861, 11108, 18, 'O cabeçalho define o contexto para o documento clínico como um todo');
INSERT INTO `lang_definitions` VALUES (105862, 11109, 18, 'A seção de cabeçalho revelará informações específicas do paciente na maioria das páginas relacionadas ao prontuário do paciente');
INSERT INTO `lang_definitions` VALUES (105863, 11110, 18, 'O Formulário de Reivindicação de Seguro Saúde é frequentemente referido pelo número de formulário CMS 1500 (HCFA 1500)');
INSERT INTO `lang_definitions` VALUES (105864, 11111, 18, 'O arquivo de ajuda está dividido nas seguintes seções');
INSERT INTO `lang_definitions` VALUES (105865, 11112, 18, 'O arquivo de ajuda lá irá guiá-lo nas etapas adicionais de configuração dos testes de laboratório');
INSERT INTO `lang_definitions` VALUES (105866, 11113, 18, 'O ícone de ajuda permitirá que você acesse a ajuda sensível ao contexto para cada uma das páginas acessadas');
INSERT INTO `lang_definitions` VALUES (105867, 11114, 18, 'O nome do host da máquina do repositório de auditoria ATNA');
INSERT INTO `lang_definitions` VALUES (105868, 11116, 18, 'O código de identificação deve ser único para que os resultados sejam exibidos corretamente, você pode apenas usar R905 como exemplo');
INSERT INTO `lang_definitions` VALUES (105869, 11117, 18, 'O código de identificação deve ser único, se for enviar para um laboratório externo, o código de identificação fornecido pelo fornecedor deve ser inserido. Vamos inserir um valor único arbitrário - WWT01');
INSERT INTO `lang_definitions` VALUES (105870, 11118, 18, 'O código de identificação é um código específico do fornecedor que identifica este procedimento ou resultado. Você pode ver exemplos disso nos papéis do laboratório que os laboratórios usam');
INSERT INTO `lang_definitions` VALUES (105871, 11119, 18, 'O código de identificação é essencial para a exibição adequada e tabulação dos resultados');
INSERT INTO `lang_definitions` VALUES (105872, 11120, 18, 'O código de identificação de R34392-1, um número arbitrário, neste caso o código de identificação precedido por R para indicar o resultado e seguido por 1 para indicar o primeiro na sequência, pode ser qualquer coisa única que você escolher');
INSERT INTO `lang_definitions` VALUES (105873, 11121, 18, 'As informações inseridas aqui são usadas para exibir um resumo do encontro. Também é usado para fins de cobrança');
INSERT INTO `lang_definitions` VALUES (105874, 11122, 18, 'As informações inseridas neste formulário serão usadas para preencher uma reclamação em papel');
INSERT INTO `lang_definitions` VALUES (105875, 11123, 18, 'As informações fornecidas no Formulário de Novo Encontro e Folha de Taxas no openEMR são usadas para gerar a reclamação em papel, bem como as reclamações eletrônicas');
INSERT INTO `lang_definitions` VALUES (105876, 11124, 18, 'Os esforços iniciais levaram à criação de Guias de Implementação (IGs) duplicados e conflitantes publicados por diferentes organizações de padrões');
INSERT INTO `lang_definitions` VALUES (105877, 11125, 18, 'A tela inicial permite que você selecione um método, oferecendo-lhe essas duas opções');
INSERT INTO `lang_definitions` VALUES (105878, 11126, 18, 'A janela inicial é a página de pesquisa na factura. No topo você pode inserir um código (número do cheque, por exemplo), pagamento de data e quantidade de seleção. A razão para isto é não ter que inseri-las uma e outra vez de cada pedido. A quantidade que você inserir será reduzida para cada nota fiscal que é dado parte do pagamento, e esperamos que vai terminar em zero quando você está feito.');
INSERT INTO `lang_definitions` VALUES (105879, 11127, 18, 'A entrada deve ser um arquivo CSV com 3 colunas: ID do layout, tipo de código e código');
INSERT INTO `lang_definitions` VALUES (105880, 11128, 18, 'O diretório de instalação precisa ser criado');
INSERT INTO `lang_definitions` VALUES (105881, 11129, 18, 'A versão SNOMED internacional instalada não é compatível com o pacote SNOMED da extensão dos EUA testado');
INSERT INTO `lang_definitions` VALUES (105882, 11130, 18, 'A versão SNOMED internacional instalada está desatualizada e não é compatível com o arquivo SNOMED de extensão dos EUA testado');
INSERT INTO `lang_definitions` VALUES (105883, 11131, 18, 'A versão instalada e os arquivos testados são os mesmos');
INSERT INTO `lang_definitions` VALUES (105884, 11132, 18, 'A versão instalada é uma versão mais recente do que os arquivos testados');
INSERT INTO `lang_definitions` VALUES (105885, 11133, 18, 'O manual de instruções sobre como preencher o formulário CMS 1500 pode ser encontrado aqui');
INSERT INTO `lang_definitions` VALUES (105886, 11134, 18, 'O endereço IP do (s) seu (s) controlador (es) de domínio');
INSERT INTO `lang_definitions` VALUES (105887, 11135, 18, 'Os problemas podem ser inseridos de duas maneiras');
INSERT INTO `lang_definitions` VALUES (105888, 11136, 18, 'A seção de problemas exibirá todos os problemas inseridos para o paciente e exibirá o tipo de problema, seu título e uma descrição');
INSERT INTO `lang_definitions` VALUES (105889, 11137, 18, 'Os itens listados na coluna \'Ativo\' delineiam os privilégios deste grupo (ARO) e constituem esta Lista de Controle de Acesso (ACL) deste grupo');
INSERT INTO `lang_definitions` VALUES (105890, 11138, 18, 'Os itens que têm asteriscos após eles são obrigatórios');
INSERT INTO `lang_definitions` VALUES (105891, 11140, 18, 'O rótulo que aparece para o usuário sobre a forma');
INSERT INTO `lang_definitions` VALUES (105892, 11141, 18, 'A última célula da linha no Encontro');
INSERT INTO `lang_definitions` VALUES (105893, 11142, 18, 'A última linha deste bloco de encontro dará ao encontro os totais de Encargos, Pagamentos, Ajustes e o Saldo');
INSERT INTO `lang_definitions` VALUES (105894, 11143, 18, 'A última seção trata de pedidos eletrônicos');
INSERT INTO `lang_definitions` VALUES (105895, 11144, 18, 'A data da última visita será preenchida automaticamente');
INSERT INTO `lang_definitions` VALUES (105896, 11145, 18, 'A versão mais recente é FHIR - Fast Healthcare Interoperability Resources - é uma estrutura de padrões de próxima geração criada pelo HL7. Isso está ganhando popularidade, mas ainda não foi amplamente implementado');
INSERT INTO `lang_definitions` VALUES (105897, 11147, 18, 'O comprimento não deve exceder o seguinte número de caracteres');
INSERT INTO `lang_definitions` VALUES (105898, 11150, 18, 'A tabela de registro mostrará uma lista de ambos mensagens e lembretes datados, se houver');
INSERT INTO `lang_definitions` VALUES (105899, 11151, 18, 'O código LOINC para ácido úrico sérico é 3084-1, LOINC refere-se a ele como urato no soro ou plasma');
INSERT INTO `lang_definitions` VALUES (105900, 11152, 18, 'A mesclagem não será executada a menos que SSN e DOB para que os dois gráficos sejam idênticos');
INSERT INTO `lang_definitions` VALUES (105901, 11153, 18, 'A mensagem não pôde ser enviada neste momento');
INSERT INTO `lang_definitions` VALUES (105902, 11154, 18, 'O status da mensagem será Novo, pois é uma nova mensagem que está sendo criada');
INSERT INTO `lang_definitions` VALUES (105903, 11155, 18, 'As mensagens que foram enviadas pelo usuário naquele dia serão exibidas na tabela abaixo');
INSERT INTO `lang_definitions` VALUES (105904, 11156, 18, 'O centro de mensagens consolida convenientemente as opções de comunicação em um só lugar');
INSERT INTO `lang_definitions` VALUES (105905, 11157, 18, 'O centro de mensagens será aberto com a guia Mensagens ativada e exibirá as mensagens do usuário conectado, conforme indicado pela legenda Minhas mensagens');
INSERT INTO `lang_definitions` VALUES (105906, 11158, 18, 'A informação mínima necessária para criar um novo encontro é selecionar uma categoria de visita');
INSERT INTO `lang_definitions` VALUES (105907, 11159, 18, 'As opções de faturamento diversas para o formulário HCFA-1500 são usadas para fornecer informações adicionais para uma reclamação individual');
INSERT INTO `lang_definitions` VALUES (105908, 11160, 18, 'O método mais comum é chamado de autorização de 2 fatores ou 2FA');
INSERT INTO `lang_definitions` VALUES (105909, 11161, 18, 'A questão mais importante que precisa ser tratada é com quem você está tentando se conectar e o que precisa acontecer no final. A maioria dos grandes laboratórios não lidará com práticas individuais; em tais casos, um fornecedor terceirizado atuará como um intermediário que será responsável por estabelecer uma conexão entre a clínica e o laboratório por meio de sua interface (do intermediário)');
INSERT INTO `lang_definitions` VALUES (105910, 11162, 18, 'O fabricante mais popular de chaves de segurança é a Yubico, que oferece versões USB regulares, bem como aquelas feitas para dispositivos que requerem conexões USB-C, como os sistemas Mac OS mais recentes da Apple');
INSERT INTO `lang_definitions` VALUES (105911, 11163, 18, 'O Sistema Open-source Médico e Hospitalar de Saúde mais popular que existe.');
INSERT INTO `lang_definitions` VALUES (105912, 11164, 18, 'A célula do nome contém o nome, data de nascimento, ID do paciente e data da última visita');
INSERT INTO `lang_definitions` VALUES (105913, 11165, 18, 'O bloco narrativo contém informações que são processadas como texto legível');
INSERT INTO `lang_definitions` VALUES (105914, 11166, 18, 'O National Uniform Claim Committee (NUCC) é responsável pela manutenção do Formulário de Reivindicação 1500');
INSERT INTO `lang_definitions` VALUES (105915, 11167, 18, 'A barra de navegação permite navegar rapidamente para várias partes do registro médico do paciente');
INSERT INTO `lang_definitions` VALUES (105916, 11168, 18, 'A nova categoria será uma sub-categoria de');
INSERT INTO `lang_definitions` VALUES (105917, 11170, 18, 'A nova senha não pode ser igual à senha atual');
INSERT INTO `lang_definitions` VALUES (105918, 11171, 18, 'Os novos campos de senha não são os mesmos');
INSERT INTO `lang_definitions` VALUES (105919, 11173, 18, 'O nome do parceiro NewCrop eRx, o nome NewCrop eRx e a senha NewCrop eRx serão fornecidos pelo fornecedor');
INSERT INTO `lang_definitions` VALUES (105920, 11174, 18, 'A próxima caixa é Body Site, não relevante para um exame de sangue, mas pode ser mais útil, digamos, para rastrear injeções ou solicitar raios-X');
INSERT INTO `lang_definitions` VALUES (105921, 11175, 18, 'As próximas poucas linhas listarão todos os códigos E / M e CPT que foram cobrados, uma linha por código');
INSERT INTO `lang_definitions` VALUES (105922, 11176, 18, 'O próximo grupo consiste dos códigos ICD');
INSERT INTO `lang_definitions` VALUES (105923, 11177, 18, 'As próximas três células são as células de ação que permitem que você execute alguma atividade de recordação');
INSERT INTO `lang_definitions` VALUES (105924, 11178, 18, 'As próximas duas caixas que indicam o código de identificação e o código padrão são muito importantes');
INSERT INTO `lang_definitions` VALUES (105925, 11179, 18, 'A célula de Notas permite- lhe adicionar uma nota a uma ação que você realiza nas 3 células de ação ou apenas uma nota sem qualquer associação com a ação');
INSERT INTO `lang_definitions` VALUES (105926, 11180, 18, 'O número de compromissos futuros para exibir na declaração');
INSERT INTO `lang_definitions` VALUES (105927, 11181, 18, 'O número de arquivos testados está incorreto. Coloque apenas o arquivo que deseja instalar / atualizar para');
INSERT INTO `lang_definitions` VALUES (105928, 11182, 18, 'O número de arquivos testados está incorreto. Coloque apenas o arquivo que deseja instalar / atualizar para');
INSERT INTO `lang_definitions` VALUES (105929, 11183, 18, 'O escritório: o celular permite que você indique que uma chamada foi feita');
INSERT INTO `lang_definitions` VALUES (105930, 11184, 18, 'A opção Expandir toda a linha é útil ao usar Texto estático para permitir que o texto seja quebrado e estendido por toda a linha, independentemente das configurações da coluna. Outro uso pode ser criar uma linha vazia como espaçador ou adicionar a opção Adicionar Borda Inferior para criar uma quebra de linha. Somente a Linha da Borda Inferior é útil aqui');
INSERT INTO `lang_definitions` VALUES (105931, 11185, 18, 'As opções de Contorno e Borda irão envolver uma linha em uma borda fina ou adicionar uma borda na parte inferior de um item');
INSERT INTO `lang_definitions` VALUES (105932, 11186, 18, 'A ordem em que a categoria, procedimento ou resultado aparece');
INSERT INTO `lang_definitions` VALUES (105933, 11187, 18, 'Os outros 4 tipos de transação são tipos de transação simples - Solicitação do paciente, Solicitação do médico, Legal e Cobrança');
INSERT INTO `lang_definitions` VALUES (105934, 11188, 18, 'Os outros segmentos contêm informações adicionais de forma estritamente estruturada');
INSERT INTO `lang_definitions` VALUES (105935, 11189, 18, 'A página será redirecionada para Demografia. Você pode editar o campo do país e clicar para NewCrop novamente');
