INSERT INTO `lang_definitions` VALUES (105983, 11240, 18, 'A seção chamada \'Pesquisa de fatura\' é onde você coloca seus parâmetros de pesquisa. Você pode pesquisar pelo nome do paciente, número do prontuário, número do encontro ou data do serviço, ou qualquer combinação destes. Você também pode selecionar se deseja ver todas as faturas, faturas em aberto ou apenas as faturas vencidas (pelo paciente). Clique no botão \'Pesquisar\' para realizar a pesquisa');
INSERT INTO `lang_definitions` VALUES (105984, 11241, 18, 'O código selecionado será adicionado à caixa de texto de codificação e a Descrição do código será adicionada à caixa de texto Título');
