INSERT INTO `lang_definitions` VALUES (105988, 11245, 18, 'O endereço do servidor será da forma');
INSERT INTO `lang_definitions` VALUES (105989, 11246, 18, 'A configuração para os testes de laboratório será descrita em detalhes, pequenas modificações nessas etapas serão necessárias para configurar os procedimentos no escritório e outros tipos de procedimento');
INSERT INTO `lang_definitions` VALUES (105990, 11247, 18, 'A Contra-referência, um tanto ambiguamente, é o espaço onde a resposta à referência feita pode ser documentada');
INSERT INTO `lang_definitions` VALUES (105991, 11248, 18, 'As colunas de origem e data são copiados da primeira página, assim que normalmente você não vai precisar tocar essas. Você pode colocar um valor de pagamento na coluna Pay, um ajuste no montante de Ajuste de coluna, ou ambos. Você também pode clicar no \"\"W \"\" sobre o direito de computar automaticamente um valor de ajuste que escreve fora do restante da carga para esse item.');
INSERT INTO `lang_definitions` VALUES (105992, 11249, 18, 'As colunas fonte e Data são copiadas da primeira página, portanto, normalmente você não precisará tocá-las. Você pode colocar um valor de pagamento na coluna Pagamento, um valor de ajuste na coluna Ajuste ou ambos. Você também pode clicar no \'W\' à direita para calcular automaticamente um valor de ajuste que baixa o restante da cobrança desse item de linha');
INSERT INTO `lang_definitions` VALUES (105993, 11250, 18, 'O tipo de amostra será Sangue, esta lista suspensa também pode ser editada conforme necessário');
