INSERT INTO `lang_definitions` VALUES (106280, 11572, 18, 'Isso permitirá o uso do relatório personalizado de Fim do Dia e indicará qual relatório usar');
INSERT INTO `lang_definitions` VALUES (106281, 11573, 18, 'Isso permitirá o uso de mensagens de advertência personalizadas nas declarações');
INSERT INTO `lang_definitions` VALUES (106282, 11574, 18, 'Esta será uma \"simulação\" sem atualizações de dados físicos');
INSERT INTO `lang_definitions` VALUES (106283, 11575, 18, 'Isso limpará os dados de todos os campos do exame de segmento anterior');
INSERT INTO `lang_definitions` VALUES (106284, 11576, 18, 'Isso limpará os dados de todos os campos de exames externos');
INSERT INTO `lang_definitions` VALUES (106285, 11577, 18, 'Isso limpará os dados de todos os campos do exame de retina');
INSERT INTO `lang_definitions` VALUES (106286, 11578, 18, 'Isso copiará o código selecionado para a caixa Códigos de diagnóstico no formulário subjacente pop-up Inserir detalhes para item favorito individual personalizado');
INSERT INTO `lang_definitions` VALUES (106287, 11579, 18, 'Isto irá criar um backup no formato tar e depois enviá-lo para seu navegador para que você possa salvá-lo');
INSERT INTO `lang_definitions` VALUES (106288, 11580, 18, 'Isso desativará os recursos de criptografia e descriptografia de documentos e os ocultará na IU');
INSERT INTO `lang_definitions` VALUES (106289, 11581, 18, 'Isso irá desativar o botão Editar em todos os formulários cujo encontro com os pais é assinado por e-mail');
INSERT INTO `lang_definitions` VALUES (106290, 11582, 18, 'Isso desativará o botão Editar em qualquer formulário que tenha assinatura eletrônica');
INSERT INTO `lang_definitions` VALUES (106291, 11583, 18, 'Isso exibirá o número da fatura no relatório de vendas ou o nome e ID do paciente ou nome do paciente e número da fatura');
INSERT INTO `lang_definitions` VALUES (106292, 11585, 18, 'Isso habilitará a criptografia de itens armazenados na unidade');
INSERT INTO `lang_definitions` VALUES (106293, 11586, 18, 'Isso permitirá a assinatura de um encontro inteiro, em vez de formulários individuais');
