INSERT INTO `lang_definitions` VALUES (106295, 11588, 18, 'Isso habilitará a capacidade de excluir as declarações do paciente selecionadas da impressão');
INSERT INTO `lang_definitions` VALUES (106296, 11589, 18, 'Isso irá preencher a caixa de texto Título, bem como o código ICD10 na caixa de texto Codificação');
