INSERT INTO `lang_definitions` VALUES (106298, 11591, 18, 'Isso dará ao usuário a opção de bloquear (bloqueio e assinatura separados)');
INSERT INTO `lang_definitions` VALUES (106299, 11592, 18, 'Isso lhe dará a opção de definir diferentes níveis de preços ao inserir manualmente os códigos CPT');
INSERT INTO `lang_definitions` VALUES (106300, 11595, 18, 'Isso irá ocultar logs de e-sign vazios no relatório do paciente');
INSERT INTO `lang_definitions` VALUES (106301, 11596, 18, 'Isso ocultará o widget de cobrança na tela de resumo do paciente');
INSERT INTO `lang_definitions` VALUES (106302, 11597, 18, 'Isso irá mesclar dois prontuários de pacientes em um. É útil quando um paciente foi duplicado por engano. Se isso acontecer com freqüência, corrija seus procedimentos de escritório - não execute isso rotineiramente!');
