INSERT INTO `lang_definitions` VALUES (106304, 11600, 18, 'Isso imprimirá o próximo compromisso na parte inferior do livro do paciente');
INSERT INTO `lang_definitions` VALUES (106305, 11601, 18, 'Isso irá exibir novamente a chave secreta por meio do código QR que pode então ser capturado e armazenado no novo Smartphone por meio de seu aplicativo autenticador');
INSERT INTO `lang_definitions` VALUES (106306, 11602, 18, 'Isso registrará uma nova chave USB U2F');
