INSERT INTO `lang_definitions` VALUES (106382, 11681, 18, 'Para permitir que cada linha de procedimento tenha um provedor separado, você deve marcar a caixa de seleção \'Provedor de suporte no item de linha na folha de taxas\' em Administração> Globais> Faturamento. Se não for marcado, o provedor de renderização nesta seção será usado para todas as reivindicações');
INSERT INTO `lang_definitions` VALUES (106383, 11682, 18, 'Para autorizar o portal do paciente para o paciente, vá para Painel> Demografia> Editar> Opções e selecione Sim na caixa suspensa Permitir portal do paciente e Salvar');
