INSERT INTO `lang_definitions` VALUES (106393, 11692, 18, 'Para criar outro painel de testes, você repetirá este processo, mas começará criando uma Ordem de Procedimento ou ramo frutífero Nível 3, por exemplo - painel de Hepatite Aguda no ramo principal ou Subgrupo Órgão / Painel de Doenças (Nível 2)');
