INSERT INTO `lang_definitions` VALUES (106396, 11696, 18, 'Para excluir qualquer um ou todos os códigos ICD10 selecionados, clique novamente na caixa Códigos de Diagnóstico para abrir a janela pop-up Selecionar Códigos de Diagnóstico');
INSERT INTO `lang_definitions` VALUES (106397, 11697, 18, 'Para desvincular, basta clicar no item para desvincular e ele será desvinculado e não será mais destacado');
INSERT INTO `lang_definitions` VALUES (106398, 11698, 18, 'Para Dems');
INSERT INTO `lang_definitions` VALUES (106399, 11699, 18, 'Para desativar a verificação automática de mensagens, vá para Administração> Globais> Conectores e defina o intervalo de verificação de mensagens phiMail como 0 (zero)');
INSERT INTO `lang_definitions` VALUES (106400, 11700, 18, 'Para desativar os certificados SSL do lado do cliente, comente acima das linhas no arquivo de configuração do Apache e defina');
INSERT INTO `lang_definitions` VALUES (106401, 11702, 18, 'Para desabilitar HTTPS, comente as linhas acima no arquivo de configuração do Apache e reinicie o servidor Apache');
INSERT INTO `lang_definitions` VALUES (106402, 11703, 18, 'Para exibir o valor do copagamento, ele deve ter sido inserido no seguro do paciente em Editar> Dados demográficos');
INSERT INTO `lang_definitions` VALUES (106403, 11704, 18, 'Para fazer isso, clique no sinal + preto no final da linha de pedido de ácido úrico no soro para abrir o pop-up Inserir detalhes');
INSERT INTO `lang_definitions` VALUES (106404, 11705, 18, 'Para editar um grupo existente (ARO) clique no ícone ao lado do grupo desejado. Isso abrirá a janela de edição');
INSERT INTO `lang_definitions` VALUES (106405, 11706, 18, 'Para ativar qualquer outra forma de conectividade, será necessário escrever um novo código');
INSERT INTO `lang_definitions` VALUES (106406, 11707, 18, 'Para habilitar certificados SSL do lado do cliente');
INSERT INTO `lang_definitions` VALUES (106407, 11708, 18, 'Para ativar a autenticação de certificados SSL do lado do cliente, HTTPS deve ser ativado');
INSERT INTO `lang_definitions` VALUES (106408, 11709, 18, 'Para ativar a ajuda - Vá para Administração> Globais> Recursos> Ativar Modal de Ajuda');
INSERT INTO `lang_definitions` VALUES (106409, 11710, 18, 'Para ativar a ajuda - Vá para o Nome de usuário no canto superior esquerdo> Configurações> Recursos> Ativar Modal de Ajuda');
INSERT INTO `lang_definitions` VALUES (106410, 11711, 18, 'Para habilitar a ajuda - Vá para o Nome de Usuário no canto superior direito> Configurações> Recursos> Habilitar Modal de Ajuda');
INSERT INTO `lang_definitions` VALUES (106411, 11712, 18, 'Para ativar apenas HTTPS, execute as alterações acima e reinicie o servidor Apache. Se você quiser configurar certificados do lado do cliente também, por favor configure-os na próxima seção');
INSERT INTO `lang_definitions` VALUES (106412, 11713, 18, 'Para habilitar o Portal do Paciente, vá para Administração> Portal> Habilitar Portal do Paciente no local na Versão 2, Habilitar Portal do Paciente Externo ou Habilitar Portal CMS');
INSERT INTO `lang_definitions` VALUES (106413, 11715, 18, 'Para Enctr');
INSERT INTO `lang_definitions` VALUES (106414, 11716, 18, 'Para filtrar por sexo');
INSERT INTO `lang_definitions` VALUES (106415, 11717, 18, 'Para cumprir os requisitos de uso significativo e ajudar a rastrear seu uso, você pode marcar a caixa de seleção Resumo de cuidados enviados e a caixa de seleção Resumo de cuidados enviados eletronicamente, se apropriado');
INSERT INTO `lang_definitions` VALUES (106416, 11718, 18, 'Para excluir totalmente, clique em \'Salvar\'');
INSERT INTO `lang_definitions` VALUES (106417, 11719, 18, 'Para começar, você escolhe um dos dois botões de opção. \'Pesquisa de fatura\' ou \'Upload ERA\'');
INSERT INTO `lang_definitions` VALUES (106418, 11720, 18, 'Para ajudar a explorar os vários componentes da página Relatório, especialmente se você quiser usá-la como um manual de instruções, é sugerido que você reduza o tamanho do navegador para cobrir metade da janela de visualização, redimensione o pop-up de ajuda clicando e arrastando a parte inferior canto direito da janela pop-up. Abra outra instância do navegador e redimensione-a para cobrir a outra metade da janela de visualização, faça login no openEMR');
INSERT INTO `lang_definitions` VALUES (106419, 11721, 18, 'Para ajudar a se familiarizar com os vários componentes da página Dashboard, é sugerido que você reduza o tamanho do navegador para cobrir metade da janela de visualização, redimensione o pop-up de ajuda clicando e arrastando a parte inferior canto direito da janela pop-up. Abra outra instância do navegador e redimensione-a para cobrir a outra metade da janela de visualização, faça login no openEMR');
INSERT INTO `lang_definitions` VALUES (106420, 11722, 18, 'Para ajudar a simplificar as implementações, os modelos comumente usados foram harmonizados a partir de guias de implementação de CDA existentes e consolidados em um único guia de implementação - o Guia de Implementação C-CDA (IG) (07/2012)');
INSERT INTO `lang_definitions` VALUES (106421, 11723, 18, 'Acrescentar/Consultar Histórico');
INSERT INTO `lang_definitions` VALUES (106422, 11724, 18, 'Para incluir os documentos digitalizados que fazem parte do registro do paciente, selecione os registros desejados marcando as caixas de seleção relevantes');
INSERT INTO `lang_definitions` VALUES (106423, 11725, 18, 'Para Questões');
INSERT INTO `lang_definitions` VALUES (106424, 11726, 18, 'Para vincular os problemas a um encontro, primeiro selecione o problema, ele será destacado em amarelo, logo clique em um ou mais encontros para vinculá-los, os encontros selecionados serão destacados em roxo');
INSERT INTO `lang_definitions` VALUES (106425, 11727, 18, 'Para vincular este encontro / consulta a um problema existente, clique no');
INSERT INTO `lang_definitions` VALUES (106426, 11728, 18, 'Para vincular este encontro / consulta a um problema existente, clique na edição desejada acima para destacá-lo e, em seguida, clique em [Salvar]. Mantenha pressionada a tecla [Ctrl] para seleccionar várias questões.');
INSERT INTO `lang_definitions` VALUES (106427, 11729, 18, 'Para vincular este encontro / consulta a um problema existente, clique no problema desejado acima para destacá-lo e logo clique em Salvar');
INSERT INTO `lang_definitions` VALUES (106428, 11730, 18, 'Para fazer o login novamente');
INSERT INTO `lang_definitions` VALUES (106429, 11731, 18, 'Para mover os grupos de uma coluna para outra selecione um ou mais itens da coluna que você precisa para removê-los e pressione o botão relevante com as divisas duplas');
INSERT INTO `lang_definitions` VALUES (106430, 11732, 18, 'Para continuar, você precisa de uma chave de segurança USB, uma conexão segura da web HTTPS e um navegador que suporte U2F');
INSERT INTO `lang_definitions` VALUES (106431, 11733, 18, 'Para recapitular, um grupo chamado Química do Soro (Nível 1) foi criado, um descendente direto ou filho chamado Ácido Úrico do Soro (Nível 2) foi criado abaixo dele como uma Ordem de Procedimento que tinha um único descendente direto ou filho também chamado de Ácido Úrico do Soro (Nível 3) como um resultado discreto que conterá o valor do resultado');
INSERT INTO `lang_definitions` VALUES (106432, 11734, 18, 'Para receber notificações de erro do serviço de mensagens diretas, um endereço de e-mail de notificação válido precisa ser inserido para o usuário nomeado em Administração> Globais> Conectores> usuário de notificação phiMail');
INSERT INTO `lang_definitions` VALUES (106433, 11735, 18, 'Para registrar comuncados, clique aqui.');
