INSERT INTO `lang_definitions` VALUES (106448, 11754, 18, 'Para usar a página de ajuda como um manual de instruções, é sugerido que você reduza o tamanho do navegador para cobrir metade da janela de visualização, redimensione o pop-up de ajuda clicando e arrastando o canto inferior direito do pop-up. Abra outra instância do navegador e redimensione-a para cobrir a outra metade da janela de visualização, faça login no openEMR');
INSERT INTO `lang_definitions` VALUES (106449, 11755, 18, 'Para usar este arquivo de ajuda como um manual de instruções é melhor redimensionar seu navegador para ocupar metade da tela, abrir outra instância do navegador para preencher a outra metade da tela, fazer o login para openEMR e abrir o arquivo de ajuda neste navegador e redimensionar clicando e arrastando o canto inferior direito para que ocupae toda a metade da tela');
