INSERT INTO `lang_definitions` VALUES (106838, 12210, 18, 'Após uma pesquisa bem-sucedida, você verá uma lista de faturas. Você pode clicar em um dos números da fatura para abrir uma segunda janela, que é a página de entrada de dados para postagem manual. Você também pode clicar no nome de um paciente se quiser inserir uma nota que a equipe da recepção verá quando o paciente fizer check-in, e você pode selecionar faturas para aparecer nos extratos dos pacientes e imprimir esses extratos');
INSERT INTO `lang_definitions` VALUES (106839, 12211, 18, 'Ao clicar em um número da factura a \"\"janela de lançamento manual \"\" aparece. Aqui você pode mudar a data de vencimento e as notas para a factura, selecione o partido para o qual você está postando, e selecione os seguros para a qual todos os paymants esperados foram recebidos. Mais importante ainda, para cada código de faturamento para as quais foi cobrada uma quantia, você pode inserir informações de pagamento e de ajustamento.');
INSERT INTO `lang_definitions` VALUES (106840, 12212, 18, 'Ao clicar em um número de fatura, a \'janela de lançamento manual\' aparece. Aqui você pode alterar a data de vencimento e as notas da fatura, selecionar a parte para a qual está lançando e selecionar os seguros para os quais todos os pagamentos esperados foram recebidos. Mais importante ainda, para cada código de faturamento pelo qual um valor foi cobrado, você pode inserir informações de pagamento e ajuste');
INSERT INTO `lang_definitions` VALUES (106841, 12213, 18, 'Ao entrar na página, existem dois botões visíveis abaixo da barra de navegação');
INSERT INTO `lang_definitions` VALUES (106842, 12214, 18, 'Ao fazer login no openEMR, um pequeno ícone de envelope fica visível no canto superior direito. Mostra o número de mensagens pendentes e lembretes datados');
INSERT INTO `lang_definitions` VALUES (106843, 12215, 18, 'Ao atingir um ponto predeterminado, seja uma data ou valor, a regra irá disparar um ou mais eventos');
INSERT INTO `lang_definitions` VALUES (106844, 12216, 18, 'Após a pesquisa que você é apresentado com uma lista de faturas. Você pode clicar em um dos números de factura para abrir uma segunda janela, que é a página de entrada de dados para lançamento manual. Você também pode clicar no nome do paciente, se você deseja inserir uma nota que o pessoal do escritório da frente vai ver quando as verificações no paciente, e você pode selecionar as facturas para aparecer em declarações paciente e imprimir essas declarações.');
INSERT INTO `lang_definitions` VALUES (106845, 12217, 18, 'Ao selecionar uma lista para editar a página de edição com os valores da lista serão exibidos');
INSERT INTO `lang_definitions` VALUES (106846, 12218, 18, 'Após o registro bem-sucedido, você será levado a página de destino Gerenciar autenticação multifator');
