INSERT INTO `lang_definitions` VALUES (106987, 12379, 18, 'Usar uma árvore frutífera como uma analogia mais fácil de visualizar explicará melhor o conceito desta hierarquia, o tronco da árvore é o Grupo (Química do Soro), o ramo frutífero é a ordem real, Ordem do Procedimento (Ácido Úrico no Soro) e o fruta é o resultado, Resultado Discreto, também chamado de (Ácido Úrico no Soro) que conterá o valor do resultado retornado. Assim como a fruta não é carregada no tronco principal, você não deve colocar um Resultado Discreto como um descendente direto ou filho de um Grupo Superior. Da mesma forma, o ramo frutífero (Ordem de Procedimento) não pode ser colocado como um descendente direto ou filho de uma fruta (Resultado Discreto)');
INSERT INTO `lang_definitions` VALUES (106988, 12380, 18, 'Usando tecnologia para melhorar a produtividade');
INSERT INTO `lang_definitions` VALUES (106989, 12381, 18, 'Usando os detalhes inseridos no sistema openEMR irá gerar mensagens HL7 v2.3 válidas em 3 formatos, um arquivo de texto que é baixado automaticamente para a pasta de downloads do seu navegador, uma mensagem HL7 que é gravada em uma pasta ou diretório no servidor em execução openEMR ou use SFTP - Protocolo de transferência segura de arquivos, que é um protocolo de rede que fornece acesso, transferência e gerenciamento de arquivos em uma conexão segura e transfere esta mensagem para um laboratório');
INSERT INTO `lang_definitions` VALUES (106990, 12382, 18, 'Usando a folha de taxas');
INSERT INTO `lang_definitions` VALUES (106991, 12383, 18, 'Usar os cabeçalhos principais da ficha de laboratório ajudará a iniciar este processo - Painéis de órgãos / doenças, hematologia, testes individuais, microbiologia, outros');
INSERT INTO `lang_definitions` VALUES (106992, 12384, 18, 'Usando esta analogia com a árvore frutífera, podemos obter uma melhor compreensão das etapas necessárias para criar um pedido para um painel de testes');
