INSERT INTO `lang_definitions` VALUES (107265, 12702, 18, 'Quando verificado, a última equipe a atualizar o quadro será exibida no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (107266, 12703, 18, 'Quando marcada, as mensagens são processadas para pacientes com Escolha Demográfica do Paciente: \"Notificação Hipaa Recebida\" definida como \"Não Atribuída\" ou \"Sim\". Quando desmarcada, esta opção deve ser = \"SIM\" para processar o lembrete do paciente. Para pacientes com Escolha = \"Não\", os lembretes precisarão ser processados manualmente');
