INSERT INTO `lang_definitions` VALUES (108275, 627, 19, 'Alternativamente, você pode optar por carregar um arquivo de remessa eletrônica (X12 835) que você tenha obtido de seu pagador ou clearinghouse. Você pode fazer isso selecionando primeiro a opção \'ERA upload\' na seção inicial \'Select Method\'. Isso traz a seção \'ERA Upload\'');
INSERT INTO `lang_definitions` VALUES (108276, 628, 19, 'Alternativamente, você pode usar a página de procura para transferir uma remessa eletrônica (X12 835), que obteve do sub-sistema pagador. Para isso, carregue no botão BROWSE e depois escolha o arquivo a transferir; depois, carregando em Procura para executar o carregamento e mostrar as facturas correspondentes. Neste caso não se aplicam os outros parâmetros mencionados acima. Upload guarda o arquivo mas não processa o seu conteúdo--isso é feito separadamente, como se explica abaixo.');
INSERT INTO `lang_definitions` VALUES (108277, 629, 19, 'Embora o HCFA-1500 tenha sido originalmente desenvolvido para a apresentação de reivindicações do Medicare, acabou sendo aceito por todas as seguradoras comerciais / privadas para facilitar a padronização do processo de reivindicações');
