INSERT INTO `lang_definitions` VALUES (112375, 5260, 19, 'Importante - o código de identificação para o grupo de favoritos personalizados é sempre definido pelo usuário');
INSERT INTO `lang_definitions` VALUES (112376, 5261, 19, 'Códigos Importantes');
INSERT INTO `lang_definitions` VALUES (112377, 5262, 19, 'IMPORTANTE: O número NPI também existe na entrada do Catálogo de endereços para o provedor, tome cuidado para inserir o número NPI correto');
INSERT INTO `lang_definitions` VALUES (112378, 5263, 19, 'IMPORTANTE: Esta ferramenta de upload serve apenas para fazer upload de documentos de pacientes que ainda não foram inseridos no sistema. Para fazer upload de arquivos para pacientes que já foram inseridos no sistema, por favor use a ferramenta de upload vinculada à tela de resumo do paciente.');
