INSERT INTO `lang_definitions` VALUES (112390, 5275, 19, 'Da mesma forma, você criará um Resultado Discreto para Potássio, Cloreto e Dióxido de Carbono');
INSERT INTO `lang_definitions` VALUES (112391, 5276, 19, 'Da mesma forma, crie um item favorito personalizado para TSH (sequência 2, código de identificação WWT02, código padrão 30166-3) e vitamina D (sequência 3, código de identificação WWT03, código padrão 35365-6)');
INSERT INTO `lang_definitions` VALUES (112392, 5277, 19, 'Da mesma forma, crie um Resultado Discreto para TSH (Sequência - 2, Código de Identificação - WWT02R, Unidades Padrão - mU / L, intervalo Padrão - 0,4-4, deixe os Serviços de Acompanhamento em branco) e Vitamina D (Sequência - 3, Código de Identificação - WWT03R, unidades padrão - ng / mL, intervalo padrão - 0-20, deixe os serviços de acompanhamento em branco)');
INSERT INTO `lang_definitions` VALUES (112393, 5278, 19, 'Além disso, existem 2 caixas de seleção');
INSERT INTO `lang_definitions` VALUES (112394, 5279, 19, 'Além de criar uma Referência, o sistema também permite que você imprima um formulário de referência em branco que pode ser preenchido manualmente para gerar uma Referência');
INSERT INTO `lang_definitions` VALUES (112395, 5280, 19, 'Em qualquer caso, o estabelecimento de uma conexão, garantindo conformidade HIPAA, a segurança dos dados etc. exigirá codificação, cujo custo geralmente é suportado pelo laboratório. No entanto, eles só aprovarão se o volume de negócios justificar seu investimento');
