INSERT INTO `lang_definitions` VALUES (112402, 5290, 19, 'Disponível');
INSERT INTO `lang_definitions` VALUES (112403, 5291, 19, 'No openEMR, os relatórios de Registro de Continuidade de Cuidados (CCR) a serem gerados podem ser limitados a um intervalo de datas específico marcando a caixa de seleção Usar intervalo de datas e inserindo o intervalo de datas desejado');
INSERT INTO `lang_definitions` VALUES (112404, 5292, 19, 'A fim de cumprir os requisitos de uso significativo para entrada de pedido de provedor computadorizado (CPOE) para testes de laboratório e radiologia, este módulo precisa ser usado');
INSERT INTO `lang_definitions` VALUES (112405, 5293, 19, 'Para armazenar e recuperar adequadamente os resultados do teste e fazer novos pedidos, os testes / pedidos devem ser configurados de maneira hierárquica');
INSERT INTO `lang_definitions` VALUES (112406, 5294, 19, 'Para registrar os valores dos resultados retornados, você deve criar um Resultado Discreto separado (Nível 4) para cada um dos constituintes do painel, a fruta, como descendentes diretos deste ramo (Painel de Saúde Geral) (Nível 3). Exemplos dos resultados são CBC - Hemoglobina, CBC - Hematócrito, CMP - Sódio, CMP - Potássio, TSH etc.');
INSERT INTO `lang_definitions` VALUES (112407, 5295, 19, 'Para registrar seu dispositivo, por favor forneça sua senha de login do OpenEMR');
INSERT INTO `lang_definitions` VALUES (112408, 5296, 19, 'Para enviar Registro de Continuidade de Cuidados (CCR) e / ou Documento de Continuidade de Cuidados (CCD), opcionalmente, marque phiMail Permitir CCD Send e / ou phiMail Permitir CCR Send para habilitar o recurso de transmissão para esses tipos de dados');
INSERT INTO `lang_definitions` VALUES (112409, 5297, 19, 'No nosso caso, escolheremos o laboratório local que foi configurado anteriormente');
INSERT INTO `lang_definitions` VALUES (112410, 5298, 19, 'No nosso caso, vamos deixá-lo como Não atribuído');
INSERT INTO `lang_definitions` VALUES (112411, 5300, 19, 'No modo Retrato, determina a altura do envelope ao longo do eixo y em mm');
INSERT INTO `lang_definitions` VALUES (112412, 5301, 19, 'No modo Retrato, determina a largura do envelope ao longo do eixo x em mm');
INSERT INTO `lang_definitions` VALUES (112413, 5302, 19, 'no olho direto');
INSERT INTO `lang_definitions` VALUES (112414, 5303, 19, 'Em suma, os pedidos eletrônicos podem ser feitos, envolve uma quantidade significativa de testes e customização para ser certificado pelo laboratório, geralmente por meio de um terceiro e só pode acontecer se o laboratório concordar em dar luz verde ao projeto');
INSERT INTO `lang_definitions` VALUES (112415, 5304, 19, 'Na seção \'Postar item\' exibida na parte superior, você pode inserir uma fonte (por exemplo, número do cheque), data de pagamento e valor do cheque. A razão para a fonte e a data de pagamento é para que você não precise inseri-las repetidamente para cada reivindicação. O valor que você inserir será reduzido para cada fatura que receber parte do pagamento e, com sorte, terminará em zero quando você terminar');
INSERT INTO `lang_definitions` VALUES (112416, 5305, 19, 'No exemplo acima, um pedido para um único teste foi criado, ou seja, ácido úrico sérico');
INSERT INTO `lang_definitions` VALUES (112417, 5306, 19, 'Na instalação padrão, clique em Adicionar para abrir a página pop-up Adicionar / Editar Problema');
INSERT INTO `lang_definitions` VALUES (112418, 5307, 19, 'Nas palavras do paciente');
INSERT INTO `lang_definitions` VALUES (112419, 5308, 19, 'Na segunda fase do uso significativo, o CCD, mas não o CCR, foi incluído como parte do padrão para troca de documentos clínicos');
INSERT INTO `lang_definitions` VALUES (112420, 5309, 19, 'Neste caso, o grupo de favoritos personalizados será chamado de Laboratórios de pré-operatório e os dois painéis reconhecidos serão descendentes diretos, cada um em um nível de item favorito personalizado denominado CBC e Painel renal, respectivamente');
INSERT INTO `lang_definitions` VALUES (112421, 5310, 19, 'Neste caso, você criará um Pedido de Procedimento, o ramo frutífero denominado Painel Geral de Saúde (Nível 3)');
INSERT INTO `lang_definitions` VALUES (112422, 5311, 19, 'No total, há dezessete seções que podem ser incluídas em um Registro de Continuidade de Cuidados (CCR)');
