INSERT INTO `lang_definitions` VALUES (112764, 5691, 19, 'Ele permite que o navegador se comunique diretamente com o dispositivo USB evitando a necessidade do usuário fazer qualquer coisa além de inserir o dispositivo em uma porta USB e tocar nele para ativá-lo');
INSERT INTO `lang_definitions` VALUES (112765, 5692, 19, 'Também permite criar novos grupos (AROs), bem como remover os existentes');
INSERT INTO `lang_definitions` VALUES (112766, 5693, 19, 'Ele também pode receber resultados eletronicamente');
INSERT INTO `lang_definitions` VALUES (112767, 5694, 19, 'Pode ser vinculado a um paciente ou apenas uma mensagem endereçada a outro (s) usuário (s)');
INSERT INTO `lang_definitions` VALUES (112768, 5695, 19, 'Ele combina o que o usuário sabe, ou seja, a senha do usuário com o que o usuário possui, ou seja, um dispositivo que é único ou um mecanismo para gerar / receber um código único para ser usado em cada login');
INSERT INTO `lang_definitions` VALUES (112769, 5696, 19, 'Consiste em três seções');
INSERT INTO `lang_definitions` VALUES (112770, 5697, 19, 'Consiste em duas partes - definir um provedor e configurar os pedidos e os resultados');
INSERT INTO `lang_definitions` VALUES (112771, 5698, 19, 'Consiste em duas partes - o aplicativo de recebimento e o recurso de recebimento');
INSERT INTO `lang_definitions` VALUES (112772, 5699, 19, 'Consiste em duas partes - o aplicativo de envio e o recurso de envio');
INSERT INTO `lang_definitions` VALUES (112773, 5700, 19, 'Ele contém uma seção esquerda e direita');
INSERT INTO `lang_definitions` VALUES (112774, 5701, 19, 'Ele contém um código QR que precisa ser capturado pelo aplicativo autenticador');
INSERT INTO `lang_definitions` VALUES (112775, 5702, 19, 'Ele contém dados estruturados que estão incluídos no Registro de Continuidade de Cuidados (CCR) definido para o padrão de Arquitetura de Documento Clínico');
INSERT INTO `lang_definitions` VALUES (112776, 5703, 19, 'Não se refere à referência real que foi criada');
INSERT INTO `lang_definitions` VALUES (112777, 5704, 19, 'Ele faz isso usando um algoritmo para combinar o horário UNIX atual com a chave secreta para gerar uma chave única em constante mudança');
INSERT INTO `lang_definitions` VALUES (112778, 5705, 19, 'Tem quatro guias');
INSERT INTO `lang_definitions` VALUES (112779, 5706, 19, 'Tem três níveis');
INSERT INTO `lang_definitions` VALUES (112780, 5707, 19, 'É um módulo de mensagem comercial disponível para práticas openEMR utilizando a versão 5.0.1 e superior');
INSERT INTO `lang_definitions` VALUES (112781, 5708, 19, 'É um campo no cabeçalho da mensagem HL7 conhecido como ID de processamento');
INSERT INTO `lang_definitions` VALUES (112782, 5709, 19, 'Faz parte do prontuário médico');
INSERT INTO `lang_definitions` VALUES (112783, 5710, 19, 'É também um serviço baseado em assinatura');
INSERT INTO `lang_definitions` VALUES (112784, 5711, 19, 'Também é necessário listar um código CID10 para que o problema seja listado no Relatório de Continuidade de Cuidados (CCR) e no Documento de Continuidade de Cuidados (CCD)');
INSERT INTO `lang_definitions` VALUES (112785, 5712, 19, 'Está dividido em duas seções');
INSERT INTO `lang_definitions` VALUES (112786, 5713, 19, 'É essencial que você leia as primeiras quatro seções para compreender os princípios subjacentes');
INSERT INTO `lang_definitions` VALUES (112787, 5714, 19, 'É muito mais fácil e intuitivo fazer grandes alterações e reorganizar os dados na planilha antes de começar a inserir os dados no openEMR');
INSERT INTO `lang_definitions` VALUES (112788, 5715, 19, 'É importante perceber que isso gerencia o MFA para o usuário conectado');
INSERT INTO `lang_definitions` VALUES (112789, 5716, 19, 'É importante compreender a função destes dois ícones dado que todos os passos subsequentes necessários para configurar correctamente a hierarquia irão depender da utilização correcta destes dois ícones');
INSERT INTO `lang_definitions` VALUES (112790, 5717, 19, 'Destina-se a incluir apenas as informações que são críticas para efetivamente continuar o cuidado');
INSERT INTO `lang_definitions` VALUES (112791, 5718, 19, 'É emitido para prestadores de cuidados de saúde nos Estados Unidos pelos Centros de Serviços Medicare e Medicaid (CMS)');
INSERT INTO `lang_definitions` VALUES (112792, 5719, 19, 'Não é necessário para o laboratório local, em vez disso, você pode usar qualquer número único arbitrário');
INSERT INTO `lang_definitions` VALUES (112793, 5720, 19, 'Não é necessário preencher os códigos de diagnóstico padrão, pois os códigos ICD10 podem ser inseridos no momento do pedido real do teste');
INSERT INTO `lang_definitions` VALUES (112794, 5721, 19, 'Não é enviado com a reclamação');
INSERT INTO `lang_definitions` VALUES (112795, 5722, 19, 'Não é incomum solicitar vários exames de sangue juntos, agrupá-los como um painel de exames facilita esse processo');
INSERT INTO `lang_definitions` VALUES (112796, 5724, 19, 'É o formulário de reclamação em papel básico prescrito por muitos pagadores para reclamações submetidas por médicos e práticas individuais, enfermeiras e profissionais, incluindo terapeutas, quiropráticos e clínicas ambulatoriais e, em alguns casos, para serviços de ambulância');
INSERT INTO `lang_definitions` VALUES (112797, 5725, 19, 'É usado para vincular problemas a encontros e também é usado para ver quais encontros estão associados a um determinado problema');
INSERT INTO `lang_definitions` VALUES (112798, 5726, 19, 'É útil praticar em um local de teste para se familiarizar com o processo antes de fazer isso no aplicativo openEMR de produção');
INSERT INTO `lang_definitions` VALUES (112799, 5727, 19, 'Permite pesquisar por códigos de diagnóstico ICD 9 e ICD 10 e CPT4 e HCPCS');
INSERT INTO `lang_definitions` VALUES (112800, 5728, 19, 'Ele permite que você envie mensagens e lembretes datados aos membros da equipe, adicione o paciente à lista de re call e envie mensagens de texto SMS para os pacientes');
INSERT INTO `lang_definitions` VALUES (112801, 5729, 19, 'Ele serve como uma ponte necessária para um ambiente diferente, muitas vezes com novos médicos que não sabem nada sobre o paciente, permitindo que o próximo provedor facilmente');
INSERT INTO `lang_definitions` VALUES (112802, 5731, 19, 'Portanto, é lógico que você não pode criar uma contra-referência por si só');
INSERT INTO `lang_definitions` VALUES (112803, 5732, 19, 'Ele usa um padrão aberto e, portanto, disponível em vários fabricantes');
INSERT INTO `lang_definitions` VALUES (112804, 5733, 19, 'Ele usa a função hash HMAC-SHA256 para gerar uma chave privada exclusiva para a conta');
INSERT INTO `lang_definitions` VALUES (112805, 5734, 19, 'Ele usa essa chave privada para assinar o desafio e envia a resposta de volta ao aplicativo');
INSERT INTO `lang_definitions` VALUES (112806, 5735, 19, 'Será exibido no resumo da visita');
INSERT INTO `lang_definitions` VALUES (112807, 5736, 19, 'Isso abrirá o formulário pop-up Inserir detalhes');
INSERT INTO `lang_definitions` VALUES (112808, 5737, 19, 'Isso abrirá o pop-up do localizador de vários pacientes');
INSERT INTO `lang_definitions` VALUES (112809, 5738, 19, 'Ele exibirá o pop-up de exibição justificado. Tem uma caixa de pesquisa que permite pesquisar um código ICD. Ele também exibirá os 10 códigos ICD mais comumente usados. Você pode selecionar qualquer um ou todos os códigos marcando a caixa de seleção J (justificar) e pressionando atualizar');
INSERT INTO `lang_definitions` VALUES (112810, 5739, 19, 'Terá um valor de 2 na coluna nível indicando que é um sucessor ou filho na primeira linha acima tendo um valor nível 1 que neste caso é Química do Soro');
INSERT INTO `lang_definitions` VALUES (112811, 5740, 19, 'Terá duas seções - a Seção de Problemas e a Seção de Encontros');
INSERT INTO `lang_definitions` VALUES (112812, 5741, 19, 'Isso ajudará mais tarde na solução de problemas que podem surgir com a configuração do módulo de Pedidos de Procedimento');
INSERT INTO `lang_definitions` VALUES (112813, 5742, 19, 'Irá abrir a seção Criar Nova Mensagem');
INSERT INTO `lang_definitions` VALUES (112814, 5743, 19, 'Isso o levará para a página de inscrição do MedEx');
INSERT INTO `lang_definitions` VALUES (112815, 5744, 19, 'Ele então aparecerá no widget Alergias no Painel do Paciente, bem como em alergias na página Problemas');
INSERT INTO `lang_definitions` VALUES (112816, 5745, 19, 'Ele então aparecerá no widget Medicamentos no Painel do Paciente, bem como em Medicamentos na página de Problemas');
