INSERT INTO `lang_definitions` VALUES (114881, 8068, 19, 'Preste atenção para o \"Terminado com\" checkboxes. Depois que os seguros sejam marcados complete então nós começaremos pedindo para o doente que pagasse o equilíbrio restante; se você não marca tudo dos seguros complete então a quantia restante não será colecionada! Também se há um equilíbrio que o doente deveria pagar, então fixe a data de vencimento adequadamente, como isto afetará o idioma que se aparece em declarações pacientes.');
INSERT INTO `lang_definitions` VALUES (114882, 8069, 19, 'Preste atenção às caixas de seleção \"Concluído com\". Depois que os seguros forem marcados como concluídos, então começaremos a solicitar ao paciente o pagamento do saldo remanescente; se você deixar de marcar todos os seguros como concluídos, então o valor restante não será cobrado! Além disso, se houver um saldo que o paciente deve pagar, então defina a data de vencimento de forma adequada, pois isso afetará a linguagem que aparece nas declarações do paciente');
