INSERT INTO `lang_definitions` VALUES (117458, 10954, 19, 'O botão \'Limpar\' removerá todas as anotações');
INSERT INTO `lang_definitions` VALUES (117459, 10955, 19, 'A janela \'Editar\' é dividida em duas colunas, \'Ativo\' e \'Inativo\'. Os grupos (AROs) listados na coluna ativa são essos grupos aos quais o usuário pertence a');
INSERT INTO `lang_definitions` VALUES (117460, 10956, 19, 'A seção \'Selecionar Códigos\' agora terá todos os códigos CPT e ICD que você inseriu agrupados nas categorias que você decidiu');
INSERT INTO `lang_definitions` VALUES (117461, 10957, 19, 'A tecla * Tab * cria cada entrada');
INSERT INTO `lang_definitions` VALUES (117462, 10958, 19, 'O Formulário de Reivindicação 1500 também pode ser usado para relatar dados de encontros com pacientes para agências federais, estaduais e / ou outras agências de saúde pública');
INSERT INTO `lang_definitions` VALUES (117463, 10959, 19, 'O 837P (Profissional) é o formato padrão usado por profissionais de saúde e fornecedores para transmitir eletronicamente alegações de saúde');
INSERT INTO `lang_definitions` VALUES (117464, 10960, 19, 'A capacidade de vincular problemas individuais a encontros com pacientes permitirá que o usuário determine rapidamente o resultado do problema ao longo do tempo');
INSERT INTO `lang_definitions` VALUES (117465, 10961, 19, 'A declaração acima falhou');
INSERT INTO `lang_definitions` VALUES (117466, 10962, 19, 'A página ACL de duas seções');
INSERT INTO `lang_definitions` VALUES (117467, 10963, 19, 'Os valores reais que serão exibidos devem existir no banco de dados');
INSERT INTO `lang_definitions` VALUES (117468, 10964, 19, 'Os testes ou procedimentos reais que podem ser pesquisados e solicitados são destacados em amarelo');
INSERT INTO `lang_definitions` VALUES (117469, 10965, 19, 'O ícone Adicionar é usado para configurar um nível que será um descendente direto deste nível');
INSERT INTO `lang_definitions` VALUES (117470, 10966, 19, 'A vantagem de integrar os resultados ao prontuário do paciente como dados estruturados é a capacidade de manipulá-los para ver as tendências em um local conveniente, para traçar gráficos com os dados e usá-los na análise de dados');
INSERT INTO `lang_definitions` VALUES (117471, 10967, 19, 'A vantagem de digitalizar os resultados no gráfico é a simplicidade - nenhuma configuração é necessária, a não ser definir um diretório / pasta no prontuário do paciente em Documentos onde o resultado será armazenado. Sendo dados não estruturados, eles não têm as vantagens acima e não atenderão aos critérios de uso significativo para entrada de pedido do provedor computadorizado (CPOE)');
INSERT INTO `lang_definitions` VALUES (117472, 10968, 19, 'A solução Allscripts integra o site Allscripts ePrescribe com openEMR');
INSERT INTO `lang_definitions` VALUES (117473, 10969, 19, 'A American Medical Association definiu 9 painéis que podem ser solicitados. Cada painel contém vários testes agrupados');
INSERT INTO `lang_definitions` VALUES (117474, 10970, 19, 'O valor será exibido na coluna Pagamento ou Ajuste, conforme o caso');
INSERT INTO `lang_definitions` VALUES (117475, 10971, 19, 'O certificado do servidor Apache SSL e a chave pública');
INSERT INTO `lang_definitions` VALUES (117476, 10972, 19, 'O aplicativo gera um desafio - um número aleatório e o passa para a chave USB junto com o nonce e a soma de verificação armazenados no aplicativo');
INSERT INTO `lang_definitions` VALUES (117477, 10973, 19, 'O aplicativo então usa a chave pública que o dispositivo USB enviou no registro para verificar a resposta');
INSERT INTO `lang_definitions` VALUES (117478, 10974, 19, 'As mudanças no status da consulta e as criações de encontros são gerenciadas através do Patient Tracker');
INSERT INTO `lang_definitions` VALUES (117479, 10975, 19, 'O nome Autentificação ou chave API para a conta selecionada. Nome de autenticação para Authorize.Net e segredo API para Stripe');
INSERT INTO `lang_definitions` VALUES (117480, 10976, 19, 'A coluna Saldo ficaria vazia');
INSERT INTO `lang_definitions` VALUES (117481, 10977, 19, 'O objetivo básico do aplicativo autenticador é gerar um código de 20 bytes (160 bits) codificado em base32 usando uma função hash segura, SHA-1, e é chamado de HMAC-SHA1 (código de autenticação de mensagem baseado em hash)');
INSERT INTO `lang_definitions` VALUES (117482, 10978, 19, 'A base para o CCR é um Formulário de Referência de Cuidados ao Paciente desenvolvido pelo Departamento de Saúde Pública de Massachusetts');
INSERT INTO `lang_definitions` VALUES (117483, 10979, 19, 'A coluna Data de cobrança / pagador mostrará a data em que o pagamento do item de linha foi recebido e o nome do pagador - seguro ou paciente');
INSERT INTO `lang_definitions` VALUES (117484, 10980, 19, 'A coluna Data de cobrança / pagador mostrará a data em que o item de linha foi cobrado e o pagador - seguro ou paciente');
INSERT INTO `lang_definitions` VALUES (117485, 10981, 19, 'O corpo contém os dados clínicos que podem ser estruturados e organizados como uma ou mais seções ou podem ser um blob não estruturado de dados');
INSERT INTO `lang_definitions` VALUES (117486, 10982, 19, 'As caixas Body Site, Administer Via e Laterality podem ser deixadas como Unassigned');
INSERT INTO `lang_definitions` VALUES (117487, 10983, 19, 'O grupo inferior consiste nos Copays');
INSERT INTO `lang_definitions` VALUES (117488, 10984, 19, 'A coluna Categoria será Custom Top Group e será destacada em rosa');
INSERT INTO `lang_definitions` VALUES (117489, 10985, 19, 'A coluna Categoria mostrará Pedido, indicando que é um pedido');
INSERT INTO `lang_definitions` VALUES (117490, 10986, 19, 'A categoria será o resultado');
INSERT INTO `lang_definitions` VALUES (117491, 10987, 19, 'O CDA é um documento de texto simples que é codificado usando a Extensible Markup Language (XML) e contém um cabeçalho e corpo');
INSERT INTO `lang_definitions` VALUES (117492, 10988, 19, 'O certificado da Autoridade de Certificação');
INSERT INTO `lang_definitions` VALUES (117493, 10989, 19, 'A coluna Cobrança ficaria em branco');
INSERT INTO `lang_definitions` VALUES (117494, 10990, 19, 'A cobrança será o valor real sendo cobrado para cada item de linha');
INSERT INTO `lang_definitions` VALUES (117495, 10991, 19, 'O arquivo de reivindicação:');
INSERT INTO `lang_definitions` VALUES (117496, 10992, 19, 'O formulário CMS 1500 possui 33 caixas e é dividido em duas seções');
INSERT INTO `lang_definitions` VALUES (117497, 10993, 19, 'A coluna Código deve ter 905, o código de identificação específico do fornecedor que foi inserido anteriormente');
INSERT INTO `lang_definitions` VALUES (117498, 10994, 19, 'A coluna Código ficará vazia porque os itens listados como um Grupo não são usados no relatório real de resultados e, portanto, não têm um número de código distinto');
INSERT INTO `lang_definitions` VALUES (117499, 10995, 19, 'O Código será R905, o valor do Código de Identificação que foi inserido para o Resultado Discreto');
INSERT INTO `lang_definitions` VALUES (117500, 10996, 19, 'O código que você digitou não era válido');
INSERT INTO `lang_definitions` VALUES (117501, 10997, 19, 'O pacote SNOMED da extensão US testada compatível já foi instalado');
INSERT INTO `lang_definitions` VALUES (117502, 10998, 19, 'A célula de Contatos tem vários bits de informações de contato, como números de telefone, e-mail, etc.');
INSERT INTO `lang_definitions` VALUES (117503, 10999, 19, 'O Documento de Continuidade de Cuidados (CCD) e o Registro de Continuidade de Cuidados (CCR) foram ambos selecionados como formatos aceitáveis para extrair informações para resumos de cuidados clínicos como parte do Estágio 1 de Uso Significativo');
INSERT INTO `lang_definitions` VALUES (117504, 11000, 19, 'O Continuity of Care Record (CCR) foi desenvolvido em conjunto pela ASTM International - uma organização que está envolvida no desenvolvimento e entrega de consenso voluntário, a Massachusetts Medical Society (MMS), a Health Information Management and Systems Society (HIMSS), a American Academy of Family Physicians (AAFP) e American Academy of Pediatrics');
INSERT INTO `lang_definitions` VALUES (117505, 11001, 19, 'O Registro de Continuidade de Cuidados (CCR) é o registro clínico do estado de saúde atual e histórico do paciente');
INSERT INTO `lang_definitions` VALUES (117506, 11002, 19, 'O conjunto de dados principal consiste em');
INSERT INTO `lang_definitions` VALUES (117507, 11003, 19, 'A chave privada correspondente');
INSERT INTO `lang_definitions` VALUES (117508, 11004, 19, 'O relatório criado pode conter muitas ou poucas informações com base na necessidade');
INSERT INTO `lang_definitions` VALUES (117509, 11005, 19, 'O método de autenticação atual para a seção de usuário conectado agora apresentará os métodos ativados');
INSERT INTO `lang_definitions` VALUES (117510, 11006, 19, 'O método de autenticação atual lista todos os métodos que estão ativos');
INSERT INTO `lang_definitions` VALUES (117511, 11007, 19, 'A folha de honorários personalizada pode ser usada. Se e quando você encontrar um código que não existe na seção \"Selecionar códigos\" personalizada, você pode usar sempre a seção \"Pesquisar códigos adicionais\"');
INSERT INTO `lang_definitions` VALUES (117512, 11008, 19, 'O nível de item favorito personalizado deve ser descendente direto ou filho do grupo favorito personalizado relevante');
INSERT INTO `lang_definitions` VALUES (117513, 11009, 19, 'O agrupamento personalizado também te permiterá agrupar dois painéis de testes reconhecidos em um grupo personalizado e, assim, organizá-los juntos, por exemplo, um grupo personalizado de Laboratórios Preop pode conter dois painéis, CBC e Painel Renal');
INSERT INTO `lang_definitions` VALUES (117514, 11010, 19, 'O painel é o local central para acesso conveniente ao prontuário médico do paciente');
INSERT INTO `lang_definitions` VALUES (117515, 11011, 19, 'A página do painel é dividida em três seções');
INSERT INTO `lang_definitions` VALUES (117516, 11012, 19, 'O teste de integridade de dados falhou para este formulário');
INSERT INTO `lang_definitions` VALUES (117517, 11013, 19, 'A seção de dados da página do painel lista todos os itens pertinentes relacionados a um paciente');
INSERT INTO `lang_definitions` VALUES (117518, 11014, 19, 'O lembrete com data começará a aparecer 5 dias antes da data do lembrete em Lembretes com data');
INSERT INTO `lang_definitions` VALUES (117519, 11015, 19, 'O tipo de código padrão a ser pesquisado na Folha de Taxas');
INSERT INTO `lang_definitions` VALUES (117520, 11016, 19, 'A folha de taxas padrão pode ser modificada e personalizada para torná-la mais útil');
INSERT INTO `lang_definitions` VALUES (117521, 11017, 19, 'A folha de taxas padrão é dividida em várias seções e é projetada para ser preenchida de cima para baixo com o botão Salvar no final');
INSERT INTO `lang_definitions` VALUES (117522, 11018, 19, 'O formulário padrão pode ser personalizado editando-o em Administração> Layouts');
INSERT INTO `lang_definitions` VALUES (117523, 11019, 19, 'O padrão tem dois botões que são definidos para \'Novo paciente\' e \'Estabelecido\' paciente');
INSERT INTO `lang_definitions` VALUES (117524, 11020, 19, 'A instalação padrão tem seis grupos - Contabilidade, Administradores, Clínicos, Login de emergência, Front Office e Médicos');
INSERT INTO `lang_definitions` VALUES (117525, 11021, 19, 'A instalação padrão possui os seguintes itens');
INSERT INTO `lang_definitions` VALUES (117526, 11022, 19, 'A instalação padrão lista 5 tipos de problemas que podem ser documentados');
INSERT INTO `lang_definitions` VALUES (117527, 11023, 19, 'A instalação padrão não fará a ligação automaticamente');
INSERT INTO `lang_definitions` VALUES (117528, 11024, 19, 'O padrão é \'Padrão\' geralmente usado para refletir as taxas cobradas para cobrança de seguro. Você pode ter um valor diferente cobrado para pagamento com cartão de crédito e pagamento em dinheiro');
INSERT INTO `lang_definitions` VALUES (117529, 11025, 19, 'O padrão é Normal, ou seja, é visível para todos. Selecionar Alta irá restringi-lo a usuários pertencentes aos grupos de Médicos e Administradores por padrão');
INSERT INTO `lang_definitions` VALUES (117530, 11026, 19, 'O tipo de problema padrão é definido como Problema');
INSERT INTO `lang_definitions` VALUES (117531, 11027, 19, 'O centro de mensagens padrão é dividido em três seções - Mensagens, Lembretes e Recalls');
INSERT INTO `lang_definitions` VALUES (117532, 11028, 19, 'Os valores padrão para os provedores de renderização podem ser definidos');
INSERT INTO `lang_definitions` VALUES (117533, 11029, 19, 'o Código de Negação é');
INSERT INTO `lang_definitions` VALUES (117534, 11030, 19, 'o código do grupo de negação é');
INSERT INTO `lang_definitions` VALUES (117535, 11031, 19, 'A coluna Descrição exibe a breve descrição que foi inserida, testes de química de soro');
INSERT INTO `lang_definitions` VALUES (117536, 11032, 19, 'A coluna Descrição refletirá o valor da descrição que foi inserido anteriormente');
INSERT INTO `lang_definitions` VALUES (117537, 11033, 19, 'A descrição deve dizer resultado de ácido úrico no soro');
INSERT INTO `lang_definitions` VALUES (117538, 11034, 19, 'A descrição irá detalhar o tipo de pagamento ou ajuste - dinheiro, cheque, eletrônico, etc.');
INSERT INTO `lang_definitions` VALUES (117539, 11035, 19, 'O formulário de destino foi fechado');
INSERT INTO `lang_definitions` VALUES (117540, 11037, 19, 'A forma de destino estava fechada; Eu não posso agir em sua seleção.');
INSERT INTO `lang_definitions` VALUES (117541, 11038, 19, 'A diferença entre os dois é que para um painel de testes que são ordenados juntos, os testes individuais são representados apenas por Resultado Discreto e esses testes não podem ser pedidos separadamente, a menos que também tenham sido configurados como testes individuais');
INSERT INTO `lang_definitions` VALUES (117542, 11039, 19, 'O nível de resultados discretos deve ser descendente direto ou filho de um nível de ordem de procedimento para a exibição adequada dos resultados');
INSERT INTO `lang_definitions` VALUES (117543, 11040, 19, 'Os resultados discretos para cada painel conterão os nomes dos testes individuais para conter os valores dos resultados retornados - WBC, hemoglobina, plaquetas, sódio, potássio, etc.');
INSERT INTO `lang_definitions` VALUES (117544, 11041, 19, 'A janela de exibição pode ser redimensionada clicando e arrastando o canto inferior direito da janela');
INSERT INTO `lang_definitions` VALUES (117545, 11042, 19, 'A opção Cada Compromisso permitirá um novo encontro independentemente da visita no mesmo dia');
INSERT INTO `lang_definitions` VALUES (117546, 11043, 19, 'O botão Encounter Preview é útil para mostrar formulários de layout de tipo de encontro como vistos ao usar o formulário em um encontro. Observe que este recurso só é útil para mostrar formulários de encontro e não exibirá formulários de sistema como dados demográficos');
INSERT INTO `lang_definitions` VALUES (117547, 11044, 19, 'A seção de encontros exibirá a data do encontro, bem como a apresentação da reclamação');
INSERT INTO `lang_definitions` VALUES (117548, 11045, 19, 'O resultado final foi uma coleção confusa de documentos contendo informações ambíguas e / ou conflitantes');
INSERT INTO `lang_definitions` VALUES (117549, 11046, 19, 'A caixa pop-up Inserir detalhes abrirá no modo Adicionar');
INSERT INTO `lang_definitions` VALUES (117550, 11047, 19, 'O pop-up Inserir detalhes do provedor ficará visível');
INSERT INTO `lang_definitions` VALUES (117551, 11048, 19, 'A coleção inteira de ACOs forma a Lista de Controle de Acesso (ACL)');
INSERT INTO `lang_definitions` VALUES (117552, 11049, 19, 'A entidade para um item favorito personalizado é a entidade escolhida para o grupo de favoritos personalizados e não pode ser alterada');
INSERT INTO `lang_definitions` VALUES (117553, 11050, 19, 'A entidade que realiza este procedimento');
INSERT INTO `lang_definitions` VALUES (117554, 11051, 19, 'As entradas contêm dados usados para processamento posterior do computador');
INSERT INTO `lang_definitions` VALUES (117555, 11052, 19, 'As entradas destacadas em amarelo podem ser solicitadas como um teste ou procedimento, aquelas destacadas em rosa podem ser solicitadas como um grupo personalizado');
INSERT INTO `lang_definitions` VALUES (117556, 11053, 19, 'O EP, hospital elegível ou CAH que recebe um paciente de outro ambiente de cuidados ou prestador de cuidados ou acredita que um encontro é relevante deve realizar reconciliação de medicamentos');
INSERT INTO `lang_definitions` VALUES (117557, 11054, 19, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento (Medida A)');
INSERT INTO `lang_definitions` VALUES (117558, 11055, 19, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento (Medida B)');
INSERT INTO `lang_definitions` VALUES (117559, 11056, 19, 'O EP, hospital elegível ou CAH que faz a transição de seu paciente para outro ambiente de cuidado ou prestador de cuidado ou encaminha seu paciente para outro prestador de cuidado deve fornecer um resumo do registro de cuidado para cada transição de cuidado ou encaminhamento');
INSERT INTO `lang_definitions` VALUES (117560, 11057, 19, 'O evento(s) foi aprovado.');
INSERT INTO `lang_definitions` VALUES (117561, 11058, 19, 'O evento(s) foi escondido.');
INSERT INTO `lang_definitions` VALUES (117562, 11059, 19, 'O dados exportado se aparece na área de texto abaixo. Você pode copiar e pode colar isto em um e-mail ou para qualquer outro destino desejado.');
INSERT INTO `lang_definitions` VALUES (117563, 11060, 19, 'Os dados exportados aparecem na área de texto abaixo. Você pode copiar e colar isso em um e-mail ou em qualquer outro destino desejado (ou) baixar o link abaixo');
INSERT INTO `lang_definitions` VALUES (117564, 11061, 19, 'O dados exportado se aparece na área de texto abaixo. Você pode copiar e pode colar isto em um e-mail ou para qualquer outro destino desejado.');
INSERT INTO `lang_definitions` VALUES (117565, 11062, 19, 'Os dados exportados aparecem na área de texto abaixo. Você pode copiar e colar isto em um e-mail ou em qualquer outro destino desejado. {{MARQUE PARA DELEÇÃO DURANTE A PRÓXIMA CONSTRUÇÃO DA TRADUÇÃO}}');
INSERT INTO `lang_definitions` VALUES (117566, 11063, 19, 'Os recursos de uma instalação habilitada para MedEx são explicados neste vídeo');
INSERT INTO `lang_definitions` VALUES (117567, 11065, 19, 'O arquivo não pôde ser salvo no CouchDB');
INSERT INTO `lang_definitions` VALUES (117568, 11066, 19, 'O arquivo não pode ser renomear com sucesso, esse erro geralmente está relacionado a problemas de permissões no sistema de armazenamento');
INSERT INTO `lang_definitions` VALUES (117569, 11067, 19, 'O arquivo não pôde ser armazenado com sucesso, este erro geralmente está relacionado a problemas de permissões no sistema de armazenamento');
INSERT INTO `lang_definitions` VALUES (117570, 11068, 19, 'A seção de filtro pode ser escondida ou revelada clicando na ponta da seta no canto inferior direito');
INSERT INTO `lang_definitions` VALUES (117571, 11069, 19, 'Os resultados filtrados aparecerão na seção abaixo deles');
INSERT INTO `lang_definitions` VALUES (117572, 11071, 19, 'O primeiro gráfico (\"alvo\") é aquele considerado o mais completo e preciso. As seções demográficas, históricas e de seguro para este serão mantidas.');
INSERT INTO `lang_definitions` VALUES (117573, 11072, 19, 'A primeira coluna contém o nome do Grupo / Categoria que será exibido no botão');
INSERT INTO `lang_definitions` VALUES (117574, 11073, 19, 'A primeira coluna é o nome que você deu a esta entrada, ou seja, Química do Soro. Uma barra vertical precederá o nome real. Isso indica que não há descendentes ou filhos para esta entrada');
INSERT INTO `lang_definitions` VALUES (117575, 11074, 19, 'As primeiras quatro seções lidam com a criação de ordens de procedimento de uma maneira estruturada para facilitar a ordem de testes e inserir os resultados retornados manualmente');
INSERT INTO `lang_definitions` VALUES (117576, 11075, 19, 'A primeira linha mostrará a data do encontro e o motivo, bem como o provedor para esse encontro');
INSERT INTO `lang_definitions` VALUES (117577, 11076, 19, 'A primeira seção permite que você vincule esta mensagem a um paciente, se desejar');
INSERT INTO `lang_definitions` VALUES (117578, 11077, 19, 'O primeiro segmento em cada mensagem HL7 é sempre o cabeçalho da mensagem, um segmento que transmite os metadados da mensagem como quem a enviou e quando. O cabeçalho da mensagem é indicado nas três primeiras letras do segmento como MSH');
INSERT INTO `lang_definitions` VALUES (117579, 11078, 19, 'O primeiro passo é se inscrever para uma conta de produção de mensagens diretas com EMR Direct, registrando-se em seu site');
INSERT INTO `lang_definitions` VALUES (117580, 11079, 19, 'A primeira etapa é fazer o download da versão SNOMED CT. O acesso ao SNOMED CT é fornecido pela IHTSDO e seus países membros. Para mais informações, veja');
INSERT INTO `lang_definitions` VALUES (117581, 11080, 19, 'O primeiro passo é fazer o download da versão VALUESET. O acesso ao VALUESET é fornecido pela NLM. Apenas o conjunto de valores para Profissionais Elegíveis precisa ser baixado e deve ser baixado no formato XML da coluna Sorted By CMS ID. Para obter mais detalhes, veja o link abaixo');
INSERT INTO `lang_definitions` VALUES (117582, 11081, 19, 'A primeira etapa é abrir uma conta no site do Unified Medical Language System');
INSERT INTO `lang_definitions` VALUES (117583, 11082, 19, 'A primeira etapa é planejar o que a seção \'Selecionar Códigos\' da sua Folha de Taxas deve exibir');
INSERT INTO `lang_definitions` VALUES (117584, 11083, 19, 'A primeira etapa é selecionar um tipo de transação');
INSERT INTO `lang_definitions` VALUES (117585, 11084, 19, 'A primeira etapa seria criar uma entrada de nível superior. Faça isso clicando no botão nível superior Adicionar');
INSERT INTO `lang_definitions` VALUES (117586, 11085, 19, 'A primeira guia é a guia de referência que constitui a referência que está sendo feita');
INSERT INTO `lang_definitions` VALUES (117587, 11086, 19, 'Os primeiros dois números na primeira e segunda colunas serão usados para determinar a ordem de classificação dos botões e das listas que estão presentes no pop-up');
