INSERT INTO `lang_definitions` VALUES (117604, 11104, 19, 'O seguinte ocorreu');
INSERT INTO `lang_definitions` VALUES (117605, 11105, 19, 'Os problemas a seguir têm os mesmos códigos de diagnóstico. Problemas de encontro não serão atualizados. Por favor, em vez disso, use a interface de encontro');
INSERT INTO `lang_definitions` VALUES (117606, 11106, 19, 'As etapas a seguir ajudarão a personalizar a Folha de Taxas para imitar o antigo superbill de papel com uma lista de códigos CPT4 e ICD organizados em categorias');
INSERT INTO `lang_definitions` VALUES (117607, 11107, 19, 'O grupo (ARO) que você criou agora aparecerá em ordem alfabética na seção \'Grupos e controles de acesso\'');
INSERT INTO `lang_definitions` VALUES (117608, 11108, 19, 'O cabeçalho define o contexto para o documento clínico como um todo');
INSERT INTO `lang_definitions` VALUES (117609, 11109, 19, 'A seção de cabeçalho revelará informações específicas do paciente na maioria das páginas relacionadas ao prontuário do paciente');
INSERT INTO `lang_definitions` VALUES (117610, 11110, 19, 'O Formulário de Reivindicação de Seguro Saúde é frequentemente referido pelo número de formulário CMS 1500 (HCFA 1500)');
INSERT INTO `lang_definitions` VALUES (117611, 11111, 19, 'O arquivo de ajuda está dividido nas seguintes seções');
INSERT INTO `lang_definitions` VALUES (117612, 11112, 19, 'O arquivo de ajuda lá irá guiá-lo nas etapas adicionais de configuração dos testes de laboratório');
INSERT INTO `lang_definitions` VALUES (117613, 11113, 19, 'O ícone de ajuda permitirá que você acesse a ajuda sensível ao contexto para cada uma das páginas acessadas');
INSERT INTO `lang_definitions` VALUES (117614, 11114, 19, 'O nome do host da máquina do repositório de auditoria ATNA');
INSERT INTO `lang_definitions` VALUES (117615, 11116, 19, 'O código de identificação deve ser único para que os resultados sejam exibidos corretamente, você pode apenas usar R905 como exemplo');
INSERT INTO `lang_definitions` VALUES (117616, 11117, 19, 'O código de identificação deve ser único, se for enviar para um laboratório externo, o código de identificação fornecido pelo fornecedor deve ser inserido. Vamos inserir um valor único arbitrário - WWT01');
INSERT INTO `lang_definitions` VALUES (117617, 11118, 19, 'O código de identificação é um código específico do fornecedor que identifica este procedimento ou resultado. Você pode ver exemplos disso nos papéis do laboratório que os laboratórios usam');
INSERT INTO `lang_definitions` VALUES (117618, 11119, 19, 'O código de identificação é essencial para a exibição adequada e tabulação dos resultados');
INSERT INTO `lang_definitions` VALUES (117619, 11120, 19, 'O código de identificação de R34392-1, um número arbitrário, neste caso o código de identificação precedido por R para indicar o resultado e seguido por 1 para indicar o primeiro na sequência, pode ser qualquer coisa única que você escolher');
INSERT INTO `lang_definitions` VALUES (117620, 11121, 19, 'As informações inseridas aqui são usadas para exibir um resumo do encontro. Também é usado para fins de cobrança');
INSERT INTO `lang_definitions` VALUES (117621, 11122, 19, 'As informações inseridas neste formulário serão usadas para preencher uma reclamação em papel');
INSERT INTO `lang_definitions` VALUES (117622, 11123, 19, 'As informações fornecidas no Formulário de Novo Encontro e Folha de Taxas no openEMR são usadas para gerar a reclamação em papel, bem como as reclamações eletrônicas');
INSERT INTO `lang_definitions` VALUES (117623, 11124, 19, 'Os esforços iniciais levaram à criação de Guias de Implementação (IGs) duplicados e conflitantes publicados por diferentes organizações de padrões');
INSERT INTO `lang_definitions` VALUES (117624, 11125, 19, 'A tela inicial permite que você selecione um método, oferecendo-lhe essas duas opções');
INSERT INTO `lang_definitions` VALUES (117625, 11126, 19, 'A janela inicial é a página de procura de fatura. Ao topo você pode entrar em uma fonte (por exemplo confira número), pague data e confira quantia. A razão para a fonte e data de pagamento está de forma que você dom \'t têm que entrar neles inúmeras vezes para cada reivindicação. A quantia na que você entra será diminuída para cada fatura que é determinada parte do pagamento, e esperançosamente terminará a zero quando você for terminado.');
INSERT INTO `lang_definitions` VALUES (117626, 11127, 19, 'A entrada deve ser um arquivo CSV com 3 colunas: ID do layout, tipo de código e código');
INSERT INTO `lang_definitions` VALUES (117627, 11128, 19, 'O diretório de instalação precisa ser criado');
INSERT INTO `lang_definitions` VALUES (117628, 11129, 19, 'A versão SNOMED internacional instalada não é compatível com o pacote SNOMED da extensão dos EUA testado');
INSERT INTO `lang_definitions` VALUES (117629, 11130, 19, 'A versão SNOMED internacional instalada está desatualizada e não é compatível com o arquivo SNOMED de extensão dos EUA testado');
INSERT INTO `lang_definitions` VALUES (117630, 11131, 19, 'A versão instalada e os arquivos testados são os mesmos');
INSERT INTO `lang_definitions` VALUES (117631, 11132, 19, 'A versão instalada é uma versão mais recente do que os arquivos testados');
INSERT INTO `lang_definitions` VALUES (117632, 11133, 19, 'O manual de instruções sobre como preencher o formulário CMS 1500 pode ser encontrado aqui');
INSERT INTO `lang_definitions` VALUES (117633, 11134, 19, 'O endereço IP do (s) seu (s) controlador (es) de domínio');
INSERT INTO `lang_definitions` VALUES (117634, 11135, 19, 'Os problemas podem ser inseridos de duas maneiras');
INSERT INTO `lang_definitions` VALUES (117635, 11136, 19, 'A seção de problemas exibirá todos os problemas inseridos para o paciente e exibirá o tipo de problema, seu título e uma descrição');
INSERT INTO `lang_definitions` VALUES (117636, 11137, 19, 'Os itens listados na coluna \'Ativo\' delineiam os privilégios deste grupo (ARO) e constituem esta Lista de Controle de Acesso (ACL) deste grupo');
INSERT INTO `lang_definitions` VALUES (117637, 11138, 19, 'Os itens que têm asteriscos após eles são obrigatórios');
INSERT INTO `lang_definitions` VALUES (117638, 11140, 19, 'O rótulo que aparece para o usuário sobre a forma');
INSERT INTO `lang_definitions` VALUES (117639, 11141, 19, 'A última célula da linha no Encontro');
INSERT INTO `lang_definitions` VALUES (117640, 11142, 19, 'A última linha deste bloco de encontro dará ao encontro os totais de Encargos, Pagamentos, Ajustes e o Saldo');
INSERT INTO `lang_definitions` VALUES (117641, 11143, 19, 'A última seção trata de pedidos eletrônicos');
INSERT INTO `lang_definitions` VALUES (117642, 11144, 19, 'A data da última visita será preenchida automaticamente');
INSERT INTO `lang_definitions` VALUES (117643, 11145, 19, 'A versão mais recente é FHIR - Fast Healthcare Interoperability Resources - é uma estrutura de padrões de próxima geração criada pelo HL7. Isso está ganhando popularidade, mas ainda não foi amplamente implementado');
INSERT INTO `lang_definitions` VALUES (117644, 11147, 19, 'O comprimento não deve exceder o seguinte número de caracteres');
INSERT INTO `lang_definitions` VALUES (117645, 11150, 19, 'A tabela de registro mostrará uma lista de ambos mensagens e lembretes datados, se houver');
INSERT INTO `lang_definitions` VALUES (117646, 11151, 19, 'O código LOINC para ácido úrico sérico é 3084-1, LOINC refere-se a ele como urato no soro ou plasma');
INSERT INTO `lang_definitions` VALUES (117647, 11152, 19, 'A mesclagem não será executada a menos que SSN e DOB para que os dois gráficos sejam idênticos');
INSERT INTO `lang_definitions` VALUES (117648, 11153, 19, 'A mensagem não pôde ser enviada neste momento');
INSERT INTO `lang_definitions` VALUES (117649, 11154, 19, 'O status da mensagem será Novo, pois é uma nova mensagem que está sendo criada');
INSERT INTO `lang_definitions` VALUES (117650, 11155, 19, 'As mensagens que foram enviadas pelo usuário naquele dia serão exibidas na tabela abaixo');
INSERT INTO `lang_definitions` VALUES (117651, 11156, 19, 'O centro de mensagens consolida convenientemente as opções de comunicação em um só lugar');
INSERT INTO `lang_definitions` VALUES (117652, 11157, 19, 'O centro de mensagens será aberto com a guia Mensagens ativada e exibirá as mensagens do usuário conectado, conforme indicado pela legenda Minhas mensagens');
INSERT INTO `lang_definitions` VALUES (117653, 11158, 19, 'A informação mínima necessária para criar um novo encontro é selecionar uma categoria de visita');
INSERT INTO `lang_definitions` VALUES (117654, 11159, 19, 'As opções de faturamento diversas para o formulário HCFA-1500 são usadas para fornecer informações adicionais para uma reclamação individual');
INSERT INTO `lang_definitions` VALUES (117655, 11160, 19, 'O método mais comum é chamado de autorização de 2 fatores ou 2FA');
INSERT INTO `lang_definitions` VALUES (117656, 11161, 19, 'A questão mais importante que precisa ser tratada é com quem você está tentando se conectar e o que precisa acontecer no final. A maioria dos grandes laboratórios não lidará com práticas individuais; em tais casos, um fornecedor terceirizado atuará como um intermediário que será responsável por estabelecer uma conexão entre a clínica e o laboratório por meio de sua interface (do intermediário)');
INSERT INTO `lang_definitions` VALUES (117657, 11162, 19, 'O fabricante mais popular de chaves de segurança é a Yubico, que oferece versões USB regulares, bem como aquelas feitas para dispositivos que requerem conexões USB-C, como os sistemas Mac OS mais recentes da Apple');
INSERT INTO `lang_definitions` VALUES (117658, 11163, 19, 'O Sistema Open-source Médico e Hospitalar de Saúde mais popular que existe.');
INSERT INTO `lang_definitions` VALUES (117659, 11164, 19, 'A célula do nome contém o nome, data de nascimento, ID do paciente e data da última visita');
INSERT INTO `lang_definitions` VALUES (117660, 11165, 19, 'O bloco narrativo contém informações que são processadas como texto legível');
INSERT INTO `lang_definitions` VALUES (117661, 11166, 19, 'O National Uniform Claim Committee (NUCC) é responsável pela manutenção do Formulário de Reivindicação 1500');
INSERT INTO `lang_definitions` VALUES (117662, 11167, 19, 'A barra de navegação permite navegar rapidamente para várias partes do registro médico do paciente');
