INSERT INTO `lang_definitions` VALUES (117665, 11171, 19, 'Os novos campos de senha não são os mesmos');
INSERT INTO `lang_definitions` VALUES (117666, 11173, 19, 'O nome do parceiro NewCrop eRx, o nome NewCrop eRx e a senha NewCrop eRx serão fornecidos pelo fornecedor');
INSERT INTO `lang_definitions` VALUES (117667, 11174, 19, 'A próxima caixa é Body Site, não relevante para um exame de sangue, mas pode ser mais útil, digamos, para rastrear injeções ou solicitar raios-X');
INSERT INTO `lang_definitions` VALUES (117668, 11175, 19, 'As próximas poucas linhas listarão todos os códigos E / M e CPT que foram cobrados, uma linha por código');
