INSERT INTO `lang_definitions` VALUES (117675, 11182, 19, 'O número de arquivos testados está incorreto. Coloque apenas o arquivo que deseja instalar / atualizar para');
INSERT INTO `lang_definitions` VALUES (117676, 11183, 19, 'O escritório: o celular permite que você indique que uma chamada foi feita');
