INSERT INTO `lang_definitions` VALUES (117678, 11185, 19, 'As opções de Contorno e Borda irão envolver uma linha em uma borda fina ou adicionar uma borda na parte inferior de um item');
INSERT INTO `lang_definitions` VALUES (117679, 11186, 19, 'A ordem em que a categoria, procedimento ou resultado aparece');
INSERT INTO `lang_definitions` VALUES (117680, 11187, 19, 'Os outros 4 tipos de transação são tipos de transação simples - Solicitação do paciente, Solicitação do médico, Legal e Cobrança');
INSERT INTO `lang_definitions` VALUES (117681, 11188, 19, 'Os outros segmentos contêm informações adicionais de forma estritamente estruturada');
INSERT INTO `lang_definitions` VALUES (117682, 11189, 19, 'A página será redirecionada para Demografia. Você pode editar o campo do país e clicar para NewCrop novamente');
INSERT INTO `lang_definitions` VALUES (117683, 11190, 19, 'A página que você requisitou não foi encontrada. Por favor, erifique se você digitou o URL corretamente');
INSERT INTO `lang_definitions` VALUES (117684, 11191, 19, 'As partes do programa às quais o acesso pode ser controlado são chamadas de Objetos de Controle de Acesso (ACOs)');
