INSERT INTO `lang_definitions` VALUES (117690, 11197, 19, 'Os lembretes do paciente foram enviados');
INSERT INTO `lang_definitions` VALUES (117691, 11198, 19, 'Os lembretes do paciente foram atualizados');
INSERT INTO `lang_definitions` VALUES (117692, 11199, 19, 'O paciente não estava logado ao enviar este formulário');
INSERT INTO `lang_definitions` VALUES (117693, 11200, 19, 'O paciente terá que alterar suas credenciais no primeiro login');
INSERT INTO `lang_definitions` VALUES (117694, 11201, 19, 'Os direitos dos pacientes');
INSERT INTO `lang_definitions` VALUES (117695, 11202, 19, 'O Pagamento, Ajuste e Saldo ficarão em branco, pois essas linhas refletem apenas as cobranças sendo feitas');
INSERT INTO `lang_definitions` VALUES (117696, 11203, 19, 'Os pagamentos lançados não podem ser inferiores a esta data. Isso garante que, depois de fazer o relatório final, ninguém poste para datas anteriores');
INSERT INTO `lang_definitions` VALUES (117697, 11204, 19, 'O cabeçalho do formulário pop-up agora exibirá Inserir detalhes para item favorito individual personalizado');
INSERT INTO `lang_definitions` VALUES (117698, 11205, 19, 'O portal possui dados para este paciente e formulário. Carregar agora?');
INSERT INTO `lang_definitions` VALUES (117699, 11206, 19, 'A mensagem anterior pode, no entanto, ser visualizada clicando no botão Exibir Log');
INSERT INTO `lang_definitions` VALUES (117700, 11207, 19, 'A página de Ordem de Procedimento lista os seguintes tipos de procedimento');
INSERT INTO `lang_definitions` VALUES (117701, 11208, 19, 'A solicitação de procedimento precisa ser estruturada de maneira hierárquica e um código de identificação exclusivo atribuído a ela que será então usado para rastrear e tabular o resultado');
INSERT INTO `lang_definitions` VALUES (117702, 11209, 19, 'O módulo de procedimentos é usado para fazer e revisar pedidos');
INSERT INTO `lang_definitions` VALUES (117703, 11210, 19, 'O processo de encaminhamento da mensagem é bastante semelhante ao de criação de uma nova mensagem');
INSERT INTO `lang_definitions` VALUES (117704, 11211, 19, 'A célula de progresso lista todas as ações junto com quaisquer notas associadas, se houver');
INSERT INTO `lang_definitions` VALUES (117705, 11213, 19, 'A chave de acesso pública para tokenização segura de autorização de cartão de crédito ou débito. Conformidade PCI');
INSERT INTO `lang_definitions` VALUES (117706, 11214, 19, 'O código QR também contém o nome do usuário e precisa ser capturado pelo usuário em seu dispositivo móvel usando um aplicativo autenticador');
INSERT INTO `lang_definitions` VALUES (117707, 11215, 19, 'A liberação do feed de dados brutos pode ser obtida em');
INSERT INTO `lang_definitions` VALUES (117708, 11216, 19, 'A célula de recall tem a data e o motivo do recall');
INSERT INTO `lang_definitions` VALUES (117709, 11217, 19, 'A guia Recalls tem dois botões New Recall e Recall Board');
INSERT INTO `lang_definitions` VALUES (117710, 11218, 19, 'O nível de recomendação é opcional');
INSERT INTO `lang_definitions` VALUES (117711, 11219, 19, 'A informação restante debaixo de só aplica se você está postando manualmente, ou se você está fazendo correções manuais.');
INSERT INTO `lang_definitions` VALUES (117712, 11220, 19, 'O lembrete para o dia atual terá um ícone de exclamação laranja');
INSERT INTO `lang_definitions` VALUES (117713, 11221, 19, 'Os lembretes estão vencidos terão um ícone de triângulo de exclamação vermelho');
INSERT INTO `lang_definitions` VALUES (117714, 11222, 19, 'O documento solicitado não está presente no local esperado no sistema de arquivos ou não há permissões suficientes para acessá-lo');
INSERT INTO `lang_definitions` VALUES (117715, 11223, 19, 'O documento pedido não está presente no local esperado no filesystem ou não há permissões suficientes para acessar isto.');
INSERT INTO `lang_definitions` VALUES (117716, 11224, 19, 'O resto pode ser deixado em branco se preferir');
INSERT INTO `lang_definitions` VALUES (117717, 11225, 19, 'O resto das caixas relacionadas ao serviço NewCrop eRx podem ser deixadas com os valores padrão');
INSERT INTO `lang_definitions` VALUES (117718, 11226, 19, 'A linha de resultados começará com um nome de ácido úrico sérico que será precedido por uma barra vertical indicando nenhum sucessor ou filho');
INSERT INTO `lang_definitions` VALUES (117719, 11227, 19, 'Os resultados não puderam ser carregados');
INSERT INTO `lang_definitions` VALUES (117720, 11228, 19, 'Os resultados, Resultado Discreto, serão o fruto deste ramo e criaremos um tal Resultado Discreto para cada um dos testes de componentes, Sódio, Potássio, Cloreto e Dióxido de Carbono');
INSERT INTO `lang_definitions` VALUES (117721, 11229, 19, 'As linhas contendo os códigos CPT4 têm várias caixas que precisam ser preenchidas para garantir o faturamento adequado de reclamações');
INSERT INTO `lang_definitions` VALUES (117722, 11230, 19, 'O problema médico salvo agora será listado como uma única linha na página de problemas principal em Problemas médicos');
INSERT INTO `lang_definitions` VALUES (117723, 11232, 19, 'O tempo de atualização da tela em segundos para a tela do quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (117724, 11234, 19, 'Os resultados da pesquisa são exibidos na seção \'Resultados da pesquisa\'');
INSERT INTO `lang_definitions` VALUES (117725, 11235, 19, 'O segundo gráfico (\"fonte\") terá suas seções demográficas, histórico e de seguros descartadas. Seus outros dados serão mesclados no gráfico de destino');
INSERT INTO `lang_definitions` VALUES (117726, 11236, 19, 'A segunda coluna contém as opções que serão exibidas quando o botão for clicado');
INSERT INTO `lang_definitions` VALUES (117727, 11237, 19, 'A segunda coluna é Categoria e deve dizer Grupo Superior para indicar sua posição como o item superior nesta árvore hierárquica particular que iremos construir');
INSERT INTO `lang_definitions` VALUES (117728, 11238, 19, 'A segunda seção permite que você escolha para quem deseja enviar a mensagem');
INSERT INTO `lang_definitions` VALUES (117729, 11239, 19, 'A segunda guia é um pouco ambiguamente chamada de Contra-referência, é o local para documentar a resposta recebida à referência que está sendo feita');
INSERT INTO `lang_definitions` VALUES (117730, 11240, 19, 'A seção chamada \'Pesquisa de fatura\' é onde você coloca seus parâmetros de pesquisa. Você pode pesquisar pelo nome do paciente, número do prontuário, número do encontro ou data do serviço, ou qualquer combinação destes. Você também pode selecionar se deseja ver todas as faturas, faturas em aberto ou apenas as faturas vencidas (pelo paciente). Clique no botão \'Pesquisar\' para realizar a pesquisa');
INSERT INTO `lang_definitions` VALUES (117731, 11241, 19, 'O código selecionado será adicionado à caixa de texto de codificação e a Descrição do código será adicionada à caixa de texto Título');
INSERT INTO `lang_definitions` VALUES (117732, 11242, 19, 'Os códigos selecionados irão aparecer na seção \'Códigos da Folha de Taxas Selecionados e Encargos para Encontro Atual\'');
INSERT INTO `lang_definitions` VALUES (117733, 11243, 19, 'As seleções nesta seção serão usadas para cobrar por este encontro');
INSERT INTO `lang_definitions` VALUES (117734, 11244, 19, 'A sequência é a ordem em que este item de ordem superior será exibido na página, 1 para denotar o primeiro grupo de nível superior');
INSERT INTO `lang_definitions` VALUES (117735, 11245, 19, 'O endereço do servidor será da forma');
INSERT INTO `lang_definitions` VALUES (117736, 11246, 19, 'A configuração para os testes de laboratório será descrita em detalhes, pequenas modificações nessas etapas serão necessárias para configurar os procedimentos no escritório e outros tipos de procedimento');
INSERT INTO `lang_definitions` VALUES (117737, 11247, 19, 'A Contra-referência, um tanto ambiguamente, é o espaço onde a resposta à referência feita pode ser documentada');
INSERT INTO `lang_definitions` VALUES (117738, 11248, 19, 'São copiadas a Fonte e colunas de Data da primeira página, tão normalmente você não precisará tocar esses. Você pode pôr uma quantia de pagamento na coluna de Pagamento, uma quantia de ajuste no Ajuste coluna, ou ambos. Você também pode clicar à direita o \"W\" para computar um valor de ajuste que escreve fora o resto do custo para aquele artigo de linha automaticamente.');
INSERT INTO `lang_definitions` VALUES (117739, 11249, 19, 'As colunas fonte e Data são copiadas da primeira página, portanto, normalmente você não precisará tocá-las. Você pode colocar um valor de pagamento na coluna Pagamento, um valor de ajuste na coluna Ajuste ou ambos. Você também pode clicar no \'W\' à direita para calcular automaticamente um valor de ajuste que baixa o restante da cobrança desse item de linha');
INSERT INTO `lang_definitions` VALUES (117740, 11250, 19, 'O tipo de amostra será Sangue, esta lista suspensa também pode ser editada conforme necessário');
