INSERT INTO `lang_definitions` VALUES (118146, 11699, 19, 'Para desativar a verificação automática de mensagens, vá para Administração> Globais> Conectores e defina o intervalo de verificação de mensagens phiMail como 0 (zero)');
INSERT INTO `lang_definitions` VALUES (118147, 11700, 19, 'Para desativar os certificados SSL do lado do cliente, comente acima das linhas no arquivo de configuração do Apache e defina');
