INSERT INTO `lang_definitions` VALUES (118159, 11713, 19, 'Para habilitar o Portal do Paciente, vá para Administração> Portal> Habilitar Portal do Paciente no local na Versão 2, Habilitar Portal do Paciente Externo ou Habilitar Portal CMS');
