INSERT INTO `lang_definitions` VALUES (118734, 12379, 19, 'Usar uma árvore frutífera como uma analogia mais fácil de visualizar explicará melhor o conceito desta hierarquia, o tronco da árvore é o Grupo (Química do Soro), o ramo frutífero é a ordem real, Ordem do Procedimento (Ácido Úrico no Soro) e o fruta é o resultado, Resultado Discreto, também chamado de (Ácido Úrico no Soro) que conterá o valor do resultado retornado. Assim como a fruta não é carregada no tronco principal, você não deve colocar um Resultado Discreto como um descendente direto ou filho de um Grupo Superior. Da mesma forma, o ramo frutífero (Ordem de Procedimento) não pode ser colocado como um descendente direto ou filho de uma fruta (Resultado Discreto)');
INSERT INTO `lang_definitions` VALUES (118735, 12380, 19, 'Usando tecnologia para melhorar a produtividade');
INSERT INTO `lang_definitions` VALUES (118736, 12381, 19, 'Usando os detalhes inseridos no sistema openEMR irá gerar mensagens HL7 v2.3 válidas em 3 formatos, um arquivo de texto que é baixado automaticamente para a pasta de downloads do seu navegador, uma mensagem HL7 que é gravada em uma pasta ou diretório no servidor em execução openEMR ou use SFTP - Protocolo de transferência segura de arquivos, que é um protocolo de rede que fornece acesso, transferência e gerenciamento de arquivos em uma conexão segura e transfere esta mensagem para um laboratório');
