INSERT INTO `lang_definitions` VALUES (118956, 12640, 19, 'Estaremos baseando o painel de eletrólito no tronco principal ou Grupo (Química do Soro)');
INSERT INTO `lang_definitions` VALUES (118957, 12641, 19, 'Estaremos criando um pedido para três testes de glicose no sangue, TSH e vitamina D e agrupá-lo em um grupo personalizado chamado Testes de Mulher Bem e criar um local para inserir manualmente os resultados retornados');
