INSERT INTO `lang_definitions` VALUES (118959, 12643, 19, 'Vamos agora criar o pedido, ou Ordem de Procedimento, chamado Painel de Eletrólito que pode ser visualizado como o galho frutífero em nossa árvore frutífera hipotética');
INSERT INTO `lang_definitions` VALUES (118960, 12644, 19, 'Iremos configurar o pedido para o painel de eletrólito que consiste em sódio sérico, potássio, cloreto e dióxido de carbono');
INSERT INTO `lang_definitions` VALUES (118961, 12645, 19, 'Começaremos com a unidade mais básica do módulo de Pedidos de Procedimento, para configurar um único pedido de teste de laboratório e a capacidade de registrar manualmente o resultado retornado');
INSERT INTO `lang_definitions` VALUES (118962, 12646, 19, 'Usaremos um resultado discreto para cada teste para manter os valores de resultado retornados');
INSERT INTO `lang_definitions` VALUES (118963, 12647, 19, 'Usaremos esta ramificação para conter todos os 9 painéis, aqui estaremos apenas criando o pedido que representa um painel, o Painel de Eletrólito');
