INSERT INTO `lang_definitions` VALUES (119011, 12701, 19, 'Quando verificado, os dados demográficos abrirão em uma nova janela do quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (119012, 12702, 19, 'Quando verificado, a última equipe a atualizar o quadro será exibida no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (119013, 12703, 19, 'Quando marcada, as mensagens são processadas para pacientes com Escolha Demográfica do Paciente: \"Notificação Hipaa Recebida\" definida como \"Não Atribuída\" ou \"Sim\". Quando desmarcada, esta opção deve ser = \"SIM\" para processar o lembrete do paciente. Para pacientes com Escolha = \"Não\", os lembretes precisarão ser processados manualmente');
INSERT INTO `lang_definitions` VALUES (119014, 12704, 19, 'Quando verificado, o número de encontro do paciente será exibido no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (119015, 12705, 19, 'Quando verificado, a ID do paciente será exibida no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (119016, 12706, 19, 'Quando verificado, o motivo da visita será exibido no quadro de fluxo do paciente');
INSERT INTO `lang_definitions` VALUES (119017, 12707, 19, 'Ao lidar com informações de saúde protegidas (PHI) e informações de identificação pessoal (PII), é importante permitir que apenas usuários autorizados acessem os dados');
INSERT INTO `lang_definitions` VALUES (119018, 12708, 19, 'Quando terminar, clique em Enviar (abaixo) para aplicar suas escolhas');
INSERT INTO `lang_definitions` VALUES (119019, 12709, 19, 'Quando tal pedido é feito, os resultados retornados conterão os valores de todos os componentes do CBC, Painel Metabólico Abrangente e TSH');
INSERT INTO `lang_definitions` VALUES (119020, 12710, 19, 'Quando o relatório gerado é exibido em uma guia separada, há uma opção que permite visualizar uma versão para impressão que pode ser impressa');
INSERT INTO `lang_definitions` VALUES (119021, 12711, 19, 'Quando a chave é registrada pela primeira vez, ela gera um número aleatório, que é chamado de nonce');
INSERT INTO `lang_definitions` VALUES (119022, 12712, 19, 'Quando o usuário visitar esta página pela primeira vez, a seguinte mensagem estará visível');
