INSERT INTO `lang_definitions` VALUES (119506, 8, 20, 'تم تحديد رمز من هذا النوع بالفعل. امسح الحقل أولاً إذا كنت بحاجة إلى استبداله.');
INSERT INTO `lang_definitions` VALUES (119507, 9, 20, 'يمكن إعادة توجيه رسالة تذكير مؤرخة بالنقر فوق الزر \"إعادة توجيه\" أو إزالتها من قائمة التذكيرات المؤرخة بالنقر فوق الزر \"تعيين كمنتهى\"');
