INSERT INTO `lang_definitions` VALUES (119516, 18, 20, 'تتكون رسالة HL7 v2.x ببساطة من عدة أسطر من النص ، ويطلق على كل سطر اسم مقطع ويتم تقسيمه إلى مزيد من الحقول باستخدام حرف الأنبوب (|)');
INSERT INTO `lang_definitions` VALUES (119517, 19, 20, 'يتم استخدام تطبيق كبير مثل openEMR من قبل العديد من المستخدمين بأدوار ودرجات متفاوتة من المسؤولية. من الضروري أن يتم منح الوصول إلى أجزاء مختلفة من البرنامج للمستخدمين على أساس الحاجة إلى المعرفة. لتحقيق ذلك - يتم استخدام قوائم التحكم في الوصول (ACL).');
