INSERT INTO `lang_definitions` VALUES (133937, 11059, 22, 'Dışarı aktarılan veriler aşağıdaki metin penceresinde görüntülenmektedir. Bunu kopyalayıp epostaya veya arzu ettiğiniz her hangi bir hedefe yapıştırabilirsiniz.');
INSERT INTO `lang_definitions` VALUES (133938, 11061, 22, 'Dışarı aktarılan veriler aşağıdaki metin penceresinde görüntülenmektedir. Bunu kopyalayıp epostaya veya arzu ettiğiniz her hangi bir hedefe yapıştırabilirsiniz.');
INSERT INTO `lang_definitions` VALUES (133939, 11062, 22, 'Dışarı aktarılan veriler aşağıdaki metin penceresinde görüntülenmektedir. Bunu kopyalayıp epostaya veya arzu ettiğiniz her hangi bir hedefe yapıştırabilirsiniz.');
INSERT INTO `lang_definitions` VALUES (133940, 11087, 22, 'Aşağıdaki takvim olayı eklendi:');
