INSERT INTO `lang_definitions` VALUES (133942, 11093, 22, 'Aşağıdaki EDI dosyası yüklendi');
INSERT INTO `lang_definitions` VALUES (133943, 11095, 22, 'Aşağıdaki Acil Giriş Kullanıcısı etkinleştirildi:');
