INSERT INTO `lang_definitions` VALUES (133946, 11114, 22, 'ATNA yedek denetim makinası ana bilgisayar adı');
INSERT INTO `lang_definitions` VALUES (133947, 11126, 22, 'İlk pencere fatura arama penceresidir. En üste bir kaynak (örneğin çek numarası) ödeme tarihi ve çek miktarı girebilirsiniz. Kaynak ve ödeme tarihinin öyle olmasının sebebi her alacaktan sonra tekrar tekrar girmek zorunda kalmamanız içindir. Girdiğiniz miktar ödenen kısım için verdiğiniz her faturada düşülecek ve bittiğinde 0 ile sonlanacaktır.');
INSERT INTO `lang_definitions` VALUES (133948, 11140, 22, 'Form üzerinde kullanıcıya görünen etiket');
INSERT INTO `lang_definitions` VALUES (133949, 11168, 22, 'Yeni kategorinin üst kategorisi:');
INSERT INTO `lang_definitions` VALUES (133950, 11192, 22, 'Şifre en az sekiz karakter içermeli ve');
INSERT INTO `lang_definitions` VALUES (133951, 11203, 22, 'Yapılan ödemeler bu tarihten öncesine gidemez. Bunun sebebi son rapor çıktıktan sonra kimsenin önceki tarihler için kayıt yapmamasını garanti etmektir.');
INSERT INTO `lang_definitions` VALUES (133952, 11219, 22, 'Aşağıdaki bilgi sadece el ile gönderiyorsanız ve el ile düzeltmeler yapıyorsanız geçerlidir.');
INSERT INTO `lang_definitions` VALUES (133953, 11223, 22, 'İstenen belge dosya sisteminde bulunmamaktadır veya ona erişmek için yeterli izin yoktur');
INSERT INTO `lang_definitions` VALUES (133954, 11248, 22, 'Kaynak ve Tarih sütunları ilk sayfadan kopyalanır, bu nedenle normal olarak onlara dokunmanız gerekmeyecektir. Ödeme sütununa bir ödeme miktarını, Düzeltme sütununa bir düzeltme miktarını veya her ikisini girebilirsiniz. Aynı zamanda sağdaki \"Y\" yi tıklayıp düzeltme değerini otomatik hesaplattırıp aynı satır için alacağın kalanını yazdırabilirsiniz.');
