INSERT INTO `lang_definitions` VALUES (150426, 5, 26, 'O regulă de decizie clinică este informații specifice pacientului, care sunt filtrate și prezentate la momente adecvate pentru a îmbunătăți sănătatea și îngrijirea sănătății');
