INSERT INTO `lang_definitions` VALUES (150429, 8, 26, 'Un cod al acestui tip este deja selectat. Stergeti campul daca doriti sa-l inlocuiti.');
INSERT INTO `lang_definitions` VALUES (150430, 9, 26, 'Un mesaj de memento datat poate fi fie redirecționat făcând clic pe butonul Redirecționare, fie eliminat din lista de memento-uri datate făcând clic pe butonul Setare ca finalizat');
