INSERT INTO `lang_definitions` VALUES (150433, 12, 26, 'Un ghid detaliat despre cum să activați și să configurați o regulă de decizie clinică este găsit aici');
INSERT INTO `lang_definitions` VALUES (150434, 13, 26, 'Este necesar un distributor');
INSERT INTO `lang_definitions` VALUES (150435, 14, 26, 'Poate fi specificată o dată limită sau poate fi aleasă o anumită perioadă de timp pentru ca mementoul datat să apară');
