INSERT INTO `lang_definitions` VALUES (150437, 16, 26, 'O întâlnire ulterioară poate fi, de asemenea, programată chiar din foaia de taxe.');
INSERT INTO `lang_definitions` VALUES (150438, 17, 26, 'Un formular GCAC trebuie adaugat la aceasta vizita.');
INSERT INTO `lang_definitions` VALUES (150439, 18, 26, 'Un mesaj HL7 v2.x constă pur și simplu din mai multe rânduri de text, fiecare linie este numită segment și este împărțită în câmpuri folosind caracterul pipe (|)');
INSERT INTO `lang_definitions` VALUES (150440, 19, 26, 'O aplicatie complexa precum openEMR este utilizata de o multitudine de utilizatori cu diferite roluri si grade de responsabilitate. Este imperativ necesar ca accesul la diferite parti ale programului sa fie acordat conform nevoilor. Pentru a realiza aceasta se utilizeaza Liste de Contol al Accesului (ACL- Access Control Lists)');
INSERT INTO `lang_definitions` VALUES (150441, 20, 26, 'Este necesar un numar de lot');
INSERT INTO `lang_definitions` VALUES (150442, 21, 26, 'Este necesar un numar de lot!');
INSERT INTO `lang_definitions` VALUES (150443, 22, 26, 'O litera mica');
INSERT INTO `lang_definitions` VALUES (150444, 23, 26, 'O Noua Programare');
INSERT INTO `lang_definitions` VALUES (150445, 24, 26, 'O nouă caracteristică ajută la gruparea testelor comandate frecvent, astfel încât acestea să poată fi comandate împreună');
INSERT INTO `lang_definitions` VALUES (150446, 25, 26, 'Un mesaj nou poate fi astfel trimis unui singur sau mai multor utilizatori și/sau poate fi despre un singur sau mai mulți pacienți');
INSERT INTO `lang_definitions` VALUES (150447, 26, 26, 'Acreditările unui pacient nou nu au putut fi trimise după înregistrarea pe portal.');
INSERT INTO `lang_definitions` VALUES (150448, 27, 26, 'Un submeniu cu filă nouă va fi vizibil în partea de sus a paginii Centrul de mesaje');
INSERT INTO `lang_definitions` VALUES (150449, 28, 26, 'Un numar');
INSERT INTO `lang_definitions` VALUES (150450, 29, 26, 'Selectati un pacient pentru generarea raportului.');
