INSERT INTO `lang_definitions` VALUES (150452, 31, 26, 'Exista deja un pacient cu acest nume.');
INSERT INTO `lang_definitions` VALUES (150453, 32, 26, 'Exista deja un pacient cu acest SS.');
INSERT INTO `lang_definitions` VALUES (150454, 33, 26, 'O plata este obligatorie! Introduceti o intrare a platii.');
INSERT INTO `lang_definitions` VALUES (150455, 34, 26, 'Un loc pentru a documenta și afișa istoricul medical trecut al pacientului, istoricul familial, istoricul personal');
INSERT INTO `lang_definitions` VALUES (150456, 35, 26, 'O casetă pop-up vă va avertiza despre succes sau eșec');
INSERT INTO `lang_definitions` VALUES (150457, 36, 26, 'Numerele pozitive vor afisa numarul de programari in sumarul pacientului, iar cele negative le vor afisa in ordine descrescatoare.');
INSERT INTO `lang_definitions` VALUES (150458, 37, 26, 'Un numar pozitiv va arata numarul de programari in sumarul pacientului.');
INSERT INTO `lang_definitions` VALUES (150459, 38, 26, 'A fost selectat un produs, dar nu exista o sectiune produs in acest formular.');
INSERT INTO `lang_definitions` VALUES (150460, 39, 26, 'Un furnizor sau un depozit poate fi selectat în caseta drop-down. Pentru ca această opțiune să fie afișată, caseta „Furnizor de asistență în elementul rând din foaia de taxe” trebuie bifată în Administrare > Global > pagina Facturare');
INSERT INTO `lang_definitions` VALUES (150461, 41, 26, 'O întâlnire recurentă. Vă rugăm să contactați biroul de programare pentru orice modificări.');
INSERT INTO `lang_definitions` VALUES (150462, 42, 26, 'O recomandare are o acțiune suplimentară - de a tipări recomandarea sau de a o salva ca fișier pdf');
INSERT INTO `lang_definitions` VALUES (150463, 43, 26, 'O recomandare este cel mai comun tip de tranzacție');
INSERT INTO `lang_definitions` VALUES (150464, 44, 26, 'O sursa de referinta poate fi specificata pentru fiecare vizita.');
