INSERT INTO `lang_definitions` VALUES (151001, 628, 26, 'Alternativ, puteti utiliza pagina de cautare pentru a incarca o trimitere pe care ati obtinut-o de la pacient. Puteti face asta facand click pe butonul \"Browser\" si selectand fisierul pe care doriti sa il incarcati, apoi folositi \"Search\" pentru a efectua incarcare si a afisa factura corespunzatoare. Incarcarea salveaza datele continute insa nu va procesa si continutul. Procesarea se va efectua urmand pasii urmatori.');
INSERT INTO `lang_definitions` VALUES (151002, 629, 26, 'Deși HCFA-1500 a fost inițial dezvoltat pentru depunerea cererilor Medicare, în cele din urmă a fost acceptat de toți transportatorii de asigurări comerciali/privați pentru a facilita standardizarea procesului de reclamații.');
