INSERT INTO `lang_definitions` VALUES (151045, 674, 26, 'Va fi trimis un e-mail cu noul dvs. autentificare de cont la adresa de e-mail furnizată mai devreme. Puteți revizui sau edita în continuare orice parte a informațiilor dvs. utilizând butoanele pasului de sus pentru a accesa panourile corespunzătoare. Rețineți pentru a vă asigura că ați dat adresa de e-mail corectă. Dacă după ce ați primit acreditările și aveți probleme cu accesul la portal, vă rugăm să contactați administrația.');
INSERT INTO `lang_definitions` VALUES (151046, 675, 26, 'O comandă electronică și rezultatul returnat este sub forma unui mesaj numit mesaj HL7. HL7 înseamnă Health Level (Application Layer) 7. Obiectivul principal al HL7 este de a simplifica implementarea interfețelor dintre aplicațiile software de asistență medicală și diverși furnizori, astfel încât să reducă durerea și costurile implicate în programarea interfeței personalizată.');
INSERT INTO `lang_definitions` VALUES (151047, 676, 26, 'O data de incheiere ulterioara datei de inceput este necesara pentru evenimente repetate!');
