INSERT INTO `lang_definitions` VALUES (151053, 683, 26, 'Un concept important de înțeles este că, odată ce cheia secretă furnizată prin codul QR este capturată de aplicația de autentificare, nu mai există nicio comunicare între aplicație și OpenEMR, fiecare va folosi ora UNIX curentă și copia sa a secretului partajat specific utilizatorului. pentru a genera același număr unic de 6 cifre');
