INSERT INTO `lang_definitions` VALUES (152079, 1782, 26, 'Faceți clic pe „exportați” pentru a exporta datele dvs. de categorie, subcategorie, articol, conținut într-un fișier text. Orice asemănare a acestui fișier cu un fișier XML este pur întâmplătoare. Etichetele de deschidere și de închidere trebuie să fie pe aceeași linie, trebuie să fie litere mici, fără spații. Pentru a importa, căutați un fișier și faceți clic pe „import”. Dacă datele sunt complet diferite, acestea vor fuziona cu datele existente. Dacă există nume de articole similare, cel vechi va fi păstrat, iar cel nou va fi salvat cu un număr adăugat la sfârșit.');
