INSERT INTO `lang_definitions` VALUES (152265, 1978, 26, 'Făcând clic pe pictograma de lângă legendă, se vor afișa mesajele tuturor, iar legendă se va schimba în Toate mesajele');
INSERT INTO `lang_definitions` VALUES (152266, 1979, 26, 'Făcând clic pe pictograma de lângă numele lor, va apărea fereastra „Editare”.');
INSERT INTO `lang_definitions` VALUES (152267, 1980, 26, 'Făcând clic pe elementul de meniu Diverse > MFA Management sau Nume utilizator > elementul de meniu MFA Management, veți ajunge la pagina de destinație pentru gestionarea paginii de autentificare multifactor pentru acel utilizator.');
INSERT INTO `lang_definitions` VALUES (152268, 1981, 26, 'Făcând clic pe numele pacientului, se va dezvălui mesajul');
INSERT INTO `lang_definitions` VALUES (152269, 1982, 26, 'Făcând clic pe pictograma creion, se va intra în modul Editare și se va afișa fereastra pop-up Introducere detalii care a fost folosită pentru a crea intrarea afișată pe această linie');
INSERT INTO `lang_definitions` VALUES (152270, 1983, 26, 'Făcând clic pe butoanele Afișare tot sau Afișare inactiv, se vor afișa mesajele corespunzătoare');
INSERT INTO `lang_definitions` VALUES (152271, 1984, 26, 'Făcând clic pe pictograma ochi tăiat, filtrele vor ascunde');
INSERT INTO `lang_definitions` VALUES (152272, 1985, 26, 'Făcând clic pe butonul Vizualizare jurnal, va apărea fereastra pop-up Jurnal de mesaje datate');
INSERT INTO `lang_definitions` VALUES (152273, 1986, 26, 'Făcând clic pe Opțiuni, se va afișa un meniu drop-down cu selecție multiplă pentru a adăuga comportamente tipului de date selectat. Tastarea după activarea meniului derulant permite căutarea în opțiuni.');
INSERT INTO `lang_definitions` VALUES (152274, 1987, 26, 'Făcând clic pe butonul va apărea o fereastră pop-up care va lista codurile E/M, verificați codul corespunzător și faceți clic pe „OK”.');
