INSERT INTO `lang_definitions` VALUES (155160, 5091, 26, 'Identificator (un cuvânt)');
INSERT INTO `lang_definitions` VALUES (155161, 5092, 26, 'Cod de identificare');
INSERT INTO `lang_definitions` VALUES (155162, 5093, 26, 'Sesiunea inactivă Timeout Secunde');
INSERT INTO `lang_definitions` VALUES (155163, 5094, 26, 'Fac');
INSERT INTO `lang_definitions` VALUES (155164, 5095, 26, 'dacă');
INSERT INTO `lang_definitions` VALUES (155165, 5096, 26, 'Dacă Coloana de date a unui câmp = 0, câmpul de date va urma imediat câmpul său de etichetă pe aceeași linie');
INSERT INTO `lang_definitions` VALUES (155166, 5097, 26, 'Dacă Label Col = 0 al unui câmp, eticheta va urma imediat câmpul de date anterior în secvența de comandă, pe aceeași linie cu câmpul Date.');
INSERT INTO `lang_definitions` VALUES (155167, 5098, 26, 'Dacă Coloana etichetei unui câmp = 1, câmpul etichetei va merge pe o nouă linie, cu excepția cazului în care valorile totale ale coloanei din câmpul anterior (Etichetă + Date) sunt mai mici decât numărul de coloane Aspect din Proprietăți grup sau Proprietăți aspect.');
INSERT INTO `lang_definitions` VALUES (155168, 5099, 26, 'Dacă un produs este vândut, atunci modificați valoarea implicită pentru a reflecta numărul necesar. Lăsați-l la una pentru proceduri');
INSERT INTO `lang_definitions` VALUES (155169, 5100, 26, 'Dacă a fost selectat un cod greșit, faceți clic pe caseta de text Codare pentru a afișa pagina pop-up Selectare coduri');
INSERT INTO `lang_definitions` VALUES (155170, 5101, 26, 'Dacă toate datele pentru toate coloanele sunt complete pentru acest formular');
INSERT INTO `lang_definitions` VALUES (155171, 5102, 26, 'Dacă toate detaliile au fost introduse corect, veți vedea glicemia în coloana Nume cu o bară verticală înainte de a indica faptul că nu are descendenți sau copii, Rezultat în coloana Categorie, WWT01R în coloana Cod, valoarea coloanei Tier ar trebui să fie 3 iar coloana Descriere ar trebui să spună rezultatul glucozei în repaus');
INSERT INTO `lang_definitions` VALUES (155172, 5103, 26, 'Dacă se utilizează justificarea facturării, introduceți numele tipului de cod de diagnosticare.');
INSERT INTO `lang_definitions` VALUES (155173, 5104, 26, 'Dacă este configurată corect, coloana Nume ar trebui să spună Glucoză din sânge cu o bară verticală înainte de a nu indica descendenți sau copii, coloana Categorie ar trebui să spună Ordine personalizată și ambele coloane Nume și Categorie vor fi evidențiate cu roz, indicând o ordine grupată personalizată.');
INSERT INTO `lang_definitions` VALUES (155174, 5105, 26, 'Dacă se dorește, mesajul curent poate fi imprimat');
INSERT INTO `lang_definitions` VALUES (155175, 5106, 26, 'Dacă este activată, aceasta va trimite timpul de execuție necesar pentru a verifica hash-ul în jurnalul de erori php.');
INSERT INTO `lang_definitions` VALUES (155176, 5107, 26, 'Dacă este activat, utilizați LDAP pentru conectare și autentificare.');
INSERT INTO `lang_definitions` VALUES (155177, 5108, 26, 'Dacă este activat, folosește directorul activ specificat pentru autentificare și autentificare.');
INSERT INTO `lang_definitions` VALUES (155178, 5109, 26, 'dacă este introdus, selectați numai cei care au beneficiat de acest serviciu');
INSERT INTO `lang_definitions` VALUES (155179, 5110, 26, 'Dacă este încă activă, adică data de încheiere nu este introdusă, va fi afișată cu roșu, dacă problema are o dată de încheiere, aceasta va fi afișată cu negru');
INSERT INTO `lang_definitions` VALUES (155180, 5111, 26, 'Dacă nume, orice parte a numelui sau prenumelui, prenume');
INSERT INTO `lang_definitions` VALUES (155181, 5112, 26, 'Dacă NewCrop eRx - modulul de prescripție electronică, este activat, butoanele NewCrop MedEntry și NewCrop Account Status vor apărea aici');
INSERT INTO `lang_definitions` VALUES (155182, 5113, 26, 'Dacă nu este listat, puteți adăuga medicamentul în caseta de text Titlu');
INSERT INTO `lang_definitions` VALUES (155183, 5115, 26, 'Dacă capturați doar codul QR, dar nu înregistrați cheia TOTP cu OpenEMR, această funcție nu va fi activată la conectare');
INSERT INTO `lang_definitions` VALUES (155184, 5116, 26, 'Dacă pacientul are o programare, faceți clic pe OK pentru a crea o întâlnire în caz contrar, anulați aceasta și apoi creați o întâlnire pentru vizita de astăzi.');
INSERT INTO `lang_definitions` VALUES (155185, 5117, 26, 'Dacă plătiți prin');
INSERT INTO `lang_definitions` VALUES (155186, 5118, 26, 'Dacă persoana este decedată, atunci introduceți data morții.');
INSERT INTO `lang_definitions` VALUES (155187, 5119, 26, 'Dacă telefonul este pierdut, nu se va putea autentifica');
INSERT INTO `lang_definitions` VALUES (155188, 5120, 26, 'Dacă privilegiile trebuie modificate, atunci se poate face fie un utilizator odată la Administrare > Utilizatori sau mai convenabil pe această pagină, adică Administrare > ACL, unde toți utilizatorii sunt listați pe o singură pagină și sunt disponibile mai multe opțiuni.');
INSERT INTO `lang_definitions` VALUES (155189, 5121, 26, 'Dacă se setează ca mare, va restricționa vizibilitatea întâlnirii la utilizatorii care aparțin anumitor grupuri (ARO). Implicit - Medici și Administratori');
INSERT INTO `lang_definitions` VALUES (155190, 5122, 26, 'Dacă se utilizează SMTP, numele de gazdă sau adresa IP a serverului.');
INSERT INTO `lang_definitions` VALUES (155191, 5123, 26, 'Dacă se utilizează SMTP, numărul portului TCP al serverului (de obicei 25).');
INSERT INTO `lang_definitions` VALUES (155192, 5124, 26, 'Dacă doriți, panoul implicit poate fi dezactivat accesând Administrare > Calendar > Recall Board: Dezactivați și bifând caseta de selectare și faceți clic pe Salvare');
INSERT INTO `lang_definitions` VALUES (155193, 5125, 26, 'Dacă da, va trebui să creați Ordine de procedură individuale (comenzile) pentru aceste teste împreună cu Rezultate discrete (locul pentru a introduce și afișa rezultatul returnat)');
INSERT INTO `lang_definitions` VALUES (155194, 5126, 26, 'Dacă are succes, acesta autentifică utilizatorul');
INSERT INTO `lang_definitions` VALUES (155195, 5127, 26, 'Dacă caseta de selectare este bifată și mesajul este trimis către mai mulți utilizatori, atunci fiecare utilizator trebuie să se deconecteze de la mesaj făcând clic pe butonul Set As Completed pentru acel mesaj');
INSERT INTO `lang_definitions` VALUES (155196, 5128, 26, 'Dacă caseta de selectare este bifată, atunci fiecare persoană dintr-un grup care primește acest mesaj va trebui să se deconecteze făcând clic pe butonul Setare ca finalizat');
INSERT INTO `lang_definitions` VALUES (155197, 5129, 26, 'Dacă fișierul csv a fost încărcat, atunci faceți clic pe butonul „Importați evenimente de vacanță”. NOTĂ că făcând clic pe butonul vor elimina toate rândurile existente în tabelul calendar_external');
INSERT INTO `lang_definitions` VALUES (155198, 5130, 26, 'Dacă titlul dorit nu este inclus, acesta poate fi introdus în caseta de text de sub listă');
INSERT INTO `lang_definitions` VALUES (155199, 5131, 26, 'Dacă tabelul afișat spune Nicio înregistrare care se potrivește, înseamnă că setul de coduri ICD10 nu este instalat');
INSERT INTO `lang_definitions` VALUES (155200, 5132, 26, 'Dacă fișierul de ajutor nu există, creați unul și plasați-l în');
INSERT INTO `lang_definitions` VALUES (155201, 5133, 26, 'Dacă problema nu a fost legată de o întâlnire, va afișa 0');
INSERT INTO `lang_definitions` VALUES (155202, 5134, 26, 'Dacă problema medicală nu este listată în caseta derulantă, faceți clic pe caseta de text Codificare pentru a afișa pagina pop-up Selectare coduri');
INSERT INTO `lang_definitions` VALUES (155203, 5135, 26, 'Dacă mesajul este redirecționat, acesta va apărea în lista de mesaje active a utilizatorului căruia i-a fost redirecționat mesajul și va dispărea din lista de mesaje active a utilizatorului curent.');
INSERT INTO `lang_definitions` VALUES (155204, 5136, 26, 'Dacă portalul pentru pacienți în afara locației este activat, va exista fie un buton care spune Creare acreditări ale portalului în afara locației, cu condiția ca pacientul să-și acorde permisiunea de a accesa portalul online pentru pacient, fie un mesaj care spune că pacientul nu a autorizat portalul pentru pacienți');
INSERT INTO `lang_definitions` VALUES (155205, 5137, 26, 'Dacă portalul pentru pacienți online este activat, va exista fie un buton care spune Creare acreditări ale portalului online, cu condiția ca pacientul să-și acorde permisiunea de a accesa portalul online pentru pacienți, fie un mesaj care spune că pacientul nu a autorizat portalul pentru pacienți');
INSERT INTO `lang_definitions` VALUES (155206, 5138, 26, 'Dacă acreditările portalului online/offsite au fost deja setate, butonul se va schimba în');
INSERT INTO `lang_definitions` VALUES (155207, 5139, 26, 'Dacă pacientul are date demografice introduse în openEMR, acesta va completa automat câmpurile relevante din secțiunile din dreapta');
INSERT INTO `lang_definitions` VALUES (155208, 5140, 26, 'Dacă pacientul nu a autorizat portalul pacientului, atunci un pacient nu a autorizat mesajul Portalul pacientului va fi afișat aici');
INSERT INTO `lang_definitions` VALUES (155209, 5141, 26, 'Dacă pacientul este adăugat la lista de retragere în ziua vizitei, aceasta ar reflecta data curentă');
INSERT INTO `lang_definitions` VALUES (155210, 5142, 26, 'Dacă pacientul sună înapoi pentru a fi adăugat pe listă, ultima vizită poate fi în trecutul îndepărtat. Rețineți că cei 1, 2, 3 plus ani sunt calculați și afișați în caseta Data din partea de jos a acestei secțiuni');
INSERT INTO `lang_definitions` VALUES (155211, 5143, 26, 'Dacă pacientul este decedat, atunci notificarea decesului va apărea cu roșu în această secțiune');
INSERT INTO `lang_definitions` VALUES (155212, 5144, 26, 'Dacă raportul este trimis electronic, trebuie urmați toți pașii necesari pentru transmiterea în siguranță și securizată a informațiilor de sănătate protejate (PHI).');
INSERT INTO `lang_definitions` VALUES (155213, 5145, 26, 'Dacă nu există niciun furnizor, introduceți un număr unic arbitrar, de preferință un număr de 5 cifre cu zero, de ex. 00211');
INSERT INTO `lang_definitions` VALUES (155214, 5146, 26, 'Dacă aceste teste sunt trimise aceluiași laborator extern, vor avea coduri de identificare identice specifice furnizorului, ceea ce provoacă apariția liniilor duplicate atunci când sunt afișate rezultatele');
INSERT INTO `lang_definitions` VALUES (155215, 5147, 26, 'Dacă au fost configurate corect, fiecare rezultat ar trebui să aibă o valoare de nivel de 4, indicând că sunt succesorul sau copilul la prima linie de mai sus cu o valoare de nivel de 3, adică panoul de electroliți');
INSERT INTO `lang_definitions` VALUES (155216, 5148, 26, 'Dacă această pagină nu se reîmprospătează, reîncărcați manual pagina Mesaje');
INSERT INTO `lang_definitions` VALUES (155217, 5149, 26, 'Dacă nu este atribuit, va fi implicit setarea php.ini pentru date.timezone.');
INSERT INTO `lang_definitions` VALUES (155218, 5150, 26, 'daca someri intra Student');
INSERT INTO `lang_definitions` VALUES (155219, 5151, 26, 'Dacă valoarea este lăsată ca zero, va fi sortată alfabetic');
INSERT INTO `lang_definitions` VALUES (155220, 5152, 26, 'Dacă este selectat YMD pentru afișarea vârstei, comutați la doar Ani când pacienții sunt mai în vârstă decât această valoare în ani');
INSERT INTO `lang_definitions` VALUES (155221, 5153, 26, 'Dacă întâmpinați probleme la conectarea la contul dvs.');
INSERT INTO `lang_definitions` VALUES (155222, 5154, 26, 'Dacă sunteți interesat de ceea ce se întâmplă sub capotă');
INSERT INTO `lang_definitions` VALUES (155223, 5155, 26, 'Dacă utilizați doar un mic subset de coduri CPT, îl puteți introduce manual în Administrare > Coduri');
INSERT INTO `lang_definitions` VALUES (155224, 5156, 26, 'Dacă intenționați să introduceți prețuri diferite pentru diferite modalități de plată, accesați Administrare > Liste');
INSERT INTO `lang_definitions` VALUES (155225, 5157, 26, 'Dacă nu sunteți sigur sau utilizați o versiune de dezvoltare între două versiuni, alegeți cea mai veche dintre versiunile posibile');
INSERT INTO `lang_definitions` VALUES (155226, 5159, 26, 'Dacă faceți upgrade de la o versiune sub 5.0.0 la versiunea 5.0.0 sau mai mare, rețineți că această actualizare poate dura de la câteva minute la câteva ore (veți vedea doar un ecran alb până când este complet; nu opriți scriptul înainte ca acesta să fie complet sau riscați să vă corupați datele)');
INSERT INTO `lang_definitions` VALUES (155227, 5160, 26, 'Dacă utilizați intrarea electronică în laborator, completați detaliile necesare și faceți clic pe Salvare');
INSERT INTO `lang_definitions` VALUES (155228, 5161, 26, 'Dacă utilizați mai multe laboratoare, introduceți detaliile pentru fiecare dintre ele');
INSERT INTO `lang_definitions` VALUES (155229, 5162, 26, 'Dacă schimbați rolul e-RX pentru ePrescription, aceasta poate afecta fluxul de lucru ePrescription. Dacă întâmpinați orice dificultăți, contactați furnizorul de ePrescription.');
INSERT INTO `lang_definitions` VALUES (155230, 5163, 26, 'Dacă vă schimbați smartphone-ul, puteți recaptura codul QR al cheii TOTP pe un dispozitiv nou, conectându-vă mai întâi utilizând aplicația de autentificare de pe telefonul dvs. vechi și apoi accesând Diverse > Autentificare MFA și făcând clic pe butonul Vizualizare din secțiunea Metodă de autentificare curentă.');
INSERT INTO `lang_definitions` VALUES (155231, 5164, 26, 'Dacă bifați caseta de selectare din oricare dintre aceste celule, va genera o intrare în ultima celulă numită Progres');
INSERT INTO `lang_definitions` VALUES (155232, 5165, 26, 'Dacă alegeți să faceți o introducere manuală, faceți clic pe butonul radio „Căutare factură”. Afișează două secțiuni „Postează articol” și „Căutare factură”');
INSERT INTO `lang_definitions` VALUES (155233, 5166, 26, 'Dacă alegeți să integrați rezultatele de laborator cu fișa pacientului, atunci trebuie efectuată o configurare preliminară');
INSERT INTO `lang_definitions` VALUES (155234, 5167, 26, 'Dacă faceți clic pe orice utilizator din secțiunea „Abonament utilizator”, veți vedea acum aceste grupuri nou create (ARO) în coloana „Inactiv”. Acestea pot fi acum alocate în mod obișnuit, după cum este necesar.');
INSERT INTO `lang_definitions` VALUES (155235, 5168, 26, 'Dacă faceți clic pe pictograma de editare de lângă acest grup nou creat (ARO), veți observa că coloana „Activ” conține doar o singură intrare - Substituent (Menține ACL-uri goale). Încă acest nou grup (ARO) NU are acces la nicio parte a programului, deoarece nu există ACO-uri alocate în coloana „Activ”.');
INSERT INTO `lang_definitions` VALUES (155236, 5169, 26, 'Dacă faceți clic pe semnul albastru + pe Serum Chemistry, veți vedea o nouă linie numită Organ/Disease Panel cu o categorie de subgrup');
INSERT INTO `lang_definitions` VALUES (155237, 5170, 26, 'Dacă întâmpinați în continuare această eroare, contactați asistența.');
INSERT INTO `lang_definitions` VALUES (155238, 5171, 26, 'Dacă nu găsiți o valoare necesară în caseta derulantă, va trebui să o adăugați prin Administrare > Liste > Unități de procedură. Consultați fișierul de ajutor din Proceduri > Furnizori');
INSERT INTO `lang_definitions` VALUES (155239, 5172, 26, 'Dacă nu selectați o potrivire, pacientul va fi creat.');
INSERT INTO `lang_definitions` VALUES (155240, 5173, 26, 'Dacă nu selectați cel puțin unul dintre acestea, OpenEMR va funcționa într-un mod numai de recepție');
INSERT INTO `lang_definitions` VALUES (155241, 5174, 26, 'Dacă nu trimiteți comenzi electronic sau primiți rezultatul electronic, lăsați-l ca valoare implicită, Descărcați');
INSERT INTO `lang_definitions` VALUES (155242, 5176, 26, 'Dacă nu doriți să faceți acest lucru, următoarea metodă implică adăugarea manuală a datelor folosind interfața openEMR');
INSERT INTO `lang_definitions` VALUES (155243, 5177, 26, 'Dacă detaliați până la linia panoului de electroliți și faceți clic pe semnul + din coloana Nume, ar trebui să vedeți sodiu listat sub aceasta cu o valoare de categorie de rezultat cu o valoare de nivel de 4');
INSERT INTO `lang_definitions` VALUES (155244, 5178, 26, 'Dacă detaliați până la linia Panoului de electroliți, ar trebui să vedeți că are o categorie de comandă și să fie evidențiată cu galben, indicând că este o comandă validă și care poate fi căutată și are o valoare de nivel 3');
INSERT INTO `lang_definitions` VALUES (155245, 5179, 26, 'Dacă ați selectat mai multe coduri, acestea vor fi separate prin punct și virgulă');
INSERT INTO `lang_definitions` VALUES (155246, 5180, 26, 'Dacă ați completat deja tabelul calendar_external, atunci faceți clic pe butonul „Sincronizează” pentru a avea sărbătorile în vizualizarea calendarului. REȚINEȚI că făcând clic pe butonul vor elimina toate elementele existente în vizualizarea calendarului legate de sărbători');
INSERT INTO `lang_definitions` VALUES (155247, 5181, 26, 'Dacă aveți un superbill vechi, puteți utiliza gruparea sa de coduri ca șablon pentru a începe personalizarea');
INSERT INTO `lang_definitions` VALUES (155248, 5182, 26, 'Dacă ați ales să încărcați remitențe electronice, atunci fereastra de căutare se reafișează cu facturile corespunzătoare din fișierul X12. Puteți face clic pe oricare dintre aceste numere de factură (așa cum este descris mai jos) dacă doriți să faceți orice corecții înainte ca informațiile de remitere să fie aplicate. Pentru a aplica modificările, faceți clic pe butonul Procesare fișier ERA din partea de jos a paginii. Aceasta va produce o nouă fereastră cu un raport detaliat.');
INSERT INTO `lang_definitions` VALUES (155249, 5183, 26, 'Dacă ați ales să încărcați remitențe electronice, atunci fereastra de căutare se reafișează cu facturile corespunzătoare din fișierul X12. Puteți face clic pe oricare dintre aceste numere de factură (așa cum este descris mai sus) dacă doriți să faceți orice corecții înainte ca informațiile de remitere să fie aplicate. Pentru a aplica modificările, faceți clic pe butonul „Procesează fișierul ERA” din partea de jos a paginii. Aceasta va produce o nouă fereastră cu un raport detaliat.');
INSERT INTO `lang_definitions` VALUES (155250, 5184, 26, 'Dacă ați activat metoda TOTP data viitoare când vă conectați, vi se va cere să introduceți parola TOTP');
INSERT INTO `lang_definitions` VALUES (155251, 5185, 26, 'Dacă ați introdus o dată de plată în pagina de căutare, aceasta va înlocui data de înregistrare a plăților și a ajustărilor care altfel sunt preluate din fișierul X12. Acest lucru poate fi util în scopuri de raportare, dacă doriți ca raportarea chitanțelor să utilizeze data dvs. de înregistrare, mai degrabă decât data de procesare a companiei de asigurări. Rețineți că acest lucru va afecta și datele plăților anterioare și ale ajustărilor care sunt introduse în revendicări secundare.');
INSERT INTO `lang_definitions` VALUES (155252, 5186, 26, 'Dacă ați introdus o dată de plată în pagina de căutare, aceasta va înlocui data de înregistrare a plăților și a ajustărilor care altfel sunt preluate din fișierul X12. Acest lucru poate fi util în scopuri de raportare, dacă doriți ca raportarea chitanțelor să utilizeze data dvs. de înregistrare, mai degrabă decât data de procesare a companiei de asigurări. Rețineți că acest lucru va afecta și datele plăților anterioare și ale ajustărilor care sunt introduse în revendicări secundare.');
INSERT INTO `lang_definitions` VALUES (155253, 5187, 26, 'Dacă ați urmat corect toți pașii de mai sus, ar trebui să vedeți Acid uric ser sub Nume, acesta va fi precedat de o bară verticală care indică absența descendenților sau a copiilor la această intrare');
INSERT INTO `lang_definitions` VALUES (155254, 5188, 26, 'Dacă ați urmat corect pașii de mai sus, testul de acid uric seric ar trebui să aibă acum un semn + înainte de Nume care indică prezența succesorilor sau a copiilor');
INSERT INTO `lang_definitions` VALUES (155255, 5189, 26, 'Dacă v-ați pierdut smartphone-ul, cei cu privilegii de administrator pot șterge cheile mergând la Administrare > Utilizatori și bifând caseta de selectare Șterge 2FA și făcând clic pe Salvare');
INSERT INTO `lang_definitions` VALUES (155256, 5190, 26, 'Dacă aveți modulul NewCrop eRx activat, atunci alergiile trebuie să fie introduse pe pagina NewCrop MedEntry');
INSERT INTO `lang_definitions` VALUES (155257, 5191, 26, 'Dacă nu ați făcut deja o preconfigurare, inclusiv adăugarea de furnizori, faceți acest lucru accesând Proceduri > Furnizori');
INSERT INTO `lang_definitions` VALUES (155258, 5192, 26, 'Dacă aveți nevoie să comandați componente individuale ale panoului, va trebui să creați o comandă de procedură separată pentru fiecare componentă individuală a panoului și să stocați rezultatul returnat sub un rezultat discret creat într-un mod similar cu cel utilizat anterior pentru a crea o comandă. pentru acid uric seric');
INSERT INTO `lang_definitions` VALUES (155259, 5193, 26, 'Dacă apăsați butonul de reîmprospătare fără a seta niciun filtru, atunci toate mementourile datate pentru utilizator vor apărea mai jos');
INSERT INTO `lang_definitions` VALUES (155260, 5194, 26, 'Dacă o lăsați la valoarea implicită de 0, atunci intrările de nivel superior pe care le faceți vor fi sortate alfabetic');
INSERT INTO `lang_definitions` VALUES (155261, 5195, 26, 'Dacă ați făcut modificări și doriți să-l retrimiteți, ștergeți originalul (în Comunicații) și încercați din nou.');
INSERT INTO `lang_definitions` VALUES (155262, 5196, 26, 'Dacă ați făcut modificări și doriți să-l retrimiteți, ștergeți originalul (în Comunicații) sau așteptați 60 de secunde și încercați din nou.');
INSERT INTO `lang_definitions` VALUES (155263, 5197, 26, 'Dacă trebuie să introduceți manual rezultatul returnat, fiecare test (articol preferat personalizat) ar trebui să aibă un rezultat discret ca descendent direct');
INSERT INTO `lang_definitions` VALUES (155264, 5198, 26, 'Dacă nu vedeți nicio intrare în caseta derulantă Comanda de la, înseamnă că nu ați configurat un laborator sub Proceduri > Furnizori');
INSERT INTO `lang_definitions` VALUES (155265, 5199, 26, 'Dacă doriți să schimbați tipurile de date sau să adăugați rânduri sau coloane');
INSERT INTO `lang_definitions` VALUES (155266, 5200, 26, 'Dacă doriți să actualizați baza de date, plasați fișierul zip al bazei de date în următorul director');
INSERT INTO `lang_definitions` VALUES (155267, 5201, 26, 'Dacă căutarea dvs. a avut succes, rezultatele căutării vor fi afișate în caseta cu rezultatele căutării de mai jos');
INSERT INTO `lang_definitions` VALUES (155268, 5202, 26, 'Igbo');
INSERT INTO `lang_definitions` VALUES (155269, 5203, 26, 'Ignora');
INSERT INTO `lang_definitions` VALUES (155270, 5205, 26, 'Codul IIS');
INSERT INTO `lang_definitions` VALUES (155271, 5207, 26, 'Maladie');
INSERT INTO `lang_definitions` VALUES (155272, 5208, 26, 'SUNT');
