INSERT INTO `lang_definitions` VALUES (155327, 5263, 26, 'IMPORTANT: Acest instrument de încărcare este doar pentru încărcarea documentelor pe pacienți care nu au fost încă introduse în sistem. Pentru a încărca fișiere pentru pacienții care au fost deja introduși în sistem, vă rugăm să utilizați instrumentul de încărcare conectat în ecranul Rezumat pacient.');
