INSERT INTO `lang_definitions` VALUES (155339, 5275, 26, 'În același mod, veți crea un rezultat discret pentru potasiu, clorură și dioxid de carbon');
INSERT INTO `lang_definitions` VALUES (155340, 5276, 26, 'În același mod, creați un articol preferat personalizat pentru TSH (secvența 2, cod de identificare WWT02, cod standard 30166-3) și vitamina D (secvența 3, cod de identificare WWT03, cod standard 35365-6)');
INSERT INTO `lang_definitions` VALUES (155341, 5277, 26, 'În același mod, creați un rezultat discret pentru TSH (secvența - 2, cod de identificare - WWT02R, unități implicite - mU/L, interval implicit - 0,4-4, lăsați necompletat serviciile de urmărire) și vitamina D (secvența - 3, cod de identificare - WWT03R, Unități implicite - ng/mL, Interval implicit - 0-20, lăsați necompletat Serviciile de urmărire)');
INSERT INTO `lang_definitions` VALUES (155342, 5278, 26, 'În plus, există 2 casete de selectare');
INSERT INTO `lang_definitions` VALUES (155343, 5279, 26, 'Pe lângă crearea unei recomandări, sistemul vă permite și să imprimați un formular de recomandare necompletat, care poate fi completat manual pentru a genera o recomandare.');
INSERT INTO `lang_definitions` VALUES (155344, 5280, 26, 'În orice caz, stabilirea unei conexiuni, asigurarea conformității HIPAA, securitatea datelor etc. va necesita codare, costul căruia este în general suportat de laborator. Cu toate acestea, ei vor aproba doar dacă volumul de afaceri justifică investiția lor');
INSERT INTO `lang_definitions` VALUES (155345, 5282, 26, 'În chatul curent');
INSERT INTO `lang_definitions` VALUES (155346, 5283, 26, 'în fiecare ochi');
