INSERT INTO `lang_definitions` VALUES (155350, 5289, 26, 'în nară');
INSERT INTO `lang_definitions` VALUES (155351, 5290, 26, 'În birou');
INSERT INTO `lang_definitions` VALUES (155352, 5291, 26, 'În openEMR, rapoartele de înregistrare a continuității îngrijirii (CCR) care trebuie generate pot fi limitate la un anumit interval de date, bifând caseta de selectare Utilizare interval de date și introducând intervalul de date dorit.');
INSERT INTO `lang_definitions` VALUES (155353, 5292, 26, 'Pentru a îndeplini cerințele de utilizare semnificativă pentru intrarea computerizată a comenzilor furnizorilor (CPOE) pentru testele de laborator și radiologie, acest modul trebuie utilizat');
INSERT INTO `lang_definitions` VALUES (155354, 5293, 26, 'Pentru a stoca și a prelua corect rezultatele testelor și pentru a plasa comenzi noi, testele/comenzile trebuie configurate într-o manieră ierarhică');
INSERT INTO `lang_definitions` VALUES (155355, 5294, 26, 'Pentru a înregistra valorile rezultatelor returnate, trebuie să creați un rezultat discret separat (Nivelul 4) pentru fiecare dintre constituenții panoului, fructul, ca descendenți direcți ai acestei ramuri (General Health Panel) (Nivelul 3). Exemple de rezultate fiind CBC - Hemoglobina, CBC - Hematocrit, CMP - Sodiu, CMP - Potasiu, TSH etc.');
INSERT INTO `lang_definitions` VALUES (155356, 5295, 26, 'Pentru a vă înregistra dispozitivul, vă rugăm să furnizați parola de conectare OpenEMR');
INSERT INTO `lang_definitions` VALUES (155357, 5296, 26, 'Pentru a trimite înregistrarea de continuitate a îngrijirii (CCR) și/sau documentul de continuitate a îngrijirii (CCD), opțional, verificați phiMail Allow CCD Send și/sau phiMail Allow CCR Send pentru a activa caracteristica Transmit pentru aceste tipuri de date');
INSERT INTO `lang_definitions` VALUES (155358, 5297, 26, 'În cazul nostru, vom alege Local Lab care a fost configurat anterior');
INSERT INTO `lang_definitions` VALUES (155359, 5298, 26, 'În cazul nostru, îl vom lăsa ca Neatribuit');
INSERT INTO `lang_definitions` VALUES (155360, 5300, 26, 'În modul Portret, determină înălțimea plicului de-a lungul axei y în mm');
INSERT INTO `lang_definitions` VALUES (155361, 5301, 26, 'În modul Portret, determină lățimea plicului de-a lungul axei x în mm');
INSERT INTO `lang_definitions` VALUES (155362, 5302, 26, 'în ochiul drept');
INSERT INTO `lang_definitions` VALUES (155363, 5303, 26, 'Pe scurt, se pot face comenzi electronice, implică o cantitate semnificativă de testare și personalizare pentru a fi certificate de laborator, în general printr-o terță parte și se poate întâmpla doar dacă laboratorul este de acord să dea undă verde proiectului.');
INSERT INTO `lang_definitions` VALUES (155364, 5304, 26, 'În secțiunea „Postează articol” care este afișată în partea de sus, puteți introduce o sursă (de exemplu, numărul cecului), data plății și suma cecului. Motivul sursei și datei plății este astfel încât să nu fie nevoie să le introduceți din nou și din nou pentru fiecare revendicare. Suma pe care o introduceți va fi redusă pentru fiecare factură care i se acordă o parte din plată și, sperăm, se va termina la zero când ați terminat.');
INSERT INTO `lang_definitions` VALUES (155365, 5305, 26, 'În exemplul de mai sus a fost creată o comandă pentru un singur test, adică Acid Uric seric');
INSERT INTO `lang_definitions` VALUES (155366, 5306, 26, 'În instalarea implicită, faceți clic pe Adăugare pentru a afișa pagina pop-up Adăugare/Editare problemă');
INSERT INTO `lang_definitions` VALUES (155367, 5307, 26, 'În cuvintele pacientului');
INSERT INTO `lang_definitions` VALUES (155368, 5308, 26, 'În a doua etapă a utilizării semnificative, CCD, dar nu CCR, a fost inclus ca parte a standardului pentru schimbul de documente clinice.');
INSERT INTO `lang_definitions` VALUES (155369, 5309, 26, 'În acest caz, grupul personalizat preferat se va numi Preop Labs, iar cele două panouri recunoscute vor fi descendenți direcți, fiecare într-un nivel personalizat de articole preferate denumit CBC și respectiv Panel renal');
INSERT INTO `lang_definitions` VALUES (155370, 5310, 26, 'În acest caz, veți crea un Ordin de procedură, ramura fructiferă numită General Health Panel (Nivelul 3)');
INSERT INTO `lang_definitions` VALUES (155371, 5311, 26, 'În total, există șaptesprezece secțiuni care pot fi incluse într-o înregistrare a continuității îngrijirii (CCR)');
