INSERT INTO `lang_definitions` VALUES (155736, 5702, 26, 'Conține date structurate care sunt incluse în înregistrarea de continuitate a îngrijirii (CCR) stabilită la standardul de arhitectură a documentelor clinice.');
INSERT INTO `lang_definitions` VALUES (155737, 5703, 26, 'Nu se referă la trimiterea reală care a fost creată');
INSERT INTO `lang_definitions` VALUES (155738, 5704, 26, 'Face acest lucru folosind un algoritm pentru a combina ora UNIX curentă cu cheia secretă pentru a genera o cheie unică în continuă schimbare.');
INSERT INTO `lang_definitions` VALUES (155739, 5705, 26, 'Are patru file');
INSERT INTO `lang_definitions` VALUES (155740, 5706, 26, 'Are trei niveluri');
INSERT INTO `lang_definitions` VALUES (155741, 5707, 26, 'Este un modul de mesagerie comercial disponibil pentru practicile openEMR care utilizează versiunea 5.0.1 și o versiune ulterioară');
INSERT INTO `lang_definitions` VALUES (155742, 5708, 26, 'Este un câmp din antetul mesajului HL7 cunoscut sub numele de Procesare ID');
INSERT INTO `lang_definitions` VALUES (155743, 5709, 26, 'Face parte din dosarul medical');
INSERT INTO `lang_definitions` VALUES (155744, 5710, 26, 'Este, de asemenea, un serviciu bazat pe abonament');
INSERT INTO `lang_definitions` VALUES (155745, 5711, 26, 'De asemenea, este necesar să enumerați un cod ICD10 pentru ca problema să fie listată în Raportul de continuitate a îngrijirii (CCR) și Documentul de continuitate a îngrijirii (CCD)');
INSERT INTO `lang_definitions` VALUES (155746, 5712, 26, 'Este împărțit în două secțiuni');
INSERT INTO `lang_definitions` VALUES (155747, 5713, 26, 'Este esențial să citiți primele patru secțiuni pentru a înțelege principiile care stau la baza');
INSERT INTO `lang_definitions` VALUES (155748, 5714, 26, 'Este mult mai ușor și intuitiv să faceți modificări majore și să reorganizați datele pe foaia de calcul înainte de a începe să introduceți datele în openEMR');
INSERT INTO `lang_definitions` VALUES (155749, 5715, 26, 'Este important să realizați că aceasta gestionează MFA pentru utilizatorul conectat');
INSERT INTO `lang_definitions` VALUES (155750, 5716, 26, 'Este important să înțelegeți funcția acestor două pictograme, deoarece toți pașii următori necesari pentru configurarea corectă a ierarhiei vor depinde de utilizarea corectă a acestor două pictograme.');
INSERT INTO `lang_definitions` VALUES (155751, 5717, 26, 'Este destinat să includă doar informațiile care sunt esențiale pentru a continua îngrijirea în mod eficient');
INSERT INTO `lang_definitions` VALUES (155752, 5718, 26, 'Este eliberat furnizorilor de servicii medicale din Statele Unite de către Centers for Medicare and Medicaid Services (CMS)');
INSERT INTO `lang_definitions` VALUES (155753, 5719, 26, 'Nu este necesar pentru laboratorul local, în schimb puteți utiliza orice număr unic arbitrar');
INSERT INTO `lang_definitions` VALUES (155754, 5720, 26, 'Nu este necesar să completați codurile implicite de diagnostic deoarece codurile ICD10 pot fi introduse în momentul comandării efective a testului');
INSERT INTO `lang_definitions` VALUES (155755, 5721, 26, 'Nu se depune cu cererea');
INSERT INTO `lang_definitions` VALUES (155756, 5722, 26, 'Nu este neobișnuit să comandați mai multe analize de sânge împreună, gruparea lor ca un panou de teste facilitează acest proces');
INSERT INTO `lang_definitions` VALUES (155757, 5723, 26, 'Este prudent să urmăriți furnizorul dacă nu este contactat.');
INSERT INTO `lang_definitions` VALUES (155758, 5724, 26, 'Este formularul de cerere de bază pe hârtie prescris de mulți plătitori pentru cererile depuse de către medici și cabinete individuale, asistente și profesioniști, inclusiv terapeuți, chiropracticieni și clinici de ambulatoriu și, în unele cazuri, pentru serviciile de ambulanță.');
INSERT INTO `lang_definitions` VALUES (155759, 5725, 26, 'Este folosit pentru a lega problemele cu întâlniri și este, de asemenea, folosit pentru a vedea care întâlniri sunt asociate cu o anumită problemă');
INSERT INTO `lang_definitions` VALUES (155760, 5726, 26, 'Este util să exersați pe un site de probă pentru a vă familiariza cu procesul înainte de a face acest lucru pe aplicația de producție openEMR');
INSERT INTO `lang_definitions` VALUES (155761, 5727, 26, 'Vă permite să căutați după codurile de diagnostic ICD 9 și ICD 10 și codurile de serviciu/procedură CPT4 și HCPCS');
INSERT INTO `lang_definitions` VALUES (155762, 5728, 26, 'Vă permite să trimiteți mesaje și memento-uri datate membrilor personalului, să adăugați pacient la lista de rechemare și să trimiteți mesaje text SMS pacienților');
INSERT INTO `lang_definitions` VALUES (155763, 5729, 26, 'Acesta servește ca o punte necesară către un mediu diferit, adesea cu medici noi care nu știu nimic despre pacient, permițând următorului furnizor să');
INSERT INTO `lang_definitions` VALUES (155764, 5731, 26, 'Prin urmare, este de la sine înțeles că nu puteți crea o contra-referire de la sine');
INSERT INTO `lang_definitions` VALUES (155765, 5732, 26, 'Utilizează un standard deschis și, prin urmare, este disponibil de la diferiți producători');
INSERT INTO `lang_definitions` VALUES (155766, 5733, 26, 'Utilizează funcția hash HMAC-SHA256 pentru a genera o cheie privată unică pentru cont');
INSERT INTO `lang_definitions` VALUES (155767, 5734, 26, 'Folosește această cheie privată pentru a semna provocarea și trimite răspunsul înapoi la aplicație');
INSERT INTO `lang_definitions` VALUES (155768, 5735, 26, 'Acesta va fi afișat în rezumatul vizitei');
INSERT INTO `lang_definitions` VALUES (155769, 5736, 26, 'Va apărea formularul pop-up Introducere detalii');
INSERT INTO `lang_definitions` VALUES (155770, 5737, 26, 'Va apărea fereastra pop-up Găsire pacienți multipli');
INSERT INTO `lang_definitions` VALUES (155771, 5738, 26, 'Va afișa fereastra pop-up de afișare justificare. Are o casetă de căutare care vă va permite să căutați un cod ICD. De asemenea, va afișa cele 10 coduri ICD cele mai frecvent utilizate. Puteți selecta oricare sau toate codurile bifând caseta de validare J (justificare) și apăsând actualizare');
INSERT INTO `lang_definitions` VALUES (155772, 5739, 26, 'Acesta va avea o valoare de 2 în coloana de nivel, indicând că este un succesor sau un copil pe prima linie de mai sus, având o valoare de nivel de 1, care în acest caz este Chimia serului');
INSERT INTO `lang_definitions` VALUES (155773, 5740, 26, 'Va avea două secțiuni - Secțiunea Probleme și Secțiunea Întâlniri');
INSERT INTO `lang_definitions` VALUES (155774, 5741, 26, 'Acesta vă va ajuta mai târziu la depanarea problemelor care pot apărea cu configurarea modulului Procedure Orders');
INSERT INTO `lang_definitions` VALUES (155775, 5742, 26, 'Se va deschide secțiunea Creare mesaj nou');
INSERT INTO `lang_definitions` VALUES (155776, 5743, 26, 'Vă va duce la pagina de înscriere MedEx');
INSERT INTO `lang_definitions` VALUES (155777, 5744, 26, 'Va apărea apoi în widget-ul Alergii din Tabloul de bord pentru pacient, precum și sub alergii din pagina Probleme');
INSERT INTO `lang_definitions` VALUES (155778, 5745, 26, 'Acesta va apărea apoi în widget-ul Medicamente din Tabloul de bord pentru pacient, precum și sub Medicamente din pagina Probleme');
