INSERT INTO `lang_definitions` VALUES (157176, 7237, 26, 'Rețineți că este recomandat să evitați aprobarea aplicațiilor SMART care nu se înregistrează ca client confidențial. Aceste aplicații sunt mai puțin sigure și ar trebui să fie foarte restricționate în domeniile OAUTH2 pe care le permiteți să le acceseze.');
INSERT INTO `lang_definitions` VALUES (157177, 7238, 26, 'Rețineți că va dura 5-10 minute pentru a procesa complet după ce faceți clic pe Instalare');
INSERT INTO `lang_definitions` VALUES (157178, 7239, 26, 'Rețineți că procesarea completă va dura 5-10 minute după ce faceți clic pe Upgrade');
INSERT INTO `lang_definitions` VALUES (157179, 7240, 26, 'Rețineți că înregistrarea de audit trebuie să fie activată mai sus');
INSERT INTO `lang_definitions` VALUES (157180, 7241, 26, 'Rețineți că Backup-ul Eventlog este setat în prezent să fie salvat în următorul folder');
INSERT INTO `lang_definitions` VALUES (157181, 7242, 26, 'Rețineți că titlul formularului pop-up va citi acum Introduceți detalii pentru grupul preferat personalizat');
INSERT INTO `lang_definitions` VALUES (157182, 7243, 26, 'Rețineți că titlul formularului pop-up va citi acum Introduceți detalii pentru rezultate discrete');
INSERT INTO `lang_definitions` VALUES (157183, 7244, 26, 'Rețineți că titlul formularului pop-up va citi acum Introduceți detalii pentru procedurile individuale');
INSERT INTO `lang_definitions` VALUES (157184, 7245, 26, 'Rețineți că nu există niciun buton „Salvare”.');
INSERT INTO `lang_definitions` VALUES (157185, 7246, 26, 'Rețineți că acest lucru se referă la înregistrarea de continuitate a îngrijirii (CCR) sau la documentul de continuitate a îngrijirii (CCD), după caz');
