INSERT INTO `lang_definitions` VALUES (157187, 7248, 26, 'Notă: ora 12:00 este PM, nu AM');
INSERT INTO `lang_definitions` VALUES (157188, 7249, 26, 'NOTĂ: Importarea datelor externe poate dura mai mult de o oră, în funcție de configurația hardware. De exemplu, unul dintre tabelele de date RxNorm conține peste 6 milioane de rânduri.');
INSERT INTO `lang_definitions` VALUES (157189, 7250, 26, 'NOTĂ: Numai versiunea bianuală internațională Snomed este acceptată în prezent');
INSERT INTO `lang_definitions` VALUES (157190, 7251, 26, 'NOTĂ: sunt acceptate în prezent doar lansările internaționale bianuale Snomed și versiunile Snomed din SUA');
