INSERT INTO `lang_definitions` VALUES (157192, 7253, 26, 'NOTĂ: Sunt acceptate numai formatele XML și seturile de valori pentru Profesioniști eligibili');
INSERT INTO `lang_definitions` VALUES (157193, 7254, 26, 'NOTĂ: importul poate dura până la câteva ore');
INSERT INTO `lang_definitions` VALUES (157194, 7255, 26, 'Notă: Acest cod nu a fost autorizat.');
INSERT INTO `lang_definitions` VALUES (157195, 7256, 26, 'Notă: Acest cod nu a fost introdus de către un utilizator autorizat. Numai codurile autorizate pot fi încărcate în Open Medical Billing Network pentru procesare. Dacă doriți să încărcați aceste coduri, vă rugăm să selectați un utilizator autorizat aici.');
INSERT INTO `lang_definitions` VALUES (157196, 7257, 26, 'Notă: această coplă a fost introdusă pentru facturare care nu a fost autorizată. Vă rugăm să examinați starea.');
INSERT INTO `lang_definitions` VALUES (157197, 7258, 26, 'Notă: aceasta nu este o adresă de e-mail');
INSERT INTO `lang_definitions` VALUES (157198, 7259, 26, 'NOTĂ: Încărcarea fișierelor cu nume duplicate va face ca fișierele să fie redenumite automat (de exemplu, fișier.jpg va deveni fișier.1.jpg). Numele fișierelor sunt considerate unice pe pacient, nu pe categorie.');
INSERT INTO `lang_definitions` VALUES (157199, 7260, 26, 'NOTĂ: Încărcarea fișierelor cu nume duplicat va face ca fișierele să fie redenumite automat. De exemplu, „<i>fișier.jpg</i>” va deveni „<i>fișier.jpg.1</i>”. Numele fișierelor sunt considerate unice pe pacient, nu pe categorie.');
