INSERT INTO `lang_definitions` VALUES (157387, 7455, 26, 'Odată salvată, entitatea pentru un grup preferat personalizat nu poate fi modificată. Dacă trebuie să schimbați entitatea, trebuie să ștergeți această intrare și să creați una nouă');
