INSERT INTO `lang_definitions` VALUES (157975, 8068, 26, 'Acordați atenție casetelor de selectare „Terminat cu”. După ce asigurările sunt marcate ca finalizate, vom începe să cerem pacientului să plătească soldul rămas; dacă nu reușiți să marcați toate asigurările complete, atunci suma rămasă nu va fi colectată! De asemenea, dacă există un sold pe care pacientul ar trebui să-l plătească, atunci setați data scadenței în mod corespunzător, deoarece acest lucru va afecta limbajul care apare pe extrasele pacientului.');
INSERT INTO `lang_definitions` VALUES (157976, 8069, 26, 'Acordați atenție casetelor de selectare „Terminat”. După ce asigurările sunt marcate ca finalizate, vom începe să cerem pacientului să plătească soldul rămas; dacă nu reușiți să marcați toate asigurările complete, atunci suma rămasă nu va fi colectată! De asemenea, dacă există un sold pe care pacientul ar trebui să-l plătească, atunci setați data scadenței în mod corespunzător, deoarece acest lucru va afecta limbajul care apare pe extrasele pacientului.');
