INSERT INTO `lang_definitions` VALUES (160662, 10954, 26, 'Butonul „Șterge” va elimina toate adnotările.');
INSERT INTO `lang_definitions` VALUES (160663, 10955, 26, 'Fereastra „Editare” este împărțită în două coloane, „Activ” și „Inactiv”. Grupurile (ARO) care sunt listate în coloana activă sunt acele grupuri cărora le aparține utilizatorul.');
INSERT INTO `lang_definitions` VALUES (160664, 10956, 26, 'Secțiunea „Selectați coduri” va avea acum toate codurile CPT și ICD pe care le-ați introdus grupate în categoriile pe care le-ați decis');
INSERT INTO `lang_definitions` VALUES (160665, 10957, 26, 'Tasta *Tab* creează fiecare intrare.');
INSERT INTO `lang_definitions` VALUES (160666, 10958, 26, 'Formularul de revendicare 1500 poate fi, de asemenea, utilizat pentru a raporta datele privind întâlnirile pacienților către agenții federale, de stat și/sau alte agenții de sănătate publică');
INSERT INTO `lang_definitions` VALUES (160667, 10959, 26, '837P (Professional) este formatul standard utilizat de profesioniștii din domeniul sănătății și furnizorii pentru a transmite cererile de îngrijire a sănătății pe cale electronică');
INSERT INTO `lang_definitions` VALUES (160668, 10960, 26, 'Capacitatea de a lega problemele individuale la întâlnirile cu pacienții îi va permite utilizatorului să determine rapid rezultatul problemei în timp');
INSERT INTO `lang_definitions` VALUES (160669, 10961, 26, 'Declarația de mai sus a eșuat');
INSERT INTO `lang_definitions` VALUES (160670, 10962, 26, 'ACL pagina două secțiuni.');
INSERT INTO `lang_definitions` VALUES (160671, 10963, 26, 'Sumele reale care vor fi afișate trebuie să existe în baza de date');
INSERT INTO `lang_definitions` VALUES (160672, 10964, 26, 'Testele sau procedurile reale care pot fi căutate și comandate sunt evidențiate cu galben');
INSERT INTO `lang_definitions` VALUES (160673, 10965, 26, 'Pictograma Adăugați este folosită pentru a configura un nivel care va fi un descendent direct al acestui nivel');
INSERT INTO `lang_definitions` VALUES (160674, 10966, 26, 'Avantajul integrării rezultatelor cu diagrama pacientului ca date structurate este capacitatea de a le manipula pentru a vedea tendințele într-o locație convenabilă, de a reprezenta grafice cu datele și de a le utiliza în analiza datelor.');
INSERT INTO `lang_definitions` VALUES (160675, 10967, 26, 'Avantajul scanării rezultatelor în diagramă este simplitatea - nu este necesară nicio configurare, în afară de definirea unui director/dosar în diagrama pacientului sub Documente unde va fi stocat rezultatul. Fiind date nestructurate, nu are avantajele de mai sus și nu vor îndeplini criteriile de utilizare semnificativă pentru introducerea computerizată a comenzilor furnizorilor (CPOE)');
INSERT INTO `lang_definitions` VALUES (160676, 10968, 26, 'Soluția Allscripts integrează site-ul web Allscripts ePrescribe cu openEMR');
INSERT INTO `lang_definitions` VALUES (160677, 10969, 26, 'Asociația Medicală Americană a definit 9 panouri care pot fi comandate. Fiecare panou conține mai multe teste grupate împreună');
INSERT INTO `lang_definitions` VALUES (160678, 10970, 26, 'Suma va fi afișată fie în coloana Plată, fie în coloana Ajustare, după caz');
INSERT INTO `lang_definitions` VALUES (160679, 10971, 26, 'Certificatul serverului Apache SSL și cheia publică');
INSERT INTO `lang_definitions` VALUES (160680, 10972, 26, 'Aplicația generează provocare - un număr aleatoriu și îl transmite cheii USB împreună cu nonce și suma de control stocate în aplicație');
INSERT INTO `lang_definitions` VALUES (160681, 10973, 26, 'Aplicația folosește apoi cheia publică pe care dispozitivul USB a trimis-o la înregistrare pentru a verifica răspunsul');
INSERT INTO `lang_definitions` VALUES (160682, 10974, 26, 'Modificările privind starea întâlnirilor și creările de întâlniri sunt gestionate prin Monitorul pacienților.');
INSERT INTO `lang_definitions` VALUES (160683, 10975, 26, 'Numele de autentificare sau cheia API pentru contul selectat. Nume de autorizare pentru Authorize.Net și API Secret pentru Stripe.');
INSERT INTO `lang_definitions` VALUES (160684, 10976, 26, 'Coloana Sold ar fi goală');
INSERT INTO `lang_definitions` VALUES (160685, 10977, 26, 'Scopul de bază al aplicației de autentificare este de a genera un cod de 20 de octeți (160 de biți) codificat în base32 folosind o funcție hash securizată, SHA-1, și se numește HMAC-SHA1 (Cod de autentificare a mesajelor bazat pe hash).');
INSERT INTO `lang_definitions` VALUES (160686, 10978, 26, 'Baza pentru CCR este un Formular de trimitere pentru îngrijirea pacientului dezvoltat de Departamentul de Sănătate Publică din Massachusetts');
INSERT INTO `lang_definitions` VALUES (160687, 10979, 26, 'Coloana Data facturată/Plătitor va afișa data la care a fost primită plata articolului rând și numele plătitorului - fie asigurare, fie pacient');
INSERT INTO `lang_definitions` VALUES (160688, 10980, 26, 'Coloana Data facturată/Plătitor va afișa data la care elementul rând a fost facturat și plătitorul - fie asigurare, fie pacient');
INSERT INTO `lang_definitions` VALUES (160689, 10981, 26, 'Corpul conține datele clinice care pot fi structurate și organizate ca una sau mai multe secțiuni sau pot fi un bloc de date nestructurat');
INSERT INTO `lang_definitions` VALUES (160690, 10982, 26, 'Casetele Body Site, Administer Via și Laterality pot fi lăsate ca Neassigned');
INSERT INTO `lang_definitions` VALUES (160691, 10983, 26, 'Grupa de jos este formată din Copay');
INSERT INTO `lang_definitions` VALUES (160692, 10984, 26, 'Coloana Categorie va fi Grup personalizat de top și va fi evidențiată cu roz');
INSERT INTO `lang_definitions` VALUES (160693, 10985, 26, 'Coloana Categorie va spune Ordine indicând că este o comandă');
INSERT INTO `lang_definitions` VALUES (160694, 10986, 26, 'Categoria va fi Rezultat');
INSERT INTO `lang_definitions` VALUES (160695, 10987, 26, 'CDA este un document cu text simplu care este codificat folosind Extensible Markup Language (XML) și conține un antet și un corp.');
INSERT INTO `lang_definitions` VALUES (160696, 10988, 26, 'Certificatul Autorității de Certificare');
INSERT INTO `lang_definitions` VALUES (160697, 10989, 26, 'Coloana Charge va fi goală');
INSERT INTO `lang_definitions` VALUES (160698, 10990, 26, 'Taxa va fi suma efectivă percepută pentru fiecare element rând');
INSERT INTO `lang_definitions` VALUES (160699, 10991, 26, 'Dosarul de revendicare:');
INSERT INTO `lang_definitions` VALUES (160700, 10992, 26, 'Formularul CMS 1500 are 33 de casete și este împărțit în două secțiuni');
INSERT INTO `lang_definitions` VALUES (160701, 10993, 26, 'Coloana Cod ar trebui să aibă 905, codul de identificare specific furnizorului care a fost introdus anterior');
INSERT INTO `lang_definitions` VALUES (160702, 10994, 26, 'Coloana Cod va fi goală, deoarece elementele listate ca grup nu sunt utilizate în raportarea efectivă a rezultatelor și, prin urmare, nu au un număr de cod distinct');
INSERT INTO `lang_definitions` VALUES (160703, 10995, 26, 'Codul va fi R905, valoarea codului de identificare care a fost introdusă pentru rezultatul discret');
INSERT INTO `lang_definitions` VALUES (160704, 10996, 26, 'Codul introdus nu a fost valid');
INSERT INTO `lang_definitions` VALUES (160705, 10997, 26, 'Pachetul compatibil US Extension SNOMED în etape a fost deja instalat.');
INSERT INTO `lang_definitions` VALUES (160706, 10998, 26, 'Celula Contacte are diverse informații de contact, cum ar fi numere de telefon, e-mail etc');
INSERT INTO `lang_definitions` VALUES (160707, 10999, 26, 'Documentul de continuitate a îngrijirii (CCD) și înregistrarea de continuitate a îngrijirii (CCR) au fost ambele selectate ca formate acceptabile pentru a extrage informații pentru rezumatele îngrijirii clinice, ca parte a Etapei 1 de utilizare semnificativă.');
INSERT INTO `lang_definitions` VALUES (160708, 11000, 26, 'Continuity of Care Record (CCR) a fost dezvoltat în comun de ASTM International - o organizație care este implicată în dezvoltarea și furnizarea de consens voluntar, Massachusetts Medical Society (MMS), Health Information Management and Systems Society (HIMSS), Academia Americană a Medicilor de Familie (AAFP) și Academia Americană de Pediatrie');
INSERT INTO `lang_definitions` VALUES (160709, 11001, 26, 'Fișa de continuitate a îngrijirii (CCR) este fișa clinică a stării medicale curente și istorice a pacientului');
INSERT INTO `lang_definitions` VALUES (160710, 11002, 26, 'Setul de date de bază este format din');
INSERT INTO `lang_definitions` VALUES (160711, 11003, 26, 'Cheia privată corespunzătoare');
INSERT INTO `lang_definitions` VALUES (160712, 11004, 26, 'Raportul creat poate conține cât mai multe sau cât mai puține informații în funcție de nevoi');
INSERT INTO `lang_definitions` VALUES (160713, 11005, 26, 'Metoda curentă de autentificare pentru secțiunea de utilizator conectat va prezenta acum metodele activate');
INSERT INTO `lang_definitions` VALUES (160714, 11006, 26, 'Metoda de autentificare curentă listează toate metodele care sunt active');
INSERT INTO `lang_definitions` VALUES (160715, 11007, 26, 'Se poate folosi Taxa personalizata. Dacă și când întâlniți un cod care nu există în secțiunea personalizată „Selectați coduri”, puteți utiliza întotdeauna secțiunea „Căutare coduri suplimentare”');
INSERT INTO `lang_definitions` VALUES (160716, 11008, 26, 'Nivelul articolului preferat personalizat ar trebui să fie descendentul direct sau un copil al grupului preferat personalizat relevant');
INSERT INTO `lang_definitions` VALUES (160717, 11009, 26, 'Gruparea personalizată vă va permite, de asemenea, să grupați două panouri recunoscute de teste într-un grup personalizat și astfel să le ordonați împreună, de ex. un grup personalizat de laboratoare Preop poate conține două panouri, CBC și Renal Panel');
INSERT INTO `lang_definitions` VALUES (160718, 11010, 26, 'Tabloul de bord este locația centrală pentru acces comod la dosarul medical al pacientului');
INSERT INTO `lang_definitions` VALUES (160719, 11011, 26, 'Pagina Tabloul de bord este împărțită în trei secțiuni');
INSERT INTO `lang_definitions` VALUES (160720, 11012, 26, 'Testul de integritate a datelor a eșuat pentru acest formular');
INSERT INTO `lang_definitions` VALUES (160721, 11013, 26, 'Secțiunea de date a paginii tabloului de bord listează toate elementele pertinente legate de un pacient');
INSERT INTO `lang_definitions` VALUES (160722, 11014, 26, 'Memento-ul datat va începe să apară cu 5 zile înainte de data mementoului, sub Memento-uri datate');
INSERT INTO `lang_definitions` VALUES (160723, 11015, 26, 'Tipul de cod implicit de căutat în Foaia de taxe.');
INSERT INTO `lang_definitions` VALUES (160724, 11016, 26, 'Taxa implicită de taxe poate fi modificată și personalizată pentru a o face mai utilă.');
INSERT INTO `lang_definitions` VALUES (160725, 11017, 26, 'Fișa de taxă implicită este împărțită în mai multe secțiuni și este concepută pentru a fi completată de sus în jos cu butonul de salvare la sfârșit.');
INSERT INTO `lang_definitions` VALUES (160726, 11018, 26, 'Formularul implicit poate fi personalizat prin editarea lui în Administrare > Aspecte');
INSERT INTO `lang_definitions` VALUES (160727, 11019, 26, 'Setarea implicită are două butoane care sunt setate pentru „Pacient nou” și „Pacient stabilit”.');
INSERT INTO `lang_definitions` VALUES (160728, 11020, 26, 'Instalarea implicită are șase astfel de grupuri - Contabilitate, Administratori, Clinicieni, Conectare de urgență, Front Office și Medici.');
INSERT INTO `lang_definitions` VALUES (160729, 11021, 26, 'Instalarea implicită are următoarele elemente');
INSERT INTO `lang_definitions` VALUES (160730, 11022, 26, 'Instalarea implicită listează 5 tipuri de probleme care pot fi documentate');
INSERT INTO `lang_definitions` VALUES (160731, 11023, 26, 'Instalarea implicită nu va efectua automat apelul telefonic');
INSERT INTO `lang_definitions` VALUES (160732, 11024, 26, 'Valoarea implicită este „Standard”, utilizată de obicei pentru a reflecta tarifele percepute pentru facturarea asigurărilor. Puteți solicita o sumă diferită pentru plata cu cardul de credit și pentru plata în numerar');
INSERT INTO `lang_definitions` VALUES (160733, 11025, 26, 'Valoarea implicită este Normală, adică este vizibilă pentru toată lumea. Selectarea High va restricționa la utilizatorii care aparțin grupurilor Medici și Administratori în mod implicit');
INSERT INTO `lang_definitions` VALUES (160734, 11026, 26, 'Tipul de problemă implicit este setat la Problemă');
INSERT INTO `lang_definitions` VALUES (160735, 11027, 26, 'Centrul de mesagerie implicit este împărțit în trei secțiuni - Mesaje, Mementouri și Rechemari');
INSERT INTO `lang_definitions` VALUES (160736, 11028, 26, 'Pot fi setate valorile implicite pentru furnizorii de randare');
INSERT INTO `lang_definitions` VALUES (160737, 11029, 26, 'codul de refuzare este');
INSERT INTO `lang_definitions` VALUES (160738, 11030, 26, 'codul grupului de refuz este');
INSERT INTO `lang_definitions` VALUES (160739, 11031, 26, 'Coloana Descriere afișează scurta descriere care a fost introdusă, Teste de chimie a serului');
INSERT INTO `lang_definitions` VALUES (160740, 11032, 26, 'Coloana Descriere va reflecta valoarea descrierii care a fost introdusă anterior');
INSERT INTO `lang_definitions` VALUES (160741, 11033, 26, 'Descrierea ar trebui să spună rezultatul acidului uric seric');
INSERT INTO `lang_definitions` VALUES (160742, 11034, 26, 'Descrierea va detalia tipul de plată sau ajustare - numerar, cec, electronic etc');
INSERT INTO `lang_definitions` VALUES (160743, 11035, 26, 'Formularul de destinație a fost închis');
INSERT INTO `lang_definitions` VALUES (160744, 11036, 26, 'Formularul de destinație a fost închis.');
INSERT INTO `lang_definitions` VALUES (160745, 11037, 26, 'Formularul de destinație a fost închis; Nu pot acționa în funcție de selecția dvs.');
INSERT INTO `lang_definitions` VALUES (160746, 11038, 26, 'Diferența dintre cele două este că, pentru un grup de teste care sunt ordonate împreună, testele individuale sunt reprezentate doar de Rezultat discret și aceste teste nu pot fi comandate separat decât dacă au fost configurate și ca teste unice.');
INSERT INTO `lang_definitions` VALUES (160747, 11039, 26, 'Nivelul de rezultat discret trebuie să fie descendentul direct sau copilul unui nivel de ordine de procedură pentru afișarea corectă a rezultatelor');
INSERT INTO `lang_definitions` VALUES (160748, 11040, 26, 'Rezultatele discrete pentru fiecare panou vor conține numele testelor individuale pentru a păstra valorile rezultatelor returnate - leucocite, hemoglobină, trombocite, sodiu, potasiu etc.');
INSERT INTO `lang_definitions` VALUES (160749, 11041, 26, 'Fereastra de afișare poate fi redimensionată făcând clic și trăgând colțul din dreapta jos al ferestrei');
INSERT INTO `lang_definitions` VALUES (160750, 11042, 26, 'Opțiunea Fiecare întâlnire va permite o nouă întâlnire, indiferent de vizita în aceeași zi.');
INSERT INTO `lang_definitions` VALUES (160751, 11043, 26, 'Butonul Previzualizare întâlnire este util pentru afișarea formularelor de aspect al tipului de întâlnire, așa cum se vede atunci când se utilizează formularul într-o întâlnire. Rețineți că această funcție este utilă numai pentru afișarea formularelor de întâlnire și nu va afișa formulare de sistem, cum ar fi Date demografice');
INSERT INTO `lang_definitions` VALUES (160752, 11044, 26, 'Secțiunea Întâlniri va afișa data întâlnirii, precum și reclamația de prezentare');
INSERT INTO `lang_definitions` VALUES (160753, 11045, 26, 'Rezultatul final a fost o colecție confuză de documente care conțineau informații ambigue și/sau conflictuale');
INSERT INTO `lang_definitions` VALUES (160754, 11046, 26, 'Caseta pop-up Introduceți detalii se va deschide în modul Adăugare');
INSERT INTO `lang_definitions` VALUES (160755, 11047, 26, 'Fereastra pop-up Introduceți detaliile furnizorului va fi vizibilă');
INSERT INTO `lang_definitions` VALUES (160756, 11048, 26, 'Întreaga colecție de ACO formează Lista de control al accesului (ACL).');
INSERT INTO `lang_definitions` VALUES (160757, 11049, 26, 'Entitatea pentru un articol personalizat preferat este entitatea aleasă pentru grupul personalizat preferat și nu poate fi modificată');
INSERT INTO `lang_definitions` VALUES (160758, 11050, 26, 'Entitatea care efectuează această procedură');
INSERT INTO `lang_definitions` VALUES (160759, 11051, 26, 'Intrările conțin date utilizate pentru prelucrarea ulterioară pe computer');
INSERT INTO `lang_definitions` VALUES (160760, 11052, 26, 'Intrările evidențiate cu galben pot fi comandate ca test sau procedură cele evidențiate cu roz pot fi comandate ca grup personalizat');
INSERT INTO `lang_definitions` VALUES (160761, 11053, 26, 'PE, spitalul eligibil sau CAH care primește un pacient dintr-un alt cadru de îngrijire sau furnizor de îngrijire sau consideră că o întâlnire este relevantă ar trebui să efectueze reconcilierea medicamentelor.');
INSERT INTO `lang_definitions` VALUES (160762, 11054, 26, 'EP, spitalul eligibil sau CAH care își transferă pacientul într-un alt cadru de îngrijire sau furnizor de îngrijire sau își trimite pacientul către un alt furnizor de îngrijire trebuie să furnizeze un rezumat al fișei de îngrijire pentru fiecare tranziție de îngrijire sau trimitere (Măsura A).');
INSERT INTO `lang_definitions` VALUES (160763, 11055, 26, 'EP, spitalul eligibil sau CAH care își transferă pacientul într-un alt cadru de îngrijire sau furnizor de îngrijire sau își trimite pacientul către un alt furnizor de îngrijire trebuie să furnizeze un rezumat al fișei de îngrijire pentru fiecare tranziție de îngrijire sau trimitere (Măsura B).');
INSERT INTO `lang_definitions` VALUES (160764, 11056, 26, 'EP, spitalul eligibil sau CAH care își transferă pacientul într-un alt cadru de îngrijire sau furnizor de îngrijire sau îl trimite pacientului către un alt furnizor de îngrijire trebuie să furnizeze un rezumat al fișei de îngrijire pentru fiecare tranziție de îngrijire sau trimitere.');
INSERT INTO `lang_definitions` VALUES (160765, 11057, 26, 'Evenimentul(ele) au fost aprobat(e).');
INSERT INTO `lang_definitions` VALUES (160766, 11058, 26, 'Evenimentul(ele) au fost ascunse.');
INSERT INTO `lang_definitions` VALUES (160767, 11059, 26, 'Datele exportate apar în zona de text de mai jos. Puteți copia și lipi acest lucru într-un e-mail sau în orice altă destinație dorită.');
INSERT INTO `lang_definitions` VALUES (160768, 11060, 26, 'Datele exportate apar în zona de text de mai jos. Puteți copia și lipi acest lucru într-un e-mail sau în orice altă destinație dorită (sau) descărcați linkul de mai jos.');
INSERT INTO `lang_definitions` VALUES (160769, 11061, 26, 'Datele exportate apar în zona de text de mai jos. Puteți copia și lipi acest lucru într-un e-mail sau în orice altă destinație dorită.');
INSERT INTO `lang_definitions` VALUES (160770, 11062, 26, 'Datele exportate apar în zona de text de mai jos. Puteți copia și inserați acest lucru într-un e-mail sau în orice altă destinație dorită.{{MARK FOR DELETION DURING NEXT TRANSLATION BUILD}}');
INSERT INTO `lang_definitions` VALUES (160771, 11063, 26, 'Caracteristicile unei instalări compatibile cu MedEx sunt explicate în acest videoclip');
INSERT INTO `lang_definitions` VALUES (160772, 11064, 26, 'Fișierul nu poate fi generat din nou. Vrei sa continui?');
INSERT INTO `lang_definitions` VALUES (160773, 11065, 26, 'Fișierul nu a putut fi salvat în CouchDB.');
INSERT INTO `lang_definitions` VALUES (160774, 11066, 26, 'Fișierul nu a putut fi redenumit cu succes, această eroare este de obicei legată de probleme de permisiuni pe sistemul de stocare.');
INSERT INTO `lang_definitions` VALUES (160775, 11067, 26, 'Fișierul nu a putut fi stocat cu succes, această eroare este de obicei legată de probleme de permisiuni pe sistemul de stocare');
INSERT INTO `lang_definitions` VALUES (160776, 11068, 26, 'Secțiunea de filtru poate fi ascunsă sau dezvăluită făcând clic pe vârful săgeții din dreapta jos');
INSERT INTO `lang_definitions` VALUES (160777, 11069, 26, 'Rezultatele filtrate vor apărea în secțiunea de mai jos');
INSERT INTO `lang_definitions` VALUES (160778, 11070, 26, 'Tabelul de căutare este grupat după procedurile anterioare, apoi codul de diagnostic. Deși pot exista coduri dx duplicate, acestea vor fi grupate cu procedura adecvată, ușurând lista de diagnostice a clădirii.');
INSERT INTO `lang_definitions` VALUES (160779, 11071, 26, 'Prima diagramă („țintă”) este cea care este considerată cea mai completă și mai precisă. Secțiunile demografice, istoric și asigurări pentru aceasta vor fi păstrate.');
INSERT INTO `lang_definitions` VALUES (160780, 11072, 26, 'Prima coloană conține numele Grupului/Categoriei care va fi afișat pe buton');
INSERT INTO `lang_definitions` VALUES (160781, 11073, 26, 'Prima coloană este numele pe care l-ați dat acestei intrări, adică Chimia serului. O bară verticală va precede numele real. Aceasta indică faptul că nu există descendenți sau copii la această intrare');
INSERT INTO `lang_definitions` VALUES (160782, 11074, 26, 'Primele patru secțiuni se ocupă de crearea ordinelor de procedură într-o manieră structurată pentru a facilita comandarea ușoară a testelor și introducerea manuală a rezultatelor returnate.');
INSERT INTO `lang_definitions` VALUES (160783, 11075, 26, 'Prima linie va afișa data și Motivul întâlnirii, precum și furnizorul pentru acea întâlnire');
INSERT INTO `lang_definitions` VALUES (160784, 11076, 26, 'Prima secțiune vă permite fie să legați acest mesaj la un pacient, dacă doriți.');
INSERT INTO `lang_definitions` VALUES (160785, 11077, 26, 'Primul segment din fiecare mesaj HL7 este întotdeauna antetul mesajului, un segment care transmite metadatele mesajului, cum ar fi cine l-a trimis și când. Antetul mesajului este indicat în primele trei litere ale segmentului ca MSH');
INSERT INTO `lang_definitions` VALUES (160786, 11078, 26, 'Primul pas este să vă înscrieți pentru un cont de mesagerie direct de producție cu EMR Direct, înregistrându-vă pe site-ul lor');
INSERT INTO `lang_definitions` VALUES (160787, 11079, 26, 'Primul pas este să descărcați versiunea SNOMED CT. Accesul la SNOMED CT este asigurat de IHTSDO și țările membre ale acestora. Pentru mai multe informații vezi');
INSERT INTO `lang_definitions` VALUES (160788, 11080, 26, 'Primul pas este să descărcați versiunea VALUESET. Accesul la VALUESET este asigurat de NLM. Trebuie descărcat numai setul de valori pentru profesioniști eligibili și ar trebui să fie descărcat în format XML din coloana Sortat după ID CMS. Pentru mai multe detalii vezi linkul de mai jos');
INSERT INTO `lang_definitions` VALUES (160789, 11081, 26, 'Primul pas este să deschideți un cont pe site-ul web Unified Medical Language System');
INSERT INTO `lang_definitions` VALUES (160790, 11082, 26, 'Primul pas este să planificați ce ar trebui să afișeze secțiunea „Selectați coduri” din foaia de taxe');
INSERT INTO `lang_definitions` VALUES (160791, 11083, 26, 'Primul pas este să selectați un tip de tranzacție');
INSERT INTO `lang_definitions` VALUES (160792, 11084, 26, 'Primul pas ar fi crearea unei intrări de nivel superior. Faceți acest lucru făcând clic pe butonul Adăugați nivel superior');
INSERT INTO `lang_definitions` VALUES (160793, 11085, 26, 'Prima filă este fila de recomandare care constituie recomandarea care se face');
INSERT INTO `lang_definitions` VALUES (160794, 11086, 26, 'Primele două numere din prima și a doua coloană vor fi folosite pentru a determina ordinea de sortare a butoanelor și a listelor care sunt prezente în fereastra pop-up');
INSERT INTO `lang_definitions` VALUES (160795, 11087, 26, 'Următorul eveniment din calendar a fost adăugat:');
INSERT INTO `lang_definitions` VALUES (160796, 11088, 26, 'Următorul eveniment din calendar a fost modificat:');
INSERT INTO `lang_definitions` VALUES (160797, 11089, 26, 'Următoarele categorii vor fi eliminate din lista dvs. de categorii');
INSERT INTO `lang_definitions` VALUES (160798, 11090, 26, 'Următoarea versiune a bazei de date este instalată în prezent');
INSERT INTO `lang_definitions` VALUES (160799, 11091, 26, 'La acest mesaj direct au fost atașate următoarele documente:');
INSERT INTO `lang_definitions` VALUES (160800, 11092, 26, 'Următorul fișier EDI nu a putut fi salvat în arhivă');
INSERT INTO `lang_definitions` VALUES (160801, 11093, 26, 'Următorul fișier EDI a fost încărcat');
INSERT INTO `lang_definitions` VALUES (160802, 11094, 26, 'Următorul fișier EDI încărcat nu s-a deschis');
INSERT INTO `lang_definitions` VALUES (160803, 11095, 26, 'Următorul utilizator de conectare de urgență este activat:');
INSERT INTO `lang_definitions` VALUES (160804, 11096, 26, 'Au avut loc următoarele erori');
INSERT INTO `lang_definitions` VALUES (160805, 11097, 26, 'Următorul câmp are o valoare nevalidă');
INSERT INTO `lang_definitions` VALUES (160806, 11098, 26, 'Următoarele câmpuri sunt goale.');
INSERT INTO `lang_definitions` VALUES (160807, 11099, 26, 'Următoarele câmpuri sunt obligatorii');
INSERT INTO `lang_definitions` VALUES (160808, 11100, 26, 'Următoarele câmpuri trebuie completate pentru a trimite o solicitare.');
INSERT INTO `lang_definitions` VALUES (160809, 11101, 26, 'Următoarele câmpuri trebuie completate pentru a trimite cererea.');
INSERT INTO `lang_definitions` VALUES (160810, 11102, 26, 'Sunt acceptate următoarele limbi International Snomed Release');
INSERT INTO `lang_definitions` VALUES (160811, 11104, 26, 'S-au întâmplat următoarele');
INSERT INTO `lang_definitions` VALUES (160812, 11105, 26, 'Următoarele probleme au aceleași coduri de diagnosticare. Problemele de întâlnire nu vor fi actualizate. Vă rugăm să utilizați în schimb interfața de întâlnire.');
INSERT INTO `lang_definitions` VALUES (160813, 11106, 26, 'Următorii pași vă vor ajuta să personalizați foaia de taxe pentru a imita vechiul superbill de hârtie cu o listă de coduri CPT4 și ICD aranjate pe categorii');
INSERT INTO `lang_definitions` VALUES (160814, 11107, 26, 'Grupul (ARO) pe care l-ați creat va apărea acum în ordine alfabetică în secțiunea „Grupuri și controale de acces”.');
INSERT INTO `lang_definitions` VALUES (160815, 11108, 26, 'Antetul definește contextul pentru documentul clinic în ansamblu');
INSERT INTO `lang_definitions` VALUES (160816, 11109, 26, 'Secțiunea antet va dezvălui informații specifice pacientului în majoritatea paginilor legate de dosarul medical al pacientului');
INSERT INTO `lang_definitions` VALUES (160817, 11110, 26, 'Formularul de cerere de asigurare de sănătate este adesea menționat prin numărul de formular CMS 1500 (HCFA 1500)');
INSERT INTO `lang_definitions` VALUES (160818, 11111, 26, 'Fișierul de ajutor este împărțit în următoarele secțiuni');
INSERT INTO `lang_definitions` VALUES (160819, 11112, 26, 'Fișierul de ajutor de acolo vă va ghida pe pașii suplimentari în configurarea testelor de laborator');
INSERT INTO `lang_definitions` VALUES (160820, 11113, 26, 'Pictograma de ajutor vă va permite să accesați ajutor sensibil la context pentru fiecare dintre paginile accesate');
INSERT INTO `lang_definitions` VALUES (160821, 11114, 26, 'Numele de gazdă al mașinii depozitului de audit ATNA.');
INSERT INTO `lang_definitions` VALUES (160822, 11115, 26, 'Numele de gazdă sau URI-ul serverului dvs. LDAP sau Active Directory.');
INSERT INTO `lang_definitions` VALUES (160823, 11116, 26, 'Codul de identificare trebuie să fie unic pentru ca rezultatele să se afișeze corect, puteți utiliza doar R905 ca exemplu');
INSERT INTO `lang_definitions` VALUES (160824, 11117, 26, 'Codul de identificare trebuie să fie unic, dacă trimiterea către un laborator extern trebuie introdus codul de identificare furnizat de furnizor. Vom introduce o valoare unică arbitrară - WWT01');
INSERT INTO `lang_definitions` VALUES (160825, 11118, 26, 'Codul de identificare este un cod specific furnizorului care identifică această procedură sau rezultat. Puteți vedea exemple în fișele de laborator pe care le folosesc laboratoarele');
INSERT INTO `lang_definitions` VALUES (160826, 11119, 26, 'Codul de identificare este esențial pentru afișarea și tabelarea corectă a rezultatelor');
INSERT INTO `lang_definitions` VALUES (160827, 11120, 26, 'Codul de identificare al R34392-1, un număr arbitrar, în acest caz codul de identificare precedat de R pentru a indica rezultatul și urmat de 1 pentru a indica primul din secvență, ar putea fi orice unic pe care îl alegeți');
INSERT INTO `lang_definitions` VALUES (160828, 11121, 26, 'Informațiile introduse aici sunt folosite pentru a afișa un rezumat al întâlnirii. Este folosit și în scopuri de facturare');
INSERT INTO `lang_definitions` VALUES (160829, 11122, 26, 'Informațiile introduse în acest formular vor fi folosite pentru a completa o cerere de cerere pe hârtie');
INSERT INTO `lang_definitions` VALUES (160830, 11123, 26, 'Informațiile furnizate în Formularul de întâlnire nouă și Fișa de taxe în openEMR sunt utilizate pentru a genera cererea de despăgubire pe hârtie, precum și cererile electronice.');
INSERT INTO `lang_definitions` VALUES (160831, 11124, 26, 'Eforturile inițiale au condus la crearea unor Ghiduri de implementare (IG) duplicative și conflictuale publicate de diferite organizații de standardizare.');
INSERT INTO `lang_definitions` VALUES (160832, 11125, 26, 'Ecranul inițial vă permite să selectați o metodă, oferindu-vă aceste două opțiuni.');
INSERT INTO `lang_definitions` VALUES (160833, 11126, 26, 'Fereastra inițială este pagina de căutare a facturii. În partea de sus puteți introduce o sursă (de exemplu, numărul cecului), data plății și suma cecului. Motivul sursei și datei plății este astfel încât să nu fie nevoie să le introduceți din nou și din nou pentru fiecare revendicare. Suma pe care o introduceți va fi scăzută pentru fiecare factură care i se acordă o parte din plată și, sperăm, se va termina la zero când ați terminat.');
INSERT INTO `lang_definitions` VALUES (160834, 11127, 26, 'Intrarea ar trebui să fie un fișier CSV cu 3 coloane: ID aspect, tip de cod și cod.');
INSERT INTO `lang_definitions` VALUES (160835, 11128, 26, 'Directorul de instalare trebuie creat.');
INSERT INTO `lang_definitions` VALUES (160836, 11129, 26, 'Versiunea International SNOMED instalată nu este compatibilă cu pachetul US Extension SNOMED în etape.');
INSERT INTO `lang_definitions` VALUES (160837, 11130, 26, 'Versiunea Internațională SNOMED instalată este învechită și nu este compatibilă cu fișierul US Extension SNOMED în etapă.');
INSERT INTO `lang_definitions` VALUES (160838, 11131, 26, 'Versiunea instalată și fișierele pregătite sunt aceleași.');
INSERT INTO `lang_definitions` VALUES (160839, 11132, 26, 'Versiunea instalată este o versiune mai recentă decât fișierele pregătite.');
INSERT INTO `lang_definitions` VALUES (160840, 11133, 26, 'Manualul de instrucțiuni despre cum să completați formularul CMS 1500 poate fi găsit aici');
INSERT INTO `lang_definitions` VALUES (160841, 11134, 26, 'Adresa IP a controlorilor dvs. de domeniu.');
INSERT INTO `lang_definitions` VALUES (160842, 11135, 26, 'Problemele pot fi introduse într-unul din două moduri');
INSERT INTO `lang_definitions` VALUES (160843, 11136, 26, 'Secțiunea Probleme va afișa toate problemele introduse pentru pacient și va afișa tipul problemei, titlul acesteia și o descriere');
INSERT INTO `lang_definitions` VALUES (160844, 11137, 26, 'Elementele enumerate în coloana „Activ” delimitează privilegiile acestui grup (ARO) și constituie Lista de control al accesului (ACL) a acestui grup.');
INSERT INTO `lang_definitions` VALUES (160845, 11138, 26, 'Elementele care au asteriscuri după ele sunt obligatorii');
INSERT INTO `lang_definitions` VALUES (160846, 11140, 26, 'Eticheta care apare utilizatorului pe formular');
INSERT INTO `lang_definitions` VALUES (160847, 11141, 26, 'Ultima celulă de pe linie din Encounter');
INSERT INTO `lang_definitions` VALUES (160848, 11142, 26, 'Ultima linie a acestui bloc de întâlnire va oferi totalul întâlnirii de taxe, plăți, ajustări și sold');
INSERT INTO `lang_definitions` VALUES (160849, 11143, 26, 'Ultima secțiune tratează comenzile electronice');
INSERT INTO `lang_definitions` VALUES (160850, 11144, 26, 'Data ultimei vizite va fi completată automat');
INSERT INTO `lang_definitions` VALUES (160851, 11145, 26, 'Cea mai recentă versiune este FHIR – Fast Healthcare Interoperability Resources – este un cadru standard de generație următoare creat de HL7. Acest lucru câștigă popularitate, dar nu a fost încă implementat pe scară largă');
INSERT INTO `lang_definitions` VALUES (160852, 11146, 26, 'Vechiul instrument de căutare de coduri este încă disponibil pentru codurile care nu se găsesc în acest instrument de căutare sau pentru editarea listei de coduri.');
INSERT INTO `lang_definitions` VALUES (160853, 11147, 26, 'Lungimea nu trebuie să depășească următorul număr de caractere');
INSERT INTO `lang_definitions` VALUES (160854, 11148, 26, 'Intrarea din jurnal cu următorul ID a fost ștearsă');
INSERT INTO `lang_definitions` VALUES (160855, 11150, 26, 'Tabelul de jurnal va afișa o listă atât a mesajelor, cât și a mementourilor datate, dacă există');
INSERT INTO `lang_definitions` VALUES (160856, 11151, 26, 'Codul LOINC pentru acidul uric seric este 3084-1, LOINC se referă la acesta ca urat în ser sau plasmă');
INSERT INTO `lang_definitions` VALUES (160857, 11152, 26, 'Fuziunea nu va rula decât dacă SSN și DOB pentru cele două diagrame sunt identice. Datele de naștere nu pot fi goale.');
INSERT INTO `lang_definitions` VALUES (160858, 11153, 26, 'Mesajul nu a putut fi trimis în acest moment.');
INSERT INTO `lang_definitions` VALUES (160859, 11154, 26, 'Starea mesajului va fi Nou, deoarece este un mesaj nou care este creat');
INSERT INTO `lang_definitions` VALUES (160860, 11155, 26, 'Mesajele care au fost trimise de utilizator în acea zi vor fi afișate în tabelul de mai jos');
INSERT INTO `lang_definitions` VALUES (160861, 11156, 26, 'Centrul de mesagerie consolidează convenabil opțiunile de comunicare într-un singur loc');
INSERT INTO `lang_definitions` VALUES (160862, 11157, 26, 'Centrul de mesagerie se va deschide cu fila Mesaje activată și va afișa mesajele utilizatorului conectat, așa cum este indicat de legenda Mesajele mele');
INSERT INTO `lang_definitions` VALUES (160863, 11158, 26, 'Informația minimă necesară pentru a crea o nouă întâlnire este să selectați o categorie de vizită');
INSERT INTO `lang_definitions` VALUES (160864, 11159, 26, 'Diversele opțiuni de facturare pentru formularul HCFA-1500 sunt utilizate pentru a furniza informații suplimentare pentru o cerere individuală');
INSERT INTO `lang_definitions` VALUES (160865, 11160, 26, 'Cea mai obișnuită metodă se numește 2-Factor Authorization sau 2FA');
INSERT INTO `lang_definitions` VALUES (160866, 11161, 26, 'Cea mai importantă problemă care trebuie abordată este cu cine încercați să vă conectați și ce trebuie să se întâmple la sfârșitul acestora. Majoritatea laboratoarelor majore nu se vor ocupa de practicile individuale, în astfel de cazuri un furnizor terț va acționa ca un intermediar care va fi responsabil pentru stabilirea unei conexiuni între cabinet și laborator prin interfața lor (intermediarului).');
INSERT INTO `lang_definitions` VALUES (160867, 11162, 26, 'Cel mai popular producător de chei de securitate este Yubico, care oferă versiuni USB obișnuite, precum și cele create pentru dispozitive care necesită conexiuni USB-C, cum ar fi sistemele Apple Mac OS mai noi.');
INSERT INTO `lang_definitions` VALUES (160868, 11163, 26, 'Cea mai populară soluție open-source pentru dosarul electronic de sănătate și managementul practicii medicale.');
INSERT INTO `lang_definitions` VALUES (160869, 11164, 26, 'Celula Nume conține numele, data nașterii, ID-ul pacientului și data ultimei vizite');
INSERT INTO `lang_definitions` VALUES (160870, 11165, 26, 'Blocul Narativ conține informații care sunt redate ca text care poate fi citit');
INSERT INTO `lang_definitions` VALUES (160871, 11166, 26, 'Comitetul Național de Revendicare Uniformă (NUCC) este responsabil pentru menținerea Formularului de Revendicare 1500');
INSERT INTO `lang_definitions` VALUES (160872, 11167, 26, 'Bara de navigare permite navigarea rapidă la diferite părți ale dosarului medical al pacientului');
INSERT INTO `lang_definitions` VALUES (160873, 11168, 26, 'Noua categorie va fi o subcategorie a');
INSERT INTO `lang_definitions` VALUES (160874, 11169, 26, 'Noua listă');
INSERT INTO `lang_definitions` VALUES (160875, 11170, 26, 'Noua parolă nu poate fi aceeași cu parola actuală.');
INSERT INTO `lang_definitions` VALUES (160876, 11171, 26, 'Noile câmpuri de parolă nu sunt aceleași.');
INSERT INTO `lang_definitions` VALUES (160877, 11172, 26, 'Noua parolă este aceeași cu parola actuală. Faceți clic pe Ok pentru a accepta oricum.');
INSERT INTO `lang_definitions` VALUES (160878, 11173, 26, 'Numele partenerului NewCrop eRx, numele NewCrop eRx și parola NewCrop eRx vor fi furnizate de către furnizor');
INSERT INTO `lang_definitions` VALUES (160879, 11174, 26, 'Următoarea casetă este Body Site, nu este relevantă pentru un test de sânge, dar poate fi mai utilă, de exemplu, pentru a urmări injecțiile sau pentru a comanda radiografii.');
INSERT INTO `lang_definitions` VALUES (160880, 11175, 26, 'Următoarele rânduri vor enumera toate codurile E/M și CPT care au fost facturate, câte o linie per cod');
INSERT INTO `lang_definitions` VALUES (160881, 11176, 26, 'Următorul grup este format din codurile ICD');
INSERT INTO `lang_definitions` VALUES (160882, 11177, 26, 'Următoarele trei celule sunt celulele de acțiune care vă permit să efectuați o activitate de rechemare');
INSERT INTO `lang_definitions` VALUES (160883, 11178, 26, 'Următoarele două casete care indică Codul de identificare și Codul standard sunt foarte importante');
INSERT INTO `lang_definitions` VALUES (160884, 11179, 26, 'Celula Note vă permite să adăugați o notă la o acțiune pe care o efectuați în cele 3 celule de acțiune sau doar o notă fără nicio asociere cu acțiunea');
INSERT INTO `lang_definitions` VALUES (160885, 11180, 26, 'Numărul de întâlniri viitoare de afișat în declarație.');
INSERT INTO `lang_definitions` VALUES (160886, 11181, 26, 'Numărul de fișiere în etape este incorect. Plasați doar fișierul la care doriți să instalați/actualizați.');
INSERT INTO `lang_definitions` VALUES (160887, 11182, 26, 'Numărul de fișiere în etape este incorect. Plasați doar fișierele la care doriți să instalați/actualizați.');
INSERT INTO `lang_definitions` VALUES (160888, 11183, 26, 'Birou: telefon mobil vă permite să indicați că a fost efectuat un apel telefonic');
INSERT INTO `lang_definitions` VALUES (160889, 11184, 26, 'Opțiunea Span Entire Row este utilă atunci când utilizați Text static, permițând textului să se încapă și să înglobeze întregul rând, indiferent de setările coloanei. O altă utilizare ar putea fi crearea unui rând gol ca distanțier sau adăugarea unei opțiuni suplimentare Add Bottom Border pentru a crea o întrerupere de linie. Numai Bottom Border Row este util aici.');
INSERT INTO `lang_definitions` VALUES (160890, 11185, 26, 'Opțiunile pentru Contur și Chenar fie vor înfășura un rând într-un chenar subțire, fie vor adăuga un chenar în partea de jos a unui articol.');
INSERT INTO `lang_definitions` VALUES (160891, 11186, 26, 'Ordinea în care apare Categoria, Procedura sau Rezultatul');
INSERT INTO `lang_definitions` VALUES (160892, 11187, 26, 'Celelalte 4 tipuri de tranzacții sunt tipuri simple de tranzacții - Solicitare pacient, Solicitare medic, Juridic și Facturare');
INSERT INTO `lang_definitions` VALUES (160893, 11188, 26, 'Celelalte Segmente conțin informații suplimentare într-un mod strict structurat');
INSERT INTO `lang_definitions` VALUES (160894, 11189, 26, 'Pagina va fi redirecționată către Date demografice. Puteți edita câmpul de țară și puteți face clic din nou pentru NewCrop.');
INSERT INTO `lang_definitions` VALUES (160895, 11190, 26, 'Pagina solicitată nu a fost găsită. Vă rugăm să verificați dacă ați introdus corect adresa URL.');
INSERT INTO `lang_definitions` VALUES (160896, 11191, 26, 'Părțile programului la care accesul poate fi controlat se numesc Access Control Objects (ACO).');
INSERT INTO `lang_definitions` VALUES (160897, 11192, 26, 'Parola trebuie să aibă cel puțin opt caractere și ar trebui');
INSERT INTO `lang_definitions` VALUES (160898, 11193, 26, 'Parola introdusă este nevalidă');
INSERT INTO `lang_definitions` VALUES (160899, 11194, 26, 'Istoricul ocular trecut (POH) și istoricul medical trecut (PMH) sunt negative.');
INSERT INTO `lang_definitions` VALUES (160900, 11195, 26, 'Pacientul s-a înregistrat deja în grup');
INSERT INTO `lang_definitions` VALUES (160901, 11196, 26, 'Cererea de înregistrare a pacientului a fost înregistrată.');
INSERT INTO `lang_definitions` VALUES (160902, 11197, 26, 'S-au trimis mementourile pacientului');
