INSERT INTO `lang_definitions` VALUES (160904, 11199, 26, 'Pacientul nu a fost autentificat la trimiterea acestui formular');
INSERT INTO `lang_definitions` VALUES (160905, 11200, 26, 'Pacientul va trebui să-și schimbe acreditările la prima conectare');
INSERT INTO `lang_definitions` VALUES (160906, 11201, 26, 'Drepturile Pacienților');
INSERT INTO `lang_definitions` VALUES (160907, 11202, 26, 'Plata, Ajustarea și Soldul vor fi goale, deoarece aceste rânduri reflectă doar taxele efectuate');
INSERT INTO `lang_definitions` VALUES (160908, 11203, 26, 'Plățile înregistrate nu pot depăși această dată. Acest lucru asigură că, după întocmirea raportului final, nimeni nu mai postează pentru datele anterioare.');
INSERT INTO `lang_definitions` VALUES (160909, 11204, 26, 'Titlul formularului pop-up va citi acum Introduceți detalii pentru elementul preferat personalizat individual');
INSERT INTO `lang_definitions` VALUES (160910, 11205, 26, 'Portalul are date pentru acest pacient și formular. Îl încărcați acum?');
INSERT INTO `lang_definitions` VALUES (160911, 11206, 26, 'Mesajul anterior poate fi totuși vizualizat făcând clic pe butonul Vizualizare jurnal');
INSERT INTO `lang_definitions` VALUES (160912, 11207, 26, 'Pagina Ordine de procedură listează următoarele tipuri de proceduri');
INSERT INTO `lang_definitions` VALUES (160913, 11208, 26, 'Solicitarea procedurii trebuie să fie structurată într-o manieră ierarhică și să i se atribuie un cod unic de identificare care va fi apoi utilizat pentru a urmări și a tabula rezultatul.');
INSERT INTO `lang_definitions` VALUES (160914, 11209, 26, 'Modulul Proceduri este utilizat pentru plasarea și revizuirea comenzilor');
INSERT INTO `lang_definitions` VALUES (160915, 11210, 26, 'Procesul de redirecționare a mesajului este destul de similar cu cel al creării unui mesaj nou');
INSERT INTO `lang_definitions` VALUES (160916, 11211, 26, 'Celula Progres listează toate acțiunile împreună cu eventualele note asociate, dacă există');
INSERT INTO `lang_definitions` VALUES (160917, 11212, 26, 'Biroul furnizorilor a fost anunțat. Mulțumesc.');
INSERT INTO `lang_definitions` VALUES (160918, 11213, 26, 'Cheia publică de acces pentru tokenizarea securizată a autorizării cardului de credit sau de debit. Conformitate PCI');
INSERT INTO `lang_definitions` VALUES (160919, 11214, 26, 'Codul QR conține, de asemenea, numele de utilizator și trebuie să fie capturat de utilizator pe dispozitivul său mobil folosind o aplicație de autentificare');
INSERT INTO `lang_definitions` VALUES (160920, 11215, 26, 'Eliberarea fluxului de date brute poate fi obținută de la');
INSERT INTO `lang_definitions` VALUES (160921, 11216, 26, 'Celula Recall are data retragerii și motivul retragerii');
INSERT INTO `lang_definitions` VALUES (160922, 11217, 26, 'Fila Recalls are două butoane New Recall și Recall Board');
INSERT INTO `lang_definitions` VALUES (160923, 11218, 26, 'Nivelul de recomandare este opțional');
INSERT INTO `lang_definitions` VALUES (160924, 11219, 26, 'Informațiile rămase de mai jos se aplică numai dacă postați manual sau dacă faceți corecții manuale.');
INSERT INTO `lang_definitions` VALUES (160925, 11220, 26, 'Mementoul pentru ziua curentă va avea o pictogramă de exclamare portocalie');
INSERT INTO `lang_definitions` VALUES (160926, 11221, 26, 'Mementourile care au trecut de data scadentă vor avea o pictogramă roșie cu un triunghi exclamativ');
INSERT INTO `lang_definitions` VALUES (160927, 11222, 26, 'Documentul solicitat nu este prezent în locația așteptată pe sistemul de fișiere sau nu există permisiuni suficiente pentru a-l accesa');
INSERT INTO `lang_definitions` VALUES (160928, 11223, 26, 'Documentul solicitat nu este prezent în locația așteptată pe sistemul de fișiere sau nu există permisiuni suficiente pentru a-l accesa.');
INSERT INTO `lang_definitions` VALUES (160929, 11224, 26, 'Restul poate fi lăsat necompletat dacă se preferă');
INSERT INTO `lang_definitions` VALUES (160930, 11225, 26, 'Restul casetelor legate de serviciul NewCrop eRx pot fi lăsate la valorile implicite');
INSERT INTO `lang_definitions` VALUES (160931, 11226, 26, 'Linia de rezultat va începe cu un nume ser de acid uric care va fi precedat de o bară verticală care indică faptul că nu există succesori sau copii.');
INSERT INTO `lang_definitions` VALUES (160932, 11227, 26, 'Rezultatele nu au putut fi încărcate');
INSERT INTO `lang_definitions` VALUES (160933, 11228, 26, 'Rezultatele, Rezultat Discret, vor fi fructul pe această ramură și vom crea câte un astfel de Rezultat Discret pentru fiecare dintre testele componente, Sodiu, Potasiu, Clorura și Dioxid de Carbon.');
INSERT INTO `lang_definitions` VALUES (160934, 11229, 26, 'Rândurile care conțin codurile CPT4 au mai multe casete care trebuie completate pentru a asigura facturarea corectă a revendicărilor');
INSERT INTO `lang_definitions` VALUES (160935, 11230, 26, 'Problema medicală salvată va fi acum listată pe o singură linie în pagina principală Probleme, sub Probleme medicale');
INSERT INTO `lang_definitions` VALUES (160936, 11232, 26, 'Timpul de reîmprospătare a ecranului în secunde pentru ecranul Panoul de flux al pacientului.');
INSERT INTO `lang_definitions` VALUES (160937, 11233, 26, 'Câmpul de căutare nu poate fi gol. Vă rugăm să introduceți un termen de căutare');
INSERT INTO `lang_definitions` VALUES (160938, 11234, 26, 'Rezultatele căutării sunt afișate în secțiunea „Rezultatele căutării”.');
INSERT INTO `lang_definitions` VALUES (160939, 11235, 26, 'Al doilea grafic („sursă”) va avea secțiunile demografice, istoric și asigurări eliminate. Celelalte date ale sale vor fi îmbinate în diagrama țintă.');
INSERT INTO `lang_definitions` VALUES (160940, 11236, 26, 'A doua coloană conține opțiunile care vor fi afișate atunci când se face clic pe butonul');
INSERT INTO `lang_definitions` VALUES (160941, 11237, 26, 'A doua coloană este Categorie și ar trebui să spună Top Group pentru a indica poziția sa ca element de sus în acest arbore ierarhic special pe care îl vom construi');
INSERT INTO `lang_definitions` VALUES (160942, 11238, 26, 'A doua secțiune vă permite să alegeți cui doriți să trimiteți mesajul');
INSERT INTO `lang_definitions` VALUES (160943, 11239, 26, 'A doua filă, denumită oarecum ambiguu ca Contra-Referire, este locul în care se documentează răspunsul primit la sesizarea care se face');
INSERT INTO `lang_definitions` VALUES (160944, 11240, 26, 'Secțiunea etichetată „Căutare facturi” este locul în care introduceți parametrii de căutare. Puteți căuta după numele pacientului, numărul diagramei, numărul întâlnirii sau data serviciului sau orice combinație a acestora. De asemenea, puteți selecta dacă doriți să vedeți toate facturile, facturile deschise sau numai facturile care sunt datorate (de către pacient). Faceți clic pe butonul „Căutare” pentru a efectua căutarea.');
INSERT INTO `lang_definitions` VALUES (160945, 11241, 26, 'Codul selectat va fi adăugat în caseta de text de codare, iar Descrierea de pe cod va fi adăugată în caseta de text Titlu');
INSERT INTO `lang_definitions` VALUES (160946, 11242, 26, 'Codurile selectate vor apărea apoi în secțiunea „Coduri de taxe selectate și taxe pentru întâlnirea curentă”');
INSERT INTO `lang_definitions` VALUES (160947, 11243, 26, 'Selecțiile din această secțiune vor fi folosite la taxarea acestei întâlniri');
INSERT INTO `lang_definitions` VALUES (160948, 11244, 26, 'Secvența este ordinea în care acest articol de ordine superioară va fi afișat pe pagină, 1 pentru a desemna primul grup de nivel superior');
INSERT INTO `lang_definitions` VALUES (160949, 11245, 26, 'Adresa serverului va fi de forma');
INSERT INTO `lang_definitions` VALUES (160950, 11246, 26, 'Configurația pentru testele de laborator va fi descrisă în detaliu, vor fi necesare modificări minore la acești pași pentru a configura procedurile în birou și alte tipuri de proceduri');
INSERT INTO `lang_definitions` VALUES (160951, 11247, 26, 'Contrareferirea numită oarecum ambiguu este spațiul în care răspunsul la sesizarea care se face poate fi documentat');
INSERT INTO `lang_definitions` VALUES (160952, 11248, 26, 'Coloanele Sursă și Data sunt copiate de pe prima pagină, așa că în mod normal nu va trebui să le atingeți. Puteți pune o sumă de plată în coloana Plată, o sumă de ajustare în coloana Ajustare sau ambele. De asemenea, puteți da clic pe „W” din dreapta pentru a calcula automat o valoare de ajustare care anulează restul taxei pentru elementul rând respectiv.');
INSERT INTO `lang_definitions` VALUES (160953, 11249, 26, 'Coloanele Sursă și Data sunt copiate de pe prima pagină, așa că în mod normal nu va trebui să le atingeți. Puteți pune o sumă de plată în coloana Plată, o sumă de ajustare în coloana Ajustare sau ambele. De asemenea, puteți face clic pe „W” din dreapta pentru a calcula automat o valoare de ajustare care anulează restul taxei pentru elementul rând respectiv.');
INSERT INTO `lang_definitions` VALUES (160954, 11250, 26, 'Tipul de specimen va fi Sânge, această listă derulantă poate fi, de asemenea, editată după cum este necesar');
INSERT INTO `lang_definitions` VALUES (160955, 11251, 26, 'Datele de lansare a fișierelor în etape nu sunt toate din aceeași ediție.');
INSERT INTO `lang_definitions` VALUES (160956, 11252, 26, 'Revizuirile fișierelor în etape nu sunt toate din aceeași ediție.');
INSERT INTO `lang_definitions` VALUES (160957, 11253, 26, 'Pachetul US Extension SNOMED în etape nu poate fi instalat decât după ce pachetul International SNOMED a fost instalat.');
INSERT INTO `lang_definitions` VALUES (160958, 11254, 26, 'Codul standard este opțional dacă se utilizează un laborator local, adică bazat pe practică, dar este recomandat atunci când se utilizează un laborator extern');
INSERT INTO `lang_definitions` VALUES (160959, 11255, 26, 'Codul standard va fi codul LOINC dacă este trimis către un laborator extern sau poate fi orice număr unic. Vom introduce codul LOINC pentru Fasting Glucose 1558-6');
INSERT INTO `lang_definitions` VALUES (160960, 11256, 26, 'starea a trei probleme cronice/inactive');
INSERT INTO `lang_definitions` VALUES (160961, 11257, 26, 'Rândurile următoare vor indica detaliile plăților primite, ajustările efectuate și soldul datorat');
INSERT INTO `lang_definitions` VALUES (160962, 11258, 26, 'Sufixul contului.');
INSERT INTO `lang_definitions` VALUES (160963, 11259, 26, 'Sistemul nu permite încărcarea fișierelor cu dimensiunea 0.');
INSERT INTO `lang_definitions` VALUES (160964, 11260, 26, 'Sistemul nu permite încărcarea fișierelor cu tip de conținut MIME');
INSERT INTO `lang_definitions` VALUES (160965, 11261, 26, 'Sistemul este, de asemenea, proiectat pentru a analiza mesajele HL7 primite și pentru a plasa rezultatele în diagrama pacientului corespunzătoare, în caz contrar, vă va oferi posibilitatea de a-l conecta manual la o fișă a pacientului.');
INSERT INTO `lang_definitions` VALUES (160966, 11262, 26, 'Sistemul este conceput atât pentru a plasa comenzi electronic, cât și pentru a primi rezultatele electronic');
INSERT INTO `lang_definitions` VALUES (160967, 11263, 26, 'A treia coloană va conține codul CPT');
INSERT INTO `lang_definitions` VALUES (160968, 11264, 26, 'Valoarea coloanei Tier va fi 1, indicând că este un element de nivel superior');
INSERT INTO `lang_definitions` VALUES (160969, 11265, 26, 'Valoarea coloanei Tier va fi 3, indicând că acesta este un succesor sau un copil al primei rânduri de deasupra acesteia, având o valoare de 2');
INSERT INTO `lang_definitions` VALUES (160970, 11266, 26, 'Coloana de nivel va fi 2, indicând că acesta este un succesor sau un copil pentru prima linie de deasupra acesteia, având o valoare de 1');
INSERT INTO `lang_definitions` VALUES (160971, 11267, 26, 'Coloana de nivel ar fi 1, indicând că este grupul de top');
INSERT INTO `lang_definitions` VALUES (160972, 11268, 26, 'Granularitatea de timp a calendarului și cel mai mic interval în minute pentru un interval de întâlnire.');
INSERT INTO `lang_definitions` VALUES (160973, 11269, 26, 'Titlul va fi numele noului grup (ARO) pe care urmează să-l creați.');
INSERT INTO `lang_definitions` VALUES (160974, 11270, 26, 'Grupul de sus este format din taxe pentru întâlnire - un rând per încărcare');
INSERT INTO `lang_definitions` VALUES (160975, 11271, 26, 'Partea de sus a panoului de rechemare permite setarea filtrelor pentru a afișa datele specificate');
INSERT INTO `lang_definitions` VALUES (160976, 11272, 26, 'Mecanismul tradițional de utilizare a unui login și a unei parole nu mai este considerat a fi suficient pentru a împiedica un utilizator neautorizat să obțină acces la aplicație');
INSERT INTO `lang_definitions` VALUES (160977, 11275, 26, 'Eticheta tradusă care va apărea pe formular în limba curentă');
INSERT INTO `lang_definitions` VALUES (160978, 11276, 26, 'Titlul tradus care va apărea în limba curentă');
INSERT INTO `lang_definitions` VALUES (160979, 11277, 26, 'Traducerea descrierii în limba curentă');
INSERT INTO `lang_definitions` VALUES (160980, 11278, 26, 'Tabelele de traducere sunt sincronizate.');
INSERT INTO `lang_definitions` VALUES (160981, 11279, 26, 'Tipul acestei entități');
INSERT INTO `lang_definitions` VALUES (160982, 11280, 26, 'Tipul va fi necompletat');
INSERT INTO `lang_definitions` VALUES (160983, 11281, 26, 'Tipul va asigurare sau pacient');
INSERT INTO `lang_definitions` VALUES (160984, 11282, 26, 'Tipul ar fi alergie');
INSERT INTO `lang_definitions` VALUES (160985, 11283, 26, 'Tipul ar fi Probleme dentare');
INSERT INTO `lang_definitions` VALUES (160986, 11284, 26, 'Tipul ar fi Medicament');
INSERT INTO `lang_definitions` VALUES (160987, 11285, 26, 'Tipul ar fi Problemă care indică o problemă medicală');
INSERT INTO `lang_definitions` VALUES (160988, 11286, 26, 'Tipul ar fi Chirurgie');
INSERT INTO `lang_definitions` VALUES (160989, 11287, 26, 'UB-04 (CMS 1450) este un formular de cerere utilizat de spitale, unități de îngrijire medicală, pacienți internați și alți furnizori de unități.');
INSERT INTO `lang_definitions` VALUES (160990, 11288, 26, 'Coloana Unitate ar fi goală');
INSERT INTO `lang_definitions` VALUES (160991, 11289, 26, 'Unitățile vor fi 1, deoarece fiecare cod este facturat o singură dată pentru întâlnire');
INSERT INTO `lang_definitions` VALUES (160992, 11290, 26, 'Mementourile viitoare au o pictogramă de exclamare verde');
INSERT INTO `lang_definitions` VALUES (160993, 11291, 26, 'Dispozitivele USB comunică cu computerul gazdă utilizând protocolul dispozitivului de interfață umană (HID), imitând în esență o tastatură');
INSERT INTO `lang_definitions` VALUES (160994, 11292, 26, 'Cheia USB trebuie conectată la computer și apoi înregistrată la OpenEMR');
INSERT INTO `lang_definitions` VALUES (160995, 11293, 26, 'Cheia USB preia acest nonce furnizat de aplicație după confirmarea sumei de control și generează o cheie privată utilizând un proces similar cu cel utilizat în procesul de înregistrare');
INSERT INTO `lang_definitions` VALUES (160996, 11294, 26, 'Privilegiile reale ale utilizatorului sunt determinate de accesul la părțile programului, adică (ACO) pe care le are fiecare grup (ARO).');
INSERT INTO `lang_definitions` VALUES (160997, 11295, 26, 'Câmpurile Nume de utilizator nu sunt aceleași.');
INSERT INTO `lang_definitions` VALUES (160998, 11296, 26, 'Numele de utilizator este adresa dvs. directă');
INSERT INTO `lang_definitions` VALUES (160999, 11297, 26, 'Valorile din caseta derulantă pot fi editate urmând pașii menționați în fișierul de ajutor Proceduri > Furnizori');
INSERT INTO `lang_definitions` VALUES (161000, 11298, 26, 'Valorile enumerate aici vor apărea în casetele derulante care vor fi utilizate pentru procesarea comenzilor');
INSERT INTO `lang_definitions` VALUES (161001, 11299, 26, 'Codul specific furnizorului care identifică această procedură sau rezultat');
INSERT INTO `lang_definitions` VALUES (161002, 11300, 26, 'Codul specific furnizorului care identifică această procedură sau rezultat. Dacă niciun furnizor nu introduce niciun număr unic arbitrar, de preferință un număr de 5 cifre cu zero, de ex. 00211');
INSERT INTO `lang_definitions` VALUES (161003, 11301, 26, 'Primul pas ar fi instalarea codurilor ICD. Accesați Administration > Other > External Data Loads. Selectați seturile de coduri pe care doriți să le instalați și faceți clic pe Instalare');
INSERT INTO `lang_definitions` VALUES (161004, 11302, 26, 'Ultima linie a acestui raport va oferi totalul general al taxelor, plăților, ajustărilor și soldului');
INSERT INTO `lang_definitions` VALUES (161005, 11303, 26, 'Weno Exchange este bine integrat cu openEMR și nu se bazează pe abonament');
INSERT INTO `lang_definitions` VALUES (161006, 11304, 26, 'Fișierele X12, precum și rapoartele HTML rezultate sunt arhivate în subdirectorul „era” al directorului principal de instalare OpenEMR. Veți dori să vă referiți la aceste arhive din când în când. URL-ul este');
INSERT INTO `lang_definitions` VALUES (161007, 11305, 26, 'Fișierele X12, precum și rapoartele HTML rezultate sunt arhivate în subdirectorul „era” al directorului principal de instalare OpenEMR. Veți dori să vă referiți la aceste arhive din când în când.');
INSERT INTO `lang_definitions` VALUES (161008, 11306, 26, 'Fișierul zip va conține următoarele elemente');
INSERT INTO `lang_definitions` VALUES (161009, 11307, 26, 'Temă');
INSERT INTO `lang_definitions` VALUES (161010, 11308, 26, 'Tema aspectului filelor (trebuie să vă deconectați și apoi să vă conectați pentru a vedea această nouă setare).');
INSERT INTO `lang_definitions` VALUES (161011, 11309, 26, 'Tema aspectului filelor (trebuie să vă deconectați și apoi să vă conectați pentru a vedea această nouă setare). Rețineți că acest lucru se aplică numai dacă utilizați tema generală Light sau Manila de mai jos.');
INSERT INTO `lang_definitions` VALUES (161012, 11310, 26, 'Apoi transmiteți numele ca valoare elementului');
INSERT INTO `lang_definitions` VALUES (161013, 11311, 26, 'Apoi apăsați butonul intermitent de pe cheie în termen de 1 minut pentru a finaliza înregistrarea');
INSERT INTO `lang_definitions` VALUES (161014, 11312, 26, 'Apoi apăsați butonul intermitent de pe cheie în decurs de 1 minut.');
INSERT INTO `lang_definitions` VALUES (161015, 11313, 26, 'Apoi eliberarea de date brute poate fi obținută de la');
INSERT INTO `lang_definitions` VALUES (161016, 11314, 26, 'Injecții terapeutice');
INSERT INTO `lang_definitions` VALUES (161017, 11315, 26, 'Terapie');
INSERT INTO `lang_definitions` VALUES (161018, 11316, 26, 'Grup de terapie');
INSERT INTO `lang_definitions` VALUES (161019, 11317, 26, 'Grup de terapie');
INSERT INTO `lang_definitions` VALUES (161020, 11318, 26, 'Întâlnire de grup de terapie');
INSERT INTO `lang_definitions` VALUES (161021, 11319, 26, 'Găsire grup de terapie');
INSERT INTO `lang_definitions` VALUES (161022, 11320, 26, 'Sunt');
INSERT INTO `lang_definitions` VALUES (161023, 11321, 26, 'Există 10 setări care sunt legate de procedurile incluse în versiunea standard a openEMR');
INSERT INTO `lang_definitions` VALUES (161024, 11322, 26, 'Există 3 formulare în categoria de bază - Date demografice, Informații despre utilizator specifice unității și istoric și toate cele 5 formulare din Tranzacții care pot fi editate');
INSERT INTO `lang_definitions` VALUES (161025, 11323, 26, 'Momentan nu există rețete');
INSERT INTO `lang_definitions` VALUES (161026, 11324, 26, 'Există erori cu trimiterea dvs. Acestea sunt prezentate mai jos.');
INSERT INTO `lang_definitions` VALUES (161027, 11325, 26, 'Există patru stări de mesaj - Nou, Redirecționat, Citit și Terminat');
INSERT INTO `lang_definitions` VALUES (161028, 11326, 26, 'Există mai multe opțiuni cu privire la portalurile pentru pacienți și informații despre cum să configurați portalul pentru pacienți sunt disponibile aici');
INSERT INTO `lang_definitions` VALUES (161029, 11327, 26, 'Există mai mulți pacienți cu autentificare pe portal');
INSERT INTO `lang_definitions` VALUES (161030, 11328, 26, 'Există nouă șabloane C-CDA care sunt definite în prezent');
INSERT INTO `lang_definitions` VALUES (161031, 11329, 26, 'Nu există diagrame verificate.');
INSERT INTO `lang_definitions` VALUES (161032, 11330, 26, 'Nu există clienți înregistrați în sistem');
INSERT INTO `lang_definitions` VALUES (161033, 11331, 26, 'Nu există dezvăluiri înregistrate pentru acest pacient.');
INSERT INTO `lang_definitions` VALUES (161034, 11332, 26, 'Nu există prescripții pentru ochelari sau lentile de contact în dosar pentru acest pacient');
INSERT INTO `lang_definitions` VALUES (161035, 11333, 26, 'Nu există mesaje în dosar pentru acest pacient.');
INSERT INTO `lang_definitions` VALUES (161036, 11334, 26, 'Nu există trimiteri noi');
INSERT INTO `lang_definitions` VALUES (161037, 11335, 26, 'Nu există note în dosar pentru acest pacient.');
INSERT INTO `lang_definitions` VALUES (161038, 11336, 26, 'Nu au fost găsite înregistrări.');
INSERT INTO `lang_definitions` VALUES (161039, 11337, 26, 'Nu există tranzacții înregistrate pentru acest pacient.');
INSERT INTO `lang_definitions` VALUES (161040, 11338, 26, 'Există mai multe versiuni de HL7, versiunile 2.x și versiunea 3');
INSERT INTO `lang_definitions` VALUES (161041, 11339, 26, 'Există mai multe moduri de a personaliza foaia de taxe. Depinde de cât de confortabil vă simțiți când adăugați informații în baza de date în sine');
INSERT INTO `lang_definitions` VALUES (161042, 11340, 26, 'Există trei acțiuni care sunt posibile - Creați un nou memento datat, Redirecționați și Setați ca finalizat');
INSERT INTO `lang_definitions` VALUES (161043, 11341, 26, 'Există trei acțiuni care pot fi efectuate aici - editați un grup existent (ARO), adăugați un grup nou (ARO) sau ștergeți un grup existent (ARO).');
INSERT INTO `lang_definitions` VALUES (161044, 11343, 26, 'Există trei tipuri principale de rapoarte care pot fi create, două se referă la continuitatea îngrijirii continue - Fișa de continuitate a îngrijirii (CCR) și Documentul de continuitate a îngrijirii (CCD) și al treilea - Raportul pacientului care creează un document care conține diferite secțiuni ale fișa medicală a pacientului, inclusiv datele demografice, probleme medicale, proceduri și întâlniri. De asemenea, are capacitatea de a include toate sau oricare dintre documentele scanate în fișa pacientului');
INSERT INTO `lang_definitions` VALUES (161045, 11344, 26, 'Există trei opțiuni disponibile atunci când creați un document de continuitate a îngrijirii (CCD)');
INSERT INTO `lang_definitions` VALUES (161046, 11345, 26, 'Există trei opțiuni disponibile atunci când creați o înregistrare a continuității îngrijirii (CCR)');
