INSERT INTO `lang_definitions` VALUES (161213, 11525, 26, 'Această pagină vă permite să examinați fiecare dintre încărcările de date externe acceptate pe care le puteți instala și actualiza. Fiecare secțiune de mai jos poate fi extinsă făcând clic pe antetul secțiunii pentru a revizui starea bazei de date de interes.');
