INSERT INTO `lang_definitions` VALUES (161216, 11528, 26, 'Această pagină va include în linie pagina de autentificare, astfel încât să nu fie nevoie să facem clic pe reconectare de fiecare dată.');
INSERT INTO `lang_definitions` VALUES (161217, 11529, 26, 'Acest pacient are deja programată o întâlnire');
