INSERT INTO `lang_definitions` VALUES (161225, 11542, 26, 'Această secțiune vă permite să creați și să eliminați grupuri și să modificați sau să acordați privilegii de acces grupurilor existente. Bifați caseta de selectare pentru a afișa secțiunea');
