INSERT INTO `lang_definitions` VALUES (161235, 11552, 26, 'Acest pas va genera un fișier pe care trebuie să îl salvați pentru utilizare ulterioară.');
INSERT INTO `lang_definitions` VALUES (161236, 11553, 26, 'Acest pas va genera un fișier pe care trebuie să îl salvați pentru utilizare ulterioară. Fișierul nu poate fi generat din nou. Vrei sa continui?');
INSERT INTO `lang_definitions` VALUES (161237, 11556, 26, 'Acest utilizator nu este membru al niciunui grup');
