INSERT INTO `lang_definitions` VALUES (161274, 11597, 26, 'Aceasta va îmbina două fișe ale pacientului într-una singură. Este util atunci când un pacient a fost duplicat din greșeală. Dacă acest lucru se întâmplă des, remediați procedurile de la birou - nu executați acest lucru în mod obișnuit!');
