INSERT INTO `lang_definitions` VALUES (161355, 11681, 26, 'Pentru a permite ca fiecare linie de procedură să aibă un furnizor separat, trebuie să bifați caseta de selectare „Furnizor de asistență în elementul rând din foaia de taxe” din Administrare > Global > Facturare. Dacă nu este bifat, furnizorul de redare din această secțiune va fi utilizat pentru toate revendicările');
INSERT INTO `lang_definitions` VALUES (161356, 11682, 26, 'Pentru a autoriza portalul pacientului pentru pacient, accesați Tabloul de bord > Date demografice > Editați > Opțiuni și selectați Da în caseta derulantă Permite portalul pacientului și Salvați');
INSERT INTO `lang_definitions` VALUES (161357, 11683, 26, 'Pentru a deschide automat formularul specificat. Unele echipe sportive folosesc football_injury_audit aici.');
