INSERT INTO `lang_definitions` VALUES (161370, 11697, 26, 'Pentru a deconecta, faceți clic pe elementul de deconectat și acesta va fi deconectat și nu va mai fi evidențiat');
INSERT INTO `lang_definitions` VALUES (161371, 11698, 26, 'Pentru Dems');
