INSERT INTO `lang_definitions` VALUES (161373, 11700, 26, 'Pentru a dezactiva certificatele SSL pe partea clientului, comentați rândurile de mai sus în fișierul de configurare Apache și setați');
INSERT INTO `lang_definitions` VALUES (161374, 11701, 26, 'Pentru a dezactiva certificatele SSL pe partea clientului, comentați rândurile de mai sus din fișierul de configurare Apache și dezactivați setarea globală „Activare SSL client” în OpenEMR și reporniți serverul Apache.');
INSERT INTO `lang_definitions` VALUES (161375, 11702, 26, 'Pentru a dezactiva HTTPS, comentați rândurile de mai sus în fișierul de configurare Apache și reporniți serverul Apache.');
INSERT INTO `lang_definitions` VALUES (161376, 11703, 26, 'Pentru a afișa suma coplata trebuie să fi fost introdusă în asigurarea pacientului sub Editare > Date demografice');
INSERT INTO `lang_definitions` VALUES (161377, 11704, 26, 'Pentru a face acest lucru, faceți clic pe semnul negru + din capătul îndepărtat din linia de comandă a acidului uric ser pentru a afișa fereastra pop-up Introduceți detalii');
INSERT INTO `lang_definitions` VALUES (161378, 11705, 26, 'Pentru a edita un grup existent (ARO) faceți clic pe pictograma de lângă grupul dorit. Aceasta va afișa fereastra de editare.');
INSERT INTO `lang_definitions` VALUES (161379, 11706, 26, 'Pentru a activa orice altă formă de conectivitate va fi necesară scrierea unui cod nou');
INSERT INTO `lang_definitions` VALUES (161380, 11707, 26, 'Pentru a activa certificatele ssl la nivelul clientului');
INSERT INTO `lang_definitions` VALUES (161381, 11708, 26, 'Pentru a activa autentificarea certificatelor SSL pe partea clientului, HTTPS ar trebui să fie activat.');
INSERT INTO `lang_definitions` VALUES (161382, 11709, 26, 'Pentru a activa ajutorul - Accesați Administrare > Globale > Funcții > Activare modal de ajutor');
INSERT INTO `lang_definitions` VALUES (161383, 11710, 26, 'Pentru a activa ajutorul - Accesați Numele de utilizator din stânga sus > Setări > Funcții > Activare modal de ajutor');
INSERT INTO `lang_definitions` VALUES (161384, 11711, 26, 'Pentru a activa ajutorul - Accesați numele de utilizator din dreapta sus > Setări > Funcții > Activare modal ajutor');
INSERT INTO `lang_definitions` VALUES (161385, 11712, 26, 'Pentru a activa numai HTTPS, efectuați modificările de mai sus și reporniți serverul Apache. Dacă doriți să configurați și certificate de partea clientului, vă rugăm să le configurați în secțiunea următoare.');
INSERT INTO `lang_definitions` VALUES (161386, 11713, 26, 'Pentru a activa Portalul pacientului, accesați Administrare > Portal > Activați Portalul Pacienților Versiunea 2 la fața locului, Activați Portalul Pacienților în afara sediului sau Activați Portalul CMS');
INSERT INTO `lang_definitions` VALUES (161387, 11715, 26, 'Pentru a Enctr');
INSERT INTO `lang_definitions` VALUES (161388, 11716, 26, 'Pentru a filtra după sex');
INSERT INTO `lang_definitions` VALUES (161389, 11717, 26, 'Pentru a îndeplini cerințele de utilizare semnificativă și a ajuta la urmărirea utilizării acesteia, puteți bifa caseta de selectare Rezumatul îngrijirii trimis și caseta de selectare Rezumatul îngrijirii trimis electronic, dacă este cazul');
INSERT INTO `lang_definitions` VALUES (161390, 11718, 26, 'Pentru a șterge complet apăsați „Salvați”');
INSERT INTO `lang_definitions` VALUES (161391, 11719, 26, 'Pentru a începe, alegeți unul dintre cele două butoane radio. „Căutare facturi” sau „Încărcare ERA”');
INSERT INTO `lang_definitions` VALUES (161392, 11720, 26, 'Pentru a ajuta la explorarea diferitelor componente ale paginii Raport, mai ales dacă doriți să o utilizați ca manual de instrucțiuni, vă recomandăm să reduceți dimensiunea browserului pentru a acoperi jumătate din fereastra de vizualizare, redimensionați fereastra pop-up de ajutor făcând clic și trăgând partea de jos. colțul din dreapta al ferestrei pop-up. Deschideți o altă instanță a browserului și redimensionați-o pentru a acoperi cealaltă jumătate a ferestrei de vizualizare, conectați-vă la openEMR');
INSERT INTO `lang_definitions` VALUES (161393, 11721, 26, 'Pentru a vă ajuta să vă familiarizați cu diferitele componente ale paginii Dashboard, vă recomandăm să reduceți dimensiunea browserului pentru a acoperi jumătate din fereastra de vizualizare, să redimensionați fereastra pop-up de ajutor făcând clic și trăgând colțul din dreapta jos al ferestrei pop-up. Deschideți o altă instanță a browserului și redimensionați-o pentru a acoperi cealaltă jumătate a ferestrei de vizualizare, conectați-vă la openEMR');
INSERT INTO `lang_definitions` VALUES (161394, 11722, 26, 'Pentru a simplifica implementările, șabloanele utilizate în mod obișnuit au fost armonizate din ghidurile de implementare CDA existente și consolidate într-un singur ghid de implementare – Ghidul de implementare C-CDA (IG) (07/2012)');
INSERT INTO `lang_definitions` VALUES (161395, 11723, 26, 'Spre Istorie');
INSERT INTO `lang_definitions` VALUES (161396, 11724, 26, 'Pentru a include documentele scanate care fac parte din dosarul pacientului, selectați înregistrările dorite bifând casetele de selectare relevante');
INSERT INTO `lang_definitions` VALUES (161397, 11725, 26, 'La Probleme');
INSERT INTO `lang_definitions` VALUES (161398, 11726, 26, 'Pentru a lega problemele la o întâlnire, selectați mai întâi problema, aceasta va fi evidențiată cu galben, apoi faceți clic pe una sau mai multe întâlniri pentru a le lega, întâlnirile selectate vor fi evidențiate în violet');
INSERT INTO `lang_definitions` VALUES (161399, 11727, 26, 'Pentru a lega această întâlnire/consultare la o problemă existentă, faceți clic pe');
INSERT INTO `lang_definitions` VALUES (161400, 11728, 26, 'Pentru a lega această întâlnire/consultare la o problemă existentă, faceți clic pe problema dorită de mai sus pentru a o evidenția și apoi faceți clic pe [Salvare]. Țineți apăsat butonul [Ctrl] pentru a selecta mai multe probleme.');
INSERT INTO `lang_definitions` VALUES (161401, 11729, 26, 'Pentru a lega această întâlnire/consultare la o problemă existentă, faceți clic pe problema dorită de mai sus pentru a o evidenția, apoi faceți clic pe Salvare');
INSERT INTO `lang_definitions` VALUES (161402, 11730, 26, 'pentru a vă autentifica din nou');
INSERT INTO `lang_definitions` VALUES (161403, 11731, 26, 'Pentru a muta grupurile dintr-o coloană în alta, selectați unul sau mai multe articole din coloana din care trebuie să le mutați și apăsați butonul corespunzător cu chevronele duble.');
INSERT INTO `lang_definitions` VALUES (161404, 11732, 26, 'Pentru a continua, aveți nevoie de o cheie de securitate USB, o conexiune web securizată HTTPS și un browser care acceptă U2F');
INSERT INTO `lang_definitions` VALUES (161405, 11733, 26, 'Pentru a recapitula, a fost creat un Grup numit Serum Chemistry (Nivelul 1), un descendent direct sau un copil numit Serum Uric Acid (Nivelul 2) a fost creat sub acesta ca un Ordin de Procedură care a avut un singur descendent direct sau copil numit și Serum Uric Acid ( Nivelul 3) ca rezultat discret care va păstra valoarea rezultatului');
INSERT INTO `lang_definitions` VALUES (161406, 11734, 26, 'Pentru a primi notificări de eroare de la serviciul de mesagerie directă, trebuie introdusă o adresă de e-mail de notificare validă pentru utilizatorul numit în Administrare > Globale > Conectori > utilizator de notificare phiMail');
INSERT INTO `lang_definitions` VALUES (161407, 11735, 26, 'Pentru a înregistra dezvăluirile, vă rugăm să faceți clic');
INSERT INTO `lang_definitions` VALUES (161408, 11736, 26, 'Pentru a vă înregistra aveți nevoie de o aplicație de autentificare instalată pe smartphone');
INSERT INTO `lang_definitions` VALUES (161409, 11738, 26, 'Pentru a retrimite, ștergeți fișierul din Communications și încercați din nou.');
INSERT INTO `lang_definitions` VALUES (161410, 11739, 26, 'Pentru a retrimite, ștergeți fișierul din Communications, reîncărcați această pagină și încercați din nou.');
INSERT INTO `lang_definitions` VALUES (161411, 11740, 26, 'Pentru a dezvălui filtrele, faceți clic pe pictograma ochiului');
INSERT INTO `lang_definitions` VALUES (161412, 11741, 26, 'a alerga');
INSERT INTO `lang_definitions` VALUES (161413, 11743, 26, 'Pentru a vedea toate ACO-urile disponibile, faceți clic pe pictograma ochiului.');
INSERT INTO `lang_definitions` VALUES (161414, 11744, 26, 'Pentru a selecta un anumit cod, identificați-l în rezultatele returnate și faceți clic pe el pentru a selecta');
INSERT INTO `lang_definitions` VALUES (161415, 11745, 26, 'Pentru a selecta mai multe grupuri, țineți apăsată tasta „Shift” sau „Ctrl” în timp ce faceți clic.');
INSERT INTO `lang_definitions` VALUES (161416, 11747, 26, 'Pentru a configura accesul https cu autentificarea cu certificat de client, procedați în felul următor');
