INSERT INTO `lang_definitions` VALUES (161420, 11751, 26, 'la această vizită?');
INSERT INTO `lang_definitions` VALUES (161421, 11752, 26, 'Pentru a încărca documentul CCR al pacientului deja existent, utilizați Ecranul Rezumat al pacientului->Documente. Pentru documentul CCR al unui pacient nou, utilizați ecranul Diverse->Documente noi');
INSERT INTO `lang_definitions` VALUES (161422, 11754, 26, 'Pentru a utiliza pagina de ajutor ca manual de instrucțiuni, se recomandă să reduceți dimensiunea browserului pentru a acoperi jumătate din fereastra de vizualizare, să redimensionați fereastra pop-up de ajutor făcând clic și trăgând colțul din dreapta jos al ferestrei pop-up. Deschideți o altă instanță a browserului și redimensionați-o pentru a acoperi cealaltă jumătate a ferestrei de vizualizare, conectați-vă la openEMR');
INSERT INTO `lang_definitions` VALUES (161423, 11755, 26, 'Pentru a utiliza acest fișier de ajutor ca manual de instrucțiuni, cel mai bine este să redimensionați browserul pentru a ocupa jumătate de ecran, deschideți o altă instanță a browserului pentru a umple cealaltă jumătate a ecranului, conectați-vă la openEMR și deschideți fișierul de ajutor în acest browser și redimensionați făcând clic și trăgând colțul din dreapta jos, astfel încât să ocupe întreaga jumătate de ecran');
INSERT INTO `lang_definitions` VALUES (161424, 11756, 26, 'Pentru a utiliza acest fișier de ajutor ca manual de instrucțiuni, se recomandă să reduceți dimensiunea browserului pentru a acoperi jumătate din fereastra de vizualizare, să redimensionați fereastra pop-up de ajutor făcând clic și trăgând colțul din dreapta jos al ferestrei pop-up. Deschideți o altă instanță a browserului și redimensionați-o pentru a acoperi cealaltă jumătate a ferestrei de vizualizare, conectați-vă la openEMR');
