INSERT INTO `lang_definitions` VALUES (161991, 12379, 26, 'Folosirea unui pom fructifer ca o analogie mai usor de vizualizat va explica mai bine conceptul acestei ierarhii, trunchiul pomului este Grupul (Chimia serului), ramura fructificatoare este ordinea reala, Ordinea procedurii (Acid uric seric) si fructul este rezultatul, Rezultat Discret, numit și (Acid Uric Seric) care va deține valoarea rezultatului returnat. Așa cum fructele nu sunt purtate pe trunchiul principal, nu trebuie să plasați un Rezultat Discret ca descendent direct sau copil al unui Grup de Sus. În mod similar, ramura fructiferă (Ordinul de procedură) nu poate fi plasată ca descendent direct sau copil al unui fruct (Rezultat discret)');
INSERT INTO `lang_definitions` VALUES (161992, 12380, 26, 'Utilizarea tehnologiei pentru a îmbunătăți productivitatea');
INSERT INTO `lang_definitions` VALUES (161993, 12381, 26, 'Folosind detaliile introduse în sistem, openEMR va genera mesaje valide HL7 v2.3 în 3 formate, un fișier text care este descărcat automat în folderul de descărcări al browserului dvs., un mesaj HL7 care este scris într-un folder sau director de pe serverul care rulează openEMR sau utilizați SFTP - Secure File Transfer Protocol, care este un protocol de rețea care oferă acces la fișiere, transfer de fișiere și gestionare a fișierelor printr-o conexiune sigură și transferați acest mesaj într-un laborator');
