INSERT INTO `lang_definitions` VALUES (162225, 12635, 26, 'Am întâmpinat câteva probleme la conectarea dumneavoastră EHR la serverele MedEx');
INSERT INTO `lang_definitions` VALUES (162226, 12636, 26, 'Am primit o solicitare de resetare a acreditărilor. Linkul pentru a vă reseta acreditările este mai jos.');
INSERT INTO `lang_definitions` VALUES (162227, 12639, 26, 'Nu am putut crea un cont.');
INSERT INTO `lang_definitions` VALUES (162228, 12640, 26, 'Vom baza panoul de electroliți de pe trunchiul sau grupul principal (chimia serului)');
INSERT INTO `lang_definitions` VALUES (162229, 12641, 26, 'Vom crea o comandă pentru trei teste de glucoză din sânge, TSH și vitamina D și o vom grupa într-un grup personalizat numit Well Woman Tests și vom crea un loc pentru a introduce manual rezultatele returnate.');
INSERT INTO `lang_definitions` VALUES (162230, 12642, 26, 'Vom trece prin procesul de stabilire a comenzii pentru un singur test de sânge - Acid Uric Seric');
INSERT INTO `lang_definitions` VALUES (162231, 12643, 26, 'Vom crea acum comanda sau ordinea de procedură, numită Panoul de electroliți, care poate fi vizualizată ca ramură fructiferă în pomul nostru fructifer ipotetic.');
INSERT INTO `lang_definitions` VALUES (162232, 12644, 26, 'Vom stabili comanda pentru panoul de electroliți care constă din ser de sodiu, potasiu, clorură și dioxid de carbon');
INSERT INTO `lang_definitions` VALUES (162233, 12645, 26, 'Vom începe cu cea mai de bază unitate a modulului Comenzi de procedură, pentru a configura o singură comandă de testare de laborator și abilitatea de a înregistra manual rezultatul returnat.');
INSERT INTO `lang_definitions` VALUES (162234, 12646, 26, 'Vom folosi un rezultat discret pentru fiecare test pentru a păstra valorile rezultatelor returnate');
INSERT INTO `lang_definitions` VALUES (162235, 12647, 26, 'Vom folosi această ramură pentru a ține toate cele 9 panouri, aici vom crea doar comanda reprezentând un singur panou, Panoul Electroliți');
