INSERT INTO `lang_definitions` VALUES (162282, 12699, 26, 'Atunci când este creat un utilizator nou, controlul accesului este acordat de administrator sau de către un utilizator cu privilegii similare selectând la ce grupuri (ARO) poate aparține un utilizator.');
INSERT INTO `lang_definitions` VALUES (162283, 12700, 26, 'Când și cât de des?');
INSERT INTO `lang_definitions` VALUES (162284, 12701, 26, 'Când este bifat, Datele demografice se vor deschide într-o fereastră nouă din panoul de flux de pacienți.');
INSERT INTO `lang_definitions` VALUES (162285, 12702, 26, 'Când este bifat, ultimul personal care a actualizat panoul va apărea în panoul pentru fluxul de pacienți.');
INSERT INTO `lang_definitions` VALUES (162286, 12703, 26, 'Când sunt bifate, mesajele sunt procesate pentru pacienții cu Opțiunea demografică a pacientului: „Notificare Hipaa primită” setat la „Nealocat” sau „Da”. Când este debifată, această alegere trebuie să = „DA” pentru a procesa memento-ul pacientului. Pentru pacienții cu Choice =\"Nu\", mementourile vor trebui procesate manual.');
INSERT INTO `lang_definitions` VALUES (162287, 12704, 26, 'Când este bifat, numărul de întâlnire cu pacientul va apărea în panoul de flux al pacientului.');
INSERT INTO `lang_definitions` VALUES (162288, 12705, 26, 'Când este bifat, ID-ul pacientului va apărea pe panoul de flux al pacientului.');
INSERT INTO `lang_definitions` VALUES (162289, 12706, 26, 'Când este bifat, motivul vizitei va apărea în panoul de flux al pacientului.');
INSERT INTO `lang_definitions` VALUES (162290, 12707, 26, 'Când aveți de-a face cu informații de sănătate protejate (PHI) și informații de identificare personală (PII), este important să permiteți accesul la date numai utilizatorilor autorizați.');
INSERT INTO `lang_definitions` VALUES (162291, 12708, 26, 'Când ați terminat, faceți clic pe Trimitere (mai jos) pentru a aplica opțiunile dvs.');
INSERT INTO `lang_definitions` VALUES (162292, 12709, 26, 'Când o astfel de comandă este plasată, rezultatele returnate vor conține valorile pentru toate componentele CBC, Comprehensive Metabolic Panel și TSH');
INSERT INTO `lang_definitions` VALUES (162293, 12710, 26, 'Când raportul generat este afișat într-o filă separată, există o opțiune care vă permite să vizualizați o versiune imprimabilă care poate fi tipărită');
INSERT INTO `lang_definitions` VALUES (162294, 12711, 26, 'Când cheia este înregistrată pentru prima dată, generează un număr aleatoriu, care se numește nonce');
INSERT INTO `lang_definitions` VALUES (162295, 12712, 26, 'Când utilizatorul vizitează inițial această pagină, următorul mesaj va fi vizibil');
INSERT INTO `lang_definitions` VALUES (162296, 12715, 26, 'Când plasați o comandă, puteți căuta Well Woman Tests sub favorite și le selectați pentru a comanda automat glicemia, TSH și vitamina D cu un singur clic');
