INSERT INTO `lang_definitions` VALUES (162303, 12722, 26, 'Deși este intuitiv să ne gândim la acest modul ca fiind locul unde testele de laborator și studiile imagistice pot fi comandate și revizuite, acest modul poate fi folosit și pentru a urmări alte proceduri efectuate la birou');
