INSERT INTO `lang_definitions` VALUES (162802, 5, 27, 'Một Quy tắc Quyết định Lâm sàng là thông tin đặc trưng của bệnh nhân được lọc và trình bày tại những thời điểm thích hợp để nâng cao sức khỏe và sự chăm sóc sức khỏe ');
