INSERT INTO `lang_definitions` VALUES (162804, 7, 27, 'Một tài liệu lâm sàng được đính kèm.');
INSERT INTO `lang_definitions` VALUES (162805, 8, 27, 'Đã chọn một mã cho kiểu này. Hãy xóa trường này trước nếu bạn cần thay thế nó.');
INSERT INTO `lang_definitions` VALUES (162806, 9, 27, 'Một thông điệp nhắc nhở theo ngày có thể được chuyển tiếp bằng cách bấm vào nút Chuyển tiếp hoặc được bỏ khỏi danh sách nhắc nhở theo ngày bằng cách bấm vào nút Đánh dấu Đã Hoàn thành');
INSERT INTO `lang_definitions` VALUES (162807, 10, 27, 'Cần phải mua một khóa bảo mật dành riêng');
INSERT INTO `lang_definitions` VALUES (162808, 11, 27, 'Mã mặc định là tùy chọn do có thể nhập mã cần thiết vào thời điểm đặt hàng thực tế ');
INSERT INTO `lang_definitions` VALUES (162809, 12, 27, 'Có thể tìm ở đây hướng dẫn chi tiết cách kích hoạt và thiết lập Quy tắc Quyết định Lâm sàng');
INSERT INTO `lang_definitions` VALUES (162810, 13, 27, 'Phải có nhà phân phối');
INSERT INTO `lang_definitions` VALUES (162811, 14, 27, 'Có thể chỉ định một ngày cuối hoặc chọn khoảng thời gian cụ thể để hiện nhắc nhở theo ngày ');
INSERT INTO `lang_definitions` VALUES (162812, 15, 27, 'Một vài từ để chỉ ra lý do lần đến khám');
INSERT INTO `lang_definitions` VALUES (162813, 16, 27, 'Có thể lên kế hoạch cho một cuộc hẹn tiếp theo ngay tại bảng tính phí.');
INSERT INTO `lang_definitions` VALUES (162814, 17, 27, 'Phải thêm vào lần đến khám này một biểu mẫu đến khám GCAC.');
INSERT INTO `lang_definitions` VALUES (162815, 19, 27, 'Một ứng dụng lớn như OpenEMR được nhiều người dùng với những vai trò khác nhau và nhiều mức độ trách nhiệm. Cần thiết phải gán quyền truy nhập vào các thành phần khác nhau của chương trình cho người dùng tùy theo sự cần biết. Để làm điều đó, Danh sách Điều khiển Truy nhập (ACL) được dùng.');
INSERT INTO `lang_definitions` VALUES (162816, 20, 27, 'Phải có số lô sản xuất');
INSERT INTO `lang_definitions` VALUES (162817, 21, 27, 'Phải có số lô sản xuất!');
