INSERT INTO `lang_definitions` VALUES (162820, 24, 27, 'Một tính năng mới giúp nhóm các xét nghiệm thường được chỉ định để chúng được chỉ định cùng nhau');
INSERT INTO `lang_definitions` VALUES (162821, 25, 27, 'Như thế có thể gửi một thông điệp mới đến một hay nhiều người dùng và/hoặc về một hay nhiều bệnh nhân ');
