INSERT INTO `lang_definitions` VALUES (163312, 626, 27, 'Ngoài ra, bạn có thể bỏ chọn tất cả và chọn chỉ những mục bạn muốn có trong báo cáo');
INSERT INTO `lang_definitions` VALUES (163313, 627, 27, 'Ngoài ra, bạn có thể chọn tải lên một tập tin chuyển tiền điện tử (X12 835) mà bạn nhận được từ người trả cho bạn hoặc ngân hàng. Đầu tiên bạn chọn \'tải lên ERE\' trong phân đoạn \'Chọn Phương thức\' sơ khởi. Việc đó đưa ra Phân doạn \'Tải lên ERA\'. ');
INSERT INTO `lang_definitions` VALUES (163314, 628, 27, 'Ngoài ra, bạn có thể sử dụng trang tìm kiếm để tải lên một tập tin chuyển tiền điện tử (X12 835) mà bạn đã thu được từ người trả tiền hoặc ngân hàng của bạn. Bạn có thể làm điều này bằng cách nhấp vào nút Browse và chọn tập tin để tải lên, và sau đó nhấp vào Tìm kiếm để thực hiện việc tải lên và hiển thị hóa đơn tương ứng. Trong trường hợp này các thông số khác được đề cập ở trên không áp dụng và sẽ bị bỏ qua. Việc tải lên lưu các tập tin nhưng không xử lý nội dung của nó -- việc xử lý được thực hiện một cách riêng biệt như mô tả dưới đây.');
INSERT INTO `lang_definitions` VALUES (163315, 629, 27, 'Mặc dù ban đầu HCFA-1500 được dùng để gửi đi các yêu cầu Medicare, cuối cùng nó được tất cả hãng bảo hiểm thương mại/tư nhận chấp nhận để tạo điều kiện thuận lợi cho việc chuẩn hóa quy trình yêu cầu');
