INSERT INTO `lang_definitions` VALUES (163354, 674, 27, 'Một thư điện tử với thông tin xác thực tài khoản mới của bạn sẽ được gửi đến địa chỉ đã cung cấp trước đây. Bạn có thễ tiếp tục xem xét hay sửa chữa bất kỳ thông tin nào của bạn bằng cách dùng các nút ở trên cùng để đến bảng phù hợp. Hãy chắc rằng bạn đã cung cấp địa chỉ e-mail chính xác. Nếu sau khi nhận được thông tin xác thực và bạn có vấn đề khi truy cập vào cổng thông tin, vui lòng liên hệ người quản trị.');
INSERT INTO `lang_definitions` VALUES (163355, 675, 27, 'Một chỉ dẫn điện tử và kết quả trả về sẽ theo dạng một thông điệp gọi là thông điệp HL7. HL7 là Health Level (Mức Sức khỏe - Lớp Ứng dụng) 7. Mục đích chính của HL7 là đơn giản hóa việc thể hiện các giao diện giữa các ứng dụng phần mềm chăm sóc sức khỏe và các nhà cung cấp khác nhau để giảm bớt khó khăn và chi phí liên quan đến việc lập trình giao diện tùy biến');
INSERT INTO `lang_definitions` VALUES (163356, 676, 27, 'Các sự kiện lặp lại phải có ngày kết thúc sau ngày bắt đầu!');
INSERT INTO `lang_definitions` VALUES (163357, 677, 27, 'Lỗi xảy ra khi đang ký biểu mẫu đó');
INSERT INTO `lang_definitions` VALUES (163358, 678, 27, 'Một lỗi xảy ra trong khi chép toàn bộ cây thư mục web OpenEMR');
INSERT INTO `lang_definitions` VALUES (163359, 679, 27, 'Một lỗi xảy ra trong khi chép toàn bộ cây thư mục web phpGACL');
INSERT INTO `lang_definitions` VALUES (163360, 680, 27, 'Một lỗi xảy ra trong khi chép toàn bộ cây thư mục web SQL-Ledger');
INSERT INTO `lang_definitions` VALUES (163361, 682, 27, 'Một lỗi xảy ra: Thiếu tập tin để tải lên: Dùng nút quay lại!');
INSERT INTO `lang_definitions` VALUES (163362, 683, 27, 'Cần nắm vững một khái niệm quan trọng là một khi ứng dụng xác thực thu nạp khóa bí mật được chuyển giao qua mã QR, sẽ không có sự truyền thông nào nữa giữa ứng dụng đó và OpenEMR, mỗi ứng dụng sẽ dùng giờ UNIX hiện tại và bản sao khóa bí mật riêng của người dùng để tạo ra cùng số 6 chữ số duy nhất ');
INSERT INTO `lang_definitions` VALUES (163363, 684, 27, 'Cần nhớ một điểm quan trọng là các xét nghiệm riêng lẽ trong mỗi bảng sẽ được liệt kê như là các Kết quả, do đó, bạn không thể trực tiếp yêu cầu các xét nghiệm riêng lẽ này');
INSERT INTO `lang_definitions` VALUES (163364, 685, 27, 'Đã tạo ra và liên kết một vấn đề GCAC không đầy đủ. Một người nào đó sẽ phải hoàn thành nó sau này.');
INSERT INTO `lang_definitions` VALUES (163365, 687, 27, 'Một Rắc rối lo về các vấn đề liên quan tới sức khỏe của bệnh nhân');
INSERT INTO `lang_definitions` VALUES (163366, 688, 27, 'Một rắc rối là một vấn đề y học, dị ứng, cho thuốc, giải phẫu hay rắc rối về răng');
INSERT INTO `lang_definitions` VALUES (163367, 690, 27, 'Đã tạo một chỉ dẫn thành công, tuy nhiên chưa tồn tại nơi để nhận và lưu giữ kết quả trả về và cần tạo nơi đó ');
INSERT INTO `lang_definitions` VALUES (163368, 691, 27, 'Một Kết quả cho vấn đề này - Đã giải quyết, Có tiến triển, Vẫn vậy, Tệ hơn, Chờ Theo dõi hay để nguyên là Chưa xác định');
INSERT INTO `lang_definitions` VALUES (163369, 692, 27, 'Đã xảy ra một lỗi bất ngờ, hãy liên hệ người quản trị hệ thống của bạn.');
