INSERT INTO `lang_definitions` VALUES (163696, 1250, 27, 'Đường màu xanh trong báo cáo này để cung cấp thông tin. Đường màu đen hiển thị thông tin có trước đây. Đường màu xanh lá cây cho thấy thay đổi đã được áp dụng thành công. Đường màu đỏ chỉ ra sai sót, hoặc thay đổi đã không được áp dụng, chúng phải được xử lý bằng tay. Tuyên bố hiện đang bị từ chối và đảo ngược thanh toán không được xử lý tự động và như vậy sẽ xuất hiện trong màu đỏ.');
