INSERT INTO `lang_definitions` VALUES (164001, 1782, 27, 'Nhấp vào \'xuất khẩu\' để xuất khẩu mục, tiểu thể loại, khoản, dữ liệu nội dung vào một tập tin văn bản. Bất kỳ giống nhau của tập tin này vào một tập tin XML là hoàn toàn trùng hợp ngẫu nhiên. Các thẻ mở và đóng cửa phải là trên cùng một dòng, họ phải là chữ thường không có dấu cách. Để nhập khẩu, trình duyệt cho một tập tin và nhấp vào \'nhập khẩu\'. Nếu dữ liệu là hoàn toàn khác nhau, nó sẽ kết hợp với các dữ liệu hiện có của bạn. Nếu có tên mục tương tự, một tuổi sẽ được lưu giữ và mới được lưu với một số được thêm vào cuối cùng.');
