INSERT INTO `lang_definitions` VALUES (165657, 5127, 27, 'Nếu đánh dấu vào hộp chọn và thông điệp đó được gửi cho nhiều người thì mỗi người phải xác nhận bằng cách nhấn vào nút Đặt Là Hoàn thành cho thông điệp đó ');
INSERT INTO `lang_definitions` VALUES (165658, 5128, 27, 'Nếu đánh dấu vào hộp chọn thì mỗi thành viên của nhóm nhận thông điệp đó phải xác nhận bằng cách nhấn vào nút Đặt Là Hoàn thành ');
INSERT INTO `lang_definitions` VALUES (165659, 5150, 27, 'nếu thất nghiệp thì nhập là Sinh viên');
INSERT INTO `lang_definitions` VALUES (165660, 5162, 27, 'Nếu bạn thay đổi e-RX Vai trò cho ePrescription, nó có thể ảnh hưởng đến công việc ePrescription. Nếu bạn phải đối mặt với bất kỳ khó khăn, hãy liên hệ với nhà cung cấp ePrescription của bạn.');
INSERT INTO `lang_definitions` VALUES (165661, 5182, 27, 'Nếu bạn đã chọn để tải lên chuyển tiền điện tử, sau đó cửa sổ tìm kiếm sẽ hiển thị lại với hoá đơn phù hợp từ các tập tin X12. Bạn có thể click vào bất kỳ của những con số hóa đơn (như mô tả dưới đây) nếu bạn muốn thực hiện bất kỳ chỉnh sửa trước khi thông tin chuyển tiền được áp dụng. Để áp dụng các thay đổi, hãy nhấp vào nút Process File ERA ở dưới cùng của trang. Điều này sẽ tạo ra một cửa sổ mới với một báo cáo chi tiết.');
INSERT INTO `lang_definitions` VALUES (165662, 5185, 27, 'Nếu bạn đã bước vào một ngày phải trả tiền trong các trang tìm kiếm, điều này sẽ ghi đè lên đăng ngày thanh toán và điều chỉnh nếu không được lấy từ các tập tin X12. Điều này có thể hữu ích cho mục đích báo cáo, nếu bạn muốn biên lai của bạn báo cáo sử dụng ngày đăng chứ không phải là công ty bảo hiểm \'s ngày chế biến. Lưu ý rằng điều này cũng sẽ ảnh hưởng đến ngày thanh toán và điều chỉnh trước khi được đưa vào tuyên bố thứ cấp.');
INSERT INTO `lang_definitions` VALUES (165663, 5199, 27, 'Nếu bạn muốn thay đổi các kiểu dữ liệu, hoặc thêm các hàng hoặc cột');
INSERT INTO `lang_definitions` VALUES (165664, 5200, 27, 'Nếu bạn muốn để nâng cấp cơ sở dữ liệu, sau đó đặt các tập tin zip cơ sở dữ liệu trong các thư mục sau đây');
