INSERT INTO `lang_definitions` VALUES (166517, 7256, 27, 'Lưu ý: Mã này đã không được nhập vào bởi một người dùng có thẩm quyền. Mã số duy nhất được ủy quyền có thể được tải lên Mạng Thanh toán Mở y tế để xử lý. Nếu bạn muốn tải lên các mã số, hãy chọn một người dùng có thẩm quyền ở đây.');
INSERT INTO `lang_definitions` VALUES (166518, 7259, 27, 'Chú ý: Nếu những tập tin đang tải lên có tên trùng với những tập tin đã có sẽ được tự động đổi tên (ví dụ, file.jpg sẽ trở thành file.1.jpg). Việc kiểm tra tên tập tin không trùng lặp được thực hiện cho mỗi bệnh nhân, không phải cho mỗi thể loại.');
INSERT INTO `lang_definitions` VALUES (166519, 7260, 27, 'Chú ý: Nếu những tập tin đang tải lên có tên trùng với những tập tin đã có sẽ được tự động đổi tên (ví dụ, \'<i>file.jpg</i>\' sẽ trở thành \'<i>file.1.jpg</i>\'). Việc kiểm tra tên tập tin không trùng lặp được thực hiện cho mỗi bệnh nhân, không phải cho mỗi thể loại.');
