INSERT INTO `lang_definitions` VALUES (168488, 12211, 27, 'Khi nhấp vào một số hóa đơn \"cửa sổ đăng hướng dẫn sử dụng\" xuất hiện. Ở đây bạn có thể thay đổi vào ngày đáo hạn và ghi chú cho hoá đơn, lựa chọn bên người mà bạn gửi bài, và chọn bảo hiểm cho tất cả paymants dự kiến ​​sẽ nhận được. Quan trọng nhất, cho mỗi mã thanh toán số tiền đã được tính phí, bạn có thể nhập thông tin thanh toán và điều chỉnh.');
INSERT INTO `lang_definitions` VALUES (168489, 12216, 27, 'Khi tìm kiếm bạn đang trình bày với một danh sách các hoá đơn. Bạn có thể click vào một trong các số hoá đơn để mở một cửa sổ thứ hai, đó là nhập dữ liệu trang cho hướng dẫn đăng. Bạn cũng có thể nhấp chuột vào một tên bệnh nhân nếu bạn muốn nhập một lưu ý rằng các nhân viên văn phòng phía trước sẽ nhìn thấy khi bệnh nhân kiểm tra, và bạn có thể chọn các hoá đơn xuất hiện trên báo cáo bệnh nhân và in các báo cáo.');
