INSERT INTO `lang_definitions` VALUES (169268, 628, 28, 'Ne menyre alternative,Ju mund te perdorni faqen e kerkimit per te ngarkuar nje cek elektronik (X12 835) qe keni marre nga pale e paguar ose nga zyra e shkembimit te ceqeve. Ju mund ta bene kete duke klikuar tek butoni Shfletoj dhe duke perzgjedhur filen qe doni te ngarkoni, dhe me pas duke kliuar tek Kerko per te bere ngarkimin dhe per te afishuar faturat perkatese. Ne kete rast parametrat e tjere te permendur me siper nuk aplikohen dhe do te injorohen. Procesi i ngarkimit e ruan filen por akoma nuk e proceson permbajtjen e files -- kjo gje kryhet me vehte sic pershkruhet me poshte.');
