INSERT INTO `lang_definitions` VALUES (173502, 1782, 29, 'Klikněte na \"export\" pro export kategorie, podkategorie, položky, údaje o obsahu do textového souboru. Jakákoliv podobnost tohoto souboru s XML souborem, je čistě náhodná. Značky pro otevírání a zavírání musí být na stejném řádku, musí obsahovat malá písmena bez mezer. Chcete-li importovat, vyhledejte soubor a klikněte na \"import\". Pokud se jedná o zcela odlišná data, pak budou sloučena s  již existujícími daty. Pokud existují podobné názvy položek, bude staré názvy zachovány a nové uloženy  s  číslem na konci.');
