INSERT INTO `lang_definitions` VALUES (175938, 7249, 29, 'Poznámka: Import externích dat může trvat více než hodinu v závislosti na konfiguraci hardwaru. Příklad:  datové rabulky RxNorm obsahují více než 6 milionů řádků.');
INSERT INTO `lang_definitions` VALUES (175939, 7256, 29, 'Poznámka: Tento kód nebyl zadán oprávněným uživatelem. Pouze autorizované kódy mohou být nahrány do sítě Open Medical Billing pro zpracování. Pokud chcete nahrát tyto kódy, prosím vyberte oprávněného uživatele zde.');
INSERT INTO `lang_definitions` VALUES (175940, 7259, 29, 'Poznámka: Nahrávání souborů s duplicitními názvy způsobí, že soubory budou automaticky přejmenovány (například file.jpg bude file.1.jpg). Názvy souborů jsou považovány za unikátní v rámci  pacienta a ne kategorie.');
INSERT INTO `lang_definitions` VALUES (175941, 7260, 29, 'Poznámka: Nahrávání souborů s duplicitními názvy způsobí, že soubory budou automaticky přejmenovány. Například \'<i>file.jpg</i>\' bude \'<i>file.jpg1</i>\'.  Názvy souborů jsou považovány za unikátní v rámci  pacienta a ne kategorie.');
