INSERT INTO `lang_definitions` VALUES (177928, 4, 30, 'Клієнтський сертифікат для користувача admin');
INSERT INTO `lang_definitions` VALUES (177929, 5, 30, 'Клінічне правило прийняття рішень-це конкретна інформація про пацієнта, яка фільтрується і представляється у відповідний час для поліпшення здоров\'я і надання медичної допомоги');
INSERT INTO `lang_definitions` VALUES (177930, 6, 30, 'Клінічний документ додається');
INSERT INTO `lang_definitions` VALUES (177931, 7, 30, 'Клінічний документ додається.');
INSERT INTO `lang_definitions` VALUES (177932, 8, 30, 'Код цього типу вже обраний. Спочатку зітріть поле, якщо вам потрібно його замінити.');
INSERT INTO `lang_definitions` VALUES (177933, 9, 30, '@ Прибув');
