INSERT INTO `lang_definitions` VALUES (177935, 11, 30, 'Код за замовчуванням є необов\'язковим, так як необхідний код може бути введений в момент розміщення фактичного замовлення');
INSERT INTO `lang_definitions` VALUES (177936, 12, 30, 'Докладний посібник щодо включення та налаштування клінічного правила прийняття рішень можна знайти тут');
INSERT INTO `lang_definitions` VALUES (177937, 13, 30, 'Потрібен дистриб\'ютор');
INSERT INTO `lang_definitions` VALUES (177938, 14, 30, 'Можна вказати дату виконання або вибрати конкретний період часу для відображення нагадування про дату');
INSERT INTO `lang_definitions` VALUES (177939, 15, 30, 'Кілька слів, щоб позначити причину візиту');
INSERT INTO `lang_definitions` VALUES (177940, 16, 30, 'Подальша зустріч також може бути запланована прямо з гонорарного листа.');
INSERT INTO `lang_definitions` VALUES (177941, 17, 30, 'До цього візиту слід додати форму відвідування GCAC.');
INSERT INTO `lang_definitions` VALUES (177942, 18, 30, 'Повідомлення HL7 v2.x просто складається з декількох рядків тексту, кожен рядок називається сегментом і далі ділиться на поля за допомогою символу труби ( / ).');
INSERT INTO `lang_definitions` VALUES (177943, 19, 30, 'Велике додаток, таке як OpenEMR, використовується багатьма користувачами з різними ролями та ступенями відповідальності. Вкрай важливо, щоб доступ до різних частин програми надавався користувачам на основі необхідності знати. Для цього використовуються списки контролю доступу (ACL).');
INSERT INTO `lang_definitions` VALUES (177944, 20, 30, 'Потрібен НОМЕР лота');
INSERT INTO `lang_definitions` VALUES (177945, 21, 30, 'Потрібен НОМЕР лота!');
INSERT INTO `lang_definitions` VALUES (177946, 22, 30, 'Мала літера');
INSERT INTO `lang_definitions` VALUES (177947, 23, 30, 'Нова зустріч');
INSERT INTO `lang_definitions` VALUES (177948, 24, 30, 'Нова функція допомагає групувати часто замовляються тести так, щоб вони могли бути замовлені разом');
INSERT INTO `lang_definitions` VALUES (177949, 25, 30, 'Таким чином, нове повідомлення може бути відправлено одному або декільком користувачам І / АБО МОЖЕ БУТИ про одного або декількох пацієнтів');
INSERT INTO `lang_definitions` VALUES (177950, 26, 30, 'Нові облікові дані пацієнтів не можуть бути відправлені після реєстрації на порталі.');
INSERT INTO `lang_definitions` VALUES (177951, 27, 30, 'У верхній частині сторінки центру повідомлень з\'явиться нове підменю tab');
INSERT INTO `lang_definitions` VALUES (177952, 28, 30, 'Число');
