INSERT INTO `lang_definitions` VALUES (177958, 34, 30, 'Місце для документування та відображення минулої історії хвороби пацієнта, сімейної історії, особистої історії');
INSERT INTO `lang_definitions` VALUES (177959, 35, 30, 'Спливаюче вікно попередить вас про успіх або невдачу');
INSERT INTO `lang_definitions` VALUES (177960, 36, 30, 'Позитивне число покаже, що багато минулих зустрічей на віджеті на екрані зведення пацієнта (негативне число покаже минулі зустрічі в порядку убування)');
INSERT INTO `lang_definitions` VALUES (177961, 37, 30, 'Позитивне число покаже, що багато минулих зустрічей знаходяться на віджеті на екрані зведення пацієнтів.');
INSERT INTO `lang_definitions` VALUES (177962, 38, 30, 'Був обраний продукт, але в цій формі немає розділу продукту.');
INSERT INTO `lang_definitions` VALUES (177963, 39, 30, 'Постачальник або склад можуть бути обрані в спадному списку. Щоб ця опція відображалася, необхідно встановити прапорець \"постачальник підтримки в рядку в платіжному аркуші\" на сторінці адміністрування > Глобали> виставлення рахунків');
INSERT INTO `lang_definitions` VALUES (177964, 41, 30, 'Повторювана Зустріч. Будь ласка, зв\'яжіться з вашою реєстраційною стійкою для будь-яких змін.');
INSERT INTO `lang_definitions` VALUES (177965, 42, 30, 'Реферал має додаткову дію-роздрукувати реферал або зберегти його у форматі pdf');
