INSERT INTO `lang_definitions` VALUES (178507, 627, 30, 'В якості альтернативи ви можете завантажити файл електронного перекладу (X12 835), отриманий від вашого платника або розрахункової палати. Ви можете зробити це, спочатку вибравши опцію \" завантаження ERA \"в початковому розділі\"Вибір методу\". Це викличе розділ \"Завантаження ери\".');
INSERT INTO `lang_definitions` VALUES (178508, 628, 30, 'Крім того, ви можете використовувати сторінку пошуку для завантаження файлу електронного перекладу (X12 835), який ви отримали від свого платника або розрахункової палати. Ви можете зробити це, натиснувши кнопку Огляд і вибравши файл для завантаження, а потім натиснувши кнопку Пошук, щоб виконати завантаження і відобразити відповідні рахунки-фактури. У цьому випадку інші параметри, згадані вище, не застосовуються і будуть проігноровані. Завантаження зберігає файл, але ще не обробляє його вміст-це робиться окремо, як описано нижче.');
INSERT INTO `lang_definitions` VALUES (178509, 629, 30, 'Хоча HCFA-1500 спочатку був розроблений для подання претензій Medicare, в кінцевому підсумку він був прийнятий усіма комерційними / приватними страховими компаніями для полегшення стандартизації процесу подання претензій');
