INSERT INTO `lang_definitions` VALUES (178552, 674, 30, 'Електронний лист з вашими новими обліковими даними буде надіслано на вказану раніше адресу електронної пошти. Ви все ще можете переглянути або відредагувати будь-яку частину вашої інформації, використовуючи верхні кнопки кроку, щоб перейти до відповідних панелей. Зверніть увагу, що Ви вказали правильну адресу електронної пошти. Якщо після отримання облікових даних у вас виникли проблеми з доступом до порталу, будь ласка, зв\'яжіться з адміністрацією.');
INSERT INTO `lang_definitions` VALUES (178553, 675, 30, 'Електронне замовлення та повернутий результат представлені у вигляді повідомлення, званого повідомленням HL7. HL7 означає рівень здоров\'я (прикладний рівень) 7. Основна мета HL7 полягає в тому, щоб спростити реалізацію інтерфейсів між медичними програмними додатками і різними постачальниками, щоб зменшити біль і витрати, пов\'язані з користувальницьким програмуванням інтерфейсів');
INSERT INTO `lang_definitions` VALUES (178554, 676, 30, 'Для повторних подій потрібна дата закінчення пізніше дати початку!');
INSERT INTO `lang_definitions` VALUES (178555, 677, 30, 'Сталася помилка при підписанні форми');
INSERT INTO `lang_definitions` VALUES (178556, 678, 30, 'Сталася помилка при скиданні дерева веб-каталогів OpenEMR');
INSERT INTO `lang_definitions` VALUES (178557, 679, 30, 'Сталася помилка при скиданні дерева веб-каталогів phpGACL');
INSERT INTO `lang_definitions` VALUES (178558, 680, 30, 'Сталася помилка при скиданні дерева веб-каталогів SQL-Ledger');
INSERT INTO `lang_definitions` VALUES (178559, 682, 30, 'Сталася помилка: відсутній файл для завантаження: використовуйте кнопку назад!');
INSERT INTO `lang_definitions` VALUES (178560, 683, 30, 'Важлива концепція, яку потрібно зрозуміти, полягає в тому, що як тільки секретний ключ, доставлений через QR-код, буде захоплений додатком authenticator, між додатком і OpenEMR більше не буде ніякого зв\'язку, кожен з них буде використовувати поточний час UNIX і свою копію користувацького загального секретного ключа для генерації одного і того ж унікального 6-значного номера');
INSERT INTO `lang_definitions` VALUES (178561, 684, 30, 'Важливо пам\'ятати, що різні індивідуальні тести в кожній панелі перераховані як результати, плоди, ви не можете безпосередньо замовити ці індивідуальні тести');
INSERT INTO `lang_definitions` VALUES (178562, 685, 30, 'Неповний випуск GCAC був створений і пов\'язаний. Хтось повинен буде закінчити його пізніше.');
INSERT INTO `lang_definitions` VALUES (178563, 687, 30, 'Питання стосується питань, пов\'язаних зі здоров\'ям пацієнта');
INSERT INTO `lang_definitions` VALUES (178564, 688, 30, 'Проблема-це медична проблема, алергія, ліки, хірургія або стоматологічна проблема');
