INSERT INTO `lang_definitions` VALUES (179089, 1250, 30, 'Сині лінії в цьому звіті носять інформаційний характер. Чорні лінії показують раніше існуючу інформацію. Зелені лінії показують зміни, які були успішно застосовані. Червоні лінії вказують на помилки або зміни, які не були застосовані; вони повинні бути оброблені вручну. В даний час відхилені претензії і повернення платежів не обробляються автоматично і тому будуть відображатися червоним кольором.');
