INSERT INTO `lang_definitions` VALUES (179212, 1376, 30, 'За замовчуванням активні повідомлення відображаються так, як зазначено в розділі під заголовком повідомлення');
INSERT INTO `lang_definitions` VALUES (179213, 1377, 30, 'За замовчуванням вибрані всі коди, зніміть прапорці з тих кодів, які вам не потрібні, і натисніть кнопку \"Додати\". Потім ці коди будуть додані до поточної зустрічі');
