INSERT INTO `lang_definitions` VALUES (179588, 1782, 30, 'Натисніть кнопку \"Експорт\", щоб експортувати дані категорії, підкатегорії, елемента або вмісту в текстовий файл. Будь-яка схожість цього файлу з XML-файлом є чисто випадковим. Відкриває і закриває теги повинні знаходитися в одному рядку, вони повинні бути рядковими без пробілів. Щоб імпортувати файл, знайдіть його і натисніть кнопку \"Імпорт\". Якщо дані повністю відрізняються, вони зіллються з вашими існуючими даними. Якщо є схожі назви елементів, то Старий буде збережений, а новий збережений з додаванням номера в кінці.');
INSERT INTO `lang_definitions` VALUES (179589, 1783, 30, 'Натисніть кнопку \"Зберегти\".');
