INSERT INTO `lang_definitions` VALUES (179764, 1968, 30, 'Натиснувши на кнопку \"Огляд\" , Ви отримаєте список всіх кодів, введених для попередніх зустрічей');
INSERT INTO `lang_definitions` VALUES (179765, 1969, 30, 'Натиснувши на вкладку введіть ім\'я або введіть ідентифікатор, ви відкриєте вікно пошуку, яке можна використовувати для вибору пацієнта');
INSERT INTO `lang_definitions` VALUES (179766, 1970, 30, 'При натисканні кнопки Встановити як завершене нагадування буде видалено з активного дисплея');
INSERT INTO `lang_definitions` VALUES (179767, 1971, 30, 'При натисканні на кнопку + на панелі заголовка пацієнта відкривається нова форма зустрічі');
INSERT INTO `lang_definitions` VALUES (179768, 1972, 30, 'При натисканні на кнопку Додати проблему з\'являється спливаюче вікно Додати проблему');
INSERT INTO `lang_definitions` VALUES (179769, 1973, 30, 'При натисканні на комірку кодування з\'явиться спливаюче вікно навчальних матеріалів, яке дозволить вам виконати пошук за кодом ICD10');
INSERT INTO `lang_definitions` VALUES (179770, 1974, 30, 'При натисканні на кнопку Створити датоване нагадування з\'явиться спливаюче вікно відправити нагадування');
INSERT INTO `lang_definitions` VALUES (179771, 1975, 30, 'При натисканні на кнопку Create Online / Offsite Portal Credentials буде згенеровано ім\'я користувача та пароль для пацієнта, які повинні бути надані пацієнту');
INSERT INTO `lang_definitions` VALUES (179772, 1976, 30, 'Натискання на кнопку Видалити призведе до видалення повідомлення');
INSERT INTO `lang_definitions` VALUES (179773, 1977, 30, 'Натиснувши на першу клітинку під заголовком, ви відкриєте спливаючу сторінку Додавання / редагування проблеми, яка дозволить вам відредагувати цей запис');
INSERT INTO `lang_definitions` VALUES (179774, 1978, 30, 'Натиснувши на значок поруч з підписом, ви побачите всі повідомлення, а підпис зміниться на всі повідомлення');
INSERT INTO `lang_definitions` VALUES (179775, 1979, 30, 'Натиснувши на значок поруч з їх ім\'ям, ви відкриєте вікно \"Правка\".');
INSERT INTO `lang_definitions` VALUES (179776, 1980, 30, 'Натиснувши на пункт меню Різне > Управління MFA або Ім\'я користувача > Управління MFA, ви потрапите на цільову сторінку для управління сторінкою багатофакторної аутентифікації для цього користувача');
INSERT INTO `lang_definitions` VALUES (179777, 1981, 30, 'Натиснувши на ім\'я пацієнта, ви побачите повідомлення');
INSERT INTO `lang_definitions` VALUES (179778, 1982, 30, 'Натиснувши на значок олівця, ви перейдете в режим редагування і відобразите спливаюче вікно введення відомостей, яке було використано для створення запису, що відображається в цьому рядку');
INSERT INTO `lang_definitions` VALUES (179779, 1983, 30, 'При натисканні на кнопки Показати всі або показати неактивні будуть показані відповідні повідомлення');
