INSERT INTO `lang_definitions` VALUES (181480, 3814, 30, 'Введіть дані категорії у відповідні поля і натисніть кнопку \"Зберегти\". Вони будуть використовуватися для угруповання кодів МКБ і будуть відображатися на кнопках в розділі \"Вибір кодів\".');
