INSERT INTO `lang_definitions` VALUES (182335, 4736, 30, 'Перейдіть в розділ Адміністрування > Глобали > З\'єднувачі, встановіть прапорець включити службу Зв\'язку MedEx і натисніть кнопку Зберегти');
INSERT INTO `lang_definitions` VALUES (182336, 4737, 30, 'Перейдіть в розділ Адміністрування > Списки, виберіть кожен з перерахованих вище списків у спадному списку і внесіть необхідні зміни');
INSERT INTO `lang_definitions` VALUES (182337, 4738, 30, 'Перейдіть до розділу адміністрування > Списки. У спадному списку виберіть пункт \"відомість зборів\".');
INSERT INTO `lang_definitions` VALUES (182338, 4739, 30, 'Перейдіть до розділу адміністрування > коди. Виберіть ICD 10 у розділі Тип, введіть код ICD 10, введіть опис, у розділі категорія виберіть відповідну категорію, цей код ICD 10 з\'явиться при натисканні кнопки з цією категорією');
INSERT INTO `lang_definitions` VALUES (182339, 4740, 30, 'Перейдіть в розділ Адміністрування > Списки і виберіть у спадному списку пункт\"типи кодів\". Використовуйте або ICD 9, або ICD 10, інактивуйте ICD 9 і виберіть \" Ні \" в останньому випадаючому списку під ICD 10');
