INSERT INTO `lang_definitions` VALUES (182668, 5090, 30, 'Ідентифікатор');
INSERT INTO `lang_definitions` VALUES (182669, 5091, 30, 'Ідентифікатор (одне слово)');
INSERT INTO `lang_definitions` VALUES (182670, 5092, 30, 'Ідентифікаційний код');
INSERT INTO `lang_definitions` VALUES (182671, 5093, 30, 'Час очікування сеансу очікування в Секундах');
INSERT INTO `lang_definitions` VALUES (182672, 5094, 30, 'Ідо');
INSERT INTO `lang_definitions` VALUES (182673, 5095, 30, 'якщо');
INSERT INTO `lang_definitions` VALUES (182674, 5096, 30, 'Якщо col даних поля = 0, то поле даних буде негайно слідувати за полем мітки в тому ж рядку');
INSERT INTO `lang_definitions` VALUES (182675, 5097, 30, 'Якщо мітка поля Col = 0, то мітка буде негайно слідувати за попереднім полем даних в послідовності замовлень, в тому ж рядку, що і поле даних.');
INSERT INTO `lang_definitions` VALUES (182676, 5098, 30, 'Якщо мітка поля Col = 1, то поле мітки перейде в новий рядок, якщо тільки загальне значення стовпця попереднього поля (мітка + дані) не буде менше кількості стовпців макета з властивостей групи або властивостей макета.');
INSERT INTO `lang_definitions` VALUES (182677, 5099, 30, 'Якщо продукт продається, то змініть значення за замовчуванням, щоб відобразити необхідну кількість. Залиште його на годину для процедур');
INSERT INTO `lang_definitions` VALUES (182678, 5100, 30, 'Якщо був обраний неправильний код, натисніть на текстове поле кодування, щоб відкрити спливаючу сторінку вибір кодів');
INSERT INTO `lang_definitions` VALUES (182679, 5101, 30, 'Якщо всі дані для всіх стовпців заповнені для цієї форми');
INSERT INTO `lang_definitions` VALUES (182680, 5102, 30, 'Якщо всі деталі були введені правильно, ви побачите рівень глюкози в крові в стовпці Ім\'я з вертикальною смугою перед ним, що вказує, що у нього немає нащадків або дітей, Результат в стовпці Категорія, WWT01R в стовпці Код, значення стовпця рівень має бути 3, а в стовпці опис має бути написано Результат глюкози натщесерце');
INSERT INTO `lang_definitions` VALUES (182681, 5103, 30, 'Якщо використовується обґрунтування виставлення рахунку, введіть ім\'я типу діагностичного коду.');
INSERT INTO `lang_definitions` VALUES (182682, 5104, 30, 'Якщо правильно налаштовано, в стовпці Ім\'я повинно бути написано Глюкоза в крові з вертикальною смугою перед ним, що вказує на відсутність нащадків або дітей, в стовпці категорія має бути написано користувальницький порядок, і обидва стовпці Ім\'я та Категорія будуть виділені рожевим кольором, що вказує на користувальницький згрупований порядок');
INSERT INTO `lang_definitions` VALUES (182683, 5105, 30, 'При бажанні поточне повідомлення можна роздрукувати');
INSERT INTO `lang_definitions` VALUES (182684, 5106, 30, 'Якщо ця функція включена, то час виконання, необхідний для перевірки хешу, буде відправлено в журнал помилок php.');
INSERT INTO `lang_definitions` VALUES (182685, 5107, 30, 'Якщо цей параметр увімкнено, використовуйте LDAP для входу та аутентифікації.');
INSERT INTO `lang_definitions` VALUES (182686, 5108, 30, 'Якщо цей параметр увімкнено, він використовує вказаний active directory для входу та автентифікації.');
INSERT INTO `lang_definitions` VALUES (182687, 5109, 30, 'якщо введено, виберіть тільки тих, хто мав цю послугу');
INSERT INTO `lang_definitions` VALUES (182688, 5110, 30, 'Якщо вона все ще активна, тобто Дата закінчення не введена, вона буде відображатися червоним кольором, якщо проблема має дату закінчення, то вона буде відображатися чорним');
INSERT INTO `lang_definitions` VALUES (182689, 5111, 30, 'Якщо ім\'я, будь-яка частина прізвища або прізвище, ім\'я');
INSERT INTO `lang_definitions` VALUES (182690, 5112, 30, 'Якщо включений модуль NewCrop eRx-електронний рецепт, то тут з\'являться кнопки NewCrop MedEntry і NewCrop Account Status');
INSERT INTO `lang_definitions` VALUES (182691, 5113, 30, 'Якщо його немає в списку, ви можете додати препарат в текстове поле заголовка');
INSERT INTO `lang_definitions` VALUES (182692, 5115, 30, 'Якщо тільки захопити QR код але не зареєструвати ключ TOTP за допомогою OpenEMR ця функція не буде включена при вході в систему');
INSERT INTO `lang_definitions` VALUES (182693, 5116, 30, 'Якщо у пацієнта призначена зустріч, натисніть кнопку ОК, щоб створити зустріч, в іншому випадку скасуйте її, а потім створіть зустріч для сьогоднішнього візиту.');
INSERT INTO `lang_definitions` VALUES (182694, 5117, 30, 'Якщо платити за');
INSERT INTO `lang_definitions` VALUES (182695, 5118, 30, 'Якщо людина померла, то введіть дату смерті.');
INSERT INTO `lang_definitions` VALUES (182696, 5119, 30, 'Якщо телефон втрачено, ви не зможете увійти в систему');
INSERT INTO `lang_definitions` VALUES (182697, 5120, 30, 'Якщо необхідно змінити привілеї, то це можна зробити або по одному користувачеві за раз в розділі Адміністрування > користувачі, або більш зручно на цій сторінці, тобто адміністрування > ACL, де всі користувачі перераховані на одній сторінці і доступно більше опцій.');
INSERT INTO `lang_definitions` VALUES (182698, 5121, 30, 'Якщо задано значення high, то видимість зустрічі буде обмежена користувачами, що належать до певних груп (AROs). За замовчуванням - лікарі та адміністратори');
INSERT INTO `lang_definitions` VALUES (182699, 5122, 30, 'Якщо використовується SMTP, то це ім\'я хоста або IP-адреса сервера.');
INSERT INTO `lang_definitions` VALUES (182700, 5123, 30, 'Якщо використовується SMTP, то номер TCP-порту сервера (зазвичай 25).');
INSERT INTO `lang_definitions` VALUES (182701, 5124, 30, 'При бажанні плату за замовчуванням можна відключити, перейшовши в розділ Адміністрування > календар > відгук плати: відключити, встановивши прапорець і натиснувши кнопку Зберегти');
INSERT INTO `lang_definitions` VALUES (182702, 5125, 30, 'Якщо це так, то вам доведеться створювати індивідуальні замовлення процедур (замовлення) для цих тестів разом з дискретними результатами (місце для введення і відображення повернутого результату)');
INSERT INTO `lang_definitions` VALUES (182703, 5126, 30, 'У разі успіху він автентифікує користувача');
INSERT INTO `lang_definitions` VALUES (182704, 5127, 30, 'Якщо прапорець встановлений і повідомлення відправляється кільком користувачам, то кожен користувач повинен підписати повідомлення, натиснувши кнопку Встановити як завершене для цього повідомлення');
INSERT INTO `lang_definitions` VALUES (182705, 5128, 30, 'Якщо прапорець встановлено, то кожен член групи, який отримав це повідомлення, повинен буде вийти з системи, натиснувши кнопку Встановити як завершене');
INSERT INTO `lang_definitions` VALUES (182706, 5129, 30, 'Якщо csv-файл був завантажений, то натисніть на кнопку \"Імпортувати святкові події\". Зверніть увагу, що при натисканні на кнопку будуть видалені всі існуючі рядки в таблиці calendar_external');
INSERT INTO `lang_definitions` VALUES (182707, 5130, 30, 'Якщо потрібний заголовок не включений, його можна ввести в текстове поле під списком');
INSERT INTO `lang_definitions` VALUES (182708, 5131, 30, 'Якщо у відображеній таблиці вказано що відповідний запис не знайдено це означає що набір кодів ICD10 Не встановлено');
INSERT INTO `lang_definitions` VALUES (182709, 5132, 30, 'Якщо файл довідки не існує створіть його і помістіть в');
INSERT INTO `lang_definitions` VALUES (182710, 5133, 30, 'Якщо проблема не була пов\'язана з будь-якою зустріччю, вона буде відображати 0');
INSERT INTO `lang_definitions` VALUES (182711, 5134, 30, 'Якщо медична проблема не вказана у спадному списку, натисніть на текстове поле кодування, щоб відкрити спливаючу сторінку вибір кодів');
INSERT INTO `lang_definitions` VALUES (182712, 5135, 30, 'Якщо повідомлення буде переадресовано, воно з\'явиться в списку активних повідомлень користувача, якому воно було переадресовано, і зникне зі списку активних повідомлень поточного користувача');
INSERT INTO `lang_definitions` VALUES (182713, 5136, 30, 'Якщо включений зовнішній портал пацієнта буде або кнопка з написом створити облікові дані зовнішнього порталу за умови що пацієнт дав дозвіл на доступ до онлайн порталу пацієнта або повідомлення з написом пацієнт не авторизував портал пацієнта');
INSERT INTO `lang_definitions` VALUES (182714, 5137, 30, 'Якщо онлайн портал пацієнта включений буде або кнопка з написом створити облікові дані онлайн порталу за умови що пацієнт дав дозвіл на доступ до онлайн порталу пацієнта або повідомлення з написом пацієнт не авторизував Портал пацієнта');
INSERT INTO `lang_definitions` VALUES (182715, 5138, 30, 'Якщо облікові дані онлайн / Оффсайтового порталу вже встановлені, то кнопка зміниться на');
INSERT INTO `lang_definitions` VALUES (182716, 5139, 30, 'Якщо у пацієнта є які-небудь демографічні дані, введені в OpenEMR, він автоматично заповнить відповідні поля в потрібних розділах');
INSERT INTO `lang_definitions` VALUES (182717, 5140, 30, 'Якщо пацієнт не авторизував портал пацієнта, то тут буде показано повідомлення пацієнт не авторизував Портал пацієнта');
INSERT INTO `lang_definitions` VALUES (182718, 5141, 30, 'Якщо пацієнт додається до списку відкликання в день візиту, він буде відображати поточну дату');
INSERT INTO `lang_definitions` VALUES (182719, 5142, 30, 'Якщо пацієнт передзвонює, щоб додати його в список, то останній візит може бути в далекому минулому. Майте на увазі, що 1,2,3 плюс року обчислюються і відображаються в полі дати в нижній частині цього розділу');
INSERT INTO `lang_definitions` VALUES (182720, 5143, 30, 'Якщо пацієнт помер, то повідомлення про смерть буде відображатися червоним кольором в цьому розділі');
INSERT INTO `lang_definitions` VALUES (182721, 5144, 30, 'Якщо звіт надсилається в електронному вигляді, то повинні бути виконані всі кроки, необхідні для безпечної та надійної передачі захищеної медичної інформації (PHI).');
INSERT INTO `lang_definitions` VALUES (182722, 5145, 30, 'Якщо Постачальника немає, введіть будь-який довільний унікальний номер, переважно 5-значний з нульовим заповненням, наприклад 00211');
INSERT INTO `lang_definitions` VALUES (182723, 5146, 30, 'Якщо ці тести відправляються в одну і ту ж зовнішню лабораторію вони матимуть ідентичні ідентифікаційні коди конкретного постачальника в результаті чого при відображенні результатів будуть з\'являтися повторювані рядки');
INSERT INTO `lang_definitions` VALUES (182724, 5147, 30, 'Якщо вони були налаштовані правильно, то кожен результат повинен мати значення рівня 4, що вказує на те, що вони є наступником або дочірнім елементом першого рядка вище зі значенням рівня 3, тобто.');
INSERT INTO `lang_definitions` VALUES (182725, 5148, 30, 'Якщо ця сторінка не оновлюється, перезавантажте сторінку повідомлень вручну');
INSERT INTO `lang_definitions` VALUES (182726, 5149, 30, 'Якщо unassigned буде за замовчуванням встановлений php.ini для date.timezone.');
INSERT INTO `lang_definitions` VALUES (182727, 5150, 30, 'якщо безробітний надійде Студентом');
INSERT INTO `lang_definitions` VALUES (182728, 5151, 30, 'Якщо значення залишити рівним нулю, то воно буде відсортовано за алфавітом');
INSERT INTO `lang_definitions` VALUES (182729, 5152, 30, 'Якщо ymd обраний для відображення віку, перейдіть на просто роки, коли пацієнти старше цього значення в роках');
INSERT INTO `lang_definitions` VALUES (182730, 5153, 30, 'Якщо у вас виникли проблеми з входом в свій аккаунт.');
INSERT INTO `lang_definitions` VALUES (182731, 5154, 30, 'Якщо вас цікавить що відбувається під капотом');
INSERT INTO `lang_definitions` VALUES (182732, 5155, 30, 'Якщо ви використовуєте лише невелику підмножину кодів CPT, ви можете ввести його вручну в розділі Адміністрування > коди');
INSERT INTO `lang_definitions` VALUES (182733, 5156, 30, 'Якщо ви плануєте вводити різні ціни для різних способів оплати, перейдіть в розділ Адміністрування > Списки');
INSERT INTO `lang_definitions` VALUES (182734, 5157, 30, 'Якщо ви не впевнені або використовували версію розробки між двома випусками, виберіть старіший з можливих випусків');
INSERT INTO `lang_definitions` VALUES (182735, 5159, 30, 'Якщо ви оновлюєтеся з версії нижче 5.0.0 до версії 5.0.0 або вище, зверніть увагу, що це оновлення може зайняти від декількох хвилин до декількох годин (ви побачите тільки білий екран до його завершення; не зупиняйте скрипт до його завершення, інакше ви ризикуєте пошкодити ваші дані)');
INSERT INTO `lang_definitions` VALUES (182736, 5160, 30, 'Якщо ви використовуєте електронну лабораторну запис, то заповніть необхідні дані і натисніть кнопку Зберегти');
INSERT INTO `lang_definitions` VALUES (182737, 5161, 30, 'Якщо ви використовуєте кілька лабораторій введіть дані для кожної з них');
INSERT INTO `lang_definitions` VALUES (182738, 5162, 30, 'Якщо ви зміните роль e-RX для ePrescription, це може вплинути на робочий процес ePrescription. Якщо ви зіткнетеся з будь-якими труднощами, зверніться до свого постачальника ePrescription.');
INSERT INTO `lang_definitions` VALUES (182739, 5163, 30, 'Якщо ви змінюєте свій смартфон, ви можете повернути QR-код ключа TOTP на новий пристрій, спочатку увійшовши в систему за допомогою програми authenticator на вашому старому телефоні, а потім перейшовши в розділ Різне > аутентифікація MFA і натиснувши кнопку Перегляд в розділі поточний метод аутентифікації');
INSERT INTO `lang_definitions` VALUES (182740, 5164, 30, 'Якщо ви встановите прапорець в будь-який з цих комірок він згенерує запис в останній комірці під назвою Прогрес');
INSERT INTO `lang_definitions` VALUES (182741, 5165, 30, 'Якщо ви вирішите виконати введення вручну, натисніть перемикач \"пошук рахунку-фактури\". Він відображає два розділи\" рознесення товару \"і\"пошук рахунку-фактури\".');
INSERT INTO `lang_definitions` VALUES (182742, 5166, 30, 'Якщо ви вирішите інтегрувати результати лабораторних досліджень із записом пацієнта, то необхідно виконати деяку попередню настройку');
INSERT INTO `lang_definitions` VALUES (182743, 5167, 30, 'Якщо ви натиснете на будь-якого користувача в розділі \"Членство користувачів\", то тепер побачите ці новостворені групи (ARO) в стовпці\"неактивні\". Тепер вони можуть бути призначені звичайним способом у міру необхідності.');
INSERT INTO `lang_definitions` VALUES (182744, 5168, 30, 'Якщо ви натиснете на значок редагування поруч з цією новоствореною групою (ARO), то помітите, що стовпець \"Активний\" містить тільки один запис - заповнювач (підтримує порожні списки ACL). Поки ця нова група (ARO) не має доступу до жодної частини програми, оскільки в стовпці \"Активний\" немає призначених ACOS.');
INSERT INTO `lang_definitions` VALUES (182745, 5169, 30, 'Якщо ви натиснете синій знак + в розділі хімія сироватки, то побачите новий рядок під назвою Панель органів / захворювань з категорією підгруп');
INSERT INTO `lang_definitions` VALUES (182746, 5170, 30, 'Якщо ви продовжуєте відчувати цю помилку, будь ласка, зверніться в службу підтримки.');
INSERT INTO `lang_definitions` VALUES (182747, 5171, 30, 'Якщо ви не знайшли потрібне значення у спадному списку, вам потрібно буде додати його через адміністрування > Списки > одиниці процедури. Зверніться до файлу довідки в розділі процедури > постачальники');
INSERT INTO `lang_definitions` VALUES (182748, 5172, 30, 'Якщо ви не виберете збіг, то пацієнт буде створений.');
INSERT INTO `lang_definitions` VALUES (182749, 5173, 30, 'Якщо ви не виберете хоча б один з них, OpenEMR буде працювати в режимі тільки прийому');
INSERT INTO `lang_definitions` VALUES (182750, 5174, 30, 'Якщо ви не відправляєте замовлення в електронному вигляді або не отримуєте результат в електронному вигляді, залиште його в якості значення за замовчуванням, Скачайте');
INSERT INTO `lang_definitions` VALUES (182751, 5176, 30, 'Якщо ви не хочете цього робити, наступний метод включає додавання даних вручну за допомогою інтерфейсу OpenEMR');
INSERT INTO `lang_definitions` VALUES (182752, 5177, 30, 'Якщо ви перейдете до рядка панелі електроліт і натиснете на знак + в стовпці Ім\'я, то побачите під ним натрій зі значенням категорії Результат зі значенням рівня 4');
INSERT INTO `lang_definitions` VALUES (182753, 5178, 30, 'Якщо ви перейдете до рядка панелі електроліту, то побачите, що вона має категорію замовлення і виділена жовтим кольором, що вказує на те, що це пошуковий і дійсний замовлення і має значення рівня 3');
INSERT INTO `lang_definitions` VALUES (182754, 5179, 30, 'Якщо ви вибрали кілька кодів, вони будуть розділені крапками з комою');
INSERT INTO `lang_definitions` VALUES (182755, 5180, 30, 'Якщо ви вже заповнили таблицю calendar_external, то натисніть на кнопку \"Синхронізувати\", щоб мати свята в поданні календаря. Зверніть увагу, що натискання на кнопку видалить всі існуючі елементи в поданні календаря, пов\'язані зі святами');
INSERT INTO `lang_definitions` VALUES (182756, 5181, 30, 'Якщо у вас є стара супербілла ви можете використовувати її угруповання кодів в якості шаблону для початку Налаштування');
INSERT INTO `lang_definitions` VALUES (182757, 5182, 30, 'Якщо ви вирішили завантажити електронні грошові перекази, то вікно пошуку повторно відобразиться з відповідними рахунками-фактурами з файлу X12. Ви можете натиснути на будь-який з цих номерів рахунків-фактур (як описано нижче), якщо хочете внести будь-які виправлення до того, як буде застосована інформація про переказ. Щоб застосувати зміни, натисніть кнопку обробити файл ERA в нижній частині сторінки. Це призведе до появи нового вікна з докладним звітом.');
INSERT INTO `lang_definitions` VALUES (182758, 5183, 30, 'Якщо ви вирішили завантажити електронні грошові перекази, то вікно пошуку повторно відобразиться з відповідними рахунками-фактурами з файлу X12. Ви можете натиснути на будь-який з цих номерів рахунків-фактур (як описано вище), якщо хочете внести будь-які виправлення до того, як буде застосована інформація про переказ. Щоб застосувати зміни, натисніть кнопку \"обробити файл ERA\" в нижній частині сторінки. Це призведе до появи нового вікна з докладним звітом.');
INSERT INTO `lang_definitions` VALUES (182759, 5184, 30, 'Якщо ви включили метод TOTP при наступному вході в систему вам буде запропоновано ввести пароль TOTP');
INSERT INTO `lang_definitions` VALUES (182760, 5185, 30, 'Якщо ви ввели дату оплати на сторінці пошуку, це перевизначить дату рознесення платежів і коригувань, які в іншому випадку беруться з файлу X12. Це може бути корисним для цілей звітності, якщо ви хочете, щоб ваша дата проведення була використана у звітах про квитанції, а не дата обробки страховою компанією. Зверніть увагу, що це також вплине на дати попередніх платежів і коригувань, які вносяться у вторинні вимоги.');
INSERT INTO `lang_definitions` VALUES (182761, 5186, 30, 'Якщо ви ввели дату оплати на сторінці пошуку, це перевизначить дату рознесення платежів і коригувань, які в іншому випадку беруться з файлу X12. Це може бути корисним для цілей звітності, якщо ви хочете, щоб ваша дата проведення була використана у звітах про квитанції, а не дата обробки страховою компанією. Зверніть увагу, що це також вплине на дати попередніх платежів і коригувань, які вносяться у вторинні вимоги.');
INSERT INTO `lang_definitions` VALUES (182762, 5187, 30, 'Якщо ви правильно виконали всі перераховані вище кроки, то повинні побачити сироватку сечової кислоти під назвою, їй буде передувати вертикальна смуга, яка вказує на відсутність нащадків або дітей у цього запису');
INSERT INTO `lang_definitions` VALUES (182763, 5188, 30, 'Якщо ви правильно виконали описані вище кроки, то тест на сечову кислоту в сироватці крові тепер повинен мати знак + перед Ім\'ям, що вказує на наявність спадкоємців або дітей');
INSERT INTO `lang_definitions` VALUES (182764, 5189, 30, 'Якщо ви втратили свій смартфон, ті, у кого є права адміністратора, можуть видалити ключі, перейшовши в розділ Адміністрування > користувачі, встановивши прапорець Очистити 2FA і натиснувши кнопку Зберегти');
INSERT INTO `lang_definitions` VALUES (182765, 5190, 30, 'Якщо у вас включений модуль NewCrop eRx, то алергію необхідно ввести на сторінці NewCrop MedEntry');
INSERT INTO `lang_definitions` VALUES (182766, 5191, 30, 'Якщо ви ще не виконали деяку попередню настройку, включаючи додавання постачальників, зробіть це, перейшовши в розділ процедури > постачальники');
INSERT INTO `lang_definitions` VALUES (182767, 5192, 30, 'Якщо у вас є необхідність замовити окремі компоненти панелі, вам доведеться створити окремий порядок процедур для кожного окремого компонента панелі і зберегти повернутий результат під дискретним результатом, створеним способом, аналогічним тому, який використовувався раніше для створення замовлення на сечову кислоту сироватки');
INSERT INTO `lang_definitions` VALUES (182768, 5193, 30, 'Якщо ви натиснете кнопку Оновити без установки будь-яких фільтрів, то всі датовані нагадування для користувача з\'являться нижче');
INSERT INTO `lang_definitions` VALUES (182769, 5194, 30, 'Якщо ви залишите його за замовчуванням рівним 0, то записи верхнього рівня, які ви робите, будуть відсортовані в алфавітному порядку');
INSERT INTO `lang_definitions` VALUES (182770, 5195, 30, 'Якщо ви внесли зміни і хочете повторно відправити його, видаліть оригінал (в повідомленнях) і повторіть спробу.');
INSERT INTO `lang_definitions` VALUES (182771, 5196, 30, 'Якщо ви внесли зміни і хочете повторно відправити його, видаліть оригінал (в повідомленнях) або почекайте 60 секунд і повторіть спробу.');
INSERT INTO `lang_definitions` VALUES (182772, 5197, 30, 'Якщо вам потрібно вручну ввести повернутий результат, кожен тест (Користувацький улюблений елемент) повинен мати дискретний результат як прямий нащадок');
INSERT INTO `lang_definitions` VALUES (182773, 5198, 30, 'Якщо ви не бачите записів у спадному списку замовлення з, це означає, що ви не налаштували лабораторію в розділі процедури > постачальники');
INSERT INTO `lang_definitions` VALUES (182774, 5199, 30, 'Якщо ви хочете змінити типи даних або додати рядки або стовпці');
INSERT INTO `lang_definitions` VALUES (182775, 5200, 30, 'Якщо ви хочете оновити базу даних, то помістіть zip-файл бази даних в наступний каталог');
INSERT INTO `lang_definitions` VALUES (182776, 5201, 30, 'Якщо ваш пошук був успішним результати пошуку будуть відображатися у вікні результатів пошуку нижче');
