INSERT INTO `lang_definitions` VALUES (182834, 5261, 30, 'Важливі коди');
INSERT INTO `lang_definitions` VALUES (182835, 5262, 30, 'Важливо: Номер NPI також існує в записі адресної книги для постачальника, подбайте про те, щоб ввести правильний номер NPI');
INSERT INTO `lang_definitions` VALUES (182836, 5263, 30, 'Важливо: цей інструмент завантаження призначений тільки для завантаження документів про пацієнтів, які ще не введені в систему. Щоб завантажити файли для пацієнтів, які вже були введені в систему, будь ласка, використовуйте інструмент завантаження, пов\'язаний з екраном зведення пацієнтів.');
INSERT INTO `lang_definitions` VALUES (182837, 5264, 30, 'Імпортні Алергії');
