INSERT INTO `lang_definitions` VALUES (182841, 5268, 30, 'Імпорт всього набору кодів CPT після того, як ви ліцензуєте його від Американської Медичної Асоціації, дасть вам всі відповідні коди CPT одним махом');
INSERT INTO `lang_definitions` VALUES (182842, 5269, 30, 'Враження / План');
