INSERT INTO `lang_definitions` VALUES (182847, 5274, 30, 'В');
INSERT INTO `lang_definitions` VALUES (182848, 5275, 30, 'Аналогічним чином ви створите Дискретний результат для калію, хлориду і вуглекислого газу');
INSERT INTO `lang_definitions` VALUES (182849, 5276, 30, 'Аналогічним чином створіть власний улюблений елемент для кожного ТТГ (послідовність 2, Ідентифікаційний код WWT02, стандартний код 30166-3) і вітаміну D (послідовність 3, ідентифікаційний код WWT03, стандартний код 35365-6)');
INSERT INTO `lang_definitions` VALUES (182850, 5277, 30, 'Аналогічним чином створіть дискретний результат для кожного ТТГ (Послідовність - 2, Ідентифікаційний код - WWT02R, Одиниці виміру - мЮ/Л, Діапазон за замовчуванням - 0,4-4, залиште Наступні служби порожніми) і вітаміну D (Послідовність - 3, Ідентифікаційний код - WWT03R, Одиниці виміру - нг/мл, Діапазон за замовчуванням - 0-20, залиште наступні служби порожніми)');
INSERT INTO `lang_definitions` VALUES (182851, 5278, 30, 'Крім того, є 2 прапорці');
INSERT INTO `lang_definitions` VALUES (182852, 5279, 30, 'На додаток до створення рефералу система також дозволяє роздрукувати порожню реферальну форму, яку можна заповнити вручну для створення реферала');
INSERT INTO `lang_definitions` VALUES (182853, 5280, 30, 'У будь-якому випадку встановлення з\'єднання, забезпечення відповідності HIPAA, безпека даних і т.д. зажадають кодування, витрати на яке, як правило, несе лабораторія. Однак вони схвалять тільки в тому випадку, якщо обсяг бізнесу виправдовує їх інвестиції');
INSERT INTO `lang_definitions` VALUES (182854, 5282, 30, 'У Поточному Чаті');
INSERT INTO `lang_definitions` VALUES (182855, 5283, 30, 'в кожному оці');
INSERT INTO `lang_definitions` VALUES (182856, 5284, 30, 'В оглядовій кімнаті');
INSERT INTO `lang_definitions` VALUES (182857, 5286, 30, 'В Будинку');
INSERT INTO `lang_definitions` VALUES (182858, 5288, 30, 'у лівому оці');
INSERT INTO `lang_definitions` VALUES (182859, 5289, 30, 'в ніздрі');
INSERT INTO `lang_definitions` VALUES (182860, 5290, 30, 'В Офісі');
INSERT INTO `lang_definitions` VALUES (182861, 5291, 30, 'У OpenEMR створювані звіти про безперервність запису догляду (CCR) можна обмежити певним діапазоном дат, встановивши прапорець Використовувати діапазон дат і ввівши потрібний діапазон дат');
INSERT INTO `lang_definitions` VALUES (182862, 5292, 30, 'Для того щоб виконати значущі вимоги до використання Комп\'ютеризованого введення замовлення Постачальника (CPOE) для лабораторних і радіологічних випробувань, цей модуль необхідно використовувати');
INSERT INTO `lang_definitions` VALUES (182863, 5293, 30, 'Щоб правильно зберігати і витягувати результати тестів і розміщувати нові замовлення, тести / Замовлення повинні бути налаштовані ієрархічно');
INSERT INTO `lang_definitions` VALUES (182864, 5294, 30, 'Щоб записати значення повернутих результатів, ви повинні створити окремий Дискретний результат (Рівень 4) для кожного з компонентів панелі, як прямих нащадків цієї гілки (Загальна панель здоров\'я) (Рівень 3). Прикладами результатів є CBC-гемоглобін, CBC-Гематокрит, CMP-натрій, CMP - калій, ТТГ і т. д.');
INSERT INTO `lang_definitions` VALUES (182865, 5295, 30, 'Для того щоб зареєструвати свій пристрій, будь ласка, вкажіть свій логін-пароль OpenEMR');
INSERT INTO `lang_definitions` VALUES (182866, 5296, 30, 'Для надсилання запису безперервності догляду (CCR) та / або документа безперервності догляду (CCD) додатково перевірте phiMail Allow CCD Send та/або phiMail Allow CCR Send, щоб увімкнути функцію передачі для цих типів даних');
INSERT INTO `lang_definitions` VALUES (182867, 5297, 30, 'У нашому випадку ми виберемо локальну лабораторію, яка була налаштована раніше');
INSERT INTO `lang_definitions` VALUES (182868, 5298, 30, 'У нашому випадку ми залишимо його як непризначений');
INSERT INTO `lang_definitions` VALUES (182869, 5300, 30, 'У портретному режимі визначає висоту обвідної вздовж осі y в мм');
INSERT INTO `lang_definitions` VALUES (182870, 5301, 30, 'У портретному режимі визначає ширину обвідної вздовж осі x в мм');
INSERT INTO `lang_definitions` VALUES (182871, 5302, 30, 'у правому оці');
INSERT INTO `lang_definitions` VALUES (182872, 5303, 30, 'Коротше кажучи, електронні замовлення можуть бути зроблені, Це включає в себе значну кількість випробувань і настройки, які повинні бути сертифіковані лабораторією, як правило, через третю сторону, і може статися тільки в тому випадку, якщо лабораторія погодиться дати зелене світло проекту');
INSERT INTO `lang_definitions` VALUES (182873, 5304, 30, 'У розділі \"Поштовий товар\", який відображається вгорі, ви можете ввести джерело (наприклад, номер чека), дату оплати і суму чека. Причина для джерела та дати оплати полягає в тому, що вам не потрібно вводити їх знову і знову для кожної претензії. Сума, яку Ви вводите, буде зменшена для кожного рахунку, який є частиною платежу, і, сподіваюся, закінчиться на нулі, коли ви закінчите.');
INSERT INTO `lang_definitions` VALUES (182874, 5305, 30, 'У наведеному вище прикладі було створено замовлення на один тест, тобто на сечову кислоту сироватки крові');
INSERT INTO `lang_definitions` VALUES (182875, 5306, 30, 'В установці за замовчуванням натисніть кнопку Додати, щоб відкрити спливаючу сторінку Додати / Змінити проблему');
INSERT INTO `lang_definitions` VALUES (182876, 5307, 30, 'За словами пацієнта');
INSERT INTO `lang_definitions` VALUES (182877, 5308, 30, 'На другому етапі осмисленого використання CCD, але не CCR, був включений в стандарт обміну клінічними документами');
INSERT INTO `lang_definitions` VALUES (182878, 5309, 30, 'У цьому випадку користувацька група вибраних буде називатися Preop Labs, а дві розпізнані панелі будуть прямими нащадками, кожна в призначеному для користувача рівні обраних елементів з іменами CBC і Renal Panel відповідно');
INSERT INTO `lang_definitions` VALUES (182879, 5310, 30, 'У цьому випадку ви створите порядок процедур, плодоносну гілку під назвою General Health Panel (Tier 3)');
INSERT INTO `lang_definitions` VALUES (182880, 5311, 30, 'В цілому існує сімнадцять розділів, які можуть бути включені в запис безперервності догляду (CCR)');
