INSERT INTO `lang_definitions` VALUES (183238, 5695, 30, 'Він поєднує в собі те, що користувач знає, тобто пароль користувача, з тим, що у нього є, тобто унікальний пристрій або механізм для генерації/отримання унікального коду, який буде використовуватися при кожному вході в систему');
