INSERT INTO `lang_definitions` VALUES (183245, 5702, 30, 'Він містить структуровані дані, які включені в запис безперервності медичної допомоги( CCR), встановлену відповідно до стандарту архітектури клінічних документів');
INSERT INTO `lang_definitions` VALUES (183246, 5703, 30, 'Він не відноситься до фактичного рефералу, який був створений');
INSERT INTO `lang_definitions` VALUES (183247, 5704, 30, 'Він робить це за допомогою алгоритму об\'єднання поточного часу UNIX з секретним ключем для створення постійно мінливого унікального ключа');
INSERT INTO `lang_definitions` VALUES (183248, 5705, 30, 'Він має чотири вкладки');
INSERT INTO `lang_definitions` VALUES (183249, 5706, 30, 'Він має три яруси');
INSERT INTO `lang_definitions` VALUES (183250, 5707, 30, 'Це комерційний модуль обміну повідомленнями, доступний для практик OpenEMR, що використовують версію 5.0.1 і вище');
INSERT INTO `lang_definitions` VALUES (183251, 5708, 30, 'Це поле в заголовку повідомлення HL7, відоме як ідентифікатор обробки');
INSERT INTO `lang_definitions` VALUES (183252, 5709, 30, 'Це частина медичної карти');
INSERT INTO `lang_definitions` VALUES (183253, 5710, 30, 'Це також послуга на основі підписки');
INSERT INTO `lang_definitions` VALUES (183254, 5711, 30, 'Також необхідно перерахувати код ICD10 для того, щоб проблема була вказана в Звіті про безперервність догляду (CCR) і документі про безперервність догляду (CCD)');
INSERT INTO `lang_definitions` VALUES (183255, 5712, 30, 'Він розділений на дві частини');
INSERT INTO `lang_definitions` VALUES (183256, 5713, 30, 'Дуже важливо, щоб Ви прочитали перші чотири розділи, щоб зрозуміти основні принципи');
INSERT INTO `lang_definitions` VALUES (183257, 5714, 30, 'Набагато простіше і інтуїтивно зрозуміліше внести серйозні зміни і реорганізувати дані в електронній таблиці, перш ніж ви почнете вводити дані в OpenEMR');
INSERT INTO `lang_definitions` VALUES (183258, 5715, 30, 'Важливо розуміти, що це управляє MFA для увійшов в систему користувача');
INSERT INTO `lang_definitions` VALUES (183259, 5716, 30, 'Важливо розуміти функцію цих двох значків, так як всі наступні кроки, необхідні для правильного налаштування ієрархії, будуть залежати від правильного використання цих двох значків');
INSERT INTO `lang_definitions` VALUES (183260, 5717, 30, 'Він призначений для включення тільки тієї інформації, яка має вирішальне значення для ефективного продовження лікування');
INSERT INTO `lang_definitions` VALUES (183261, 5718, 30, 'Він видається постачальникам медичних послуг у Сполучених Штатах Центрами Medicare і Medicaid Services (CMS)');
INSERT INTO `lang_definitions` VALUES (183262, 5719, 30, 'Це не обов\'язково для локальної лабораторії, замість цього ви можете використовувати будь-який довільний унікальний номер');
INSERT INTO `lang_definitions` VALUES (183263, 5720, 30, 'Немає необхідності заповнювати діагностичні коди за замовчуванням, так як коди ICD10 можуть бути введені в момент фактичного замовлення тесту');
INSERT INTO `lang_definitions` VALUES (183264, 5721, 30, 'Вона не подається з претензією');
INSERT INTO `lang_definitions` VALUES (183265, 5722, 30, 'Нерідко замовляють кілька аналізів крові разом, угруповання їх у вигляді панелі тестів полегшує цей процес');
INSERT INTO `lang_definitions` VALUES (183266, 5723, 30, 'Розсудливо стежити за провайдером, якщо з ним не зв\'язалися.');
INSERT INTO `lang_definitions` VALUES (183267, 5724, 30, 'Це основна паперова форма претензії, запропонована багатьма платниками для претензій, поданих окремими лікарями та практиками, медсестрами та професіоналами, включаючи терапевтів, хіропрактиків та амбулаторні клініки, а в деяких випадках і для служб швидкої допомоги');
INSERT INTO `lang_definitions` VALUES (183268, 5725, 30, 'Він використовується для зв\'язку проблем із зустрічами, а також для того, щоб побачити, які зустрічі пов\'язані з конкретною проблемою');
INSERT INTO `lang_definitions` VALUES (183269, 5726, 30, 'Корисно потренуватися на пробному сайті, щоб ознайомитися з процесом, перш ніж робити це в виробничому додатку OpenEMR');
INSERT INTO `lang_definitions` VALUES (183270, 5727, 30, 'Він дозволяє здійснювати пошук за діагностичними кодами ICD 9 і ICD 10, а також сервісним / процедурним кодам CPT4 і HCPCS');
INSERT INTO `lang_definitions` VALUES (183271, 5728, 30, 'Він дозволяє відправляти повідомлення і датовані нагадування співробітникам, додавати пацієнта в список відкликання і відправляти SMS-повідомлення пацієнтам');
INSERT INTO `lang_definitions` VALUES (183272, 5729, 30, 'Він служить необхідним мостом в інше середовище, часто з новими клініцистами, які нічого не знають про пацієнта, дозволяючи наступному постачальнику легко');
INSERT INTO `lang_definitions` VALUES (183273, 5731, 30, 'Тому само собою зрозуміло, що ви не можете створити Контрреферал сам по собі');
INSERT INTO `lang_definitions` VALUES (183274, 5732, 30, 'Він використовує відкритий стандарт і тому доступний від різних виробників');
INSERT INTO `lang_definitions` VALUES (183275, 5733, 30, 'Він використовує хеш-функцію HMAC-SHA256 для створення унікального закритого ключа для облікового запису');
INSERT INTO `lang_definitions` VALUES (183276, 5734, 30, 'Він використовує цей закритий ключ для підпису виклику і відправляє відповідь назад в додаток');
INSERT INTO `lang_definitions` VALUES (183277, 5735, 30, 'Він буде відображений у зведенні відвідування');
INSERT INTO `lang_definitions` VALUES (183278, 5736, 30, 'Він викличе спливаючу форму введення відомостей');
INSERT INTO `lang_definitions` VALUES (183279, 5737, 30, 'Він викличе спливаюче вікно Multi patient finder');
INSERT INTO `lang_definitions` VALUES (183280, 5738, 30, 'Він відобразить спливаюче вікно justify display. У нього є вікно пошуку, яке дозволить вам шукати код ICD. Він також буде відображати 10 найбільш часто використовуваних кодів МКБ. Ви можете вибрати будь-який або всі коди, встановивши прапорець J (justify) і натиснувши кнопку Оновити');
INSERT INTO `lang_definitions` VALUES (183281, 5739, 30, 'Він буде мати значення 2 у стовпці Tier, що вказує на те, що він є наступником або дочірнім елементом у першому рядку вище, що має значення Tier 1, яке в даному випадку є хімією сироватки');
INSERT INTO `lang_definitions` VALUES (183282, 5740, 30, 'Він буде складатися з двох розділів-розділу Проблем і розділу зустрічей');
INSERT INTO `lang_definitions` VALUES (183283, 5741, 30, 'Це допоможе пізніше в усуненні проблем, які можуть виникнути при налаштуванні модуля замовлень процедур');
INSERT INTO `lang_definitions` VALUES (183284, 5742, 30, 'Він відкриє розділ Створити нове повідомлення');
INSERT INTO `lang_definitions` VALUES (183285, 5743, 30, 'Він приведе вас на сторінку реєстрації MedEx');
INSERT INTO `lang_definitions` VALUES (183286, 5744, 30, 'Потім він з\'явиться в віджеті алергія на панелі моніторингу пацієнта, а також в розділі алергія на сторінці проблеми');
INSERT INTO `lang_definitions` VALUES (183287, 5745, 30, 'Потім він з\'явиться в віджеті ліки на панелі моніторингу пацієнта, а також в розділі ліки на сторінці проблеми');
