INSERT INTO `lang_definitions` VALUES (183314, 5782, 30, 'Трохи нижче контрольної інформації знаходиться синя область, в яку Ви вводите параметри пошуку. Ви можете шукати за ім\'ям пацієнта, номером картки, номером зустрічі або датою обслуговування або будь-якої їх комбінації. Ви також можете вибрати, чи хочете ви бачити всі рахунки-фактури, відкриті рахунки-фактури або тільки ті рахунки, які повинні бути оплачені (пацієнтом). Натисніть кнопку Пошук, щоб виконати пошук.');
