INSERT INTO `lang_definitions` VALUES (184689, 7241, 30, 'Зверніть увагу, що резервна копія журналу подій в даний час налаштована на збереження в наступній папці');
INSERT INTO `lang_definitions` VALUES (184690, 7242, 30, 'Зверніть увагу, що заголовок спливаючої форми тепер буде читати: введіть відомості для користувацької вибраної групи');
INSERT INTO `lang_definitions` VALUES (184691, 7243, 30, 'Зверніть увагу, що заголовок спливаючої форми тепер буде читати введення відомостей для дискретних результатів');
INSERT INTO `lang_definitions` VALUES (184692, 7244, 30, 'Зверніть увагу, що заголовок спливаючої форми тепер буде читати: введіть відомості про окремі процедури');
INSERT INTO `lang_definitions` VALUES (184693, 7245, 30, 'Зверніть увагу, що тут немає кнопки \"Зберегти\".');
INSERT INTO `lang_definitions` VALUES (184694, 7246, 30, 'Примітка. це стосується запису про безперервність догляду (CCR) або документа про безперервність догляду (CCD) залежно від обставин');
INSERT INTO `lang_definitions` VALUES (184695, 7247, 30, 'Тип примітки');
INSERT INTO `lang_definitions` VALUES (184696, 7248, 30, 'Примітка: 12:00 опівдні-це PM, а не AM');
INSERT INTO `lang_definitions` VALUES (184697, 7249, 30, 'Примітка: імпорт зовнішніх даних може зайняти більше години в залежності від конфігурації вашого обладнання. Наприклад, одна з таблиць даних RxNorm містить більше 6 мільйонів рядків.');
INSERT INTO `lang_definitions` VALUES (184698, 7250, 30, 'Примітка: в даний час підтримується тільки дворічний міжнародний випуск Snomed');
