INSERT INTO `lang_definitions` VALUES (184702, 7254, 30, 'Примітка: імпорт може зайняти до декількох годин');
INSERT INTO `lang_definitions` VALUES (184703, 7255, 30, 'Примітка: Цей код не був авторизований.');
INSERT INTO `lang_definitions` VALUES (184704, 7256, 30, 'Примітка: Цей код не був введений авторизованим користувачем. Тільки авторизовані коди можуть бути завантажені у відкриту медичну білінгову мережу для обробки. Якщо ви хочете завантажити ці коди, будь ласка, виберіть тут авторизованого користувача.');
INSERT INTO `lang_definitions` VALUES (184705, 7257, 30, 'Примітка: Ця доплата була введена проти виставлення рахунків, які не були авторизовані. Будь ласка, перегляньте статус.');
