INSERT INTO `lang_definitions` VALUES (184708, 7260, 30, 'Примітка: завантаження файлів з повторюваними іменами призведе до автоматичного перейменування файлів. Наприклад \'<i>file.jpg< / i> \'стане\' <i>file.jpg.1</i>\'. Імена файлів вважаються унікальними для кожного пацієнта, а не для кожної категорії.');
