INSERT INTO `lang_definitions` VALUES (184893, 7452, 30, 'Як тільки призначена зустріч відгук буде видалений з дошки відкликання');
INSERT INTO `lang_definitions` VALUES (184894, 7453, 30, 'Після завершення перегляньте та збережіть цю зустріч у вигляді PDF-файлу');
INSERT INTO `lang_definitions` VALUES (184895, 7454, 30, 'Після завершення редагування натисніть кнопку Зберегти. Форми процедур поточні діагнози процедур будуть заповнюватися точно так же, як і в цьому діалоговому вікні.');
INSERT INTO `lang_definitions` VALUES (184896, 7455, 30, 'Після збереження сутність для користувацької обраної групи не може бути змінена. Якщо вам потрібно змінити сутність, ви повинні видалити цей запис і створити нову');
INSERT INTO `lang_definitions` VALUES (184897, 7456, 30, 'Як тільки додаток захопить QR код воно покаже ім\'я Користувача OpenEMR в додатку');
INSERT INTO `lang_definitions` VALUES (184898, 7457, 30, 'Як тільки основний бізнес-об\'єкт буде встановлений, зміна ідентифікатора об\'єкта вплине на ePrescription NewCrop.');
INSERT INTO `lang_definitions` VALUES (184899, 7458, 30, 'Після того, як основний бізнес-об\'єкт встановлений, він не повинен бути змінений. Зміна об\'єкта вплине на роботу в NewCrop ePrescription.');
INSERT INTO `lang_definitions` VALUES (184900, 7459, 30, 'Як тільки ця функція буде включена, вам буде потрібно вводити 6-значний ключ при кожному вході в систему');
INSERT INTO `lang_definitions` VALUES (184901, 7460, 30, 'Як тільки це буде зроблено загальний секретний ключ унікальний для кожного користувача повинен існувати тільки в OpenEMR і в додатку аутентифікатора користувача');
INSERT INTO `lang_definitions` VALUES (184902, 7461, 30, 'Як тільки цей крок буде завершено, ви можете перейти до наступного кроку-Налаштування тестів , які можна замовити з системи');
INSERT INTO `lang_definitions` VALUES (184903, 7462, 30, 'Як тільки ви зміните свій пароль, вам доведеться повторно увійти в систему.');
