INSERT INTO `lang_definitions` VALUES (184965, 7530, 30, 'Open Med Practice та її постачальники докладають своїх комерційно обґрунтованих зусиль для надання їм найбільш актуальних і повних даних, що стосуються історії рецептів, лікарських взаємодій і формулярів, алергії пацієнтів та інших факторів, але, використовуючи цю послугу, ви визнаєте, що (1) повнота і точність таких даних залежить від повноти і точності, з якою вони вводяться в підключені електронні бази даних лікарями, кабінетами лікарів, менеджерами фармацевтичних пільг, фірмами електронної медичної документації та іншими учасниками мережі, (2) такі дані можуть бути помилковими або пропущеними при введенні, зберіганні або, передачі та відображення, технічні збої, відключення живлення або послуг., або інші перерви в електронному зв\'язку, будь-який або всі з яких можуть бути поза контролем Open Med Practice і її постачальників, і (3) деяка інформація може бути недоступна через нормативних, договірних, конфіденційних або інших правових обмежень. Ви несете відповідальність за те, щоб завжди використовувати своє клінічне судження при наданні медичних послуг та консультуванні.');
