INSERT INTO `lang_definitions` VALUES (185484, 8068, 30, 'Зверніть увагу на прапорці \"Готово\". Після того як страховки будуть позначені як завершені, ми почнемо просити пацієнта оплатити залишок, що залишився; якщо ви не відзначите всі страховки як завершені, то сума, що залишилася не буде зібрана! Крім того, якщо є баланс, який пацієнт повинен сплатити, то встановіть дату оплати відповідним чином, так як це вплине на мову, яка з\'являється в заявах пацієнта.');
INSERT INTO `lang_definitions` VALUES (185485, 8069, 30, 'Зверніть увагу на прапорці \"Готово\". Після того як страховки будуть позначені як завершені, ми почнемо просити пацієнта оплатити залишок, що залишився; якщо ви не відзначите всі страховки як завершені, то сума, що залишилася не буде зібрана! Крім того, якщо є баланс, який пацієнт повинен сплатити, то встановіть дату оплати відповідним чином, так як це вплине на мову, яка з\'являється в заявах пацієнта.');
