INSERT INTO `lang_definitions` VALUES (188172, 10955, 30, 'Вікно \" Правка \"розділене на дві колонки:\" активна \"і\"неактивна\". Групи (AROS), перераховані в активному стовпці, - це ті групи, до яких належить користувач.');
INSERT INTO `lang_definitions` VALUES (188173, 10956, 30, 'У розділі \"Вибір кодів\" тепер всі введені вами коди CPT і ICD будуть згруповані за категоріями, які ви вибрали');
INSERT INTO `lang_definitions` VALUES (188174, 10957, 30, 'Клавіша * Tab * створює кожен запис.');
INSERT INTO `lang_definitions` VALUES (188175, 10958, 30, 'Форма заявки 1500 також може бути використана для передачі даних про зустрічі пацієнтів федеральним, державним та / або іншим установам громадської охорони здоров\'я');
INSERT INTO `lang_definitions` VALUES (188176, 10959, 30, '837P ( Professional) - це стандартний формат, який використовується медичними працівниками та постачальниками для передачі медичних претензій в електронному вигляді');
INSERT INTO `lang_definitions` VALUES (188177, 10960, 30, 'Можливість пов\'язувати окремі проблеми з контактами з пацієнтами дозволить користувачеві швидко визначити результат проблеми з плином часу');
INSERT INTO `lang_definitions` VALUES (188178, 10961, 30, 'Вищенаведене твердження Не вдалося');
INSERT INTO `lang_definitions` VALUES (188179, 10962, 30, 'Сторінка ACL складається з двох розділів.');
INSERT INTO `lang_definitions` VALUES (188180, 10963, 30, 'Фактичні суми, які будуть відображатися, повинні існувати в базі даних');
INSERT INTO `lang_definitions` VALUES (188181, 10964, 30, 'Фактичні тести або процедури, які можна знайти і замовити, виділені жовтим кольором');
INSERT INTO `lang_definitions` VALUES (188182, 10965, 30, 'Значок Додати використовується для налаштування рівня, який буде прямим нащадком цього рівня');
INSERT INTO `lang_definitions` VALUES (188183, 10966, 30, 'Перевага інтеграції результатів з діаграмою пацієнта у вигляді структурованих даних полягає в можливості маніпулювати ними, щоб побачити тенденції в одному зручному місці, побудувати графіки з даними і використовувати їх в аналізі даних');
INSERT INTO `lang_definitions` VALUES (188184, 10967, 30, 'Перевага сканування результатів в діаграму полягає в простоті - не потрібно ніякої настройки, крім визначення каталогу / папки в карті пацієнта під документами, де буде зберігатися результат. Будучи неструктурованими даними, він не має перерахованих вище переваг і не буде відповідати значущим критеріям використання для комп\'ютеризованого введення замовлення Постачальника (CPOE)');
INSERT INTO `lang_definitions` VALUES (188185, 10968, 30, 'Рішення Allscripts інтегрує веб-сайт Allscripts ePrescribe з OpenEMR');
INSERT INTO `lang_definitions` VALUES (188186, 10969, 30, 'Американська медична асоціація визначила 9 панелей, які можна замовити. Кожна панель містить кілька тестів, згрупованих разом');
INSERT INTO `lang_definitions` VALUES (188187, 10970, 30, 'Сума буде відображатися в стовпці Оплата або коригування в залежності від обставин');
INSERT INTO `lang_definitions` VALUES (188188, 10971, 30, 'Сертифікат сервера Apache SSL і відкритий ключ');
INSERT INTO `lang_definitions` VALUES (188189, 10972, 30, 'Додаток генерує виклик-випадкове число і передає його на USB-ключ разом з nonce і контрольною сумою, що зберігаються в додатку');
INSERT INTO `lang_definitions` VALUES (188190, 10973, 30, 'Потім додаток використовує відкритий ключ, який USB-пристрій надіслав під час реєстрації, щоб перевірити відповідь');
INSERT INTO `lang_definitions` VALUES (188191, 10974, 30, 'Зміни статусу прийому та створення зустрічей управляються через Трекер пацієнтів.');
INSERT INTO `lang_definitions` VALUES (188192, 10975, 30, 'Ім\'я аутентифікації або ключ API для вибраного облікового запису. Ім\'я Auth для авторизации.Net і API Secret для Stripe.');
INSERT INTO `lang_definitions` VALUES (188193, 10976, 30, 'Стовпець балансу буде порожнім');
INSERT INTO `lang_definitions` VALUES (188194, 10977, 30, 'Основна мета програми authenticator полягає в тому, щоб згенерувати 20 байт (160 біт) коду, закодованого в base32 за допомогою захищеної хеш-функції SHA-1, і називається HMAC-SHA1 (Hash-based Message Authentication Code)');
INSERT INTO `lang_definitions` VALUES (188195, 10978, 30, 'Основою для CCR є форма направлення пацієнта на лікування, розроблена Департаментом громадської охорони здоров\'я штату Массачусетс');
INSERT INTO `lang_definitions` VALUES (188196, 10979, 30, 'У стовпці Дата виставлення рахунку / платник буде показана дата отримання платежу за статтею та ім\'я платника-або страховка, або пацієнт');
INSERT INTO `lang_definitions` VALUES (188197, 10980, 30, 'У стовпці Дата виставлення рахунку / платник буде показана дата виставлення рахунку за статтею і платник-або страховка, або пацієнт');
INSERT INTO `lang_definitions` VALUES (188198, 10981, 30, 'Тіло містить клінічні дані, які можуть бути структуровані і організовані у вигляді одного або декількох розділів або можуть являти собою неструктурований згусток даних');
INSERT INTO `lang_definitions` VALUES (188199, 10982, 30, 'Поле Body Site, Administrate Via і Laterality можна залишити непризначеним');
INSERT INTO `lang_definitions` VALUES (188200, 10983, 30, 'Нижня група складається з копійок');
INSERT INTO `lang_definitions` VALUES (188201, 10984, 30, 'Стовпець Категорія буде користувальницької верхньої групою і буде виділений рожевим кольором');
INSERT INTO `lang_definitions` VALUES (188202, 10985, 30, 'У стовпці Категорія буде написано Порядок вказує на те що це порядок');
INSERT INTO `lang_definitions` VALUES (188203, 10986, 30, 'Категорія буде Результатом');
INSERT INTO `lang_definitions` VALUES (188204, 10987, 30, 'CDA-це простий текстовий документ, який кодується за допомогою розширюваної мови розмітки (XML) і містить заголовок і тіло');
INSERT INTO `lang_definitions` VALUES (188205, 10988, 30, 'Сертифікат центру сертифікації');
INSERT INTO `lang_definitions` VALUES (188206, 10989, 30, 'Стовпець заряду буде порожнім');
INSERT INTO `lang_definitions` VALUES (188207, 10990, 30, 'Плата буде являти собою фактичну суму, що стягується за кожен рядок');
INSERT INTO `lang_definitions` VALUES (188208, 10991, 30, 'Позовна справа:');
INSERT INTO `lang_definitions` VALUES (188209, 10992, 30, 'Форма CMS 1500 має 33 коробки і розділена на дві секції');
INSERT INTO `lang_definitions` VALUES (188210, 10993, 30, 'У стовпці Код повинен бути вказаний 905-ідентифікаційний код конкретного постачальника, введений раніше');
INSERT INTO `lang_definitions` VALUES (188211, 10994, 30, 'Стовпець Код буде порожнім, так як елементи, перераховані як група, не використовуються в фактичному звіті про результати і, отже, не мають чіткого кодового номера');
INSERT INTO `lang_definitions` VALUES (188212, 10995, 30, 'Код буде R905, що ідентифікує значення коду, яке було введено для дискретного результату');
INSERT INTO `lang_definitions` VALUES (188213, 10996, 30, 'Введений вами код був недійсний');
INSERT INTO `lang_definitions` VALUES (188214, 10997, 30, 'Сумісний пакет staged us Extension SNOMED вже встановлений.');
INSERT INTO `lang_definitions` VALUES (188215, 10998, 30, 'Комірка контактів містить різні біти контактної інформації, такі як номери телефонів, електронна пошта і т. Д');
INSERT INTO `lang_definitions` VALUES (188216, 10999, 30, 'Документ безперервності догляду (CCD) і запис безперервності догляду (CCR) були обрані в якості прийнятних форматів для вилучення інформації для резюме клінічної допомоги в рамках етапу 1 осмисленого використання');
INSERT INTO `lang_definitions` VALUES (188217, 11000, 30, 'Безперервність запису медичної допомоги (CCR) була розроблена спільно ASTM International - організацією, яка бере участь у розробці та наданні добровільного консенсусу, Массачусетським медичним товариством (MMS), товариством управління медичною інформацією та системами охорони здоров\'я (HIMSS), Американською академією сімейних лікарів (AAFP) та Американською академією педіатрії.');
INSERT INTO `lang_definitions` VALUES (188218, 11001, 30, 'Безперервність медичного запису ( CCR) - це клінічний запис поточного та історичного стану здоров\'я пацієнта');
INSERT INTO `lang_definitions` VALUES (188219, 11002, 30, 'Основний набір даних складається з');
INSERT INTO `lang_definitions` VALUES (188220, 11003, 30, 'Відповідний закритий ключ');
INSERT INTO `lang_definitions` VALUES (188221, 11004, 30, 'Створений звіт може містити як багато, так і мало інформації в залежності від потреби');
INSERT INTO `lang_definitions` VALUES (188222, 11005, 30, 'Поточний метод аутентифікації для увійшов в розділ користувача тепер буде містити активовані методи');
INSERT INTO `lang_definitions` VALUES (188223, 11006, 30, 'Поточний метод автентифікації містить список всіх активних методів');
INSERT INTO `lang_definitions` VALUES (188224, 11007, 30, 'Можна використовувати custmomized fee Sheet. Якщо і коли ви зіткнетеся з кодом, якого немає в призначеному для користувача розділі \"Вибір кодів\", ви завжди можете скористатися розділом\"пошук додаткових кодів\".');
INSERT INTO `lang_definitions` VALUES (188225, 11008, 30, 'Рівень користувацьких вибраних елементів повинен бути прямим нащадком або дочірнім елементом відповідної Користувацької групи обраних');
INSERT INTO `lang_definitions` VALUES (188226, 11009, 30, 'Користувацька угруповання також дозволить вам згрупувати дві розпізнані панелі тестів у групу і таким чином упорядкувати їх разом, наприклад, спеціальна група Preop Labs може містити дві панелі, CBC і Renal Panel');
INSERT INTO `lang_definitions` VALUES (188227, 11010, 30, 'Приладова панель є центральним місцем для зручного доступу до медичної карти пацієнта');
INSERT INTO `lang_definitions` VALUES (188228, 11011, 30, 'Сторінка панелі моніторингу розділена на три розділи');
INSERT INTO `lang_definitions` VALUES (188229, 11012, 30, 'Тест цілісності даних для цієї форми не пройшов');
INSERT INTO `lang_definitions` VALUES (188230, 11013, 30, 'У розділі даних на сторінці панелі моніторингу перераховані всі відповідні елементи, пов\'язані з пацієнтом');
INSERT INTO `lang_definitions` VALUES (188231, 11014, 30, 'Датоване нагадування почне з\'являтися за 5 днів до дати нагадування в розділі датовані нагадування');
INSERT INTO `lang_definitions` VALUES (188232, 11015, 30, 'Тип коду за замовчуванням для пошуку в відомості зборів.');
INSERT INTO `lang_definitions` VALUES (188233, 11016, 30, 'Відомість зборів за замовчуванням може бути змінена і налаштована таким чином, щоб зробити її більш корисною.');
INSERT INTO `lang_definitions` VALUES (188234, 11017, 30, 'Аркуш збору за замовчуванням розділений на кілька розділів і призначений для заповнення зверху вниз за допомогою кнопки Зберегти в самому кінці.');
INSERT INTO `lang_definitions` VALUES (188235, 11018, 30, 'Форму за замовчуванням можна налаштувати, відредагувавши її в розділі Адміністрування > макети');
INSERT INTO `lang_definitions` VALUES (188236, 11019, 30, 'За замовчуванням є дві кнопки, які встановлені для\" Нового пацієнта \"і\" встановленого \" пацієнта');
INSERT INTO `lang_definitions` VALUES (188237, 11020, 30, 'Установка за замовчуванням має шість таких груп-Бухгалтерія, адміністратори, клініцисти, Аварійний вхід, Фронт-офіс і лікарі.');
INSERT INTO `lang_definitions` VALUES (188238, 11021, 30, 'Установка за замовчуванням містить наступні елементи');
INSERT INTO `lang_definitions` VALUES (188239, 11022, 30, 'Установка за замовчуванням перераховує 5 типів проблем, які можуть бути задокументовані');
INSERT INTO `lang_definitions` VALUES (188240, 11023, 30, 'Установка за замовчуванням не буде робити телефонний дзвінок автоматично');
INSERT INTO `lang_definitions` VALUES (188241, 11024, 30, 'За замовчуванням використовується \"Стандарт\", який зазвичай використовується для відображення ставок, що стягуються при виставленні страхових рахунків. При оплаті кредитною карткою та готівкою може стягуватися різна сума');
INSERT INTO `lang_definitions` VALUES (188242, 11025, 30, 'Значення за замовчуванням-нормальне, тобто воно видно всім. Вибір High за замовчуванням обмежить його доступ до користувачів, що належать до груп лікарів і адміністраторів');
INSERT INTO `lang_definitions` VALUES (188243, 11026, 30, 'Тип проблеми за замовчуванням встановлений в Problem');
INSERT INTO `lang_definitions` VALUES (188244, 11027, 30, 'Центр обміну повідомленнями за замовчуванням розділений на три розділи-повідомлення, нагадування та нагадування');
INSERT INTO `lang_definitions` VALUES (188245, 11028, 30, 'Можна задати значення за замовчуванням для постачальників рендеринга');
INSERT INTO `lang_definitions` VALUES (188246, 11029, 30, 'код відмови такий');
INSERT INTO `lang_definitions` VALUES (188247, 11030, 30, 'код групи відмови');
INSERT INTO `lang_definitions` VALUES (188248, 11031, 30, 'У стовпці опис відображається введене короткий опис, тести з хімії сироватки');
INSERT INTO `lang_definitions` VALUES (188249, 11032, 30, 'У стовпці Опис буде відображено значення опису, введене раніше');
INSERT INTO `lang_definitions` VALUES (188250, 11033, 30, 'В описі має бути написано Результат сечової кислоти в сироватці крові');
INSERT INTO `lang_definitions` VALUES (188251, 11034, 30, 'В описі буде детально описаний тип оплати або коригування - Готівка, Чек, Електронні і т. Д');
INSERT INTO `lang_definitions` VALUES (188252, 11035, 30, 'Форма призначення була закрита');
INSERT INTO `lang_definitions` VALUES (188253, 11036, 30, 'Форма призначення була закрита.');
INSERT INTO `lang_definitions` VALUES (188254, 11037, 30, 'Форма призначення була закрита; я не можу діяти за вашим вибором.');
INSERT INTO `lang_definitions` VALUES (188255, 11038, 30, 'Різниця між ними полягає в тому, що для групи тестів, які впорядковані разом, окремі тести представлені тільки дискретним результатом, і ці тести не можуть бути впорядковані окремо, якщо вони також не були налаштовані як окремі тести');
INSERT INTO `lang_definitions` VALUES (188256, 11039, 30, 'Дискретний рівень результатів повинен бути прямим нащадком або дочірнім рівнем порядку процедур для правильного відображення результатів');
INSERT INTO `lang_definitions` VALUES (188257, 11040, 30, 'Дискретні результати для кожної панелі містять назви окремих тестів для зберігання значень повернутих результатів-WBC, гемоглобін, тромбоцити, натрій, калій тощо.');
INSERT INTO `lang_definitions` VALUES (188258, 11041, 30, 'Розмір вікна відображення можна змінити, клацнувши і перетягнувши його в правий нижній кут');
INSERT INTO `lang_definitions` VALUES (188259, 11042, 30, 'Опція \"кожна зустріч\" дозволить провести нову зустріч незалежно від відвідування в той же день.');
INSERT INTO `lang_definitions` VALUES (188260, 11043, 30, 'Кнопка попереднього перегляду зустрічі корисна для відображення форм макета типу зустрічі, як це видно при використанні форми в зустрічі. Зверніть увагу, що ця функція корисна тільки для відображення форм зустрічей і не буде відображати системні форми, такі як Демографія');
INSERT INTO `lang_definitions` VALUES (188261, 11044, 30, 'У розділі зустрічі буде відображатися дата зустрічі, а також пред\'явлена скарга');
INSERT INTO `lang_definitions` VALUES (188262, 11045, 30, 'Кінцевим результатом став заплутаний набір документів, що містять неоднозначну та / або суперечливу інформацію');
INSERT INTO `lang_definitions` VALUES (188263, 11046, 30, 'У режимі Додавання відкриється спливаюче вікно Ввести відомості');
INSERT INTO `lang_definitions` VALUES (188264, 11047, 30, 'З\'явиться спливаюче вікно введіть відомості про постачальника');
INSERT INTO `lang_definitions` VALUES (188265, 11048, 30, 'Вся колекція ACOS формує Список управління доступом (ACL).');
INSERT INTO `lang_definitions` VALUES (188266, 11049, 30, 'Сутність для користувацького вибраного елемента-це сутність, обрана для користувацької групи обраних, і вона не може бути змінена');
INSERT INTO `lang_definitions` VALUES (188267, 11050, 30, 'Суб\'єкт, який виконує цю процедуру');
INSERT INTO `lang_definitions` VALUES (188268, 11051, 30, 'Записи містять дані, що використовуються для подальшої комп\'ютерної обробки');
INSERT INTO `lang_definitions` VALUES (188269, 11052, 30, 'Записи, виділені жовтим кольором, можна замовити як тест або процедуру, а записи, виділені рожевим кольором, можна замовити як призначену для користувача групу');
INSERT INTO `lang_definitions` VALUES (188270, 11053, 30, 'EP, відповідна лікарня або CAH, який приймає пацієнта з іншої установи або постачальника медичної допомоги або вважає, що зустріч має відношення до справи, повинні виконати звірку ліків.');
INSERT INTO `lang_definitions` VALUES (188271, 11054, 30, 'EP, відповідна лікарня або CAH, які переводять свого пацієнта в іншу установу по догляду або постачальника послуг по догляду або направляють свого пацієнта до іншого постачальника послуг по догляду, повинні надати зведений запис про догляд для кожного переходу по догляду або направлення (міра а).');
INSERT INTO `lang_definitions` VALUES (188272, 11055, 30, 'EP, відповідна лікарня або CAH, які переводять свого пацієнта в іншу установу по догляду або постачальника послуг по догляду або направляють свого пацієнта до іншого постачальника послуг по догляду, повинні надати зведений запис про догляд для кожного переходу по догляду або направлення (міра B).');
INSERT INTO `lang_definitions` VALUES (188273, 11056, 30, 'EP, відповідна лікарня або CAH, які переводять свого пацієнта в іншу установу по догляду або постачальника послуг по догляду або направляють свого пацієнта до іншого постачальника послуг по догляду, повинні надати зведений запис про догляд для кожного переходу по догляду або направлення.');
INSERT INTO `lang_definitions` VALUES (188274, 11057, 30, 'Захід (и) було схвалено.');
INSERT INTO `lang_definitions` VALUES (188275, 11058, 30, 'Подія (події) були приховані.');
INSERT INTO `lang_definitions` VALUES (188276, 11059, 30, 'Експортовані дані відображаються в текстовій області нижче. Ви можете скопіювати та вставити це в електронну пошту або в будь-яке інше бажане місце призначення.');
INSERT INTO `lang_definitions` VALUES (188277, 11060, 30, 'Експортовані дані відображаються в текстовій області нижче. Ви можете скопіювати і вставити це в електронний лист або в будь-яке інше бажане місце призначення (або) завантажити за посиланням нижче.');
INSERT INTO `lang_definitions` VALUES (188278, 11061, 30, 'Експортовані дані відображаються в текстовій області нижче. Ви можете скопіювати та вставити це в електронну пошту або в будь-яке інше бажане місце призначення.');
INSERT INTO `lang_definitions` VALUES (188279, 11062, 30, 'Експортовані дані відображаються в текстовій області нижче. Ви можете скопіювати та вставити це в електронну пошту або в будь-яке інше бажане місце призначення.{{ПОЗНАЧКА ДЛЯ ВИДАЛЕННЯ ПІД ЧАС НАСТУПНОЇ ЗБІРКИ ПЕРЕКЛАДУ}}');
INSERT INTO `lang_definitions` VALUES (188280, 11063, 30, 'Особливості установки з підтримкою MedEx описані в цьому відео');
INSERT INTO `lang_definitions` VALUES (188281, 11064, 30, 'Файл не може бути згенерований знову. Ви хочете продовжити?');
INSERT INTO `lang_definitions` VALUES (188282, 11065, 30, 'Файл не вдалося зберегти в CouchDB.');
INSERT INTO `lang_definitions` VALUES (188283, 11066, 30, 'Файл не може бути успішно перейменований, ця помилка зазвичай пов\'язана з проблемами дозволів в системі зберігання.');
INSERT INTO `lang_definitions` VALUES (188284, 11067, 30, 'Файл не може бути успішно збережений, ця помилка зазвичай пов\'язана з проблемами дозволів в системі зберігання');
INSERT INTO `lang_definitions` VALUES (188285, 11068, 30, 'Розділ фільтра можна приховати або відкрити, натиснувши на стрілку в правому нижньому кутку');
INSERT INTO `lang_definitions` VALUES (188286, 11069, 30, 'Відфільтровані результати будуть показані в розділі нижче');
INSERT INTO `lang_definitions` VALUES (188287, 11070, 30, 'Таблиця finder згрупована за минулими процедурами, а потім за діагностичним кодом. Хоча можуть бути дублікати кодів dx, вони будуть згруповані з відповідною процедурою, що полегшує побудову списку діагнозів.');
INSERT INTO `lang_definitions` VALUES (188288, 11071, 30, 'Перший (\"цільовий\") графік-це той, який вважається найбільш повним і точним. Демографічні, історичні та страхові розділи для цього будуть збережені.');
INSERT INTO `lang_definitions` VALUES (188289, 11072, 30, 'Перший стовпець містить назву групи / категорії, яке буде відображатися на кнопці');
INSERT INTO `lang_definitions` VALUES (188290, 11073, 30, 'Перша колонка-це назва, яку Ви дали цьому запису, тобто Хімія сироватки. Вертикальна смуга передуватиме фактичному імені. Це вказує на те, що цей запис не має нащадків або дітей');
INSERT INTO `lang_definitions` VALUES (188291, 11074, 30, 'Перші чотири розділи присвячені структурованому створенню порядків процедур для полегшення впорядкування тестів і введення повернутих результатів вручну');
INSERT INTO `lang_definitions` VALUES (188292, 11075, 30, 'У першому рядку будуть показані дата і причина зустрічі, а також постачальник для цієї зустрічі');
INSERT INTO `lang_definitions` VALUES (188293, 11076, 30, 'Перший розділ дозволяє вам або зв\'язати це повідомлення з пацієнтом, якщо це необхідно.');
INSERT INTO `lang_definitions` VALUES (188294, 11077, 30, 'Перший сегмент у кожному повідомленні HL7 завжди є Заголовком повідомлення, Сегментом, який передає метадані повідомлення, наприклад, хто його відправив і коли. Заголовок повідомлення позначається в перших трьох буквах сегмента як MSH');
INSERT INTO `lang_definitions` VALUES (188295, 11078, 30, 'Першим кроком є реєстрація облікового запису production Direct messaging в EMR Direct шляхом реєстрації на їхньому веб-сайті');
INSERT INTO `lang_definitions` VALUES (188296, 11079, 30, 'Першим кроком є завантаження випуску SNOMED CT. Доступ до SNOMED CT надається IHTSDO та їх країнами-членами. Для отримання додаткової інформації див.');
INSERT INTO `lang_definitions` VALUES (188297, 11080, 30, 'Першим кроком є завантаження випуску набору значень. Доступ до набору значень надається компанією NLM. Необхідно завантажити тільки набір значень для відповідних фахівців, і він повинен бути завантажений у форматі XML зі стовпця Sorted By CMS ID. Для отримання більш детальної інформації див. посилання нижче');
INSERT INTO `lang_definitions` VALUES (188298, 11081, 30, 'Першим кроком є відкриття облікового запису на веб-сайті Єдиної системи медичної мови');
INSERT INTO `lang_definitions` VALUES (188299, 11082, 30, 'Перший крок-спланувати, що повинен відображати розділ \"Вибір кодів\" вашого платіжного листа');
INSERT INTO `lang_definitions` VALUES (188300, 11083, 30, 'Першим кроком є вибір типу транзакції');
INSERT INTO `lang_definitions` VALUES (188301, 11084, 30, 'Першим кроком буде створення запису верхнього рівня. Зробіть це, натиснувши на кнопку Додати верхній рівень');
INSERT INTO `lang_definitions` VALUES (188302, 11085, 30, 'Перша вкладка-це вкладка реферала, яка являє собою зроблену рефералку');
INSERT INTO `lang_definitions` VALUES (188303, 11086, 30, 'Перші два числа в першому і другому стовпці будуть використовуватися для визначення порядку сортування кнопок і списків, присутніх у спливаючому вікні');
INSERT INTO `lang_definitions` VALUES (188304, 11087, 30, 'Додано наступну подію календаря:');
INSERT INTO `lang_definitions` VALUES (188305, 11088, 30, 'Наступна календарна подія була змінена:');
INSERT INTO `lang_definitions` VALUES (188306, 11089, 30, 'Наступні категорії будуть видалені з Вашого списку категорій');
INSERT INTO `lang_definitions` VALUES (188307, 11090, 30, 'В даний час встановлено наступний випуск бази даних');
INSERT INTO `lang_definitions` VALUES (188308, 11091, 30, 'До цього прямого повідомлення були додані наступні документи:');
INSERT INTO `lang_definitions` VALUES (188309, 11092, 30, 'Наступний файл EDI не вдалося зберегти в архів');
INSERT INTO `lang_definitions` VALUES (188310, 11093, 30, 'Був завантажений наступний файл EDI');
INSERT INTO `lang_definitions` VALUES (188311, 11094, 30, 'Не вдалося відкрити наступне завантаження EDI-файлу');
INSERT INTO `lang_definitions` VALUES (188312, 11095, 30, 'Активується наступний користувач аварійного входу в систему:');
INSERT INTO `lang_definitions` VALUES (188313, 11096, 30, 'Відбулися наступні помилки');
INSERT INTO `lang_definitions` VALUES (188314, 11097, 30, 'Наступне поле має неприпустиме значення');
INSERT INTO `lang_definitions` VALUES (188315, 11098, 30, 'Наступні поля порожні.');
INSERT INTO `lang_definitions` VALUES (188316, 11099, 30, 'Обов\'язковими є наступні поля');
INSERT INTO `lang_definitions` VALUES (188317, 11100, 30, 'Для відправки запиту необхідно заповнити наступні поля.');
INSERT INTO `lang_definitions` VALUES (188318, 11101, 30, 'Для відправки запиту необхідно заповнити наступні поля.');
INSERT INTO `lang_definitions` VALUES (188319, 11102, 30, 'Підтримуються наступні міжнародні мови випуску Snomed');
INSERT INTO `lang_definitions` VALUES (188320, 11104, 30, 'Сталося наступне');
INSERT INTO `lang_definitions` VALUES (188321, 11105, 30, 'Наступні проблеми мають однакові діагностичні коди. Виниклі проблеми не будуть оновлюватися. Будь ласка, використовуйте замість цього інтерфейс encounter.');
INSERT INTO `lang_definitions` VALUES (188322, 11106, 30, 'Наступні кроки допоможуть налаштувати відомість зборів так, щоб вона імітувала стару паперову супербіллу зі списком кодів CPT4 і ICD, розташованих за категоріями');
INSERT INTO `lang_definitions` VALUES (188323, 11107, 30, 'Створена вами група (ARO) тепер буде відображатися в алфавітному порядку в розділі \"Групи і елементи управління доступом\".');
INSERT INTO `lang_definitions` VALUES (188324, 11108, 30, 'Заголовок визначає контекст клінічного документа в цілому');
INSERT INTO `lang_definitions` VALUES (188325, 11109, 30, 'Розділ заголовка покаже конкретну інформацію про пацієнта на більшості сторінок, пов\'язаних з медичною картою пацієнта');
INSERT INTO `lang_definitions` VALUES (188326, 11110, 30, 'Форма заяви про медичне страхування часто згадується за номером форми CMS 1500 (HCFA 1500)');
INSERT INTO `lang_definitions` VALUES (188327, 11111, 30, 'Файл довідки розділений на наступні розділи');
INSERT INTO `lang_definitions` VALUES (188328, 11112, 30, 'Файл довідки там допоможе вам в подальших кроках по налаштуванню лабораторних тестів');
INSERT INTO `lang_definitions` VALUES (188329, 11113, 30, 'Значок довідки дозволить вам отримати доступ до контекстної довідки для кожної з доступних сторінок');
INSERT INTO `lang_definitions` VALUES (188330, 11114, 30, 'Ім\'я хоста машини репозиторію аудиту ATNA.');
INSERT INTO `lang_definitions` VALUES (188331, 11115, 30, 'Ім\'я хоста або URI вашого сервера LDAP або Active Directory.');
INSERT INTO `lang_definitions` VALUES (188332, 11116, 30, 'Ідентифікаційний код повинен бути унікальним, щоб результати відображалися правильно, ви можете просто використовувати R905 як приклад');
INSERT INTO `lang_definitions` VALUES (188333, 11117, 30, 'Ідентифікаційний код повинен бути унікальним, якщо при відправці в зовнішню лабораторію необхідно ввести ідентифікаційний код, наданий постачальником. Ми введемо довільне унікальне значення-WWT01');
INSERT INTO `lang_definitions` VALUES (188334, 11118, 30, 'Ідентифікаційний код-це код конкретного постачальника, що ідентифікує дану процедуру або результат. Ви можете побачити приклади цього в паперових лабораторних бланках, які використовують лабораторії');
INSERT INTO `lang_definitions` VALUES (188335, 11119, 30, 'Ідентифікаційний код необхідний для правильного відображення і табулювання результатів');
INSERT INTO `lang_definitions` VALUES (188336, 11120, 30, 'Ідентифікаційний код R34392-1, довільне число, в даному випадку ідентифікаційний код, що передує R для позначення результату і наступний за 1 для позначення першого в послідовності, може бути будь-яким унікальним, який ви виберете');
INSERT INTO `lang_definitions` VALUES (188337, 11121, 30, 'Введена тут Інформація використовується для відображення короткого звіту про зустріч. Він також використовується для виставлення рахунків');
INSERT INTO `lang_definitions` VALUES (188338, 11122, 30, 'Інформація, введена в цю форму, буде використана для заповнення паперової претензії');
INSERT INTO `lang_definitions` VALUES (188339, 11123, 30, 'Інформація, представлена в новій формі зустрічі і відомості зборів в OpenEMR, використовується для формування паперової претензії, а також електронних претензій');
INSERT INTO `lang_definitions` VALUES (188340, 11124, 30, 'Початкові зусилля призвели до створення дублюючих та суперечливих посібників з впровадження (IGS), опублікованих різними організаціями зі стандартизації');
INSERT INTO `lang_definitions` VALUES (188341, 11125, 30, 'Початковий екран дозволяє вибрати метод, запропонувавши вам ці два варіанти.');
INSERT INTO `lang_definitions` VALUES (188342, 11126, 30, 'Початкове вікно-це сторінка пошуку рахунку-фактури. Вгорі ви можете ввести джерело (наприклад, номер чека), дату оплати і суму чека. Причина для джерела та дати оплати полягає в тому, що вам не потрібно вводити їх знову і знову для кожної претензії. Сума, яку Ви вводите, буде зменшена для кожного рахунку, який є частиною платежу, і, сподіваюся, закінчиться на нулі, коли ви закінчите.');
INSERT INTO `lang_definitions` VALUES (188343, 11127, 30, 'Вхідними даними повинен бути CSV-файл з 3 стовпцями: ідентифікатор макета, тип коду і код.');
INSERT INTO `lang_definitions` VALUES (188344, 11128, 30, 'Необхідно створити інсталяційний каталог.');
INSERT INTO `lang_definitions` VALUES (188345, 11129, 30, 'Встановлена міжнародна версія SNOMED несумісна з пакетом staged us Extension SNOMED.');
INSERT INTO `lang_definitions` VALUES (188346, 11130, 30, 'Встановлена міжнародна версія SNOMED застаріла і не сумісна з файлом staged US Extension SNOMED.');
INSERT INTO `lang_definitions` VALUES (188347, 11131, 30, 'Встановлена версія і проміжні файли однакові.');
INSERT INTO `lang_definitions` VALUES (188348, 11132, 30, 'Встановлена версія є більш пізньою версією, ніж проміжні файли.');
INSERT INTO `lang_definitions` VALUES (188349, 11133, 30, 'Посібник із заповнення форми CMS 1500 можна знайти тут');
INSERT INTO `lang_definitions` VALUES (188350, 11134, 30, 'IP-адреса Вашого контролера (контролерів) домену.');
INSERT INTO `lang_definitions` VALUES (188351, 11135, 30, 'Питання можуть бути введені одним з двох способів');
INSERT INTO `lang_definitions` VALUES (188352, 11136, 30, 'У розділі Питання будуть відображатися всі питання, введені для пацієнта, а також тип проблеми, її назва і опис');
INSERT INTO `lang_definitions` VALUES (188353, 11137, 30, 'Елементи, перераховані в стовпці \"Активний\", визначають привілеї цієї групи (ARO) і складають список контролю доступу цієї групи (ACL).');
INSERT INTO `lang_definitions` VALUES (188354, 11138, 30, 'Елементи, які мають зірочки після них, є обов\'язковими');
INSERT INTO `lang_definitions` VALUES (188355, 11140, 30, 'Мітка, яка з\'являється у користувача на формі');
INSERT INTO `lang_definitions` VALUES (188356, 11141, 30, 'Остання клітина на лінії в зіткненні');
INSERT INTO `lang_definitions` VALUES (188357, 11142, 30, 'В останньому рядку цього блоку зустрічей будуть наведені загальні суми зустрічей за витратами, платежами, коригуваннями і Балансу');
INSERT INTO `lang_definitions` VALUES (188358, 11143, 30, 'Останній розділ присвячений електронним замовленням');
INSERT INTO `lang_definitions` VALUES (188359, 11144, 30, 'Дата останнього відвідування буде заповнена автоматично');
INSERT INTO `lang_definitions` VALUES (188360, 11145, 30, 'Остання версія Fhir-Fast Healthcare Interoperability Resources-являє собою стандартну структуру наступного покоління, створену компанією HL7. Це набирає популярність, але ще не було широко реалізовано');
INSERT INTO `lang_definitions` VALUES (188361, 11146, 30, 'Застарілий пошук коду як і раніше доступний для кодів, не знайдених в цьому пошуковику або редагуванні списку кодів.');
INSERT INTO `lang_definitions` VALUES (188362, 11147, 30, 'Довжина не повинна перевищувати наступної кількості символів');
INSERT INTO `lang_definitions` VALUES (188363, 11148, 30, 'Запис журналу з наступним ідентифікатором був видалений');
INSERT INTO `lang_definitions` VALUES (188364, 11150, 30, 'У таблиці журналу буде показано список як повідомлень, так і датованих нагадувань, якщо такі є');
INSERT INTO `lang_definitions` VALUES (188365, 11151, 30, 'Код LOINC для сироваткової сечової кислоти-3084-1, LOINC відноситься до неї як до урату в сироватці або плазмі');
INSERT INTO `lang_definitions` VALUES (188366, 11152, 30, 'Злиття не буде виконуватися, якщо SSN і DOB для двох діаграм не будуть ідентичні. ДОБс не може бути порожнім.');
INSERT INTO `lang_definitions` VALUES (188367, 11153, 30, 'Повідомлення не могло бути відправлено в цей час.');
INSERT INTO `lang_definitions` VALUES (188368, 11154, 30, 'Статус повідомлення буде новим, так як це нове повідомлення, яке створюється');
INSERT INTO `lang_definitions` VALUES (188369, 11155, 30, 'Повідомлення, які були відправлені користувачем в цей день, будуть відображені в таблиці нижче');
INSERT INTO `lang_definitions` VALUES (188370, 11156, 30, 'Центр обміну повідомленнями зручно об\'єднує можливості зв\'язку в одному місці');
INSERT INTO `lang_definitions` VALUES (188371, 11157, 30, 'Центр обміну повідомленнями відкриється з активованою вкладкою повідомлення і відобразить повідомлення увійшов користувача як зазначено в заголовку Мої повідомлення');
INSERT INTO `lang_definitions` VALUES (188372, 11158, 30, 'Мінімальна інформація, необхідна для створення нової зустрічі, - це вибір категорії відвідування');
INSERT INTO `lang_definitions` VALUES (188373, 11159, 30, 'Форма різні варіанти виставлення рахунків для HCFA-1500 використовується для надання додаткової інформації за індивідуальною претензії');
INSERT INTO `lang_definitions` VALUES (188374, 11160, 30, 'Найбільш поширений метод називається 2-факторною авторизацією або 2FA');
INSERT INTO `lang_definitions` VALUES (188375, 11161, 30, 'Найважливіше питання, яке необхідно вирішити, - це те, з ким ви намагаєтеся встановити контакт і що має відбутися в кінці. Більшість великих лабораторій не матимуть справу з окремими практиками, в таких випадках Сторонній постачальник буде виступати посередником, який буде відповідати за встановлення зв\'язку між практикою і лабораторією через їх (посередника) інтерфейс');
INSERT INTO `lang_definitions` VALUES (188376, 11162, 30, 'Найпопулярнішим виробником ключів безпеки є Yubico, який пропонує звичайні версії USB, а також ті, які зроблені для пристроїв, що вимагають підключення USB-C, таких як нові системи Mac OS від Apple');
INSERT INTO `lang_definitions` VALUES (188377, 11163, 30, 'Найпопулярніше рішення для управління електронними медичними записами та медичною практикою з відкритим вихідним кодом.');
INSERT INTO `lang_definitions` VALUES (188378, 11164, 30, 'Клітинка імені містить ім\'я, дату народження, ідентифікатор пацієнта і дату останнього відвідування');
INSERT INTO `lang_definitions` VALUES (188379, 11165, 30, 'Розповідний блок містить інформацію, яка відображається у вигляді тексту, що читається');
INSERT INTO `lang_definitions` VALUES (188380, 11166, 30, 'Національний єдиний комітет з претензій (NUCC) відповідає за ведення форми претензії 1500');
INSERT INTO `lang_definitions` VALUES (188381, 11167, 30, 'Навігаційна панель дозволяє швидко переміщатися по різних частинах медичної карти пацієнта');
INSERT INTO `lang_definitions` VALUES (188382, 11168, 30, 'Нова категорія буде підкатегорією');
INSERT INTO `lang_definitions` VALUES (188383, 11169, 30, 'Новий список');
INSERT INTO `lang_definitions` VALUES (188384, 11170, 30, 'Новий пароль не може збігатися з поточним паролем.');
INSERT INTO `lang_definitions` VALUES (188385, 11171, 30, 'Нові поля пароля не збігаються.');
INSERT INTO `lang_definitions` VALUES (188386, 11172, 30, 'Новий пароль збігається з поточним. Натисніть кнопку Ок, щоб прийняти його в будь-якому випадку.');
INSERT INTO `lang_definitions` VALUES (188387, 11173, 30, 'Ім\'я партнера NewCrop eRx, Ім\'я NewCrop eRx і пароль NewCrop eRx будуть надані постачальником');
INSERT INTO `lang_definitions` VALUES (188388, 11174, 30, 'Наступна коробка-Це місце тіла, яке не має відношення до аналізу крові, але може бути більш корисним, скажімо, для відстеження ін\'єкцій або замовлення рентгенівських променів');
INSERT INTO `lang_definitions` VALUES (188389, 11175, 30, 'У наступних кількох рядках будуть перераховані всі коди E / M і CPT, які були виставлені на рахунок, по одному рядку на код');
INSERT INTO `lang_definitions` VALUES (188390, 11176, 30, 'Наступна група складається з кодів МКБ');
INSERT INTO `lang_definitions` VALUES (188391, 11177, 30, 'Наступні три комірки-це комірки дії, які дозволяють виконувати деякі дії по згадуванню');
INSERT INTO `lang_definitions` VALUES (188392, 11178, 30, 'Наступні два поля позначають ідентифікаційний код і стандартний код дуже важливі');
INSERT INTO `lang_definitions` VALUES (188393, 11179, 30, 'Комірка Примітки дозволяє додати замітку до дії, яку ви виконуєте в 3 осередках дії, або просто замітку без будь-якого зв\'язку з цією дією');
INSERT INTO `lang_definitions` VALUES (188394, 11180, 30, 'Кількість майбутніх призначень для відображення у виписці.');
INSERT INTO `lang_definitions` VALUES (188395, 11181, 30, 'Кількість проміжних файлів невірно. Помістіть тільки той файл, який ви хочете встановити / оновити.');
INSERT INTO `lang_definitions` VALUES (188396, 11182, 30, 'Кількість проміжних файлів невірно. Розміщуйте тільки ті файли, які ви хочете встановити/оновити.');
INSERT INTO `lang_definitions` VALUES (188397, 11183, 30, 'Офіс: телефонна комірка дозволяє вказати, що був зроблений телефонний дзвінок');
INSERT INTO `lang_definitions` VALUES (188398, 11184, 30, 'Опція span Whole Row корисна при використанні статичного тексту, дозволяючи тексту переносити і охоплювати весь рядок незалежно від налаштувань стовпця. Іншим варіантом використання може бути створення порожнього рядка як роздільника або додавання додаткової опції Додати нижню межу для створення розриву рядка.Тут корисний тільки нижній прикордонний ряд.');
INSERT INTO `lang_definitions` VALUES (188399, 11185, 30, 'Параметри контуру і кордону або обгорнуть рядок тонкою рамкою, або додадуть рамку в нижню частину елемента.');
INSERT INTO `lang_definitions` VALUES (188400, 11186, 30, 'Порядок, в якому з\'являється Категорія, Процедура або Результат');
INSERT INTO `lang_definitions` VALUES (188401, 11187, 30, 'Решта 4 типи транзакцій є простими типами транзакцій - запит пацієнта , запит лікаря, Юридичний і білінг');
INSERT INTO `lang_definitions` VALUES (188402, 11188, 30, 'Інші сегменти містять додаткову інформацію в строго структурованому вигляді');
INSERT INTO `lang_definitions` VALUES (188403, 11189, 30, 'Сторінка буде перенаправлена на демографію. Ви можете відредагувати поле країна і знову перейти до NewCrop.');
INSERT INTO `lang_definitions` VALUES (188404, 11190, 30, 'Запитана вами сторінка не була знайдена. Будь ласка, переконайтеся, що ви правильно ввели URL-адресу.');
INSERT INTO `lang_definitions` VALUES (188405, 11191, 30, 'Частини програми, до яких можна керувати доступом, називаються Об\'єктами управління доступом (ACOs).');
INSERT INTO `lang_definitions` VALUES (188406, 11192, 30, 'Пароль повинен складатися не менше ніж з восьми символів.');
INSERT INTO `lang_definitions` VALUES (188407, 11193, 30, 'Введений вами пароль недійсний');
INSERT INTO `lang_definitions` VALUES (188408, 11194, 30, 'Минулий очний анамнез (POH) і минулий медичний анамнез (PMH) негативні.');
INSERT INTO `lang_definitions` VALUES (188409, 11195, 30, 'Пацієнт вже зареєстрований в групі');
INSERT INTO `lang_definitions` VALUES (188410, 11196, 30, 'Запит на запис пацієнта був записаний.');
INSERT INTO `lang_definitions` VALUES (188411, 11197, 30, 'Пацієнту були відправлені нагадування');
INSERT INTO `lang_definitions` VALUES (188412, 11198, 30, 'Нагадування про пацієнтів були оновлені');
INSERT INTO `lang_definitions` VALUES (188413, 11199, 30, 'Пацієнт не був зареєстрований при відправці цієї форми');
INSERT INTO `lang_definitions` VALUES (188414, 11200, 30, 'Пацієнту доведеться змінити свої облікові дані при першому вході в систему');
INSERT INTO `lang_definitions` VALUES (188415, 11201, 30, 'Права пацієнтів');
INSERT INTO `lang_definitions` VALUES (188416, 11202, 30, 'Платіж, коригування і Баланс будуть порожніми, так як ці рядки відображають тільки вироблені витрати');
INSERT INTO `lang_definitions` VALUES (188417, 11203, 30, 'Рознесені платежі не можуть йти нижче цієї дати.Це гарантує, що після прийняття остаточного звіту ніхто не буде публікувати дані за попередні дати.');
INSERT INTO `lang_definitions` VALUES (188418, 11204, 30, 'Заголовок спливаючої форми тепер буде читати: введіть відомості для окремого користувацького обраного елемента');
INSERT INTO `lang_definitions` VALUES (188419, 11205, 30, 'На порталі є дані по цьому пацієнту і форма. Завантажити його зараз?');
INSERT INTO `lang_definitions` VALUES (188420, 11206, 30, 'Однак попереднє повідомлення можна переглянути, натиснувши на кнопку Переглянути журнал');
INSERT INTO `lang_definitions` VALUES (188421, 11207, 30, 'На сторінці порядок процедур перераховані наступні типи процедур');
INSERT INTO `lang_definitions` VALUES (188422, 11208, 30, 'Запит процедури повинен бути структурований ієрархічним чином і йому повинен бути присвоєний унікальний ідентифікаційний код, який потім буде використовуватися для відстеження і табулювання результату');
INSERT INTO `lang_definitions` VALUES (188423, 11209, 30, 'Модуль процедури використовується для розміщення та перевірки замовлень');
INSERT INTO `lang_definitions` VALUES (188424, 11210, 30, 'Процес пересилання повідомлення дуже схожий на процес створення нового повідомлення');
INSERT INTO `lang_definitions` VALUES (188425, 11211, 30, 'У комірці Прогрес перераховані всі дії разом з будь-якими пов\'язаними нотатками, якщо такі є');
INSERT INTO `lang_definitions` VALUES (188426, 11212, 30, 'Офіс провайдерів був повідомлений. Дякую.');
INSERT INTO `lang_definitions` VALUES (188427, 11213, 30, 'Відкритий ключ доступу для безпечної токенізації авторизації кредитної або дебетової картки. Відповідність вимогам PCI');
INSERT INTO `lang_definitions` VALUES (188428, 11214, 30, 'QR-код також містить ім\'я користувача і повинен бути записаний Користувачем на свій мобільний пристрій за допомогою програми-аутентифікатора');
INSERT INTO `lang_definitions` VALUES (188429, 11215, 30, 'Випуск каналу необроблених даних може бути отриманий з');
INSERT INTO `lang_definitions` VALUES (188430, 11216, 30, 'Комірка відкликання містить дату відкликання і причину відкликання');
INSERT INTO `lang_definitions` VALUES (188431, 11217, 30, 'Вкладка Recalls має дві кнопки New Recall і Recall Board');
INSERT INTO `lang_definitions` VALUES (188432, 11218, 30, 'Рівень рекомендацій є необов\'язковим');
INSERT INTO `lang_definitions` VALUES (188433, 11219, 30, 'Інша наведена нижче інформація застосовується тільки в тому випадку, якщо ви проводите облік вручну або виконуєте ручні виправлення.');
INSERT INTO `lang_definitions` VALUES (188434, 11220, 30, 'Нагадування на поточний день матиме Помаранчевий знак оклику');
INSERT INTO `lang_definitions` VALUES (188435, 11221, 30, 'Нагадування, які пройшли термін виконання, матимуть червоний значок оклику трикутника');
INSERT INTO `lang_definitions` VALUES (188436, 11222, 30, 'Запитаний документ відсутній в очікуваному місці файлової системи або немає достатніх дозволів для доступу до нього');
INSERT INTO `lang_definitions` VALUES (188437, 11223, 30, 'Запитаний документ відсутній в очікуваному місці файлової системи або немає достатніх дозволів для доступу до нього.');
INSERT INTO `lang_definitions` VALUES (188438, 11224, 30, 'Інші можуть бути залишені порожніми, якщо це краще');
INSERT INTO `lang_definitions` VALUES (188439, 11225, 30, 'Інші поля, пов\'язані з сервісом NewCrop eRx, можна залишити в значеннях за замовчуванням');
INSERT INTO `lang_definitions` VALUES (188440, 11226, 30, 'Рядок результатів буде починатися з назви сироватки сечової кислоти, перед якою буде стояти вертикальна смуга, що вказує на відсутність спадкоємців або дітей');
INSERT INTO `lang_definitions` VALUES (188441, 11227, 30, 'Результати не можуть бути завантажені');
INSERT INTO `lang_definitions` VALUES (188442, 11228, 30, 'Результати, Дискретний результат, будуть плодом на цій гілці, і ми створимо один такий Дискретний результат для кожного з компонентів тесту-натрію, калію,хлориду і вуглекислого газу');
INSERT INTO `lang_definitions` VALUES (188443, 11229, 30, 'Рядки, що містять коди CPT4, мають кілька полів, які необхідно заповнити, щоб забезпечити належне виставлення рахунків за претензіями');
INSERT INTO `lang_definitions` VALUES (188444, 11230, 30, 'Збережена медична проблема тепер буде вказана у вигляді одного рядка на сторінці основні проблеми в розділі Медичні проблеми');
INSERT INTO `lang_definitions` VALUES (188445, 11232, 30, 'Час оновлення екрану в секундах для екрану панелі управління потоком пацієнта.');
INSERT INTO `lang_definitions` VALUES (188446, 11233, 30, 'Поле пошуку не може бути порожнім. Будь ласка, введіть пошуковий запит');
INSERT INTO `lang_definitions` VALUES (188447, 11234, 30, 'Результати пошуку відображаються в розділі \"Результати пошуку\".');
INSERT INTO `lang_definitions` VALUES (188448, 11235, 30, 'На другому (\"вихідному\") графіку будуть відкинуті розділи \"демографія\", \"історія\"і \" страхування\". Інші його дані будуть об\'єднані в цільову діаграму.');
INSERT INTO `lang_definitions` VALUES (188449, 11236, 30, 'Другий стовпець містить параметри, які будуть відображатися при натисканні кнопки');
INSERT INTO `lang_definitions` VALUES (188450, 11237, 30, 'Друга колонка категорія і повинна говорити Верхня група щоб вказати її положення як верхнього елемента в цьому конкретному ієрархічному дереві яке ми будемо будувати');
INSERT INTO `lang_definitions` VALUES (188451, 11238, 30, 'Другий розділ дозволяє вам вибрати, кому ви хочете відправити повідомлення');
INSERT INTO `lang_definitions` VALUES (188452, 11239, 30, 'Друга вкладка, дещо двозначно названа Контррефералом, є місцем для документування отриманої відповіді на зроблене звернення');
INSERT INTO `lang_definitions` VALUES (188453, 11240, 30, 'Розділ з написом \"пошук рахунків-фактур\" - це те місце, де ви вводите свої параметри пошуку. Ви можете шукати за ім\'ям пацієнта, номером картки, номером зустрічі або датою обслуговування або будь-якої їх комбінації. Ви також можете вибрати, чи хочете ви бачити всі рахунки-фактури, відкриті рахунки-фактури або тільки ті рахунки, які повинні бути оплачені (пацієнтом). Натисніть кнопку \"Пошук\", щоб виконати пошук.');
INSERT INTO `lang_definitions` VALUES (188454, 11241, 30, 'Вибраний код буде додано в текстове поле кодування, а опис коду - в текстове поле Заголовка');
INSERT INTO `lang_definitions` VALUES (188455, 11242, 30, 'Вибрані коди потім з\'являться в розділі \"Вибрані коди відомості зборів і збори за поточну зустріч\".');
INSERT INTO `lang_definitions` VALUES (188456, 11243, 30, 'Вибір у цьому розділі буде використовуватися при нарахуванні плати за цю зустріч');
INSERT INTO `lang_definitions` VALUES (188457, 11244, 30, 'Послідовність-це порядок, в якому цей елемент верхнього порядку буде відображатися на сторінці, 1 для позначення першої групи верхнього рівня');
INSERT INTO `lang_definitions` VALUES (188458, 11245, 30, 'Адреса сервера матиме вигляд');
INSERT INTO `lang_definitions` VALUES (188459, 11246, 30, 'Налаштування лабораторних тестів буде детально описана, незначні зміни в цих кроках будуть необхідні для налаштування процедур в офісі та інших типів процедур');
INSERT INTO `lang_definitions` VALUES (188460, 11247, 30, 'Дещо неоднозначно названий Контрреферал-це простір, де може бути задокументована відповідь на зроблене звернення');
INSERT INTO `lang_definitions` VALUES (188461, 11248, 30, 'Стовпці джерело і Дата копіюються з першої сторінки, тому зазвичай вам не потрібно буде їх чіпати. Ви можете помістити суму платежу в стовпець Оплата, суму коригування в стовпець коригування або і те, і інше. Ви також можете натиснути кнопку \"W\" праворуч, щоб автоматично обчислити коригуюче значення, яке списує решту витрат для цієї позиції.');
INSERT INTO `lang_definitions` VALUES (188462, 11249, 30, 'Стовпці джерело і Дата копіюються з першої сторінки, тому зазвичай вам не потрібно буде їх чіпати. Ви можете помістити суму платежу в стовпець Оплата, суму коригування в стовпець коригування або і те, і інше. Ви також можете натиснути кнопку \" W \" праворуч, щоб автоматично обчислити коригуюче значення, яке списує решту витрат для цієї позиції.');
INSERT INTO `lang_definitions` VALUES (188463, 11250, 30, 'Тип зразка буде кров, цей список, що випадає також можна редагувати в міру необхідності');
INSERT INTO `lang_definitions` VALUES (188464, 11251, 30, 'Дати випуску проміжних файлів не всі відносяться до одного і того ж випуску.');
INSERT INTO `lang_definitions` VALUES (188465, 11252, 30, 'Проміжні версії файлів не всі відносяться до одного і того ж випуску.');
INSERT INTO `lang_definitions` VALUES (188466, 11253, 30, 'Поетапний Американський пакет розширення SNOMED не може бути встановлений до тих пір, поки не буде встановлений міжнародний пакет SNOMED.');
INSERT INTO `lang_definitions` VALUES (188467, 11254, 30, 'Стандартний код необов\'язковий при використанні локальної тобто практичної лабораторії але рекомендується при використанні зовнішньої лабораторії');
INSERT INTO `lang_definitions` VALUES (188468, 11255, 30, 'Стандартний код буде кодом LOINC при відправці в зовнішню лабораторію або може бути будь-яким унікальним номером. Ми введемо код LOINC для глюкози натщесерце 1558-6');
INSERT INTO `lang_definitions` VALUES (188469, 11256, 30, 'стан трьох хронічних / неактивних проблем');
INSERT INTO `lang_definitions` VALUES (188470, 11257, 30, 'У наступних рядках будуть вказані деталі отриманих платежів, здійснених Коригувань і належного залишку');
INSERT INTO `lang_definitions` VALUES (188471, 11258, 30, 'Суфікс рахунку.');
INSERT INTO `lang_definitions` VALUES (188472, 11259, 30, 'Система не дозволяє завантажувати файли розміром 0.');
INSERT INTO `lang_definitions` VALUES (188473, 11260, 30, 'Система не дозволяє завантажувати файли з типом вмісту MIME');
INSERT INTO `lang_definitions` VALUES (188474, 11261, 30, 'Система також призначена для аналізу вхідних повідомлень HL7 і розміщення результатів у відповідній карті пацієнта, в іншому випадку вона дасть вам можливість вручну пов\'язати її з картою пацієнта');
INSERT INTO `lang_definitions` VALUES (188475, 11262, 30, 'Система призначена як для розміщення замовлень в електронному вигляді, так і для отримання результатів в електронному вигляді');
INSERT INTO `lang_definitions` VALUES (188476, 11263, 30, 'Третій стовпець буде містити код CPT');
INSERT INTO `lang_definitions` VALUES (188477, 11264, 30, 'Значення стовпця рівня буде дорівнює 1, що вказує на те, що це елемент верхнього рівня');
INSERT INTO `lang_definitions` VALUES (188478, 11265, 30, 'Значення стовпця рівня буде дорівнює 3, що вказує на те, що це наступник або нащадок першого рядка над ним, що має значення 2');
INSERT INTO `lang_definitions` VALUES (188479, 11266, 30, 'Стовпець рівня буде дорівнює 2, що вказує на те, що це наступник або нащадок першого рядка над ним, що має значення 1');
INSERT INTO `lang_definitions` VALUES (188480, 11267, 30, 'Стовпець рівня буде дорівнює 1, вказуючи, що це верхня група');
INSERT INTO `lang_definitions` VALUES (188481, 11268, 30, 'Деталізація часу календаря і найменший інтервал у хвилинах для інтервалу зустрічі.');
INSERT INTO `lang_definitions` VALUES (188482, 11269, 30, 'Назва буде назвою нової групи (ARO), яку ви збираєтеся створити.');
INSERT INTO `lang_definitions` VALUES (188483, 11270, 30, 'Верхня група складається з зборів за зустріч-один ряд на заряд');
INSERT INTO `lang_definitions` VALUES (188484, 11271, 30, 'Верхня частина плати відкликання дозволяє налаштувати фільтри для відображення заданих даних');
INSERT INTO `lang_definitions` VALUES (188485, 11272, 30, 'Традиційний механізм використання логіна і пароля більше не вважається достатнім для запобігання несанкціонованого доступу користувача до додатка');
INSERT INTO `lang_definitions` VALUES (188486, 11275, 30, 'Перекладена мітка, яка з\'явиться на формі на поточній мові');
INSERT INTO `lang_definitions` VALUES (188487, 11276, 30, 'Перекладена назва, яка з\'явиться на поточній мові');
INSERT INTO `lang_definitions` VALUES (188488, 11277, 30, 'Переклад опису на поточну мову');
INSERT INTO `lang_definitions` VALUES (188489, 11278, 30, 'Таблиці перекладу синхронізовані.');
INSERT INTO `lang_definitions` VALUES (188490, 11279, 30, 'Тип цієї сутності');
INSERT INTO `lang_definitions` VALUES (188491, 11280, 30, 'Тип буде порожнім');
INSERT INTO `lang_definitions` VALUES (188492, 11281, 30, 'Тип буде Страховка або пацієнт');
INSERT INTO `lang_definitions` VALUES (188493, 11282, 30, 'Тип буде алергія');
INSERT INTO `lang_definitions` VALUES (188494, 11283, 30, 'Тип буде стоматологічні проблеми');
INSERT INTO `lang_definitions` VALUES (188495, 11284, 30, 'Тип буде медикаментозним');
