INSERT INTO `lang_definitions` VALUES (188498, 11287, 30, 'UB-04(CMS 1450) - це форма претензії, що використовується лікарнями, сестринськими установами, стаціонарами та іншими постачальниками медичних послуг');
INSERT INTO `lang_definitions` VALUES (188499, 11288, 30, 'Стовпець Одиниця виміру буде порожнім');
INSERT INTO `lang_definitions` VALUES (188500, 11289, 30, 'Одиниці виміру будуть рівні 1, так як кожен код виставляється тільки один раз за зустріч');
INSERT INTO `lang_definitions` VALUES (188501, 11290, 30, 'Майбутні нагадування мають зелений знак значок');
INSERT INTO `lang_definitions` VALUES (188502, 11291, 30, 'USB-пристрої взаємодіють з хост-комп\'ютером по протоколу human interface device( HID), по суті імітуючи клавіатуру');
INSERT INTO `lang_definitions` VALUES (188503, 11292, 30, 'USB-ключ повинен бути підключений до комп\'ютера, а потім зареєстрований в OpenEMR');
INSERT INTO `lang_definitions` VALUES (188504, 11293, 30, 'USB ключ приймає цей nonce наданий додатком після підтвердження контрольної суми і генерує закритий ключ використовуючи процес аналогічний тому який використовується в процесі реєстрації');
INSERT INTO `lang_definitions` VALUES (188505, 11294, 30, 'Фактичні привілеї користувача визначаються доступом до частин програми, тобто (ACO), який має кожна група (ARO).');
INSERT INTO `lang_definitions` VALUES (188506, 11295, 30, 'Поля імені користувача не збігаються.');
INSERT INTO `lang_definitions` VALUES (188507, 11296, 30, 'Ім\'я користувача - це ваша пряма адреса');
INSERT INTO `lang_definitions` VALUES (188508, 11297, 30, 'Значення у спадному списку можна відредагувати, виконавши дії, описані у файлі довідки процедури > постачальники');
INSERT INTO `lang_definitions` VALUES (188509, 11298, 30, 'Перераховані тут значення будуть відображатися в розкривних вікнах, які будуть використовуватися для обробки замовлень');
INSERT INTO `lang_definitions` VALUES (188510, 11299, 30, 'Код конкретного постачальника, який ідентифікує цю процедуру або результат');
INSERT INTO `lang_definitions` VALUES (188511, 11300, 30, 'Код конкретного постачальника, який ідентифікує цю процедуру або результат. Якщо жоден постачальник не вводить довільний унікальний номер, бажано 5-значний з нульовим заповненням, наприклад 00211');
INSERT INTO `lang_definitions` VALUES (188512, 11301, 30, 'Найпершим кроком буде установка кодів ICD. Перейдіть до розділу адміністрування > Інше > завантаження зовнішніх даних. Виберіть Набори кодів, які ви хочете встановити, і натисніть кнопку Встановити');
INSERT INTO `lang_definitions` VALUES (188513, 11302, 30, 'У самому останньому рядку цього звіту буде дана загальна сума витрат, платежів, Коригувань і Сальдо');
INSERT INTO `lang_definitions` VALUES (188514, 11303, 30, 'Обмін Weno добре інтегрований з OpenEMR і не заснований на підписці');
INSERT INTO `lang_definitions` VALUES (188515, 11304, 30, 'Файли X12, а також результуючі вихідні звіти HTML архівуються в підкаталозі\" era \" основного інсталяційного каталогу OpenEMR. Ви захочете час від часу звертатися до цих архівів. URL-адреса:');
INSERT INTO `lang_definitions` VALUES (188516, 11305, 30, 'Файли X12, а також результуючі вихідні звіти HTML архівуються в підкаталозі era основного інсталяційного каталогу OpenEMR. Ви захочете час від часу звертатися до цих архівів.');
INSERT INTO `lang_definitions` VALUES (188517, 11306, 30, 'Zip-файл буде містити наступні елементи');
INSERT INTO `lang_definitions` VALUES (188518, 11307, 30, 'Тема');
INSERT INTO `lang_definitions` VALUES (188519, 11308, 30, 'Тема макета вкладок (потрібно вийти з системи, а потім увійти в систему, щоб побачити цю нову настройку).');
INSERT INTO `lang_definitions` VALUES (188520, 11309, 30, 'Тема макета вкладок (потрібно вийти з системи, а потім увійти в систему, щоб побачити цю нову настройку). Зауважте, що це застосовується лише тоді, коли ви використовуєте загальну тему Light або Manila нижче.');
INSERT INTO `lang_definitions` VALUES (188521, 11310, 30, 'Потім передайте його ім\'я як значення елементу');
INSERT INTO `lang_definitions` VALUES (188522, 11311, 30, 'Потім натисніть миготливу кнопку на вашому ключі протягом 1 хвилини, щоб завершити реєстрацію');
