INSERT INTO `lang_definitions` VALUES (188529, 11318, 30, 'Зустріч терапевтичної групи');
INSERT INTO `lang_definitions` VALUES (188530, 11319, 30, 'Пошук терапевтичної групи');
INSERT INTO `lang_definitions` VALUES (188531, 11320, 30, 'Існує');
INSERT INTO `lang_definitions` VALUES (188532, 11321, 30, 'Існує 10 налаштувань, пов\'язаних з процедурами, включеними в стандартний випуск OpenEMR');
INSERT INTO `lang_definitions` VALUES (188533, 11322, 30, 'В основній категорії є 3 форми-Демографія, інформація про Користувача конкретного об\'єкта і історія, а також всі 5 форм в транзакціях, які можна редагувати');
INSERT INTO `lang_definitions` VALUES (188534, 11323, 30, 'В даний час рецептів немає');
INSERT INTO `lang_definitions` VALUES (188535, 11324, 30, 'Є помилки з вашою подачею. Вони викладені нижче.');
INSERT INTO `lang_definitions` VALUES (188536, 11325, 30, 'Існує чотири статусу повідомлення-Нове, Переадресоване, прочитане і зроблене');
INSERT INTO `lang_definitions` VALUES (188537, 11326, 30, 'Існує кілька варіантів, що стосуються порталів пацієнтів, і інформація про те, як налаштувати портал пацієнтів, доступна тут');
INSERT INTO `lang_definitions` VALUES (188538, 11327, 30, 'Є кілька пацієнтів з портальним логіном');
INSERT INTO `lang_definitions` VALUES (188539, 11328, 30, 'Існує дев\'ять шаблонів C-CDA, які в даний час визначені');
INSERT INTO `lang_definitions` VALUES (188540, 11329, 30, 'Там немає перевірених карт.');
INSERT INTO `lang_definitions` VALUES (188541, 11330, 30, 'У системі Немає зареєстрованих клієнтів');
INSERT INTO `lang_definitions` VALUES (188542, 11331, 30, 'Щодо цього пацієнта не зареєстровано жодних розкриттів.');
INSERT INTO `lang_definitions` VALUES (188543, 11332, 30, 'У картотеці немає рецептів на окуляри або контактні лінзи для цього пацієнта');
INSERT INTO `lang_definitions` VALUES (188544, 11333, 30, 'У файлі немає ніяких повідомлень для цього пацієнта.');
INSERT INTO `lang_definitions` VALUES (188545, 11334, 30, 'Нових заявок немає');
INSERT INTO `lang_definitions` VALUES (188546, 11335, 30, 'У досьє на цього пацієнта немає ніяких записів.');
INSERT INTO `lang_definitions` VALUES (188547, 11336, 30, 'Ніяких записів не знайдено.');
INSERT INTO `lang_definitions` VALUES (188548, 11337, 30, 'У файлі немає ніяких транзакцій для цього пацієнта.');
INSERT INTO `lang_definitions` VALUES (188549, 11338, 30, 'Існує кілька версій HL7, версії 2.x і версії 3');
INSERT INTO `lang_definitions` VALUES (188550, 11339, 30, 'Існує кілька способів налаштування тарифного листа. Це залежить від того, наскільки зручно вам додавати інформацію в саму базу даних');
INSERT INTO `lang_definitions` VALUES (188551, 11340, 30, 'Є три можливих дії-створити нове датоване нагадування, переслати і встановити як завершене');
INSERT INTO `lang_definitions` VALUES (188552, 11341, 30, 'Тут можна виконати три дії: змінити існуючу групу (ARO), додати нову групу (ARO) або видалити існуючу групу (ARO).');
INSERT INTO `lang_definitions` VALUES (188553, 11343, 30, 'Існує три основних типи звітів, які можуть бути створені, два відносяться до безперервності поточного догляду - безперервність запису догляду (CCR) і безперервність документа догляду (CCD) і третій - звіт пацієнта, який створює документ, що містить різні розділи медичної карти пацієнта, включаючи демографію, медичні проблеми, процедури і зустрічі. Він також має можливість включити всі або будь-який з відсканованих документів в карту пацієнта');
INSERT INTO `lang_definitions` VALUES (188554, 11344, 30, 'При створенні документа безперервності догляду (CCD)');
INSERT INTO `lang_definitions` VALUES (188555, 11345, 30, 'При створенні запису безперервності догляду (CCR) Доступні три варіанти)');
INSERT INTO `lang_definitions` VALUES (188556, 11346, 30, 'Є три набори дій, які можна виконати на цій сторінці, крім того, форма може бути налаштована');
INSERT INTO `lang_definitions` VALUES (188557, 11347, 30, 'Є дві кнопки, які дозволяють вам встановити або зняти всі доступні прапорці');
INSERT INTO `lang_definitions` VALUES (188558, 11348, 30, 'Є два варіанти для записів, які будуть створені');
INSERT INTO `lang_definitions` VALUES (188559, 11349, 30, 'Є два розділи, які видно');
INSERT INTO `lang_definitions` VALUES (188560, 11350, 30, 'Є два джерела, які можна знайти-MedlinePlus Connect або Local Content');
INSERT INTO `lang_definitions` VALUES (188561, 11351, 30, 'Це може бути досягнуто двома способами: або ручним методом, шляхом пошуку і введення даних для окремих рахунків-фактур, або шляхом завантаження всього файлу ERA електронних рекомендацій з переказу грошових коштів.');
INSERT INTO `lang_definitions` VALUES (188562, 11352, 30, 'Існують різні варіанти заповнення, мінімальні дані, необхідні для успішного збереження реферала, - це Дата реферала, посилання і Причина');
INSERT INTO `lang_definitions` VALUES (188563, 11353, 30, 'Сталася помилка відправки пошти за адресою');
INSERT INTO `lang_definitions` VALUES (188564, 11357, 30, 'Є лабораторне замовлення');
INSERT INTO `lang_definitions` VALUES (188565, 11358, 30, 'Є повідомлення про помилку');
INSERT INTO `lang_definitions` VALUES (188566, 11359, 30, 'Вже є категорія з ім\'ям');
INSERT INTO `lang_definitions` VALUES (188567, 11360, 30, 'Вже є підкатегорія з ім\'ям');
INSERT INTO `lang_definitions` VALUES (188568, 11361, 30, 'Там вже є елемент з ім\'ям');
INSERT INTO `lang_definitions` VALUES (188569, 11362, 30, 'Вже є відкритий запит на запис пацієнта.');
INSERT INTO `lang_definitions` VALUES (188570, 11363, 30, 'Для облікового запису AR немає запису COA');
INSERT INTO `lang_definitions` VALUES (188571, 11364, 30, 'Немає запису COA для касового рахунку');
INSERT INTO `lang_definitions` VALUES (188572, 11365, 30, 'Немає запису COA для рахунку доходу');
INSERT INTO `lang_definitions` VALUES (188573, 11366, 30, 'В даний час пацієнта немає');
INSERT INTO `lang_definitions` VALUES (188574, 11367, 30, 'Для цієї теми немає локального контенту.');
INSERT INTO `lang_definitions` VALUES (188575, 11368, 30, 'Немає збігу для ідентифікатора рахунку-фактури');
INSERT INTO `lang_definitions` VALUES (188576, 11369, 30, 'Немає збігу для ідентифікатора рахунку-фактури =');
INSERT INTO `lang_definitions` VALUES (188577, 11370, 30, 'Немає запису деталей для ідентифікатора служби');
INSERT INTO `lang_definitions` VALUES (188578, 11371, 30, 'Немає пацієнта з портальним логіном');
INSERT INTO `lang_definitions` VALUES (188579, 11373, 30, 'Виникла проблема з відправкою повідомлення.');
INSERT INTO `lang_definitions` VALUES (188580, 11374, 30, 'При обробці Вашого запиту сталася помилка.');
INSERT INTO `lang_definitions` VALUES (188581, 11375, 30, 'Сталася помилка екранування OpenEMR SQL наступного рядка');
INSERT INTO `lang_definitions` VALUES (188582, 11376, 30, 'Тому кожен користувач повинен індивідуально активувати цю функцію');
INSERT INTO `lang_definitions` VALUES (188583, 11377, 30, 'Ці ACO згруповані в десять широких категорій, які є частиною установки за замовчуванням. Це-Адміністрація, Бухгалтерія, інформація про пацієнтів, інформація про зустрічі, загони, чутливість, Списки, заповнювач, Національні замітки і Портал пацієнтів. Кожна з цих категорій має одну або кілька підкатегорій, які забезпечують доступ до певних частин програми.');
INSERT INTO `lang_definitions` VALUES (188584, 11378, 30, 'Вони безкоштовні і можуть бути завантажені з відповідного магазину додатків для пристроїв ios і Android');
INSERT INTO `lang_definitions` VALUES (188585, 11379, 30, 'Це посилання 2012 року');
INSERT INTO `lang_definitions` VALUES (188586, 11380, 30, 'Вони використовуються для заповнення полів 3 і 4 в заголовку повідомлення HL7 MSH-message');
INSERT INTO `lang_definitions` VALUES (188587, 11381, 30, 'Вони використовуються для заповнення полів 5 і 6 в заголовку повідомлення HL7 MSH-message');
INSERT INTO `lang_definitions` VALUES (188588, 11382, 30, 'Ці облікові дані будуть використовуватися пацієнтом для входу на портал пацієнта в перший раз');
INSERT INTO `lang_definitions` VALUES (188589, 11383, 30, 'Ці користувацькі групи є специфічними для додатків, а не для користувачів');
INSERT INTO `lang_definitions` VALUES (188590, 11384, 30, 'Ці записи будуть використовуватися для визначення постачальників в модулі процедури');
INSERT INTO `lang_definitions` VALUES (188591, 11385, 30, 'Ці групи (AROS) можуть потім отримати набір привілеїв, призначивши різні категорії (ACOs).');
INSERT INTO `lang_definitions` VALUES (188592, 11386, 30, 'Ці елементи можна редагувати, якщо користувач володіє достатніми правами');
INSERT INTO `lang_definitions` VALUES (188593, 11387, 30, 'Ці списки використовуються для визначення того, хто може отримати доступ до чого в OpenEMR. Вони працюють зверху вниз, тобто спочатку всім відмовлено в доступі до тих частин програми, які контролюються ACL.');
INSERT INTO `lang_definitions` VALUES (188594, 11388, 30, 'Ці номери повинні збігатися для успішної аутентифікації користувача');
INSERT INTO `lang_definitions` VALUES (188595, 11389, 30, 'Ці нотатки про пацієнтів надсилаються без призначеного пацієнта');
INSERT INTO `lang_definitions` VALUES (188596, 11390, 30, 'Ці підкатегорії являють собою фактичні об\'єкти управління доступом (ACOs).');
INSERT INTO `lang_definitions` VALUES (188597, 11391, 30, 'Ці шаблони є лише текстовими і не відображатимуть жодного іншого форматування, крім чистого тексту.');
INSERT INTO `lang_definitions` VALUES (188598, 11392, 30, 'Ці три кроки необхідні для розміщення замовлень і отримання результатів, пов\'язаних з картою пацієнта');
INSERT INTO `lang_definitions` VALUES (188599, 11393, 30, 'Ці транзакції зазвичай використовуються для документування подій, які вже відбулися');
INSERT INTO `lang_definitions` VALUES (188600, 11394, 30, 'Ці дві дії доступні для всіх транзакцій');
INSERT INTO `lang_definitions` VALUES (188601, 11395, 30, 'Вони відображаються рядами і поділяються на три групи');
INSERT INTO `lang_definitions` VALUES (188602, 11396, 30, 'Це Електролітна панель, Базова метаболічна панель, комплексна метаболічна панель, панель функції нирок, Панель загального здоров\'я, Акушерська панель, панель гострого гепатиту, Панель функції печінки і ліпідна панель');
INSERT INTO `lang_definitions` VALUES (188603, 11397, 30, 'Вони перераховані в порядку зростання за датою зустрічі');
INSERT INTO `lang_definitions` VALUES (188604, 11398, 30, 'Вони не поділяють уразливості методів заснованих на SMS і як правило не вимагають підключення до Інтернету за винятком того що їх годинник синхронізовані з поточним часом');
INSERT INTO `lang_definitions` VALUES (188605, 11399, 30, 'Вони будуть надані об\'єктом, до якого ви будете підключатися');
INSERT INTO `lang_definitions` VALUES (188606, 11400, 30, 'Потовщена Права:');
