INSERT INTO `lang_definitions` VALUES (188618, 11412, 30, 'Речі, які фронт-офіс може читати і вводити, але не змінювати');
INSERT INTO `lang_definitions` VALUES (188619, 11413, 30, 'Речі, які фронт-офіс може читати і змінювати');
INSERT INTO `lang_definitions` VALUES (188620, 11414, 30, 'Речі, які фронт-офіс може прочитати і частково змінити');
INSERT INTO `lang_definitions` VALUES (188621, 11415, 30, 'Речі, які лікарі можуть тільки читати');
INSERT INTO `lang_definitions` VALUES (188622, 11416, 30, 'Речі, які лікарі можуть читати і вводити, але не змінювати');
INSERT INTO `lang_definitions` VALUES (188623, 11417, 30, 'Речі, які лікарі можуть читати і змінювати');
INSERT INTO `lang_definitions` VALUES (188624, 11418, 30, 'Речі, які лікарі можуть читати і частково змінювати');
INSERT INTO `lang_definitions` VALUES (188625, 11419, 30, 'Третина');
INSERT INTO `lang_definitions` VALUES (188626, 11420, 30, 'Третє повідомлення облікового запису');
INSERT INTO `lang_definitions` VALUES (188627, 11421, 30, 'Цей обліковий запис вже існує.');
INSERT INTO `lang_definitions` VALUES (188628, 11422, 30, 'Ця дія не може бути скасована.');
INSERT INTO `lang_definitions` VALUES (188629, 11423, 30, 'Ця дія не може бути скасована.');
INSERT INTO `lang_definitions` VALUES (188630, 11424, 30, 'Ця дія не може бути скасована. Ви впевнені, що хочете видалити цю форму?');
INSERT INTO `lang_definitions` VALUES (188631, 11425, 30, 'Ця дія буде записано в журнал');
INSERT INTO `lang_definitions` VALUES (188632, 11426, 30, 'Ця дія обнулить вашу претензію!');
INSERT INTO `lang_definitions` VALUES (188633, 11427, 30, 'Ця сторінка адміністрування призначена для керування списком зареєстрованих додатків OAUTH2, яким дозволено використовувати API.');
INSERT INTO `lang_definitions` VALUES (188634, 11428, 30, 'Це дозволяє вибрати діапазон дат в таблиці потоку пацієнтів.');
INSERT INTO `lang_definitions` VALUES (188635, 11430, 30, 'Цей слот для зустрічей вже використовується, будь ласка, виберіть інший.');
INSERT INTO `lang_definitions` VALUES (188636, 11431, 30, 'Цей слот для зустрічей вже використовується, все одно використовуйте його?');
INSERT INTO `lang_definitions` VALUES (188637, 11432, 30, 'Цей слот для запису на прийом недоступний, будь ласка, виберіть інший.');
INSERT INTO `lang_definitions` VALUES (188638, 11433, 30, 'В Цьому Календарному Році');
INSERT INTO `lang_definitions` VALUES (188639, 11436, 30, 'Ця вимога була скасована.');
INSERT INTO `lang_definitions` VALUES (188640, 11437, 30, 'Цей позов був закритий.');
INSERT INTO `lang_definitions` VALUES (188641, 11438, 30, 'Ця вимога була відхилена.Причина:-');
INSERT INTO `lang_definitions` VALUES (188642, 11439, 30, 'Ця претензія була переадресована на наступний рівень.');
INSERT INTO `lang_definitions` VALUES (188643, 11440, 30, 'Ця претензія має різні варіанти виставлення рахунків HCFA 1500');
INSERT INTO `lang_definitions` VALUES (188644, 11442, 30, 'Цей клієнт в даний час відключений');
INSERT INTO `lang_definitions` VALUES (188645, 11443, 30, 'Цей код є необов\'язковим, якщо використовується тільки ручне введення лабораторних даних');
INSERT INTO `lang_definitions` VALUES (188646, 11444, 30, 'Цей код необов\'язковий, але це хороша практика.');
INSERT INTO `lang_definitions` VALUES (188647, 11445, 30, 'Цей код необов\'язковий, але є гарною практикою.');
INSERT INTO `lang_definitions` VALUES (188648, 11446, 30, 'Цей код є необов\'язковим.');
INSERT INTO `lang_definitions` VALUES (188649, 11447, 30, 'Цей тип коду не приймає відносин.');
INSERT INTO `lang_definitions` VALUES (188650, 11448, 30, 'Це завершує базову настройку і дозволить використовувати відомість зборів для документування зборів з метою виставлення рахунків');
INSERT INTO `lang_definitions` VALUES (188651, 11449, 30, 'Цей контекст містить категорії, які будуть видалені. Ви все ще хочете продовжити?');
INSERT INTO `lang_definitions` VALUES (188652, 11450, 30, 'Ця Розмова');
INSERT INTO `lang_definitions` VALUES (188653, 11451, 30, 'Цей спеціальний вибраний елемент може бути відправлений тільки в відображену лабораторію, обрану в групі призначених для користувача обраних');
INSERT INTO `lang_definitions` VALUES (188654, 11452, 30, 'Це визначає, як зустрічі відображаються в календарі.');
INSERT INTO `lang_definitions` VALUES (188655, 11453, 30, 'Це визначає, яка колірна схема використовується для призначення');
INSERT INTO `lang_definitions` VALUES (188656, 11456, 30, 'Цей діалог генерується з діагнозів проблем пацієнта і накопичених діагнозів всіх минулих процедур.');
INSERT INTO `lang_definitions` VALUES (188657, 11457, 30, 'Це дозволяє постачальнику включити рядок у відомість зборів');
INSERT INTO `lang_definitions` VALUES (188658, 11458, 30, 'Ця Зустріч');
INSERT INTO `lang_definitions` VALUES (188659, 11459, 30, 'Ця зустріч була оголошена. Якщо вам потрібно змінити його, він повинен бути знову відкритий.');
INSERT INTO `lang_definitions` VALUES (188660, 11460, 30, 'Ця зустріч була оголошена. Щоб внести зміни, знову відкрийте його або виберіть Додати додаткові елементи.');
INSERT INTO `lang_definitions` VALUES (188661, 11461, 30, 'Ця зустріч заблокована. Ніякі нові форми не можуть бути додані.');
INSERT INTO `lang_definitions` VALUES (188662, 11462, 30, 'Цей елемент EOB не відповідає мінімальним вимогам друку, встановленим у Globals, або існує невідома помилка.');
INSERT INTO `lang_definitions` VALUES (188663, 11464, 30, 'Цей факс вже відправлений.');
INSERT INTO `lang_definitions` VALUES (188664, 11465, 30, 'Ця функція поки недоступна');
INSERT INTO `lang_definitions` VALUES (188665, 11466, 30, 'Ця функція використовується для додавання пацієнтів до списку відкликання, тобто тих, хто потребує прийому в майбутньому, але прийом ще не запланований');
INSERT INTO `lang_definitions` VALUES (188666, 11467, 30, 'Ця функція дуже Експериментальна і не повністю перевірена. Використовуйте на свій страх і ризик!');
INSERT INTO `lang_definitions` VALUES (188667, 11468, 30, 'Ця функція дозволить перевизначити код POS-об\'єкта за замовчуванням з зустрічі.');
INSERT INTO `lang_definitions` VALUES (188668, 11469, 30, 'Ця функція дозволить перевизначити код POS-об\'єкта за замовчуванням під час зустрічі.');
INSERT INTO `lang_definitions` VALUES (188669, 11470, 30, 'Це поле використовується для прийняття рішення про те, чи слід обробляти повідомлення відповідно до правил обробки програми HL7 (рівень 7).');
INSERT INTO `lang_definitions` VALUES (188670, 11471, 30, 'Ця форма дозволяє ввести детальну інформацію про візит або взаємодію з пацієнтом');
INSERT INTO `lang_definitions` VALUES (188671, 11472, 30, 'Ця повнофункціональна плата відкликання, включена в установку за замовчуванням, може бути використана для додавання пацієнтів до списку відкликання');
INSERT INTO `lang_definitions` VALUES (188672, 11473, 30, 'Це дає вам можливість видалити будь-який небажаний окремий тест в групі');
INSERT INTO `lang_definitions` VALUES (188673, 11474, 30, 'Це повинно бути введено один раз в цій формі');
INSERT INTO `lang_definitions` VALUES (188674, 11475, 30, 'Цей файл довідки розділений на чотири розділи');
INSERT INTO `lang_definitions` VALUES (188675, 11476, 30, 'Цей файл довідки розділений на наступні розділи');
INSERT INTO `lang_definitions` VALUES (188676, 11477, 30, 'Цей код ICD може бути автоматично доданий до списку проблем, встановивши прапорець P (Problem). Цей вибраний елемент з\'явиться в розділі проблеми в розділі Медичні проблеми');
INSERT INTO `lang_definitions` VALUES (188677, 11478, 30, 'Цей номер рахунку-фактури був змінений на');
INSERT INTO `lang_definitions` VALUES (188678, 11479, 30, 'Це дитя результату');
INSERT INTO `lang_definitions` VALUES (188679, 11480, 30, 'Це робиться в розділі Адміністрування > користувачі.');
INSERT INTO `lang_definitions` VALUES (188680, 11481, 30, 'Далі йдуть стовпці редагувати і додавати, що містять значок олівця і значок +');
INSERT INTO `lang_definitions` VALUES (188681, 11483, 30, 'Це не є дійсним запитом');
INSERT INTO `lang_definitions` VALUES (188682, 11484, 30, 'Це передається додатку разом із значенням контрольної суми і є унікальним для кожного USB-ключа і, отже, користувача, який ним володіє');
INSERT INTO `lang_definitions` VALUES (188683, 11485, 30, 'Це публічна інформація, підтримувана HHS / CMS. Ми не несемо відповідальності за отримані дані');
INSERT INTO `lang_definitions` VALUES (188684, 11486, 30, 'Це необхідно як для ручного введення результатів лабораторних досліджень, так і для електронного замовлення тестів і отримання результатів');
INSERT INTO `lang_definitions` VALUES (188685, 11487, 30, 'Це необхідно як для вашої безпеки, так і для нашої.');
INSERT INTO `lang_definitions` VALUES (188686, 11488, 30, 'Це дата початку звіту Головної книги.');
INSERT INTO `lang_definitions` VALUES (188687, 11489, 30, 'Це діаграма, яка повинна бути об\'єднана з основною діаграмою, а потім видалена.');
INSERT INTO `lang_definitions` VALUES (188688, 11490, 30, 'Це початкова дата за замовчуванням для плати потоку пацієнтів. (застосовується тільки в тому випадку, якщо включений параметр Дозволити діапазон дат в наведеній вище опції)');
INSERT INTO `lang_definitions` VALUES (188689, 11491, 30, 'Це кінцева дата за замовчуванням для плати потоку пацієнтів. (застосовується тільки в тому випадку, якщо включений параметр Дозволити діапазон дат в наведеній вище опції)');
INSERT INTO `lang_definitions` VALUES (188690, 11492, 30, 'Це ліве поле друку за замовчуванням для CMS 1500. Він буде регулювати остаточний друкований висновок вліво або вправо.');
INSERT INTO `lang_definitions` VALUES (188691, 11493, 30, 'Це ліве поле друку за замовчуванням для UB04. Він буде регулювати остаточний друкований висновок вліво або вправо.');
INSERT INTO `lang_definitions` VALUES (188692, 11494, 30, 'Це верхнє поле друку за замовчуванням для CMS 1500. Він буде регулювати кінцевий друкований висновок вгору або вниз.');
INSERT INTO `lang_definitions` VALUES (188693, 11495, 30, 'Це верхнє поле друку за замовчуванням для UB04. Він буде регулювати кінцевий друкований висновок вгору або вниз.');
INSERT INTO `lang_definitions` VALUES (188694, 11496, 30, 'Це кінцева дата для діапазону дат плати потоку пацієнтів. (застосовується тільки в тому випадку, якщо включений параметр Дозволити діапазон дат в наведеній вище опції)');
INSERT INTO `lang_definitions` VALUES (188695, 11497, 30, 'Це останнє з декількох результуючих значень.');
INSERT INTO `lang_definitions` VALUES (188696, 11498, 30, 'Це основна діаграма, яка повинна отримувати об\'єднані дані.');
INSERT INTO `lang_definitions` VALUES (188697, 11499, 30, 'Це кількість повідомлень, яке буде відображатися в віджеті повідомлення на екрані зведення пацієнта.');
INSERT INTO `lang_definitions` VALUES (188698, 11500, 30, 'Це рекомендований метод для нетехнічного користувача, який при ретельному виконанні зменшить кількість помилок конфігурації');
INSERT INTO `lang_definitions` VALUES (188699, 11501, 30, 'Саме тут створюються реферали і різні інші прості транзакції');
INSERT INTO `lang_definitions` VALUES (188700, 11502, 30, 'Цей елемент не має достатньо даних для побудови графіка');
INSERT INTO `lang_definitions` VALUES (188701, 11503, 30, 'Цей елемент буде відображатися на сторінці в один рядок');
INSERT INTO `lang_definitions` VALUES (188702, 11504, 30, 'Цей ключ генерується додатком і представляється користувачеві у вигляді QR-коду');
INSERT INTO `lang_definitions` VALUES (188703, 11505, 30, 'Це ключове ім\'я вже використовується вами. Пробувати знову.');
INSERT INTO `lang_definitions` VALUES (188704, 11506, 30, 'Такого макета не існує.');
INSERT INTO `lang_definitions` VALUES (188705, 11507, 30, 'Цей ідентифікатор макета вже існує');
INSERT INTO `lang_definitions` VALUES (188706, 11508, 30, 'Це дозволяє вручну ввести відповідь на реферал у вигляді структурованих даних');
INSERT INTO `lang_definitions` VALUES (188707, 11509, 30, 'Це дозволяє вам встановити рівень цін для зборів і стягувати різні тарифи для різних способів оплати.');
INSERT INTO `lang_definitions` VALUES (188708, 11510, 30, 'це місце');
INSERT INTO `lang_definitions` VALUES (188709, 11511, 30, 'Це повідомлення не обов\'язково повинно бути пов\'язане з пацієнтом');
INSERT INTO `lang_definitions` VALUES (188710, 11512, 30, 'Цей текст повідомлення не зберігається автоматично. Скопіюйте та збережіть його відповідно до змісту.');
INSERT INTO `lang_definitions` VALUES (188711, 11513, 30, 'Однак цей метод призведе до того, що дані стануть неструктурованими, і людина втратить можливість документувати відповідь в електронному форматі');
INSERT INTO `lang_definitions` VALUES (188712, 11514, 30, 'Цей модуль використовується');
INSERT INTO `lang_definitions` VALUES (188713, 11515, 30, 'Цей модуль знаходиться в тестовому режимі. База даних не буде змінена.');
INSERT INTO `lang_definitions` VALUES (188714, 11516, 30, 'Цей модуль заснований на підписці і повинен бути включений з меню Адміністрування > Глобали > З\'єднувачі > включити службу NewCrop eRx');
INSERT INTO `lang_definitions` VALUES (188715, 11517, 30, 'Цей модуль добре інтегрований з OpenEMR, однак є дві альтернативи, не засновані на підписці, Weno і Allscripts, які можна використовувати замість цього');
INSERT INTO `lang_definitions` VALUES (188716, 11518, 30, 'Цей модуль сприяє ефективному введенню даних EOB.');
INSERT INTO `lang_definitions` VALUES (188717, 11519, 30, 'Цього місяця на сьогоднішній день');
INSERT INTO `lang_definitions` VALUES (188718, 11520, 30, 'Це ім\'я вже існує під цим батьком.');
INSERT INTO `lang_definitions` VALUES (188719, 11521, 30, 'Цей простір імен вже існує в базі даних');
INSERT INTO `lang_definitions` VALUES (188720, 11522, 30, 'Ця нова категорія буде підкатегорією');
INSERT INTO `lang_definitions` VALUES (188721, 11524, 30, 'Цей наказ вже був переданий');
INSERT INTO `lang_definitions` VALUES (188722, 11525, 30, 'На цій сторінці можна переглянути всі підтримувані зовнішні завантаження даних, які можна встановити і оновити. Кожен розділ нижче можна розширити, натиснувши на заголовок розділу, щоб переглянути стан конкретної бази даних, що цікавить.');
INSERT INTO `lang_definitions` VALUES (188723, 11526, 30, 'Ця сторінка деактивована з міркувань безпеки.');
INSERT INTO `lang_definitions` VALUES (188724, 11527, 30, 'Ця сторінка дозволяє налаштувати замовлення і результати');
INSERT INTO `lang_definitions` VALUES (188725, 11528, 30, 'Ця сторінка буде вбудована в сторінку входу, так що нам не доведеться кожного разу натискати кнопку relogin.');
INSERT INTO `lang_definitions` VALUES (188726, 11529, 30, 'У цього пацієнта вже призначена зустріч');
INSERT INTO `lang_definitions` VALUES (188727, 11530, 30, 'Цей пацієнт не дозволяє відправляти SMS-повідомлення!');
INSERT INTO `lang_definitions` VALUES (188728, 11532, 30, 'У цього пацієнта немає ніякої активності.');
INSERT INTO `lang_definitions` VALUES (188729, 11533, 30, 'Цей ідентифікатор пацієнта вже використовується!');
INSERT INTO `lang_definitions` VALUES (188730, 11534, 30, 'Це портали аутентифікації.');
INSERT INTO `lang_definitions` VALUES (188731, 11535, 30, 'Цей продукт допускає тільки одну партію на склад.');
INSERT INTO `lang_definitions` VALUES (188732, 11536, 30, 'Цей протокол не реалізований');
INSERT INTO `lang_definitions` VALUES (188733, 11539, 30, 'В даний час цей звіт працює тільки для кодів ICD9.');
INSERT INTO `lang_definitions` VALUES (188734, 11542, 30, 'Цей розділ дозволяє створювати і видаляти групи, А також змінювати або надавати права доступу існуючим групам. Установіть прапорець для відображення розділу');
INSERT INTO `lang_definitions` VALUES (188735, 11543, 30, 'Цей розділ можна налаштувати так, щоб згрупувати коди за різними категоріями');
INSERT INTO `lang_definitions` VALUES (188736, 11544, 30, 'Цей розділ НЕ дозволяє створювати нові ACOS.');
INSERT INTO `lang_definitions` VALUES (188737, 11545, 30, 'У цьому розділі вибираються коди, які використовуються для стягування плати за відвідування');
INSERT INTO `lang_definitions` VALUES (188738, 11546, 30, 'Цей розділ дозволяє шукати необхідний код, якщо він не знаходиться в Налаштуваннях за замовчуванням або налаштованих в розділі \"Вибір коду\".');
INSERT INTO `lang_definitions` VALUES (188739, 11547, 30, 'Цей розділ дозволить ввійшов в систему користувачеві переглянути існуючі методи або видалити їх');
INSERT INTO `lang_definitions` VALUES (188740, 11548, 30, 'Це встановлює подання календаря за замовчуванням, за замовчуванням-День.');
INSERT INTO `lang_definitions` VALUES (188741, 11549, 30, 'Це вказує друк користувальницького згрупованого Постачальника звітів на кінець дня або дозволяє друк тільки підсумків');
INSERT INTO `lang_definitions` VALUES (188742, 11550, 30, 'Це вказує, чи слід включати дату в поле 31.');
INSERT INTO `lang_definitions` VALUES (188743, 11551, 30, 'Це вказує, яку редакцію форми повинен генерувати модуль виставлення рахунків');
INSERT INTO `lang_definitions` VALUES (188744, 11552, 30, 'На цьому кроці буде згенеровано файл, який ви повинні зберегти для подальшого використання.');
INSERT INTO `lang_definitions` VALUES (188745, 11553, 30, 'На цьому кроці буде згенеровано файл, який ви повинні зберегти для подальшого використання. Файл не може бути згенерований знову. Ви хочете продовжити?');
INSERT INTO `lang_definitions` VALUES (188746, 11556, 30, 'Цей користувач не є членом будь-якої групи');
INSERT INTO `lang_definitions` VALUES (188747, 11557, 30, 'Цей користувач буде отримувати повідомлення про нові вхідні прямі повідомлення');
INSERT INTO `lang_definitions` VALUES (188748, 11558, 30, 'Ця утиліта є експериментальною. Створіть резервну копію своєї бази даних і документів перед її використанням!');
INSERT INTO `lang_definitions` VALUES (188749, 11559, 30, 'Ця утиліта є експериментальною. Створіть резервну копію своєї бази даних і документів перед її використанням!');
INSERT INTO `lang_definitions` VALUES (188750, 11560, 30, 'Цей візит починає нове використання контрацептивів');
INSERT INTO `lang_definitions` VALUES (188751, 11561, 30, 'Для цього візиту потрібна форма GCAC, напрямок або процедурна служба.');
INSERT INTO `lang_definitions` VALUES (188752, 11562, 30, 'Це була стара форма життєвих показників тільки для метрики, тепер застаріла.');
INSERT INTO `lang_definitions` VALUES (188753, 11563, 30, 'На цьому тижні на сьогоднішній день');
INSERT INTO `lang_definitions` VALUES (188754, 11565, 30, 'Це призведе до відмови від ваших незбережених змін. Ти впевнений?');
INSERT INTO `lang_definitions` VALUES (188755, 11566, 30, 'Це активує звітність CCR(Continuity of Care Record) і CCD (Continuity of Care Document).');
INSERT INTO `lang_definitions` VALUES (188756, 11568, 30, 'Це дозволить надрукувати користувальницьке повідомлення на операторах.');
INSERT INTO `lang_definitions` VALUES (188757, 11569, 30, 'Це дозволить роздрукувати платіжну відомість пацієнта на виписках.');
INSERT INTO `lang_definitions` VALUES (188758, 11570, 30, 'Це дозволить вибрати мову налагодження (\"фіктивний\").');
INSERT INTO `lang_definitions` VALUES (188759, 11571, 30, 'Це дозволить відображати модальну довідку на сторінках з підтримкою довідки');
INSERT INTO `lang_definitions` VALUES (188760, 11572, 30, 'Це дозволить використовувати користувальницький звіт про кінець дня і вказати, який звіт використовувати.');
INSERT INTO `lang_definitions` VALUES (188761, 11573, 30, 'Це дозволить використовувати призначені для користувача повідомлення Даннінга в операторах.');
INSERT INTO `lang_definitions` VALUES (188762, 11574, 30, 'Це буде \"сухий пробіг\" без будь-яких фізичних оновлень даних.');
INSERT INTO `lang_definitions` VALUES (188763, 11575, 30, 'Це очистить дані від усіх полів обстеження переднього сегмента');
INSERT INTO `lang_definitions` VALUES (188764, 11576, 30, 'Це очистить дані від усіх зовнішніх полів іспиту');
INSERT INTO `lang_definitions` VALUES (188765, 11577, 30, 'Це очистить дані від усіх полів іспиту сітківки');
INSERT INTO `lang_definitions` VALUES (188766, 11578, 30, 'При цьому обраний код буде скопійований в поле діагностичні коди у спливаючій формі\"введення відомостей для окремого користувача обраного елемента\".');
INSERT INTO `lang_definitions` VALUES (188767, 11579, 30, 'Це створить резервну копію у форматі tar, а потім відправить її у ваш веб-браузер, щоб ви могли зберегти її');
INSERT INTO `lang_definitions` VALUES (188768, 11580, 30, 'Це деактивує функції шифрування і дешифрування документів і приховає їх в інтерфейсі користувача.');
INSERT INTO `lang_definitions` VALUES (188769, 11581, 30, 'Це відключить кнопку редагування на всіх формах, батьківська зустріч яких підписана електронним підписом');
INSERT INTO `lang_definitions` VALUES (188770, 11582, 30, 'Це вимкне кнопку редагування на будь-якій формі, підписаній електронним підписом');
INSERT INTO `lang_definitions` VALUES (188771, 11583, 30, 'Це дозволить відобразити номер рахунку-фактури в Звіті про продажі або Ім\'я та ідентифікатор пацієнта або Ім\'я пацієнта і номер рахунку-фактури.');
INSERT INTO `lang_definitions` VALUES (188772, 11584, 30, 'Це дозволить шифрувати елементи, що зберігаються в CouchDB.');
INSERT INTO `lang_definitions` VALUES (188773, 11585, 30, 'Це дозволить шифрувати елементи, що зберігаються на диску.');
INSERT INTO `lang_definitions` VALUES (188774, 11586, 30, 'Це дозволить підписати цілу зустріч, а не окремі форми');
INSERT INTO `lang_definitions` VALUES (188775, 11587, 30, 'Це дозволить підписувати окремі форми окремо');
INSERT INTO `lang_definitions` VALUES (188776, 11588, 30, 'Це дозволить виключити з друку вибрані виписки пацієнтів.');
INSERT INTO `lang_definitions` VALUES (188777, 11589, 30, 'Це заповнить текстове поле заголовка, а також код ICD10 в текстовому полі кодування');
INSERT INTO `lang_definitions` VALUES (188778, 11590, 30, 'Це змусить віджет виставлення рахунків на екрані зведення пацієнтів завжди бути відкритим.');
INSERT INTO `lang_definitions` VALUES (188779, 11591, 30, 'Це дасть користувачеві можливість блокування (окрема блокування і підпис)');
INSERT INTO `lang_definitions` VALUES (188780, 11592, 30, 'Це дасть вам можливість встановлювати різні рівні цін при ручному введенні кодів CPT');
INSERT INTO `lang_definitions` VALUES (188781, 11595, 30, 'Це приховає порожні журнали електронного підпису в звіті про пацієнта');
INSERT INTO `lang_definitions` VALUES (188782, 11596, 30, 'Це приховає віджет виставлення рахунків на екрані зведення пацієнтів');
INSERT INTO `lang_definitions` VALUES (188783, 11597, 30, 'Це дозволить об\'єднати дві карти пацієнтів в одну. Це корисно, коли пацієнт був дубльований помилково. Якщо це відбувається часто, виправте свої офісні процедури-не виконуйте їх регулярно!');
INSERT INTO `lang_definitions` VALUES (188784, 11598, 30, 'Це не завадить вам зайти на сайт електронних рецептів.');
INSERT INTO `lang_definitions` VALUES (188785, 11600, 30, 'Це дозволить надрукувати наступну зустріч у нижній частині книги пацієнтів');
INSERT INTO `lang_definitions` VALUES (188786, 11601, 30, 'Це дозволить повторно відобразити секретний ключ за допомогою QR-коду, який потім може бути захоплений і збережений на новому смартфоні за допомогою програми authenticator');
INSERT INTO `lang_definitions` VALUES (188787, 11602, 30, 'Це зареєструє новий USB-ключ U2F');
INSERT INTO `lang_definitions` VALUES (188788, 11603, 30, 'Це відкриє розділ Register TOTP Key для увійшов в систему користувача');
INSERT INTO `lang_definitions` VALUES (188789, 11604, 30, 'Це покаже старіння в операторі користувача.');
INSERT INTO `lang_definitions` VALUES (188790, 11605, 30, 'Це відключить використання безпечного апострофа, що робиться шляхом перетворення \' і \" в `.(настійно рекомендується, щоб цей параметр був вимкнений і щоб використовувалися безпечні апострофи)');
