INSERT INTO `lang_definitions` VALUES (188859, 11676, 30, 'Щоб додати додаткові параметри в спадне меню, перейдіть в розділ Адміністрування > Списки > управління списками, виберіть у спадному списку пункт \"рівень цін\" і введіть типи, наприклад: Кредитна карта, Готівка і т. д.');
