INSERT INTO `lang_definitions` VALUES (188863, 11680, 30, 'в постраждалий район');
INSERT INTO `lang_definitions` VALUES (188864, 11681, 30, 'Щоб дозволити для кожного рядка процедури мати окремого постачальника, ви повинні встановити прапорець \"постачальник підтримки в рядку в платіжному аркуші\" в розділі Адміністрування > Глобали > виставлення рахунків. Якщо цей прапорець Не встановлено, постачальник рендеринга в цьому розділі буде використовуватися для всіх тверджень');
INSERT INTO `lang_definitions` VALUES (188865, 11682, 30, 'Щоб авторизувати портал пацієнта для пацієнта, перейдіть в панель моніторингу > Демографія > Правка > вибір і виберіть Так У спадному списку дозволити портал пацієнта і збережіть');
INSERT INTO `lang_definitions` VALUES (188866, 11683, 30, 'Щоб автоматично відкрити зазначену форму. Деякі спортивні команди використовують тут football_injury_audit.');
INSERT INTO `lang_definitions` VALUES (188867, 11684, 30, 'Щоб пов\'язати цю проблему з зустріччю, натисніть на кнопку, щоб відкрити спливаючу сторінку \"проблеми і зустрічі\".');
