INSERT INTO `lang_definitions` VALUES (188875, 11692, 30, 'Щоб створити ще одну панель тестів, ви повторите цей процес, але почнете зі створення порядку процедур або плодоносної гілки рівня 3 , наприклад-панелі гострого гепатиту під основною гілкою або підгрупою органів / захворювань (Рівень 2)');
INSERT INTO `lang_definitions` VALUES (188876, 11694, 30, 'На сьогоднішній день має бути пізніше, ніж на сьогоднішній день!');
INSERT INTO `lang_definitions` VALUES (188877, 11695, 30, 'До дед\'бле');
INSERT INTO `lang_definitions` VALUES (188878, 11696, 30, 'Щоб видалити будь-який або всі вибрані коди ICD10, натисніть ще раз на поле діагностичні коди, щоб відкрити спливаюче вікно Вибір діагностичних кодів');
INSERT INTO `lang_definitions` VALUES (188879, 11697, 30, 'Щоб видалити посилання просто натисніть на елемент для видалення посилання і він буде видалений і більше не буде виділений');
INSERT INTO `lang_definitions` VALUES (188880, 11698, 30, 'Для Dems');
INSERT INTO `lang_definitions` VALUES (188881, 11699, 30, 'Щоб відключити автоматичну перевірку повідомлень, перейдіть в розділ Адміністрування > Глобали > З\'єднувачі і встановіть інтервал перевірки повідомлень phiMail рівним 0 (нулю)');
INSERT INTO `lang_definitions` VALUES (188882, 11700, 30, 'Щоб відключити SSL-сертифікати на стороні клієнта, прокоментуйте наведені вище рядки в конфігураційному файлі Apache і встановіть');
INSERT INTO `lang_definitions` VALUES (188883, 11701, 30, 'Щоб відключити SSL-сертифікати на стороні клієнта, прокоментуйте наведені вище рядки в конфігураційному файлі Apache і вимкніть глобальну настройку\" включити клієнтський SSL \" в OpenEMR і перезапустіть сервер Apache.');
INSERT INTO `lang_definitions` VALUES (188884, 11702, 30, 'Щоб вимкнути HTTPS, прокоментуйте наведені вище рядки в конфігураційному файлі Apache і перезапустіть сервер Apache.');
INSERT INTO `lang_definitions` VALUES (188885, 11703, 30, 'Щоб відобразити суму доплати, вона повинна бути введена в страховку пацієнта в розділі Правка > Демографія');
INSERT INTO `lang_definitions` VALUES (188886, 11704, 30, 'Для цього натисніть на чорний знак + в дальньому кінці рядка замовлення сироватки сечової кислоти, щоб відкрити спливаюче вікно введення відомостей');
INSERT INTO `lang_definitions` VALUES (188887, 11705, 30, 'Щоб відредагувати існуючу групу (ARO), натисніть на значок поруч з потрібною групою. Це викличе вікно редагування.');
INSERT INTO `lang_definitions` VALUES (188888, 11706, 30, 'Для включення будь-якої іншої форми підключення потрібно написати новий код');
INSERT INTO `lang_definitions` VALUES (188889, 11707, 30, 'Щоб включити клієнтські SSL сертифікати');
INSERT INTO `lang_definitions` VALUES (188890, 11708, 30, 'Щоб включити аутентифікацію SSL-сертифікатів на стороні клієнта, необхідно включити HTTPS.');
INSERT INTO `lang_definitions` VALUES (188891, 11709, 30, 'Щоб включити довідку-перейдіть в розділ Адміністрування > Глобали > функції > включити модальну довідку');
INSERT INTO `lang_definitions` VALUES (188892, 11710, 30, 'Щоб увімкнути довідку-перейдіть до імені користувача у верхньому лівому куті > Налаштування > функції > увімкнути модальну довідку');
INSERT INTO `lang_definitions` VALUES (188893, 11711, 30, 'Щоб увімкнути довідку-перейдіть до імені користувача у верхньому правому куті > Налаштування > функції > увімкнути модальну довідку');
INSERT INTO `lang_definitions` VALUES (188894, 11712, 30, 'Щоб увімкнути лише HTTPS, виконайте наведені вище зміни та перезапустіть сервер Apache. Якщо ви також хочете налаштувати сертифікати на стороні клієнта, будь ласка, налаштуйте їх в наступному розділі.');
INSERT INTO `lang_definitions` VALUES (188895, 11713, 30, 'Щоб увімкнути Портал пацієнта, перейдіть до розділу адміністрування > Портал > увімкнути локальний портал пацієнта версії 2, увімкнути зовнішній Портал пацієнта або увімкнути Портал CMS');
INSERT INTO `lang_definitions` VALUES (188896, 11715, 30, 'В Enctr');
INSERT INTO `lang_definitions` VALUES (188897, 11716, 30, 'Фільтрувати по підлозі');
INSERT INTO `lang_definitions` VALUES (188898, 11717, 30, 'Щоб виконати значущі вимоги до використання і допомогти відстежувати його використання, ви можете встановити прапорець відправлена зведення догляду і прапорець відправлена зведення догляду в електронному вигляді, якщо це необхідно');
INSERT INTO `lang_definitions` VALUES (188899, 11718, 30, 'Щоб повністю видалити його, натисніть кнопку \"Зберегти\".');
INSERT INTO `lang_definitions` VALUES (188900, 11719, 30, 'Щоб почати роботу, ви вибираєте один з двох перемикачів. \"Пошук рахунків-фактур\" або \" завантаження ери\"');
INSERT INTO `lang_definitions` VALUES (188901, 11720, 30, 'Щоб допомогти вивчити різні компоненти сторінки звіту, особливо якщо ви хочете використовувати її в якості керівництва по експлуатації, рекомендується зменшити розмір браузера до половини видового екрану, змінити розмір спливаючого вікна довідки, клацнувши і перетягнувши його в правий нижній кут. Відкрийте інший екземпляр браузера і змініть його розмір, щоб він закривав іншу половину вікна перегляду, увійдіть в OpenEMR');
INSERT INTO `lang_definitions` VALUES (188902, 11721, 30, 'Щоб допомогти Вам ознайомитися з різними компонентами сторінки панелі моніторингу, рекомендується зменшити розмір браузера до половини видового екрану, змінити розмір спливаючого вікна довідки, клацнувши і перетягнувши його в правий нижній кут. Відкрийте інший екземпляр браузера і змініть його розмір, щоб він закривав іншу половину вікна перегляду, увійдіть в OpenEMR');
INSERT INTO `lang_definitions` VALUES (188903, 11722, 30, 'Щоб допомогти спростити реалізацію, широко використовувані шаблони були гармонізовані з існуючими посібниками з реалізації CDA і об\'єднані в єдине керівництво по реалізації – Керівництво по реалізації C-CDA (IG) (07/2012)');
INSERT INTO `lang_definitions` VALUES (188904, 11723, 30, 'До історії');
INSERT INTO `lang_definitions` VALUES (188905, 11724, 30, 'Щоб включити відскановані документи, які є частиною історії хвороби пацієнта, виберіть потрібні записи, встановивши відповідні прапорці');
INSERT INTO `lang_definitions` VALUES (188906, 11725, 30, 'До Питань');
INSERT INTO `lang_definitions` VALUES (188907, 11726, 30, 'Щоб зв\'язати проблеми з зустріччю, спочатку виберіть проблему, вона буде виділена жовтим кольором, потім натисніть на одну або кілька зустрічей, щоб зв\'язати їх, вибрані зустрічі будуть виділені фіолетовим кольором');
INSERT INTO `lang_definitions` VALUES (188908, 11727, 30, 'Щоб пов\'язати цю зустріч/консультацію з існуючою проблемою, натисніть кнопку');
INSERT INTO `lang_definitions` VALUES (188909, 11728, 30, 'Щоб пов\'язати цю зустріч/консультацію з існуючою проблемою, клацніть потрібну проблему вище, щоб виділити її, а потім натисніть кнопку [Зберегти]. Утримуючи кнопку [Ctrl], виберіть кілька проблем.');
INSERT INTO `lang_definitions` VALUES (188910, 11729, 30, 'Щоб пов\'язати цю зустріч/консультацію з існуючою проблемою, клацніть потрібну проблему вище, щоб виділити її, а потім натисніть кнопку Зберегти');
INSERT INTO `lang_definitions` VALUES (188911, 11730, 30, 'щоб знову увійти в систему');
INSERT INTO `lang_definitions` VALUES (188912, 11731, 30, 'Щоб перемістити групи з одного стовпця в інший, виберіть один або кілька елементів зі стовпця, з якого їх потрібно перемістити, і натисніть відповідну кнопку з подвійними шевронами.');
INSERT INTO `lang_definitions` VALUES (188913, 11732, 30, 'Для продовження роботи вам знадобиться USB-ключ безпеки, захищене HTTPS-з\'єднання і браузер, що підтримує U2F');
INSERT INTO `lang_definitions` VALUES (188914, 11733, 30, 'Нагадаємо, що була створена група, яка називається хімією сироватки (Рівень 1), під нею був створений прямий нащадок або нащадок, званий Сироватковою сечовою кислотою (Рівень 2), Як Порядок процедур, який мав одного прямого нащадка або нащадок, також званий Сироватковою сечовою кислотою (Рівень 3), Як Дискретний результат, який міститиме значення результату.');
INSERT INTO `lang_definitions` VALUES (188915, 11734, 30, 'Щоб отримувати повідомлення про помилки від служби прямих повідомлень, необхідно ввести дійсну адресу електронної пошти повідомлення для користувача, названого в розділі Адміністрування > Глобали > З\'єднувачі > Користувач повідомлення phiMail');
INSERT INTO `lang_definitions` VALUES (188916, 11735, 30, 'Щоб записати розкриття інформації, будь ласка, натисніть кнопку');
INSERT INTO `lang_definitions` VALUES (188917, 11736, 30, 'Для реєстрації вам потрібен додаток authenticator, встановлений на вашому смартфоні');
INSERT INTO `lang_definitions` VALUES (188918, 11738, 30, 'Для повторної відправки видаліть файл з системи зв\'язку і повторіть спробу.');
INSERT INTO `lang_definitions` VALUES (188919, 11739, 30, 'Для повторної відправки видаліть файл з системи зв\'язку, перезавантажте цю сторінку і повторіть спробу.');
INSERT INTO `lang_definitions` VALUES (188920, 11740, 30, 'Щоб відкрити фільтри натисніть на значок очі');
INSERT INTO `lang_definitions` VALUES (188921, 11741, 30, 'бігти');
INSERT INTO `lang_definitions` VALUES (188922, 11743, 30, 'Щоб побачити всі доступні ACOS, натисніть на значок очі.');
INSERT INTO `lang_definitions` VALUES (188923, 11744, 30, 'Щоб вибрати конкретний код, ідентифікуйте його в результатах, що повертаються, і натисніть на нього, щоб вибрати');
INSERT INTO `lang_definitions` VALUES (188924, 11745, 30, 'Щоб вибрати кілька груп, утримуйте клавішу \"Shift\" або \"Ctrl\" під час клацання.');
INSERT INTO `lang_definitions` VALUES (188925, 11747, 30, 'Щоб налаштувати https-доступ з перевіркою автентичності сертифіката клієнта, виконайте наступні дії');
