INSERT INTO `lang_definitions` VALUES (188927, 11749, 30, 'до шкіри');
INSERT INTO `lang_definitions` VALUES (188928, 11750, 30, 'Підбивати підсумки');
INSERT INTO `lang_definitions` VALUES (188929, 11751, 30, 'до цього візиту?');
INSERT INTO `lang_definitions` VALUES (188930, 11752, 30, 'Щоб завантажити документ CCR вже існуючого пацієнта, Використовуйте екран зведення пацієнта- > документи. Для отримання документа CCR нового пацієнта використовуйте Miscellanous - >New Documents screen');
INSERT INTO `lang_definitions` VALUES (188931, 11754, 30, 'Щоб використовувати сторінку довідки в якості керівництва по експлуатації, рекомендується зменшити розмір браузера до половини видового екрану, змінити розмір спливаючого вікна довідки, клацнувши і перетягнувши його в правий нижній кут. Відкрийте інший екземпляр браузера і змініть його розмір, щоб він закривав іншу половину вікна перегляду, увійдіть в OpenEMR');
INSERT INTO `lang_definitions` VALUES (188932, 11755, 30, 'Щоб використовувати цей файл довідки в якості керівництва по експлуатації, найкраще змінити розмір вашого браузера, щоб зайняти половину екрану, відкрити інший екземпляр браузера, щоб заповнити іншу половину екрану, увійти в OpenEMR і відкрити файл довідки в цьому браузері і змінити його розмір, натиснувши і перетягнувши нижній правий кут так, щоб він займав всю половину екрану.');
INSERT INTO `lang_definitions` VALUES (188933, 11756, 30, 'Щоб використовувати цей файл довідки в якості керівництва по експлуатації, рекомендується зменшити розмір браузера до половини видового екрану, змінити розмір спливаючого вікна довідки, клацнувши і перетягнувши його в правий нижній кут. Відкрийте інший екземпляр браузера і змініть його розмір, щоб він закривав іншу половину вікна перегляду, увійдіть в OpenEMR');
