INSERT INTO `lang_definitions` VALUES (189344, 12210, 30, 'Після успішного пошуку Вам буде представлений список рахунків-фактур. Ви можете натиснути на один з номерів рахунку-фактури, щоб відкрити друге вікно, яке є сторінкою Введення даних для ручної проводки. Ви також можете натиснути на ім\'я пацієнта, якщо хочете ввести нотатку, яку персонал приймальні побачить, коли пацієнт зареєструється, і ви можете вибрати рахунки-фактури, які будуть відображатися у виписках пацієнтів, і роздрукувати ці виписки.');
INSERT INTO `lang_definitions` VALUES (189345, 12211, 30, 'При натисканні на номер рахунку-фактури з\'являється \"вікно ручної проводки\". Тут ви можете змінити дату оплати і примітки до рахунку-фактури, вибрати сторону, для якої Ви проводите облік, і вибрати страховки, за якими були отримані всі очікувані платежі. Найголовніше, що для кожного платіжного коду, за яким була списана сума, ви можете ввести платіжну та коригувальну інформацію.');
INSERT INTO `lang_definitions` VALUES (189346, 12212, 30, 'При натисканні на номер рахунку-фактури з\'являється \"вікно ручної проводки\". Тут ви можете змінити дату оплати і примітки до рахунку-фактури, вибрати сторону, для якої Ви проводите облік, і вибрати страховки, за якими були отримані всі очікувані платежі. Найголовніше, що для кожного платіжного коду, за яким була списана сума, можна ввести платіжну та коригувальну інформацію.');
INSERT INTO `lang_definitions` VALUES (189347, 12213, 30, 'При вході на сторінку під панеллю навігації видно дві кнопки');
INSERT INTO `lang_definitions` VALUES (189348, 12214, 30, 'При вході в OpenEMR в правому верхньому куті відображається невеликий значок конверта. Він показує кількість очікуваних повідомлень і датованих нагадувань');
INSERT INTO `lang_definitions` VALUES (189349, 12215, 30, 'Після досягнення заздалегідь визначеної точки, будь то дата або Значення, правило викличе одну або кілька подій');
INSERT INTO `lang_definitions` VALUES (189350, 12216, 30, 'При пошуку Вам буде представлений список рахунків-фактур. Ви можете натиснути на один з номерів рахунку-фактури, щоб відкрити друге вікно, яке є сторінкою Введення даних для ручної проводки. Ви також можете натиснути на ім\'я пацієнта, якщо хочете ввести нотатку, яку персонал приймальні побачить, коли пацієнт зареєструється, і ви можете вибрати рахунки-фактури, які будуть відображатися у виписках пацієнтів, і роздрукувати ці виписки.');
INSERT INTO `lang_definitions` VALUES (189351, 12217, 30, 'При виборі списку для редагування буде відображена сторінка редагування зі значеннями списку');
INSERT INTO `lang_definitions` VALUES (189352, 12218, 30, 'Після успішної реєстрації ви повернетеся на цільову сторінку управління багатофакторною аутентифікацією');
