INSERT INTO `lang_definitions` VALUES (189500, 12379, 30, 'Використання фруктового дерева як простішої для візуалізації аналогії краще пояснить концепцію цієї ієрархії: стовбур дерева-це група (хімія сироватки), плодоносна гілка-це фактичний порядок, Порядок процедур (сечова кислота сироватки), а плід-це результат, Дискретний результат, також званий (сечова кислота сироватки), який буде містити значення повернутого результату. Точно так само, як плід не народжується на головному стовбурі, ви не повинні поміщати Дискретний Результат в якості прямого нащадка або дитини верхньої групи. Точно так само плодоносна гілка (порядок процедури) не може бути поміщена як прямий нащадок або нащадок плода (Дискретний результат)');
INSERT INTO `lang_definitions` VALUES (189501, 12380, 30, 'Використання технологій для підвищення продуктивності');
INSERT INTO `lang_definitions` VALUES (189502, 12381, 30, 'Використовуючи дані, введені в систему OpenEMR буде генерувати дійсні повідомлення HL7 v2.3 в 3 форматах, текстовий файл, який автоматично завантажується в папку завантажень вашого браузера, повідомлення HL7, яке записується в папку або каталог на сервері, що працює під управлінням OpenEMR, або використовувати SFTP - Secure File Transfer Protocol, який є мережевим протоколом, який забезпечує доступ до файлів, передачу файлів і управління файлами по захищеному з\'єднанню і передачу цього повідомлення в лабораторію.');
INSERT INTO `lang_definitions` VALUES (189503, 12382, 30, 'Використання таблиці зборів');
INSERT INTO `lang_definitions` VALUES (189504, 12383, 30, 'Використання основних рубрик на лабораторному аркуші допоможе запустити цей процес-панелі органів / захворювань, Гематологія, індивідуальні тести, Мікробіологія та інші');
INSERT INTO `lang_definitions` VALUES (189505, 12384, 30, 'Використовуючи цю аналогію з фруктовим деревом, ми можемо краще зрозуміти кроки, необхідні для створення замовлення на панель тестів');
