INSERT INTO `lang_definitions` VALUES (189729, 12630, 30, 'Ми цінуємо своєчасну виплату належних залишків');
INSERT INTO `lang_definitions` VALUES (189730, 12631, 30, 'Ми цінуємо своєчасну виплату належних залишків.');
INSERT INTO `lang_definitions` VALUES (189731, 12632, 30, 'Ми збираємося створити тест, який можна замовити під назвою сироваткова сечова кислота');
INSERT INTO `lang_definitions` VALUES (189732, 12633, 30, 'Ми шкодуємо, що у вас виникли проблеми з вашим обліковим записом.');
INSERT INTO `lang_definitions` VALUES (189733, 12634, 30, 'ми оглянули вашого вищезгаданого пацієнта для обстеження та лікування в нашій амбулаторній психіатричній клініці. Спасибі вам за цей напрямок.');
INSERT INTO `lang_definitions` VALUES (189734, 12635, 30, 'У нас виникли деякі проблеми з підключенням вашого EHR до серверів MedEx');
INSERT INTO `lang_definitions` VALUES (189735, 12636, 30, 'Ми отримали запит на скидання облікових даних. Посилання для скидання ваших облікових даних знаходиться нижче.');
INSERT INTO `lang_definitions` VALUES (189736, 12639, 30, 'Ми не змогли створити обліковий запис.');
INSERT INTO `lang_definitions` VALUES (189737, 12640, 30, 'Ми будемо базувати електролітну панель на основному стовбурі або групі (хімія сироватки)');
INSERT INTO `lang_definitions` VALUES (189738, 12641, 30, 'Ми створимо замовлення на три тести глюкози крові, ТТГ і вітаміну D і згрупуємо його в призначену для користувача групу під назвою well Woman Tests і створимо місце для ручного введення повернутих результатів');
INSERT INTO `lang_definitions` VALUES (189739, 12642, 30, 'Ми пройдемо через процес оформлення замовлення на єдиний аналіз крові-сироватку сечової кислоти');
INSERT INTO `lang_definitions` VALUES (189740, 12643, 30, 'Тепер ми створимо порядок, або порядок процедури, званий панеллю електроліту, яку можна візуалізувати як плодоносну гілку нашого гіпотетичного фруктового дерева');
INSERT INTO `lang_definitions` VALUES (189741, 12644, 30, 'Ми встановимо замовлення на електролітну панель, що складається з сироваткового натрію, калію, хлориду і вуглекислого газу');
INSERT INTO `lang_definitions` VALUES (189742, 12645, 30, 'Почнемо з самого базового блоку модуля Procedure Orders, щоб налаштувати єдиний лабораторний тестовий замовлення і можливість вручну записати результат, що повертається');
INSERT INTO `lang_definitions` VALUES (189743, 12646, 30, 'Ми будемо використовувати дискретний результат для кожного тесту для зберігання повернутих значень результату');
INSERT INTO `lang_definitions` VALUES (189744, 12647, 30, 'Ми будемо використовувати цю гілку для зберігання всіх 9 панелей, тут ми просто створимо замовлення, що представляє одну панель, панель електроліту');
