INSERT INTO `lang_definitions` VALUES (189785, 12693, 30, 'Що являє собою замовлення і який його електронний формат, як він відправляється, як отриманий результат, чи буде система тільки отримувати результати або відправляти замовлення і отримувати результати, до яких лабораторій ви будете підключатися і що має відбутися на іншому кінці, чи буде залучена в цю транзакцію третя сторона чи ні');
