INSERT INTO `lang_definitions` VALUES (189790, 12698, 30, 'Хрипкий:');
INSERT INTO `lang_definitions` VALUES (189791, 12699, 30, 'При створенні нового користувача управління доступом надається адміністратором або Користувачем з аналогічними привілеями шляхом вибору груп (AROS), до яких може належати Користувач.');
INSERT INTO `lang_definitions` VALUES (189792, 12700, 30, 'Коли і як часто?');
INSERT INTO `lang_definitions` VALUES (189793, 12701, 30, 'При перевірці Демографія відкриється в новому вікні з панелі потоку пацієнтів.');
INSERT INTO `lang_definitions` VALUES (189794, 12702, 30, 'При перевірці Останній Персонал, який оновить дошку, буде відображатися на дошці потоку пацієнтів.');
INSERT INTO `lang_definitions` VALUES (189795, 12703, 30, 'При перевірці повідомлення обробляються для пацієнтів з демографічним вибором пацієнта:\" повідомлення HIPAA отримано \"встановлено в\" Непризначене \"або\"так\". Якщо прапорець знятий, цей вибір повинен бути = \"так\", щоб обробити нагадування пацієнта. Для пацієнтів з вибором = \" ні \" нагадування повинні бути оброблені вручну.');
INSERT INTO `lang_definitions` VALUES (189796, 12704, 30, 'При перевірці номер зустрічі пацієнта буде відображатися на дошці потоку пацієнтів.');
INSERT INTO `lang_definitions` VALUES (189797, 12705, 30, 'При перевірці ідентифікатор пацієнта буде відображатися на панелі потоку пацієнтів.');
INSERT INTO `lang_definitions` VALUES (189798, 12706, 30, 'При перевірці Причина відвідування буде Показана на дошці потоку пацієнтів.');
INSERT INTO `lang_definitions` VALUES (189799, 12707, 30, 'При роботі з захищеною медичною інформацією (PHI) і персональною ідентифікаційною інформацією (PII) важливо дозволити доступ до цих даних тільки авторизованим користувачам');
INSERT INTO `lang_definitions` VALUES (189800, 12708, 30, 'Коли закінчите, натисніть кнопку НАДІСЛАТИ (нижче), щоб застосувати свій вибір.');
INSERT INTO `lang_definitions` VALUES (189801, 12709, 30, 'При розміщенні такого замовлення повертаються результати будуть містити значення для всіх компонентів CBC, комплексної метаболічної панелі і ТТГ');
INSERT INTO `lang_definitions` VALUES (189802, 12710, 30, 'Коли згенерований звіт відображається на окремій вкладці, є опція, що дозволяє переглянути друковану версію, яку можна роздрукувати');
INSERT INTO `lang_definitions` VALUES (189803, 12711, 30, 'Коли ключ вперше зареєстрований, він генерує випадкове число, яке називається nonce');
INSERT INTO `lang_definitions` VALUES (189804, 12712, 30, 'Коли користувач вперше відвідає цю сторінку, буде видно наступне повідомлення');
INSERT INTO `lang_definitions` VALUES (189805, 12715, 30, 'Коли ви розміщуєте замовлення, Ви можете знайти тести Well Woman в розділі Вибране і вибрати його, щоб автоматично замовити глюкозу в крові, ТТГ і вітамін D одним клацанням миші');
INSERT INTO `lang_definitions` VALUES (189806, 12716, 30, 'Де можна знайти відповідні відскановані або паперові документи?');
INSERT INTO `lang_definitions` VALUES (189807, 12717, 30, 'Де на вашому тілі це відбувається?');
INSERT INTO `lang_definitions` VALUES (189808, 12718, 30, 'Чи Застрахований');
