INSERT INTO `lang_definitions` VALUES (189810, 12720, 30, 'Які нотатки повинні відображатися на екрані виставлення рахунків');
INSERT INTO `lang_definitions` VALUES (189811, 12721, 30, 'При пересиланні датованого нагадування відображається старе повідомлення, яке може бути перезаписано');
INSERT INTO `lang_definitions` VALUES (189812, 12722, 30, 'Хоча інтуїтивно зрозуміло думати про цей модуль як про місце де можна замовити і переглянути лабораторні тести і дослідження зображень цей модуль також можна використовувати для відстеження інших процедур виконуваних в офісі');
