INSERT INTO `lang_definitions` VALUES (189955, 12872, 30, 'Ви можете закрити вікно редагування, натиснувши на значок \"косе око\" поруч з назвою групи.');
INSERT INTO `lang_definitions` VALUES (189956, 12873, 30, 'Ви можете видалити відгук, натиснувши на кнопку X в правому верхньому куті комірки');
INSERT INTO `lang_definitions` VALUES (189957, 12874, 30, 'Ви можете завантажити файл Loinc Universal LabOrders ValueSet.csv звідси');
INSERT INTO `lang_definitions` VALUES (189958, 12875, 30, 'Ви можете редагувати заголовок, якщо хочете');
INSERT INTO `lang_definitions` VALUES (189959, 12876, 30, 'Ви можете ввести дані в усі 5 категорій з цієї сторінки');
INSERT INTO `lang_definitions` VALUES (189960, 12877, 30, 'При необхідності ви можете пов\'язати алергію з однією або декількома зустрічами');
INSERT INTO `lang_definitions` VALUES (189961, 12878, 30, 'Ви можете пов\'язати ліки з однією або декількома зустрічами, якщо це необхідно');
INSERT INTO `lang_definitions` VALUES (189962, 12879, 30, 'Ви не можете отримати доступ до цієї функції безпосередньо.');
INSERT INTO `lang_definitions` VALUES (189963, 12880, 30, 'Ви не можете змінити статус на \"Прибуття\" до призначеного часу');
INSERT INTO `lang_definitions` VALUES (189964, 12881, 30, 'Ви можете тільки додати до існуючого повідомлення і не можете редагувати раніше введені дані');
INSERT INTO `lang_definitions` VALUES (189965, 12882, 30, 'Ви можете тільки розмістити замовлення на електролітну панель і провести тестування всієї панелі і отримати їх результати назад');
INSERT INTO `lang_definitions` VALUES (189966, 12883, 30, 'Ви можете тільки вибрати');
INSERT INTO `lang_definitions` VALUES (189967, 12884, 30, 'Ви можете шукати і вибирати коди, натиснувши один раз на кожен рядок, що містить код');
INSERT INTO `lang_definitions` VALUES (189968, 12885, 30, 'Ви можете відсортувати відкладені повідомлення в порядку зростання або спадання, натиснувши на стрілку в кожній комірці заголовка таблиці');
INSERT INTO `lang_definitions` VALUES (189969, 12886, 30, 'Потім ви можете перейти до зв\'язування знову доданої проблеми з encounters');
INSERT INTO `lang_definitions` VALUES (189970, 12887, 30, 'Ви можете завантажувати контент і маркувати його кодом ICD10, що дозволить вам шукати і завантажувати обраний матеріал');
INSERT INTO `lang_definitions` VALUES (189971, 12888, 30, 'Ви можете використовувати коди LOINC для стандартних кодів');
INSERT INTO `lang_definitions` VALUES (189972, 12889, 30, 'Ви можете використовувати описаний вище метод для створення замовлень для інших Панелей органів / захворювань, за винятком панелі загального здоров\'я, яка складається з CBC, комплексної метаболічної панелі і TSH, а також акушерської панелі, яка має CBC в якості одного зі своїх компонентів');
INSERT INTO `lang_definitions` VALUES (189973, 12890, 30, 'Ви можете використовувати коди, зазначені на паперовому лабораторному аркуші місцевої лабораторії великої лабораторії, як ідентифікуючі коди');
INSERT INTO `lang_definitions` VALUES (189974, 12891, 30, 'Ви не можете отримати доступ до цієї сторінки безпосередньо.');
INSERT INTO `lang_definitions` VALUES (189975, 12892, 30, 'Ви не можете додати порожнє значення для категорії!');
INSERT INTO `lang_definitions` VALUES (189976, 12893, 30, 'Ви не можете додати порожнє значення для підкатегорії!');
INSERT INTO `lang_definitions` VALUES (189977, 12894, 30, 'Ви не можете додати порожнє значення для елемента!');
INSERT INTO `lang_definitions` VALUES (189978, 12895, 30, 'Ви не можете редагувати вже обрану лабораторію, якщо відправляєте в іншу лабораторію віддалений запис і створюєте нову');
INSERT INTO `lang_definitions` VALUES (189979, 12896, 30, 'Ви не можете ввести майбутню дату з завершеним значенням YES.');
INSERT INTO `lang_definitions` VALUES (189980, 12897, 30, 'Ви можете вручну відредагувати цю дату, якщо захочете, або зовсім іншу дату');
INSERT INTO `lang_definitions` VALUES (189981, 12898, 30, 'Ви не вибирали ніяких дій.');
INSERT INTO `lang_definitions` VALUES (189982, 12899, 30, 'У вас немає доступу до перегляду / редагування цієї замітки');
INSERT INTO `lang_definitions` VALUES (189983, 12900, 30, 'У тебе є');
INSERT INTO `lang_definitions` VALUES (189984, 12901, 30, 'У вас є рахунок-фактура, що підлягає оплаті в документах вашого пацієнта. Там ви можете оплатити, завантажити або роздрукувати рахунок. Дякую.');
INSERT INTO `lang_definitions` VALUES (189985, 12902, 30, 'Ви спробували змінити вміст, який заблоковано. Зніміть замок, якщо ви хочете це зробити. Щоб розблокувати, видаліть рядок \'/*lock::*/\'');
INSERT INTO `lang_definitions` VALUES (189986, 12903, 30, 'Ви були виписані. Дякую.');
INSERT INTO `lang_definitions` VALUES (189987, 12904, 30, 'Ви успішно вийшли з системи.');
INSERT INTO `lang_definitions` VALUES (189988, 12905, 30, 'Ви вибрали самострахування або в даний час не маєте страховки. Натисніть кнопку Далі, щоб продовжити реєстрацію.');
INSERT INTO `lang_definitions` VALUES (189989, 12906, 30, 'Ви закінчили оцінку.');
INSERT INTO `lang_definitions` VALUES (189990, 12907, 30, 'Ви не ввели ніяких клінічних послуг або продуктів. Натисніть кнопку Скасувати, щоб додати їх. Або натисніть кнопку ОК, якщо ви хочете зберегти як є.');
INSERT INTO `lang_definitions` VALUES (189991, 12908, 30, 'Тепер ви успішно виконали замовлення на один лабораторний тест');
INSERT INTO `lang_definitions` VALUES (189992, 12909, 30, 'Ви вибрали для видалення');
INSERT INTO `lang_definitions` VALUES (189993, 12910, 30, 'Ви повинні мати уявлення про те, як структурована програма, а також здатність і готовність змінювати базовий код.');
INSERT INTO `lang_definitions` VALUES (189994, 12911, 30, 'У вас є незбережені зміни.');
INSERT INTO `lang_definitions` VALUES (189995, 12912, 30, 'У вас є незбережені зміни. Кинути їх?');
INSERT INTO `lang_definitions` VALUES (189996, 12913, 30, 'У вас є незбережені зміни. Ви дійсно хочете закрити цю форму?');
INSERT INTO `lang_definitions` VALUES (189997, 12914, 30, 'Вам може знадобитися змінити пароль при першому вході в систему.');
INSERT INTO `lang_definitions` VALUES (189998, 12915, 30, 'Ви можете завантажувати лише файли .txt');
INSERT INTO `lang_definitions` VALUES (189999, 12916, 30, 'Ви можете додатково завантажити результати HL7 з файлу');
INSERT INTO `lang_definitions` VALUES (190000, 12917, 30, 'Ви можете помістити текст тут в якості скарги за замовчуванням в новій формі зустрічі з пацієнтом.');
INSERT INTO `lang_definitions` VALUES (190001, 12919, 30, 'Ви все ще можете використовувати форматування, якщо шаблон також використовується в Nation Notes, однак чистий текст все одно буде відображатися тут.');
INSERT INTO `lang_definitions` VALUES (190002, 12920, 30, 'Ви можете ввести ім\'я людини, що посилається на вас, або залишити його порожнім');
INSERT INTO `lang_definitions` VALUES (190003, 12921, 30, 'Можливо, ви захочете повернутися на попередню сторінку і переконатися, що всі поля заповнені правильно.');
INSERT INTO `lang_definitions` VALUES (190004, 12922, 30, 'Спочатку ви повинні активувати Weno! Перейти до адміністрування, Глобалів, З\'єднувачів');
INSERT INTO `lang_definitions` VALUES (190005, 12924, 30, 'Ви повинні погодитися з Угодою HIPAA Business Associate Agreement');
INSERT INTO `lang_definitions` VALUES (190006, 12925, 30, 'Ви повинні погодитися з умовами та положеннями перед реєстрацією');
INSERT INTO `lang_definitions` VALUES (190007, 12926, 30, 'Ви повинні підтвердити це ім\'я користувача.');
INSERT INTO `lang_definitions` VALUES (190008, 12927, 30, 'Ви повинні ввести новий або повторно ввести поточний пароль, щоб зберегти його. Навіть для зміни імені користувача.');
INSERT INTO `lang_definitions` VALUES (190009, 12928, 30, 'Для шифрування документа необхідно ввести парольну фразу');
INSERT INTO `lang_definitions` VALUES (190010, 12929, 30, 'Ви повинні вказати причину скасування цієї зустрічі?');
INSERT INTO `lang_definitions` VALUES (190011, 12930, 30, 'Ви повинні ввести свій власний пароль, щоб змінити паролі користувачів. Залиште поле порожнім, щоб зберегти пароль незмінним.');
INSERT INTO `lang_definitions` VALUES (190012, 12931, 30, 'Спочатку необхідно вибрати елемент в розділі, перемикач якого встановлений.');
INSERT INTO `lang_definitions` VALUES (190013, 12932, 30, 'Спочатку необхідно вибрати або додати пацієнта або групу терапії.');
INSERT INTO `lang_definitions` VALUES (190014, 12933, 30, 'Спочатку ви повинні вибрати або додати пацієнта.');
INSERT INTO `lang_definitions` VALUES (190015, 12934, 30, 'Спочатку ви повинні вибрати або створити зустріч.');
INSERT INTO `lang_definitions` VALUES (190016, 12936, 30, 'Ви повинні вибрати категорію відвідування');
INSERT INTO `lang_definitions` VALUES (190017, 12937, 30, 'Ви повинні вибрати категорію відвідування.');
INSERT INTO `lang_definitions` VALUES (190018, 12938, 30, 'Ви повинні вибрати деякі поля, щоб продовжити.');
INSERT INTO `lang_definitions` VALUES (190019, 12939, 30, 'Вам потрібні права адміністратора, щоб додати додаткові параметри');
INSERT INTO `lang_definitions` VALUES (190020, 12940, 30, 'Вам потрібні права адміністратора, щоб відключити плату відкликання за замовчуванням');
INSERT INTO `lang_definitions` VALUES (190021, 12941, 30, 'Вам потрібні права адміністратора, щоб включити службу Зв\'язку MedEx');
INSERT INTO `lang_definitions` VALUES (190022, 12942, 30, 'Вам потрібні права адміністратора, щоб надати доступ до інших груп');
INSERT INTO `lang_definitions` VALUES (190023, 12943, 30, 'Вам потрібні права адміністратора, щоб збільшити кількість відображуваних нагадувань');
INSERT INTO `lang_definitions` VALUES (190024, 12944, 30, 'Вам потрібні права адміністратора для виконання змін значень у розкривних вікнах.');
INSERT INTO `lang_definitions` VALUES (190025, 12945, 30, 'Для виконання установки вам потрібні права адміністратора');
INSERT INTO `lang_definitions` VALUES (190026, 12946, 30, 'Для виконання цієї дії вам потрібні права адміністратора');
INSERT INTO `lang_definitions` VALUES (190027, 12947, 30, 'Вам потрібно повернутися назад і створити провайдера');
INSERT INTO `lang_definitions` VALUES (190028, 12948, 30, 'Ви повинні запустити цей тест, якщо це твердження виявилося згенерованим успішно, але фактичний файл затвердження не містить ніяких даних або тільки незавершену частину обсягу даних, які він повинен містити. Це очевидно з твердженнями HCFA, тому що вони читаються для людини, з твердженнями X12 це більш складний процес, щоб визначити, чи є твердження належним чином повним.');
INSERT INTO `lang_definitions` VALUES (190029, 12949, 30, 'Ви не повинні робити Дискретний результат для калію нащадком попереднього Дискретного результату, тобто натрію, тобто мати значення Рівня 5');
INSERT INTO `lang_definitions` VALUES (190030, 12950, 30, 'Ви повинні вибрати принаймні один контекст');
INSERT INTO `lang_definitions` VALUES (190031, 12951, 30, 'Ви повинні вибрати хоча б одного постачальника');
INSERT INTO `lang_definitions` VALUES (190032, 12952, 30, 'Ви будете автоматично перенаправлені на демографію. Ви можете внести необхідні виправлення і знову перейти до NewCrop.');
