INSERT INTO `lang_definitions` VALUES (190308, 2, 31, 'شماره چک یا شماره پرونده برای پیگیری پرداخت');
INSERT INTO `lang_definitions` VALUES (190309, 3, 31, 'برای فعال کردن این منو باید یک شماره پرونده انتخاب شود.');
INSERT INTO `lang_definitions` VALUES (190310, 4, 31, 'گواهی کاربر برای کاربر مدیر');
INSERT INTO `lang_definitions` VALUES (190311, 5, 31, 'یک قانون تصمیم بالینی اطلاعات مختص به بیمار است که برای بهبود سلامت و حفظ سلامتی فیلتر شده و در زمان مناسب ارائه میشود');
INSERT INTO `lang_definitions` VALUES (190312, 6, 31, 'یک سند بالینی پیوست شده است');
INSERT INTO `lang_definitions` VALUES (190313, 7, 31, 'یک سند بالینی پیوست شده است.');
INSERT INTO `lang_definitions` VALUES (190314, 8, 31, 'قبلا یک کد از این نوع انتخاب شده است. برای جایگزینی آن ، ابتدا فیلد را پاک کنید');
INSERT INTO `lang_definitions` VALUES (190315, 9, 31, 'یک پیام یادآوری تاریخ دار می تواند با کلیک کردن روی دکمه \"هدایت پیام\"به جا ی دیگری ارسال شود یا با کلیک بر روی دکمه \"تنظیم به عنوان تکمیل شده\" از لیست یادآوری های تاریخ دار حذف شود');
INSERT INTO `lang_definitions` VALUES (190316, 10, 31, 'باید یک کلید امنیتی اختصاصی خریداری شود');
INSERT INTO `lang_definitions` VALUES (190317, 11, 31, 'کد پیش فرض اختیاری است زیرا کد مورد نیاز می تواند در زمان ثبت سفارش واقعی وارد شود');
INSERT INTO `lang_definitions` VALUES (190318, 12, 31, 'یک راهنمای دقیق در مورد چگونگی فعال کردن و تنظیم قانون تصمیم بالینی در اینجا یافت می شود');
INSERT INTO `lang_definitions` VALUES (190319, 13, 31, 'توزیع کننده ای مورد نیاز است');
INSERT INTO `lang_definitions` VALUES (190320, 14, 31, 'می توان یک تاریخ سررسید مشخص کرد یا یک دوره زمانی خاص را برای نشان دادن یادآور تاریخ دار انتخاب کرد');
INSERT INTO `lang_definitions` VALUES (190321, 15, 31, 'چند کلمه برای نشان دادن دلیل بازدید');
INSERT INTO `lang_definitions` VALUES (190322, 16, 31, 'قرار ملاقات بعدی از طریق برگه هزینه نیز می تواند تعیین شود.');
INSERT INTO `lang_definitions` VALUES (190323, 17, 31, 'یک فرم ملاقات GCAC باید به این ملاقات اضافه شود.');
INSERT INTO `lang_definitions` VALUES (190324, 18, 31, 'یک پیام HL7 نسخه 2.x به سادگی از چندین خط متن تشکیل شده است ، هر سطر را یک قطعه می نامند و با استفاده از کاراکتر خط عمودی \"|\" به بخشهای مختلف تقسیم می شود');
INSERT INTO `lang_definitions` VALUES (190325, 19, 31, 'یک برنامه بزرگ مانند openEMR توسط بسیاری از کاربران با نقش و درجه مسئولیت های متفاوت مورد استفاده قرار می گیرد. ضروری است که دسترسی به قسمتهای مختلف برنامه بر اساس نیاز به کاربران به آنها داده شود. برای دستیابی به این هدف - از لیست های کنترل دسترسی (ACL) استفاده می شود.');
INSERT INTO `lang_definitions` VALUES (190326, 20, 31, 'شماره سری مورد نیاز است');
INSERT INTO `lang_definitions` VALUES (190327, 21, 31, 'شماره سری مورد نیاز است!');
INSERT INTO `lang_definitions` VALUES (190328, 22, 31, 'یک حرف کوچک');
INSERT INTO `lang_definitions` VALUES (190329, 23, 31, 'یک قرار جدید');
INSERT INTO `lang_definitions` VALUES (190330, 24, 31, 'یک ویژگی جدید که به گروه بندی تست های مرتب سفارش شده کمک می کند تا بتوان آنها را با هم سفارش داد');
INSERT INTO `lang_definitions` VALUES (190331, 25, 31, 'بنابراین یک پیام جدید می تواند برای یک یا چند کاربر ارسال شود و / یا می تواند در مورد یک یا چند بیمار باشد');
INSERT INTO `lang_definitions` VALUES (190332, 27, 31, 'یک زیر منوی جدید در بالای صفحه ی مرکز پیام قابل مشاهده خواهد بود');
INSERT INTO `lang_definitions` VALUES (190333, 28, 31, 'یک شماره');
INSERT INTO `lang_definitions` VALUES (190334, 29, 31, 'برای تولید این گزارش ، یک بیمار باید انتخاب شود');
INSERT INTO `lang_definitions` VALUES (190335, 30, 31, 'اکنون بیماری با این شماره شناسایی وجود دارد.');
INSERT INTO `lang_definitions` VALUES (190336, 31, 31, 'اکنون بیماری با این نام وجود دارد.');
INSERT INTO `lang_definitions` VALUES (190337, 32, 31, 'اکنون بیماری با این شماره(کد ملی) وجود دارد.');
INSERT INTO `lang_definitions` VALUES (190338, 33, 31, 'ثبت پرداخت لازم است !. لطفاً یک مورد از آیتم های پرداخت را وارد کنید.');
INSERT INTO `lang_definitions` VALUES (190339, 34, 31, 'مکانی برای ثبت و نمایش سابقه پزشکی گذشته بیمار ، سابقه خانوادگی ، سابقه شخصی بیمار');
INSERT INTO `lang_definitions` VALUES (190340, 35, 31, 'یک پنجره پاپ آپ موفقیت یا شکست را به شما اطلاع خواهد داد');
INSERT INTO `lang_definitions` VALUES (190341, 36, 31, 'یک عدد مثبت به همان مقدار ملاقات اخیر را در صفحه خلاصه بیمار نمایش میدهد(یک عدد منفی قرارهای گذشته را به ترتیب نزولی نشان می دهد)');
INSERT INTO `lang_definitions` VALUES (190342, 37, 31, 'یک عدد مثبت به همان مقدار ملاقات اخیر را در صفحه خلاصه بیمار نمایش میدهد(یک عدد منفی قرارهای گذشته را به ترتیب نزولی نشان می دهد)');
INSERT INTO `lang_definitions` VALUES (190343, 38, 31, 'یک محصول انتخاب شده است اما در این فرم بخشی مربوط به محصول وجود ندارد.');
INSERT INTO `lang_definitions` VALUES (190344, 39, 31, 'یک ارائه دهنده یا انبار را می توان در منوی کشویی انتخاب کرد. برای اینکه این گزینه نمایش داده شود ، گزینه \"قابلیت ورود آیتم ارائه دهنده در خط در برگه هزینه\" باید در بخش مدیریت> تنظیمات کلی> صفحه صورتحساب علامت گذاری شود');
INSERT INTO `lang_definitions` VALUES (190345, 42, 31, 'یک ارجاع دهنده یک اقدام اضافی دارد - برای چاپ ارجاع یا ذخیره آن به عنوان یک فایل pdf');
INSERT INTO `lang_definitions` VALUES (190346, 44, 31, 'برای هر بازدید میتواند یک منبع ارجاع مشخص شود.');
INSERT INTO `lang_definitions` VALUES (190347, 45, 31, 'به یک کد IPPF مرتبط نیاز است!');
INSERT INTO `lang_definitions` VALUES (190348, 46, 31, 'برای تایید هویت دومرحله ای به ارتباط امن وب HTTPS نیاز است');
INSERT INTO `lang_definitions` VALUES (190349, 47, 31, 'شرح مختصری از این گروه هنگام قرار گرفتن نشانگر موس بر روی گروه تازه ایجاد شده (ARO) ظاهر می شود.');
INSERT INTO `lang_definitions` VALUES (190350, 48, 31, 'شرح مختصری از این گروه ، آزمایشات شیمی خون');
INSERT INTO `lang_definitions` VALUES (190351, 49, 31, 'شرح مختصری از این روش یا کد نتیجه');
INSERT INTO `lang_definitions` VALUES (190352, 52, 31, 'یک حرف ویژه');
INSERT INTO `lang_definitions` VALUES (190353, 53, 31, 'برای ارائه مطالبات از فرم استانداردی به نام فرم مطالبه بیمه سلامت استفاده می شود');
INSERT INTO `lang_definitions` VALUES (190354, 54, 31, 'گزینه سوم اسکن نتایج و ذخیره آن به عنوان یک سند با فرمت های TIFF ، JPEG یا PDF در نمودار بیمار در زیرمنوی اسناد است');
INSERT INTO `lang_definitions` VALUES (190355, 55, 31, 'یک فرم دو برگه ای نشان داده خواهد شد');
INSERT INTO `lang_definitions` VALUES (190356, 56, 31, 'یک مقدار منحصر به فرد برای شناسایی این فیلد، برای کاربر قابل مشاهده نیست');
INSERT INTO `lang_definitions` VALUES (190357, 57, 31, 'یک شروع درست این است که از چند آزمایشگاه برگه آزمایش تهیه کنید و به نحوه چینش آزمایشات در برگه آزمایشگاه نگاه کنید');
INSERT INTO `lang_definitions` VALUES (190358, 59, 31, 'امروز یک بازدید برای این گروه وجود دارد. برای باز کردن ، لغو را کلیک کنید یا برای ادامه کار با ایجاد یک گروه جدید تأیید را کلیک کنید.');
