INSERT INTO `lang_definitions` VALUES (190832, 626, 31, 'همچنین میتوانید تمام آیتم های انتخاب شده را پاک کنید و فقط آیتم های مورد نظر برای گزارش را انتخاب کنید');
INSERT INTO `lang_definitions` VALUES (190833, 627, 31, 'همچنین میتوانید حواله الکترونیکی یا رسید پرداخت خود را آپلود کنید. برای این کار در بخش \"انتخاب روش\" \"آپلود رسید\" را انتخاب کنید که باعث نمایش بخش \"آپلود رسید\" میشود');
INSERT INTO `lang_definitions` VALUES (190834, 628, 31, 'همچنین شما میتوانید با استفاده از صفحه جست و جو رسید الکترونیکی یا رسید پرداخت خود را آپلود کنید.این کار را می توانید با کلیک روی دکمه Browse و انتخاب فایل برای آپلود و سپس کلیک بر روی Search برای بارگذاری و نمایش فاکتورهای مربوطه انجام دهید. در این حالت سایر پارامترهای ذکر شده در بالا اعمال نمی شوند و نادیده گرفته می شوند.بارگذاری فایل باعث ذخیره آن میشود ولی محتوای آن هنوز پردازش نشده است و لازم است که به صورت جداگانه انجام شود که شرح آن در زیر آمده است.');
INSERT INTO `lang_definitions` VALUES (190835, 629, 31, 'اگر چه HCFA-1500 در اصل برای ارسال ادعاهای مدیکر توسعه داده شد، آن را در نهایت همه / حامل بیمه تجاری خصوصی برای تسهیل استاندارد سازی فرایند ادعاهای پذیرفته شد');
