INSERT INTO `lang_definitions` VALUES (190877, 674, 31, 'ایمیلی با مشخصات حساب جدید شما به آدرس ایمیلی که قبلاً وارد کردید ارسال می شود. هنوز هم می توانید با استفاده از دکمه های مرحله در بالای صفحه برای رفتن به پنل های مناسب ، هر قسمت از اطلاعات خود را مرور یا ویرایش کنید. مطمئن شوید آدرس ایمیل خود را صحیح وارد کرده اید. اگر پس از دریافت ایمیل در دسترسی به پورتال مشکل دارید ، لطفا با پشتیبانی تماس بگیرید.');
INSERT INTO `lang_definitions` VALUES (190878, 675, 31, 'یک دستور الکترونیکی و نتیجه برگشتی به صورت پیامی، پیام HL7 نامیده میشود. HL7 مخفف سطح سلامتی 7 است. هدف اصلی HL7 ساده سازی اجرای رابط های بین برنامه های نرم افزاری مراقبت های بهداشتی و تامین کنندگان مختلف است تا از این طریق دردسر و هزینه های برنامه نویسی رابط سفارشی کاهش یابد.');
INSERT INTO `lang_definitions` VALUES (190879, 676, 31, 'تاریخ پایان بعد از تاریخ شروع برای رویدادهای تکرار شونده مورد نیاز است!');
