INSERT INTO `lang_definitions` VALUES (190883, 680, 31, 'خطایی در ذخیره خروجی دایرکتوری درختی برنامه SQL-Ledger رخ داد');
INSERT INTO `lang_definitions` VALUES (190884, 682, 31, 'خطایی رخ داد: فایل انتخاب شده برای آپلود پیدا نشد: دکمه بازگشت را بزنید!');
INSERT INTO `lang_definitions` VALUES (190885, 683, 31, 'یک مفهوم مهم برای درک این است که هنگامی که secret key تحویل شده از طریق کد QR توسط برنامه احراز هویت گرفته می شود ، دیگر ارتباطی بین برنامه و OpenEMR وجود ندارد ، هر یک از زمان UNIX فعلی و کپی آن از secret key مشترک کاربر برای تولید یک شماره 6 رقمی منحصر به فرد یکسان استفاده میکنند.');
INSERT INTO `lang_definitions` VALUES (190886, 684, 31, 'نکته مهمی که باید بخاطر بسپارید این است که آزمونهای مختلف افراد در هر پنل به عنوان نتایج لیست شده اند ، شما نمی توانید مستقیماً تک تک این تستها را سفارش دهید');
INSERT INTO `lang_definitions` VALUES (190887, 685, 31, 'یک مورد ناقص جهانی مراقبت از سقط جنین ایجاد و پیوند داده شده است. بعداً باید شخصی آن را تکمیل کند.');
