INSERT INTO `lang_definitions` VALUES (191432, 1302, 31, 'جعبه 17 - نام وارد شده ارائه دهنده ارجاع شده، ارائه دهنده سفارش یا تأمین کننده نظارتی است که سرویس ها یا عرضه های ادعا را ارجاع ، سفارش یا نظارت کرده است. اگر چندین ارائه دهنده درگیر هستند ، با استفاده از ترتیب اولویت زیر یک ارائه دهنده را وارد کنید: 1. ارائه دهنده ارجاع ، 2. ارائه دهنده سفارش ، 3. ارائه دهنده نظارت.');
