INSERT INTO `lang_definitions` VALUES (191674, 1562, 31, 'هر مورد موجود را تغییر دهید و پس از آماده شدن روی ارسال برای بررسی کلیک کنید. این تغییرات علامت گذاری شده و قبل از انجام تغییرات در نمودار ، به کارکنان جهت بررسی تغییرات اطلاع داده می شود. در طول دوره زمانی قبل از بررسی تغییرات ، دکمه بازبینی شده در حالت انتظار است و داده های پروفایل همچنان برای تغییرات در دسترس هستند. هنگام دسترسی به پروفایل در حالت تعلیق ، همه ویرایش های قبلی با رنگ آبی و مقادیر نمودار فعلی با رنگ قرمز ظاهر می شوند. با کلیک روی آن مورد قرمز (یا نسخه بالعکس) ممکن است هر ویرایشی را به مقدار اولیه نمودار برگردانید اما به یاد داشته باشید که وقتی روی ارسال برای بررسی کلیک می کنید ، مواردی که نمایش داده شده اند مواردی هستند که ارسال می شوند. دکمه بازگردانی مقادیر همه چیز را به مقادیر اولیه نمودار تغییر می دهد و میتوانید از آنجا تغییراتی ایجاد کنید. بنابراین ، یادآوری می کنیم: موارد به رنگ آبی ، ویرایش های بیمار است و موارد قرمز مقادیر اصلی قبل از ویرایش شدن هستند.');
