INSERT INTO `lang_definitions` VALUES (191858, 1782, 31, 'برای صادر کردن دسته ، زیر مجموعه ، مورد ، مورد محتوا به یک پرونده متنی ، بر \"صادرات\" کلیک کنید. هرگونه شباهت این پرونده به یک فایل XML کاملاً تصادفی است. برچسب های باز و بسته باید در یک خط باشند ، آنها باید کوچک و بدون فاصله باشند. برای وارد کردن ، یک فایل را جستجو کنید و \"وارد کردن\" را کلیک کنید. اگر داده ها کاملاً متفاوت باشند ، با داده های موجود شما ادغام می شوند. اگر نام موارد مشابه وجود داشته باشد ، نام قدیمی نگهداری می شود و مورد جدید با اضافه شدن شماره به انتها ذخیره می شود.');
