INSERT INTO `lang_definitions` VALUES (192022, 1969, 31, 'با کلیک بر روی زبانه ورود نام یا ورود آیدی کادر جستجو ظاهر می شود که می توانید برای انتخاب بیمار استفاده کنید');
INSERT INTO `lang_definitions` VALUES (192023, 1970, 31, 'با کلیک بر روی تنظیم به عنوان تکمیل ، یادآوری از صفحه نمایش فعال حذف می شود');
INSERT INTO `lang_definitions` VALUES (192024, 1971, 31, 'با کلیک بر روی دکمه + در صفحه هدر بیمار ، فرم برخورد جدید باز می شود');
INSERT INTO `lang_definitions` VALUES (192025, 1972, 31, 'با کلیک بر روی دکمه افرودن مشکل جعبه بازشونده افزودن مشکل ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (192026, 1973, 31, 'با کلیک بر روی سلول کدگذاری ، پاپ آپ مواد آموزشی ظاهر می شود که به شما امکان می دهد با کد ICD10 جستجو کنید');
INSERT INTO `lang_definitions` VALUES (192027, 1974, 31, 'با کلیک بر روی دکمه ایجاد یک یادآوری تاریخ دار ، پنجره ارسال یک یادآور ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (192028, 1975, 31, 'با کلیک بر روی دکمه ایجاد اعتبارنامه آنلاین / پورتال خارج از سایت ، نام کاربری و رمز عبور برای بیمار ایجاد می شود که باید به بیمار داده شود.');
INSERT INTO `lang_definitions` VALUES (192029, 1976, 31, 'با کلیک بر روی دکمه حذف پیام حذف می شود');
INSERT INTO `lang_definitions` VALUES (192030, 1977, 31, 'با کلیک بر روی سلول اول زیر عنوان ، صفحه بازشونده افزودن/ویرایش مشکلات ظاهر می شود که به شما امکان می دهد این مقاله را ویرایش کنید');
INSERT INTO `lang_definitions` VALUES (192031, 1978, 31, 'با کلیک بر روی نماد کنار زیرنویس ، پیام های همه نمایش داده می شود و عنوان به همه پیام ها تغییر می کند');
INSERT INTO `lang_definitions` VALUES (192032, 1979, 31, 'با کلیک بر روی نماد کنار نام آنها ، پنجره \"ویرایش\" ظاهر می شود.');
INSERT INTO `lang_definitions` VALUES (192033, 1980, 31, 'با کلیک بر روی گزینه های دیگر> گزینه منو مدیریت MFA یا نام کاربری> مورد منوی مدیریت MFA شما را به صفحه فرود برای مدیریت صفحه احراز هویت چند عاملی برای آن کاربر می رساند');
INSERT INTO `lang_definitions` VALUES (192034, 1981, 31, 'با کلیک بر روی نام بیمار ، پیام ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (192035, 1982, 31, 'با کلیک بر روی نماد مداد وارد حالت ویرایش می شوید و پنجره بازشوی ورود جزئیات که برای ایجاد ورودی نمایش داده شده در این خط استفاده شده است نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (192036, 1983, 31, 'با کلیک بر روی دکمه های نمایش همه یا نمایش غیر فعال پیام های متناسب نشان داده می شود');
INSERT INTO `lang_definitions` VALUES (192037, 1984, 31, 'با کلیک بر روی نماد چشم برش خورده فیلترها پنهان می شوند');
