INSERT INTO `lang_definitions` VALUES (192039, 1986, 31, 'با کلیک روی گزینه ها ، یک منوی چند گزینه ای برای اضافه کردن رفتارها به نوع داده انتخاب شده ، نمایش داده می شود. تایپ کردن پس از فعال کردن کشیدن به پایین ، امکان جستجو در گزینه ها را فراهم می کند.');
INSERT INTO `lang_definitions` VALUES (192040, 1987, 31, 'با کلیک بر روی دکمه ، پنجره ای ظاهر می شود که کدهای E / M را لیست می کند ، کد مناسب را بررسی کرده و \"تأیید\" را کلیک کنید');
