INSERT INTO `lang_definitions` VALUES (192829, 2889, 31, 'بسته به نوع صورتحسابی که در حال آزمایش هستید ، HCFA مانند خروجی را در یک صفحه خالی برای صورتحساب های HCFA مشاهده خواهید کرد ، در صورت آزمایش ادعای X12 ، تعداد زیادی متن و متن تا حدودی مبهم را مشاهده خواهید کرد. این متن مبهم قالب X12 EDI 4010A است. گاهی اوقات کاراکترهای عجیب و غریب را مشاهده می کنید که شبیه دومینو یا عصا هستند ، اینها شخصیت های کنترلی مانند فیدهای صفحه هستند و طبیعی هستند.');
