INSERT INTO `lang_definitions` VALUES (194464, 4737, 31, 'به قسمت Administration> Lists بروید ، از کادر کشویی هر یک از لیست های فوق را انتخاب کرده و در صورت لزوم تغییراتی را اعمال کنید');
INSERT INTO `lang_definitions` VALUES (194465, 4738, 31, 'به مدیریت> لیست ها بروید.\"Fee Sheet\" را از کادر کشویی انتخاب کنید');
INSERT INTO `lang_definitions` VALUES (194466, 4739, 31, 'به Adminstration> Codes بروید.ICD 10 را در Type تایپ کنید ، ICD 10 Code را وارد کنید ، Description را وارد کنید ، در زیر دسته بندی یک دسته مناسب را انتخاب کنید ، سپس با کلیک روی دکمه مربوط به آن دسته ، این کد ICD 10 ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (194467, 4740, 31, 'به قسمت Administration> Lists بروید و «Code Types» را از کادر کشویی انتخاب کنید.از ICD 9 یا ICD 10 استفاده کنید ، ICD 9 غیرفعال است و \"آخرین\" را در آخرین کادر کشویی زیر ICD 10 انتخاب کنید');
