INSERT INTO `lang_definitions` VALUES (194795, 5096, 31, 'اگر یک پایگاه داده Field Col = 0 فیلد داده بلافاصله پس زمینه برچسب خود را در همان خط دنبال کنید');
INSERT INTO `lang_definitions` VALUES (194796, 5097, 31, 'اگر یک برچسب Field Col = 0 برچسب بلافاصله بعد از فیلد داده قبلی را در ترتیب سفارش، در همان خط به عنوان فیلد داده دنبال کنید.');
INSERT INTO `lang_definitions` VALUES (194797, 5098, 31, 'اگر یک برچسب فیلد Col = 1 فیلد برچسب به یک خط جدید برود، مگر اینکه مقادیر کل ستون قبلی (برچسب + داده) کمتر از تعداد ستون های طرح از خواص گروه یا خواص طرح بندی باشد.');
INSERT INTO `lang_definitions` VALUES (194798, 5099, 31, 'اگر یک محصول به فروش می رسد، پیش فرض را تغییر دهید تا منعکس کننده شماره مورد نیاز باشد.آن را در یکی برای مراحل ترک کنید');
INSERT INTO `lang_definitions` VALUES (194799, 5100, 31, 'اگر یک کد اشتباه انتخاب شده بر روی جعبه متن کدگذاری کلیک کنید تا صفحه Pop-up را انتخاب کنید');
INSERT INTO `lang_definitions` VALUES (194800, 5101, 31, 'اگر تمام داده ها برای تمام ستون ها برای این فرم کامل شوند');
INSERT INTO `lang_definitions` VALUES (194801, 5102, 31, 'اگر تمام جزئیات وارد شده به درستی شما گلوکز خون را در ستون نام با یک نوار عمودی مشاهده کنید قبل از اینکه نشان می دهد که هیچ فرزندی یا فرزند ندارد، به ستون رده، WWT01R در ستون کد منجر می شود، مقدار ستون سطح باید 3 باشدو ستون توصیفی باید نتیجه گلوکز روزه بگیرد');
INSERT INTO `lang_definitions` VALUES (194802, 5103, 31, 'اگر توجیه صورتحساب استفاده شود، نام کد تشخیص را وارد کنید.');
INSERT INTO `lang_definitions` VALUES (194803, 5104, 31, 'اگر به درستی پیکربندی شده، ستون نام باید گلوکز خون را با یک نوار عمودی بگوید قبل از اینکه نشان دهنده هیچ فرزندی یا فرزندان باشد، ستون رده باید سفارش سفارشی را بگوید و هر دو نام و ستون های دسته بندی شده در صورتی نشان داده شده است که نشان دهنده یک سفارش سفارشی گروهی است');
INSERT INTO `lang_definitions` VALUES (194804, 5105, 31, 'اگر پیام فعلی را می توان چاپ کرد');
INSERT INTO `lang_definitions` VALUES (194805, 5106, 31, 'در صورت فعال بودن، این زمان اجرای آن را برای تأیید هش به ورود به سیستم PHP ارسال می کند.');
INSERT INTO `lang_definitions` VALUES (194806, 5107, 31, 'اگر فعال شود، از LDAP برای ورود و احراز هویت استفاده کنید.');
INSERT INTO `lang_definitions` VALUES (194807, 5108, 31, 'اگر فعال شود، از دایرکتوری مشخص شده برای ورود و احراز هویت استفاده می کند.');
INSERT INTO `lang_definitions` VALUES (194808, 5109, 31, 'اگر وارد شد، تنها کسانی را انتخاب کنید که این سرویس را داشته باشند');
INSERT INTO `lang_definitions` VALUES (194809, 5110, 31, 'اگر آن را هنوز هم فعال است I.E. تاریخ پایان وارد نشده است آن را به صورت قرمز نمایش داده می شود، اگر مشکل تاریخ پایان است، آن را در سیاه نمایش داده خواهد شد');
INSERT INTO `lang_definitions` VALUES (194810, 5111, 31, 'اگر نام، هر بخش از نام خانوادگی یا آخرین نام خانوادگی، نام خانوادگی');
INSERT INTO `lang_definitions` VALUES (194811, 5112, 31, 'اگر NewCrop ERX - ماژول نسخه الکترونیکی، دکمه های وضعیت حساب کاربری NewCrop را فعال می کند و دکمه های وضعیت حساب NewCrop در اینجا ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (194812, 5113, 31, 'اگر لیست نشده اید، می توانید دارو را به جعبه متن عنوان اضافه کنید');
INSERT INTO `lang_definitions` VALUES (194813, 5115, 31, 'اگر فقط کد QR را ضبط کنید، اما کلید TOTP را با OpenEMR ثبت نکنید این ویژگی در ورود به سیستم فعال نخواهد شد');
INSERT INTO `lang_definitions` VALUES (194814, 5116, 31, 'اگر بیمار انتصاب را داشته باشد، روی OK کلیک کنید تا یک برخورد را ایجاد کنید، در غیر اینصورت، لغو این را لغو کنید و سپس یک دیدار برای بازدید امروز ایجاد کنید.');
INSERT INTO `lang_definitions` VALUES (194815, 5117, 31, 'اگر پرداخت شود');
INSERT INTO `lang_definitions` VALUES (194816, 5118, 31, 'اگر فرد مرحوم باشد، سپس تاریخ مرگ را وارد کنید.');
INSERT INTO `lang_definitions` VALUES (194817, 5119, 31, 'اگر تلفن از دست رفته قادر به ورود به سیستم نیست');
INSERT INTO `lang_definitions` VALUES (194818, 5120, 31, 'اگر امتیازات باید اصلاح شوند، می توان آن را می توان یا یک کاربر در یک زمان در مدیریت> کاربران یا به راحتی در این صفحه انجام داد. مدیریت> ACL که در آن همه کاربران در یک صفحه فهرست شده اند و گزینه های بیشتری در دسترس هستند.');
INSERT INTO `lang_definitions` VALUES (194819, 5121, 31, 'اگر تعیین شده به عنوان بالا، دید را محدود به کاربران متعلق به گروه های خاص (AROS) محدود می کند.به طور پیش فرض - پزشکان و مدیران');
INSERT INTO `lang_definitions` VALUES (194820, 5122, 31, 'اگر SMTP استفاده شود، نام میزبان سرور یا آدرس IP.');
INSERT INTO `lang_definitions` VALUES (194821, 5123, 31, 'اگر SMTP استفاده شود، شماره پورت TCP سرور (معمولا 25).');
INSERT INTO `lang_definitions` VALUES (194822, 5124, 31, 'اگر به نظر می رسد، هیئت مدیره پیش فرض را می توان با رفتن به مدیریت> تقویم> به یادآوری هیئت مدیره غیرفعال کرد: غیرفعال کردن و چک کردن جعبه و کلیک کنید');
INSERT INTO `lang_definitions` VALUES (194823, 5125, 31, 'اگر بنابراین شما باید سفارشات روش های فردی (سفارشات) را برای این آزمایش ها همراه با نتایج گسسته (مکان برای ورود و نمایش نتیجه بازگشتی) ایجاد کنید');
INSERT INTO `lang_definitions` VALUES (194824, 5126, 31, 'اگر موفق به تایید کاربر شود');
INSERT INTO `lang_definitions` VALUES (194825, 5127, 31, 'اگر کادر چک چک شود و پیام به چندین کاربر ارسال می شود، هر کاربر باید با کلیک بر روی مجموعه به عنوان دکمه تکمیل شده برای آن پیام، باید در پیام ثبت نام کند');
INSERT INTO `lang_definitions` VALUES (194826, 5128, 31, 'اگر جعبه چک چک شود، هر فردی از یک گروه دریافت کننده این پیام باید با کلیک کردن بر روی مجموعه به عنوان دکمه تکمیل شده، امضا شود');
INSERT INTO `lang_definitions` VALUES (194827, 5129, 31, 'اگر فایل CSV آپلود شده باشد، روی دکمه «رویدادهای تعطیلات» کلیک کنید.توجه داشته باشید که با کلیک بر روی دکمه، تمام ردیف های موجود را در جدول Calendar_External حذف می کند');
INSERT INTO `lang_definitions` VALUES (194828, 5130, 31, 'اگر عنوان دلخواه گنجانده نشده باشد، می توان آن را به جعبه متن زیر لیست تایپ کرد');
INSERT INTO `lang_definitions` VALUES (194829, 5131, 31, 'اگر جدول نمایش داده شده می گوید هیچ رکورد تطبیقی یافت نشد، به این معنی است که مجموعه کد ICD10 نصب نشده است');
INSERT INTO `lang_definitions` VALUES (194830, 5132, 31, 'اگر فایل کمک وجود ندارد ایجاد یک و قرار دادن آن را در');
INSERT INTO `lang_definitions` VALUES (194831, 5133, 31, 'اگر موضوع به یک برخورد مرتبط نشده است، 0 را نمایش داده است');
INSERT INTO `lang_definitions` VALUES (194832, 5134, 31, 'اگر مشکل پزشکی در جعبه کشویی ذکر نشده است، بر روی جعبه متن کدگذاری کلیک کنید تا صفحه Pop-up را انتخاب کنید');
INSERT INTO `lang_definitions` VALUES (194833, 5135, 31, 'اگر پیام ارسال شود، آن را در لیست پیام های فعال کاربر نشان می دهد که پیام فرستاده شده و از لیست پیام های فعال کاربر فعلی ناپدید می شود');
INSERT INTO `lang_definitions` VALUES (194834, 5136, 31, 'اگر پورتال بیمار Offsite فعال شود، یک دکمه وجود دارد که می گوید ایجاد اعتبار پورتال Offsite را فراهم می کند');
INSERT INTO `lang_definitions` VALUES (194835, 5137, 31, 'اگر پورتال بیمار آنلاین فعال باشد، یک دکمه وجود دارد که می گوید ایجاد اعتبار پورتال آنلاین را فراهم می کند');
INSERT INTO `lang_definitions` VALUES (194836, 5138, 31, 'اگر اعتبار پورتال آنلاین / Offsite قبلا تنظیم شده است، دکمه تغییر خواهد کرد');
INSERT INTO `lang_definitions` VALUES (194837, 5139, 31, 'اگر بیمار دارای اطلاعات جمعیتی در OpenEMR باشد، به طور خودکار زمینه های مربوطه را در بخش های مناسب قرار می دهد');
INSERT INTO `lang_definitions` VALUES (194838, 5140, 31, 'اگر بیمار پورتال بیمار را مجاز نیاورد و سپس بیمار مجاز به ارسال پیام پورتال بیمار در اینجا نشان داده نخواهد شد');
INSERT INTO `lang_definitions` VALUES (194839, 5141, 31, 'اگر بیمار در روز بازدید به لیست یادآوری اضافه شود، تاریخ فعلی را منعکس می کند');
INSERT INTO `lang_definitions` VALUES (194840, 5142, 31, 'اگر بیمار تماس بگیرد تا به لیست اضافه شود، آخرین بازدید ممکن است در گذشته از راه دور باشد.توجه داشته باشید که سال های 1،2،3 به علاوه محاسبه شده و در جعبه تاریخ در پایین این بخش نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (194841, 5143, 31, 'اگر بیمار مرحوم باشد، اعلان مرحوم در این بخش به صورت قرمز ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (194842, 5144, 31, 'اگر این گزارش به صورت الکترونیکی ارسال شود، تمام مراحل مورد نیاز برای انتقال امن و امن اطلاعات بهداشتی محافظت شده (PHI) باید دنبال شود');
INSERT INTO `lang_definitions` VALUES (194843, 5145, 31, 'اگر هیچ فروشنده هیچ شماره منحصر به فرد دلخواه را وارد نکنید، ترجیحا یک عدد 5 عدد صفر صفر است.00211');
INSERT INTO `lang_definitions` VALUES (194844, 5146, 31, 'اگر این تست ها به همان آزمایشگاه خارجی ارسال شوند، کدهای شناسایی خاصی را به فروش می رسانند که باعث می شود خطوط تکراری ظاهر شوند، زمانی که نتایج نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (194845, 5147, 31, 'اگر آنها به درستی پیکربندی شده اند، هر نتیجه باید مقدار سطح 4 را داشته باشند، که نشان می دهد آنها جانشین یا فرزند به خط اول بالا با مقدار سطحی 3، i.e پنل الکترولیتی هستند');
INSERT INTO `lang_definitions` VALUES (194846, 5148, 31, 'اگر این صفحه تجدید نکند، صفحه پیام ها را به صورت دستی بارگیری کنید');
INSERT INTO `lang_definitions` VALUES (194847, 5149, 31, 'اگر Unassigned به طور پیش فرض به تنظیم php.ini برای تاریخ به روز شود.');
INSERT INTO `lang_definitions` VALUES (194848, 5150, 31, 'اگر بیکار، قید کنید دانشجو');
INSERT INTO `lang_definitions` VALUES (194849, 5151, 31, 'اگر مقدار به عنوان صفر باقی بماند، به ترتیب حروف الفبا مرتب می شود');
INSERT INTO `lang_definitions` VALUES (194850, 5152, 31, 'اگر YMD برای نمایش سن انتخاب شده باشد، فقط زمانی که بیماران مسن تر از این ارزش در سال ها هستند، تغییر دهید');
INSERT INTO `lang_definitions` VALUES (194851, 5153, 31, 'اگر مشکلی در ورود به حساب کاربری خود دارید.');
INSERT INTO `lang_definitions` VALUES (194852, 5154, 31, 'اگر شما علاقه مند به آنچه که در زیر هود اتفاق می افتد');
INSERT INTO `lang_definitions` VALUES (194853, 5155, 31, 'اگر فقط از یک زیر مجموعه کوچک از کدهای CPT استفاده می کنید، می توانید به صورت دستی آن را در Codes مدیریت کنید');
INSERT INTO `lang_definitions` VALUES (194854, 5156, 31, 'اگر شما در حال برنامه ریزی برای وارد کردن قیمت های مختلف برای روش های مختلف پرداخت به دولت> لیست');
INSERT INTO `lang_definitions` VALUES (194855, 5157, 31, 'اگر مطمئن نیستید یا از یک نسخه توسعه بین دو نسخه استفاده کنید، سپس قدیمی تر از نسخه های احتمالی را انتخاب کنید');
INSERT INTO `lang_definitions` VALUES (194856, 5159, 31, 'اگر شما از نسخه زیر 5.0.0 به نسخه 5.0.0 یا بالاتر ارتقا دهید، توجه داشته باشید که این ارتقاء می تواند از چند دقیقه تا چند ساعت طول بکشد (شما فقط یک Whitescreen را تا زمانی که کامل نیست، اسکریپت را متوقف نکنیدقبل از آن کامل است یا شما می توانید اطلاعات خود را خراب کنید)');
INSERT INTO `lang_definitions` VALUES (194857, 5160, 31, 'اگر از ورود آزمایشگاه الکترونیکی استفاده می کنید، جزئیات لازم را پر کنید و روی ذخیره کلیک کنید');
INSERT INTO `lang_definitions` VALUES (194858, 5161, 31, 'اگر از چندین آزمایشگاه استفاده می کنید، جزئیات را برای هر یک از آنها وارد کنید');
INSERT INTO `lang_definitions` VALUES (194859, 5162, 31, 'اگر نقش E-RX را برای ePrescription تغییر دهید، ممکن است بر گردش کار Eprescription تاثیر بگذارد.اگر با دشواری مواجه شدید، با فروشنده ePrescription خود تماس بگیرید.');
INSERT INTO `lang_definitions` VALUES (194860, 5163, 31, 'اگر گوشی هوشمند خود را تغییر دهید، می توانید کد کلید QR کلید TOTP را به یک دستگاه جدید با استفاده از برنامه Authenticator در تلفن قدیمی خود بازگردانید و سپس به احراز هویت MFA و با کلیک بر روی دکمه نمایش در بخش روش احراز هویت فعلی بروید');
INSERT INTO `lang_definitions` VALUES (194861, 5164, 31, 'اگر جعبه چک را در هر یک از این سلول ها بررسی کنید، ورودی را در آخرین سلول به نام پیشرفت تولید می کند');
INSERT INTO `lang_definitions` VALUES (194862, 5165, 31, 'اگر شما تصمیم به انجام یک ورودی دستی کلیک کنید، روی دکمه رادیویی \"جستجو فاکتور\" کلیک کنید.این نمایش دو بخش \"پست\" و \"جستجوی فاکتور\" را نمایش می دهد');
INSERT INTO `lang_definitions` VALUES (194863, 5166, 31, 'اگر تصمیم به ادغام نتایج آزمایشگاه با رکورد بیمار دارید، برخی از تنظیمات اولیه باید انجام شود');
INSERT INTO `lang_definitions` VALUES (194864, 5167, 31, 'اگر بر روی هر کاربر در بخش «عضویت کاربر» کلیک کنید، اکنون این گروه تازه ایجاد شده (ARO) را در ستون غیر فعال خواهید دید.این ها اکنون می توانند به صورت معمول به صورت معمول تعیین شوند.');
INSERT INTO `lang_definitions` VALUES (194865, 5168, 31, 'اگر بر روی آیکون ویرایش در کنار این گروه تازه ایجاد شده کلیک کنید (ARO) شما توجه خواهید کرد که ستون \"فعال\" تنها یک ورودی تک ورودی را شامل می شود (ACL های خالی را حفظ می کند).با این حال، این گروه جدید (ARO) هیچ دسترسی به هیچ بخشی از برنامه ندارد، زیرا هیچ ACOs در ستون فعال وجود ندارد.');
INSERT INTO `lang_definitions` VALUES (194866, 5169, 31, 'اگر بر روی علامت آبی + روی شیمی قرار گیرید، یک خط جدید به نام organ / panel panel را با یک دسته از گروه زیر مشاهده خواهید کرد');
INSERT INTO `lang_definitions` VALUES (194867, 5170, 31, 'اگر این خطا را تجربه کنید، لطفا با پشتیبانی تماس بگیرید.');
INSERT INTO `lang_definitions` VALUES (194868, 5171, 31, 'اگر مقدار مورد نیاز را در جعبه کشویی پیدا نکنید، باید آن را از طریق مدیریت> لیست> واحد های روش اضافه کنید.به پرونده راهنما در مراحل> ارائه دهندگان مراجعه کنید');
INSERT INTO `lang_definitions` VALUES (194869, 5172, 31, 'اگر شما یک مسابقه را انتخاب نکنید، بیمار ایجاد خواهد شد.');
INSERT INTO `lang_definitions` VALUES (194870, 5173, 31, 'اگر حداقل یکی از اینها را انتخاب نکنید، OpenEMR در حالت دریافتی تنها کار می کند');
INSERT INTO `lang_definitions` VALUES (194871, 5174, 31, 'اگر سفارشات الکترونیکی را به صورت الکترونیکی ارسال نکنید یا دریافت کنید، به صورت الکترونیکی آن را به عنوان مقدار پیش فرض، دانلود کنید');
INSERT INTO `lang_definitions` VALUES (194872, 5176, 31, 'اگر شما نمی خواهید این کار را انجام دهید، روش زیر شامل اضافه کردن داده ها به صورت دستی با استفاده از رابط OpenEMR');
INSERT INTO `lang_definitions` VALUES (194873, 5177, 31, 'اگر شما به خط پانل الکترولیت بروید و روی علامت + علامت نام کلیک کنید');
INSERT INTO `lang_definitions` VALUES (194874, 5178, 31, 'اگر شما به خط پانل الکترولیتی تمرین کنید، باید ببینید که آن دسته از نظم را دارد و در زرد نشان می دهد که این یک نظم جستجو و معتبر است و دارای مقدار قابل توجهی از 3 است');
INSERT INTO `lang_definitions` VALUES (194875, 5179, 31, 'اگر کد های چندگانه را انتخاب کرده اید، آنها توسط نیمه کولون ها جدا خواهند شد');
INSERT INTO `lang_definitions` VALUES (194876, 5180, 31, 'اگر قبلا جدول Calendar_External را پر کرده اید، روی دکمه \"همگام سازی\" کلیک کنید تا تعطیلات را در نمای تقویم داشته باشید.توجه داشته باشید که کلیک کردن بر روی دکمه تمام موارد موجود را در نمای تقویم مربوط به تعطیلات حذف می کند');
INSERT INTO `lang_definitions` VALUES (194877, 5181, 31, 'اگر شما یک superbill قدیمی دارید، می توانید گروه بندی های خود را به عنوان یک الگو برای شروع سفارشی سازی استفاده کنید');
INSERT INTO `lang_definitions` VALUES (194878, 5182, 31, 'اگر شما انتخاب کرده اید که پول های الکترونیکی را آپلود کنید، پنجره جستجو خود را با فاکتورهای تطبیق از فایل X12 تغییر دهید.شما ممکن است بر روی هر یک از این شماره های فاکتور کلیک کنید (همانطور که در زیر شرح داده شده است) اگر بخواهید قبل از اینکه اطلاعات انتقال پول اعمال شود، تصحیح کنید.برای اعمال تغییرات، روی دکمه فرآیند ERA فایل در پایین صفحه کلیک کنید.این یک پنجره جدید را با یک گزارش دقیق تولید خواهد کرد.');
INSERT INTO `lang_definitions` VALUES (194879, 5183, 31, 'اگر شما انتخاب کرده اید که پول های الکترونیکی را آپلود کنید، پنجره جستجو خود را با فاکتورهای تطبیق از فایل X12 تغییر دهید.شما ممکن است بر روی هر کدام از این شماره های فاکتور کلیک کنید (همانطور که در بالا توضیح داده شد) اگر می خواهید قبل از اینکه اطلاعات انتقال پول اعمال شود، هر گونه اصلاحات را انجام دهید.برای اعمال تغییرات، روی دکمه «پرونده فرآیند ERA \'در پایین صفحه کلیک کنید.این یک پنجره جدید را با یک گزارش دقیق تولید خواهد کرد.');
INSERT INTO `lang_definitions` VALUES (194880, 5184, 31, 'اگر شما روش TOTP را فعال کرده اید، دفعه بعد که وارد شوید، از شما خواسته می شود که رمز عبور TOTP را وارد کنید');
INSERT INTO `lang_definitions` VALUES (194881, 5185, 31, 'اگر شما یک تاریخ پرداخت را در صفحه جستجو وارد کرده اید، این تاریخچه ارسال پرداخت ها و تنظیمات را که در غیر این صورت از فایل X12 گرفته شده است، لغو می شود.این ممکن است برای اهداف گزارش مفید باشد، اگر می خواهید گزارش های دریافتی خود را برای استفاده از تاریخ ارسال خود به جای تاریخ پردازش شرکت بیمه کنید.توجه داشته باشید که این نیز بر تاریخ پرداخت های پیشین و تنظیمات که به ادعاهای ثانویه منتقل می شود، تاثیر می گذارد.');
INSERT INTO `lang_definitions` VALUES (194882, 5186, 31, 'اگر شما یک تاریخ پرداخت را در صفحه جستجو وارد کرده اید، این تاریخچه ارسال پرداخت ها و تنظیمات را که در غیر این صورت از فایل X12 گرفته شده است، لغو می شود.این ممکن است برای اهداف گزارش مفید باشد، اگر می خواهید گزارش های دریافتی خود را برای استفاده از تاریخ ارسال خود به جای تاریخ پردازش شرکت بیمه کنید.توجه داشته باشید که این نیز بر تاریخ پرداخت های پیشین و تنظیمات که به ادعاهای ثانویه منتقل می شود، تاثیر می گذارد.');
INSERT INTO `lang_definitions` VALUES (194883, 5187, 31, 'اگر شما تمام مراحل فوق را به درستی دنبال کرده اید، باید اسید اوریک سرم را تحت نام قرار دهید، قبل از آن یک نوار عمودی که نشان دهنده عدم وجود فرزندان یا کودکان به این مطلب است، پیش می رود');
INSERT INTO `lang_definitions` VALUES (194884, 5188, 31, 'اگر مراحل فوق را به درستی دنبال کرده اید، آزمون اسید اوریک سرم باید در حال حاضر یک علامت + را قبل از نام نشان می دهد که حضور جانشینان یا کودکان را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (194885, 5189, 31, 'اگر گوشی های هوشمند خود را از دست داده اید، کسانی که دارای امتیازات مدیران هستند می توانند کلید ها را با رفتن به مدیریت> کاربران و بررسی کادر تأیید 2FA و کلیک بر روی ذخیره سازی حذف کنند');
INSERT INTO `lang_definitions` VALUES (194886, 5190, 31, 'اگر ماژول ERX Newcrop را فعال کرده اید، آلرژی ها باید در صفحه Medentry Newcrop وارد شوند');
INSERT INTO `lang_definitions` VALUES (194887, 5191, 31, 'اگر قبلا برخی از پیش پیکربندی را انجام نداده اید، از جمله اضافه کردن ارائه دهندگان، این کار را با رفتن به روش ها> ارائه دهندگان انجام دهید');
INSERT INTO `lang_definitions` VALUES (194888, 5192, 31, 'اگر شما نیاز به سفارش اجزای فردی از پانل دارید، باید یک سفارش جداگانه را برای هر جزء فردی پانل ایجاد کنید و نتیجه بازگشتی را تحت یک نتیجه گسسته ایجاد کنیدبرای اسید اوریک سرم');
INSERT INTO `lang_definitions` VALUES (194889, 5193, 31, 'اگر شما دکمه Refresh را بدون تنظیم هر فیلتر فشار دهید، تمام یادآوری های تاریخی برای کاربر زیر ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (194890, 5194, 31, 'اگر شما آن را به طور پیش فرض از 0 بگذارید، نوشته های سطح بالا که شما انجام می دهید، به ترتیب حروف الفبا مرتب می شود');
INSERT INTO `lang_definitions` VALUES (194891, 5195, 31, 'اگر تغییرات را انجام دادید و میخواهید دوباره آن را ارسال کنید، اصلی را حذف کنید (در ارتباطات) و دوباره امتحان کنید.');
INSERT INTO `lang_definitions` VALUES (194892, 5196, 31, 'اگر تغییراتی را انجام دادید و میخواهید دوباره آن را ارسال کنید، اصلی (در ارتباطات) را حذف کنید یا 60 ثانیه صبر کنید و دوباره امتحان کنید.');
INSERT INTO `lang_definitions` VALUES (194893, 5197, 31, 'اگر شما نیاز به دستی را به صورت دستی وارد نتیجه بازگشتی هر آزمون (مورد مورد علاقه سفارشی) باید یک نتیجه گسسته به عنوان یک نسل مستقیم داشته باشد');
INSERT INTO `lang_definitions` VALUES (194894, 5198, 31, 'اگر هیچ ورودی را به ترتیب از جعبه کشویی مشاهده نکنید، این بدان معنی است که شما یک آزمایشگاه تحت مراحل> ارائه دهندگان را تنظیم نکرده اید');
INSERT INTO `lang_definitions` VALUES (194895, 5199, 31, 'اگر می خواهید انواع داده را تغییر دهید یا ردیف ها یا ستون ها را اضافه کنید');
INSERT INTO `lang_definitions` VALUES (194896, 5200, 31, 'اگر می خواهید پایگاه داده را ارتقا دهید، سپس فایل زیپ پایگاه داده را در دایرکتوری زیر قرار دهید');
INSERT INTO `lang_definitions` VALUES (194897, 5201, 31, 'اگر جستجوی شما موفق بود نتایج جستجو در جعبه نتایج جستجو در زیر نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (194898, 5202, 31, 'ایگبو');
INSERT INTO `lang_definitions` VALUES (194899, 5203, 31, 'چشم پوشی');
INSERT INTO `lang_definitions` VALUES (194900, 5205, 31, 'کد IIS');
INSERT INTO `lang_definitions` VALUES (194901, 5207, 31, 'بیماری');
INSERT INTO `lang_definitions` VALUES (194902, 5208, 31, 'من هستم');
INSERT INTO `lang_definitions` VALUES (194903, 5209, 31, 'بوم تصویر');
