INSERT INTO `lang_definitions` VALUES (194957, 5263, 31, 'مهم: این ابزار آپلود تنها برای آپلود اسناد در بیماران است که هنوز وارد سیستم نشده اند.برای آپلود فایل ها برای بیماران که قبلا وارد سیستم شده اند، لطفا از ابزار آپلود شده در صفحه خلاصه بیمار استفاده کنید.');
