INSERT INTO `lang_definitions` VALUES (194969, 5275, 31, 'به همین ترتیب، شما یک نتیجه گسسته برای پتاسیم، کلرید و دی اکسید کربن ایجاد خواهید کرد');
INSERT INTO `lang_definitions` VALUES (194970, 5276, 31, 'به همین ترتیب یک مورد سفارشی مورد علاقه هر کدام را برای TSH ایجاد کنید (دنباله 2، شناسایی کد WWT02، کد استاندارد 30166-3) و ویتامین D (توالی 3، کد شناسایی WWT03، کد استاندارد 35365-6)');
INSERT INTO `lang_definitions` VALUES (194971, 5277, 31, 'به همین ترتیب یک نتیجه گسسته ایجاد یک نتیجه گسسته برای TSH (دنباله - 2، شناسایی کد - WWT02R، واحد های پیش فرض - MU / L، محدوده پیش فرض - 0.4-4، ترک خدمات پیگیری خالی) و ویتامین D (توالی - 3، کد شناسایی- WWT03R، واحدهای پیش فرض - NG / ML، محدوده پیش فرض - 0-20، ترک خدمات پیگیری خالی)');
INSERT INTO `lang_definitions` VALUES (194972, 5278, 31, 'علاوه بر این 2 جعبه چک وجود دارد');
INSERT INTO `lang_definitions` VALUES (194973, 5279, 31, 'علاوه بر ایجاد یک ارجاع، سیستم همچنین به شما اجازه می دهد تا یک فرم ارجاع خالی را چاپ کنید که می تواند به صورت دستی برای تولید ارجاع پر شود');
INSERT INTO `lang_definitions` VALUES (194974, 5280, 31, 'در هر صورت ایجاد یک اتصال، اطمینان از انطباق HIPAA، امنیت داده ها و غیره نیاز به برنامه نویسی دارد، هزینه آن معمولا توسط آزمایشگاه مورد استفاده قرار می گیرد.با این حال، آنها تنها تایید خواهند کرد که آیا حجم کسب و کار سرمایه گذاری خود را توجیه می کند');
INSERT INTO `lang_definitions` VALUES (194975, 5282, 31, 'در چت کنونی');
INSERT INTO `lang_definitions` VALUES (194976, 5283, 31, 'در هر چشم');
