INSERT INTO `lang_definitions` VALUES (194981, 5290, 31, 'در دفتر');
INSERT INTO `lang_definitions` VALUES (194982, 5291, 31, 'در OpenEmr تداوم رکورد مراقبت (CCR) گزارش می شود که تولید می شود می تواند محدود به محدوده تاریخ خاص با چک کردن جعبه بررسی تاریخ تاریخ استفاده و وارد شدن محدوده تاریخ مورد نظر');
INSERT INTO `lang_definitions` VALUES (194983, 5292, 31, 'به منظور تحقق شرایط استفاده معنی دار برای ورود به سیستم ارائه دهنده کامپیوتری (CPOE) برای آزمایشات آزمایشگاهی و رادیولوژی، این ماژول باید مورد استفاده قرار گیرد');
INSERT INTO `lang_definitions` VALUES (194984, 5293, 31, 'به منظور به درستی ذخیره و بازیابی نتایج آزمون و قرار دادن سفارشات جدید، تست ها / سفارشات باید در یک روش سلسله مراتبی راه اندازی شود');
INSERT INTO `lang_definitions` VALUES (194985, 5294, 31, 'به منظور ثبت مقادیر نتایج، شما باید یک نتیجه گسسته جداگانه (سطح 4) را برای هر یک از اجزای پانل، میوه، به عنوان نسل مستقیم از این (پانل بهداشت عمومی) (سطح 3) ایجاد کنید.نمونه هایی از نتایج حاصل از CBC - هموگلوبین، CBC - هماتوکریت، CMP - سدیم، CMP - پتاسیم، TSH و غیره');
INSERT INTO `lang_definitions` VALUES (194986, 5295, 31, 'برای ثبت نام دستگاه خود، لطفا رمز ورود OpenEMR خود را ارائه دهید');
INSERT INTO `lang_definitions` VALUES (194987, 5296, 31, 'به منظور ارسال تداوم رکورد مراقبت (CCR) و / یا تداوم سند مراقبت (CCD) به صورت اختیاری بررسی PHIMAIL اجازه می دهد CCD ارسال و / یا PHIMAIL اجازه دهد CCR ارسال کند تا ویژگی انتقال برای این نوع داده ها را فعال کند');
INSERT INTO `lang_definitions` VALUES (194988, 5297, 31, 'در مورد ما آزمایشگاه محلی را انتخاب کردیم که قبلا راه اندازی شد');
INSERT INTO `lang_definitions` VALUES (194989, 5298, 31, 'در مورد ما ما آن را به عنوان یکپارچه ترک خواهیم کرد');
INSERT INTO `lang_definitions` VALUES (194990, 5300, 31, 'در حالت عمودی، ارتفاع پاکت را در امتداد محور Y در میلیمتر تعیین می کند');
INSERT INTO `lang_definitions` VALUES (194991, 5301, 31, 'در حالت عمودی، عرض پاکت را در امتداد محور x در میلیمتر تعیین می کند');
INSERT INTO `lang_definitions` VALUES (194992, 5302, 31, 'در چشم راست');
INSERT INTO `lang_definitions` VALUES (194993, 5303, 31, 'در سفارشات الکترونیکی کوتاه می تواند انجام شود، آن را شامل مقدار قابل توجهی از تست و سفارشی سازی توسط آزمایشگاه، به طور کلی از طریق یک شخص ثالث گواهی شده است و تنها زمانی اتفاق می افتد که آزمایشگاه موافقت کند که نور سبز را به پروژه برساند');
INSERT INTO `lang_definitions` VALUES (194994, 5304, 31, 'در بخش «پست پست» که در بالای صفحه نمایش داده می شود، ممکن است یک منبع (E.G. شماره چک) را وارد کنید، تاریخ پرداخت و مقدار چک را وارد کنید.دلیل منبع منبع و پرداخت، به طوری که شما مجبور نیستید آنها را دوباره و دوباره برای هر ادعا وارد کنید.مبلغی که وارد می کنید، برای هر فاکتور که بخشی از پرداخت را داده می شود، کاهش می یابد و امیدوارم زمانی که شما انجام می شود، به صفر برسد.');
INSERT INTO `lang_definitions` VALUES (194995, 5305, 31, 'در مثال فوق، سفارش یک آزمون واحد ایجاد شد، I.E. اسید اوریک سرم');
INSERT INTO `lang_definitions` VALUES (194996, 5306, 31, 'در نصب پیش فرض روی افزودن کلیک کنید تا صفحه Pop-up افزودن / ویرایش را مطرح کنید');
