INSERT INTO `lang_definitions` VALUES (194999, 5309, 31, 'در این مورد، گروه مورد علاقه دلخواه به نام Preop Labs نامیده می شود و دو پانل شناخته شده به طور مستقیم به ترتیب به ترتیب به ترتیب CBC و پنل کلیه به ترتیب');
INSERT INTO `lang_definitions` VALUES (195000, 5310, 31, 'در این مورد شما یک روش را ایجاد خواهید کرد، شاخه ی بلبرینگ به نام پانل بهداشت عمومی (سطح 3)');
