INSERT INTO `lang_definitions` VALUES (195352, 5689, 31, 'قسمت موضوعات');
INSERT INTO `lang_definitions` VALUES (195353, 5691, 31, 'این اجازه می دهد تا مرورگر به طور مستقیم به دستگاه USB ارتباط برقرار کند، اجتناب از نیاز به کاربر برای انجام هر کاری بیشتر از وارد کردن دستگاه به یک پورت USB و ضربه بزنید تا آن را فعال کنید');
INSERT INTO `lang_definitions` VALUES (195354, 5692, 31, 'همچنین به شما امکان می دهد گروه های جدید (AROS) را ایجاد کنید و همچنین حذف موجودات موجود را حذف کنید.');
INSERT INTO `lang_definitions` VALUES (195355, 5693, 31, 'همچنین می تواند نتایج را به صورت الکترونیکی دریافت کند');
INSERT INTO `lang_definitions` VALUES (195356, 5694, 31, 'این می تواند به بیمار متصل شود یا فقط یک پیام به کاربر دیگری باشد (ها)');
INSERT INTO `lang_definitions` VALUES (195357, 5695, 31, 'این ترکیبی از آنچه کاربر می داند i.e. رمز عبور کاربر با آنچه کاربر I.E. یک دستگاه منحصر به فرد یا مکانیسم برای تولید / دریافت یک کد منحصر به فرد برای استفاده در هر ورود به سیستم است');
INSERT INTO `lang_definitions` VALUES (195358, 5696, 31, 'این شامل سه بخش است');
INSERT INTO `lang_definitions` VALUES (195359, 5697, 31, 'این شامل دو بخش است - تعریف یک ارائه دهنده و پیکربندی سفارشات و نتایج');
INSERT INTO `lang_definitions` VALUES (195360, 5698, 31, 'این شامل دو بخش است - درخواست دریافت و دریافت امکانات');
INSERT INTO `lang_definitions` VALUES (195361, 5699, 31, 'این شامل دو بخش است - درخواست ارسال و ارسال امکانات');
INSERT INTO `lang_definitions` VALUES (195362, 5700, 31, 'این شامل بخش چپ و راست است');
INSERT INTO `lang_definitions` VALUES (195363, 5701, 31, 'این شامل یک کد QR است که باید توسط برنامه Authenticator ضبط شود');
INSERT INTO `lang_definitions` VALUES (195364, 5702, 31, 'این شامل داده های ساختاری است که در تداوم رکورد مراقبت (CCR) قرار دارد به استاندارد معماری سند بالینی');
INSERT INTO `lang_definitions` VALUES (195365, 5703, 31, 'این به ارجاع واقعی که ایجاد شده اشاره نمی کند');
INSERT INTO `lang_definitions` VALUES (195366, 5704, 31, 'این کار با استفاده از یک الگوریتم برای ترکیب زمان یونیکس فعلی با کلید مخفی برای تولید یک کلید منحصر به فرد در حال تغییر است');
INSERT INTO `lang_definitions` VALUES (195367, 5705, 31, 'این چهار زبانه دارد');
INSERT INTO `lang_definitions` VALUES (195368, 5706, 31, 'این سه مرحله دارد');
INSERT INTO `lang_definitions` VALUES (195369, 5707, 31, 'این یک ماژول پیامرسانی تجاری است که برای استفاده از OpenEMR با استفاده از نسخه 5.0.1 و بالاتر است');
INSERT INTO `lang_definitions` VALUES (195370, 5708, 31, 'این یک فیلد در هدر پیام HL7 به نام ID پردازش است');
INSERT INTO `lang_definitions` VALUES (195371, 5709, 31, 'این بخشی از پرونده پزشکی است');
INSERT INTO `lang_definitions` VALUES (195372, 5710, 31, 'این نیز یک سرویس مبتنی بر اشتراک است');
INSERT INTO `lang_definitions` VALUES (195373, 5711, 31, 'همچنین لازم است که کد ICD10 را به منظور حل مشکل در تداوم گزارش مراقبت (CCR) و تداوم سند مراقبت (CCD) ذکر شود');
INSERT INTO `lang_definitions` VALUES (195374, 5712, 31, 'این به دو بخش تقسیم شده است');
INSERT INTO `lang_definitions` VALUES (195375, 5713, 31, 'ضروری است که از چهار بخش اول بخوانید تا اصول اساسی را درک کنید');
INSERT INTO `lang_definitions` VALUES (195376, 5714, 31, 'قبل از شروع ورود به داده ها در OpenEMR، این بسیار ساده تر و بصری است تا تغییرات بزرگی را تغییر دهید و اطلاعات را در صفحه گسترده تنظیم کنید');
INSERT INTO `lang_definitions` VALUES (195377, 5715, 31, 'مهم است بدانیم که این مدیریت MFA را برای کاربر وارد شده مدیریت می کند');
INSERT INTO `lang_definitions` VALUES (195378, 5716, 31, 'مهم است که عملکرد این دو آیکون را درک کنید، زیرا تمام مراحل بعدی مورد نیاز برای تنظیم به درستی تنظیم سلسله مراتب به استفاده صحیح از این دو آیکون بستگی دارد');
INSERT INTO `lang_definitions` VALUES (195379, 5717, 31, 'در نظر گرفته شده است که تنها اطلاعاتی را که برای مراقبت به طور موثر ادامه دارد، شامل شود');
INSERT INTO `lang_definitions` VALUES (195380, 5718, 31, 'این به ارائه دهندگان خدمات بهداشتی در ایالات متحده توسط مراکز خدمات Medicare و Medicaid (CMS) صادر می شود');
INSERT INTO `lang_definitions` VALUES (195381, 5719, 31, 'برای آزمایشگاه محلی لازم نیست، در عوض شما می توانید از هر شماره منحصر به فرد دلخواه استفاده کنید');
INSERT INTO `lang_definitions` VALUES (195382, 5720, 31, 'لازم نیست که کدهای تشخیص پیش فرض را پر کنید زیرا کد ICD10 را می توان در زمان سفارش واقعی آزمون وارد کرد');
INSERT INTO `lang_definitions` VALUES (195383, 5721, 31, 'این ادعا ارائه نشده است');
INSERT INTO `lang_definitions` VALUES (195384, 5722, 31, 'این کار غیر معمول نیست که چندین آزمایش خون را با هم ترکیب کنیم، گروه بندی آنها را به عنوان پانل تست ها تسهیل می کند');
INSERT INTO `lang_definitions` VALUES (195385, 5723, 31, 'اگر با تماس با ما تماس بگیرید، محتاط است.');
INSERT INTO `lang_definitions` VALUES (195386, 5724, 31, 'این فرم ادعای مقاله پایه ای است که توسط بسیاری از پرداخت کنندگان برای ادعاهای ارائه شده توسط پزشکان و شیوه های فردی، پرستاران و متخصصان، از جمله درمانگران، متخصصین متخصصین، و کلینیک های خارج از بیمار ارائه شده است، و در بعضی موارد برای خدمات آمبولانس');
INSERT INTO `lang_definitions` VALUES (195387, 5725, 31, 'این مورد برای پیوند مشکلات با برخورد استفاده می شود و همچنین مورد استفاده قرار می گیرد تا ببینید که کدام برخورد ها به یک مسئله خاص مرتبط هستند');
INSERT INTO `lang_definitions` VALUES (195388, 5726, 31, 'مفید است که در یک محاکمه تمرین کنید تا قبل از انجام این کار، با این فرآیند آشنا شوید');
INSERT INTO `lang_definitions` VALUES (195389, 5727, 31, 'این به شما اجازه می دهد تا با کد های تشخیصی ICD 9 و ICD 10 و CPT4 و HCPCS خدمات / روش های COMENTS را جستجو کنید');
INSERT INTO `lang_definitions` VALUES (195390, 5728, 31, 'این به شما اجازه می دهد پیام ها و یادآوری های تاریخی را به اعضای کارکنان ارسال کنید، بیمار را به لیست یادآوری اضافه کنید و پیام های متنی SMS را به بیماران ارسال کنید');
INSERT INTO `lang_definitions` VALUES (195391, 5729, 31, 'این به عنوان یک پل ضروری به یک محیط متفاوت عمل می کند، اغلب با پزشکان جدید که هیچ چیز در مورد بیمار نمی دانند، امکان ارائه دهنده بعدی را به راحتی می دهد');
INSERT INTO `lang_definitions` VALUES (195392, 5731, 31, 'بنابراین این بدان معناست که شما نمیتوانید خود را به صورت ضد ارجاع ایجاد کنید');
INSERT INTO `lang_definitions` VALUES (195393, 5732, 31, 'از یک استاندارد باز استفاده می کند و بنابراین از تولیدات مختلف موجود است');
INSERT INTO `lang_definitions` VALUES (195394, 5733, 31, 'این تابع HMAC-SHA256 HASH را برای ایجاد یک کلید خصوصی منحصر به فرد برای حساب کاربری استفاده می کند');
INSERT INTO `lang_definitions` VALUES (195395, 5734, 31, 'از این کلید خصوصی برای امضای چالش استفاده می کند و پاسخ را به برنامه ارسال می کند');
INSERT INTO `lang_definitions` VALUES (195396, 5735, 31, 'این در خلاصه بازدید نمایش داده خواهد شد');
INSERT INTO `lang_definitions` VALUES (195397, 5736, 31, 'این فرم پاپ آپ را وارد می کند');
INSERT INTO `lang_definitions` VALUES (195398, 5737, 31, 'این پنجره چند منظوره یاب را به ارمغان خواهد آورد');
INSERT INTO `lang_definitions` VALUES (195399, 5738, 31, 'این نمایش پاپ آپ توجیه را نمایش می دهد.این یک جعبه جستجو است که WIL به شما اجازه می دهد کد ICD را جستجو کنید.همچنین 10 کدهای ICD مورد استفاده را نمایش می دهد.شما می توانید هر یا هر کدهای را با چک کردن جعبه J (توجیه) و فشار دادن به روز رسانی انتخاب کنید');
INSERT INTO `lang_definitions` VALUES (195400, 5739, 31, 'این مقدار 2 را در ستون لایه ای نشان می دهد که نشان می دهد این یک جانشین یا کودک در خط اول بالا است که دارای مقدار سطح 1 است که در این مورد شیمی سرم است');
INSERT INTO `lang_definitions` VALUES (195401, 5740, 31, 'این دو بخش دارد - بخش مسائل و بخش برخورد');
INSERT INTO `lang_definitions` VALUES (195402, 5741, 31, 'این بعدا در مشکلات عیب یابی کمک خواهد کرد که ممکن است با پیکربندی ماژول سفارشات رویه مواجه شود');
INSERT INTO `lang_definitions` VALUES (195403, 5742, 31, 'این بخش ایجاد پیام جدید را باز می کند');
INSERT INTO `lang_definitions` VALUES (195404, 5743, 31, 'این شما را به صفحه ثبت نام Medex می برد');
INSERT INTO `lang_definitions` VALUES (195405, 5744, 31, 'سپس در ویجت آلرژی در داشبورد بیمار و همچنین آلرژی در صفحه مسائل ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (195406, 5745, 31, 'پس از آن در ویجت داروها در داشبورد بیمار و همچنین داروها در صفحه مسائل ظاهر می شود');
INSERT INTO `lang_definitions` VALUES (195407, 5746, 31, 'ایتالیایی');
INSERT INTO `lang_definitions` VALUES (195408, 5747, 31, 'فقره');
INSERT INTO `lang_definitions` VALUES (195409, 5748, 31, 'فقره');
