INSERT INTO `lang_definitions` VALUES (196771, 7237, 31, 'توجه داشته باشید توصیه می شود از تصویب برنامه های هوشمند که به عنوان یک مشتری محرمانه ثبت نام نمی کنند، از تأیید برنامه های هوشمند استفاده کنید.این برنامه ها کمتر امن هستند و باید در حوزه های OAUTH2 بسیار محدود باشند که به آنها اجازه دسترسی آنها را می دهد.');
INSERT INTO `lang_definitions` VALUES (196772, 7238, 31, 'توجه داشته باشید پس از کلیک بر روی نصب، 5-10 دقیقه به طور کامل پردازش می شود');
