INSERT INTO `lang_definitions` VALUES (196975, 7454, 31, 'هنگامی که ویرایش به پایان رسید، روی ذخیره کلیک کنید.این روش تشخیص روش های فعلی تشخیص دقیقا همانطور که در این گفتگو ساخته شده است.');
INSERT INTO `lang_definitions` VALUES (196976, 7455, 31, 'هنگامی که نهاد را برای یک گروه مورد علاقه سفارشی ذخیره کرد، نمی توان تغییر داد.اگر شما نیاز به تغییر نهاد دارید، باید این مطلب را حذف کنید و یک جدید ایجاد کنید');
INSERT INTO `lang_definitions` VALUES (196977, 7456, 31, 'هنگامی که برنامه برنامه QR را ضبط می کند، نام کاربری OpenEMR را در برنامه نشان می دهد');
INSERT INTO `lang_definitions` VALUES (196978, 7457, 31, 'هنگامی که تسهیلات کسب و کار اولیه تنظیم شده است، تغییر شناسه تسهیلات بر Eprescription NewCrop تاثیر می گذارد.');
INSERT INTO `lang_definitions` VALUES (196979, 7458, 31, 'هنگامی که تأسیسات کسب و کار اولیه تنظیم می شود، نباید تغییر کرد.تغییر تسهیلات بر کار در Newcrop Eprescription تاثیر می گذارد.');
INSERT INTO `lang_definitions` VALUES (196980, 7459, 31, 'هنگامی که این ویژگی فعال می شود، لازم است که در هر ورودی کلید 6 رقمی را تایپ کنید');
INSERT INTO `lang_definitions` VALUES (196981, 7460, 31, 'هنگامی که این کار کلید مخفی مشترک است که منحصر به فرد است برای هر کاربر تنها باید در OpenEMR و در برنامه Authenticator کاربر وجود دارد');
INSERT INTO `lang_definitions` VALUES (196982, 7461, 31, 'هنگامی که این مرحله تکمیل می شود، می توانید به مرحله بعدی بروید - برای پیکربندی تست هایی که می توانید از سیستم سفارش دهید');
