INSERT INTO `lang_definitions` VALUES (197045, 7530, 31, 'Open Med Practice و تامین کنندگان آن از تلاش های تجاری خود برای ارائه اطلاعات فعلی و کامل برای ارائه اطلاعات موجود در مورد تاریخچه نسخه، تعاملات دارویی و فرمولار، آلرژی های بیمار و سایر عوامل، استفاده می کنند، اما با استفاده از این سرویس شما تصدیق می کنید که (1) کامل بودن و صحت چنین داده ها بستگی به کامل بودن و دقت دارد که به طور کامل به پایگاه داده های الکترونیکی متصل شده توسط پزشکان، دفاتر پزشک، مدیران مزایای دارویی، شرکت های پزشکی الکترونیکی پزشکی و سایر شرکت کنندگان شبکه وارد می شود خطا یا حذف در ورودی، ذخیره سازی یا بازیابی، انتقال و نمایش، اختلال فنی، قدرت و یا قطع برق، و یا وقفه های دیگر در ارتباطات الکترونیکی، هر کدام از آنها ممکن است فراتر از کنترل تمرین باز و تامین کنندگان آن باشد، و (3 ) برخی از اطلاعات ممکن است به دلیل مقررات، قراردادی، حریم خصوصی یا سایر محدودیت های قانونی ممکن است در دسترس نباشد. شما مسئول استفاده از قضاوت بالینی خود در همه زمان ها در ارائه خدمات پزشکی و مشاوره هستید.');
