INSERT INTO `lang_definitions` VALUES (197550, 8068, 31, 'به گزینه های \"انجام شده با\" توجه کنید. پس از دریافت و علامت زدن همه پرداختهای بیمه‌ از بیمار درخواست پرداخت مبلغ باقی مانده خواهد شد. در غیر این صورت مبلغ باقی مانده جمع آوری نمی شود! همچنین اگر مبلغ باقی مانده یی وجود دارد که بیمار باید پرداخت کند، مهلت مناسبی برای پرداخت باید قید شود که روی لحن و انشأ صورت حساب بیمار تاثیر گذار میباشد.');
INSERT INTO `lang_definitions` VALUES (197551, 8069, 31, 'توجه به جعبه های انجام شده را پرداخت کنید.پس از آنکه بیمه ها به طور کامل مشخص می شوند، ما شروع خواهیم کرد که بیمار را به پرداخت تعادل باقی مانده بپردازیم؛اگر شما نتوانستید تمام بیمه ها را علامت بزنید، مقدار باقی مانده جمع آوری نخواهد شد!همچنین اگر تعادل وجود داشته باشد که بیمار باید پرداخت کند، سپس تاریخ تعیین شده را به طور مناسب تعیین کنید، زیرا این امر بر زبان هایی که بر روی اظهارات بیمار ظاهر می شود تاثیر می گذارد.');
