INSERT INTO `lang_definitions` VALUES (199797, 10548, 31, 'با کلیک بر روی دکمه مرور و انتخاب پرونده برای بارگذاری ، و سپس با کلیک بر روی \"بارگذاری\" برای بارگذاری و نمایش فاکتورهای مربوطه.در این حالت سایر پارامترهای ذکر شده در بالا اعمال نمی شوند و نادیده گرفته می شوند.بارگذاری فایل را ذخیره می کند اما هنوز محتوای آن را پردازش نمی کند - که به شرح جداگانه انجام می شود.');
