INSERT INTO `lang_definitions` VALUES (200168, 10954, 31, 'دکمه \"پاک کردن\" همه حاشیه نویسی ها را حذف می کند.');
INSERT INTO `lang_definitions` VALUES (200169, 10955, 31, 'پنجره \"ویرایش\" به دو ستون \"فعال\" و \"غیر فعال\" تقسیم شده است.گروههایی (ARO) که در ستون فعال ذکر شده اند گروههایی هستند که کاربر به آنها تعلق دارد.');
INSERT INTO `lang_definitions` VALUES (200170, 10956, 31, 'بخش \"انتخاب کدها\" اکنون دارای کلیه کدهای CPT و ICD است که شما در گروههایی که برای آنها تصمیم گرفته اید گروه بندی شده اند');
INSERT INTO `lang_definitions` VALUES (200171, 10957, 31, 'کلید * Tab * هر ورودی را ایجاد می کند.');
INSERT INTO `lang_definitions` VALUES (200172, 10958, 31, 'فرم ادعای 1500 همچنین می تواند برای گزارش داده های برخورد بیماران به آژانس های بهداشت عمومی ، ایالتی و / یا سایر موارد استفاده شود');
INSERT INTO `lang_definitions` VALUES (200173, 10959, 31, '837P (حرفه ای) قالب استانداردی است که توسط متخصصان و تامین کنندگان مراقبت های بهداشتی برای انتقال ادعاهای مراقبت های بهداشتی به صورت الکترونیکی استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200174, 10960, 31, 'توانایی پیوند دادن مسائل منفرد با برخوردهای بیمار ، به کاربر اجازه می دهد تا به مرور نتیجه مسئله را مشخص کند');
INSERT INTO `lang_definitions` VALUES (200175, 10961, 31, 'گزاره فوق ناموفق بود');
INSERT INTO `lang_definitions` VALUES (200176, 10962, 31, 'صفحه ACL دو بخش است.');
INSERT INTO `lang_definitions` VALUES (200177, 10963, 31, 'مبالغ واقعی که نمایش داده می شوند باید در پایگاه داده وجود داشته باشد');
INSERT INTO `lang_definitions` VALUES (200178, 10964, 31, 'آزمایشات یا روشهای واقعی که می توان آنها را جستجو و سفارش داد ، با زرد مشخص شده اند');
INSERT INTO `lang_definitions` VALUES (200179, 10965, 31, 'از آیکون Add برای تنظیم ردیفی استفاده می شود که از نوادگان مستقیم این ردیف باشد');
INSERT INTO `lang_definitions` VALUES (200180, 10966, 31, 'مزیت تلفیق نتایج با نمودار بیمار به عنوان داده های ساختاری توانایی دستکاری آن برای دیدن روندها در یک مکان مناسب ، ترسیم نمودارها با داده ها و استفاده از آنها در تجزیه و تحلیل داده ها');
INSERT INTO `lang_definitions` VALUES (200181, 10967, 31, 'مزیت اسکن نتایج در نمودار سادگی است - به غیر از تعریف دایرکتوری / پوشه در نمودار بیمار تحت اسنادی که در آن نتیجه ذخیره می شود ، هیچ تنظیم دیگری مورد نیاز نیست.از آنجا که داده بدون ساختار است ، مزایای فوق را ندارد و معیارهای استفاده معنی دار برای ثبت سفارش ارائه دهنده رایانه ای (CPOE) را برآورده نمی کند');
INSERT INTO `lang_definitions` VALUES (200182, 10968, 31, 'راه حل Allscriptts وب سایت AllScript ePrescribe را با openEMR ادغام می کند');
INSERT INTO `lang_definitions` VALUES (200183, 10969, 31, 'انجمن پزشکی آمریكا 9 پنل قابل سفارش برای شما تعریف كرده است.هر پانل شامل چندین تست است که با هم گروه شده اند');
INSERT INTO `lang_definitions` VALUES (200184, 10970, 31, 'این مبلغ حسب مورد در ستون پرداخت یا تنظیم نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (200185, 10971, 31, 'گواهی سرور و کلید عمومی Apache SSL');
INSERT INTO `lang_definitions` VALUES (200186, 10972, 31, 'این برنامه چالشی را ایجاد می کند - یک عدد تصادفی و آن را به همراه کلید nonce و checksum ذخیره شده در برنامه به کلید USB منتقل می کند');
INSERT INTO `lang_definitions` VALUES (200187, 10973, 31, 'سپس برنامه برای تأیید پاسخ از کلید عمومی که دستگاه USB هنگام ثبت نام ارسال کرده استفاده می کند');
INSERT INTO `lang_definitions` VALUES (200188, 10974, 31, 'تغییر وضعیت قرار ملاقات و ایجاد مواجهه از طریق ردیاب بیمار انجام می شود.');
INSERT INTO `lang_definitions` VALUES (200189, 10975, 31, 'Auth Name یا کلید API برای حساب انتخاب شده.Auth Name برای Authorize.Net و API Secret برای Stripe.');
INSERT INTO `lang_definitions` VALUES (200190, 10976, 31, 'ستون Balance خالی خواهد بود');
INSERT INTO `lang_definitions` VALUES (200191, 10977, 31, 'هدف اصلی برنامه احراز هویت تولید کد 20 بایت (160 بیت) رمزگذاری شده در base32 با استفاده از یک تابع هش امن ، SHA-1 است و HMAC-SHA1 (کد تأیید پیام مبتنی بر Hash) نامیده می شود');
INSERT INTO `lang_definitions` VALUES (200192, 10978, 31, 'اساس CCR فرم ارجاع مراقبت از بیمار است که توسط وزارت بهداشت عمومی ماساچوست تهیه شده است');
INSERT INTO `lang_definitions` VALUES (200193, 10979, 31, 'ستون تاریخ صورتحساب / پرداخت کننده ، تاریخ دریافت مورد مورد و نام پرداخت کننده را نشان می دهد - بیمه یا بیمار');
INSERT INTO `lang_definitions` VALUES (200194, 10980, 31, 'ستون تاریخ صورتحساب / پرداخت کننده ، تاریخی است که مورد خط صورتحساب اعلام شده و پرداخت کننده - بیمه یا بیمار - را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200195, 10981, 31, 'بدن شامل داده های بالینی است که ممکن است به صورت یک یا چند بخش ساخته شده و سازمان یافته باشد یا ممکن است یک قطعه داده غیر ساختاری باشد');
INSERT INTO `lang_definitions` VALUES (200196, 10982, 31, 'جعبه های Body Site ، Administra Via و Laterality را می توان به صورت غیر واگذار شده رها کرد');
INSERT INTO `lang_definitions` VALUES (200197, 10983, 31, 'گروه پایین متشکل از Copays است');
INSERT INTO `lang_definitions` VALUES (200198, 10984, 31, 'ستون رده گروه برتر سفارشی خواهد بود و با رنگ صورتی مشخص می شود');
INSERT INTO `lang_definitions` VALUES (200199, 10985, 31, 'ستون دسته عبارت Order را نشان می دهد که نشان می دهد سفارش است');
INSERT INTO `lang_definitions` VALUES (200200, 10986, 31, 'گروه نتیجه خواهد شد');
INSERT INTO `lang_definitions` VALUES (200201, 10987, 31, 'CDA یک سند متنی ساده است که با استفاده از زبان نشانه گذاری توسعه پذیر (XML) کدگذاری می شود و شامل یک سربرگ و بدنه است');
INSERT INTO `lang_definitions` VALUES (200202, 10988, 31, 'گواهی مرجع صدور گواهینامه');
INSERT INTO `lang_definitions` VALUES (200203, 10989, 31, 'ستون شارژ خالی خواهد بود');
INSERT INTO `lang_definitions` VALUES (200204, 10990, 31, 'شارژ مبلغ واقعی است که برای هر مورد از خط شارژ می شود');
INSERT INTO `lang_definitions` VALUES (200205, 10991, 31, 'پرونده ادعا:');
INSERT INTO `lang_definitions` VALUES (200206, 10992, 31, 'فرم CMS 1500 دارای 33 جعبه است و به دو بخش تقسیم می شود');
INSERT INTO `lang_definitions` VALUES (200207, 10993, 31, 'ستون Code باید دارای 905 باشد ، کد شناسایی مشخص کننده فروشنده که قبلاً وارد شده است');
INSERT INTO `lang_definitions` VALUES (200208, 10994, 31, 'ستون کد خالی خواهد بود زیرا موارد ذکر شده به عنوان گروه در گزارش واقعی نتایج استفاده نمی شوند و بنابراین شماره کد مشخصی ندارند');
INSERT INTO `lang_definitions` VALUES (200209, 10995, 31, 'کد R905 خواهد بود ، مقدار کد شناسایی که برای نتیجه گسسته وارد شده است');
INSERT INTO `lang_definitions` VALUES (200210, 10996, 31, 'کدی که وارد کردید معتبر نیست');
INSERT INTO `lang_definitions` VALUES (200211, 10997, 31, 'بسته سازگار SNOMED مرحله داخلی US قبلاً نصب شده است.');
INSERT INTO `lang_definitions` VALUES (200212, 10998, 31, 'سلول مخاطب دارای اطلاعات مختلفی از جمله شماره تلفن ، ایمیل و غیره است');
INSERT INTO `lang_definitions` VALUES (200213, 10999, 31, 'سند تداوم مراقبت (CCD) و سابقه تداوم مراقبت (CCR) هر دو به عنوان فرمت های قابل قبول برای استخراج اطلاعات خلاصه مراقبت های بالینی به عنوان بخشی از مرحله استفاده معنی دار انتخاب شدند.');
INSERT INTO `lang_definitions` VALUES (200214, 11000, 31, 'سوابق تداوم مراقبت (CCR) توسط ASTM International به طور مشترک تهیه شده است - سازمانی که در توسعه و تحویل اجماع داوطلبانه شرکت دارد ، انجمن پزشکی ماساچوست (MMS) ، انجمن مدیریت اطلاعات و سیستم های سلامت (HIMSS) ،آكادمی پزشكان خانواده آمریكا (AAFP) و آكادمی اطفال آمریكا');
INSERT INTO `lang_definitions` VALUES (200215, 11001, 31, 'سوابق تداوم مراقبت (CCR) سوابق بالینی وضعیت مراقبت های بهداشتی فعلی و تاریخی بیمار است');
INSERT INTO `lang_definitions` VALUES (200216, 11002, 31, 'مجموعه داده اصلی شامل');
INSERT INTO `lang_definitions` VALUES (200217, 11003, 31, 'کلید خصوصی مربوطه');
INSERT INTO `lang_definitions` VALUES (200218, 11004, 31, 'گزارش ایجاد شده بر اساس نیاز می تواند حاوی اطلاعاتی به میزان کم یا زیاد باشد');
INSERT INTO `lang_definitions` VALUES (200219, 11005, 31, 'اکنون روش احراز هویت فعلی برای بخش ورود به سیستم کاربر ، روشهای فعال شده را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200220, 11006, 31, 'روش تأیید اعتبار فعلی ، تمام روشهایی را که فعال هستند لیست می کند');
INSERT INTO `lang_definitions` VALUES (200221, 11007, 31, 'از برگه هزینه نگهداری می توان استفاده کرد.اگر و وقتی با کدی روبرو شدید که در قسمت سفارشی \"انتخاب کدها\" وجود ندارد ، همیشه می توانید از بخش \"جستجو برای کدهای اضافی\" استفاده کنید');
INSERT INTO `lang_definitions` VALUES (200222, 11008, 31, 'ردیف مورد دلخواه سفارشی باید فرزندان مستقیم یا فرزند گروه مورد علاقه سفارشی مربوطه باشد');
INSERT INTO `lang_definitions` VALUES (200223, 11009, 31, 'همچنین گروه بندی سفارشی به شما امکان می دهد دو صفحه آزمون شناخته شده را در یک گروه سفارشی قرار دهید و بنابراین آنها را با هم ترتیب دهید ،یک گروه سفارشی از آزمایشگاه های Preop ممکن است شامل دو صفحه CBC و Renal Panel باشد');
INSERT INTO `lang_definitions` VALUES (200224, 11010, 31, 'داشبورد محل اصلی دسترسی راحت به پرونده پزشکی بیمار است');
INSERT INTO `lang_definitions` VALUES (200225, 11011, 31, 'صفحه داشبورد به سه بخش تقسیم شده است');
INSERT INTO `lang_definitions` VALUES (200226, 11012, 31, 'آزمون یکپارچگی داده ها برای این فرم ناموفق بود');
INSERT INTO `lang_definitions` VALUES (200227, 11013, 31, 'در بخش داده ها در صفحه داشبورد همه موارد مربوط به یک بیمار ذکر شده است');
INSERT INTO `lang_definitions` VALUES (200228, 11014, 31, 'یادآوری تاریخ دار 5 روز قبل از تاریخ یادآوری در بخش یادآوری های تاریخ شروع به نمایش می کند');
INSERT INTO `lang_definitions` VALUES (200229, 11015, 31, 'نوع کد پیش فرض برای جستجو در صفحه هزینه.');
INSERT INTO `lang_definitions` VALUES (200230, 11016, 31, 'ورق پیش فرض کارمزد را می توان برای مفیدتر کردن ، اصلاح و سفارشی کرد.');
INSERT INTO `lang_definitions` VALUES (200231, 11017, 31, 'ورقه پیش فرض کارمزد به چندین بخش تقسیم شده و به گونه ای طراحی شده است که در انتهای آن با دکمه ذخیره از بالا به پایین پر می شود.');
INSERT INTO `lang_definitions` VALUES (200232, 11018, 31, 'فرم پیش فرض را می توان با ویرایش در اداره> پوسته ها سفارشی کرد');
INSERT INTO `lang_definitions` VALUES (200233, 11019, 31, 'پیش فرض دارای دو دکمه است که برای \"بیمار جدید\" و \"تأسیس شده\" تنظیم شده است');
INSERT INTO `lang_definitions` VALUES (200234, 11020, 31, 'نصب پیش فرض دارای شش گروه از این قبیل است: حسابداری ، سرپرستان ، پزشکان ، ورود به سیستم اضطراری ، مطب و پزشکان.');
INSERT INTO `lang_definitions` VALUES (200235, 11021, 31, 'نصب پیش فرض موارد زیر را دارد');
INSERT INTO `lang_definitions` VALUES (200236, 11022, 31, 'نصب پیش فرض 5 نوع مسئله را که می تواند مستند شود لیست می کند');
INSERT INTO `lang_definitions` VALUES (200237, 11023, 31, 'نصب پیش فرض تماس تلفنی را به طور خودکار برقرار نمی کند');
INSERT INTO `lang_definitions` VALUES (200238, 11024, 31, 'پیش فرض \"استاندارد\" است که معمولاً برای منعکس کردن نرخ های صورتحساب بیمه استفاده می شود.برای پرداخت کارت اعتباری و پرداخت نقدی می توانید مبلغ دیگری شارژ کنید');
INSERT INTO `lang_definitions` VALUES (200239, 11025, 31, 'پیش فرض نرمال است ، یعنی برای همه قابل مشاهده است.با انتخاب High به طور پیش فرض فقط به کاربران عضو گروه پزشکان و سرپرستان محدود می شود');
INSERT INTO `lang_definitions` VALUES (200240, 11026, 31, 'نوع شماره پیش فرض روی Problem تنظیم شده است');
INSERT INTO `lang_definitions` VALUES (200241, 11027, 31, 'مرکز پیام رسانی پیش فرض به سه بخش تقسیم شده است: پیام ها ، یادآوری ها و یادآوری ها');
INSERT INTO `lang_definitions` VALUES (200242, 11028, 31, 'مقادیر پیش فرض ارائه دهندگان ارائه را می توان تنظیم کرد');
INSERT INTO `lang_definitions` VALUES (200243, 11029, 31, 'کد انکار است');
INSERT INTO `lang_definitions` VALUES (200244, 11030, 31, 'کد انکار گروه است');
INSERT INTO `lang_definitions` VALUES (200245, 11031, 31, 'ستون توضیحات توضیح کوتاهی را که وارد شده است ، آزمایشات شیمی سرم نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200246, 11032, 31, 'ستون توضیحات مقدار توصیفی را که قبلاً وارد شده است منعکس می کند');
INSERT INTO `lang_definitions` VALUES (200247, 11033, 31, 'در این توضیحات باید نتیجه اسید اوریک سرم باشد');
INSERT INTO `lang_definitions` VALUES (200248, 11034, 31, 'در توضیحات نوع پرداخت یا تعدیل - نقدی ، چک ، الکترونیکی و غیره توضیح داده خواهد شد');
INSERT INTO `lang_definitions` VALUES (200249, 11035, 31, 'فرم مقصد بسته شد');
INSERT INTO `lang_definitions` VALUES (200250, 11036, 31, 'فرم مقصد بسته شد.');
INSERT INTO `lang_definitions` VALUES (200251, 11037, 31, 'فرم مقصد بسته شد.من نمی توانم براساس انتخاب شما عمل کنم.');
INSERT INTO `lang_definitions` VALUES (200252, 11038, 31, 'تفاوت این دو در این است که برای مجموعه ای از تست ها که با هم ترتیب داده می شوند ، تست های منفرد فقط توسط نتیجه گسسته نشان داده می شوند و این آزمون ها را نمی توان جداگانه سفارش داد ، مگر اینکه به صورت تک تست نیز تنظیم شده باشد.');
INSERT INTO `lang_definitions` VALUES (200253, 11039, 31, 'برای نمایش صحیح نتایج ، ردیف گسسته نتیجه باید از نوادگان مستقیم یا فرزند ردیف سفارش مراحل باشد');
INSERT INTO `lang_definitions` VALUES (200254, 11040, 31, 'نتایج گسسته برای هر پانل حاوی اسامی آزمایشات جداگانه برای نگهداری مقادیر نتایج برگشتی است - WBC ، هموگلوبین ، پلاکت ، سدیم ، پتاسیم و غیره');
INSERT INTO `lang_definitions` VALUES (200255, 11041, 31, 'با کلیک و کشیدن گوشه پایین سمت راست پنجره ، می توانید اندازه پنجره نمایش را تغییر دهید');
INSERT INTO `lang_definitions` VALUES (200256, 11042, 31, 'گزینه هر قرار ملاقات بدون توجه به بازدید همان روز ، امکان برخورد جدید را فراهم می کند.');
INSERT INTO `lang_definitions` VALUES (200257, 11043, 31, 'دکمه پیش نمایش برخورد برای نشان دادن فرم های چیدمان نوع برخورد همانطور که هنگام استفاده از فرم در یک برخورد مشاهده می شود ، مفید است.توجه داشته باشید ، این ویژگی فقط برای نشان دادن فرمهای برخورد مفید است و فرمهای سیستم مانند دموگرافیک را نمایش نمی دهد');
INSERT INTO `lang_definitions` VALUES (200258, 11044, 31, 'بخش برخورد ها تاریخ برخورد و همچنین شکایت ارائه شده را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200259, 11045, 31, 'نتیجه نهایی یک مجموعه گیج کننده اسناد حاوی اطلاعات مبهم و / یا متناقض بود');
INSERT INTO `lang_definitions` VALUES (200260, 11046, 31, 'کادر بازشو Enter Details در حالت افزودن باز می شود');
INSERT INTO `lang_definitions` VALUES (200261, 11047, 31, 'پنجره بازشوی Enter Provider Details قابل مشاهده خواهد بود');
INSERT INTO `lang_definitions` VALUES (200262, 11048, 31, 'کل مجموعه ACO ها لیست کنترل دسترسی (ACL) را تشکیل می دهند.');
INSERT INTO `lang_definitions` VALUES (200263, 11049, 31, 'موجودیت مورد دلخواه سفارشی موجودی است که برای گروه مورد علاقه سفارشی انتخاب شده است و قابل تغییر نیست');
INSERT INTO `lang_definitions` VALUES (200264, 11050, 31, 'نهادی که این رویه را انجام می دهد');
INSERT INTO `lang_definitions` VALUES (200265, 11051, 31, 'مطالب ورودی حاوی داده هایی است که برای پردازش بیشتر رایانه استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200266, 11052, 31, 'ورودی هایی که با رنگ زرد برجسته شده اند را می توان به عنوان یک آزمون یا رویه ای که با رنگ صورتی مشخص شده اند ، می توان به عنوان یک گروه سفارشی سفارش داد');
INSERT INTO `lang_definitions` VALUES (200267, 11053, 31, 'EP ، بیمارستان یا CAH واجد شرایط که بیمار را از یک محیط مراقبت دیگر یا ارائه دهنده مراقبت دریافت می کند یا معتقد است که یک برخورد مرتبط است ، باید مصالحه دارو را انجام دهد.');
INSERT INTO `lang_definitions` VALUES (200268, 11054, 31, 'EP ، بیمارستان یا CAH واجد شرایط که بیمار خود را به یک مکان دیگر از مراقبت یا ارائه دهنده مراقبت منتقل می کند یا بیمار خود را به یک ارائه دهنده دیگر مراقبت ارجاع می دهد ، باید خلاصه سوابق مراقبت را برای هر انتقال مراقبت یا ارجاع ارائه دهد (اندازه A).');
INSERT INTO `lang_definitions` VALUES (200269, 11055, 31, 'EP ، بیمارستان یا CAH واجد شرایط که بیمار خود را به یک مکان دیگر از مراقبت یا ارائه دهنده مراقبت منتقل می کند یا بیمار خود را به یک ارائه دهنده دیگر مراقبت ارجاع می دهد ، باید خلاصه سوابق مراقبت را برای هر انتقال مراقبت یا ارجاع ارائه دهد (اندازه ب).');
INSERT INTO `lang_definitions` VALUES (200270, 11056, 31, 'EP ، بیمارستان واجد شرایط CAH یا بیمارانی که بیمار خود را به وضعیت دیگری از مراقبت یا ارائه دهنده مراقبت منتقل می کنند یا بیمار خود را به ارائه دهنده دیگر مراقبت ارجاع می دهند ، باید خلاصه سوابق مراقبت را برای هر انتقال مراقبت یا ارجاع ارائه دهند.');
INSERT INTO `lang_definitions` VALUES (200271, 11057, 31, 'این رویداد تأیید شده است.');
INSERT INTO `lang_definitions` VALUES (200272, 11058, 31, 'این رویداد پنهان شده است');
INSERT INTO `lang_definitions` VALUES (200273, 11059, 31, 'داده های صادر شده در قسمت متن زیر ظاهر می شود.می توانید این را در ایمیل یا در هر مقصد دلخواه دیگری کپی و پیست کنید.');
INSERT INTO `lang_definitions` VALUES (200274, 11060, 31, 'داده های صادر شده در قسمت متن زیر ظاهر می شود.می توانید این را در ایمیل کپی کرده و در مقصد مورد نظر خود قرار دهید (یا) لینک زیر را بارگیری کنید.');
INSERT INTO `lang_definitions` VALUES (200275, 11061, 31, 'داده های صادر شده در قسمت متن زیر ظاهر می شود.می توانید این را در ایمیل یا در هر مقصد دلخواه دیگری کپی و پیست کنید.');
INSERT INTO `lang_definitions` VALUES (200276, 11062, 31, 'داده های صادر شده در قسمت متن زیر ظاهر می شود.می توانید این را در یک ایمیل یا مقصد دلخواه دیگری کپی و پیست کنید. {{MARK FOR DELETION DURING NEXT TRANSLATION BUILD}}');
INSERT INTO `lang_definitions` VALUES (200277, 11063, 31, 'ویژگی های نصب فعال شده MedEx در این ویدئو توضیح داده شده است');
INSERT INTO `lang_definitions` VALUES (200278, 11064, 31, 'پرونده مجدداً تولید نمی شود.آیا شما می خواهید ادامه دهید؟');
INSERT INTO `lang_definitions` VALUES (200279, 11065, 31, 'پرونده در CouchDB ذخیره نشد.');
INSERT INTO `lang_definitions` VALUES (200280, 11066, 31, 'نام فایل را با موفقیت نمی توان تغییر داد ، این خطا معمولاً مربوط به مشکلات مجوزها در سیستم ذخیره سازی است.');
INSERT INTO `lang_definitions` VALUES (200281, 11067, 31, 'پرونده نمی تواند با موفقیت ذخیره شود ، این خطا معمولاً مربوط به مشکلات مجوزهای سیستم ذخیره سازی است');
INSERT INTO `lang_definitions` VALUES (200282, 11068, 31, 'بخش فیلتر را می توان با کلیک کردن بر روی فلش در پایین سمت راست پنهان یا آشکار کرد');
INSERT INTO `lang_definitions` VALUES (200283, 11069, 31, 'نتایج فیلتر شده در بخش زیر آن نشان داده می شود');
INSERT INTO `lang_definitions` VALUES (200284, 11070, 31, 'جدول یاب بر اساس روشهای گذشته و سپس کد تشخیص گروه بندی می شود.اگرچه ممکن است کدهای dx تکراری وجود داشته باشد ، اما با سهولت مناسب لیست تشخیص های ساختمان گروه بندی می شوند.');
INSERT INTO `lang_definitions` VALUES (200285, 11071, 31, 'نمودار (\"هدف\") اولین نمودار است که کامل ترین و دقیق ترین آن در نظر گرفته شده است.بخش های جمعیتی ، سابقه و بیمه برای این بخش حفظ می شود.');
INSERT INTO `lang_definitions` VALUES (200286, 11072, 31, 'ستون اول شامل نام گروه / دسته است که روی دکمه نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (200287, 11073, 31, 'ستون اول نامی است که شما در این قسمت قرار داده اید ، یعنی شیمی سرم.یک نوار عمودی قبل از نام واقعی است.این نشان می دهد که هیچ فرزندی یا فرزندی در این ورود وجود ندارد');
INSERT INTO `lang_definitions` VALUES (200288, 11074, 31, 'چهار بخش اول مربوط به ایجاد سفارشات رویه به روشی ساخت یافته به منظور سهولت در سفارش آسان آزمونها و ورود دستی نتایج بازگشتی است.');
INSERT INTO `lang_definitions` VALUES (200289, 11075, 31, 'خط اول تاریخ برخورد و دلیل و همچنین ارائه دهنده آن برخورد را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200290, 11076, 31, 'بخش اول به شما امکان می دهد در صورت تمایل این پیام را به بیمار پیوند دهید.');
INSERT INTO `lang_definitions` VALUES (200291, 11077, 31, 'اولین بخش در هر پیام HL7 همیشه پیام هدر است ، بخشی است که فراداده پیام را ارسال می کند مانند اینکه چه کسی آن را ارسال کرده و چه زمانی.سربرگ Message در سه حرف اول بخش به عنوان MSH نشان داده شده است');
INSERT INTO `lang_definitions` VALUES (200292, 11078, 31, 'اولین قدم ثبت نام برای یک حساب کاربری پیام مستقیم تولید با EMR Direct با ثبت نام در وب سایت آنها است');
INSERT INTO `lang_definitions` VALUES (200293, 11079, 31, 'اولین قدم این است که نسخه SNOMED CT را بارگیری کنید.دسترسی به SNOMED CT توسط IHTSDO و کشورهای عضو آنها فراهم شده است.برای اطلاعات بیشتر ببین');
INSERT INTO `lang_definitions` VALUES (200294, 11080, 31, 'اولین قدم این است که نسخه VALUESET را بارگیری کنید.دسترسی به VALUESET توسط NLM فراهم شده است.فقط مقدارهای مربوط به افراد واجد شرایط لازم است بارگیری شود و باید در قالب XML از ستون مرتب سازی بر اساس شناسه CMS بارگیری شود.برای اطلاعات بیشتر به پیوند زیر مراجعه کنید');
INSERT INTO `lang_definitions` VALUES (200295, 11081, 31, 'اولین قدم افتتاح حساب با وب سایت Unified Medical Language System است');
INSERT INTO `lang_definitions` VALUES (200296, 11082, 31, 'اولین قدم این است که برنامه هایی را که بخش Fee Sheet \"انتخاب کدها\" نشان می دهد ، برنامه ریزی کنید');
INSERT INTO `lang_definitions` VALUES (200297, 11083, 31, 'اولین قدم انتخاب نوع معامله است');
INSERT INTO `lang_definitions` VALUES (200298, 11084, 31, 'اولین قدم ایجاد یک ورودی سطح بالا است.این کار را با کلیک کردن روی دکمه افزودن سطح بالا انجام دهید');
INSERT INTO `lang_definitions` VALUES (200299, 11085, 31, 'اولین برگه برگه ارجاع است که ارجاع انجام شده را تشکیل می دهد');
INSERT INTO `lang_definitions` VALUES (200300, 11086, 31, 'از دو عدد اول در ستون اول و دوم برای تعیین ترتیب مرتب سازی دکمه ها و لیست هایی که در پنجره بازشو وجود دارد استفاده خواهد شد');
INSERT INTO `lang_definitions` VALUES (200301, 11087, 31, 'رویداد تقویم زیر اضافه شده است:');
INSERT INTO `lang_definitions` VALUES (200302, 11088, 31, 'رویداد تقویم زیر اصلاح شده است:');
INSERT INTO `lang_definitions` VALUES (200303, 11089, 31, 'دسته های زیر از لیست دسته شما حذف می شوند');
INSERT INTO `lang_definitions` VALUES (200304, 11090, 31, 'نسخه دیتابیس زیر در حال حاضر نصب شده است');
INSERT INTO `lang_definitions` VALUES (200305, 11091, 31, 'اسناد زیر به این پیام مستقیم پیوست شده است:');
INSERT INTO `lang_definitions` VALUES (200306, 11092, 31, 'بایگانی فایل EDI زیر ذخیره نشد');
INSERT INTO `lang_definitions` VALUES (200307, 11093, 31, 'فایل EDI زیر بارگذاری شده است');
INSERT INTO `lang_definitions` VALUES (200308, 11094, 31, 'بارگذاری پرونده EDI زیر باز نشد');
INSERT INTO `lang_definitions` VALUES (200309, 11095, 31, 'کاربر ورود به سیستم اضطراری زیر فعال شده است:');
INSERT INTO `lang_definitions` VALUES (200310, 11096, 31, 'خطاهای زیر رخ داده است');
INSERT INTO `lang_definitions` VALUES (200311, 11097, 31, 'قسمت زیر مقدار نامعتبری دارد');
INSERT INTO `lang_definitions` VALUES (200312, 11098, 31, 'قسمتهای زیر خالی هستند');
INSERT INTO `lang_definitions` VALUES (200313, 11099, 31, 'موارد ذیل مورد نیاز است');
INSERT INTO `lang_definitions` VALUES (200314, 11100, 31, 'برای ارسال درخواست باید قسمتهای زیر پر شود.');
INSERT INTO `lang_definitions` VALUES (200315, 11101, 31, 'موارد ذیل باید پر شوئد تا درخواست ارسال شود.');
INSERT INTO `lang_definitions` VALUES (200316, 11102, 31, 'در زیر زبان بین المللی SNOMED انتشار پشتیبانی می شوند');
INSERT INTO `lang_definitions` VALUES (200317, 11104, 31, 'موارد زیر رخ داد');
INSERT INTO `lang_definitions` VALUES (200318, 11105, 31, 'مشکلات زیر دارای کدهای تشخیصی یکسان هستند.مشکلات برخورد به روز نمی شودلطفاً به جای آن از رابط برخورد استفاده کنید.');
INSERT INTO `lang_definitions` VALUES (200319, 11106, 31, 'مراحل زیر به سفارشی کردن Fee Sheet کمک می کند تا فوق العاده اسکناس کاغذی قدیمی را با لیستی از کدهای CPT4 و ICD در دسته ها تقلید کند');
INSERT INTO `lang_definitions` VALUES (200320, 11107, 31, 'گروهی (ARO) که ایجاد کرده اید اکنون به ترتیب حروف الفبا در بخش \"گروه ها و کنترل دسترسی\" ظاهر می شوند.');
INSERT INTO `lang_definitions` VALUES (200321, 11108, 31, 'سرصفحه متن كلی سند بالینی را تعریف می كند');
INSERT INTO `lang_definitions` VALUES (200322, 11109, 31, 'بخش سرصفحه اطلاعات خاص بیمار را در اکثر صفحات مربوط به پرونده پزشکی بیمار نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200323, 11110, 31, 'فرم ادعای بیمه سلامت اغلب با شماره فرم CMS 1500 (HCFA 1500) ارجاع می شود');
INSERT INTO `lang_definitions` VALUES (200324, 11111, 31, 'پرونده راهنما به بخشهای زیر تقسیم شده است');
INSERT INTO `lang_definitions` VALUES (200325, 11112, 31, 'پرونده راهنما در آنجا شما را درمورد مراحل بعدی تنظیم آزمایشات راهنمایی می کند');
INSERT INTO `lang_definitions` VALUES (200326, 11113, 31, 'نماد راهنما به شما امکان می دهد به راهنمای حساس به متن برای هر یک از صفحات دسترسی پیدا کنید');
INSERT INTO `lang_definitions` VALUES (200327, 11114, 31, 'نام میزبان دستگاه مخزن حسابرسی ATNA.');
INSERT INTO `lang_definitions` VALUES (200328, 11115, 31, 'نام میزبان یا URI سرور LDAP یا Active Directory شما.');
INSERT INTO `lang_definitions` VALUES (200329, 11116, 31, 'برای اینکه نتایج به درستی نمایش داده شوند ، کد شناسایی باید منحصر به فرد باشد ، شما فقط می توانید از R905 به عنوان مثال استفاده کنید');
INSERT INTO `lang_definitions` VALUES (200330, 11117, 31, 'کد شناسایی باید منحصر به فرد باشد ، در صورتی که فروشنده کد شناسایی را وارد می کند ، باید به یک آزمایشگاه خارجی وارد شود.ما یک مقدار بی نظیر دلخواه - WWT01 وارد خواهیم کرد');
INSERT INTO `lang_definitions` VALUES (200331, 11118, 31, 'کد شناسایی یک کد مخصوص فروشنده است که این روش یا نتیجه را مشخص می کند.نمونه هایی از آن را می توانید در برگه های آزمایشگاه کاغذ مشاهده کنید که آزمایشگاه ها از آن استفاده می کنند');
INSERT INTO `lang_definitions` VALUES (200332, 11119, 31, 'کد شناسایی برای نمایش مناسب و جدول بندی نتایج ضروری است');
INSERT INTO `lang_definitions` VALUES (200333, 11120, 31, 'کد شناسایی R34392-1 ، یک عدد دلخواه ، در این مورد کد شناسایی قبل از R برای نشان دادن نتیجه و موفق به 1 با نشان دادن اولین ترتیب ، می تواند هر چیز منحصر به فردی باشد که انتخاب کنید');
INSERT INTO `lang_definitions` VALUES (200334, 11121, 31, 'اطلاعات وارد شده در اینجا برای نمایش خلاصه ای از برخورد استفاده می شود.این همچنین برای اهداف صورتحساب استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200335, 11122, 31, 'اطلاعات وارد شده در این فرم برای تکمیل ادعای مقاله استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200336, 11123, 31, 'اطلاعات ارائه شده در فرم برخورد جدید و برگ هزینه در openEMR برای تولید ادعای کاغذی و همچنین ادعاهای الکترونیکی استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200337, 11124, 31, 'تلاش های اولیه منجر به ایجاد راهنماهای پیاده سازی تکراری و متناقض (IG) منتشر شده توسط سازمانهای استاندارد مختلف شد');
INSERT INTO `lang_definitions` VALUES (200338, 11125, 31, 'صفحه اولیه به شما امکان می دهد با ارائه این دو گزینه به شما روشی را انتخاب کنید.');
INSERT INTO `lang_definitions` VALUES (200339, 11126, 31, 'صفحه اول برای جستجوی فاکتور است. در بالای صفحه، میتوانید یک مرجع اطلاعات (مثلا شماره چک)، تاریخ پرداخت و مبلغ چک را وارد کنید. دلیل قید مرجع اطلاعات و تاریخ پرداخت آن است که مجبور نباشید آنها را مجددا برای هر مطالبه وارد کنید. مبلغ وارد شده برای هر فاکتور بر اساس هر صورت حساب پرداختی مربوطه کاهش میابد، و انشاءالله سرانجام به صفر می‌رسد.');
INSERT INTO `lang_definitions` VALUES (200340, 11127, 31, 'ورودی باید یک فایل CSV با 3 ستون باشد: شناسه طرح ، نوع کد و کد.');
INSERT INTO `lang_definitions` VALUES (200341, 11128, 31, 'فهرست نصب باید ایجاد شود.');
INSERT INTO `lang_definitions` VALUES (200342, 11129, 31, 'نسخه بین المللی SNOMED نصب شده با بسته برنامه SNOMED داخلی Extension سازگار نیست.');
INSERT INTO `lang_definitions` VALUES (200343, 11130, 31, 'نسخه نصب شده SNOMED بین المللی قدیمی است و با پرونده مرحله ای SNOMED پسوند ایالات متحده سازگار نیست.');
INSERT INTO `lang_definitions` VALUES (200344, 11131, 31, 'نسخه نصب شده و پرونده های مرحله ای یکسان هستند.');
INSERT INTO `lang_definitions` VALUES (200345, 11132, 31, 'نسخه نصب شده نسخه جدیدتری نسبت به پرونده های مرحله بندی شده است.');
INSERT INTO `lang_definitions` VALUES (200346, 11133, 31, 'کتابچه راهنمای نحوه پر کردن فرم CMS 1500 را می توانید در اینجا پیدا کنید');
INSERT INTO `lang_definitions` VALUES (200347, 11134, 31, 'آدرس IP کنترل کننده (های) دامنه شما.');
INSERT INTO `lang_definitions` VALUES (200348, 11135, 31, 'شماره ها را می توان به یکی از دو روش وارد کرد');
INSERT INTO `lang_definitions` VALUES (200349, 11136, 31, 'در بخش Issues تمام مسائل وارد شده برای بیمار نمایش داده می شود و نوع شماره ، عنوان آن و توضیحات نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (200350, 11137, 31, 'موارد ذکر شده در ستون \"فعال\" امتیازات این گروه (ARO) را مشخص می کند و لیست کنترل دسترسی این گروه (ACL) را تشکیل می دهد.');
INSERT INTO `lang_definitions` VALUES (200351, 11138, 31, 'مواردی که بعد از آنها ستاره دارند ، اجباری هستند');
INSERT INTO `lang_definitions` VALUES (200352, 11140, 31, 'برچسبی که در فرم برای کاربر نشان داده می شود');
INSERT INTO `lang_definitions` VALUES (200353, 11141, 31, 'آخرین سلول روی خط در برخورد');
INSERT INTO `lang_definitions` VALUES (200354, 11142, 31, 'آخرین خط از این بلوک برخورد مجموع مواجهه با شارژها ، پرداخت ها ، تنظیمات و مانده را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200355, 11143, 31, 'آخرین بخش مربوط به سفارشات الکترونیکی است');
INSERT INTO `lang_definitions` VALUES (200356, 11144, 31, 'تاریخ آخرین بازدید به طور خودکار پر می شود');
INSERT INTO `lang_definitions` VALUES (200357, 11145, 31, 'آخرین نسخه FHIR - منابع تعاملی سریع بهداشت و درمان - یک چارچوب استاندارد بعدی است که توسط HL7 ایجاد شده است.این مورد در حال کسب محبوبیت است اما هنوز به طور گسترده اجرا نشده است');
INSERT INTO `lang_definitions` VALUES (200358, 11146, 31, 'کد یاب قدیمی همچنان برای کدهایی موجود نیست که در این یاب یا ویرایش لیست کد یافت نمی شوند.');
INSERT INTO `lang_definitions` VALUES (200359, 11147, 31, 'طول نباید از تعداد نویسه های زیر بیشتر باشد');
INSERT INTO `lang_definitions` VALUES (200360, 11148, 31, 'ورود به سیستم با شناسه زیر حذف شده است');
INSERT INTO `lang_definitions` VALUES (200361, 11150, 31, 'جدول ورود به سیستم لیستی از پیام ها و یادآوری های تاریخ دار در صورت وجود را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200362, 11151, 31, 'کد LOINC برای اسید اوریک سرم 3084-1 است ، LOINC از آن با عنوان Urate در سرم یا پلاسما یاد می کند');
INSERT INTO `lang_definitions` VALUES (200363, 11152, 31, 'ادغام اجرا نمی شود مگر اینکه SSN و DOB برای دو نمودار یکسان باشند.DOB ها نمی توانند خالی باشند.');
INSERT INTO `lang_definitions` VALUES (200364, 11153, 31, 'در حال حاضر پیام ارسال نمی شود.');
INSERT INTO `lang_definitions` VALUES (200365, 11154, 31, 'وضعیت پیام جدید خواهد بود زیرا پیام جدیدی است که در حال ایجاد است');
INSERT INTO `lang_definitions` VALUES (200366, 11155, 31, 'پیام های ارسال شده توسط کاربر در آن روز در جدول زیر نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (200367, 11156, 31, 'مرکز پیام رسانی به راحتی گزینه های ارتباطی را در یک مکان تلفیق می کند');
INSERT INTO `lang_definitions` VALUES (200368, 11157, 31, 'مرکز پیام با فعال شدن برگه پیام ها باز می شود و پیام های کاربر وارد شده را همانطور که در عنوان پیام های من نشان داده شده است نمایش می دهد');
INSERT INTO `lang_definitions` VALUES (200369, 11158, 31, 'حداقل اطلاعات مورد نیاز برای ایجاد یک مواجهه جدید ، انتخاب دسته بازدید است');
INSERT INTO `lang_definitions` VALUES (200370, 11159, 31, 'از گزینه های مختلف صورتحساب برای فرم HCFA-1500 برای ارائه اطلاعات اضافی برای ادعای شخصی استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200371, 11160, 31, 'متداول ترین روش ، مجوز 2-Factor یا 2FA نامیده می شود');
INSERT INTO `lang_definitions` VALUES (200372, 11161, 31, 'مهمترین مسئله ای که باید مورد توجه قرار گیرد این است که شما به چه کسی می خواهید وصل شوید و چه اتفاقی باید در پایان آنها بیفتد.اکثر آزمایشگاه های اصلی با شیوه های افراد سروکار نخواهند داشت ، در چنین مواردی فروشنده شخص ثالث با واسطه ای رفتار خواهد کرد که مسئول ایجاد ارتباط بین آزمایشگاه و آزمایشگاه از طریق رابط کاربری آنها (واسطه) خواهد بود.');
INSERT INTO `lang_definitions` VALUES (200373, 11162, 31, 'معروف ترین سازنده Security Keys Yubico است که نسخه های معمولی USB و همچنین نسخه های ساخته شده برای دستگاه هایی را که به اتصالات USB-C نیاز دارند مانند سیستم های جدیدتر Mac OS اپل ارائه می دهد.');
INSERT INTO `lang_definitions` VALUES (200374, 11163, 31, 'محبوب ترین راه حل مدیریت پرونده های الکترونیکی سلامت الکترونیکی و منبع باز الکترونیکی.');
INSERT INTO `lang_definitions` VALUES (200375, 11164, 31, 'سلول Name دارای نام ، تاریخ تولد ، شناسه بیمار و تاریخ آخرین مراجعه است');
INSERT INTO `lang_definitions` VALUES (200376, 11165, 31, 'بلوک داستانی شامل اطلاعاتی است که به صورت متن قابل خواندن ارائه می شود');
INSERT INTO `lang_definitions` VALUES (200377, 11166, 31, 'کمیته ادعای لباس متحدالشکل ملی (NUCC) مسئول نگهداری فرم ادعای 1500 است');
INSERT INTO `lang_definitions` VALUES (200378, 11167, 31, 'Nav Bar به فرد امکان می دهد تا به سرعت به قسمتهای مختلف پرونده پزشکی بیمار پیمایش کند');
INSERT INTO `lang_definitions` VALUES (200379, 11168, 31, 'دسته جدید یک زیر مجموعه از خواهد بود');
INSERT INTO `lang_definitions` VALUES (200380, 11169, 31, 'لیست جدید');
INSERT INTO `lang_definitions` VALUES (200381, 11170, 31, 'رمز ورود جدید نمی تواند همان رمز عبور فعلی باشد.');
INSERT INTO `lang_definitions` VALUES (200382, 11171, 31, 'قسمتهای رمز عبور جدید یکسان نیستند.');
INSERT INTO `lang_definitions` VALUES (200383, 11172, 31, 'رمز جدید همان رمز عبور فعلی است.برای پذیرش به هر حال روی Okay کلیک کنید.');
INSERT INTO `lang_definitions` VALUES (200384, 11173, 31, 'نام شریک NewCrop eRx ، نام NewCrop eRx و رمز عبور eCx NewCrop توسط فروشنده ارائه می شود');
INSERT INTO `lang_definitions` VALUES (200385, 11174, 31, 'جعبه بعدی Body Site است ، که برای آزمایش خون مناسب نیست اما ممکن است برای گفتن تزریق یا سفارش اشعه ایکس مفیدتر باشد');
INSERT INTO `lang_definitions` VALUES (200386, 11175, 31, 'در چند خط بعدی تمام کدهای E / M و CPT که صورتحساب شده اند ، یک خط به ازای هر کد لیست می شوند');
INSERT INTO `lang_definitions` VALUES (200387, 11176, 31, 'گروه بعدی شامل کدهای ICD است');
INSERT INTO `lang_definitions` VALUES (200388, 11177, 31, 'سه سلول بعدی سلول های عملیاتی هستند که به شما امکان می دهند برخی فعالیت های یادآوری را انجام دهید');
INSERT INTO `lang_definitions` VALUES (200389, 11178, 31, 'دو کادر بعدی که نشان دهنده کد شناسایی و استاندارد کد هستند بسیار مهم هستند');
INSERT INTO `lang_definitions` VALUES (200390, 11179, 31, 'سلول Notes به شما امکان می دهد یک یادداشت را به عملی که در 3 سلول عمل انجام می دهید یا فقط یک یادداشت بدون هیچ گونه ارتباطی با عملکرد اضافه کنید.');
INSERT INTO `lang_definitions` VALUES (200391, 11180, 31, 'تعداد قرارهای آینده برای نمایش در بیانیه.');
INSERT INTO `lang_definitions` VALUES (200392, 11181, 31, 'تعداد پرونده های مرحله بندی شده نادرست است.فقط فایلی را که می خواهید در آن نصب یا ارتقا دهید قرار دهید.');
INSERT INTO `lang_definitions` VALUES (200393, 11182, 31, 'تعداد پرونده های مرحله بندی شده نادرست است.فقط پرونده هایی را که می خواهید در آنها نصب یا ارتقا دهید قرار دهید.');
INSERT INTO `lang_definitions` VALUES (200394, 11183, 31, 'Office: سلول تلفن به شما امکان می دهد که مکالمه تلفنی برقرار شده است');
INSERT INTO `lang_definitions` VALUES (200395, 11184, 31, 'گزینه Span Entire Row هنگام استفاده از Static Text در اجازه دادن به متن برای بسته بندی و باز شدن کل ردیف بدون در نظر گرفتن تنظیمات ستون مفید است.استفاده دیگر می تواند ایجاد یک سطر خالی به عنوان spacer یا افزودن گزینه اضافی Add Bottom Border برای ایجاد خط شکسته باشد. فقط Bottom Border Row در اینجا مفید است.');
INSERT INTO `lang_definitions` VALUES (200396, 11185, 31, 'گزینه های Outline و Border یا یک ردیف را در حاشیه نازک قرار می دهد یا حاشیه ای را به پایین یک مورد اضافه می کند.');
INSERT INTO `lang_definitions` VALUES (200397, 11186, 31, 'ترتیب نمایش دسته ، روش یا نتیجه');
INSERT INTO `lang_definitions` VALUES (200398, 11187, 31, '4 نوع معامله دیگر انواع معاملات ساده است - درخواست بیمار ، درخواست پزشک ، حقوقی و صورتحساب');
INSERT INTO `lang_definitions` VALUES (200399, 11188, 31, 'بخشهای دیگر به صورت کاملاً ساختارمند حاوی اطلاعات اضافی هستند');
INSERT INTO `lang_definitions` VALUES (200400, 11189, 31, 'این صفحه به Demographics هدایت می شود.می توانید فیلد کشور را ویرایش کرده و دوباره روی NewCrop کلیک کنید.');
INSERT INTO `lang_definitions` VALUES (200401, 11190, 31, 'صفحه مورد نظر شما یافت نشد.لطفاً بررسی کنید که URL را به درستی تایپ کرده اید.');
INSERT INTO `lang_definitions` VALUES (200402, 11191, 31, 'قسمت هایی از برنامه که می توان دسترسی به آنها را کنترل کرد ، Access Control Objects (ACOs) نامیده می شوند.');
INSERT INTO `lang_definitions` VALUES (200403, 11192, 31, 'رمز ورود باید حداقل هشت حرف باشد و باید باشد');
INSERT INTO `lang_definitions` VALUES (200404, 11193, 31, 'رمز عبوری که وارد کرده اید نامعتبر است');
INSERT INTO `lang_definitions` VALUES (200405, 11194, 31, 'تاریخچه گذشته چشم (POH) و سابقه پزشکی گذشته (PMH) منفی است.');
INSERT INTO `lang_definitions` VALUES (200406, 11195, 31, 'بیمار قبلاً در این گروه ثبت نام کرده است');
INSERT INTO `lang_definitions` VALUES (200407, 11196, 31, 'درخواست پرونده بیمار ثبت شده است.');
INSERT INTO `lang_definitions` VALUES (200408, 11197, 31, 'یادآوری های بیمار ارسال شده است');
INSERT INTO `lang_definitions` VALUES (200409, 11198, 31, 'یادآوری های بیمار به روز شده است');
INSERT INTO `lang_definitions` VALUES (200410, 11199, 31, 'بیمار هنگام ارسال این فرم وارد سیستم نشده است');
INSERT INTO `lang_definitions` VALUES (200411, 11200, 31, 'بیمار در اولین ورود باید مدارک خود را تغییر دهد');
INSERT INTO `lang_definitions` VALUES (200412, 11201, 31, 'حقوق بیماران');
INSERT INTO `lang_definitions` VALUES (200413, 11202, 31, 'پرداخت ، تنظیم و تراز خالی خواهد بود زیرا این خطوط فقط هزینه های ایجاد شده را منعکس می کنند');
INSERT INTO `lang_definitions` VALUES (200414, 11203, 31, 'پرداخت های ارسال شده نمی تواند زیر این تاریخ باشد. این اطمینان می دهد که پس از گرفتن گزارش نهایی ، هیچ کس برای تاریخ های قبلی ارسال نمی کند.');
INSERT INTO `lang_definitions` VALUES (200415, 11204, 31, 'عنوان فرم پاپ آپ اکنون جزئیات Enter برای مورد شخصی مورد دلخواه سفارشی را می خواند');
INSERT INTO `lang_definitions` VALUES (200416, 11205, 31, 'پورتال داده هایی برای این بیمار و فرم دارد.اکنون بارگیری شود؟');
INSERT INTO `lang_definitions` VALUES (200417, 11206, 31, 'پیام قبلی را می توان با کلیک روی دکمه View Log مشاهده کرد');
INSERT INTO `lang_definitions` VALUES (200418, 11207, 31, 'صفحه Procedure Order انواع روشهای زیر را لیست می کند');
INSERT INTO `lang_definitions` VALUES (200419, 11208, 31, 'درخواست رویه باید به صورت سلسله مراتبی ساختار یافته و یک کد شناسایی منحصر به فرد به آن اختصاص داده شود که سپس برای ردیابی و جدول بندی نتیجه استفاده شود.');
INSERT INTO `lang_definitions` VALUES (200420, 11209, 31, 'از ماژول Procedures برای قرار دادن و بررسی سفارشات استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200421, 11210, 31, 'روند ارسال پیام کاملاً مشابه ایجاد پیام جدید است');
INSERT INTO `lang_definitions` VALUES (200422, 11211, 31, 'سلول Progress کلیه اقدامات را همراه با هرگونه یادداشت مرتبط در صورت وجود لیست می کند');
INSERT INTO `lang_definitions` VALUES (200423, 11212, 31, 'به دفتر ارائه دهندگان اطلاع داده شده است.متشکرم.');
INSERT INTO `lang_definitions` VALUES (200424, 11213, 31, 'کلید دسترسی عمومی برای رمزگذاری ایمن اعتبار کارت اعتباری یا بدهی.انطباق با PCI');
INSERT INTO `lang_definitions` VALUES (200425, 11214, 31, 'کد QR همچنین شامل نام کاربری است و باید توسط کاربر با استفاده از یک برنامه احراز هویت توسط دستگاه تلفن همراه خود ضبط شود');
INSERT INTO `lang_definitions` VALUES (200426, 11215, 31, 'انتشار خوراک داده خام را می توان از اینجا بدست آورد');
INSERT INTO `lang_definitions` VALUES (200427, 11216, 31, 'سلول Recall تاریخ فراخوانی و دلیل فراخوان را دارد');
INSERT INTO `lang_definitions` VALUES (200428, 11217, 31, 'تب Recalls دارای دو دکمه New Recall و Recall Board است');
INSERT INTO `lang_definitions` VALUES (200429, 11218, 31, 'ردیف توصیه ها اختیاری است');
INSERT INTO `lang_definitions` VALUES (200430, 11219, 31, 'اطلاعات باقیمانده در زیر فقط در صورت ارسال دستی ارسال نامه یا انجام اصلاحات دستی اعمال می شوند.');
INSERT INTO `lang_definitions` VALUES (200431, 11220, 31, 'یادآوری برای روز جاری یک نماد تعجب نارنجی دارد');
INSERT INTO `lang_definitions` VALUES (200432, 11221, 31, 'یادآوری هایی که از تاریخ سررسید گذشته اند دارای یک نماد مثلث تعجب قرمز هستند');
INSERT INTO `lang_definitions` VALUES (200433, 11222, 31, 'سند درخواستی در محل مورد انتظار در سیستم فایل وجود ندارد یا مجوزهای کافی برای دسترسی به آن وجود ندارد');
INSERT INTO `lang_definitions` VALUES (200434, 11223, 31, 'سند درخواستی در محل مورد انتظار در سیستم فایل وجود ندارد یا مجوزهای کافی برای دسترسی به آن وجود ندارد.');
INSERT INTO `lang_definitions` VALUES (200435, 11224, 31, 'در صورت تمایل بقیه ممکن است خالی بمانند');
INSERT INTO `lang_definitions` VALUES (200436, 11225, 31, 'بقیه کادرهای مربوط به سرویس NewCrop eRx را می توان در مقادیر پیش فرض قرار داد');
INSERT INTO `lang_definitions` VALUES (200437, 11226, 31, 'خط نتیجه با یک اسید اوریک سرم نام آغاز می شود که قبل از آن یک میله عمودی نشان می دهد که هیچ جانشین یا فرزندی وجود ندارد');
INSERT INTO `lang_definitions` VALUES (200438, 11227, 31, 'نتایج بارگیری نشد');
INSERT INTO `lang_definitions` VALUES (200439, 11228, 31, 'نتایج ، نتیجه گسسته ، ثمره این شاخه خواهد بود و ما برای هر یک از آزمایشات م componentلفه ، سدیم ، پتاسیم ، کلرید و دی اکسید کربن یک نتیجه گسسته ایجاد خواهیم کرد.');
INSERT INTO `lang_definitions` VALUES (200440, 11229, 31, 'ردیف های حاوی کدهای CPT4 دارای چندین جعبه هستند که برای اطمینان از صورتحساب مناسب ادعاها باید پر شوند');
INSERT INTO `lang_definitions` VALUES (200441, 11230, 31, 'مشکل پزشکی ذخیره شده اکنون به عنوان یک خط واحد در صفحه اصلی مشکلات تحت مشکلات پزشکی لیست خواهد شد');
INSERT INTO `lang_definitions` VALUES (200442, 11232, 31, 'زمان تازه سازی صفحه در ثانیه برای صفحه تابلو روان بیمار.');
INSERT INTO `lang_definitions` VALUES (200443, 11233, 31, 'قسمت جستجو نمی تواند خالی باشد.لطفا یک عبارت برای جستجوی وارد کنید');
INSERT INTO `lang_definitions` VALUES (200444, 11234, 31, 'نتایج جستجو در بخش \"نتایج جستجو\" نمایش داده می شود.');
INSERT INTO `lang_definitions` VALUES (200445, 11235, 31, 'نمودار دوم (\"منبع\") بخش های جمعیتی ، سابقه و بیمه خود را کنار می گذارد.سایر داده های آن در نمودار هدف ادغام می شوند.');
INSERT INTO `lang_definitions` VALUES (200446, 11236, 31, 'ستون دوم شامل گزینه هایی است که با کلیک روی دکمه نمایش داده می شود');
INSERT INTO `lang_definitions` VALUES (200447, 11237, 31, 'ستون دوم Category است و باید عبارت Top Group را نشان دهد تا موقعیت آن را به عنوان مورد اصلی در این درخت سلسله مراتبی خاص که ما در حال ساخت آن هستیم ، نشان دهد.');
INSERT INTO `lang_definitions` VALUES (200448, 11238, 31, 'بخش دوم به شما امکان می دهد که برای چه کسی پیام ارسال کنید');
INSERT INTO `lang_definitions` VALUES (200449, 11239, 31, 'تب دوم ، تا حدودی مبهم به عنوان Counter-Reference معرفی شده است ، محلی برای سند پاسخ دریافت شده به ارجاع است');
INSERT INTO `lang_definitions` VALUES (200450, 11240, 31, 'بخشی با عنوان \"جستجوی فاکتور\" محلی است که شما پارامترهای جستجوی خود را قرار می دهید.می توانید براساس نام بیمار ، شماره نمودار ، شماره مواجهه یا تاریخ خدمات یا هر ترکیبی از این موارد جستجو کنید.همچنین می توانید انتخاب کنید که آیا می خواهید همه فاکتورها ، فاکتورهای باز یا فقط فاکتورهایی را که به سررسید هستند (توسط بیمار) ببینید.برای انجام جستجو روی دکمه \"جستجو\" کلیک کنید.');
INSERT INTO `lang_definitions` VALUES (200451, 11241, 31, 'کد انتخاب شده به کادر متن کدگذاری و توضیحات مربوط به کد به جعبه متن عنوان اضافه می شود');
INSERT INTO `lang_definitions` VALUES (200452, 11242, 31, 'سپس کدهای انتخاب شده در قسمت \"کدهای صفحه انتخاب شده هزینه و هزینه های مربوط به برخورد فعلی\" ظاهر می شوند');
INSERT INTO `lang_definitions` VALUES (200453, 11243, 31, 'انتخاب های این بخش برای شارژ این برخورد استفاده خواهد شد');
INSERT INTO `lang_definitions` VALUES (200454, 11244, 31, 'توالی به ترتیب نمایش این مورد برتر در صفحه نشان داده می شود ، 1 برای نشان دادن اولین گروه سطح بالا');
INSERT INTO `lang_definitions` VALUES (200455, 11245, 31, 'آدرس سرور از فرم خواهد بود');
INSERT INTO `lang_definitions` VALUES (200456, 11246, 31, 'تنظیمات آزمایشات با جزئیات شرح داده خواهد شد ، برای تنظیم مراحل داخلی و سایر روشها اصلاح جزئی در این مراحل لازم است');
INSERT INTO `lang_definitions` VALUES (200457, 11247, 31, 'تقاضای متقابل تا حدودی مبهم نامیده می شود فضایی است که می توان پاسخ ارجاع را ثبت کرد');
INSERT INTO `lang_definitions` VALUES (200458, 11248, 31, 'ستون های Source و Date از صفحه اول کپی می شوند ، بنابراین معمولاً نیازی به لمس آنها نیستید.شما می توانید مبلغ پرداختی را در ستون پرداخت ، مبلغی را در ستون تنظیم یا هر دو قرار دهید.همچنین می توانید روی \"W\" در سمت راست کلیک کنید تا یک مقدار تنظیم به طور خودکار محاسبه شود که باقیمانده شارژ آن مورد خط را بنویسد.');
INSERT INTO `lang_definitions` VALUES (200459, 11249, 31, 'ستون های Source و Date از صفحه اول کپی می شوند ، بنابراین معمولاً نیازی به لمس آنها نیستید.شما می توانید مبلغ پرداختی را در ستون پرداخت ، مبلغی را در ستون تنظیم یا هر دو قرار دهید.همچنین می توانید روی \"W\" در سمت راست کلیک کنید تا یک مقدار تنظیم به طور خودکار محاسبه شود که باقیمانده هزینه آن مورد خط را بنویسد.');
INSERT INTO `lang_definitions` VALUES (200460, 11250, 31, 'نوع نمونه خون خواهد بود ، این لیست کشویی همچنین می تواند در صورت لزوم ویرایش شود');
INSERT INTO `lang_definitions` VALUES (200461, 11251, 31, 'تاریخ انتشار پرونده های مرحله ای همه از یک نسخه نیستند.');
INSERT INTO `lang_definitions` VALUES (200462, 11252, 31, 'بازبینی پرونده های مرحله ای همه از یک نسخه نیستند.');
INSERT INTO `lang_definitions` VALUES (200463, 11253, 31, 'بسته مرحله ای SNOMED Extension US تا قبل از نصب بسته International SNOMED قابل نصب نیست.');
INSERT INTO `lang_definitions` VALUES (200464, 11254, 31, 'استاندارد استاندارد در صورت استفاده از آزمایشگاه محلی یعنی عملی اختیاری است اما هنگام استفاده از آزمایشگاه خارجی توصیه می شود');
INSERT INTO `lang_definitions` VALUES (200465, 11255, 31, 'کد استاندارد در صورت ارسال به آزمایشگاه خارجی ، کد LOINC خواهد بود یا می تواند هر شماره منحصر به فردی باشد.ما کد LOINC را برای Fasting Glucose 1558-6 وارد خواهیم کرد');
INSERT INTO `lang_definitions` VALUES (200466, 11256, 31, 'وضعیت سه مشکل مزمن / غیرفعال');
INSERT INTO `lang_definitions` VALUES (200467, 11257, 31, 'خطوط بعدی جزئیات پرداخت های دریافتی ، تنظیمات انجام شده و مانده بدهی را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (200468, 11258, 31, 'پسوند حساب.');
INSERT INTO `lang_definitions` VALUES (200469, 11259, 31, 'سیستم بارگذاری پرونده هایی با اندازه 0 را مجاز نمی داند.');
INSERT INTO `lang_definitions` VALUES (200470, 11260, 31, 'سیستم بارگذاری پرونده هایی با نوع محتوای MIME را مجاز نمی داند');
INSERT INTO `lang_definitions` VALUES (200471, 11261, 31, 'این سیستم همچنین برای تجزیه و تحلیل پیام های HL7 ورودی و قرار دادن نتایج در نمودار مناسب بیمار طراحی شده است ، در صورت عدم امکان به شما این امکان را می دهد که آن را به صورت دستی به نمودار بیمار پیوند دهید.');
INSERT INTO `lang_definitions` VALUES (200472, 11262, 31, 'این سیستم به گونه ای طراحی شده است که هم سفارشات را به صورت الکترونیکی انجام می دهد و هم نتایج را به صورت الکترونیکی دریافت می کند');
INSERT INTO `lang_definitions` VALUES (200473, 11263, 31, 'ستون سوم حاوی کد CPT خواهد بود');
INSERT INTO `lang_definitions` VALUES (200474, 11264, 31, 'مقدار ستون Tier 1 خواهد بود که نشان می دهد یک مورد سطح بالایی است');
INSERT INTO `lang_definitions` VALUES (200475, 11265, 31, 'مقدار ستون Tier 3 خواهد بود ، نشانگر این است که این یک جانشین یا فرزند خط اول بالای آن است که دارای مقدار 2 است');
INSERT INTO `lang_definitions` VALUES (200476, 11266, 31, 'ستون Tier 2 خواهد بود ، نشان می دهد این یک جانشین یا فرزند خط اول بالای آن است که دارای مقدار 1 است');
INSERT INTO `lang_definitions` VALUES (200477, 11267, 31, 'ستون ردیف 1 است که نشان می دهد گروه برتر است');
INSERT INTO `lang_definitions` VALUES (200478, 11268, 31, 'دانه دانه بودن زمان تقویم و کمترین فاصله در دقیقه برای یک قرار ملاقات.');
INSERT INTO `lang_definitions` VALUES (200479, 11269, 31, 'عنوان نام گروه جدید (ARO) است که می خواهید ایجاد کنید.');
