INSERT INTO `lang_definitions` VALUES (200499, 11291, 31, 'دستگاه های USB با استفاده از پروتکل دستگاه رابط انسان (HID) با رایانه میزبان ارتباط برقرار می کنند و اساساً از صفحه کلید تقلید می کنند');
INSERT INTO `lang_definitions` VALUES (200500, 11292, 31, 'کلید USB باید به رایانه متصل شود و سپس در OpenEMR ثبت شود');
INSERT INTO `lang_definitions` VALUES (200501, 11293, 31, 'کلید USB این مورد را غیرفعال شده توسط برنامه پس از تأیید صحت تأیید می کند و با استفاده از فرآیند مشابه فرآیند ثبت نام ، یک کلید خصوصی تولید می کند');
INSERT INTO `lang_definitions` VALUES (200502, 11294, 31, 'امتیازات واقعی کاربر با دسترسی به قسمت های برنامه یعنی (ACO) که هر گروه (ARO) دارد تعیین می شود.');
