INSERT INTO `lang_definitions` VALUES (200505, 11297, 31, 'مقادیر موجود در کادر کشویی را می توان با دنبال کردن مراحل ذکر شده در پرونده راهنما روش ها> ارائه دهندگان ، ویرایش کرد');
INSERT INTO `lang_definitions` VALUES (200506, 11298, 31, 'مقادیر ذکر شده در اینجا در کادرهای کشویی نشان داده می شوند که برای پردازش سفارشات استفاده می شوند');
INSERT INTO `lang_definitions` VALUES (200507, 11299, 31, 'کد اختصاصی فروشنده که این روش یا نتیجه را مشخص می کند');
INSERT INTO `lang_definitions` VALUES (200508, 11300, 31, 'کد اختصاصی فروشنده که این روش یا نتیجه را مشخص می کند.اگر هیچ فروشنده ای عدد منحصر به فرد دلخواه را وارد نکنید ، ترجیحاً یک عدد 5 رقمی صفر پر شود.00211');
INSERT INTO `lang_definitions` VALUES (200509, 11301, 31, 'اولین قدم نصب کدهای ICD است.به قسمت Administration> Other> External Data Loads بروید.مجموعه کد را که می خواهید نصب کنید انتخاب کنید و روی نصب کلیک کنید');
INSERT INTO `lang_definitions` VALUES (200510, 11302, 31, 'آخرین خط این گزارش ، مجموع کل شارژها ، پرداخت ها ، تنظیمات و مانده را ارائه می دهد.');
