INSERT INTO `lang_definitions` VALUES (200517, 11309, 31, 'طرح زمینه زبانه ها (برای دیدن این تنظیم جدید باید از سیستم خارج شوید و سپس وارد شوید).توجه داشته باشید این تنها درصورتی استفاده می شود که از موضوع کلی نور یا مانیل در زیر استفاده کنید.');
