INSERT INTO `lang_definitions` VALUES (200530, 11322, 31, 'در فرم Core 3 فرم وجود دارد - اطلاعات دموگرافیک ، اطلاعات خاص کاربر و سابقه تسهیلات و 5 فرم موجود در معاملات که می توانند ویرایش شوند.');
