INSERT INTO `lang_definitions` VALUES (200546, 11338, 31, 'نسخه های مختلفی از HL7 ، نسخه 2.x و نسخه 3 وجود دارد');
INSERT INTO `lang_definitions` VALUES (200547, 11339, 31, 'روش های مختلفی برای سفارشی کردن برگ هزینه وجود دارد.این به راحتی شما در افزودن اطلاعات به خود پایگاه داده بستگی دارد');
INSERT INTO `lang_definitions` VALUES (200548, 11340, 31, 'سه عمل ممکن است وجود داشته باشد - ایجاد یک یادآوری تاریخ دار جدید ، باز ارسال و تنظیم به عنوان کامل');
INSERT INTO `lang_definitions` VALUES (200549, 11341, 31, 'سه عمل وجود دارد که می تواند در اینجا انجام شود - ویرایش یک گروه موجود (ARO) ، افزودن یک گروه جدید (ARO) یا حذف یک گروه موجود (ARO).');
INSERT INTO `lang_definitions` VALUES (200550, 11343, 31, 'سه نوع گزارش اصلی وجود دارد که می تواند ایجاد شود ، دو مورد مربوط به تداوم مراقبت مداوم است - سابقه تداوم مراقبت (CCR) و سند مراقبت مداوم (CCD) و سوم - گزارش بیمار که سندی را شامل می شود که شامل بخشهای مختلفی ازپرونده پزشکی بیمار شامل مشخصات جمعیتی ، مسائل پزشکی ، رویه ها و برخوردها.همچنین این توانایی را دارد که تمام یا هر یک از اسناد اسکن شده را در نمودار بیمار قرار دهد');
INSERT INTO `lang_definitions` VALUES (200551, 11344, 31, 'هنگام ایجاد سند تداوم مراقبت (CCD) سه گزینه در دسترس است');
INSERT INTO `lang_definitions` VALUES (200552, 11345, 31, 'هنگام ایجاد سابقه تداوم مراقبت (CCR) سه گزینه در دسترس است');
INSERT INTO `lang_definitions` VALUES (200553, 11346, 31, 'سه مجموعه عملکرد وجود دارد که می تواند در این صفحه انجام شود ، علاوه بر این فرم می تواند سفارشی شود');
INSERT INTO `lang_definitions` VALUES (200554, 11347, 31, 'دو دکمه وجود دارد که شما را قادر می سازد همه کادرهای تأیید را علامت گذاری یا پاک کنید');
