INSERT INTO `lang_definitions` VALUES (200556, 11349, 31, 'دو بخش وجود دارد که قابل مشاهده است');
INSERT INTO `lang_definitions` VALUES (200557, 11350, 31, 'دو منبع قابل جستجو هستند - MedlinePlus Connect یا Local Content');
INSERT INTO `lang_definitions` VALUES (200558, 11351, 31, 'به دو روش وجود دارد که می توان این کار را انجام داد ، یا با استفاده از روش دستی ، با جستجو و وارد کردن داده ها برای فاکتورهای منفرد یا با بارگذاری کل پرونده مشاوره حواله الکترونیکی ERA.');
INSERT INTO `lang_definitions` VALUES (200559, 11352, 31, 'انتخاب های مختلفی برای پر کردن وجود دارد ، حداقل داده های مورد نیاز برای ذخیره موفقیت آمیز ارجاع ، تاریخ مراجعه ، مراجعه به و دلیل است');
