INSERT INTO `lang_definitions` VALUES (200579, 11376, 31, 'بنابراین هر کاربر باید به طور جداگانه این ویژگی را فعال کند');
INSERT INTO `lang_definitions` VALUES (200580, 11377, 31, 'این ACO ها در ده دسته گسترده دسته بندی می شوند که بخشی از نصب پیش فرض هستند.آنها عبارتند از: مدیریت ، حسابداری ، اطلاعات بیمار ، اطلاعات برخورد ، جوخه ها ، حساسیت ها ، لیست ها ، محل نگهدارنده ، یادداشت های ملت و پورتال بیمار.هر یک از این دسته ها دارای یک یا چند زیر مجموعه هستند که امکان دسترسی به قسمت های خاصی از برنامه را فراهم می کنند.');
INSERT INTO `lang_definitions` VALUES (200581, 11378, 31, 'اینها رایگان هستند و می توانند از فروشگاه برنامه مربوطه برای دستگاه های iOS و Android بارگیری شوند');
INSERT INTO `lang_definitions` VALUES (200582, 11379, 31, 'این پیوندهای سال 2012 است');
