INSERT INTO `lang_definitions` VALUES (200584, 11381, 31, 'اینها برای پر کردن قسمتهای 5 و 6 در هدر پیام HL7 MSH استفاده می شوند');
INSERT INTO `lang_definitions` VALUES (200585, 11382, 31, 'این اعتبارات توسط بیمار برای ورود به پورتال بیمار برای اولین بار استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200586, 11383, 31, 'این گروه های سفارشی خاص برنامه هستند و مختص کاربر نیستند');
INSERT INTO `lang_definitions` VALUES (200587, 11384, 31, 'از این ورودی ها برای تعریف ارائه دهندگان در ماژول Procedures استفاده خواهد شد');
INSERT INTO `lang_definitions` VALUES (200588, 11385, 31, 'سپس با اختصاص دسته های مختلف (ACO) به این گروه ها (ARO) می توان مجموعه ای از امتیازات را داد.');
INSERT INTO `lang_definitions` VALUES (200589, 11386, 31, 'اگر کاربر از امتیاز کافی برخوردار باشد ، می توان این موارد را ویرایش کرد');
INSERT INTO `lang_definitions` VALUES (200590, 11387, 31, 'این لیست ها برای تعیین اینکه چه کسی می تواند در openEMR به چه چیزی دسترسی پیدا کند استفاده می شود.آنها به صورت بالا به پایین کار می کنند ، یعنی در ابتدا دسترسی به آن قسمت از برنامه که توسط ACL کنترل می شود از همه محروم است.');
INSERT INTO `lang_definitions` VALUES (200591, 11388, 31, 'برای احراز هویت موفقیت آمیز کاربر ، این اعداد باید مطابقت داشته باشند');
INSERT INTO `lang_definitions` VALUES (200592, 11389, 31, 'این یادداشت های بیمار بدون بیمار تعیین شده ارسال می شود');
