INSERT INTO `lang_definitions` VALUES (200666, 11470, 31, 'از این قسمت برای تصمیم گیری در مورد پردازش پیام به عنوان تعریف شده در HL7 Application (سطح 7) قوانین پردازش استفاده می شود');
