INSERT INTO `lang_definitions` VALUES (200716, 11521, 31, 'این فضای نام از قبل در پایگاه داده وجود دارد');
INSERT INTO `lang_definitions` VALUES (200717, 11522, 31, 'این دسته جدید زیر گروه خواهد بود');
INSERT INTO `lang_definitions` VALUES (200718, 11524, 31, 'این سفارش قبلاً در تاریخ ارسال شده است');
INSERT INTO `lang_definitions` VALUES (200719, 11525, 31, 'این صفحه به شما امکان می دهد هر یک از داده های پشتیبانی شده خارجی را که می توانید نصب و ارتقا دهید مرور کنید.برای بازبینی وضعیت پایگاه داده مورد نظر خاص ، می توانید هر بخش زیر را با کلیک کردن روی عنوان بخش گسترش دهید.');
INSERT INTO `lang_definitions` VALUES (200720, 11526, 31, 'این صفحه به دلایل امنیتی غیرفعال شده است.');
INSERT INTO `lang_definitions` VALUES (200721, 11527, 31, 'این صفحه به شما امکان می دهد تا سفارشات و نتایج را پیکربندی کنید');
INSERT INTO `lang_definitions` VALUES (200722, 11528, 31, 'این صفحه شامل صفحه ورود به سیستم خواهد بود ، بنابراین ما مجبور نیستیم هر بار روی ورود مجدد کلیک کنیم.');
INSERT INTO `lang_definitions` VALUES (200723, 11529, 31, 'این بیمار از قبل قرار ملاقات برای وی تعیین شده است');
INSERT INTO `lang_definitions` VALUES (200724, 11530, 31, 'این بیمار پیام کوتاه را مجاز نمی داند!');
INSERT INTO `lang_definitions` VALUES (200725, 11532, 31, 'این بیمار هیچ فعالیتی ندارد.');
INSERT INTO `lang_definitions` VALUES (200726, 11533, 31, 'این شناسه بیمار قبلاً در حال استفاده است!');
INSERT INTO `lang_definitions` VALUES (200727, 11534, 31, 'این احراز هویت پورتال است.');
INSERT INTO `lang_definitions` VALUES (200728, 11535, 31, 'این محصول در هر انبار فقط یک قسمت را مجاز می داند.');
INSERT INTO `lang_definitions` VALUES (200729, 11536, 31, 'این پروتکل اجرا نمی شود');
INSERT INTO `lang_definitions` VALUES (200730, 11539, 31, 'این گزارش در حال حاضر فقط برای کدهای ICD9 کار می کند.');
INSERT INTO `lang_definitions` VALUES (200731, 11542, 31, 'این بخش به شما امکان ایجاد و حذف گروه ها و اصلاح یا اعطای امتیازات دسترسی به گروه های موجود را می دهد.بخش نمایش برای نمایش را علامت بزنید');
INSERT INTO `lang_definitions` VALUES (200732, 11543, 31, 'این بخش را می توان سفارشی کرد تا کدها را در دسته های مختلف گروه بندی کند');
INSERT INTO `lang_definitions` VALUES (200733, 11544, 31, 'این بخش به شما اجازه ایجاد ACO های جدید را نمی دهد.');
INSERT INTO `lang_definitions` VALUES (200734, 11545, 31, 'این بخش جایی است که کدها برای دریافت هزینه بازدید استفاده می کنند');
INSERT INTO `lang_definitions` VALUES (200735, 11546, 31, 'این بخش به شما امکان می دهد کد مورد نیاز را در صورت عدم وجود گزینه های پیش فرض یا سفارشی در بخش \"انتخاب کد\" ، جستجو کنید');
INSERT INTO `lang_definitions` VALUES (200736, 11547, 31, 'این بخش به کاربر وارد شده اجازه می دهد تا روش های موجود را مشاهده یا آنها را حذف کند');
INSERT INTO `lang_definitions` VALUES (200737, 11548, 31, 'با این کار نمای پیش فرض تقویم تنظیم می شود ، پیش فرض روز است.');
INSERT INTO `lang_definitions` VALUES (200738, 11549, 31, 'این چاپ ارائه دهنده گروه بندی شده گزارش پایان روز سفارشی را مشخص می کند یا فقط چاپ تعداد کل مجاز است');
INSERT INTO `lang_definitions` VALUES (200739, 11550, 31, 'این مشخص می کند که آیا تاریخ در جعبه 31 درج شود.');
INSERT INTO `lang_definitions` VALUES (200740, 11551, 31, 'این مشخص می کند که ماژول صورتحساب کدام نسخه را باید در فرم ایجاد کند');
INSERT INTO `lang_definitions` VALUES (200741, 11552, 31, 'در این مرحله پرونده ای ایجاد می شود که باید برای استفاده در آینده ذخیره کنید.');
INSERT INTO `lang_definitions` VALUES (200742, 11553, 31, 'در این مرحله پرونده ای ایجاد می شود که باید برای استفاده در آینده ذخیره کنید.پرونده مجدداً تولید نمی شود.آیا شما می خواهید ادامه دهید؟');
INSERT INTO `lang_definitions` VALUES (200743, 11556, 31, 'این کاربر عضو هیچ گروهی نیست');
INSERT INTO `lang_definitions` VALUES (200744, 11557, 31, 'این کاربر اعلان پیام های جدید ورودی جدید را دریافت می کند');
INSERT INTO `lang_definitions` VALUES (200745, 11558, 31, 'این ابزار آزمایشی است.قبل از استفاده از پایگاه داده و اسناد خود ، از آن پشتیبان تهیه کنید!');
INSERT INTO `lang_definitions` VALUES (200746, 11559, 31, 'این ابزار آزمایشی است.قبل از استفاده از پایگاه داده و اسناد خود ، از آن پشتیبان تهیه کنید!');
INSERT INTO `lang_definitions` VALUES (200747, 11560, 31, 'این ملاقات آغاز استفاده از پیشگیری بارداری جدید میباشد');
INSERT INTO `lang_definitions` VALUES (200748, 11561, 31, 'این ملاقات نیازمند فرم GCAC، و مراجعه یا خدمات پزشکی دارد.');
INSERT INTO `lang_definitions` VALUES (200749, 11562, 31, 'این فرم قدیمی متغیر فقط Vital ها بود که اکنون منسوخ شده است.');
INSERT INTO `lang_definitions` VALUES (200750, 11563, 31, 'این هفته تا امروز');
INSERT INTO `lang_definitions` VALUES (200751, 11565, 31, 'با این کار تغییرات ذخیره نشده شما کنار گذاشته می شود.مطمئنی؟');
INSERT INTO `lang_definitions` VALUES (200752, 11566, 31, 'با این کار گزارش CCR (تداوم مراقبت از مراقبت) و CCD (تداوم مراقبت از سند) گزارش فعال می شود.');
INSERT INTO `lang_definitions` VALUES (200753, 11568, 31, 'این امکان چاپ پیام سفارشی بر روی دستورات را فراهم می کند.');
INSERT INTO `lang_definitions` VALUES (200754, 11569, 31, 'این امکان چاپ یادداشت صورتحساب بیمار بر روی عبارات را فراهم می کند.');
INSERT INTO `lang_definitions` VALUES (200755, 11570, 31, 'این امکان انتخاب زبان اشکال زدایی ( \"ساختگی \") را فراهم می کند.');
INSERT INTO `lang_definitions` VALUES (200756, 11571, 31, 'به شما امکان نمایش حالت کمکی کمک در صفحه های فعال شده با کمک را می دهد');
INSERT INTO `lang_definitions` VALUES (200757, 11572, 31, 'به شما امکان می دهد از گزارش سفارشی پایان روز استفاده کنید و مشخص کنید که از کدام گزارش استفاده کنید.');
INSERT INTO `lang_definitions` VALUES (200758, 11573, 31, 'این امکان را فراهم می کند که از Dunning Messages سفارشی در عبارات استفاده کنید.');
INSERT INTO `lang_definitions` VALUES (200759, 11574, 31, 'این یک \"خشک\" است و بدون به روزرسانی داده های فیزیکی است.');
INSERT INTO `lang_definitions` VALUES (200760, 11575, 31, 'با این کار داده ها از تمام زمینه های آزمون مقدماتی قسمت قبلی پاک می شوند');
INSERT INTO `lang_definitions` VALUES (200761, 11576, 31, 'با این کار داده ها از تمام قسمت های External Exam پاک می شوند');
INSERT INTO `lang_definitions` VALUES (200762, 11577, 31, 'با این کار داده ها از تمام زمینه های آزمون شبکیه چشم پاک می شوند');
INSERT INTO `lang_definitions` VALUES (200763, 11578, 31, 'با این کار کد انتخاب شده در کادر Diagnosis Codes در فرم پاپ آپ Enter جزئیات مورد شخصی مورد دلخواه کپی می شود.');
INSERT INTO `lang_definitions` VALUES (200764, 11579, 31, 'با این کار یک نسخه پشتیبان با فرمت tar ایجاد می شود و سپس آن را به مرورگر وب خود ارسال می کنید تا بتوانید آن را ذخیره کنید');
INSERT INTO `lang_definitions` VALUES (200765, 11580, 31, 'با این کار خصوصیات رمزگذاری و رمزگشایی غیرفعال می شود و در UI پنهان می شود.');
INSERT INTO `lang_definitions` VALUES (200766, 11581, 31, 'با این کار دکمه ویرایش در همه فرم هایی که برخورد والدین آنها به صورت الکترونیکی امضا شده است غیرفعال می شود');
INSERT INTO `lang_definitions` VALUES (200767, 11582, 31, 'با این کار دکمه ویرایش در هر فرم که با ایمیل امضا شده غیرفعال می شود');
INSERT INTO `lang_definitions` VALUES (200768, 11583, 31, 'با این کار شماره فاکتور در گزارش فروش یا نام بیمار و شناسه یا نام بیمار و شماره فاکتور نمایش داده می شود.');
INSERT INTO `lang_definitions` VALUES (200769, 11584, 31, 'این امکان رمزگذاری موارد ذخیره شده در CouchDB را فراهم می کند.');
INSERT INTO `lang_definitions` VALUES (200770, 11585, 31, 'این امکان رمزگذاری موارد ذخیره شده در درایو را فراهم می کند.');
INSERT INTO `lang_definitions` VALUES (200771, 11586, 31, 'این امکان را فراهم می کند که یک کل برخورد را به جای فرم های جداگانه امضا کنید');
INSERT INTO `lang_definitions` VALUES (200772, 11587, 31, 'امضای فرمهای جداگانه را فعال می کند');
INSERT INTO `lang_definitions` VALUES (200773, 11588, 31, 'این امکان امکان حذف اظهارات بیمار را از چاپ فراهم می کند.');
INSERT INTO `lang_definitions` VALUES (200774, 11589, 31, 'با این کار کادر عنوان Title و همچنین کد ICD10 در کادر متن Coding پر می شود');
INSERT INTO `lang_definitions` VALUES (200775, 11590, 31, 'با این کار ویجت صورتحساب در صفحه خلاصه بیمار مجبور است همیشه باز باشد.');
INSERT INTO `lang_definitions` VALUES (200776, 11591, 31, 'این گزینه را به کاربر می دهد تا قفل کند (قفل کردن و امضای جداگانه)');
