INSERT INTO `lang_definitions` VALUES (200780, 11597, 31, 'با این کار دو نمودار بیمار در یک ادغام می شود.زمانی مفید است که بیمار به اشتباه کپی شده باشد.اگر این اتفاق اغلب می افتد ، رویه های دفتر خود را اصلاح کنید - این کار را به طور معمول انجام ندهید!');
INSERT INTO `lang_definitions` VALUES (200781, 11598, 31, 'این امر از رفتن شما به سایت نسخه های الکترونیکی جلوگیری نمی کند.');
