INSERT INTO `lang_definitions` VALUES (200850, 11673, 31, 'برای دسترسی به آن ، روی مورد منوی Recall Board در نوار پیمایش بالا کلیک کنید یا روی دکمه Recall Board در مرکز پیام کلیک کنید');
