INSERT INTO `lang_definitions` VALUES (200853, 11676, 31, 'برای افزودن گزینه های بیشتر به فهرست کشویی ، به بخش مدیریت> لیست ها> مدیریت لیست ها بروید و \"Price Level\" را در کادر کشویی انتخاب کرده و انواع آن را وارد کنید: کارت اعتباری ، وجه نقد و غیره');
