INSERT INTO `lang_definitions` VALUES (200858, 11681, 31, 'برای اینکه هر خط رویه یک ارائه دهنده جداگانه داشته باشد ، باید کادر تأیید \"ارائه دهنده پشتیبانی در مورد مورد در صفحه هزینه\" را در بخش مدیریت> جهانی> صورتحساب علامت بزنید.در صورت عدم بررسی ، ارائه دهنده ارائه در این بخش برای همه ادعاها استفاده می شود');
INSERT INTO `lang_definitions` VALUES (200859, 11682, 31, 'برای مجاز کردن پورتال بیمار برای بیمار ، به داشبورد> دموگرافیک> ویرایش> گزینه ها بروید و گزینه Yes را در کادر کشویی Allow Patient Portal انتخاب کرده و ذخیره کنید.');
INSERT INTO `lang_definitions` VALUES (200860, 11683, 31, 'برای باز کردن خودکار فرم مشخص شدهبرخی از تیم های ورزشی در اینجا از حسابرسی_ فوتبال_صدمه استفاده می کنند.');
INSERT INTO `lang_definitions` VALUES (200861, 11684, 31, 'برای اینکه بتوانید این مسئله را به یک مشکل مرتبط کنید ، روی دکمه کلیک کنید تا صفحه pop-up Issues and Encounters ظاهر شود');
