INSERT INTO `lang_definitions` VALUES (200869, 11692, 31, 'برای ایجاد یک پانل آزمایش دیگر ، این فرایند را تکرار می کنید ، اما با ایجاد یک دستورالعمل روش یا شاخه میوه دار درجه 3 شروع می شود ، به عنوان مثال - پانل هپاتیت حاد در زیر شاخه اصلی یا صفحه زیر گروه بدن یا بیماری (گروه 2)');
INSERT INTO `lang_definitions` VALUES (200870, 11694, 31, 'تاریخ باید دیرتر از From باشد!');
