INSERT INTO `lang_definitions` VALUES (200872, 11696, 31, 'برای حذف هر یا همه کدهای ICD10 انتخاب شده ، دوباره روی کادر Diagnosis Codes کلیک کنید تا پنجره بازشو Select Diagnosis Codes ظاهر شود');
INSERT INTO `lang_definitions` VALUES (200873, 11697, 31, 'برای پیوند دادن ، فقط روی مورد کلیک کنید تا پیوند ایجاد شود ، این موضوع حذف خواهد شد و دیگر برجسته نخواهد شد');
INSERT INTO `lang_definitions` VALUES (200874, 11698, 31, 'به دمس');
INSERT INTO `lang_definitions` VALUES (200875, 11699, 31, 'برای غیرفعال کردن بررسی خودکار پیام به بخش مدیریت> Globals> اتصالات بروید و فاصله بررسی پیام phiMail را روی 0 (صفر) تنظیم کنید');
INSERT INTO `lang_definitions` VALUES (200876, 11700, 31, 'برای غیرفعال کردن گواهینامه های SSL سمت مشتری ، در مورد خطوط موجود در پرونده پیکربندی Apache نظر دهید و تنظیم کنید');
INSERT INTO `lang_definitions` VALUES (200877, 11701, 31, 'برای غیرفعال کردن گواهینامه های SSL سمت سرویس گیرنده ، در مورد خطوط موجود در پرونده پیکربندی Apache نظر دهید و تنظیمات جهانی  \"Enable Client SSL \" را در OpenEMR خاموش کرده و سرور Apache را مجدداً راه اندازی کنید.');
INSERT INTO `lang_definitions` VALUES (200878, 11702, 31, 'برای غیرفعال کردن HTTPS ، خطوط فوق را در پرونده پیکربندی Apache نظر دهید و سرور Apache را مجدداً راه اندازی کنید.');
INSERT INTO `lang_definitions` VALUES (200879, 11703, 31, 'برای نمایش مبلغ حق الزحمه باید در بیمه بیمار تحت ویرایش> جمعیت شناسی وارد شده باشد');
INSERT INTO `lang_definitions` VALUES (200880, 11704, 31, 'برای انجام این کار ، روی علامت + سیاه و سفید در انتهای خط دستور Serid Uric Acid کلیک کنید تا پنجره بازشو Enter Details ظاهر شود');
INSERT INTO `lang_definitions` VALUES (200881, 11705, 31, 'برای ویرایش یک گروه موجود (ARO) بر روی نماد کنار گروه مورد نظر کلیک کنید.با این کار پنجره ویرایش ظاهر می شود.');
INSERT INTO `lang_definitions` VALUES (200882, 11706, 31, 'برای فعال کردن هر نوع اتصال دیگر نیاز به نوشتن کد جدید است');
INSERT INTO `lang_definitions` VALUES (200883, 11707, 31, 'برای فعال کردن گواهینامه های سمت مشتری ssl');
INSERT INTO `lang_definitions` VALUES (200884, 11708, 31, 'برای فعال کردن احراز هویت گواهینامه های SSL سمت مشتری ، HTTPS باید فعال شود.');
INSERT INTO `lang_definitions` VALUES (200885, 11709, 31, 'برای فعال کردن راهنما - به بخش مدیریت> Globals> ویژگی ها> فعال کردن راهنما کمک کنید');
INSERT INTO `lang_definitions` VALUES (200886, 11710, 31, 'برای فعال کردن راهنما - به قسمت نام کاربری در بالا سمت چپ> تنظیمات> ویژگی ها> فعال کردن راهنما کمک کنید');
INSERT INTO `lang_definitions` VALUES (200887, 11711, 31, 'برای فعال کردن راهنما - به نام کاربری در سمت راست بالا> تنظیمات> ویژگی ها> فعال کردن راهنما کمک کنید');
INSERT INTO `lang_definitions` VALUES (200888, 11712, 31, 'برای فعال کردن فقط HTTPS ، تغییرات فوق را انجام داده و سرور Apache را مجدداً راه اندازی کنید.اگر می خواهید گواهی های سمت مشتری را نیز پیکربندی کنید ، لطفاً آنها را در بخش بعدی پیکربندی کنید.');
INSERT INTO `lang_definitions` VALUES (200889, 11713, 31, 'برای فعال کردن پورتال بیمار به بخش مدیریت> پورتال> فعال کردن نسخه 2 پورتال بیمار در داخل سایت ، فعال کردن پورتال بیمار در خارج از سایت یا فعال کردن پورتال CMS بروید');
INSERT INTO `lang_definitions` VALUES (200890, 11715, 31, 'به Enctr');
INSERT INTO `lang_definitions` VALUES (200891, 11716, 31, 'فیلتر کردن بر اساس جنسیت');
INSERT INTO `lang_definitions` VALUES (200892, 11717, 31, 'برای تحقق الزامات استفاده معنادار و کمک به پیگیری استفاده از آن ، می توانید در صورت لزوم در کادر تأیید خلاصه مراقبت از مراقبت و در جعبه تأیید چکیده مراقبت از خدمات الکترونیکی در این زمینه علامت بزنید.');
INSERT INTO `lang_definitions` VALUES (200893, 11718, 31, 'برای حذف کامل \"ذخیره\" ضربه بزنید');
INSERT INTO `lang_definitions` VALUES (200894, 11719, 31, 'برای شروع یکی از دو دکمه رادیویی را انتخاب می کنید.\"جستجوی فاکتور\" یا \"بارگذاری ERA\"');
INSERT INTO `lang_definitions` VALUES (200895, 11720, 31, 'برای کمک به کشف اجزای مختلف صفحه گزارش ، به ویژه اگر می خواهید از آن به عنوان یک کتابچه راهنمای استفاده کنید ، پیشنهاد می شود که اندازه مرورگر را کاهش دهید تا نیمی از نمای مشاهده را پوشش دهد ، با کلیک کردن و کشیدن قسمت پایین ، اندازه پنجره بازشو را تغییر دهیدگوشه سمت راست پنجره بازشونمونه دیگری از مرورگر را باز کنید و اندازه آن را تغییر دهید تا نیمه دیگر قسمت نمایش را پوشش دهد ، برای openEMR وارد شوید');
INSERT INTO `lang_definitions` VALUES (200896, 11721, 31, 'پیشنهاد می شود برای آشنایی شما با اجزای مختلف صفحه داشبورد ، اندازه مرورگر را کاهش دهید تا نیمی از نمای مشاهده را پوشش دهد ، با کلیک کردن و کشیدن گوشه پایین سمت راست پنجره بازشو ، اندازه پنجره بازشو را تغییر دهید.نمونه دیگری از مرورگر را باز کنید و اندازه آن را تغییر دهید تا نیمه دیگر قسمت نمایش را پوشش دهد ، برای openEMR وارد شوید');
INSERT INTO `lang_definitions` VALUES (200897, 11722, 31, 'برای کمک به ساده سازی پیاده سازی ها ، الگوهای معمول مورد استفاده از راهنماهای موجود اجرای CDA هماهنگ شده و در یک راهنمای پیاده سازی منسجم - راهنمای اجرای C-CDA (IG) (2012/2017)');
INSERT INTO `lang_definitions` VALUES (200898, 11723, 31, 'به تاریخچه');
INSERT INTO `lang_definitions` VALUES (200899, 11724, 31, 'برای درج اسناد اسکن شده که بخشی از سوابق بیمار است ، با علامت زدن در کادرهای مربوط ، سوابق مورد نظر را انتخاب کنید');
INSERT INTO `lang_definitions` VALUES (200900, 11725, 31, 'به مسائل');
INSERT INTO `lang_definitions` VALUES (200901, 11726, 31, 'برای پیوند دادن مشکلات به یک برخورد ابتدا مسئله را انتخاب کنید ، به رنگ زرد برجسته خواهد شد ، سپس برای پیوند دادن آنها روی یک یا چند مورد کلیک کنید ، برخوردهای انتخاب شده با رنگ بنفش برجسته می شوند');
INSERT INTO `lang_definitions` VALUES (200902, 11727, 31, 'برای پیوند دادن این رویارویی / مشورت با مسئله موجود ، روی کلیک کنید');
INSERT INTO `lang_definitions` VALUES (200903, 11728, 31, 'برای پیوند دادن این رویارویی / مشورت با مسئله موجود ، روی شماره مورد نظر در بالا کلیک کنید تا برجسته شود و سپس بر روی \"ذخیره\" کلیک کنید.دکمه [Ctrl] را برای انتخاب چند مسئله پایین نگه دارید.');
INSERT INTO `lang_definitions` VALUES (200904, 11729, 31, 'برای پیوند دادن این رویارویی / مشورت با مسئله موجود ، روی شماره مورد نظر در بالا کلیک کنید تا برجسته شود و سپس ذخیره را کلیک کنید');
INSERT INTO `lang_definitions` VALUES (200905, 11730, 31, 'برای ورود مجدد');
INSERT INTO `lang_definitions` VALUES (200906, 11731, 31, 'برای جابجایی گروهها از یک ستون به ستون دیگر ، یک یا چند مورد از ستون مورد نظر را انتخاب کنید که باید آنها را از آن خارج کرده و دکمه مربوطه را با دو شاخر فشار دهید.');
INSERT INTO `lang_definitions` VALUES (200907, 11732, 31, 'برای ادامه کار به یک کلید امنیتی USB ، اتصال وب HTTPS امن و مرورگری که از U2F پشتیبانی می کند ، نیاز دارید');
INSERT INTO `lang_definitions` VALUES (200908, 11733, 31, 'به طور خلاصه ، گروهی به نام شیمی سرم (ردیف 1) ایجاد شد ، یک فرزند مستقیم یا فرزند به نام سرم اوریک اسید (ردیف 2) در زیر آن به عنوان یک دستورالعمل ایجاد شد که دارای یک فرزندان مستقیم یا یک فرزند به نام اسید اوریک سرم بود (ردیف 3) به عنوان یک نتیجه گسسته که مقدار نتیجه را در خود نگه می دارد');
INSERT INTO `lang_definitions` VALUES (200909, 11734, 31, 'برای دریافت اعلان های خطا از سرویس پیام رسانی مستقیم ، باید یک آدرس ایمیل معتبر اعلان برای کاربری که در مدیریت> Globals> اتصالات> کاربر اعلان phiMail نامگذاری شده است');
INSERT INTO `lang_definitions` VALUES (200910, 11735, 31, 'برای ثبت افشای اطلاعات ، لطفا کلیک کنید');
INSERT INTO `lang_definitions` VALUES (200911, 11736, 31, 'برای ثبت نام ، به یک برنامه احراز هویت روی تلفن هوشمند خود نیاز دارید');
INSERT INTO `lang_definitions` VALUES (200912, 11738, 31, 'برای ارسال مجدد پرونده ، پرونده را از ارتباطات حذف کرده و دوباره امتحان کنید.');
INSERT INTO `lang_definitions` VALUES (200913, 11739, 31, 'برای ارسال مجدد پرونده ، پرونده را از ارتباطات حذف کنید ، این صفحه را بارگیری کنید و دوباره امتحان کنید.');
INSERT INTO `lang_definitions` VALUES (200914, 11740, 31, 'برای آشکار کردن فیلترها ، روی نماد چشم کلیک کنید');
INSERT INTO `lang_definitions` VALUES (200915, 11741, 31, 'دویدن');
INSERT INTO `lang_definitions` VALUES (200916, 11743, 31, 'برای دیدن همه ACO های موجود بر روی نماد چشم کلیک کنید.');
INSERT INTO `lang_definitions` VALUES (200917, 11744, 31, 'برای انتخاب یک کد خاص ، آن را در نتایج برگشت یافته شناسایی کنید و برای انتخاب روی آن کلیک کنید');
INSERT INTO `lang_definitions` VALUES (200918, 11745, 31, 'برای انتخاب چندین گروه هنگام کلیک روی کلیدهای \"Shift\" یا \"Ctrl\" نگه دارید.');
INSERT INTO `lang_definitions` VALUES (200919, 11747, 31, 'برای تنظیم دسترسی https با احراز هویت گواهی مشتری ، موارد زیر را انجام دهید');
INSERT INTO `lang_definitions` VALUES (200920, 11748, 31, 'به پوست');
INSERT INTO `lang_definitions` VALUES (200921, 11749, 31, 'به پوست');
INSERT INTO `lang_definitions` VALUES (200922, 11750, 31, 'به طور خلاصه');
INSERT INTO `lang_definitions` VALUES (200923, 11751, 31, 'به این ملاقات؟');
INSERT INTO `lang_definitions` VALUES (200924, 11752, 31, 'برای بارگذاری سند CCR بیمار موجود ، از صفحه خلاصه بیمار-> اسناد استفاده کنید.برای سند CCR بیمار جدید از صفحه نمایش Miscellanous-> New Documents استفاده کنید');
INSERT INTO `lang_definitions` VALUES (200925, 11754, 31, 'برای استفاده از صفحه راهنما به عنوان یک کتابچه راهنمای ، پیشنهاد می شود که اندازه مرورگر را کاهش دهید تا نیمی از نمای نمایش را پوشش دهد ، با کلیک کردن و کشیدن گوشه سمت راست پایین پنجره بازشو ، اندازه پنجره بازشو را تغییر دهید.نمونه دیگری از مرورگر را باز کنید و اندازه آن را تغییر دهید تا نیمه دیگر قسمت نمایش را پوشش دهد ، برای openEMR وارد شوید');
INSERT INTO `lang_definitions` VALUES (200926, 11755, 31, 'برای استفاده از این فایل راهنما به عنوان یک کتابچه راهنمای ، بهتر است اندازه مرورگر خود را تغییر دهید تا نیمی از صفحه را اشغال کند ، نمونه دیگری از مرورگر را باز کنید تا نیمه دیگر صفحه را پر کنید ، برای openEMR وارد شوید و پرونده راهنما را در این مرورگر باز کنید و تغییر اندازه دهیدآن را با کلیک و کشیدن گوشه پایین سمت راست به طوری که کل نیمه صفحه را اشغال کند');
INSERT INTO `lang_definitions` VALUES (200927, 11756, 31, 'پیشنهاد می شود برای استفاده از این پرونده راهنما به عنوان راهنمای دستورالعمل ، اندازه مرورگر را کاهش دهید تا نیمی از نمای مشاهده را پوشش دهد ، با کلیک کردن و کشیدن گوشه پایین سمت راست پنجره بازشو ، اندازه پنجره بازشو را تغییر دهید.نمونه دیگری از مرورگر را باز کنید و اندازه آن را تغییر دهید تا نیمه دیگر قسمت نمایش را پوشش دهد ، برای openEMR وارد شوید');
