INSERT INTO `lang_definitions` VALUES (201317, 12210, 31, 'با جستجوی موفقیت آمیز ، لیستی از فاکتورها به شما ارائه می شود.شما می توانید بر روی یکی از شماره های فاکتور کلیک کنید تا پنجره دوم ، صفحه ورود اطلاعات برای ارسال دستی باز شود.همچنین اگر می خواهید یادداشتی را وارد کنید که کارکنان مطب جلو هنگام بررسی بیمار آن را مشاهده می کنند ، می توانید بر روی نام بیمار کلیک کنید و می توانید فاکتورها را انتخاب کنید تا در اظهارات بیمار ظاهر شود و این اظهارات را چاپ کنید.');
INSERT INTO `lang_definitions` VALUES (201318, 12211, 31, 'با کلیک بر روی شماره فاکتور ، \"پنجره ارسال دستی\" ظاهر می شود.در اینجا می توانید تاریخ سررسید و یادداشت های فاکتور را تغییر دهید ، طرفی را که برای آن ارسال می کنید انتخاب کنید و بیمه هایی را که همه بازپرداخت کنندگان انتظار برای آن دریافت کرده اند انتخاب کنید.از همه مهمتر ، برای هر کد صورتحساب که مبلغی برای آن شارژ شده است ، می توانید اطلاعات پرداخت و تنظیمات را وارد کنید.');
INSERT INTO `lang_definitions` VALUES (201319, 12212, 31, 'با کلیک بر روی شماره فاکتور ، \"پنجره ارسال دستی\" ظاهر می شود.در اینجا می توانید تاریخ سررسید و یادداشت های فاکتور را تغییر دهید ، طرفی را که برای آن ارسال می کنید انتخاب کنید و بیمه هایی را که همه پرداخت های مورد انتظار برای آنها دریافت شده است انتخاب کنید.از همه مهمتر ، برای هر کد صورتحساب که مبلغی برای آن شارژ شده است ، می توانید اطلاعات پرداخت و تنظیمات را وارد کنید.');
INSERT INTO `lang_definitions` VALUES (201320, 12213, 31, 'با ورود به صفحه دو دکمه در زیر نوار پیمایش قابل مشاهده است');
INSERT INTO `lang_definitions` VALUES (201321, 12214, 31, 'با ورود به سیستم openEMR ، یک نماد پاکت کوچک در سمت راست بالا قابل مشاهده است.تعداد پیام های معلق و یادآوری های تاریخ را نشان می دهد');
INSERT INTO `lang_definitions` VALUES (201322, 12215, 31, 'با رسیدن به یک نقطه از پیش تعیین شده ، یا یک تاریخ یا یک مقدار ، این قانون باعث ایجاد یک یا چند رویداد می شود');
INSERT INTO `lang_definitions` VALUES (201323, 12216, 31, 'پس از جستجو لیست فاکتورها به شما ارائه میشود. شما میتوانید روی یکی از شماره فاکتورها کلیک کنید تا صفحه دومی‌ برای وارد کردن اطلاعات و ارسال دستی باز شود. همچنین برای وارد کردن یاد داشت می توانید روی نام یک بیمار کلیک کنید تا کارکنان دفتر جلو در زمان پذیرش بیمار آن را ببینند. همچنین می توانید فاکتورهایی‌ را انتخاب کنید تا در صورت حسابهای بیماران قید شده و آن صورت حسابها را چاپ کنید.');
INSERT INTO `lang_definitions` VALUES (201324, 12217, 31, 'با انتخاب یک لیست برای ویرایش صفحه ویرایش با مقادیر لیست نمایش داده می شود');
