INSERT INTO `lang_definitions` VALUES (201472, 12378, 31, 'با استفاده از احراز هویت دو عاملی');
INSERT INTO `lang_definitions` VALUES (201473, 12379, 31, 'استفاده از یک درخت میوه به عنوان آسان تر تجسم قیاس ، مفهوم این سلسله مراتب را بهتر توضیح می دهد ، تنه درخت گروه (شیمی سرم) است ، شاخه میوه دهنده ترتیب واقعی است ، ترتیب روش (اسید اوریک سرم) ومیوه نتیجه است ، نتیجه گسسته ، همچنین (سرم اوریک اسید) نامیده می شود که مقدار نتیجه برگشتی را در خود نگه می دارد.همانطور که میوه در تنه اصلی حمل نمی شود ، شما نباید یک نتیجه گسسته را به عنوان یک نسل مستقیم یا فرزند یک گروه برتر قرار دهید.به همین ترتیب شاخه میوه دار (Order Procedure) را نمی توان به عنوان یک نسل مستقیم یا فرزند میوه قرار داد (نتیجه گسسته)');
INSERT INTO `lang_definitions` VALUES (201474, 12380, 31, 'استفاده از فناوری برای بهبود بهره وری');
INSERT INTO `lang_definitions` VALUES (201475, 12381, 31, 'با استفاده از جزئیات وارد شده به سیستم ، OpenEMR پیام های معتبر HL7 v2.3 را در 3 قالب تولید می کند ، یک فایل متنی که به طور خودکار در پوشه بارگیری مرورگر شما بارگیری می شود ، یک پیام HL7 که در یک پوشه یا فهرست بر روی سرور در حال اجرا نوشته می شودopenEMR یا از SFTP - Secure File Transfer Protocol استفاده کنید ، که یک پروتکل شبکه است که دسترسی فایل ، انتقال فایل و مدیریت پرونده را از طریق اتصال ایمن فراهم می کند و این پیام را به آزمایشگاه منتقل می کند.');
INSERT INTO `lang_definitions` VALUES (201476, 12382, 31, 'با استفاده از کاربرگ کاربر');
INSERT INTO `lang_definitions` VALUES (201477, 12383, 31, 'استفاده از عناوین اصلی در برگه آزمایشگاه به شروع این روند کمک می کند - پانل های ارگان / بیماری ، خون شناسی ، آزمایش های فردی ، میکروب شناسی ، سایر موارد');
INSERT INTO `lang_definitions` VALUES (201478, 12384, 31, 'با استفاده از این تشبیه درخت میوه می توانیم درک بهتری از مراحل مورد نیاز برای ایجاد سفارش برای یک مجموعه آزمایش داشته باشیم');
