INSERT INTO `lang_definitions` VALUES (201683, 12612, 31, 'هشدار ، بیمار کدهای مبهمی در لیست مشکلات دارد!');
INSERT INTO `lang_definitions` VALUES (201684, 12613, 31, 'هشدار: امروز قبلا یک ملاقات برای این بیمار ساخته شد!');
INSERT INTO `lang_definitions` VALUES (201685, 12614, 31, 'هشدار: پیشگیری از بارداری برای بیمار زیر 10 سال یا بالاتر از 50 سال.');
INSERT INTO `lang_definitions` VALUES (201686, 12616, 31, 'هشدار: روش پیشگیری از بارداری با بیمار مرد سازگار نیست.');
INSERT INTO `lang_definitions` VALUES (201687, 12617, 31, 'هشدار: اگر از نسخه اسپانیایی 2012-10-31 استفاده می کنید ، توجه داشته باشید که باید یک بار آن را از حالت فشرده خارج کنید تا آن را در قسمت مشارکت / خرابکاری قرار دهید (این به این دلیل است که پرونده منتشر شده \"\" دو برابر زیپ شده بود \").');
INSERT INTO `lang_definitions` VALUES (201688, 12619, 31, 'هشدار: خطای پیمایش.لطفاً این صفحه را تازه کنید');
INSERT INTO `lang_definitions` VALUES (201689, 12620, 31, 'هشدار: شناسه بیمار منحصر به فرد نیست!');
INSERT INTO `lang_definitions` VALUES (201690, 12622, 31, 'هشدار: هیچ محصولی مطابق با خدمات پیشگیری از بارداری وجود ندارد.');
INSERT INTO `lang_definitions` VALUES (201691, 12623, 31, 'هشدار: هیچ خدمتی با محصول پیشگیری از بارداری مطابقت ندارد.');
INSERT INTO `lang_definitions` VALUES (201692, 12624, 31, 'هشدار: این اطلاعات پیکربندی را با داده های فایل بارگذاری شده بازنویسی می کند!');
