INSERT INTO `lang_definitions` VALUES (201699, 12631, 31, 'ما از پرداخت سریع مانده های سررسید قدردانی می کنیم.');
INSERT INTO `lang_definitions` VALUES (201700, 12632, 31, 'ما در حال ساخت آزمایشی هستیم که می توان آن را سفارش داد به نام اسید اوریک سرم');
INSERT INTO `lang_definitions` VALUES (201701, 12633, 31, 'متأسفیم که با حساب خود مشکلی دارید.');
INSERT INTO `lang_definitions` VALUES (201702, 12634, 31, 'ما بیمار بالا را برای ارزیابی و درمان در کلینیک روانپزشکی سرپایی خود دیده ایم.با تشکر از شما برای این مراجعه');
INSERT INTO `lang_definitions` VALUES (201703, 12635, 31, 'در اتصال EHR شما به سرورهای MedEx با مشکلاتی روبرو شدیم');
INSERT INTO `lang_definitions` VALUES (201704, 12636, 31, 'ما درخواست تنظیم مجدد اعتبارنامه را دریافت کردیم.پیوند برای تنظیم مجدد اعتبارنامه شما در زیر است.');
INSERT INTO `lang_definitions` VALUES (201705, 12639, 31, 'ما قادر به ایجاد یک حساب کاربری نیستیم.');
INSERT INTO `lang_definitions` VALUES (201706, 12640, 31, 'ما پانل الکترولیت را از صندوق اصلی یا گروه (شیمی سرم) پایه گذاری خواهیم کرد');
INSERT INTO `lang_definitions` VALUES (201707, 12641, 31, 'ما برای سه آزمایش سفارش گلوکز خون ، TSH و ویتامین D ایجاد می کنیم و آن را در یک گروه سفارشی به نام Well Woman Tests گروه بندی می کنیم و مکانی را برای دستیابی به نتایج برگشتی ایجاد می کنیم');
INSERT INTO `lang_definitions` VALUES (201708, 12642, 31, 'ما مراحل تنظیم سفارش برای یک آزمایش خون را دنبال خواهیم کرد - اسید اوریک سرم');
INSERT INTO `lang_definitions` VALUES (201709, 12643, 31, 'اکنون ما سفارش یا Order Procedure را ایجاد می کنیم ، به نام صفحه الکترولیت که می تواند به عنوان شاخه میوه دار در درخت میوه فرضی ما تجسم یابد.');
INSERT INTO `lang_definitions` VALUES (201710, 12644, 31, 'ما سفارش صفحه پنل الکترولیت را که متشکل از سدیم سدیم ، پتاسیم ، کلرید و دی اکسید کربن است تنظیم خواهیم کرد.');
INSERT INTO `lang_definitions` VALUES (201711, 12645, 31, 'ما برای شروع یک دستور آزمایشی آزمایشگاهی و توانایی ضبط دستی نتیجه برگشتی ، با ابتدایی ترین واحد ماژول سفارشات رویه شروع خواهیم کرد.');
INSERT INTO `lang_definitions` VALUES (201712, 12646, 31, 'برای نگهداری مقادیر نتیجه برگشتی ، از یک نتیجه گسسته برای هر آزمون استفاده خواهیم کرد');
INSERT INTO `lang_definitions` VALUES (201713, 12647, 31, 'ما از این شاخه برای نگهداری همه 9 پانل استفاده خواهیم کرد ، در اینجا ما فقط سفارش نمایش دهنده یک پانل ، پانل الکترولیت را ایجاد خواهیم کرد.');
