INSERT INTO `lang_definitions` VALUES (201754, 12693, 31, 'چه چیزی سفارش را تشکیل می دهد و فرمت الکترونیکی آن چیست ، چگونه ارسال می شود ، چگونه نتیجه دریافت می شود ، اگر سیستم فقط نتیجه می گیرد یا سفارش می فرستد و نتیجه می گیرد ، به چه آزمایشگاه هایی متصل می شوید و چه مواردی باید در این کشور اتفاق بیفتدسرانجام ، اینکه شخص ثالثی در این معامله دخیل باشد یا خیر');
INSERT INTO `lang_definitions` VALUES (201755, 12694, 31, 'چه چیزی باید شمارش شود؟');
INSERT INTO `lang_definitions` VALUES (201756, 12695, 31, 'چه نوع مرتب سازی در لیست های رها شده وجود دارد.');
INSERT INTO `lang_definitions` VALUES (201757, 12696, 31, 'خس خس:');
INSERT INTO `lang_definitions` VALUES (201758, 12697, 31, 'خس خس سینه');
INSERT INTO `lang_definitions` VALUES (201759, 12698, 31, 'خس خس سینه:');
INSERT INTO `lang_definitions` VALUES (201760, 12699, 31, 'هنگامی که کاربر جدید ایجاد می شود ، کنترل دسترسی توسط سرپرست یا کاربری با امتیازات مشابه با انتخاب گروههایی (ARO) که کاربر می تواند به آنها تعلق گیرد ، اعطا می شود.');
INSERT INTO `lang_definitions` VALUES (201761, 12700, 31, 'چه موقع و چند بار؟');
INSERT INTO `lang_definitions` VALUES (201762, 12701, 31, 'هنگامی که بررسی می شود ، اطلاعات جمعیتی در پنجره جدید از صفحه جریان بیمار باز می شود.');
INSERT INTO `lang_definitions` VALUES (201763, 12702, 31, 'هنگامی که بررسی می شود ، آخرین کارکنان برای به روزرسانی صفحه در صفحه جریان بیمار نشان داده می شوند.');
INSERT INTO `lang_definitions` VALUES (201764, 12703, 31, 'هنگام بررسی ، پیام ها برای بیماران با انتخاب دموگرافیک بیمار پردازش می شوند: \"اعلامیه Hipaa دریافت شد\" روی \"غیر واگذار شده\" یا \"بله\" تنظیم شده است.در صورت عدم انتخاب ، برای پردازش یادآوری بیمار باید \"بله\" باشد.برای بیماران مبتلا به Choice = \"نه\" ، یادآوری ها باید به صورت دستی پردازش شوند.');
INSERT INTO `lang_definitions` VALUES (201765, 12704, 31, 'وقتی بررسی شد ، شماره برخورد بیمار در صفحه جریان بیمار نشان داده می شود.');
INSERT INTO `lang_definitions` VALUES (201766, 12705, 31, 'هنگام بررسی ، شناسه بیمار در صفحه جریان بیمار نشان داده می شود.');
INSERT INTO `lang_definitions` VALUES (201767, 12706, 31, 'هنگامی که بررسی شد ، مراجعه به دلیل در صفحه جریان بیمار نشان داده می شود.');
INSERT INTO `lang_definitions` VALUES (201768, 12707, 31, 'هنگام برخورد با اطلاعات بهداشتی محافظت شده (PHI) و شناسایی شخصی اطلاعات (PII) مهم است که فقط به کاربران مجاز اجازه دسترسی به داده ها را بدهید');
INSERT INTO `lang_definitions` VALUES (201769, 12708, 31, 'پس از اتمام ، روی گزینه ارسال (زیر) کلیک کنید تا گزینه های شما اعمال شود.');
INSERT INTO `lang_definitions` VALUES (201770, 12709, 31, 'وقتی چنین سفارشی انجام می شود ، نتایج برگشتی حاوی مقادیر مربوط به تمام اجزای CBC ، صفحه متابولیک جامع و TSH است.');
INSERT INTO `lang_definitions` VALUES (201771, 12710, 31, 'هنگامی که گزارش تولید شده در یک تب جداگانه نمایش داده می شود ، گزینه ای وجود دارد که به شما امکان می دهد نسخه قابل چاپ قابل چاپ را مشاهده کنید');
INSERT INTO `lang_definitions` VALUES (201772, 12711, 31, 'هنگامی که کلید برای اولین بار ثبت می شود ، یک عدد تصادفی تولید می کند که به آن nonce می گویند');
INSERT INTO `lang_definitions` VALUES (201773, 12712, 31, 'هنگامی که کاربر در ابتدا از این صفحه بازدید می کند ، پیام زیر قابل مشاهده است');
INSERT INTO `lang_definitions` VALUES (201774, 12715, 31, 'هنگام سفارش می توانید تست های Well Woman Tests را در فهرست موارد دلخواه جستجو کرده و آن را انتخاب کنید تا به صورت خودکار با یک کلیک گلوکز خون ، TSH و ویتامین D را سفارش دهید');
INSERT INTO `lang_definitions` VALUES (201775, 12716, 31, 'از کجا می توان اسناد کاغذی یا اسکن شده مرتبط را پیدا کرد؟');
INSERT INTO `lang_definitions` VALUES (201776, 12717, 31, 'از کجا روی بدن شما اتفاق می افتد؟');
INSERT INTO `lang_definitions` VALUES (201777, 12718, 31, 'چه بیمه شده باشد');
INSERT INTO `lang_definitions` VALUES (201778, 12719, 31, 'روزهای آخر هفته شما کدام روزها هستند؟');
INSERT INTO `lang_definitions` VALUES (201779, 12720, 31, 'کدام یادداشت ها باید در صفحه صورتحساب نمایش داده شوند');
INSERT INTO `lang_definitions` VALUES (201780, 12721, 31, 'هنگام ارسال یک یادآوری تاریخ دار ، پیام قدیمی نمایش داده می شود ، می توان آن را بازنویسی کرد');
