INSERT INTO `lang_definitions` VALUES (203008, 1782, 32, 'テキストフ​​ァイルにカテゴリ、サブカテゴリ、アイテム、コンテンツデータをエクスポートする「輸出」をクリックしてください。 XMLファイルには、このファイルの任意の類似点とは一切関係ありません。開始タグと終了タグが同じライン上にある必要があり、彼らはスペースなしで小文字する必要があります。インポートするには、ファイルを参照し、「インポート」をクリックします。データは完全に異なっている場合、それはあなたの既存のデータとマージします。類似の項目名がある場合は、古いものが保持され、新しいものが最後に追加で保存。');
