INSERT INTO `lang_definitions` VALUES (209459, 1782, 34, 'एक मजकूर फाइल आपल्या वर्ग, उपश्रेणी, आयटम, सामग्री डेटा निर्यात करण्याची \'निर्यात\' क्लिक करा. XML फाइल या फाइल कोणत्याही साम्य पूर्णपणे योगायोग आहे. उघडणे आणि बंद टॅग त्याच ओळीत असणे आवश्यक आहे, ते नाही मोकळी जागा सह लोअरकेस करणे आवश्यक आहे. आयात करण्यासाठी, फाईल ब्राउझ करा आणि \'आयात\' वर क्लिक करा. डेटा पूर्णपणे भिन्न आहे, तर आपल्या विद्यमान डेटा विलीन होईल. समान आयटम नावे आहेत, तर, जुन्या ठेवायला आणि एक नंबर सेव्ह नवीन शेवटी जोडली जाईल.');
