INSERT INTO `lang_definitions` VALUES (211206, 5162, 34, 'तुम्ही ePrescription ई-RX भूमिका बदलू असेल, तर ते ePrescription कार्यपद्धत प्रभाव पडू शकतो. आपण कोणत्याही अडचण असेल तर, आपल्या ePrescription विक्रेता संपर्क साधा.');
INSERT INTO `lang_definitions` VALUES (211207, 5172, 34, 'आपण एक सामना निवडा नसेल तर रुग्णाला निर्माण होईल.');
INSERT INTO `lang_definitions` VALUES (211208, 5182, 34, 'आपण इलेक्ट्रॉनिक व्यवहार अपलोड करण्यासाठी निवडलेली असेल, तर नंतर शोध विंडो X12 फाइल पासून जुळणारे पावत्या स्वतः redisplays. (खाली वर्णन केल्याप्रमाणे) आपण पैसे पाठवण्याच्या माहिती लागू करण्यापूर्वी कोणत्याही सुधारणा करण्यासाठी इच्छित असल्यास आपण या चलन संख्या कोणत्याही क्लिक करू शकता. बदल लागू करण्यासाठी, पृष्ठाच्या तळाशी प्रक्रिया ईआरए फाइल या बटणावर क्लिक करा. हे एक सविस्तर अहवाल एक नवीन विंडो निर्मिती होईल.');
INSERT INTO `lang_definitions` VALUES (211209, 5185, 34, 'आपण शोध पृष्ठामधील पे तारीख प्रवेश केला आहे तर, हे अन्यथा X12 फाइल घेतले जातात की पैसे आणि ऍडजस्ट पोस्टिंग तारीख पुन्हा लिहीले जातील. आपण इन्शुरन्स कंपनीला  \'चे प्रक्रिया तारीख ऐवजी आपल्या पोस्टिंग तारीख वापर अहवाल आपल्या पावत्या इच्छित असल्यास हा उद्देशांसाठी अहवाल उपयुक्त असू शकते. हे देखील दुय्यम दावे मध्ये ठेवले आहेत की आधी पैसे आणि ऍडजस्ट तारखा परिणाम होईल हे लक्षात ठेवा.');
INSERT INTO `lang_definitions` VALUES (211210, 5199, 34, 'आपण डेटा प्रकार बदलू किंवा पंक्ती किंवा स्तंभ जोडू इच्छित असल्यास');
