INSERT INTO `lang_definitions` VALUES (214854, 12211, 34, 'एक चलन संख्या \"मॅन्युअल पोस्टिंग विंडो\" क्लिक यावर दिसते. येथे आपण, बीजक देय तारीख आणि नोट्स बदलू तुम्ही पोस्ट ज्यांच्याकडून पक्ष निवडा, आणि सर्व अपेक्षा paymants प्राप्त केले आहेत, जे इन्शुरन्सचे निवडू शकता. प्रत्येक बिलिंग कोड जे एक रक्कम आकारण्यात आला सर्वात महत्त्वाचे म्हणजे, आपण पेमेंट आणि समायोजन माहिती दाखल करू शकता.');
INSERT INTO `lang_definitions` VALUES (214855, 12216, 34, 'शोध केल्यानंतर आपण पावत्या एक यादी दिली जाते. आपण मॅन्युअल पोस्टिंग डेटा एंट्री पृष्ठ आहे जे एक दुसरा विंडो उघडण्यासाठी बीजक क्रमांक एक वर क्लिक करू शकता. जेव्हा तुम्ही सहनशील धनादेश एकही कार्यालय कर्मचारी दिसेल की एक लक्षात ठेवा प्रविष्ट करू इच्छित असल्यास आपण एक रुग्ण नावावर क्लिक करा शकते, व तुम्ही रुग्णाला स्टेटमेन्ट वर दिसतात आणि त्या स्टेटमेन्ट मुद्रित करण्यासाठी पावत्या निवडू शकता.');
